/* CodeBee 前端（无依赖；状态走 SSE 实时推送，断线自动降级轮询） */
"use strict";

// 桌宠通过窗口标题里的端口识别并复用当前 CodeBee 实例。
function codebeeDocumentTitle(lang) {
  const brand = lang === "en" ? "CodeBee · Multi-agent Orchestrator" : "CodeBee · 多智能体编排台";
  const port = location.port || (location.protocol === "https:" ? "443" : "80");
  return brand + " [" + port + "]";
}
document.title = codebeeDocumentTitle((localStorage.getItem("orch.lang") || "zh").toLowerCase());

const $ = (id) => document.getElementById(id);
const S = { state: null, catalog: null, catSig: "", providers: null, bindings: null, modelsSig: "", bindSig: "", tab: "tasks", mainPage: "", /* 主栏正显示的全局页（"" = 新建任务表单）；左栏是任务树还是设置导航看 body.settings-mode */ detailRunId: null, forceStartRunId: null, pollTimer: null, showArchived: false, /* 会话内开关：每次加载默认隐藏已归档、图标不选中（不持久化，见 btn-side-arch） */ selProvs: {}, selModels: {}, selRuns: {}, provStatus: "enabled", mlistStatus: "enabled", /* 供应商/模型列表状态过滤：默认只看启用，停用的点对应 chip 才现身 */ bindSel: {}, catalogChecking: false, updateCheckAt: 0, control: null, sseLive: false, es: null, flows: null, experts: null, orch: null, skills: null, orchSig: "", settings: null, sessionAgents: new Set(), atts: [], cmpPlugins: [], capabilities: null, gitInfo: null, gitWb: null, gitWbKey: "", gitWbAt: 0, gitWbBusy: false, creatingTask: false, templateBudget: null, inspKey: null, inspData: null, inspSig: "", inspAt: 0, inspTab: "git", inspAutoSig: "", rdTab: null, rdTabSig: "", rdTabPin: false, _rdCtx: {}, taskContracts: {}, lastPrefs: null, prefsApplied: false, sideUsage: null, sideUsageAt: 0, ovUsage: null, ovDays: undefined, coverPrompt: null };

// 第二批运营能力的轻量 UI 缓存；后端接口不存在时各面板仍保持可用。
const UI_FEATURES = { reviewPolicy: null, templates: null, analytics: null, analyticsDays: 1, interventions: [], cliDiscovery: null };

/* 工作/开发/聊天是界面场景偏好，共用任务和引擎，不改变现有任务的执行参数。 */
const WORKSPACE_MODE_KEY = "orch.workspace-mode.v1";
const WORKSPACE_MODES = {
  work: { label: t("工作"), defaultType: "direct", quick: ["direct", "doc", "research", "translation"],
    greeting: t("把想法变成成果"), hint: t("写作、调研、文档与翻译，从这里开始。") },
  develop: { label: t("开发"), defaultType: "code", quick: ["code", "defect_retro", "tech_proposal", "direct"],
    greeting: t("今天想构建什么？"), hint: t("编写代码、调试问题、运行测试与评审变更。") },
  chat: { label: t("聊天"), defaultType: "direct", quick: ["direct"],
    greeting: t("想聊点什么？"), hint: t("直接问答、头脑风暴与日常对话，从这里开始。") },
};
let workspaceChoice = { mode: "chat", types: {} };
let workspaceHasChoice = false;
try {
  const saved = JSON.parse(localStorage.getItem(WORKSPACE_MODE_KEY) || "null");
  if (saved && Object.prototype.hasOwnProperty.call(WORKSPACE_MODES, saved.mode)) {
    workspaceChoice.mode = saved.mode;
    workspaceHasChoice = true;
    for (const mode of ["work", "develop", "chat"]) {
      if (saved.types && typeof saved.types[mode] === "string") workspaceChoice.types[mode] = saved.types[mode];
    }
  }
} catch (e) { /* 不可用或损坏的本机偏好回落聊天模式 */ }

/* ---------------------------------------------------------- 工作台（预览与发布） */
const WB_STORAGE_KEY = "orch.workbench.v1";
const WB_TASK_STORAGE_KEY = "orch.workbench.task.v1";
let wbState = wbLoadState();
let wbTaskId = "";
let wbView = "preview";
let wbWorkspacePlatform = "";
let wbWorkspaceKey = "";
let wbWorkspacePoll = 0;
let wbPvSeq = 0;         // 预览挂载过期闸门：任何一次重画都让在飞的挂载响应作废
let wbPvMounted = "";    // 已挂进 iframe 的 run：同 run 重画只亮回 iframe，不整页 reload
let wbNpSeq = 0;         // 小说纸面过期闸门：重画/换章都让在飞的章节响应作废

try { wbTaskId = localStorage.getItem(WB_TASK_STORAGE_KEY) || ""; } catch (e) { wbTaskId = ""; }

function wbLoadState() {
  try {
    const raw = JSON.parse(localStorage.getItem(WB_STORAGE_KEY) || "{}");
    return {
      view: raw.view === "console" ? "console" : "preview",
      updatedAt: Number(raw.updatedAt) || 0,
    };
  } catch (e) {
    return { view: "preview", updatedAt: 0 };
  }
}

function wbSaveState() {
  try {
    wbState.updatedAt = Math.max(Date.now(), Number(wbState.updatedAt || 0) + 1);
    localStorage.setItem(WB_STORAGE_KEY, JSON.stringify(wbState));
  } catch (e) { /* private browsing: state remains in memory */ }
}

function wbTaskList() {
  return ((S.state || {}).tasks || []).filter((task) => task && task.id);
}

function wbTaskForId(id) {
  return wbTaskList().find((t) => t.id === id) || null;
}

function wbLatestRun(task) {
  if (!task || !task.id) return null;
  const latest = (S.state || {}).task_latest || {};
  return latest[task.id] || null;
}

function wbCurrentTask() {
  return wbTaskForId(wbTaskId);
}

function wbSetTask(id) {
  wbTaskId = id || "";
  try { localStorage.setItem(WB_TASK_STORAGE_KEY, wbTaskId); } catch (e) {}
  wbDraw();
  wbLoadPublishState(wbCurrentTask());
}

function wbSetView(view) {
  wbView = view === "console" ? "console" : "preview";
  wbState.view = wbView;
  wbSaveState();
  wbDraw();
}

/* 工作台「控制台」视图：人类可读的运行事实摘要 + 可折叠原始 JSON。
 * 此前直接 JSON.stringify(run) 整坨倒出，取消/无步骤的 run 只剩一屏裸数据。 */
function wbConsoleHtml(run) {
  const row = (k, v) => (v !== "" && v != null ? '<div class="wb-kv"><span>' + esc(k) + "</span><b>" + v + "</b></div>" : "");
  const mins = (run.started_at && run.ended_at)
    ? Math.max(1, Math.round((new Date(String(run.ended_at).replace(" ", "T"))
      - new Date(String(run.started_at).replace(" ", "T"))) / 60000))
    : 0;
  let html = row(t("状态"), esc(runStatusText(run)))
    + row(t("原因"), run.error ? esc(run.error) : (run.summary ? esc(run.summary) : ""))
    + row(t("创建时间"), esc(run.created_at || ""))
    + row(t("开始"), run.started_at ? esc(run.started_at) : "—")
    + row(t("结束"), run.ended_at ? esc(run.ended_at) : "—")
    + (mins ? row(t("耗时"), mins + t(" 分钟")) : "")
    + (Number(run.auto_resumes) > 0 ? row(t("自动续跑"), esc(String(run.auto_resumes)) + t(" 次")) : "")
    + (Number(run.tokens) > 0 ? row(t("Token"), esc(fmtTok(run.tokens))) : "")
    + (Number(run.cost_usd) > 0 ? row(t("费用"), esc(fmtUsd(run.cost_usd))) : "");
  if (!html) html = '<div class="wb-kv"><span></span><b>' + esc(t("暂无运行信息")) + "</b></div>";
  html += '<details class="wb-raw"><summary>' + esc(t("原始数据")) + "</summary><pre>"
    + esc(JSON.stringify(run, null, 2)) + "</pre></details>";
  return html;
}

function wbDraw() {
  wbPvSeq++;
  wbNpSeq++;
  const task = wbCurrentTask();
  const run = wbLatestRun(task);
  
  // Task selector
  const select = $("wb-task-select");
  if (select) {
    const tasks = wbTaskList();
    select.innerHTML = '<option value="">' + t("选择任务…") + "</option>" +
      tasks.map((t) => '<option value="' + esc(t.id) + '"' + (t.id === wbTaskId ? " selected" : "") + ">" + esc(t.title || t.id) + "</option>").join("");
  }
  
  // Title and subtitle
  const title = $("wb-title");
  if (title) title.textContent = task ? (task.title || task.id) : t("预览与发布");
  const sub = $("wb-sub");
  if (sub) sub.textContent = task ? (task.type || "") : t("任务成品预览、验证与平台发布");
  
  // View switch
  document.querySelectorAll("[data-wb-view]").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.wbView === wbView);
    btn.setAttribute("aria-selected", btn.dataset.wbView === wbView ? "true" : "false");
  });
  
  // Stage content
  const empty = $("wb-empty");
  const paper = $("wb-paper");
  const frame = $("wb-frame");
  const console_ = $("wb-console");
  const cdpScreen = $("wb-cdp-screen");
  
  if (empty) empty.classList.add("hidden");
  if (paper) paper.classList.add("hidden");
  // src 不在这里摘：同 run 重画由 wbMountWebPreview 原样亮回，避免 iframe 整页 reload；
  // 真要清（换 run/切视图/无任务）由 wbPreviewReset 统一收尸
  if (frame) frame.classList.add("hidden");
  if (console_) console_.classList.add("hidden");
  if (cdpScreen) { cdpScreen.classList.add("hidden"); cdpScreen.removeAttribute("src"); }
  
  const stageLabel = $("wb-stage-label");
  const stageNote = $("wb-stage-note");
  const stageActions = $("wb-stage-actions");
  const footHint = $("wb-foot-hint");
  const footMeta = $("wb-foot-meta");
  
  if (!task) {
    wbPreviewReset();
    if (empty) empty.classList.remove("hidden");
    if (stageLabel) stageLabel.querySelector("span[data-i18n]").textContent = t("预览");
    if (stageNote) stageNote.textContent = "";
    if (stageActions) stageActions.innerHTML = "";
    if (footHint) footHint.textContent = "";
    if (footMeta) footMeta.textContent = "";
  } else if (wbView === "console") {
    wbPreviewReset();
    if (console_) {
      console_.classList.remove("hidden");
      console_.innerHTML = run ? wbConsoleHtml(run) : esc(t("暂无运行日志"));
    }
    if (stageLabel) stageLabel.querySelector("span[data-i18n]").textContent = t("控制台");
    if (stageNote) stageNote.textContent = run ? run.id : "";
    if (stageActions) stageActions.innerHTML = "";
    if (footHint) footHint.textContent = t("运行日志与输出");
    if (footMeta) footMeta.textContent = run ? (run.verdict || "") : "";
  } else {
    // Preview mode
    const type = (task.type || "").toLowerCase();
    if (type === "serial_novel" || type === "novel") {
      wbPreviewReset();
      // Novel paper preview
      if (paper) paper.classList.remove("hidden");
      if (stageLabel) stageLabel.querySelector("span[data-i18n]").textContent = t("小说预览");
      if (stageNote) stageNote.textContent = task.serial ? (task.serial.chapters + t(" 章")) : "";
      if (stageActions) stageActions.innerHTML = "";
      if (footHint) footHint.textContent = t("连载小说成品预览");
      if (footMeta) footMeta.textContent = "";
      wbMountNovelPaper(run);
    } else {
      // 网页成品预览：先问后端要入口与挂载根（/preview/<run>/<令牌>/ 的只读
      // 静态挂载），有才挂 iframe；没有（小说/普通任务的常态）给空态说明——
      // 不能把 /api/runs/<id>/preview 这个 JSON 接口当页面开，那是一行 no_html
      if (stageLabel) stageLabel.querySelector("span[data-i18n]").textContent = t("预览");
      if (stageNote) stageNote.textContent = run ? run.id : "";
      if (footMeta) footMeta.textContent = run ? (run.workdir || "") : "";
      wbMountWebPreview(run);
    }
  }
  
  // Task context card
  const card = $("wb-task-card");
  if (card) {
    if (!task) {
      card.innerHTML = '<div class="wb-task-empty">' + t("选择一个任务开始工作") + "</div>";
    } else {
      const status = task.status || "";
      const statusClass = status === "running" ? "ok" : status === "failed" ? "bad" : "";
      card.innerHTML = '<div class="wb-task-title">' + esc(task.title || task.id) + "</div>" +
        '<div class="wb-task-meta">' +
        '<span class="wb-task-status ' + statusClass + '">' + esc(status) + "</span>" +
        (task.type ? "<span>" + esc(task.type) + "</span>" : "") +
        (task.serial ? "<span>" + (task.serial.chapters || 0) + t(" 章") + "</span>" : "") +
        "</div>" +
        (task.goal ? '<div class="wb-task-goal">' +
          esc((task.goal || "").slice(0, 160)) +
          ((task.goal || "").length > 160 ? "…" : "") + "</div>" : "");
    }
  }
  
  // Action buttons
  const actions = $("wb-aside-actions");
  if (actions) {
    if (!task) {
      actions.innerHTML = "";
    } else {
      actions.innerHTML = '<button class="primary small" onclick="wbOpenPreview()"><svg class="ico" aria-hidden="true"><use href="#i-clapper"></use></svg>' + t("预览成品") + "</button>" +
        '<button class="ghost small" onclick="wbOpenDetail()"><svg class="ico" aria-hidden="true"><use href="#i-file-search"></use></svg>' + t("查看详情") + "</button>" +
        '<button class="ghost small" onclick="wbRetryTask()"><svg class="ico" aria-hidden="true"><use href="#i-refresh"></use></svg>' + t("重新运行") + "</button>";
    }
  }
  
  // Verify card：三态（通过 / 未通过 / 未执行）。run.verdict 是对象，旧代码写
  // `run.verdict === "pass"` 恒为 false，跑通的任务也显示「验证未通过」；
  // 而没配验证命令的任务（verify_ran=false）又不该显示为通过——口径同后端
  // _verify_text（2026-10-23 修）。
  const verify = $("wb-verify-card");
  if (verify) {
    const v = run && run.verdict && typeof run.verdict === "object" ? run.verdict : null;
    if (!v) {
      verify.innerHTML = '<span style="color:var(--muted)">' + t("暂无验证结果") + "</span>";
    } else {
      const ran = v.verify_ran !== false;
      const ok = ran && v.pass !== false && v.publishable !== false;
      const tone = !ran ? "" : ok ? "ok" : "bad";
      const icon = !ran ? "clock" : ok ? "check" : "x";
      const label = !ran ? t("验证未执行") : ok ? t("验证通过") : t("验证未通过");
      verify.innerHTML = '<div class="wb-verify-line' + (tone ? " " + tone : "") + '">' +
        '<svg class="ico" aria-hidden="true"><use href="#i-' + icon + '"></use></svg>' +
        label +
        "</div>";
    }
  }
}

/* 小说纸面预览：读 run 成品里的 chapter-<数字>.md 真章文。run.chapter_scores
 * 后端从不落盘，旧版对着它渲染永远是「暂无章节内容」。章清单来自
 * /api/runs/<id>/files（任务首跑以来的产出，与「成果」同口径，续写任务即本
 * 任务写的章节），正文走 /api/runs/<id>/file 按章现取；-draft/-final 等过程稿
 * 不进目录。 */
async function wbMountNovelPaper(run) {
  const paper = $("wb-paper");
  if (!paper) return;
  const seq = ++wbNpSeq;
  if (!run || !run.id) {
    paper.innerHTML = '<div style="padding:40px;text-align:center;color:var(--paper-muted)">' + t("暂无章节内容") + "</div>";
    return;
  }
  let files = [];
  try {
    const d = await api("/api/runs/" + encodeURIComponent(run.id) + "/files");
    files = (d.files || []).filter((f) => /^chapter-(\d+)\.md$/i.test(f.name || ""));
  } catch (e) { files = []; }
  if (seq !== wbNpSeq) return;   // 拉取期间重画过：过期响应不落盘
  const chNo = (f) => parseInt(f.name.match(/^chapter-(\d+)\.md$/i)[1], 10);
  files.sort((a, b) => chNo(a) - chNo(b));
  if (!files.length) {
    paper.innerHTML = '<div style="padding:40px;text-align:center;color:var(--paper-muted)">' + t("本次运行没有产出章节文件") + "</div>";
    return;
  }
  const opts = files.map((f, i) =>
    '<option value="' + i + '">' + esc(t("第") + " " + chNo(f) + " " + t("章")) + "</option>").join("");
  paper.innerHTML = '<div>' +
    '<div style="display:flex;align-items:center;gap:8px;padding:14px 18px;border-bottom:1px solid rgba(0,0,0,.08);position:sticky;top:0;background:inherit;z-index:1">' +
      '<button class="chip" id="wb-np-prev">‹ ' + esc(t("上一章")) + "</button>" +
      '<select id="wb-np-sel" style="max-width:220px" aria-label="' + esc(t("选择章节")) + '">' + opts + "</select>" +
      '<button class="chip" id="wb-np-next">' + esc(t("下一章")) + ' ›</button>' +
      '<span style="color:var(--paper-muted);font-size:12px">' + esc(files.length + t(" 章")) + "</span>" +
    "</div>" +
    '<div id="wb-np-body" style="padding:26px 8% 40px"><div style="text-align:center;color:var(--paper-muted)">' + esc(t("正在读取文件…")) + "</div></div>" +
    "</div>";
  const sel = $("wb-np-sel"), body = $("wb-np-body");
  const load = async (i) => {
    if (!sel || !body || i < 0 || i >= files.length) return;
    const mySeq = ++wbNpSeq;
    sel.value = String(i);
    body.innerHTML = '<div style="text-align:center;color:var(--paper-muted)">' + esc(t("正在读取文件…")) + "</div>";
    let text = "";
    try {
      const r = await fetch(urlAuth("/api/runs/" + encodeURIComponent(run.id) + "/file?name=" + encodeURIComponent(files[i].name)), { headers: authHeaders() });
      if (!r.ok) throw new Error("HTTP " + r.status);
      text = await r.text();
    } catch (e) { text = ""; }
    const box = $("wb-np-body");
    if (mySeq !== wbNpSeq || !box) return;   // 过期或纸面已重画：不落盘
    if (!text) {
      box.innerHTML = '<div style="text-align:center;color:var(--paper-muted)">' + esc(t("章节内容读取失败")) + "</div>";
      return;
    }
    // 标题取章内首个 # 标题行；没有就落回「第 N 章」
    const hm = text.match(/^\s*#\s*(.+?)\s*$/m);
    const title = hm ? hm[1] : (t("第") + " " + chNo(files[i]) + " " + t("章"));
    const prose = hm ? text.slice(text.indexOf(hm[0]) + hm[0].length).replace(/^\s+/, "") : text;
    box.innerHTML = '<h2 style="font-size:20px;font-weight:700;margin:0 0 18px;text-align:center">' + esc(title) + "</h2>" +
      '<div style="font-size:15px;line-height:2;white-space:pre-wrap;color:var(--paper,#3a332a)">' + esc(prose) + "</div>";
  };
  const cur = () => parseInt((sel && sel.value) || "0", 10) || 0;
  const prev = $("wb-np-prev"), next = $("wb-np-next");
  if (prev) prev.onclick = () => load(cur() - 1);
  if (next) next.onclick = () => load(cur() + 1);
  if (sel) sel.onchange = () => load(parseInt(sel.value, 10) || 0);
  load(0);
}

async function wbOpenPreview() {
  const task = wbCurrentTask();
  const run = wbLatestRun(task);
  if (!run) { toast(t("暂无可预览的运行"), true); return; }
  const type = String((task && task.type) || "").toLowerCase();
  if (type === "serial_novel" || type === "novel") { wbSetView("preview"); return; }   // 小说走纸面预览
  let d = null;
  try { d = await api("/api/runs/" + encodeURIComponent(run.id) + "/preview"); }
  catch (e) { d = null; }
  if (d && d.ok && d.base && d.entry) {
    window.open(urlAuth(d.base + d.entry), "_blank");
  } else {
    toast(t("该任务没有可预览的成品"), true);
  }
}

/* 入口 kind → 底部提示文案（后端 list_app 返回 web|video|audio|image|pdf） */
const WB_PV_KIND_HINT = {
  web: "网页成品预览", video: "媒体成品预览", audio: "媒体成品预览",
  image: "图片成品预览", pdf: "文档成品预览",
};

/* 工作台成品挂载：iframe 只认 /preview/<run>/<令牌>/<入口> 的只读静态挂载；
 * /api/runs/<id>/preview 是元数据接口，吐的是 ok/no_html 的 JSON——当页面开就是
 * 一行裸 JSON。挂载信息随 run 走：同 run 重画只把 iframe 亮回来，换 run/换任务/
 * 切视图即作废在飞的响应（wbPvSeq 闸门），也不给没有可预览成品的任务硬开窗口。 */
function wbPreviewReset() {
  wbPvMounted = "";
  const frame = $("wb-frame");
  if (frame) { frame.classList.add("hidden"); frame.removeAttribute("src"); }
}

async function wbMountWebPreview(run) {
  const seq = wbPvSeq;
  const frame = $("wb-frame"), empty = $("wb-empty");
  const stageActions = $("wb-stage-actions"), footHint = $("wb-foot-hint");
  if (!run || !run.id) {
    wbPreviewReset();
    if (empty) {
      empty.classList.remove("hidden");
      empty.querySelector("h3").textContent = t("暂无预览");
      empty.querySelector("p").textContent = t("任务尚未运行或没有可预览的成品");
    }
    if (stageActions) stageActions.innerHTML = "";
    if (footHint) footHint.textContent = "";
    return;
  }
  if (wbPvMounted === run.id) {
    if (frame) frame.classList.remove("hidden");
    return;
  }
  wbPreviewReset();
  let d = null;
  try { d = await api("/api/runs/" + encodeURIComponent(run.id) + "/preview"); }
  catch (e) { d = null; }
  if (seq !== wbPvSeq) return;   // 拉取期间重画过：过期响应不落盘
  if (d && d.ok && d.base && d.entry) {
    wbPvMounted = run.id;
    if (frame) {
      frame.src = urlAuth(d.base + d.entry);
      frame.classList.remove("hidden");
    }
    if (stageActions) stageActions.innerHTML = '<button class="ghost small" type="button" onclick="wbOpenPreview()"><svg class="ico" aria-hidden="true"><use href="#i-external"></use></svg><span>' + esc(t("新窗口打开")) + "</span></button>";
    if (footHint) footHint.textContent = t(WB_PV_KIND_HINT[d.kind] || "网页成品预览");
  } else {
    if (empty) {
      empty.classList.remove("hidden");
      empty.querySelector("h3").textContent = t("暂无可预览的成品");
      empty.querySelector("p").textContent = t("最近一次运行没有可预览的成品文件，请在详情页查看成果");
    }
    if (stageActions) stageActions.innerHTML = "";
    if (footHint) footHint.textContent = "";
  }
}

function wbOpenDetail() {
  const task = wbCurrentTask();
  if (!task) return;
  // 与侧栏点任务同一条链：主栏就地进对话式任务详情（showDetailInMain 会把
  // 工作台所在的设置子页切走，不会两层叠加）。codebeeOpenTaskDetail 从未存在，
  // 旧写法是点了没反应的静默空操作。
  window.sideOpenTask(task.id);
}

function wbRetryTask() {
  const task = wbCurrentTask();
  if (!task) return;
  // 与侧栏右键「重试」同一条链：POST /retry 后 jumpToRun 跳新 run
  retryTask(task.id);
}

// CDP workspace helpers (adapted from browser*)
function wbWorkspacePlatformFor(url) {
  try {
    const parsed = new URL(url, location.origin);
    if (parsed.protocol !== "https:" || parsed.username || parsed.password) return "";
    const host = parsed.hostname.toLowerCase();
    if (host === "fanqienovel.com" || host.endsWith(".fanqienovel.com")) return "fanqie";
    if (host === "qimao.com" || host.endsWith(".qimao.com")) return "qimao";
  } catch (e) {}
  return "";
}

function wbWorkspaceStop() {
  clearInterval(wbWorkspacePoll);
  wbWorkspacePoll = 0;
  wbWorkspacePlatform = "";
  wbWorkspaceKey = "";
  const screen = $("wb-cdp-screen");
  if (screen) { screen.classList.add("hidden"); screen.removeAttribute("src"); }
}

function wbWorkspaceShow(data) {
  const screen = $("wb-cdp-screen");
  if (!screen || !data || !data.image) throw new Error(t("浏览器没有返回页面画面"));
  screen.src = "data:image/png;base64," + data.image;
  screen.classList.remove("hidden");
}

function wbWorkspaceFallback(url, error) {
  const frame = $("wb-frame");
  wbWorkspaceStop();
  wbPvMounted = "";   // iframe 内容被工作台地址顶掉：旧挂载记录一并作废
  if (frame) {
    frame.classList.remove("hidden");
    frame.src = url;
  }
  const hint = $("wb-foot-hint");
  if (hint) hint.textContent = t("受控浏览器暂不可用，已切回嵌入页面") + (error ? " " + error : "");
}

async function wbWorkspaceRequest(platform, action, extra) {
  return api("/api/browser/workspace", {
    method: "POST", timeout: 90000, silent: true, busy: false, operation: false,
    headers: Object.assign(authHeaders(), { "Content-Type": "application/json" }),
    body: JSON.stringify(Object.assign({ platform, action }, extra || {})),
  });
}

async function wbWorkspaceRefresh(platform) {
  if (!platform || platform !== wbWorkspacePlatform) return;
  try {
    const data = await api("/api/browser/workspace?platform=" + encodeURIComponent(platform),
      { timeout: 15000, silent: true, busy: false, operation: false });
    if (platform === wbWorkspacePlatform) wbWorkspaceShow(data);
  } catch (e) {
    if (e && e.status === 409) return;
    wbWorkspaceFallback("", e && e.message);
  }
}

function wbWorkspaceOpen(url, platform) {
  const frame = $("wb-frame"), screen = $("wb-cdp-screen");
  if (frame) frame.classList.add("hidden");
  if (screen) screen.classList.remove("hidden");
  const key = platform + "\n" + url;
  if (wbWorkspaceKey === key) return;
  clearInterval(wbWorkspacePoll);
  wbWorkspacePlatform = platform;
  wbWorkspaceKey = key;
  if (screen) screen.removeAttribute("src");
  wbWorkspaceRequest(platform, "navigate", { url }).then((data) => {
    if (wbWorkspaceKey !== key) return;
    wbWorkspaceShow(data);
    clearInterval(wbWorkspacePoll);
    wbWorkspacePoll = window.setInterval(() => wbWorkspaceRefresh(platform), 1800);
  }).catch((e) => {
    if (wbWorkspaceKey !== key) return;
    if (e && e.status === 409) {
      const hint = $("wb-foot-hint");
      if (hint) hint.textContent = t("发布操作正在使用受控浏览器，完成后将继续打开作者后台。");
      clearInterval(wbWorkspacePoll);
      wbWorkspacePoll = window.setInterval(() => {
        if (wbWorkspaceKey !== key) return;
        wbWorkspaceRequest(platform, "navigate", { url }).then((data) => {
          if (wbWorkspaceKey !== key) return;
          wbWorkspaceShow(data);
          clearInterval(wbWorkspacePoll);
          wbWorkspacePoll = window.setInterval(() => wbWorkspaceRefresh(platform), 1800);
        }).catch((retryError) => {
          if (retryError && retryError.status === 409) return;
          if (wbWorkspaceKey === key) wbWorkspaceFallback(url, retryError && retryError.message);
        });
      }, 1800);
      return;
    }
    wbWorkspaceFallback(url, e && e.message);
  });
}

function wbWorkspacePointer(event, action) {
  const screen = $("wb-cdp-screen");
  if (!screen || screen.classList.contains("hidden") || !screen.naturalWidth || !screen.naturalHeight) return;
  const rect = screen.getBoundingClientRect();
  const scale = Math.min(rect.width / screen.naturalWidth, rect.height / screen.naturalHeight);
  const drawnWidth = screen.naturalWidth * scale, drawnHeight = screen.naturalHeight * scale;
  const left = rect.left + (rect.width - drawnWidth) / 2;
  const top = rect.top + (rect.height - drawnHeight) / 2;
  const x = Math.round((event.clientX - left) / scale), y = Math.round((event.clientY - top) / scale);
  if (x < 0 || y < 0 || x >= screen.naturalWidth || y >= screen.naturalHeight) return;
  wbWorkspaceAction(action, { x, y });
}

function wbWorkspaceAction(action, extra) {
  const platform = wbWorkspacePlatform;
  if (!platform) return;
  wbWorkspaceRequest(platform, action, extra).then((data) => {
    if (platform === wbWorkspacePlatform) wbWorkspaceShow(data);
  }).catch((e) => {
    if (e && e.status === 409) return;
    wbWorkspaceFallback("", e && e.message);
  });
}

// Publish state (reuse existing logic)
function wbLoadPublishState(task) {
  // This will be wired to existing pbLoadState
  if (window.pbLoadState) window.pbLoadState(task);
}

function wbBind() {
  const select = $("wb-task-select");
  if (select) {
    select.addEventListener("change", () => wbSetTask(select.value));
  }
  
  document.querySelectorAll("[data-wb-view]").forEach((btn) => {
    btn.addEventListener("click", () => wbSetView(btn.dataset.wbView));
  });
  
  wbView = wbState.view || "preview";
  wbDraw();
  wbLoadPublishState(wbCurrentTask());
}

/* ---------------------------------------------------------- 任务类型（流程） */
async function loadFlows() {
  // 偏好记忆（借鉴 chinese-novelist-skill）：并行拉最近一次的任务参数，
  // renderTypeOptions/onTypeChange 用它预填类型与轮数/阈值等（拉失败不挡首屏）
  api("/api/prefs").then((r) => { S.lastPrefs = (r && r.prefs) || {}; })
    .then(() => renderTypeOptions())
    .catch(() => {});
  try {
    const r = await api("/api/flows");
    S.flows = r.flows || [];
  } catch (e) { S.flows = []; }
  renderTypeOptions();
}

async function loadExperts() {
  try {
    const r = await api("/api/experts");
    S.experts = r.experts || [];
  } catch (e) { S.experts = []; }
  renderExpertOptions();
}

function renderExpertOptions() {
  const sel = $("f-expert");
  if (!sel) return;
  const prev = sel.value;
  sel.innerHTML = '<option value="">' + esc(t("通用执行")) + "</option>" +
    (S.experts || []).map((x) => '<option value="' + esc(x.id) + '">' +
      esc(t(x.name)) + " · " + esc(t(x.description || "")) + "</option>").join("");
  if (prev && (S.experts || []).some((x) => x.id === prev)) sel.value = prev;
}

function expertById(id) {
  return (S.experts || []).find((x) => x.id === id) || null;
}

function invalidateFlowRubricDraft(flowId) {
  if (S.flowRubricDrafts) delete S.flowRubricDrafts[flowId];
  const rubric = $("f-rubric");
  if (rubric && rubric.dataset.flowId === flowId) rubric.dataset.flowId = "";
}

function flowById(id) {
  return (S.flows || []).find((f) => f.id === id) || null;
}

/* 流程图标渲染："i-*" = 精灵表单色线性图标（currentColor，日/夜主题黑白自适应）；
 * 其他值（自定义流程的 emoji、老数据）原样文本显示兜底。 */
function flowIconHtml(f) {
  const ic = (f && f.icon) || "";
  if (ic.indexOf("i-") === 0) return '<svg class="ico" aria-hidden="true"><use href="#' + esc(ic) + '"></use></svg>';
  return ic ? '<span class="tp-emoji">' + esc(ic) + "</span>" : "";
}

function flowDesc(f) {
  if (f.id === "rank_scan") return t("四平台选材 → 评审打磨 → 标准输入 → 新开连载");
  if (f.id === "short_drama") return t("项目圣经 → 分集大纲 → 逐场对白剧本 → 连续性与集尾钩子评审（Markdown，不生成视频）");
  if (f.engine === "direct") return t("单智能体直达（快）");
  if (f.engine === "code") return t("实现 → 验证 →（复杂任务进）评审");
  // 连载与单稿件同引擎，描述必须区分：连载强调逐章与断点续跑
  if (f.serial) return t("大纲 → 逐章起草评审 → 合并（可续跑）");
  if (f.story) return t("起草 → 字数闸 → 评审修订（单篇）");
  return t("起草 → 多维评审 → 门禁");
}

function renderTypeOptions() {
  const sel = $("f-type");
  if (!sel || !S.flows) return;
  const prev = sel.value;  sel.innerHTML = (S.flows || []).map((f) => {
    return '<option value="' + esc(f.id) + '">' + esc(t(f.name)) + t("（") + flowDesc(f) + (f.builtin ? "" : t(" · 自定义")) + t("）") + "</option>";
  }).join("");
  // 保住用户手动选择（typeTouched）；出厂默认 direct 不算选择——prefs 迟到
  // 竞态下要让位给偏好记忆，否则「上次类型」永远恢复不了（高负载下实测）
  if (prev && flowById(prev) && (S.typeTouched || prev !== "direct")) sel.value = prev;
  // 偏好记忆：上次创建用的类型优先于出厂默认「直接执行」（老数据/已删流程回落）
  else if (!workspaceHasChoice && S.lastPrefs && S.lastPrefs.type && flowById(S.lastPrefs.type)) {
    sel.value = S.lastPrefs.type;
    workspaceChoice.mode = flowById(sel.value).engine === "code" ? "develop" : "work";
  }
  // 明确选择场景后恢复各自类型；已删除的记忆回落场景默认，再回落首项。
  else {
    const preferred = workspaceChoice.types[workspaceChoice.mode] || WORKSPACE_MODES[workspaceChoice.mode].defaultType;
    const fallback = WORKSPACE_MODES[workspaceChoice.mode].defaultType;
    if (flowById(preferred)) sel.value = preferred;
    else if (flowById(fallback)) sel.value = fallback;
  }
  applyTaskPreferenceDefaults();
  renderTypeMenu();
  onTypeChange();
  paintWorkspaceMode();
}

// 语言切换只更新类型文案，不触发 onTypeChange 的流程默认值回填，保留用户正在编辑的表单。
function refreshTypeTranslations() {
  const sel = $("f-type");
  if (!sel || !S.flows) return;
  const current = sel.value;
  sel.innerHTML = (S.flows || []).map((f) =>
    '<option value="' + esc(f.id) + '">' + esc(t(f.name)) + t("（") +
    flowDesc(f) + (f.builtin ? "" : t(" · 自定义")) + t("）") + "</option>").join("");
  sel.value = current;
  renderTypeMenu();
  syncTypeBtn();
}

function applyTaskPreferenceDefaults() {
  if (S.prefsApplied || !S.lastPrefs) return;
  const lp = S.lastPrefs;
  const mode = $("f-mode"), thinking = $("f-thinking");
  if (mode && ["auto", "fast", "expert", "manual"].includes(lp.mode)) mode.value = lp.mode;
  if (thinking && ["auto", "low", "standard", "high"].includes(lp.thinking)) thinking.value = lp.thinking;
  const manual = $("f-manual-only");
  if (manual && mode) manual.classList.toggle("hidden", mode.value !== "manual");
  syncCmpSelFace("f-mode");
  syncCmpSelFace("f-thinking");
  S.prefsApplied = true;
}

/* composer 内「编排模式/思考程度」pill 的短名：原生 select 透明覆盖在 pill 上，
 * face 只显示选项的短前缀（「自动（推荐）：…」→「自动」），值真源仍是 select。 */
function cmpSelShort(text) {
  return (String(text || "").split(/[：:]/)[0]
    .replace(/[（(].*?[）)]/g, "").trim()) || "";
}

function syncCmpSelFace(id) {
  const sel = $(id), face = $(id + "-face");
  if (!sel || !face) return;
  const opt = sel.options[sel.selectedIndex];
  face.textContent = cmpSelShort(opt && opt.textContent) || sel.value;
}
window.syncCmpSelFace = syncCmpSelFace;   // applyI18n 重译 option 后同步短名

/* ---- 对话模型 pill：厂商 → 模型两级钻取菜单（ChatGPT 选择器同款语汇）。
 * 真源仍是 f-direct-provider / f-direct-model-name 两个隐藏 select，
 * 菜单只改它们的值——既有提交流 / onTypeChange 显隐 / 测试全兼容。 */
let cmpModelProv = "";   // ""=厂商级；否则=已钻入的厂商 id（模型级）

/* 可指定为对话执行者的真实 CLI（手动指定 CLI，2026-09-23）：
 * state.agents 即 effective_agents（已装+启用编排），mode=real 排掉 mock */
function realCliAgents() {
  return ((S.state && S.state.agents) || []).filter((a) => a && a.mode === "real");
}

function cmpDirectAgentVal() {
  const el = $("f-direct-agent");
  return el ? String(el.value || "").trim() : "";
}

function cmpDirectBtnSync() {
  const btn = $("f-direct-btn");
  if (!btn) return;
  const av = cmpDirectAgentVal();
  if (av) {
    const a = realCliAgents().find((x) => x.id === av);
    btn.textContent = (a ? (a.label || a.id) : av) + " · CLI";
    return;
  }
  const pv = $("f-direct-provider").value, mv = $("f-direct-model-name").value;
  if (!pv) { btn.textContent = t("自动推荐"); return; }
  const p = directProviders().find((x) => x.id === pv);
  btn.textContent = (p ? (p.name || p.id) : pv) + (mv ? "/" + mv : "/" + t("推荐"));
}

/* 菜单里「指定 CLI」分组（两级菜单复用同一段，差别只在真源变量）：
 * entriesHtml(选中id, 空文案) 返回分组 HTML；空列表返回 "" */
function cliMenuSectionHtml(selectedId) {
  const clis = realCliAgents();
  if (!clis.length) return "";
  const chk = '<svg class="ico ti-check" aria-hidden="true"><use href="#i-check"></use></svg>';
  return '<div class="type-menu-cap">' + t("指定 CLI") + "</div>" +
    clis.map((a) =>
      '<button type="button" class="type-item" data-cli="' + esc(a.id) + '"><span class="ti-body"><span class="ti-name">' +
      esc(a.label || a.id) + "</span></span>" + (selectedId === a.id ? chk : "") + "</button>").join("");
}

function cmpModelMenuRender() {
  const menu = $("cmp-model-menu");
  if (!menu) return;
  const pv = $("f-direct-provider").value, mv = $("f-direct-model-name").value;
  const av = cmpDirectAgentVal();
  const chk = '<svg class="ico ti-check" aria-hidden="true"><use href="#i-check"></use></svg>';
  const arr = '<svg class="ico ti-check" aria-hidden="true"><use href="#i-chevron-r"></use></svg>';
  if (!cmpModelProv) {
    menu.innerHTML =
      '<button type="button" class="type-item" data-p="" data-m=""><span class="ti-body"><span class="ti-name">' +
        t("自动推荐") + "</span></span>" + (!pv && !av ? chk : "") + "</button>" +
      directProviders().map((p) =>
        '<button type="button" class="type-item" data-p="' + esc(p.id) + '"><span class="ti-body"><span class="ti-name">' +
        esc(p.name || p.id) + "</span></span>" + (pv === p.id && !av ? chk : arr) + "</button>").join("") +
      cliMenuSectionHtml(av) +
      '<div class="type-menu-foot"><button type="button" class="type-item" data-manage="1"><span class="ti-body"><span class="ti-name">' +
        t("管理模型…") + "</span></span></button></div>";
  } else {
    const p = directProviders().find((x) => x.id === cmpModelProv);
    const names = p ? (p.models || []).filter((m) => m.enabled !== false && !m.hidden)
      .map((m) => m.name).filter(Boolean) : [];
    menu.innerHTML =
      '<button type="button" class="type-item" data-back="1"><span class="ti-body"><span class="ti-name">‹ ' +
        esc(p ? (p.name || p.id) : cmpModelProv) + "</span></span></button>" +
      '<button type="button" class="type-item" data-p="' + esc(cmpModelProv) + '" data-m=""><span class="ti-body"><span class="ti-name">' +
        t("随厂商推荐") + "</span></span>" + (pv === cmpModelProv && !mv ? chk : "") + "</button>" +
      names.map((n) =>
        '<button type="button" class="type-item" data-p="' + esc(cmpModelProv) + '" data-m="' + esc(n) + '"><span class="ti-body"><span class="ti-name">' +
        esc(n) + "</span></span>" + (pv === cmpModelProv && mv === n ? chk : "") + "</button>").join("");
  }
  positionFloatingModelMenu(menu, $("f-direct-wrap"));
}

const FLOATING_MODEL_MENUS = [
  ["cmp-model-menu", "f-direct-wrap"],
  ["rd-model-menu", "rd-model-wrap"],
];

function positionFloatingModelMenu(menu, anchor) {
  if (!menu || !anchor || menu.classList.contains("hidden")) return;
  const rect = anchor.getBoundingClientRect();
  const viewportWidth = document.documentElement.clientWidth;
  const viewportHeight = document.documentElement.clientHeight;
  const width = Math.max(1, Math.min(320, viewportWidth - 16));
  const left = Math.max(8, Math.min(rect.left, viewportWidth - width - 8));
  const above = Math.max(0, rect.top - 14);
  const below = Math.max(0, viewportHeight - rect.bottom - 14);
  const openAbove = above >= below;
  const available = openAbove ? above : below;
  const maxHeight = Math.max(1, Math.min(316, viewportHeight - 16, Math.max(48, available - 6)));

  menu.style.width = width + "px";
  menu.style.maxHeight = maxHeight + "px";
  const height = Math.min(menu.scrollHeight, maxHeight);
  const maxTop = Math.max(8, viewportHeight - height - 8);
  const desiredTop = openAbove ? rect.top - height - 6 : rect.bottom + 6;
  menu.style.left = left + "px";
  menu.style.top = Math.max(8, Math.min(maxTop, desiredTop)) + "px";
}

function syncFloatingModelMenus() {
  for (const [menuId, anchorId] of FLOATING_MODEL_MENUS)
    positionFloatingModelMenu($(menuId), $(anchorId));
}

document.addEventListener("scroll", syncFloatingModelMenus, true);
window.addEventListener("resize", syncFloatingModelMenus);

function toggleModelMenu(force) {
  const menu = $("cmp-model-menu");
  if (!menu) return;
  const show = force !== undefined ? force : menu.classList.contains("hidden");
  if (show) { cmpModelProv = ""; cmpModelMenuRender(); }
  menu.classList.toggle("hidden", !show);
  if (show) positionFloatingModelMenu(menu, $("f-direct-wrap"));
}
window.toggleModelMenu = toggleModelMenu;

(function () {
  const menu = $("cmp-model-menu");
  if (!menu || menu.dataset.cmpBound) return;
  document.body.appendChild(menu);
  menu.dataset.cmpBound = "1";
  menu.addEventListener("click", (e) => {
    // 钻取/选定都在菜单内完成：阻止冒泡到 document 的「点外面收起」——
    // innerHTML 重写后 e.target 是已脱离 DOM 的旧节点，wrap.contains 会误判
    // false 而把刚钻取的菜单收掉（真机「点厂商没反应」根因）
    e.stopPropagation();
    const b = e.target.closest("[data-p],[data-back],[data-manage],[data-cli]");
    if (!b) return;
    if (b.dataset.manage) { toggleModelMenu(false); switchTab("models"); return; }
    if (b.dataset.back) { cmpModelProv = ""; cmpModelMenuRender(); return; }
    if (b.dataset.cli !== undefined) {
      // 手动指定执行 CLI：写真源即可，模型绑定保留在任务上（运行时 CLI 优先）
      $("f-direct-agent").value = b.dataset.cli;
      cmpDirectBtnSync();
      toggleModelMenu(false);
      return;
    }
    if (b.dataset.m === undefined) {
      // 点厂商 = 只钻取到模型级（用户拍板 2026-09-21：模型必须亲手点，
      // 不要自动带推荐）。真源不动——用户点了具体模型才写 provider/model。
      cmpModelProv = b.dataset.p;
      cmpModelMenuRender();
      return;
    }
    // 选定：写回隐藏 select 真源（提交流/回归测试全走原路径）。顺序关键：
    // 先让 provider 的 option 就位再赋值，否则 select.value 静默失效（真机
    // 「没法选模型」根因：options 由 poll 重建，可能仍是残缺态）。
    // 选定模型/自动推荐同时清除 CLI 指定（三者互斥，模型生效=走内置智能体）
    $("f-direct-agent").value = "";
    renderDirectModelPicker();
    $("f-direct-provider").value = b.dataset.p;
    renderDirectModelPicker();
    $("f-direct-model-name").value = b.dataset.m;
    if ($("f-direct-model-name").value !== b.dataset.m) {
      const opt = document.createElement("option");
      opt.value = b.dataset.m;
      $("f-direct-model-name").appendChild(opt);
      $("f-direct-model-name").value = b.dataset.m;
    }
    cmpDirectBtnSync();
    toggleModelMenu(false);
  });
  document.addEventListener("click", (e) => {
    const wrap = $("f-direct-wrap");
    if (wrap && !wrap.contains(e.target) && !menu.contains(e.target)) toggleModelMenu(false);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") toggleModelMenu(false);
  });
})();

/* 类型选择的可见层：带黑白图标的按钮 + 弹出菜单。原生 <option> 渲染不了 SVG，
 * 所以隐藏 select 只当值真源（既有联动/测试全部照旧），外观全靠这层。 */
function renderTypeMenu() {
  const menu = $("type-menu");
  if (!menu || !S.flows) return;
  menu.innerHTML = (S.flows || []).map((f) => {
    const est = S.flowEstimates && S.flowEstimates[f.id];
    return '<button type="button" class="type-item" role="option" data-v="' + esc(f.id) + '" onclick="pickType(\'' + jsq(f.id) + '\')">' +
    '<span class="ti-ico" aria-hidden="true">' + flowIconHtml(f) + "</span>" +
    '<span class="ti-body"><span class="ti-name">' + esc(t(f.name)) +
    (f.builtin ? "" : '<em class="ti-tag">' + t("自定义") + "</em>") + "</span>" +
    '<span class="ti-desc">' + esc(flowDesc(f)) + "</span>" +
    (est ? '<span class="ti-est">' + esc(t("≈{0} tokens · {1}次", fmtTok(est.median_tokens), est.samples)) + "</span>" : "") +
    "</span>" +
    '<svg class="ico ti-check" aria-hidden="true"><use href="#i-check"></use></svg>' +
    "</button>";
  }).join("")
    /* 底部固定入口：管理流程替代原工具条上的「管理」按钮（简化 composer 工具行） */
    + '<div class="type-menu-foot"><button type="button" class="type-item" onclick="manageFlowsFromMenu()">' +
    '<span class="ti-ico" aria-hidden="true"><svg class="ico"><use href="#i-gear"></use></svg></span>' +
    '<span class="ti-body"><span class="ti-name">' + esc(t("管理任务类型…")) + "</span></span></button></div>";
  syncTypeBtn();
}

/* 类型菜单的成本/次数预估（借鉴 omnigent，数据源 /api/usage/estimate）：
 * 拉到手后就地更新菜单项——菜单开着也不重建 DOM，不打断滚动/悬停 */
async function fetchFlowEstimates() {
  if (!S.flows || S._flowEstimatesLoading || S._flowEstimatesLoaded) return;
  S._flowEstimatesLoading = true;
  const targets = S.flows;
  const results = [];
  for (const f of targets) {
    try {
      const d = await api("/api/usage/estimate?type=" + encodeURIComponent(f.id) + "&days=90");
      results.push([f.id, (d && d.samples > 0) ? d : null]);
    } catch (e) { results.push([f.id, null]); }
  }
  S._flowEstimatesLoading = false;
  S._flowEstimatesLoaded = true;
  S.flowEstimates = Object.fromEntries(results.filter(([, d]) => d));
  const menu = $("type-menu");
  if (!menu) return;
  menu.querySelectorAll(".type-item[data-v]").forEach((b) => {
    const d = S.flowEstimates[b.dataset.v];
    const body = b.querySelector(".ti-body");
    if (!d || !body || body.querySelector(".ti-est")) return;
    const est = document.createElement("span");
    est.className = "ti-est";
    est.textContent = t("≈{0} tokens · {1}次", fmtTok(d.median_tokens), d.samples);
    body.appendChild(est);
  });
}
window.manageFlowsFromMenu = function () {
  toggleTypeMenu(false);
  openFlowsManager();
};

function syncTypeBtn() {
  const sel = $("f-type");
  const flow = flowById(sel.value);
  const ico = $("f-type-ico"), name = $("f-type-name");
  if (flow && ico) ico.innerHTML = flowIconHtml(flow);
  if (flow && name) name.textContent = t(flow.name);
  const menu = $("type-menu");
  if (menu) menu.querySelectorAll(".type-item").forEach((b) => b.classList.toggle("on", b.dataset.v === sel.value));
}

function toggleTypeMenu(force) {
  const menu = $("type-menu");
  if (!menu) return;
  const show = force != null ? !!force : menu.classList.contains("hidden");
  menu.classList.toggle("hidden", !show);
  if (show) fetchFlowEstimates();
}

function pickType(id) {
  if (!flowById(id)) return;
  S.typeTouched = true;   // 用户手动选过：flows 重渲染时优先保住，不让位偏好记忆
  const sel = $("f-type");
  if (sel && sel.value !== id) {
    sel.value = id;
    sel.dispatchEvent(new Event("change"));   // 既有联动（表单显隐/流程默认值）照常走
  }
  toggleTypeMenu(false);
  rememberWorkspaceType(id);
}
window.toggleTypeMenu = toggleTypeMenu;
window.pickType = pickType;

/* 切换类型：按引擎显隐表单区、带出流程默认值 */
function onTypeChange() {
  syncTypeBtn();
  renderQuickChips();
  const flow = flowById($("f-type").value);
  const expertSel = $("f-expert");
  if (expertSel && expertSel.value) {
    const expert = expertById(expertSel.value);
    if (!expert || expert.flow_id !== (flow && flow.id)) expertSel.value = "";
  }
  const engine = flow ? flow.engine : "code";
  const isReview = engine === "review";
  const isDirect = engine === "direct";
  const codeOnly = $("f-code-only"), reviewOnly = $("f-review-only");
  // 直连：验证命令与评审参数都不适用，两块一起收起（目标+附件即全部输入）
  if (codeOnly) codeOnly.classList.toggle("hidden", isReview || isDirect);
  if (reviewOnly) reviewOnly.classList.toggle("hidden", !isReview);
  // 对话模型选择已收进工具行 pill：更多选项里的旧块永久隐藏（select 真源保留）
  if ($("f-direct-model")) $("f-direct-model").classList.add("hidden");
  const dwrap = $("f-direct-wrap");
  if (dwrap) dwrap.classList.toggle("hidden", !isDirect);
  if (isDirect) { renderDirectModelPicker(); cmpDirectBtnSync(); }
  const bibleCreate = $("bible-create-field");
  const isSerialReview = isReview && !!(flow && flow.serial);
  if (bibleCreate) bibleCreate.classList.toggle("hidden", !isSerialReview);
  const dramaFields = $("f-drama-only");
  if (dramaFields) dramaFields.classList.toggle("hidden", !(isReview && flow && flow.id === "short_drama"));
  const storyFields = $("f-story-only");
  if (storyFields) storyFields.classList.toggle("hidden", !(isReview && flow && flow.story));
  const clearSerialFields = () => ["f-chapters", "f-words-per-ch", "f-variants", "f-branches", "f-bible",
    "f-vol-chapters", "f-vol-spec", "f-story-words"].forEach((id) => {
    const el = $(id);
    if (el) el.value = "";
  });
  const goal = $("f-goal");
  if (goal && flow && flow.goal_hint) goal.placeholder = t(flow.goal_hint);
  if (isReview && flow) {
    if (flow.manuscript) $("f-manuscript").value = flow.manuscript;
    // 偏好记忆（借鉴 chinese-novelist-skill）：上次创建用过的参数优先于流程出厂默认
    const lp = S.lastPrefs || {};
    $("f-rounds").value = lp.rounds || flow.rounds || 2;
    $("f-threshold").value = (lp.threshold != null ? lp.threshold : (flow.threshold || 7.0));
    $("f-bestof").value = lp.best_of || flow.best_of || 1;
    const rubric = $("f-rubric");
    const previousFlow = rubric.dataset.flowId || "";
    if (!S.flowRubricDrafts) S.flowRubricDrafts = {};
    if (previousFlow && previousFlow !== flow.id) {
      S.flowRubricDrafts[previousFlow] = rubric.value;
    }
    if (previousFlow !== flow.id) {
      rubric.value = Object.prototype.hasOwnProperty.call(S.flowRubricDrafts, flow.id)
        ? S.flowRubricDrafts[flow.id]
        : (flow.rubric || []).join(", ");
      rubric.dataset.flowId = flow.id;
    }
    // 连载参数预填（用户可改/可清空 = 单稿件模式）；偏好记忆的最近值优先
    if (flow.serial) {
      if (!$("f-chapters").value) $("f-chapters").value = lp.chapters || flow.serial.chapters || "";
      if (!$("f-words-per-ch").value) $("f-words-per-ch").value = lp.words_per_chapter || flow.serial.words_per_chapter || "";
      // 分卷开箱即用：没填过就预填一个常见每卷章数（用户可改；清空 = 不分卷）。
      // 卷边界由后端按全书章号推导，续写批次自动接上同一卷。
      if (!$("f-vol-chapters").value && !$("f-vol-spec").value) {
        $("f-vol-chapters").value = (lp.volume_chapters != null && lp.volume_chapters !== "")
          ? lp.volume_chapters : (flow.serial.volume_chapters || 20);
      }
    } else clearSerialFields();
    // 短篇目标字数预填（在 clearSerialFields 之后：非连载流程刚被清空）
    if (flow.story) {
      if (!$("f-story-words").value) {
        $("f-story-words").value = (lp.story_words != null && lp.story_words !== "")
          ? lp.story_words : flow.story.words || 12000;
      }
    }
  } else {
    // 隐藏控件仍保留 DOM 值；换流程时清理，避免章节/圣经状态污染下一次提交。
    clearSerialFields();
  }
  renderImplSelects();
  refreshEstimate();
}

function directProviders() {
  /* 停用厂商不列出（用户拍板 2026-09-21「停用的不弄出来」）；只列启用且有 key 的。
   * 模型名单已抓取但启用数为零的也不列——「随厂商推荐」没有可落的模型。 */
  return (S.providers || []).filter((p) => {
    if (p.enabled === false || !p.api_key) return false;
    const ms = p.models;
    if (Array.isArray(ms) && ms.length && !ms.some((m) => m.enabled !== false && !m.hidden)) return false;
    return true;
  });
}

function renderDirectModelPicker() {
  const ps = $("f-direct-provider"), ms = $("f-direct-model-name");
  if (!ps || !ms) return;
  const prev = ps.value;
  const provs = directProviders();
  ps.innerHTML = '<option value="">' + t("自动推荐") + '</option>' + provs.map((p) =>
    '<option value="' + esc(p.id) + '">' + esc(p.name || p.id) + "</option>").join("");
  if (prev && provs.some((p) => p.id === prev)) ps.value = prev;
  const p = provs.find((x) => x.id === ps.value);
  const oldModel = ms.value;
  // 只列启用模型（停用/已删除的与后端 resolve 同口径；已选模型被停用时自然回落「随厂商推荐」）
  const names = p ? (p.models || []).filter((m) => !m.hidden && m.enabled !== false)
    .map((m) => m.name).filter(Boolean) : [];
  ms.innerHTML = '<option value="">' + t("随厂商推荐") + '</option>' + names.map((name) =>
    '<option value="' + esc(name) + '">' + esc(name) + "</option>").join("");
  if (oldModel && names.includes(oldModel)) ms.value = oldModel;
  cmpDirectBtnSync();   // 工具行 pill 文字跟随真源
}

function recommendTaskType(goal) {
  const s = String(goal || "").toLowerCase();
  const rules = [
    // 专属词在前（简历/PPT/标书的目标里常带技术词，放 code 之后会被截胡，
    // 「优化我的简历，投后端岗」实测命中 code——2026-10-07 巡检）：
    ["resume", /(简历|求职|应聘)/i],
    ["presentation", /(演示文稿|ppt|幻灯片|答辩|演示场合)/i],
    ["bid_doc", /(标书|投标|招标应答)/i],
    // 缺陷复盘同为专属词（「复盘这些bug」会被 code 的 bug 词截胡）：要求复盘
    // 与 bug/缺陷 共现（或命中漏测），纯 debug（「分析这个bug」）仍归 code。
    ["defect_retro",
     /(缺陷复盘|漏测|(bug|缺陷)[^，。；]{0,10}复盘|复盘[^，。；]{0,10}(bug|缺陷))/i],
    ["code", /(代码|bug|报错|修复|重构|接口|数据库|前端|后端|python|javascript|typescript|java|go\b|git)/i],
    ["translation", /(翻译|译成|translate|translation|中译英|英译中)/i],
    ["email", /(邮件|email|e-mail|回信|邀约信|商务函)/i],
    ["weekly_report", /(周报|月报|述职|工作汇报|工作总结)/i],
    ["short_drama", /(短剧|微短剧|短剧本|分集剧本|网剧本)/i],
    // 手绘视频在 video_script 之前：「手绘讲解视频」兼有视频词，专属词先接
    ["handdraw_video", /(手绘|手绘视频|白板动画|涂鸦视频|边画边讲)/i],
    ["video_script", /(短视频|口播|分镜|抖音|b站|视频号|视频脚本|讲解视频)/i],
    ["speech", /(演讲稿|发言稿|致辞|演讲)/i],
    ["tech_proposal", /(技术方案|架构方案|选型方案|实施方案)/i],
    ["research", /(调研|深度研究)/i],
    // goal_hint 引导词对齐（2026-10-08 第二轮巡检）：serial_novel 例句
    // 「都市女频/可签约平台」、article 提示「头条/知乎」——照提示输入
    // 此前不弹类型建议（同 video_script 补词第 3 例缝隙）。
    // 短篇在连载/长篇之前：「短篇小说/短故事」不含连载词，但会被 novel 的
    // 「小说/短篇」截胡——专属词先接（2026-10-22 短篇流程）。
    ["short_story", /(短篇|短故事)/i],
    ["serial_novel", /(连载|续写.*章|网文|长篇小说|女频|男频|签约平台)/i],
    ["novel", /(小说|故事|章节)/i],
    ["article", /(公众号|自媒体|文章|博客|小红书|头条|知乎)/i],
    ["doc", /(文档|操作手册|说明书)/i],
    // 宽词放末位兜底（「电影排行榜文章」由前面的 article 先接住）；词形对齐
    // rank_scan 的 goal_hint（「默认分析总榜热门题材」）。至此 direct 之外
    // 17 型推荐规则全覆盖（2026-10-08 巡检补 rank_scan/defect_retro 两型）。
    ["rank_scan", /(扫榜|热门题材|榜单分析|排行榜)/i],
  ];
  const hit = rules.find((x) => x[1].test(s));
  return hit && flowById(hit[0]) ? hit[0] : "";
}

