/* 开跑前成本与耗时预估（借鉴 omnigent 的 pre-run estimate）：优先读同类台账，
 * 无历史时显示流程基线；快速切类型用序号丢弃过期响应。 */
let _estSeq = 0;
async function refreshEstimate() {
  const el = $("cmp-estimate");
  const flowId = ($("f-type") || {}).value || "";
  if (!el) return;
  const seq = ++_estSeq;
  try {
    const mode = ($("f-mode") || {}).value || "auto";
    const thinking = ($("f-thinking") || {}).value || "standard";
    const rounds = ($("f-rounds") || {}).value || "";
    const query = new URLSearchParams({ type: flowId, days: "90", mode, thinking });
    if (rounds) query.set("rounds", rounds);
    const d = await api("/api/usage/estimate?" + query.toString());
    if (seq !== _estSeq) return;
    if (!d || !(d.estimated_duration_s > 0)) {
      el.classList.add("hidden"); el.textContent = ""; return;
    }
    const duration = chatDurTxt(d.estimated_duration_s);
    const p90 = chatDurTxt(d.p90_duration_s || d.estimated_duration_s);
    const source = (d.samples || 0) >= (d.min_samples_for_estimate || 10)
      ? t("近{0}天 · {1}次同类", d.days || 90, d.samples)
      : (d.samples > 0
        ? t("同类仅 {0} 次样本，估得不准", d.samples)
        : t("暂无同类历史，按流程基线估算"));
    const tokenPart = d.samples >= (d.min_samples_for_estimate || 10) && d.median_tokens != null
      ? " · ≈" + fmtTok(d.median_tokens) + " tokens" : "";
    const cost = (d.median_cost_usd || 0) > 0 ? " · ≈¥" + Number(d.median_cost_usd).toFixed(2) : "";
    el.textContent = t("预计完成约 {0}，保守不超过 {1}", duration, p90) +
      tokenPart + cost + t("（") + source + t("）");
    el.classList.remove("hidden");
  } catch (e) {
    if (seq === _estSeq) { el.classList.add("hidden"); el.textContent = ""; }
  }
}

/* ---------------------------------------------------------- 本机身份与鉴权 */
function clientId() {
  let id = localStorage.getItem("orch.client");
  if (!id) {
    const buf = new Uint8Array(8);
    if (window.crypto && crypto.getRandomValues) {
      crypto.getRandomValues(buf);
      id = "c-" + Date.now() + "-" + Array.from(buf, (b) => b.toString(16).padStart(2, "0")).join("");
    } else {
      id = "c-" + Date.now();  // 极老浏览器兜底：仅本地设备标识，非加密用途
    }
    localStorage.setItem("orch.client", id);
  }
  return id;
}

function deviceName() {
  const ua = navigator.userAgent;
  if (/iPhone/.test(ua)) return "iPhone";
  if (/iPad/.test(ua)) return "iPad";
  if (/Android/.test(ua)) return "Android";
  if (/Macintosh/.test(ua)) return "Mac";
  if (/Edg\//.test(ua)) return t("Edge·电脑");
  if (/Chrome/.test(ua)) return t("Chrome·电脑");
  return t("电脑");
}

function authHeaders(extra) {
  return Object.assign({
    "Content-Type": "application/json",
    "X-CodeBee-Token": localStorage.getItem("orch.token") || "",
    "X-CodeBee-Client": clientId(),
    "X-CodeBee-Name": encodeURIComponent(deviceName()),  // 头值必须 ISO-8859-1
  }, extra || {});
}

/* EventSource 带不了自定义头：鉴权与设备身份全走 query */
function qsAuth() {
  const q = new URLSearchParams();
  const t = localStorage.getItem("orch.token");
  if (t) q.set("token", t);
  q.set("client", clientId());
  q.set("name", encodeURIComponent(deviceName()));
  const s = q.toString();
  return s ? "?" + s : "";
}

/* 下载/预览等导航类 URL 同样带不了请求头：令牌拼进 query（已有 query 用 &，
 * 没有用 ?；已带 token 的 URL 原样返回）。本机会话令牌为空则原样返回。 */
function urlAuth(u) {
  const t = localStorage.getItem("orch.token");
  if (!t || String(u).includes("token=")) return u;
  return u + (String(u).includes("?") ? "&" : "?") + "token=" + encodeURIComponent(t);
}

/* ---------------------------------------------------------- 工具 */
let _requestBusyCount = 0;
let _lastActionButton = null;
let _lastActionAt = 0;
const _requestBusyButtons = new WeakMap();
const _operations = [];
let _operationSeq = 0;

function operationLabel(path, opts) {
  if (opts && opts.operation === false) return "";
  if (opts && typeof opts.operation === "string") return t(opts.operation);
  if (opts && opts.busy === false && opts.operation !== true) return "";
  const method = String((opts && opts.method) || "GET").toUpperCase();
  if (method === "GET" || method === "HEAD") return "";
  // 只自动记录刚由用户点击触发的写操作；后台维护请求需显式传 operation 才显示。
  if (!(opts && opts.operation === true) &&
      (!_lastActionAt || performance.now() - _lastActionAt >= 2000)) return "";
  const clean = String(path || "").split("?")[0];
  const rules = [
    [/^\/api\/tasks$/, t("创建任务")],
    [/\/tasks\/[^/]+\/delete$/, t("删除任务")],
    [/\/tasks\/[^/]+\/archive$/, t("归档任务")],
    [/\/tasks\/[^/]+\/retry$/, t("重试任务")],
    [/\/tasks\/[^/]+\/continue$/, t("创建续写任务")],
    [/\/tasks\/[^/]+\/rename$/, t("重命名任务")],
    [/\/runs\/[^/]+\/cancel$/, t("取消运行")],
    [/\/runs\/[^/]+\/delete$/, t("删除运行")],
    [/\/runs\/(delete-batch|clear)$/, t("清理运行记录")],
    [/\/attachments(?:\/[^/]+)?$/, t("上传附件")],
    [/\/selfupdate\/apply$/, t("升级 CodeBee")],
    [/\/market\//, t("更新插件")],
    [/\/models\/binding$/, t("更新智能体绑定")],
    [/\/models\//, t("更新模型配置")],
    [/\/zentao\/test$/, t("测试禅道连接")],
    [/\/zentao\/products$/, t("拉取禅道产品")],
    [/\/zentao\/users$/, t("拉取禅道账号")],
    [/\/zentao\/modules$/, t("拉取模块清单")],
    [/\/zentao\/scan$/, t("禅道扫描 Bug")],
    [/\/zentao\/config$/, t("保存禅道配置")],
    [/\/wxdigest\/groups$/, t("刷新群列表")],
    [/\/wxdigest\/scan$/, t("扫描群摘要")],
    [/\/wxdigest\/config$/, t("保存群摘要设置")],
    [/\/ports\/close$/, t("关闭端口进程")],
  ];
  const hit = rules.find((it) => it[0].test(clean));
  return t(hit ? hit[1] : t("提交操作"));
}

function operationStart(path, opts) {
  const label = operationLabel(path, opts);
  if (!label) return null;
  const op = { id: ++_operationSeq, label, status: "running", at: Date.now(), error: "" };
  _operations.unshift(op);
  if (_operations.length > 12) _operations.length = 12;
  renderOperationCenter();
  return op.id;
}

function operationFinish(id, status, error) {
  if (!id) return;
  const op = _operations.find((it) => it.id === id);
  if (!op) return;
  op.status = status;
  op.error = String(error || "").slice(0, 240);
  op.endedAt = Date.now();
  renderOperationCenter();
}

function operationTime(ts) {
  try { return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }
  catch (e) { return ""; }
}

function renderOperationCenter() {
  const button = $("btn-ops");
  const list = $("op-list");
  if (!button || !list) return;
  button.classList.toggle("hidden", !_operations.length);
  const running = _operations.filter((it) => it.status === "running").length;
  const failed = _operations.filter((it) => it.status === "failed").length;
  button.classList.toggle("running", running > 0);
  button.classList.toggle("failed", !running && failed > 0);
  button.classList.toggle("done", !running && !failed && _operations.length > 0);
  const pill = $("op-pill-text");
  if (pill) pill.textContent = running ? t("{0} 项处理中").replace("{0}", running)
    : failed ? t("{0} 项失败").replace("{0}", failed) : t("操作完成");
  list.innerHTML = _operations.map((op) => {
    const status = op.status === "running" ? t("处理中")
      : op.status === "failed" ? t("失败") : t("已完成");
    const remove = op.status === "running" ? "" :
      '<button type="button" class="op-dismiss" aria-label="' + esc(t("移除")) +
      '" title="' + esc(t("移除")) + '" onclick="dismissOperation(event,' + jsq(op.id) + ')">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg></button>';
    return '<div class="op-row ' + op.status + '"><span class="op-state" aria-hidden="true"></span>' +
      '<div class="op-copy"><div><b>' + esc(op.label) + '</b><span>' + esc(status) + " · " +
      esc(operationTime(op.endedAt || op.at)) + '</span></div>' +
      (op.error ? '<p title="' + esc(op.error) + '">' + esc(op.error) + "</p>" : "") +
      "</div>" + remove + "</div>";
  }).join("");
}

function toggleOperationCenter(force) {
  const panel = $("op-center");
  const button = $("btn-ops");
  if (!panel || !button) return;
  const open = force === undefined ? panel.classList.contains("hidden") : !!force;
  panel.classList.toggle("hidden", !open);
  button.setAttribute("aria-expanded", open ? "true" : "false");
}

function clearFinishedOperations() {
  for (let i = _operations.length - 1; i >= 0; i--) {
    if (_operations[i].status === "done") _operations.splice(i, 1);
  }
  renderOperationCenter();
  if (!_operations.length) toggleOperationCenter(false);
}

function dismissOperation(event, id) {
  if (event) event.stopPropagation();
  const i = _operations.findIndex((it) => it.id === id && it.status !== "running");
  if (i >= 0) _operations.splice(i, 1);
  renderOperationCenter();
  if (!_operations.length) toggleOperationCenter(false);
}

window.toggleOperationCenter = toggleOperationCenter;
window.clearFinishedOperations = clearFinishedOperations;
window.dismissOperation = dismissOperation;

document.addEventListener("click", (e) => {
  const wrap = $("op-wrap");
  if (wrap && !wrap.contains(e.target)) toggleOperationCenter(false);
});

/* 记录发起请求的按钮。写请求统一在 api() 里挂忙碌态，避免每个业务入口各写一套；
 * 确认框的按钮不覆盖原始操作按钮，但会续期，使“确认后执行”仍反馈在原按钮上。 */
document.addEventListener("click", (e) => {
  const btn = e.target && e.target.closest ? e.target.closest("button") : null;
  if (!btn) return;
  if (btn.classList.contains("request-busy")) {
    e.preventDefault();
    e.stopImmediatePropagation();
    return;
  }
  _lastActionAt = performance.now();
  if (!btn.closest("#ask")) _lastActionButton = btn;
}, true);

function requestBusyStart(opts) {
  const method = String((opts && opts.method) || "GET").toUpperCase();
  if (opts && opts.busy === false) return null;
  if ((method === "GET" || method === "HEAD") && !(opts && opts.busy)) return null;

  _requestBusyCount++;
  let bar = $("request-progress");
  if (!bar && document.body) {
    bar = document.createElement("div");
    bar.id = "request-progress";
    bar.className = "request-progress";
    bar.setAttribute("role", "status");
    bar.setAttribute("aria-label", t("操作处理中"));
    bar.setAttribute("aria-hidden", "true");
    document.body.appendChild(bar);
  }
  if (bar) {
    bar.classList.add("active");
    bar.setAttribute("aria-hidden", "false");
  }

  let btn = opts && opts.busyElement;
  if (typeof btn === "string") btn = document.querySelector(btn);
  if (!btn && performance.now() - _lastActionAt < 2000) btn = _lastActionButton;
  if (!btn || !document.documentElement.contains(btn)) btn = null;
  if (btn) {
    let state = _requestBusyButtons.get(btn);
    if (!state) {
      state = {
        count: 0,
        ariaBusy: btn.getAttribute("aria-busy"),
        ariaDisabled: btn.getAttribute("aria-disabled"),
      };
      _requestBusyButtons.set(btn, state);
    }
    state.count++;
    btn.classList.add("request-busy");
    btn.setAttribute("aria-busy", "true");
    btn.setAttribute("aria-disabled", "true");
  }
  return { button: btn };
}

function requestBusyEnd(token) {
  if (!token) return;
  _requestBusyCount = Math.max(0, _requestBusyCount - 1);
  const btn = token.button;
  const state = btn && _requestBusyButtons.get(btn);
  if (state) {
    state.count--;
    if (state.count <= 0) {
      btn.classList.remove("request-busy");
      if (state.ariaBusy === null) btn.removeAttribute("aria-busy");
      else btn.setAttribute("aria-busy", state.ariaBusy);
      if (state.ariaDisabled === null) btn.removeAttribute("aria-disabled");
      else btn.setAttribute("aria-disabled", state.ariaDisabled);
      _requestBusyButtons.delete(btn);
    }
  }
  if (_requestBusyCount === 0) {
    const bar = $("request-progress");
    if (bar) {
      bar.classList.remove("active");
      bar.setAttribute("aria-hidden", "true");
    }
  }
}

async function api(path, opts) {
  opts = opts || {};
  const onResponse = typeof opts.onResponse === "function" ? opts.onResponse : null;
  // 可选超时：长请求（如外部插件下载）传 opts.timeout，网络卡死时也能
  // 按时给出错误反馈，而不是无限静默
  let ctrl = null;
  if (opts.timeout) {
    ctrl = new AbortController();
    var timer = setTimeout(() => ctrl.abort(), opts.timeout);
  }
  const busyToken = requestBusyStart(opts);
  const operationToken = operationStart(path, opts);
  const fetchOpts = Object.assign({}, opts);
  delete fetchOpts.timeout;
  delete fetchOpts.busy;
  delete fetchOpts.busyElement;
  delete fetchOpts.operation;
  delete fetchOpts._ctrlRetry;
  delete fetchOpts.onResponse;
  try {
    let res;
    try {
      res = await fetch(path, Object.assign({ headers: authHeaders() }, fetchOpts,
        ctrl ? { signal: ctrl.signal } : {}));
    } catch (e) {
      if (ctrl && e.name === "AbortError") throw new Error(t("请求超时，请重试或检查网络"));
      throw e;
    }
    if (res.status === 304) {
      // Conditional requests still need to expose the status to callers.
      // In particular, a phone relay may return a stale 304 before the
      // browser has received its first snapshot; refreshState can then make
      // one safe unconditional retry instead of leaving the UI blank.
      if (onResponse) onResponse(res);
      operationFinish(operationToken, "done");
      return null;
    }
    // D2（三轮审查）：不再静默吞解析失败。先取原文，非 JSON 声明或空体保底 null，
    // 声明 JSON 却解析失败则在 2xx 时显式抛错，让调用方不再对 null 解构被静默吞掉。
    let data = null;
    const rawText = await res.text();
    if (rawText.trim().length) {
      const ct = res.headers && res.headers.get ? res.headers.get("content-type") : "";
      const looksJson = ct && ct.toLowerCase().indexOf("application/json") !== -1;
      if (looksJson) {
        try { data = JSON.parse(rawText); }
        catch (e) {
          if (res.ok) {
            const err = new Error(t("服务器响应格式异常（非预期 JSON）"));
            err.status = res.status;
            err.data = rawText.slice(0, 200);
            throw err;
          }
          // 非 2xx 且体非 JSON（隧道/反代 502 HTML 页等）：保留 null，下方用状态码兜底
        }
      }
    }
    // Only let callers cache response metadata after a successful body read/parse.
    // A truncated mobile response must not pin the client to an unusable ETag.
    if (onResponse && res.ok) onResponse(res);
    if (res.status === 401) {
      const authError = (data && data.error) || (res.statusText ? (res.status + " " + res.statusText) : "HTTP 401");
      // The phone relay also uses 401 for an expired/unpaired phone session.
      // Only explicit local access-token failures should open the desktop token
      // gate. Do not infer that every unknown 401 means the desktop token is bad:
      // relay wording can vary by pairing, expiry, or future edge responses.
      const isDesktopTokenError = /需要访问令牌|令牌(?:不正确|不匹配)|invalid or revoked token/i.test(authError);
      if (isDesktopTokenError) {
        showTokenGate(t("令牌不正确或已更换，请重新输入"));
        throw new Error(t("需要访问令牌"));
      }
      const failure = new Error(authError);
      failure.status = res.status;
      failure.data = data;
      throw failure;
    }
    if (res.status === 423 && data && data.control) {
      setControl(data.control);
      // 手机端接管闭环（用户实测反馈：423 连点全失败不知道怎么办）：
      // 他人持有时弹「接管并重试」确认，确认后抢夺控制权并自动重试一次。
      // uiConfirm 弹窗互斥防堆叠；重试标记防递归；GET 轮询不会走到这里。
      const holder = data.control.holder || "";
      // 30s 节流：弹框未关时 _ctrlPrompting 互斥已挡并发，但关框后紧跟着的
      // 自动写请求会连环撞 423 连环弹（实测一轮页面循环 5927 次），只留一次打断。
      if (!opts._ctrlRetry && !opts.silent && !api._ctrlPrompting && holder
          && Date.now() - (api._ctrlPromptAt || 0) > 30000) {
        api._ctrlPromptAt = Date.now();
        api._ctrlPrompting = true;
        try {
          if (await uiConfirm(t("「{0}」正在控制，接管后自动重试「{1}」？",
            holder, operationLabel(path, { ...opts, operation: true }) || t("提交操作")),
            { ok: t("接管并重试") })) {
            const acquired = await ctrlAction("acquire", true, true);
            api._ctrlPrompting = false;
            if (acquired) {
              return api(path, Object.assign({}, opts, { _ctrlRetry: true }));
            }
            throw new Error(t("接管控制权失败，请点击右上角锁图标接管后重试"));
          }
        } finally {
          api._ctrlPrompting = false;
        }
      }
    }
    if (!res.ok) {
      let msg = (data && data.error) || "";
      // 错误体非 JSON（反代 502/504 HTML 页）时带 statusText，至少比裸「HTTP 502」多信息
      if (!msg) msg = res.statusText ? (res.status + " " + res.statusText) : ("HTTP " + res.status);
      const failure = new Error(msg);
      failure.status = res.status;
      failure.data = data;
      throw failure;
    }
    const method = String(fetchOpts.method || "GET").toUpperCase();
    if (method !== "GET") {
      if (String(path).startsWith("/api/catalog/")) S._catalogLoaded = false;
      if (String(path).startsWith("/api/models/")) S._modelsLoaded = false;
    }
    operationFinish(operationToken, "done");
    return data;
  } catch (e) {
    operationFinish(operationToken, "failed", e && e.message ? e.message : e);
    throw e;
  } finally {
    if (timer) clearTimeout(timer);
    requestBusyEnd(busyToken);
  }
}

/* 质量门禁三选一弹框（替代原生 confirm 的单一「强制放行」出口）：
 * 取消 / ↻ 重新评审 / 强制放行。「重新评审」= 重写未达标章再评（语义同详情页
 * 「↻ 重写未达标章」按钮，走 retry 的未达标分支），仅 serial 任务才给；任务
 * 运行/排队中按钮置灰（后端 retry 会拒），但必须显出来并写明出路——正在跑的
 * 这轮结束后再来发布，仍不达标时按钮即可点；无声藏按钮用户只会看到死路。
 * 返回 "review" | "force" | null(取消)。 */
async function pbGateChoice(err, promptText, taskId) {
  const tk = ((S.state || {}).tasks || []).find((x) => x.id === taskId);
  const busy = !!(tk && (tk.status === "running" || tk.status === "queued"));
  const canReview = !!(tk && tk.serial && !busy);
  const resumeAt = busy
    ? ((((S.state || {}).task_latest || {})[taskId] || {}).resume_enqueue_at || "") : "";
  const busyHint = (tk && tk.serial && busy)
    ? (resumeAt
        ? t("任务正在运行/排队中，预计 {0} 自动续跑，暂不能重复发起评审；等这轮跑完再来点发布——若质量仍不达标，这里就能点「重新评审」（只重写未达标章）。",
            String(resumeAt).slice(11, 16))
        : t("任务正在运行/排队中，暂不能重复发起评审；等这轮跑完再来点发布——若质量仍不达标，这里就能点「重新评审」（只重写未达标章）。"))
    : "";
  const msg = (promptText || t("质量门禁未通过")) + "\n\n" + ((err && err.message) || "");
  const v = await _askOpen({
    title: t("质量门禁未通过"),
    bodyHtml: '<div class="ask-msg">' + esc(msg) + "</div>" +
      (canReview ? '<div class="ask-msg">' +
        esc(t("「重新评审」只重写未达标章节并重新评审（已过线章节沿用成稿与评分），跑完后再来发布。")) + "</div>" : "") +
      (busyHint ? '<div class="ask-msg">' + esc(busyHint) + "</div>" : ""),
    okText: t("强制放行…"),
    extra: (tk && tk.serial)
      ? [{ text: "↻ " + t("重新评审"), value: "review", disabled: busy,
           title: busy ? t("任务运行/排队中，暂不能发起；等这轮跑完再试") : "" }]
      : [],
    onOpen: () => $("ask-yes").focus(),
  });
  return v === "review" ? "review" : (v === true ? "force" : null);
}

async function pbApiWithQualityOverride(path, body, prompt, taskId) {
  try {
    return await api(path, { method: "POST", body: JSON.stringify(body) });
  } catch (e) {
    const gate = e && e.data && e.data.quality_gate;
    if (!gate) throw e;
    // Automatic publishing is the product default.  A quality gate must be
    // audited, but it must never turn a background publish into a manual
    // prompt.  The server validates the same hard guards and records this
    // deterministic reason in the publish ledger.
    const reason = "用户已启用全自动发布；系统按平台校准流程自动提交";
    return await api(path, { method: "POST", body: JSON.stringify({ ...body,
      auto_submit: body.auto_submit === false ? false : true,
      force: true, force_confirmed: true, force_reason: reason }) });
  }
}

/* 轻提示：3.5s 自动消失 */
function toast(msg, bad) {
  let el = $("toast");
  if (!el) {
    el = document.createElement("div");
    el.id = "toast";
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.className = "toast show" + (bad ? " bad" : "");
  clearTimeout(toast._t);
  toast._t = setTimeout(() => { el.className = "toast"; }, 3500);
}

/* ------------------------------------------------ 应用内确认 / 输入弹框
 * 替代浏览器原生 confirm/prompt（原生框与应用视觉完全脱节）。
 * uiConfirm(msg, {ok, danger, title}) → Promise<boolean>
 * uiPrompt(title, value)               → Promise<string|null>（取消为 null）
 * 可叠在 #modal 之上（z-index 250 > 200）；Esc=取消、Enter=确定。
 */
let _askResolve = null;

function _askClose(v) {
  if (!_askResolve) return;
  const r = _askResolve;
  _askResolve = null;
  $("ask").classList.add("hidden");
  document.body.classList.remove("ask-open");
  r(v);
}

function _askOpen(opts) {
  if (_askResolve) _askClose(false);   // 上一帧未关：先收掉，避免悬挂 Promise
  return new Promise((resolve) => {
    _askResolve = resolve;
    $("ask-title").textContent = opts.title || t("确认");
    $("ask-body").innerHTML = opts.bodyHtml || "";
    // 三态弹框：extra 按钮插在「取消」左侧，点按以 opts 里的 value 结束
    // （非布尔，只有用到 extra 的调用方需要判读）；开新框先清上一帧残留。
    const yes = $("ask-yes");
    const no = $("ask-no");
    const foot = yes.parentNode;
    foot.querySelectorAll(".ask-extra").forEach((b) => b.remove());
    (opts.extra || []).forEach((b) => {
      const el = document.createElement("button");
      el.className = (b.cls || "ghost") + " ask-extra";
      el.textContent = b.text;
      el.disabled = !!b.disabled;   // 置灰态：看得见点不了（配合 title 说明原因）
      if (b.title) el.title = b.title;
      el.addEventListener("click", () => _askClose(b.value));
      foot.insertBefore(el, $("ask-no"));
    });
    yes.textContent = opts.okText || t("确定");
    yes.className = opts.danger ? "danger" : "primary";
    no.textContent = opts.noText || t("取消");
    $("ask").classList.remove("hidden");
    document.body.classList.add("ask-open");
    if (opts.onOpen) opts.onOpen();
  });
}

function uiConfirm(message, opts) {
  opts = opts || {};
  return _askOpen({
    title: opts.title || t("确认操作"),
    bodyHtml: '<div class="ask-msg">' + esc(message) + "</div>",
    okText: opts.ok, danger: opts.danger,
    onOpen: () => $("ask-yes").focus(),
  });
}

function uiPrompt(title, value) {
  let inp = null;
  return _askOpen({
    title: title,
    bodyHtml: '<input type="text" class="ask-input" id="ask-input" autocomplete="off">',
    okText: t("确定"),
    onOpen: () => {
      inp = $("ask-input");
      inp.value = value || "";
      inp.focus();
      inp.select();
    },
  }).then((ok) => ((ok && inp) ? inp.value.trim() : null));
}

// 供独立的 UI 模块（例如 mobile-workbench.js）复用统一弹框，避免模块
// 各自退回浏览器原生 confirm/prompt，造成视觉和交互不一致。
window.uiConfirm = uiConfirm;
window.uiPrompt = uiPrompt;

/* 访问令牌门（仅远程设备会碰到） */
function showTokenGate(err) {
  const g = $("token-gate");
  if (!g) return;
  if (err) $("gate-err").textContent = err;
  g.classList.remove("hidden");
  setTimeout(() => $("gate-token").focus(), 50);
}

function submitToken() {
  const v = $("gate-token").value.trim();
  if (!v) return;
  localStorage.setItem("orch.token", v);
  location.reload();
}

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

/* 密钥形态识别（A1，dsh 0.2.1「已发送消息密钥默认脱敏按需查看」借鉴）。
 * 与后端 redact._KEY_PATTERNS 同族，但只收「高置信前缀形态」——裸 40 位
 * hex（git sha1）在日志里大量合法出现，不进显示侧名单。 */
const SECRET_MATCHERS = [
  /\bsk-[A-Za-z0-9_-]{8,}/g,
  /\bghp_[A-Za-z0-9]{16,}/g, /\bgho_[A-Za-z0-9]{16,}/g, /\bghu_[A-Za-z0-9]{16,}/g,
  /\bgithub_pat_[A-Za-z0-9_]{20,}/g,
  /\bxox[bpars]-[A-Za-z0-9-]{10,}/g,
  /\bAKIA[0-9A-Z]{16}\b/g,
  /\beyJ[A-Za-z0-9_-]{16,}\.eyJ[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{8,}\b/g,
  /(?:api[_-]?key|apikey|access[_-]?token|auth[_-]?token|secret[_-]?key|password|passwd|pwd)["']?\s*[:=，：]\s*["']?[A-Za-z0-9._~+/=-]{16,}/gi,
];

/* DOM 后处理：遍历文本节点，命中密钥形态的片段换成 .sec-mask（默认打码，
 * 点击切换明暗）。放在 innerHTML 之后跑，覆盖用户气泡/助手正文/思考块/
 * CLI 日志 pre 全部表面——渲染器（markdown-lite/纯转义）不用各自改。 */
function maskSecretsInDOM(root) {
  if (!root || !root.createTreeWalker) return;
  const hits = [];
  try {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const v = node.nodeValue;
        if (!v || v.length < 8) return NodeFilter.FILTER_REJECT;
        const p = node.parentNode;
        if (!p || /^(script|style|textarea|input)$/i.test(p.nodeName)) return NodeFilter.FILTER_REJECT;
        if (p.closest && (p.closest(".sec-mask") || p.closest("[data-no-secmask]"))) return NodeFilter.FILTER_REJECT;
        return SECRET_MATCHERS.some((re) => { re.lastIndex = 0; return re.test(v); })
          ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
      },
    });
    let n;
    while ((n = walker.nextNode())) hits.push(n);
  } catch (e) { return; }
  hits.forEach((node) => {
    const text = node.nodeValue;
    const found = [];
    SECRET_MATCHERS.forEach((re) => {
      re.lastIndex = 0;
      let m;
      while ((m = re.exec(text)) && m[0]) found.push([m.index, m.index + m[0].length]);
    });
    if (!found.length) return;
    found.sort((a, b) => a[0] - b[0]);
    const merged = [];
    found.forEach(([s, e]) => {
      if (!merged.length || s > merged[merged.length - 1][1]) merged.push([s, e]);
    });
    const frag = document.createDocumentFragment();
    let last = 0;
    merged.forEach(([s, e]) => {
      if (s > last) frag.appendChild(document.createTextNode(text.slice(last, s)));
      const span = document.createElement("span");
      span.className = "sec-mask";
      try { span.dataset.sec = btoa(unescape(encodeURIComponent(text.slice(s, e)))); }
      catch (err) { span.dataset.sec = ""; }
      span.textContent = "•••" + t("密钥") + "•••";
      frag.appendChild(span);
      last = e;
    });
    if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
    if (node.parentNode) node.parentNode.replaceChild(frag, node);
  });
}

/* 打码片段点击切换明暗（事件委托：时间线整块重建不丢监听）。 */
document.addEventListener("click", (e) => {
  const el = e.target.closest ? e.target.closest(".sec-mask") : null;
  if (!el) return;
  if (el.classList.toggle("revealed")) {
    let plain = "";
    try { plain = decodeURIComponent(escape(atob(el.dataset.sec || ""))); } catch (err) { plain = ""; }
    el.dataset.masked = el.textContent;
    el.textContent = plain || "?";
    el.title = t("点击隐藏");
  } else {
    el.textContent = el.dataset.masked || ("•••" + t("密钥") + "•••");
    el.title = t("已打码；点击查看明文");
  }
});

/* 内联 onclick 里的字符串字面量转义。esc 不够用：它把 ' 编成 &#39;，浏览器
 * 解码属性值后 JS 仍看到一个裸引号，用户自建标签含撇号就会截断字面量
 * （语法错误或参数错位）。这里先做 HTML 属性转义再叠 JS 转义。
 * 换行与 U+2028/U+2029 也要转：它们在 JS 字符串字面量里是硬性行终止符，
 * 上游返回的模型名一旦带换行，整个 handler 会变成语法错误（点了没反应）。 */
function jsq(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/"/g, "&quot;")
    .replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/\\/g, "\\\\").replace(/'/g, "\\'")
    .replace(/\r/g, "\\r").replace(/\n/g, "\\n")
    .replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
}

function statusChip(st) {
  const zh = { queued: t("排队中"), running: t("运行中"), done: t("完成"), failed: t("失败"), cancelled: t("已取消"), timeout: t("超时") };
  return '<span class="chip ' + esc(st) + '">' + (zh[st] || esc(st)) + "</span>";
}

/* 运行状态文案（传 run 对象）：退避窗口内的续跑副本写明「将于 HH:MM 自动
 * 续跑」，别让 5 分钟等待看起来像卡死/资源排队（2026-09-18 重写任务误判案）。
 * 到点后翻回「排队中」——页面轮询重渲染时 Date.now() 已过预定时刻。 */
function runStatusText(run) {
  const st = String((run && run.status) || "");
  if (st === "queued" && run && run.resume_enqueue_at) {
    const at = Date.parse(String(run.resume_enqueue_at).replace(" ", "T"));
    if (!isNaN(at) && Date.now() < at)
      return t("将于 {0} 自动续跑", String(run.resume_enqueue_at).slice(11, 16));
  }
  const txt = { queued: t("排队中"), running: t("运行中"), done: t("完成"),
    failed: t("失败"), cancelled: t("已取消"), timeout: t("超时") }[st] || st;
  if ((st === "queued" || st === "running") && run && run.paused) {
    return run.pause_phase === "paused"
      ? t("已到达暂停点·等待放行")
      : t("暂停请求已接收·当前步骤完成后挂起");
  }
  // 「跑完」≠「通过」：done 但评审未过（verdict.pass=false）必须一眼可辨——
  // 此前一律显示「完成」，用户以为修好了（2026-09-23 禅道双单实案反馈）
  if (st === "done" && run && run.verdict && run.verdict.pass === false)
    return txt + t("·未达标");
  return txt;
}

/* 运行错误来源徽标：错误文案以「超时」打头（runner 统一格式）时标 TIMEOUT，
 * 和普通失败一眼区分；运行状态仍是 failed，不动状态机 */
function errTag(err) {
  return /^超时/.test(err || "") ? '<b class="err-tag">TIMEOUT</b>' : "";
}

function runKindTag(k) {
  return k === "mgmt" ? '<span class="tag">' + t("管理") + '</span>' : '<span class="tag">' + t("编排") + '</span>';
}

/* 供应商来源标签：手动添加的不打标，其余按来源 id → 显示名映射 */
function srcTag(source) {
  if (!source || source === "manual") return "";
  const name = (S.sourceNames || {})[source] || source;
  return '<span class="tag">' + esc(name) + "</span>";
}

/* 可注入 CLI 的供应商：显式 anthropic/openai，或 auto 但实测出过 wire
 * （wire_caps）。google 与「auto 且还没探测」的仅登记。 */
function bindableProvs(provs) {
  return (provs || []).filter((p) => p.protocol === "anthropic" || p.protocol === "openai" ||
    (p.wire_caps || {}).anthropic || (p.wire_caps || {}).openai);
}

/* ---------------------------------------------------------- 通用弹框 */
let _pbReturnFocus = null;
function openModal(title, bodyHtml, footHtml) {
  _pbReturnFocus = null;
  delete $("modal").dataset.pbKey;
  $("modal").classList.remove("pb-selection-modal");
  $("modal-title").textContent = title;
  $("modal-body").innerHTML = bodyHtml || "";
  $("modal-foot").innerHTML = footHtml || "";
  $("modal").classList.remove("hidden");
  document.body.classList.add("modal-open");
}

function closeModal() {
  const m = $("modal");
  if (!m) return;
  m.classList.add("hidden");
  delete m.dataset.pbKey;
  m.classList.remove("pb-selection-modal");
  $("modal-body").innerHTML = "";
  $("modal-foot").innerHTML = "";
  document.body.classList.remove("modal-open");
  if (_pbReturnFocus && _pbReturnFocus.isConnected) _pbReturnFocus.focus();
  _pbReturnFocus = null;
}

/* ---------------------------------------------------------- 人工评审队列 */
const REVIEW_QUEUE = { rows: [], loaded: false, loading: 0, saving: false };
const REVIEW_LABELS = { requested: t("待分配"), assigned: t("评审中"), approved: t("已批准"),
  changes_requested: t("要求修改"), dismissed: t("已关闭"), expired: t("已过期") };

function reviewActions(status) {
  if (status === "requested") return ["assign", "dismiss", "expire"];
  if (status === "assigned") return ["approve", "changes_requested", "dismiss", "expire"];
  if (status === "changes_requested") return ["dismiss", "expire"];
  return [];
}

function reviewActionLabel(action) {
  return t(({ assign: t("分配评审人"), approve: t("批准评审"), changes_requested: t("要求修改"),
    dismiss: t("关闭请求"), expire: t("标记过期") })[action] || action);
}

function renderReviewQueue() {
  const list = $("review-queue-list");
  if (!list) return;
  const filter = $("review-queue-filter").value;
  const rows = REVIEW_QUEUE.rows.filter((row) => filter === "all" ||
    (filter === "active" ? reviewActions(row.status).length > 0 : row.status === filter))
    .sort((a, b) => Number(b.updated_at || 0) - Number(a.updated_at || 0));
  $("review-queue-count").textContent = t("显示 {0} / {1} 条", rows.length, REVIEW_QUEUE.rows.length);
  list.innerHTML = rows.map((row) => {
    const stamp = new Date(Number(row.updated_at || 0) * 1000);
    const time = Number.isFinite(stamp.getTime()) ? stamp.toLocaleString(getLang() === "en" ? "en-US" : "zh-CN") : "";
    return '<article class="review-request"><div class="review-request-head"><strong>' +
      esc(row.summary || t("未填写评审摘要")) + '</strong><span class="tag ' +
      (row.status === "approved" ? "ok" : row.status === "changes_requested" ? "warn" : "") + '">' +
      esc(t(REVIEW_LABELS[row.status] || row.status)) + '</span></div><div class="review-request-meta">' +
      '<span>' + esc(t("运行 ID")) + ': <code>' + esc(row.run_id) + '</code></span>' +
      (row.channel ? '<span>' + esc(t("评审渠道")) + ': ' + esc(row.channel) + '</span>' : "") +
      (row.reviewer ? '<span>' + esc(t("评审人")) + ': ' + esc(row.reviewer) + '</span>' : "") +
      '<time>' + esc(time) + '</time></div>' +
      (Array.isArray(row.paths) && row.paths.length ? '<div class="review-request-paths">' +
        row.paths.map((path) => '<code>' + esc(path) + '</code>').join("") + '</div>' : "") +
      (row.reason ? '<p class="review-request-reason">' + esc(row.reason) + '</p>' : "") +
      '<div class="actions">' + reviewActions(row.status).map((action) =>
        '<button type="button" class="ghost small" data-review-id="' + esc(row.id) +
        '" data-review-action="' + action + '">' + esc(reviewActionLabel(action)) + '</button>').join("") +
      '</div></article>';
  }).join("") || '<p class="hint">' + esc(t(REVIEW_QUEUE.loaded ? t("暂无匹配的评审请求") : t("正在加载评审请求…"))) + '</p>';
  list.onclick = (event) => {
    const button = event.target.closest("[data-review-action]");
    if (button && list.contains(button)) openReviewTransition(button.dataset.reviewId, button.dataset.reviewAction);
  };
}

async function loadReviewQueue() {
  const list = $("review-queue-list"), message = $("review-queue-message");
  if (!list || !message) return;
  const token = ++REVIEW_QUEUE.loading;
  list.setAttribute("aria-busy", "true");
  message.textContent = t("正在加载评审请求…");
  if (!REVIEW_QUEUE.loaded) renderReviewQueue();
  try {
    const data = await api("/api/reviews", { timeout: 15000 });
    if (token !== REVIEW_QUEUE.loading) return;
    if (!Array.isArray(data.reviews)) throw new Error(t("评审数据格式不正确"));
    REVIEW_QUEUE.rows = data.reviews;
    REVIEW_QUEUE.loaded = true;
    message.textContent = "";
    renderReviewQueue();
  } catch (e) {
    if (token === REVIEW_QUEUE.loading) message.textContent = t("评审队列加载失败：") + e.message;
  } finally {
    if (token === REVIEW_QUEUE.loading) list.setAttribute("aria-busy", "false");
  }
}

/* ---------------- 第二批运营面板：评审策略 / HITL / CLI 能力 / 指标 ---------------- */
function reviewPolicyDimensions() {
  return (UI_FEATURES.reviewPolicy && UI_FEATURES.reviewPolicy.dimensions) || [];
}

function renderReviewPolicy() {
  const rows = reviewPolicyDimensions();
  const box = $("review-policy-dimensions");
  if (!box) return;
  box.innerHTML = rows.map((row, index) =>
    '<div class="review-policy-row" data-index="' + index + '">' +
    '<input class="review-dim-name" aria-label="' + esc(t("评审维度名称")) + '" value="' + esc(row.name || row.id || "") + '" maxlength="80">' +
    '<input class="review-dim-weight" aria-label="' + esc(t("评审维度权重")) + '" type="number" min="0.01" max="100" step="0.1" value="' + esc(String(row.weight == null ? 1 : row.weight)) + '">' +
    '<button type="button" class="ghost small" data-remove-review-dim="' + index + '" aria-label="' + esc(t("删除维度")) + '">×</button></div>').join("") ||
    '<p class="hint">' + esc(t("暂无评审维度")) + '</p>';
  box.insertAdjacentHTML("beforeend", '<button type="button" class="ghost small" id="review-add-dimension" data-i18n="新增维度">＋ ' + esc(t("新增维度")) + '</button>');
  box.querySelectorAll("[data-remove-review-dim]").forEach((button) => button.addEventListener("click", () => {
    const index = Number(button.dataset.removeReviewDim);
    const next = reviewPolicyDimensions().filter((_, i) => i !== index);
    UI_FEATURES.reviewPolicy.dimensions = next.length ? next : [{ id: "custom", name: t("新维度"), weight: 1 }];
    renderReviewPolicy();
  }));
  const add = $("review-add-dimension");
  if (add) add.onclick = () => {
    UI_FEATURES.reviewPolicy.dimensions = reviewPolicyDimensions().concat([{ id: "custom-" + Date.now(), name: t("新维度"), weight: 1 }]);
    renderReviewPolicy();
  };
  const policy = UI_FEATURES.reviewPolicy || {};
  if ($("review-min-score")) $("review-min-score").value = policy.min_score == null ? 7 : policy.min_score;
  if ($("review-min-confidence")) $("review-min-confidence").value = policy.min_confidence == null ? 0 : policy.min_confidence;
  if ($("review-min-family")) $("review-min-family").value = policy.min_model_family || "";
}

async function loadReviewPolicy() {
  const message = $("review-policy-message");
  try {
    UI_FEATURES.reviewPolicy = await api("/api/review-policy", { timeout: 15000 });
    renderReviewPolicy();
    if (message) message.textContent = "";
  } catch (error) { if (message) message.textContent = t("评审策略加载失败：") + error.message; }
}

async function saveReviewPolicy() {
  const message = $("review-policy-message");
  const dimensions = Array.from(document.querySelectorAll("#review-policy-dimensions .review-policy-row")).map((row) => {
    const name = (row.querySelector(".review-dim-name") || {}).value || "";
    const weight = Number((row.querySelector(".review-dim-weight") || {}).value || 1);
    return { id: name.trim().toLowerCase().replace(/\s+/g, "-").slice(0, 60), name: name.trim(), weight };
  }).filter((row) => row.name);
  try {
    const result = await api("/api/review-policy", { method: "POST", body: JSON.stringify({
      dimensions, min_score: Number($("review-min-score").value),
      min_confidence: Number($("review-min-confidence").value), min_model_family: $("review-min-family").value.trim() }) });
    UI_FEATURES.reviewPolicy = result.policy || result;
    renderReviewPolicy();
    if (message) { message.className = "msg ok"; message.textContent = t("评审策略已保存"); }
  } catch (error) { if (message) { message.className = "msg err"; message.textContent = t("保存失败：") + error.message; } }
}

function renderInterventions() {
  const box = $("hitl-list");
  if (!box) return;
  const rows = UI_FEATURES.interventions || [];
  box.innerHTML = rows.length ? rows.map((row) =>
    '<article class="hitl-row"><div><strong>' + esc(row.point || t("人工确认")) + '</strong><span class="chip warn">' + esc(t("等待人工确认")) + '</span>' +
    '<div class="hint">' + esc(t("运行 ID")) + ': <code>' + esc(row.run_id || "") + '</code></div>' +
    (row.payload && row.payload.summary ? '<p>' + esc(row.payload.summary) + '</p>' : '') + '</div><div class="actions">' +
    '<button type="button" class="primary small" data-hitl-action="approve" data-hitl-id="' + esc(row.id) + '">' + esc(t("批准继续")) + '</button>' +
    '<button type="button" class="danger small" data-hitl-action="reject" data-hitl-id="' + esc(row.id) + '">' + esc(t("拒绝")) + '</button></div></article>').join("") :
    '<p class="hint">' + esc(t("暂无待确认介入")) + '</p>';
  box.onclick = async (event) => {
    const button = event.target.closest("[data-hitl-action]");
    if (!button) return;
    button.disabled = true;
    try { await api("/api/interventions/" + encodeURIComponent(button.dataset.hitlId) + "/decide", { method: "POST", body: JSON.stringify({ action: button.dataset.hitlAction }) }); await loadInterventions(); }
    catch (error) { toast(t("人工确认失败：") + error.message, true); button.disabled = false; }
  };
}

async function loadInterventions() {
  try { const result = await api("/api/interventions", { timeout: 15000 }); UI_FEATURES.interventions = result.requests || []; renderInterventions(); }
  catch (error) { const box = $("hitl-list"); if (box) box.innerHTML = '<p class="hint bad">' + esc(t("介入请求加载失败：") + error.message) + '</p>'; }
}

function renderCliDiscovery() {
  const box = $("cli-discovery-list");
  if (!box) return;
  const rows = UI_FEATURES.cliDiscovery || [];
  box.innerHTML = rows.length ? rows.map((row) => {
    // 慢 ≠ 坏：版本命令没在预算内回来时后端标 slow，界面用「响应慢」而不是
    // 「探测异常」——冷启动的 CLI 只是慢，派发照样能用。
    const state = row.slow ? "slow" : (row.error ? "bad" : (row.available ? "ok" : "off"));
    const chipCls = state === "ok" ? "done" : (state === "slow" ? "warn" : "failed");
    const label = state === "ok" ? t("可用") : state === "slow" ? t("响应慢")
      : state === "bad" ? t("探测异常") : t("未检测到");
    return '<div class="cli-discovery-row"><strong>' + esc(row.name || row.executable || "CLI") + '</strong><span class="chip ' + chipCls + '">' + esc(label) + '</span>' +
      '<span class="mono">' + esc(row.version || row.path || "") + '</span><span class="hint">' + esc((row.supports_stdin ? "stdin · " : "") + (row.output_format || "text")) + '</span>' +
      (row.error ? '<small class="hint' + (row.slow ? "" : " bad") + '">' + esc(row.error) + '</small>' : '') +
      (!row.available && row.install_hint ? '<small class="hint">' + esc(row.install_hint) + '</small>' : '') + '</div>';
  }).join("") : '<p class="hint">' + esc(t("尚无能力探测结果")) + '</p>';
}

async function loadCliDiscovery(force) {
  const box = $("cli-discovery-list");
  if (box && force) box.innerHTML = '<p class="hint">' + esc(t("正在探测…")) + '</p>';
  try {
    const result = force
      ? await api("/api/cli-discovery", { method: "POST", timeout: 45000, body: JSON.stringify({}) })
      : await api("/api/cli-discovery", { timeout: 15000 });
    UI_FEATURES.cliDiscovery = result.clis || [];
    renderCliDiscovery();
  }
  catch (error) { if (box) box.innerHTML = '<p class="hint bad">' + esc(t("CLI 能力加载失败：") + error.message) + '</p>'; }
}

async function generateAdapterScaffold() {
  const message = $("scaffold-message"), resultBox = $("scaffold-result");
  try {
    const result = await api("/api/scaffold-adapter", { method: "POST", body: JSON.stringify({
      name: $("scaffold-name").value.trim(), executable: $("scaffold-executable").value.trim(),
      invocation: $("scaffold-invocation").value.trim(), output_format: $("scaffold-output-format").value.trim() }) });
    if (resultBox) { resultBox.textContent = JSON.stringify(result, null, 2); resultBox.classList.remove("hidden"); }
    if (message) { message.className = "msg ok"; message.textContent = t("脚手架已生成，请按提示补充实现"); }
  } catch (error) { if (message) { message.className = "msg err"; message.textContent = t("脚手架生成失败：") + error.message; } }
}

function openReviewRequest() {
  if (REVIEW_QUEUE.saving) return;
  const runs = ((S.state || {}).runs || []).slice(0, 100);
  openModal(t("新建评审请求"), '<form id="review-request-form" class="form">' +
    '<div class="field"><label for="review-run-id">' + esc(t("运行 ID")) + ' *</label>' +
    '<input id="review-run-id" list="review-run-options" required maxlength="100" autocomplete="off">' +
    '<datalist id="review-run-options">' + runs.map((run) => '<option value="' + esc(run.id) + '">' +
      esc(run.goal || run.task_id || run.id) + '</option>').join("") + '</datalist></div>' +
    '<div class="field"><label for="review-summary">' + esc(t("评审摘要")) + '</label>' +
    '<textarea id="review-summary" rows="3" maxlength="1000"></textarea></div>' +
    '<div class="field"><label for="review-paths">' + esc(t("待评审文件（每行一个路径）")) + '</label>' +
    '<textarea id="review-paths" rows="3"></textarea></div>' +
    '<div class="field"><label for="review-channel">' + esc(t("评审渠道")) + '</label>' +
    '<input id="review-channel" maxlength="200"></div>' +
    '<p id="review-form-message" class="hint" role="status" aria-live="polite"></p></form>',
    '<button type="button" class="ghost" onclick="closeModal()">' + esc(t("取消")) + '</button>' +
    '<button id="review-save" type="submit" form="review-request-form" class="primary">' + esc(t("创建请求")) + '</button>');
  $("review-request-form").onsubmit = (event) => { event.preventDefault(); saveReviewRequest(); };
  $("review-run-id").value = S.detailRunId || "";
  $("review-run-id").focus();
}

function openReviewTransition(id, action) {
  if (REVIEW_QUEUE.saving) return;
  const row = REVIEW_QUEUE.rows.find((item) => item.id === id);
  if (!row || !reviewActions(row.status).includes(action)) return;
  const assigning = action === "assign", needsReason = action === "changes_requested";
  openModal(reviewActionLabel(action), '<form id="review-transition-form" class="form">' +
    '<p class="hint">' + esc(row.summary || row.run_id) + '</p>' +
    '<div class="field"><label for="review-reviewer">' + esc(t("评审人")) + (assigning ? ' *' : '') + '</label>' +
    '<input id="review-reviewer" maxlength="200" value="' + esc(row.reviewer || "") + '"' +
    (assigning ? ' required' : '') + '></div>' +
    '<div class="field"><label for="review-reason">' + esc(t("处理意见")) + (needsReason ? ' *' : '') + '</label>' +
    '<textarea id="review-reason" rows="4" maxlength="1000"' + (needsReason ? ' required' : '') + '></textarea></div>' +
    '<p id="review-form-message" class="hint" role="status" aria-live="polite"></p></form>',
    '<button type="button" class="ghost" onclick="closeModal()">' + esc(t("取消")) + '</button>' +
    '<button id="review-save" type="submit" form="review-transition-form" class="primary">' + esc(reviewActionLabel(action)) + '</button>');
  $("review-transition-form").onsubmit = (event) => { event.preventDefault(); saveReviewTransition(id, action); };
  $(assigning ? "review-reviewer" : "review-reason").focus();
}

async function reviewQueueSave(path, body) {
  if (REVIEW_QUEUE.saving) return;
  const button = $("review-save"), form = $("review-request-form") || $("review-transition-form");
  const message = $("review-form-message");
  REVIEW_QUEUE.saving = true;
  button.disabled = true;
  message.textContent = t("正在保存…");
  try {
    await api(path, { method: "POST", body: JSON.stringify(body), timeout: 15000 });
    if (form.isConnected) closeModal();
    toast(t("评审请求已保存"));
    await loadReviewQueue();
  } catch (e) {
    if (message.isConnected) message.textContent = t("评审请求保存失败：") + e.message;
    else toast(t("评审请求保存失败：") + e.message, true);
  } finally {
    REVIEW_QUEUE.saving = false;
    button.disabled = false;
  }
}

async function saveReviewRequest() {
  const runId = $("review-run-id").value.trim();
  const paths = $("review-paths").value.split(/\r?\n/).map((path) => path.trim()).filter(Boolean);
  if (!runId) { $("review-form-message").textContent = t("请填写运行 ID"); return; }
  if (paths.length > 200 || paths.some((path) => path.length > 500)) {
    $("review-form-message").textContent = t("最多 200 个文件，每个路径最多 500 字符"); return;
  }
  await reviewQueueSave("/api/reviews", { run_id: runId, paths,
    summary: $("review-summary").value.trim(), channel: $("review-channel").value.trim() });
}

async function saveReviewTransition(id, action) {
  const reviewer = $("review-reviewer").value.trim(), reason = $("review-reason").value.trim();
  if (action === "assign" && !reviewer) { $("review-form-message").textContent = t("请填写评审人"); return; }
  if (action === "changes_requested" && !reason) { $("review-form-message").textContent = t("请填写修改意见"); return; }
  await reviewQueueSave("/api/reviews/" + encodeURIComponent(id) + "/transition", { action, reviewer, reason });
}

/* catalog 里 model 可能是字符串，也可能是 {default:...} 之类的对象 */
function fmtModel(m) {
  if (m == null || m === "") return "";
  return typeof m === "object" ? JSON.stringify(m) : String(m);
}

/* 极简 Markdown 渲染（标题/加粗/行内码/列表/表格/代码块）。
 * 围栏代码块走 codeBlockHTML（行号表格+高亮+代码主题）：裸 <pre> 只有
 * --log-bg 底色没配浅字，暖色皮肤里深底配深字根本读不了。 */
function md2html(md) {
  const lines = String(md || "").split(/\r?\n/);
  let html = [], inCode = false, codeBuf = null, inTable = false, listOpen = false;
  const inline = (t) => esc(t)
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
  const closeList = () => { if (listOpen) { html.push("</ul>"); listOpen = false; } };
  const closeTable = () => { if (inTable) { html.push("</tbody></table>"); inTable = false; } };
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, "");
    if (line.startsWith("```")) {
      closeList(); closeTable();
      if (inCode) { html.push(codeBlockHTML(codeBuf.join("\n"))); codeBuf = null; }
      else codeBuf = [];
      inCode = !inCode; continue;
    }
    if (inCode) { codeBuf.push(raw); continue; }
    if (/^\|(.+)\|\s*$/.test(line)) {
      const cells = line.slice(1, -1).split("|").map((s) => s.trim());
      if (/^[-: ]+$/.test(cells.join(""))) continue; // 分隔行
      if (!inTable) { closeList(); html.push("<table><tbody>"); inTable = true; }
      html.push("<tr>" + cells.map((c) => "<td>" + inline(c) + "</td>").join("") + "</tr>");
      continue;
    }
    closeTable();
    const h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) { closeList(); html.push("<h" + (h[1].length + 1) + ">" + inline(h[2]) + "</h" + (h[1].length + 1) + ">"); continue; }
    if (/^[-*]\s+/.test(line)) {
      if (!listOpen) { html.push("<ul>"); listOpen = true; }
      html.push("<li>" + inline(line.replace(/^[-*]\s+/, "")) + "</li>"); continue;
    }
    closeList();
    if (!line.trim()) { continue; }
    html.push("<p>" + inline(line) + "</p>");
  }
  closeList(); closeTable();
  if (inCode && codeBuf) html.push(codeBlockHTML(codeBuf.join("\n")));   // 未闭合围栏也按代码块收尾
  return html.join("\n");
}

/* ---------------------------------------------------------- 运行完成右下角通知 */
/* 任务跑完没有主动提示，台账徽章不盯屏幕就不知道。run 从活跃态翻到终态时
 * 右下角弹卡。不用居中 toast：它是单例，连载/并行多任务接连完成会互相覆盖。
 * 只对「本会话亲眼见过在跑」的 run 弹：首帧、刷新后回看、换轮次只记账不轰炸。 */
const RUN_ACTIVE_STATUS = new Set(["queued", "running", "waiting"]);

function runSettleWatch(prev, next) {
  try {
    if (!next || typeof next !== "object") return;
    const seen = (S._runSeen = S._runSeen || new Map());
    const names = new Map();
    for (const tk of (next.tasks || []).concat(next.archived_tasks || [])) {
      if (tk && tk.id) names.set(tk.id, tk.title || tk.goal || "");
    }
    const latest = next.task_latest || {};
    for (const [taskId, run] of Object.entries(latest)) {
      if (!run || !run.id) continue;
      const st = String(run.status || "");
      const active = RUN_ACTIVE_STATUS.has(st);
      const was = seen.get(taskId);
      if (!was || was.runId !== run.id) {   // 首见/新一轮：只记账
        seen.set(taskId, { runId: run.id, active });
        continue;
      }
      seen.set(taskId, { runId: run.id, active });
      if (was.active && !active && st !== "cancelled") {   // 取消是自己点的，不回执
        runSettleNotice(taskId, names.get(taskId) || t("未命名任务"), run);
      }
    }
    for (const taskId of Array.from(seen.keys())) {
      if (!(taskId in latest)) seen.delete(taskId);   // 任务删档/清场：台账跟着清
    }
  } catch (e) { /* 通知环节失败不许影响状态同步 */ }
}

function runSettleNotice(taskId, title, run) {
  let box = $("notice-stack");
  if (!box) {
    box = document.createElement("div");
    box.id = "notice-stack";
    document.body.appendChild(box);
  }
  const st = String((run && run.status) || "");
  const unqualified = st === "done" && run && run.verdict && run.verdict.pass === false;
  const tone = st === "done" ? (unqualified ? "warn" : "good") : "bad";
  const head = t({ done: t("任务已完成"), failed: t("任务失败"), timeout: t("任务超时") }[st]
    || String(runStatusText(run))) + (unqualified ? t("·未达标") : "");
  sendBrowserRunNotification(taskId, title, run, head);
  const card = document.createElement("div");
  card.className = "notice-card " + tone;
  card.innerHTML = '<div class="notice-head"><span class="notice-ico">' +
    (tone === "good" ? "✓" : tone === "warn" ? "⚠" : "✕") + "</span>" + esc(head) + "</div>" +
    '<div class="notice-title">' + esc(title) + "</div>" +
    '<div class="notice-hint">' + esc(t("点击查看任务")) + "</div>";
  card.addEventListener("click", () => {
    card.remove();
    if (typeof sideOpenTask === "function") sideOpenTask(taskId);   // 任务点击默认进对话
  });
  box.appendChild(card);
  requestAnimationFrame(() => card.classList.add("in"));   // 触发滑入过渡
  while (box.children.length > 4) box.firstChild.remove();   // 连环完成只留最近 4 张
  setTimeout(() => {
    card.classList.add("out");
    setTimeout(() => card.remove(), 300);
  }, 7000);
}

function browserNotifyEnabled() { return localStorage.getItem("orch.browser-notify") === "1"; }
function notifySoundEnabled() { return localStorage.getItem("orch.notify-sound") !== "0"; }
function sendBrowserRunNotification(taskId, title, run, head) {
  try {
    if (browserNotifyEnabled() && "Notification" in window && Notification.permission === "granted") {
      const note = new Notification("CodeBee · " + head, { body: title + " · " + (run && run.id ? run.id : taskId), tag: "codebee-" + taskId });
      note.onclick = () => { window.focus(); if (typeof sideOpenTask === "function") sideOpenTask(taskId); note.close(); };
    }
    if (notifySoundEnabled() && soundEnabled()) beepAttention();
  } catch (error) { /* 浏览器权限/音频限制不应影响任务状态 */ }
}

async function requestBrowserNotification() {
  const status = $("browser-notify-status");
  if (!("Notification" in window)) { if (status) status.textContent = t("当前浏览器不支持通知"); return; }
  try {
    const permission = await Notification.requestPermission();
    if (permission === "granted") localStorage.setItem("orch.browser-notify", "1");
    if (status) status.textContent = permission === "granted" ? t("通知权限已开启") : t("通知权限未授予");
    paintBrowserNotify();
  } catch (error) { if (status) status.textContent = t("通知权限请求失败：") + error.message; }
}

function paintBrowserNotify() {
  const browser = $("set-browser-notify"), sound = $("set-notify-sound"), status = $("browser-notify-status");
  if (browser) browser.checked = browserNotifyEnabled();
  if (sound) sound.checked = notifySoundEnabled();
  if (status && "Notification" in window) status.textContent = t("当前权限：") + Notification.permission;
}

function saveBrowserNotifyPreference() {
  const browser = $("set-browser-notify"), sound = $("set-notify-sound");
  if (browser) localStorage.setItem("orch.browser-notify", browser.checked ? "1" : "0");
  if (sound) localStorage.setItem("orch.notify-sound", sound.checked ? "1" : "0");
  paintBrowserNotify();
}

/* ---------------------------------------------------------- 状态同步：SSE 实时 + 轮询降级 */
/* 应用 /api/state 或 SSE 推送的状态载荷 */
function applyState(d) {
  if (!d || typeof d !== "object") return;
  // A slower /api/state response can finish after a newer SSE frame. The
  // version is monotonic on the desktop and prevents that stale snapshot from
  // rolling the phone workbench back to an older state.
  const incomingVersion = Number(d.v);
  const currentVersion = Number(S.state && S.state.v);
  if (Number.isFinite(incomingVersion) && Number.isFinite(currentVersion) &&
      incomingVersion < currentVersion) return;
  const prevState = S.state;
  S.state = d;
  if (!window.__orchStateReady) {
    window.__orchStateReady = true;
    window.dispatchEvent(new Event("orch:state-ready"));
  }
  runSettleWatch(prevState, d);
  if (d.control) setControl(d.control);
  if (d.health) renderHealthBanner(d.health);
  const conn = $("conn");
  if (conn) {
    // A successful state snapshot proves that the API/relay path works even
    // when the optional SSE stream later degrades on a mobile network.
    conn.textContent = t("已连接");
    conn.className = "conn ok";
    conn.removeAttribute("title");
  }
  restoreInspector();   // 刷新后恢复上次打开的检查器（只在已开时为空操作）
  restoreLastTask();    // 刷新/重开后回到最近打开的任务对话（只在首帧尝试一次）
  ovMaybeRefresh();     // 停在概览页时：概览语与最近运行跟着这次状态一起刷新
  memoryCenterMaybeRefresh();
  updateStatusSidebar(); // 暖色皮肤状态侧栏
  if (S.tab === "home") renderHome();   // 停在主页时：最近任务列表跟着刷新
  if (S.tab === "kanban") renderKanban();   // 停在看板页时：列/卡随状态帧刷新（阻塞出现即挪待裁决列）
  if (S.tab === "browser") {
    browserRenderTaskContext();
    browserLoadPublishState(browserCurrentTask());
  }
  scheduleStartupEnhancements();
}

/* ---------------------------------------------------------- 供应商健康告警横幅 */
/* 告警触发时顶栏横幅（厂商+模型）+ 提示音；点击弹出详情弹框：
   静默本次告警 / 手动标记恢复 / 一键禁用厂商。 */
let _healthBeeped = false;

/* 账号类告警（CLI 探活）后端没有静默通道——探活不恢复横幅就永远红着。
   前端给「隐藏」：agent_id→到期时间戳存 localStorage，12小时内不再计入横幅，
   到期或探活恢复后自然回归。 */
const ACCT_DISMISS_KEY = "health.acct.dismissUntil";
const ACCT_DISMISS_MS = 12 * 3600 * 1000;
let _visibleAcctIds = [];

function acctDismissMap() {
  try { return JSON.parse(localStorage.getItem(ACCT_DISMISS_KEY) || "{}") || {}; }
  catch (e) { return {}; }
}

function visibleAccountAlerts(health) {
  const now = Date.now();
  const dm = acctDismissMap();
  return ((health && health.account_alerts) || [])
    .filter((a) => (dm[a.agent_id || ""] || 0) <= now);
}

function visibleProviderAlerts(health) {
  const alerts = (health && health.alerts) || [];
  // The backend also prunes these rows. Keep the UI defensive while an older
  // long-running process still serves a persisted alert from before disable.
  // Do not flash or beep for a stale persisted row before the provider
  // registry has arrived. Unknown telemetry is preserved once the registry is
  // loaded, so this only suppresses the configuration bootstrap window.
  if (!S._modelsLoaded || !Array.isArray(S.providers)) return [];
  return alerts.filter((alert) => {
    const providerId = String(alert.provider_id || "");
    const providerName = String(alert.provider || "");
    const provider = (providerId
      ? S.providers.find((p) => String(p.id || "") === providerId)
      : null) || (!providerId
      ? S.providers.find((p) => String(p.name || "") === providerName)
      : null);
    // Preserve unknown/synthetic telemetry until the backend can classify it.
    if (!provider) return true;
    if (provider.enabled === false) return false;
    const model = String(alert.model || "").trim();
    if (!model) return true;
    const row = (provider.models || []).find((m) =>
      String(m.name || "").trim() === model);
    return !(row && (row.enabled === false || row.hidden));
  });
}

function dismissVisibleAccountAlerts() {
  dismissAccountAlerts(_visibleAcctIds);
}

function dismissAccountAlert(agentId) {
  dismissAccountAlerts([agentId]);
}

function dismissAccountAlerts(agentIds) {
  const ids = (agentIds || []).filter(Boolean);
  if (!ids.length) return;
  const dm = acctDismissMap();
  const until = Date.now() + ACCT_DISMISS_MS;
  ids.forEach((id) => { dm[id] = until; });
  const now = Date.now();
  Object.keys(dm).forEach((k) => { if (dm[k] <= now) delete dm[k]; });
  try { localStorage.setItem(ACCT_DISMISS_KEY, JSON.stringify(dm)); } catch (e) {}
  closeModal();
  renderHealthBanner(S.state && S.state.health);
  toast(t("已隐藏账号告警，12小时内不再提示"));
}

function renderHealthBanner(health) {
  const el = $("health-banner");
  if (!el) return;
  const alerts = visibleProviderAlerts(health);
  const accountAlerts = visibleAccountAlerts(health);
  _visibleAcctIds = accountAlerts.map((a) => a.agent_id || "");
  const allAlerts = alerts.concat(accountAlerts.map((a) => ({
    account: true, provider: a.agent_id || t("账号"), provider_id: "",
    last_error: a.last_error || a.summary || a.code || ""
  })));
  if (!allAlerts.length) {
    const rec = (health.providers || []).find((p) => p.status === "recovered");
    const accountRec = (health.accounts || []).find((a) => a.status === "recovered" && a.recovered_at);
    const recoveredAt = Math.max(
      rec ? (Date.parse(rec.recovered_at || "") || 0) : 0,
      accountRec ? Number(accountRec.recovered_at || 0) * 1000 : 0);
    if ((rec || accountRec) && recoveredAt && Date.now() - recoveredAt < 60000) {
      el.textContent = "✓ " + (rec ? rec.provider : accountRec.agent_id) + " " + t("已恢复");
      el.className = "health-banner recovered";
    } else {
      el.className = "health-banner hidden";
      el.textContent = "";
      _healthBeeped = false;
    }
    return;
  }
  el.textContent = "";
  const txt = document.createElement("span");
  txt.className = "health-txt";
  txt.textContent = healthBannerText(health);
  el.appendChild(txt);
  if (_visibleAcctIds.length) {
    const x = document.createElement("span");
    x.className = "health-x";
    x.setAttribute("role", "button");
    x.title = t("隐藏账号告警");
    x.textContent = "✕";
    x.onclick = (ev) => { ev.stopPropagation(); dismissVisibleAccountAlerts(); };
    el.appendChild(x);
  }
  el.className = "health-banner alerting";
  el.title = allAlerts.map((p) => p.account
    ? p.provider + t("：") + (p.last_error || t("账号失效，正在定时探活"))
    : p.provider + (p.model ? " · " + p.model : "") +
      (p.static
        ? t("：") + (p.last_error || t("未知错误"))
        : t("：连续失败 ") + p.consecutive_failures + t(" 次（") + (p.last_error || t("未知错误")) + t("）"))
  ).join("\n");
  if (!_healthBeeped) { _healthBeeped = true; beepAttention(); }
}

function healthBannerText(health) {
  const providers = visibleProviderAlerts(health);
  const accounts = (health && health.account_alerts) || [];
  return providers.map((p) => {
    const m = p.model ? " · " + p.model : "";
    return "⚠ " + p.provider + m + " " + (p.static ? t("绑定链失效") : t("连接异常"));
  }).concat(accounts.map((a) => "⚠ " + (a.agent_id || t("账号")) + " " +
    t("账号失效，正在定时探活"))).join(t("　"));
}

function healthBannerClick() {
  const alerts = visibleProviderAlerts(S.state && S.state.health);
  const accountAlerts = visibleAccountAlerts(S.state && S.state.health);
  if (!alerts.length && !accountAlerts.length) return;
  const providerRows = alerts.map((p, index) => {
    const statLine = p.static ? "" :
      "<div style='opacity:.75;font-size:12px;margin-top:2px'>" +
      t("连续失败") + " " + p.consecutive_failures + " " + t("次 · 首次失败 ") + (p.first_fail_at || "-") +
      "</div>";
    const actions = "<div style='display:flex;flex-wrap:wrap;gap:6px;margin-top:8px'>" +
      (p.provider_id && p.model
        ? "<button class='ghost small' data-health-action='disable-model' data-health-index=\"" + index + "\">" + t("禁用该模型") + "</button>"
        : "") +
      (p.provider_id
        ? "<button class='ghost small' data-health-action='disable-provider' data-health-index=\"" + index + "\">" + t("禁用该厂商") + "</button>"
        : "") +
      "<button class='ghost small' data-health-action='silence' data-health-index=\"" + index + "\">" + t("静默本次告警") + "</button>" +
      "<button class='ghost small' data-health-action='reset' data-health-index=\"" + index + "\">" + t("手动标记恢复") + "</button>" +
      "</div>";
    return "<div style='padding:10px 0;border-bottom:1px solid var(--border)'>" +
      "<b>" + esc(p.provider) + (p.model ? " · " + esc(p.model) : "") + "</b>" +
      statLine +
      "<div style='color:#dc2626;font-size:12px;margin-top:2px;word-break:break-all'>" +
      esc(p.last_error || "") + "</div>" + actions + "</div>";
  }).join("");
  const accountRows = accountAlerts.map((a, index) =>
    "<div style='padding:10px 0;border-bottom:1px solid var(--border)'><b>" + esc(a.agent_id || t("账号")) + "</b>" +
      "<div style='color:#dc2626;font-size:12px;margin-top:2px;word-break:break-all'>" +
      esc(a.last_error || a.summary || a.code || t("账号失效，正在定时探活")) +
      "</div><div style='opacity:.75;font-size:12px;margin-top:2px'>" +
      esc(t("恢复后会自动重新进入调度")) + "</div>" +
      "<div style='display:flex;margin-top:8px'><button class='ghost small' data-account-action='dismiss' data-account-index=\"" + index + "\">" +
      t("隐藏 12 小时") + "</button></div></div>").join("");
  const rows =
    (providerRows ? "<section><h3 style='font-size:13px;margin:0 0 2px'>" + t("供应商连接告警") + "</h3>" + providerRows + "</section>" : "") +
    (accountRows ? "<section style='margin-top:" + (providerRows ? "18px" : "0") + "'><h3 style='font-size:13px;margin:0 0 2px'>" +
      t("CLI 账号告警") + "</h3>" + accountRows + "</section>" : "");
  const foot =
    (accountAlerts.length > 1 ? "<button class='ghost' onclick='dismissVisibleAccountAlerts()'>" + t("隐藏全部账号告警 12 小时") + "</button>" : "") +
    "<button class='primary' onclick='closeModal()'>" + t("关闭") + "</button>";
  openModal(t("供应商健康告警"), rows, foot);
  bindHealthAlertActions(alerts, accountAlerts);
}

function bindHealthAlertActions(alerts, accountAlerts) {
  const modal = $("modal");
  if (!modal) return;
  modal.querySelectorAll("[data-health-action][data-health-index]").forEach((btn) => {
    const alert = alerts[Number(btn.dataset.healthIndex)];
    if (!alert) return;
    btn.addEventListener("click", () => {
      const action = btn.dataset.healthAction;
      if (action === "disable-model") {
        healthDisableModel(alert.provider_id, alert.model, alert.provider);
      } else if (action === "disable-provider") {
        healthDisableProvider(alert.provider_id, alert.provider);
      } else {
        healthOp(action, alert);
      }
    });
  });
  modal.querySelectorAll("[data-account-action][data-account-index]").forEach((btn) => {
    const account = accountAlerts[Number(btn.dataset.accountIndex)];
    if (!account) return;
    btn.addEventListener("click", () => dismissAccountAlert(account.agent_id));
  });
}

async function applyHealthOp(provider, op) {
  const r = await api("/api/health/op", { method: "POST",
    body: JSON.stringify({ provider, op }) });
  if (r && r.health) { S.state.health = r.health; renderHealthBanner(r.health); }
  return r;
}

async function healthOp(op, down) {
  if (!down) return;
  try {
    await applyHealthOp(down.provider, op);
    closeModal(); render();
    if (op === "silence") toast(t("已静默 {0} 的告警（恢复后自动重新武装）").replace("{0}", down.provider));
    if (op === "reset") toast(t("已手动标记 {0} 为恢复，探针将重新核实").replace("{0}", down.provider));
  } catch (e) {
    if (e && e.status === 404) {
      // 弹窗数据是打开那一刻的快照：点击时健康行可能已被清（禁用模型/
      // 厂商时后端 clear_inactive 顺手清掉，或已自行恢复重建）——告警
      // 已不存在，目标已达成，按成功收场而不是弹「未知的供应商」红错。
      closeModal(); render(); refreshState().catch(() => {});
      toast(t("该告警已消失，无需处理"));
      return;
    }
    toast(t("操作失败：") + e.message, true);
  }
}

/* 模型级禁用：绑定链里它的条目由后端自动剔除（modelhub 停用即出调度）。
   只对出问题的那一格生效——厂商其它模型照常可用。 */
async function healthDisableModel(pid, model, provider) {
  if (!pid || !model) { closeModal(); return; }
  const yes = await uiConfirm(
    t("确认禁用模型 {0}？调度链里它的条目会自动移除，其余模型不受影响；可在模型调度页重新启用。").replace("{0}", pid + " · " + model),
    { title: t("禁用模型"), danger: true, ok: t("禁用") });
  if (!yes) return;
  try {
    await api("/api/models/model-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, name: model, op: "disable" }) });
    if (provider) {
      // 禁用一成功，后端 clear_inactive 多半已把健康行一并清掉，这条
      // 顺手静默常常无行可静默——尽力而为，失败不能掩盖禁用本身成功。
      try { await applyHealthOp(provider, "silence"); } catch (e) {}
    }
    const models = await api("/api/models");
    S.providers = models.providers; S.bindings = models.bindings;
    S.modelCatalog = models.catalog || [];
    S.provSig = "";
    closeModal(); render(); loadOrchestrator();
    toast(t("已禁用模型 {0} · {1}，调度链已自动移除它；绑定页可重新启用").replace("{0}", pid).replace("{1}", model));
  } catch (e) {
    toast(t("操作失败：") + e.message, true);
  }
}

async function healthDisableProvider(pid, provider) {
  if (!pid) { closeModal(); return; }
  const yes = await uiConfirm(
    t("确认禁用该厂商？调度链里它的条目会自动移除，恢复后可在模型调度页重新启用。"),
    { title: t("禁用厂商"), danger: true, ok: t("禁用") });
  if (!yes) return;
  try {
    await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids: [pid], op: "disable" }) });
    if (provider) {
      // 禁用一成功，后端 clear_inactive 多半已把健康行一并清掉，这条
      // 顺手静默常常无行可静默——尽力而为，失败不能掩盖禁用本身成功。
      try { await applyHealthOp(provider, "silence"); } catch (e) {}
    }
    const models = await api("/api/models");
    S.providers = models.providers; S.bindings = models.bindings;
    S.provSig = "";
    closeModal(); render(); loadOrchestrator();
    toast(t("已禁用厂商 {0}：调度链已自动移除它的条目，绑定页可重新启用").replace("{0}", pid));
  } catch (e) {
    toast(t("操作失败：") + e.message, true);
  }
}

/* ---------------------------------------------------------- 通道体检 */
/* /api/availability：厂商健康 + 模型熔断 + CLI 降级链 + 账号探活一页聚合。
   只读展示；禁用/静默等操作仍走健康告警弹框与模型调度页。
   搜索、状态筛选、排序、模型展开全部在客户端完成，不额外打接口。 */

const AVAIL = {
  data: null, at: 0, loading: false,
  q: "", status: "all", sort: "severity",
  open: new Set(),
};

async function loadAvailability(opts) {
  const silent = !!(opts && opts.silent === true);
  if (AVAIL.loading) return;
  AVAIL.loading = true;
  const btn = $("avail-refresh");
  if (btn) { btn.disabled = true; btn.classList.add("is-loading"); }
  try {
    /* 「重新体检」是真体检：先让后端并行重探全部异常通道再渲染（探针单条
     * 最久 20s，后端有界等待 25s，前端超时给 30s）。按钮原先只重读台账，
     * 状态永远不动＝点了没有用（2026-10-22 实案）。静默刷新（主页摘要/
     * 进页预热）维持纯重读，不白烧探测；旧后端没有重探端点时退化纯重读。 */
    if (!silent) {
      try {
        const probed = await api("/api/availability/refresh",
          { method: "POST", body: "{}", timeout: 30000, busy: false });
        if (probed) {
          AVAIL.data = probed;
          AVAIL.at = Date.now();
          renderAvailability(probed);
          renderHomeHealth();
          return;
        }
      } catch (e) { /* 旧版后端没有重探端点：落到下面的纯重读 */ }
    }
    const data = await api("/api/availability", { timeout: 15000 });
    if (!data) return;
    AVAIL.data = data;
    AVAIL.at = Date.now();
    renderAvailability(data);
    renderHomeHealth();
  } catch (e) {
    if (!silent) toast(t("操作失败：") + e.message, true);
  } finally {
    AVAIL.loading = false;
    if (btn) { btn.disabled = false; btn.classList.remove("is-loading"); }
  }
}
window.loadAvailability = loadAvailability;

const AVAIL_SEV = { bad: 0, warn: 1, off: 2, ok: 3 };

function availHost(u) {
  if (!u) return "";
  try { return new URL(u).host; } catch (e) { return u; }
}

function availProvStatus(p) {
  if (!p || p.enabled === false) return "off";
  const h = p.health;
  if (h && (h.alerting || h.status === "down")) return "bad";
  if (h && h.status === "failing") return "warn";
  return "ok";
}

function availCliStatus(row) {
  const a = row && row.account;
  if (a && a.status !== "ok" && a.status !== "recovered") return "bad";
  if ((row.chain || []).some((e) => e && e.down)) return "warn";
  return "ok";
}

function availStatusLabel(st) {
  return st === "warn" ? t("观察中") : st === "bad" ? t("已熔断")
    : st === "off" ? t("已停用") : t("可用");
}

function availChip(label, cls) {
  return "<span class='avail-chip " + cls + "'>" + esc(label) + "</span>";
}

function availCounts(provs) {
  const c = { ok: 0, warn: 0, bad: 0, off: 0, total: provs.length };
  provs.forEach((p) => { c[availProvStatus(p)] += 1; });
  return c;
}

function availVerdict(c) {
  if (!c.total) return { tone: "", text: t("尚未接入厂商") };
  if (c.bad) return { tone: "bad", text: t("有 {0} 条通道已熔断", c.bad) };
  if (c.warn) return { tone: "warn", text: t("有 {0} 条通道观察中", c.warn) };
  if (c.ok) return { tone: "ok", text: t("所有启用通道正常") };
  return { tone: "", text: t("所有通道均已停用") };
}

function availMatchesProv(p, q) {
  if (!q) return true;
  const hay = [p.name, p.id, p.base_url, p.protocol, p.model,
    p.health && p.health.last_error].concat((p.models || []).map((m) => m.name));
  return hay.some((s) => String(s || "").toLowerCase().includes(q));
}

function availMatchesCli(row, q) {
  if (!q) return true;
  const a = row.account || {};
  const hay = [row.id, a.summary, a.last_error, a.code]
    .concat((row.chain || []).map((e) => (e.provider || e.provider_id || "") + " " + (e.model || "")));
  return hay.some((s) => String(s || "").toLowerCase().includes(q));
}

function availSortProvs(list) {
  const arr = list.slice();
  const name = (p) => String(p.name || p.id || "");
  const fails = (p) => String((p.health && p.health.last_fail_at) || "");
  if (AVAIL.sort === "name") {
    arr.sort((a, b) => name(a).localeCompare(name(b)));
  } else if (AVAIL.sort === "models") {
    arr.sort((a, b) => (b.models || []).length - (a.models || []).length
      || AVAIL_SEV[availProvStatus(a)] - AVAIL_SEV[availProvStatus(b)]
      || name(a).localeCompare(name(b)));
  } else if (AVAIL.sort === "recent") {
    arr.sort((a, b) => {
      const fa = fails(a), fb = fails(b);
      if (fa !== fb) return fa < fb ? 1 : -1;
      return AVAIL_SEV[availProvStatus(a)] - AVAIL_SEV[availProvStatus(b)]
        || name(a).localeCompare(name(b));
    });
  } else {
    arr.sort((a, b) => AVAIL_SEV[availProvStatus(a)] - AVAIL_SEV[availProvStatus(b)]
      || name(a).localeCompare(name(b)));
  }
  return arr;
}

function availKpisHtml(c) {
  const tiles = [
    ["ok", c.ok, t("可用"), t("正常响应")],
    ["warn", c.warn, t("观察中"), t("连续失败观察")],
    ["bad", c.bad, t("已熔断"), t("正在告警")],
    ["off", c.off, t("已停用"), t("不参与调度")],
  ];
  return tiles.map((row) => {
    const st = row[0], on = AVAIL.status === st;
    return '<button type="button" class="avail-kpi' + (on ? " is-active" : "") +
      '" data-status="' + st + '" onclick="availSetStatus(\'' + st + '\')" aria-pressed="' +
      (on ? "true" : "false") + '">' +
      '<span class="avail-kpi-top"><span class="avail-kpi-dot"></span>' + esc(row[2]) + "</span>" +
      '<span class="avail-kpi-v">' + row[1] + "</span>" +
      '<span class="avail-kpi-s">' + esc(row[3]) + "</span></button>";
  }).join("");
}

function availModelChip(m, pid) {
  const cls = m.down ? " down" : (m.enabled ? "" : " off");
  const label = m.down ? t("熔断中") : (m.enabled ? t("可用") : t("已停用"));
  const tip = m.enabled ? t("点击停用该模型（调度链自动移除，可再启用）") : t("点击启用该模型");
  return '<button type="button" class="avail-model' + cls + '" title="' + esc(label + " · " + tip) +
    '" onclick="availModelOp(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\', ' +
    (m.enabled ? "true" : "false") + ')">' + esc(m.name) + "</button>";
}

function availProvRow(p, q) {
  const st = availProvStatus(p);
  const h = p.health || {};
  const models = p.models || [];
  const downN = models.filter((m) => m.down).length;
  const activeFailure = h.status === "failing" || h.status === "down";
  const meta = [];
  if (p.model) meta.push(t("默认模型") + " <b>" + esc(p.model) + "</b>");
  if (p.keys_total) {
    meta.push("KEY <b>" + p.keys_enabled + "/" + p.keys_total + "</b>" +
      (p.keys_enabled ? "" : ' <span class="avail-bad-text">' + esc(t("无可用 KEY")) + "</span>"));
  }
  if (h.consecutive_failures) meta.push(t("连续失败") + " <b>" + h.consecutive_failures + "</b> " + t("次"));
  if (h.last_fail_at) meta.push(t("最近失败") + " <b>" + esc(h.last_fail_at) + "</b>");
  if (h.last_ok_at) meta.push(t("最近成功") + " <b>" + esc(h.last_ok_at) + "</b>");
  if (h.silenced) meta.push(t("告警已静默"));
  // 行内操作（2026-10-23）：以前只读，看到熔断还得绕去健康弹框/模型接入动手。
  const pname = p.name || p.id;
  const acts = [];
  if (p.enabled === false) {
    acts.push('<button type="button" class="avail-act" onclick="availProviderOp(\'' +
      jsq(p.id) + '\', \'enable\', \'' + jsq(pname) + '\')">' + esc(t("启用")) + "</button>");
  } else {
    if (st === "bad" && !h.silenced) {
      acts.push('<button type="button" class="avail-act" onclick="availSilence(\'' +
        jsq(pname) + '\')">' + esc(t("静默告警")) + "</button>");
    }
    acts.push('<button type="button" class="avail-act is-danger" onclick="availProviderOp(\'' +
      jsq(p.id) + '\', \'disable\', \'' + jsq(pname) + '\')">' + esc(t("停用")) + "</button>");
  }
  const open = AVAIL.open.has(p.id) || !!q;
  return '<article class="avail-row' + (p.enabled === false ? " is-off" : "") + '">' +
    '<span class="avail-row-dot ' + st + '"></span>' +
    '<div class="avail-row-main">' +
      '<div class="avail-row-head">' +
        '<span class="avail-row-name">' + esc(pname) + "</span>" +
        availChip(availStatusLabel(st), st) +
        '<span class="avail-row-host" title="' + esc(p.base_url) + '">' +
          esc(availHost(p.base_url)) + (p.protocol ? " · " + esc(p.protocol) : "") + "</span>" +
        '<span class="avail-row-acts">' + acts.join("") + "</span>" +
      "</div>" +
      (meta.length ? '<div class="avail-row-meta">' + meta.map((s) => "<span>" + s + "</span>").join("") + "</div>" : "") +
      (h.last_error ? '<div class="avail-row-err' + (activeFailure ? "" : " is-history") +
        '" title="' + esc(h.last_error) + '"><b class="avail-row-err-label">' +
        esc(t(activeFailure ? "当前失败详情" : "历史失败记录")) + "：</b> " +
        esc(String(h.last_error).slice(0, 400)) + "</div>" : "") +
      (models.length ? '<div class="avail-row-foot"><button type="button" class="avail-models-toggle" aria-expanded="' +
        (open ? "true" : "false") + '" onclick="availToggle(\'' + jsq(p.id) + '\')"><span>' +
        models.length + " " + esc(t("个模型")) + (downN ? " · " + downN + " " + esc(t("异常")) : "") +
        '</span><svg class="ico" aria-hidden="true"><use href="#i-chevrons-d"></use></svg></button></div>' : "") +
      (open && models.length ? '<div class="avail-models">' + models.map((m) => availModelChip(m, p.id)).join("") + "</div>" : "") +
    "</div></article>";
}

function availCliRow(row) {
  const st = availCliStatus(row);
  const a = row.account;
  const chain = row.chain || [];
  const chip = !a ? availChip(t("未探活"), "muted")
    : (a.status === "ok" || a.status === "recovered") ? availChip(t("账号可用"), "ok")
      : availChip(t("账号失效"), "bad");
  const steps = chain.map((e, i) =>
    '<span class="avail-chain-step' + (e.down ? " down" : "") + '">' +
    '<span class="avail-chain-n">' + (i + 1) + "</span>" +
    esc((e.provider || e.provider_id || "?") + " · " + (e.model || "")) + "</span>").join("");
  const meta = [];
  if (chain.length) meta.push(t("降级链 {0} 级", chain.length));
  if (a && a.code) meta.push(a.code);
  const note = [];
  if (a && a.summary) note.push(a.summary);
  if (a && a.status !== "ok" && a.status !== "recovered" && a.last_error) note.push(a.last_error);
  return '<article class="avail-row">' +
    '<span class="avail-row-dot ' + st + '"></span>' +
    '<div class="avail-row-main">' +
      '<div class="avail-row-head"><span class="avail-row-name">' + esc(row.id) + "</span>" + chip + "</div>" +
      (chain.length ? "" : '<div class="avail-row-meta"><span>' +
        esc(t("无降级链，按任务类型自动推荐厂商与模型")) + "</span></div>") +
      (steps ? '<div class="avail-chain">' + steps + "</div>" : "") +
      (meta.length ? '<div class="avail-row-meta">' + meta.map((s) => "<span>" + esc(s) + "</span>").join("") + "</div>" : "") +
      (note.length ? '<div class="avail-row-note">' + esc(note.join(" · ")) + "</div>" : "") +
    "</div></article>";
}

function availEmpty(icon, title, hint, actionLabel, actionCall) {
  return '<div class="avail-empty">' +
    '<span class="avail-empty-ico"><svg class="ico" aria-hidden="true"><use href="#' + icon + '"></use></svg></span>' +
    "<b>" + esc(title) + "</b><p>" + esc(hint) + "</p>" +
    (actionLabel ? '<button class="ghost small" type="button" onclick="' + jsq(actionCall) + '">' + esc(actionLabel) + "</button>" : "") +
    "</div>";
}

function renderAvailability(data) {
  if (data) AVAIL.data = data;
  const d = AVAIL.data;
  if (!d) return;
  const allProvs = d.providers || [];
  const allClis = d.clis || [];
  const c = availCounts(allProvs);
  const verdict = availVerdict(c);

  const dot = $("avail-verdict-dot");
  if (dot) dot.className = "avail-dot" + (verdict.tone ? " " + verdict.tone : "");
  const verdictEl = $("avail-verdict");
  if (verdictEl) verdictEl.textContent = verdict.text;
  const stamp = $("avail-stamp");
  if (stamp) {
    // 手动重探过的数据带 probe_round：让「体检确实跑过」可见，即使状态没翻新
    let stampText = d.generated_at ? t("数据更新于 {0}", d.generated_at) : "";
    const round = d.probe_round;
    if (round && round.targets) {
      stampText += (stampText ? " · " : "")
        + t("已重探 {0}/{1} 条异常通道", round.done, round.targets);
    }
    stamp.textContent = stampText;
  }
  const sub = $("avail-hero-sub");
  if (sub) {
    const enabled = allProvs.filter((p) => p.enabled !== false);
    const modelN = enabled.reduce((n, p) => n + (p.models || []).length, 0);
    const downN = enabled.reduce((n, p) => n + (p.models || []).filter((m) => m.down).length, 0);
    sub.textContent = t("已启用 {0}/{1} 个厂商 · {2} 个模型{3} · {4} 个 CLI",
      enabled.length, allProvs.length, modelN,
      downN ? "（" + t("{0} 个熔断", downN) + "）" : "", allClis.length);
  }

  const kpis = $("avail-kpis");
  if (kpis) kpis.innerHTML = availKpisHtml(c);
  document.querySelectorAll("#avail-filter button").forEach((b) => {
    const on = b.dataset.status === AVAIL.status;
    b.classList.toggle("on", on);
    b.setAttribute("aria-pressed", on ? "true" : "false");
  });
  const clearBtn = $("avail-q-clear");
  if (clearBtn) clearBtn.classList.toggle("hidden", !AVAIL.q);
  const qInput = $("avail-q");
  if (qInput && qInput.value !== AVAIL.q) qInput.value = AVAIL.q;
  const sortSel = $("avail-sort");
  if (sortSel) sortSel.value = AVAIL.sort;

  const q = AVAIL.q.trim().toLowerCase();
  const provs = availSortProvs(allProvs.filter((p) =>
    (AVAIL.status === "all" || availProvStatus(p) === AVAIL.status) && availMatchesProv(p, q)));
  const clis = allClis.filter((row) =>
    (AVAIL.status === "all" || availCliStatus(row) === AVAIL.status) && availMatchesCli(row, q))
    .sort((a, b) => AVAIL_SEV[availCliStatus(a)] - AVAIL_SEV[availCliStatus(b)]
      || String(a.id).localeCompare(String(b.id)));

  const provEl = $("avail-providers");
  if (provEl) {
    if (!allProvs.length) {
      provEl.innerHTML = availEmpty("i-layers", t("还没有接入厂商"),
        t("在「模型接入」里添加厂商和 API KEY 后，这里会显示真实健康状态。"),
        t("去模型接入"), "switchTab('models')");
    } else if (!provs.length) {
      provEl.innerHTML = availEmpty("i-search", t("没有符合条件的通道"),
        t("试试清空搜索，或切换到「全部」状态。"), t("清除筛选"), "availResetFilters()");
    } else {
      provEl.innerHTML = provs.map((p) => availProvRow(p, q)).join("");
    }
  }
  const provCount = $("avail-prov-count");
  if (provCount) provCount.textContent = allProvs.length ? t("显示 {0} / {1}", provs.length, allProvs.length) : "";

  const cliEl = $("avail-clis");
  if (cliEl) {
    if (!allClis.length) {
      cliEl.innerHTML = availEmpty("i-link", t("还没有配置 CLI 降级链"),
        t("为 CLI 配置厂商模型降级顺序后，这里会显示账号与链路状态。"),
        t("去模型调度"), "switchTab('bindings')");
    } else if (!clis.length) {
      cliEl.innerHTML = availEmpty("i-search", t("没有符合条件的 CLI"),
        t("试试清空搜索，或切换到「全部」状态。"), t("清除筛选"), "availResetFilters()");
    } else {
      cliEl.innerHTML = clis.map((row) => availCliRow(row)).join("");
    }
  }
  const cliCount = $("avail-cli-count");
  if (cliCount) cliCount.textContent = allClis.length ? t("显示 {0} / {1}", clis.length, allClis.length) : "";
}

function availSetStatus(st) {
  if (["all", "ok", "warn", "bad", "off"].indexOf(st) < 0) return;
  AVAIL.status = st;
  renderAvailability();
}

function availSetSort(v) {
  if (["severity", "name", "recent", "models"].indexOf(v) < 0) return;
  AVAIL.sort = v;
  renderAvailability();
}

function availSetQuery(v) {
  AVAIL.q = String(v || "");
  renderAvailability();
}

function availClearQuery() {
  AVAIL.q = "";
  const input = $("avail-q");
  if (input) { input.value = ""; input.focus(); }
  renderAvailability();
}

function availResetFilters() {
  AVAIL.q = "";
  AVAIL.status = "all";
  const input = $("avail-q");
  if (input) input.value = "";
  renderAvailability();
}

function availToggle(id) {
  if (!id) return;
  if (AVAIL.open.has(id)) AVAIL.open.delete(id); else AVAIL.open.add(id);
  renderAvailability();
}

/* ---- 通道体检行内操作（2026-10-23）：端点全部复用现成路由，本页仍不做探测。
 *   停用/启用厂商 → /api/models/provider-op（停用即出调度，链条目自动剔除）
 *   点击模型启停 → /api/models/model-op（只动这一格，其余模型不受影响）
 *   静默告警     → /api/health/op（404=告警行已消失，按成功收场） */
async function availProviderOp(pid, op, pname) {
  if (!pid || (op !== "enable" && op !== "disable")) return;
  if (op === "disable") {
    const yes = await uiConfirm(
      t("确认停用通道 {0}？调度链里它的条目会自动移除，配置保留，可随时再启用。", pname || pid),
      { title: t("停用通道"), danger: true, ok: t("停用") });
    if (!yes) return;
  }
  try {
    await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids: [pid], op }) });
    if (op === "disable") {
      // 停用成功后 clear_inactive 多半已把健康行一并清掉：顺手静默尽力而为，
      // 失败不能掩盖停用本身的成功（同健康告警弹框的口径）。
      try { await applyHealthOp(pname || pid, "silence"); } catch (e) {}
    }
    toast(op === "disable"
      ? t("已停用 {0}：调度链已自动移除它的条目", pname || pid)
      : t("已启用 {0}", pname || pid));
    loadAvailability({ silent: true });
  } catch (e) {
    toast(t("操作失败：") + e.message, true);
  }
}

async function availModelOp(pid, name, enable) {
  if (!pid || !name) return;
  if (!enable) {
    const yes = await uiConfirm(
      t("确认停用模型 {0} · {1}？调度链里它的条目会自动移除，其余模型不受影响。", pid, name),
      { title: t("停用模型"), danger: true, ok: t("停用") });
    if (!yes) return;
  }
  try {
    await api("/api/models/model-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, name, op: enable ? "enable" : "disable" }) });
    toast(enable
      ? t("已启用模型 {0} · {1}", pid, name)
      : t("已停用模型 {0} · {1}，调度链已自动移除它", pid, name));
    loadAvailability({ silent: true });
  } catch (e) {
    toast(t("操作失败：") + e.message, true);
  }
}

async function availSilence(pname) {
  if (!pname) return;
  try {
    await applyHealthOp(pname, "silence");
    toast(t("已静默 {0} 的告警（恢复后自动重新武装）", pname));
    loadAvailability({ silent: true });
  } catch (e) {
    if (e && e.status === 404) {
      // 快照与现实的时间差：健康行可能已被 clear_inactive 清掉或已自愈重建
      toast(t("该告警已消失，无需处理"));
      loadAvailability({ silent: true });
      return;
    }
    toast(t("操作失败：") + e.message, true);
  }
}

/* 自动刷新：30 秒静默重读一次（不触发真探测，真探测仍只归「重新体检」）。
 * 开关落 localStorage；离开体检页或页面隐藏时都不打接口。 */
let availAutoTimer = null;
function availAutoStart() {
  const box = $("avail-auto");
  const on = localStorage.getItem("orch.availAuto") === "1";
  if (box) box.checked = on;
  if (availAutoTimer) { clearInterval(availAutoTimer); availAutoTimer = null; }
  if (!on) return;
  availAutoTimer = setInterval(() => {
    if (S.tab !== "availability" || document.hidden) return;
    loadAvailability({ silent: true });
  }, 30000);
}

function availAutoStop() {
  if (availAutoTimer) { clearInterval(availAutoTimer); availAutoTimer = null; }
}

function availSetAuto(on) {
  localStorage.setItem("orch.availAuto", on ? "1" : "0");
  if (on) availAutoStart(); else availAutoStop();
}

/* 一键复制纯文本诊断报告：贴给支持/同事时不用截一长串图。 */
function availReportText() {
  const d = AVAIL.data;
  if (!d) return "";
  const provs = d.providers || [];
  const c = availCounts(provs);
  const lines = [];
  lines.push(t("通道体检") + " · " + (d.generated_at || ""));
  lines.push(availVerdict(c).text);
  provs.forEach((p) => {
    const h = p.health || {};
    const downN = (p.models || []).filter((m) => m.down).length;
    let line = "[" + availStatusLabel(availProvStatus(p)) + "] " + (p.name || p.id);
    if (downN) line += " · " + t("{0} 个模型熔断", downN);
    if (h.last_error) line += "\n    " + String(h.last_error).slice(0, 200);
    lines.push(line);
  });
  (d.clis || []).forEach((row) => {
    const a = row.account || {};
    let line = "[" + availStatusLabel(availCliStatus(row)) + "] CLI " + row.id;
    if (a && a.summary) line += " · " + a.summary;
    if (a && a.last_error) line += "\n    " + String(a.last_error).slice(0, 200);
    lines.push(line);
  });
  return lines.join("\n");
}

function availCopyReport() {
  const text = availReportText();
  if (!text) { toast(t("还没有体检数据，先点「重新体检」"), true); return; }
  copyText(text, () => toast(t("诊断报告已复制")));
}

/* 主页快捷入口的通道摘要：与体检页共用同一份缓存，60 秒内不重复拉取 */
function renderHomeHealth() {
  const line = $("rd-avail-summary");
  const badge = $("rd-avail-badge");
  if (!line && !badge) return;
  const d = AVAIL.data;
  if (!d) {
    if (line) line.textContent = t("厂商、模型与 CLI 的实时可用性");
    if (badge) { badge.className = "rd-tool-badge"; badge.textContent = ""; }
    return;
  }
  const provs = d.providers || [];
  const c = availCounts(provs);
  const enabled = provs.filter((p) => p.enabled !== false);
  const modelN = enabled.reduce((n, p) => n + (p.models || []).length, 0);
  const cliN = (d.clis || []).length;
  if (line) {
    line.textContent = t("厂商 {0}/{1} · 模型 {2} · CLI {3}",
      c.ok + c.warn + c.bad, c.total, modelN, cliN);
  }
  if (badge) {
    const v = availVerdict(c);
    badge.textContent = v.tone === "ok" ? t("正常")
      : v.tone === "bad" ? t("{0} 条熔断", c.bad)
        : v.tone === "warn" ? t("{0} 条观察中", c.warn) : t("未接入");
    badge.className = "rd-tool-badge" + (v.tone ? " " + v.tone : "");
  }
}

function homeHealthRefresh() {
  renderHomeHealth();
  if (AVAIL.loading) return;
  if (AVAIL.data && Date.now() - AVAIL.at < 60000) return;
  loadAvailability({ silent: true });
}

async function refreshState() {
  // The phone relay adds a second network hop and can transfer the initial
  // snapshot over a slow mobile link. Give this critical request enough time
  // to complete instead of cycling through false timeout failures.
  let _retried304 = false;
  while (true) {
    const headers = S._stateEtag ? { "If-None-Match": S._stateEtag } : {};
    let notModified = false;
    const state = await api("/api/state", {
      timeout: 30000, busy: false, operation: false,
      headers: authHeaders(headers),
      onResponse: (response) => {
        if (response.status === 304) notModified = true;
        else if (response.status === 200) S._stateEtag = response.headers.get("ETag") || "";
      },
    });
    if (state) applyState(state);
    if (state) break;
    // Never let an unexpected first-frame 304 strand a mobile page with no
    // state. One unconditional retry is enough; subsequent 304s are kept as a
    // valid cached response once a snapshot exists.
    // !S.state is the first-frame condition that needs recovery.
    if (!notModified || S.state || _retried304) break;
    _retried304 = true;
    S._stateEtag = "";
  }
}

let _lookupRefresh = null;
async function refreshPollLookups(force) {
  if (_lookupRefresh) return _lookupRefresh;
  const now = Date.now();
  const loadCatalog = !!force || !S._catalogLoaded || now - (S._catalogAt || 0) >= 60000;
  const loadModels = !!force || !S._modelsLoaded || now - (S._modelsAt || 0) >= 30000;
  if (!loadCatalog && !loadModels) return;
  if (loadCatalog) S._catalogAt = now;
  if (loadModels) S._modelsAt = now;
  _lookupRefresh = (async () => {
    try {
      const [cat, models] = await Promise.all([
        loadCatalog ? api("/api/catalog", { timeout: 15000 }) : Promise.resolve(null),
        loadModels ? api("/api/models", { timeout: 15000 }) : Promise.resolve(null),
      ]);
      if (cat) {
        S.catalog = cat.catalog;
        S.catalogChecking = !!cat.checking;
        S._catalogLoaded = true;
      }
      if (models) {
        S.providers = models.providers; S.bindings = models.bindings;
        S.modelCatalog = models.catalog || [];
        S.sourceNames = models.source_names || S.sourceNames || {};
        S._modelsLoaded = true;
        refreshBenchScores();          // 评测实测分随模型目录一起保鲜（推荐选模用）
        renderDirectModelPicker();
        const provSig = JSON.stringify((S.providers || []).map((p) => [p.id, p.enabled, !!p.api_key]));
        if (provSig !== S.provSig) { S.provSig = provSig; loadOrchestrator(); }
        // Re-render after model configuration arrives so stale backend alerts
        // for disabled providers disappear without waiting for a restart.
        renderHealthBanner(S.state && S.state.health);
      }
      render();
    } catch (e) {
      if (loadCatalog) S._catalogAt = 0;
      if (loadModels) S._modelsAt = 0;
    }
  })();
  try { await _lookupRefresh; }
  finally { _lookupRefresh = null; }
}

let _pollBusy = false;
let _sseEpoch = 0;
let _sseRetryTimer = null;
let _startupEnhancementsStarted = false;
let _startupEnhancementTasks = null;
let _startupEnhancementTimer = null;
let _startupEnhancementActive = 0;

// Wait for the first usable state snapshot before consuming the browser's
// small per-origin connection pool with secondary startup data. A two-request
// cap keeps the phone relay responsive without leaving the UI idle on latency.
function scheduleStartupEnhancements() {
  if (!S.state || document.hidden || _startupEnhancementTimer || _startupEnhancementActive >= 2) return;
  if (!_startupEnhancementTasks) {
    _startupEnhancementTasks = [
      loadFlows,                 // task type selector
      loadExperts,               // expert templates
      refreshSessionAgents,      // resume-session selector
      loadOrchestrator,          // sidebar provider indicator
      loadSettings,              // new-task defaults
      loadTaskTemplates,         // task templates
      suStartupCheck,            // optional version notice
    ];
  }
  if (!_startupEnhancementTasks.length) {
    if (_startupEnhancementActive) return;
    _startupEnhancementsStarted = true;
    return;
  }
  const runNext = () => {
    _startupEnhancementTimer = null;
    if (document.hidden) return;
    const task = _startupEnhancementTasks.shift();
    if (!task) return;
    _startupEnhancementsStarted = true;
    _startupEnhancementActive++;
    Promise.resolve().then(task).catch(() => {
      /* optional startup data must not block the UI */
    }).finally(() => {
      _startupEnhancementActive = Math.max(0, _startupEnhancementActive - 1);
      if (!_startupEnhancementTasks.length && !_startupEnhancementActive) {
        _startupEnhancementsStarted = true;
      } else {
        scheduleStartupEnhancements();
      }
    });
    // Fill the second slot immediately; waiting until this task finishes
    // would make the nominal two-request cap behave sequentially.
    scheduleStartupEnhancements();
  };
  _startupEnhancementTimer = setTimeout(runNext, _startupEnhancementsStarted ? 0 : 500);
}

function scheduleSSEReconnect() {
  if (_sseRetryTimer || document.hidden || S.es) return;
  _sseRetryTimer = setTimeout(() => {
    _sseRetryTimer = null;
    if (!document.hidden && !S.es) startSSE();
  }, 3000);
}

async function poll() {
  // 上一轮还没回来就跳过本轮：服务端偶发卡顿（如目录探测）时，无超时的
  // 轮询会每 2s 叠两条连接，塞满浏览器 6 连接池后连点击的请求都排不上队
  // ——整个界面（左栏+右栏）一起假死（2026-09-22 用户实测）。在飞保护 +
  // 15s 超时保证任何时刻最多占两条连接，卡完即自愈。
  if (_pollBusy) return;
  _pollBusy = true;
  try {
    // State is the only startup-critical request. Catalog/model lookups are
    // scheduled separately after the first paint so they cannot compete with
    // the phone relay's initial state request for its limited connections.
    // EventSource.onopen only confirms that the stream headers arrived. On a
    // phone relay the first SSE data frame can still be delayed or lost while
    // the connection stays open; keep the ordinary state request alive until
    // at least one state payload has actually been applied, otherwise the UI
    // remains stuck on "Connecting…" forever.
    if (!S.sseLive || !S.state) await refreshState();
    else if (S._lastStateSseAt && Date.now() - S._lastStateSseAt > 30000 && !document.hidden) {
      // SSE 静默看门狗：连接半死时 EventSource 不报错、sseLive 恒真、上面
      // 的拉取被跳过——侧栏会冻在几分钟前的快照，而详情卡自拉自新，两头
      // 对不上（2026-09-22 详情「完成」侧栏「在跑」实案）。60s 没有任何
      // 状态推送就主动拉一次全量兜底；不要把 usage 事件或连接 open 当状态
      // 活跃。后台页签没人看，不烧这份流量。
      S._lastStateSseAt = Date.now();
      await refreshState();
    }
    render();
    scheduleStartupEnhancements();
    // Do not let the long-lived SSE request compete with the very first
    // state snapshot on the phone relay.  The initial snapshot is the
    // connectivity proof; only open the stream after it has arrived.  This
    // avoids a relay connection-pool race where EventSource occupies the
    // only available slot and /api/state is reported as "连接失败".
    if (S.state && !S.es && !document.hidden) startSSE();
  } catch (e) {
    if (!S.state || !S.sseLive || !S.es) {
      // Keep the relay/API's HTTP status or message visible; the generic
      // badge made mobile failures impossible to distinguish from offline.
      $("conn").textContent = t("连接失败：") + String((e && e.message) || e).slice(0, 100);
      $("conn").className = "conn bad";
    }
  } finally {
    _pollBusy = false;
  }
}

function schedulePolling() {
  clearInterval(S.pollTimer);
  S.pollTimer = setInterval(() => { if (!document.hidden) poll(); }, S.sseLive ? 8000 : 2000);
}

/* SSE：状态变化即时推送；断开自动重连，重连失败降级为 2s 轮询 */
function startSSE() {
  if (!window.EventSource) return;
  if (S.es) return;
  clearTimeout(_sseRetryTimer);
  _sseRetryTimer = null;
  const epoch = ++_sseEpoch;
  try {
    const es = new EventSource("/api/events" + qsAuth());
    S.es = es;
    const current = () => epoch === _sseEpoch && S.es === es;
    es.onopen = () => {
      if (!current()) { try { es.close(); } catch (e) {} return; }
      // Headers alone do not prove that the relay can deliver event frames.
      // Keep short polling until the first actual state payload arrives.
      S.sseLive = false;
      schedulePolling();
      poll();
    };
    // 命名事件：台账有新记账（event: usage）。不进 onmessage、不触发
    // applyState——只刷新左下角用量条，3s 节流在 sideUsageLoad 里。
    es.addEventListener("usage", () => {
      if (!current()) return;
      S._lastSseAt = Date.now();
      sideUsageLoad(true);
    });
    es.onmessage = (ev) => {
      if (!current()) return;
      try {
        const data = JSON.parse(ev.data);
        S.sseLive = true;
        S._lastStateSseAt = Date.now();
        schedulePolling();
        applyState(data);
        render();
      } catch (e) { /* ignore */ }
    };
    es.onerror = () => {
      if (!current()) { try { es.close(); } catch (e) {} return; }
      // EventSource may remain in CONNECTING for a long time without closing.
      // Mark the stream unavailable immediately so the mobile relay falls back
      // to /api/state instead of skipping polls while the phone shows failure.
      S.sseLive = false;
      schedulePolling();
      if (es.readyState === EventSource.CLOSED) {  // 彻底失败（如 401）：降级轮询
        S.es = null; S.sseLive = false; schedulePolling(); poll();
        scheduleSSEReconnect();
      } else {
        poll();
      }
      // D3（三轮审查）：SSE 已不可用（被限/断线）时诚实告知，并提示已用轮询兜底——
      // 之前只显示「重连中…」，用户无从判断是瞬时抖动还是被限流持续失败。
      const conn = $("conn");
      if (conn) {
        if (S.state) {
          // SSE is an enhancement, not the data connection. Keep the badge
          // green after a state snapshot and expose the degraded stream as a
          // tooltip; the 2s polling fallback remains fully usable.
          conn.textContent = t("已连接");
          conn.className = "conn ok";
          conn.title = t("实时连接受限，已用轮询兜底");
        }
        // Before the first state snapshot, leave the badge to poll()'s
        // /api/state result. It carries the actionable relay/API error (401,
        // 503, timeout, etc.); a generic EventSource failure would race with
        // and hide that diagnosis on mobile.
      }
    };
  } catch (e) { /* EventSource 不可用：保持轮询 */ }
}

/* 页签可见性：后台页签关闭 SSE 让出连接（HTTP/1.1 单域名 6 连接上限，
 * 每个隐藏页签一条永久 SSE 会把连接池吃光，前台页签的接口全部排队超时
 * ——2026-09-23 实案：多标签打开时步骤列表/日志请求超时）。回到前台
 * 立即重开 SSE 并拉一次全量。轮询在隐藏态本就被跳过，后台零连接占用。 */
document.addEventListener("visibilitychange", () => {
  if (document.hidden) {
    clearTimeout(_sseRetryTimer);
    _sseRetryTimer = null;
    ++_sseEpoch;
    if (S.es) { try { S.es.close(); } catch (e) {} S.es = null; S.sseLive = false; schedulePolling(); }
  } else if (!S.es) {
    startSSE();
    poll();
    sideUsageLoad(true);  // 隐藏期落下的记账立刻补上（SSE 断开期间收不到 usage 事件）
  }
  if (!document.hidden) scheduleStartupEnhancements();
});

/* ---------------------------------------------------------- 多端控制权 */
function setControl(c) {
  S.control = c || null;
  renderCtrl();
}

function renderCtrl() {
  const el = $("ctrl-pill");
  if (!el) return;
  const c = S.control;
  el.classList.remove("hidden", "mine", "held");
  // 顶栏统一纯图标：状态靠图标 + 颜色（mine=绿 / held=黄）传达，
  // 完整语义（谁在控制）放 title / aria-label，悬停与读屏都能拿到
  let icon = "unlock", tip = t("控制空闲：执行任意操作即可自动接管");
  if (c && c.mode !== "free") {
    if (c.mine) {
      el.classList.add("mine");
      icon = "gamepad"; tip = t("你在控制（点击释放）");
    } else {
      el.classList.add("held");
      icon = "lock";
      const holder = c.holder || t("其他设备");
      tip = t("{0} 正在控制（点击接管）", holder);
    }
  }
  el.innerHTML = '<svg class="ico" aria-hidden="true"><use href="#i-' + icon + '"></use></svg>';
  el.title = tip;
  el.setAttribute("aria-label", tip);
}

async function ctrlAction(action, force, silent = false) {
  try {
    const d = await api("/api/control", { method: "POST", body: JSON.stringify({ action, force: !!force }) });
    setControl(d.control);
    return !!d.control;
  } catch (e) { if (!silent) toast(e.message, true); return false; }
}

async function ctrlClick() {
  const c = S.control;
  if (!c || c.mode === "free") return ctrlAction("acquire");
  if (c.mine) return ctrlAction("release");
  if (await uiConfirm(t("接管控制权？「") + (c.holder || t("其他设备")) + t("」将变为只读。"), { ok: t("接管") })) {
    ctrlAction("acquire", true);
  }
}

/* 持有控制权时每 15s 续期；45s 无心跳服务端自动释放 */
function startCtrlHeartbeat() {
  setInterval(() => {
    if (S.control && S.control.mine) {
      api("/api/control/heartbeat", { method: "POST", body: "{}", busy: false })
        .then((d) => setControl(d.control)).catch(() => {});
    }
  }, 15000);
  window.addEventListener("pagehide", () => {
    if (S.control && S.control.mine) {
      try {
        fetch("/api/control", { method: "POST", headers: authHeaders(),
                                body: JSON.stringify({ action: "release" }), keepalive: true });
      } catch (e) { /* ignore */ }
    }
  });
}

function render() {
  renderImplSelects();
  renderRunList();
  renderSideTasks();
  CodeBeeActivity.render();
  renderRunDetail();
  renderChangeSummary();
  renderCatalog();
  renderModels();
  renderBindings();
  renderOrchSide();   // 用缓存的 S.orch 重画（供应商变更时由 poll 触发重新拉取）
  refreshInspector(); // 检查器开着时节流跟刷（内部 2s 节流，关着直接返回）
  refreshDetailSide(); // 详情页开着时节流跟刷任务级 side（累计统计 + git 实时）
}

/* ---------------------------------------------------------- 模型接入 */
/* 批量选择的只读/可写访问器：渲染只读，点击才写，避免轮询重绘时误改状态 */
function modelSel(pid) { return (S.selModels || {})[pid] || {}; }
function modelSelSet(pid) {
  S.selModels = S.selModels || {};
  return (S.selModels[pid] = S.selModels[pid] || {});
}

function renderModels() {
  renderProvList();
  const box = $("prov-detail");
  if (!box) return;
  const sig = JSON.stringify([S.providers, S.bindings, S.selProv,
                              S.testProvState, S.testModelState, S.probeState,
                              S.selProvs, S.selModels]);
  if (sig === S.modelsSig) return;  // 数据没变不重绘，避免清掉正在输入的内容
  S.modelsSig = sig;
  renderProvDetail();
}

/* ---------------------------------------------------------- CLI 绑定 */
function renderBindings() {
  const bbox = $("binding-list");
  if (!bbox) return;
  const provs = S.providers || [];
  const bindable = bindableProvs(provs);
  const nonBindable = provs.length - bindable.length;
  const targets = (S.catalog || []).filter((c) => c.installed && c.orch_kind);
  // 先建好草稿态并清理失效项，再算签名——否则首帧创建草稿态会让签名变化、白重绘一次。
  for (const c of targets) bindSelById(c.id);
  for (const id of Object.keys(S.bindSel || {})) {
    if (!targets.some((c) => c.id === id)) delete S.bindSel[id];
  }
  const sig = JSON.stringify([provs, S.bindings,
                              targets.map((c) => [c.id, c.orch_kind]), S.bindSel]);
  if (sig === S.bindSig) return;
  S.bindSig = sig;
  syncSaveAllBtn();
  if (!targets.length) {
    bbox.innerHTML = '<div class="empty">' + t("还没有装好的 CLI 智能体（codex / claude / kimi 等）。") +
      '<a href="#" onclick="return helpOpenTopic(\'quickstart\')">' + t("看看快速上手") + '</a></div>';
    return;
  }
  bbox.innerHTML = targets.map((c) => {
    const b = (S.bindings || {})[c.id] || {};
    const opts = '<option value="">' + t("自动推荐（推荐）") + '</option>' + bindable.map((p) => {
      const adaptedOnly = p.protocol !== "anthropic" && p.protocol !== "openai";
      return '<option value="' + esc(p.id) + '"' + (b.provider_id === p.id ? " selected" : "") + ">" +
        esc(p.name) + t("（") + esc(protoLabel(p)) + (adaptedOnly ? t(" · 已适配") : "") +
        (p.enabled === false ? t(" · 已停用") : "") + t("）") + "</option>";
    }).join("");
    const bound = provs.find((p) => p.id === b.provider_id);
    const offWarn = bound && bound.enabled === false
      ? '<p class="hint warn">' + t("该供应商已停用：编排时不会注入它，模型链因此失效时相关步骤会直接判失败。") + '</p>' : "";
    const protoWarn = bound && !bindable.some((p) => p.id === bound.id)
      ? '<p class="hint warn">' + t("该供应商协议为 ") + esc(protoLabel(bound)) +
        t("，当前没有可注入的 CLI，编排时相关步骤会直接判失败。") + '</p>' : "";
    // 供应商停用但链上勾选了它家模型：链条目在解析时也会被整条跳过，链空了
    // 相关步骤会直接判失败（2026-09-17 起；此前的静默回落本机默认正是 2026-09-16
    // 配额事故的隐藏形态）——单说「供应商下拉」警告不够，链本身的死活也要点名。
    const chainDead = bindChain(b).some((c2) => c2.p && (() => {
      const pv = provs.find((p) => p.id === c2.p);
      return !pv || pv.enabled === false;
    })());
    const chainWarn = (!bound || bound.enabled !== false) && chainDead
      ? '<p class="hint warn">' + t("模型链里有已停用/已删除的供应商：这些条目解析时会被跳过，链可能因此整体失效，相关步骤将判失败。") + '</p>' : "";
    return '<div class="card"><div class="head"><span class="name">' + esc(c.name) + "</span>" +
      '<span class="tag">' + esc(c.orch_kind) + "</span></div>" +
      '<div class="field"><label>' + t("供应商") + '</label><select id="bindprov-' + esc(c.id) + '">' + opts + "</select></div>" +
      '<p class="hint">' + t("默认不需要绑定：系统会按任务类型、难度、成本与健康状态自动推荐可用模型；只有需要固定厂商、模型或降级顺序时才在这里绑定。绑定后编排调用会注入该供应商的 API key 与地址；完全未指定时保持自动调度，没有兼容可用供应商才使用 CLI 自身配置。") + '</p>' +
      bindModelBox(c, b.provider_id) + offWarn + protoWarn + chainWarn +
      '<div class="ops"><label class="toggle"><input type="checkbox" id="binddiff-' + esc(c.id) + '"' +
      (b.difficulty_routing ? " checked" : "") + '>' + t(" 按难度自动选模型（简单/困难）") + '</label>' +
      '<button class="ghost small" onclick="saveBinding(\'' + jsq(c.id) + '\')">' + t("保存") + '</button></div></div>';
  }).join("") +
    (!targets.length ? '<p class="hint">' + t("还没有已安装且可编排的 CLI——先到「本机智能体」页安装并启用。") + '</p>' : "") +
    (nonBindable ? '<p class="hint">' + t("另有 ") + nonBindable +
      t(" 个供应商（google 等协议）仅登记，不支持注入 CLI，未出现在上面的下拉中。") + '</p>' : "");
}

/* ---------------------------------------------------------- 供应商主从视图 */
function renderProvList() {
  const box = $("prov-list");
  if (!box) return;
  const kw = (S.provFilter || "").trim().toLowerCase();
  const kwHit = (p) => !kw ||
    (p.name || "").toLowerCase().includes(kw) ||
    (p.protocol || "").toLowerCase().includes(kw) ||
    (p.source || "").toLowerCase().includes(kw) ||
    (p.base_url || "").toLowerCase().includes(kw);
  const view = S.provStatus || "enabled";
  // 状态过滤默认只看启用（2026-09-30 用户拍板）：停用的点「已停用/全部」chip 才现身
  const stHit = (p) => view === "all" || (view === "off" ? p.enabled === false : p.enabled !== false);
  const hit = (S.providers || []).filter(kwHit);
  const provs = hit.filter(stHit);
  if (!S.selProv && provs.length) S.selProv = provs[0].id;
  if (S.selProv && !provs.some((p) => p.id === S.selProv)) {
    S.selProv = provs.length ? provs[0].id : null;
  }
  // 供应商可能已被（别处）删除，清掉失效的选择
  for (const id of Object.keys(S.selProvs || {})) {
    if (!(S.providers || []).some((p) => p.id === id)) delete S.selProvs[id];
  }
  const selN = Object.keys(S.selProvs || {}).length;
  box.classList.toggle("has-sel", selN > 0);
  const chips = hit.length ? '<div class="cat-chips prov-status">' +
    '<button class="cat-chip' + (view === "enabled" ? " active" : "") + '" onclick="setProvStatus(\'enabled\')">' +
      t("已启用") + " <b>" + hit.filter((p) => p.enabled !== false).length + "</b></button>" +
    '<button class="cat-chip' + (view === "off" ? " active" : "") + '" onclick="setProvStatus(\'off\')">' +
      t("已停用") + " <b>" + hit.filter((p) => p.enabled === false).length + "</b></button>" +
    '<button class="cat-chip' + (view === "all" ? " active" : "") + '" onclick="setProvStatus(\'all\')">' +
      t("全部") + " <b>" + hit.length + "</b></button></div>" : "";
  const batch = selN ? '<div class="prov-batch"><span class="n">' + t("已选 ") + selN + t(" 个") + "</span>" +
    '<button class="ghost small" onclick="batchProvOp(\'enable\')">' + t("启用") + '</button>' +
    '<button class="ghost small" onclick="batchProvOp(\'disable\')">' + t("停用") + '</button>' +
    '<button class="danger small" onclick="batchProvOp(\'delete\')">' + t("删除") + '</button>' +
    '<button class="ghost small" onclick="clearProvSel()">' + t("取消") + '</button></div>' : "";
  const allBox = provs.length ? '<label class="prov-all"><input type="checkbox"' +
    (selN === provs.length && selN > 0 ? " checked" : "") +
    ' onchange="toggleAllProvSel(this.checked)">' + t(" 全选") +
    (kw || view !== "all" ? t("（筛选后 ") + provs.length + t(" 个）") : t("（") + provs.length + t("）")) + "</label>" : "";
  box.innerHTML = chips + batch + allBox + (provs.map((p) => {
    // 卡片计数只数启用中的模型（列表默认也只展示启用中的，两边口径一致）
    const n = p.models == null ? null : p.models.filter((m) => !m.hidden && m.enabled !== false).length;
    const st = n == null ? t("未获取") : n + t(" 模型");
    const off = p.enabled === false;
    return '<div class="prov-item' + (p.id === S.selProv ? " active" : "") + (off ? " off" : "") +
      '" onclick="selectProvider(\'' + jsq(p.id) + '\')">' +
      '<input type="checkbox" class="pi-check"' + (S.selProvs[p.id] ? " checked" : "") +
      ' title="' + t("勾选以批量操作") + '" onclick="event.stopPropagation()"' +
      ' onchange="toggleProvSel(\'' + jsq(p.id) + '\', this.checked)">' +
      '<div class="pi-body"><div class="pi-top"><div class="pi-name">' + esc(p.name) + "</div>" +
      '<span class="pi-n">' + st + "</span></div>" +
      '<div class="pi-meta"><span class="tag">' + esc(protoLabel(p)) + "</span>" +
      (p.protocol === "auto" ? "" : wireCapTags(p, p.protocol)) +
      ((p.keys || []).length > 1 ? '<span class="tag">' + t("%1 把密钥").replace("%1", (p.keys || []).length) + "</span>" : "") +
      (off ? '<span class="tag">' + t("已停用") + "</span>" : "") +
      "</div></div></div>";
  }).join("") ||
    '<div class="hint" style="padding:8px">' + (kw && (S.providers || []).length
      ? t("没有匹配「") + esc(S.provFilter) + t("」的供应商。")
      : (view === "enabled" && hit.some((p) => p.enabled === false)
        ? t("%1 个供应商已停用——点上方「已停用」查看。").replace("%1", hit.filter((p) => p.enabled === false).length)
        : t("暂无供应商——点上方「导入」。"))) + "</div>");
}

function setProvStatus(v) {
  S.provStatus = v;
  S.modelsSig = null;
  renderProvList();   // 可能收敛 S.selProv，详情跟着换人
  renderProvDetail();
}

function toggleProvSel(id, on) {
  S.selProvs = S.selProvs || {};
  if (on) S.selProvs[id] = true; else delete S.selProvs[id];
  S.modelsSig = null;
  renderProvList();
}

function toggleAllProvSel(on) {
  S.selProvs = {};
  if (on) {
    const kw = (S.provFilter || "").trim().toLowerCase();
    const view = S.provStatus || "enabled";
    for (const p of (S.providers || []).filter((p) => (!kw ||
      (p.name || "").toLowerCase().includes(kw) ||
      (p.protocol || "").toLowerCase().includes(kw) ||
      (p.source || "").toLowerCase().includes(kw) ||
      (p.base_url || "").toLowerCase().includes(kw)) &&
      (view === "all" || (view === "off" ? p.enabled === false : p.enabled !== false)))) S.selProvs[p.id] = true;
  }
  S.modelsSig = null;
  renderProvList();
}

function clearProvSel() {
  S.selProvs = {};
  S.modelsSig = null;
  renderProvList();
}

async function batchProvOp(op) {
  const ids = Object.keys(S.selProvs || {});
  if (!ids.length) return;
  const tips = {
    enable: t("启用所选 ") + ids.length + t(" 个供应商？"),
    disable: t("停用所选 ") + ids.length + t(" 个供应商？\n停用后其绑定会回落为 CLI 默认；配置与模型列表都保留，可随时再启用。"),
    delete: t("删除所选 ") + ids.length + t(" 个供应商？\n相关显式模型调度会自动解除，此操作不可撤销。"),
  };
  if (!await uiConfirm(tips[op] || (t("执行「") + op + t("」？")))) return;
  try {
    await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids, op }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  S.selProvs = {};
  S.modelsSig = null;
  poll();
}

function selectProvider(id) {
  if (S.selProv !== id) S.selModels = {};  // 切供应商时清空模型勾选
  S.selProv = id;
  S.modelsSig = null;
  renderProvList();
  renderProvDetail();
}

function renderProvDetail() {
  const box = $("prov-detail");
  if (!box) return;
  if (S.dragging) return;  // 拖拽中不重绘
  const p = (S.providers || []).find((x) => x.id === S.selProv);
  if (!p) {
    box.innerHTML = '<div class="empty">' + t("左侧选择供应商；还没有供应商时点左上角「导入」，") +
      t("可从 CCSwitch / Codex / Claude Code / ZCode / Qwen / Gemini / OpenCode / Continue / Cursor / Trae 扫描带入。") +
      '<br><a href="#" onclick="return helpOpenTopic(\'models\')">' + t("还没配过模型？看「模型接入与绑定」帮助") + '</a></div>';
    return;
  }
  const tp = (S.testProvState || {})[p.id];
  const tpHtml = tp ? (tp.status === "reachable_unverified"
    ? '<span class="badge warn" title="' + esc(tp.note || "") + '">⚠ ' +
      t("可达，密钥未验证") + " · " + tp.latency_ms + "ms</span>"
    : (tp.ok
    ? '<span class="badge ok"' + (tp.note ? ' title="' + esc(tp.note) + '"' : "") + '>' +
      t("✓ 连通 ") + tp.latency_ms + "ms" +
      (tp.note ? " · " + t("无模型列表接口") : " · " + tp.count + t(" 个模型")) + "</span>"
    : '<span class="badge bad" title="' + esc(tp.error || "") + '">✗ ' + esc((tp.error || t("失败")).slice(0, 60)) + "</span>")) : "";
  // 适配测试通过的 wire（同密钥实测可注入的另一条协议面）；形态随徽章标出
  const capTags = wireCapTags(p, "");
  const pb = (S.probeState || {})[p.id];
  const pbHtml = !pb ? "" : (pb.busy
    ? '<span class="badge">' + esc(t("适配测试中…")) + "</span>"
    : (pb.ok ? '<span class="badge ok">' : '<span class="badge bad">') + esc(pb.message || "") + "</span>");
  const bp = p.builtin_process || {};
  const builtinProcessHtml = p.builtin ? (
    bp.state === "started" && bp.managed
      ? '<span class="badge ok" title="' + esc(bp.message || "") + '">✓ ' + t("CodeBee 已托管运行") + "</span>"
      : bp.state === "already_running"
      ? '<span class="badge" title="' + esc(bp.message || "") + '">' + t("检测到外部 standalone") + "</span>"
      : (bp.state === "failed" || bp.state === "unavailable") && bp.error
      ? '<span class="badge warn" title="' + esc(bp.error) + '">' + t("standalone 未启动") + "</span>"
      : "") : "";
  const builtinHtml = p.builtin ? (p.builtin_status === "disabled"
    ? '<span class="badge" title="' + esc(p.builtin_status_message || "") + '">' + t("本地免费服务已手动停用") + "</span>"
    : p.builtin_status === "ready"
    ? '<span class="badge ok" title="' + esc(p.builtin_status_message || "") + '">✓ ' + t("本地免费服务已连接") + "</span>"
    : '<span class="badge warn" title="' + esc(p.builtin_status_message || "") + '">⚠ ' + t("免费模型服务未启动") + "</span>") : "";
  const models = (p.models || []).filter((m) => !m.hidden)
    .sort((a, b) => (a.priority || 0) - (b.priority || 0));
  const hidden = (p.models || []).filter((m) => m.hidden);
  const sel = modelSel(p.id);
  const selN = Object.keys(sel).length;
  let html = '<div class="pd-head">' +
    '<div class="pd-title"><span class="pd-name">' + esc(p.name) + "</span>" +
    '<span class="tag">' + esc(protoLabel(p)) + "</span>" + capTags +
    (p.enabled === false ? '<span class="tag">' + t("已停用") + "</span>" : "") +
    srcTag(p.source) + builtinHtml + builtinProcessHtml + tpHtml + pbHtml + "</div>" +
    '<div class="pd-url" title="' + esc(p.base_url || "") + '">' + esc(p.base_url || "") + "</div>" +
    '<div class="pd-ops">' +
    '<button class="primary small" onclick="testProv(\'' + jsq(p.id) + '\')">' + t("测试连接") + "</button>" +
    '<button class="ghost small" onclick="probeWire(\'' + jsq(p.id) + '\')" title="' +
    esc(t("实测该网关同一密钥是否也支持另一条 wire 协议；通过后绑定链可跨协议注入")) + '">' + t("适配测试") + "</button>" +
    '<button class="ghost small" onclick="refreshProviderModels(\'' + jsq(p.id) + '\')">' + t("获取模型列表") + "</button>" +
    (p.builtin ? "" : '<button class="ghost small" onclick="duplicateProvider(\'' + jsq(p.id) + '\')" title="' + t("复制一份（同地址同密钥，可再换 KEY / 改名）") + '">' + t("复制一份") + "</button>") +
    '<button class="ghost small" onclick="toggleProviderEnabled(\'' + jsq(p.id) + '\', ' +
    (p.enabled === false) + ')">' + (p.enabled === false ? t("启用供应商") : t("停用供应商")) + "</button>" +
    '<span class="pd-ops-gap"></span>' +
    '<button class="danger small" onclick="delProvider(\'' + jsq(p.id) + '\')">' + t("删除") + "</button>" +
    "</div></div>";
  if (selN) {
    html += '<div class="mrow-batch"><span class="n">' + t("已选 ") + selN + t(" 个模型") + "</span>" +
      '<button class="ghost small" onclick="batchModelOp(\'' + jsq(p.id) + '\', \'enable\')">' + t("启用") + '</button>' +
      '<button class="ghost small" onclick="batchModelOp(\'' + jsq(p.id) + '\', \'disable\')">' + t("停用") + '</button>' +
      '<button class="ghost small" onclick="batchModelOp(\'' + jsq(p.id) + '\', \'restore\')">' + t("恢复") + '</button>' +
      '<button class="danger small" onclick="batchModelOp(\'' + jsq(p.id) + '\', \'delete\')">' + t("删除") + '</button>' +
      '<button class="ghost small" onclick="clearModelSel(\'' + jsq(p.id) + '\')">' + t("取消") + '</button></div>';
  }
  html += '<details class="pd-config"><summary>' + t("编辑供应商配置（地址 / 协议 / 难度模型）") + '</summary>' +
    providerCard(p) + "</details>";
  if (p.models == null) {
    html += '<div class="empty">' + t("尚未获取模型列表——点上方「获取模型列表」。") + '</div>' +
      '<div class="hint">' + t("厂商列表接口调不通？直接手工添加模型名也能用。") + '</div>' +
      pmAddHtml(p);
  } else {
    const kw = (S.modelFilter || {})[p.id] || "";
    html += '<div class="pm-tools">' +
      '<input id="pm-search-' + esc(p.id) + '" type="search" placeholder="' + t("按名称过滤模型…") + '" autocomplete="off"' +
      ' value="' + esc(kw) + '" oninput="filterModels(\'' + jsq(p.id) + '\', this.value)">' +
      '<span class="pm-count" id="pm-count-' + esc(p.id) + '"></span>' +
      pmAddHtml(p) + '</div>';
    // 模型列表状态过滤：默认只看启用（与供应商列表同一套 chip 口径）
    const vis = (p.models || []).filter((m) => !m.hidden);
    if (vis.length) {
      const mview = S.mlistStatus || "enabled";
      html += '<div class="cat-chips pm-status">' +
        '<button class="cat-chip' + (mview === "enabled" ? " active" : "") + '" onclick="setModelStatus(\'enabled\')">' +
          t("已启用") + " <b>" + vis.filter((m) => m.enabled !== false).length + "</b></button>" +
        '<button class="cat-chip' + (mview === "off" ? " active" : "") + '" onclick="setModelStatus(\'off\')">' +
          t("已停用") + " <b>" + vis.filter((m) => m.enabled === false).length + "</b></button>" +
        '<button class="cat-chip' + (mview === "all" ? " active" : "") + '" onclick="setModelStatus(\'all\')">' +
          t("全部") + " <b>" + vis.length + "</b></button></div>";
    }
    html += '<div id="pm-groups" class="pm-groups' + (selN ? " has-sel" : "") + '">' +
      provModelGroupsHtml(p) + "</div>";
    if (hidden.length) {
      html += '<details class="prow-hidden"><summary>' + t("已删除 ") + hidden.length +
        t(" 个模型（刷新不会再带回）") + "</summary><div class=\"prow-hidden-list\">";
      for (const m of hidden) {
        html += '<label><input type="checkbox"' + (sel[m.name] ? " checked" : "") +
          ' onchange="toggleModelSel(\'' + jsq(p.id) + '\', \'' + jsq(m.name) + '\', this.checked)">' +
          esc(m.name) + "</label>";
      }
      html += '</div><div class="prow-hidden-ops">' +
        '<button class="ghost small" onclick="batchModelOp(\'' + jsq(p.id) + '\', \'restore\')">' + t("恢复所选") + '</button>' +
        '<button class="ghost small" onclick="restoreHidden(\'' + jsq(p.id) + '\')">' + t("恢复全部") + '</button>' +
        "</div></details>";
    }
  }
  // 密钥区放最下：与模型列表同属「日常不动、偶尔来看」的配置，别挡在模型区前面
  html += p.builtin
    ? '<div class="hint" style="padding:8px">' + t("密钥由本机 standalone 服务管理，不能在 CodeBee 中添加备用 Key。") + "</div>"
    : keyListHtml(p);
  box.innerHTML = html;
  updateModelCount(p.id);
  bindModelRowDnD(p.id, box);
  bindKeyRowDnD(p.id, box);
}

/* ---------------------------------------------------------- 多 KEY（同厂商多密钥）
 * 顺序即调用顺序：欠费/停用的 KEY 被解析自动跳过，切到下一把。 */
function keyListHtml(p) {
  const keys = p.keys || [];
  const single = keys.length <= 1;
  const rows = keys.map((k, i) => {
    const badge = !k.enabled
      ? '<span class="tag">' + t("已停用") + "</span>"
      : (k.cooling
         ? '<span class="tag warn" title="' + esc(k.last_error || "") + '">' + t("冷却中") + "</span>" : "");
    const err = k.last_error
      ? '<span class="hint warn" title="' + esc(k.last_error) + '">✗ ' + esc(k.last_error.slice(0, 40)) + "</span>" : "";
    const inUse = k.enabled && !k.cooling && k.key === p.api_key;
    return '<div class="krow' + (k.enabled ? "" : " off") + '" draggable="true" data-kid="' + esc(k.id) + '">' +
      '<span class="drag" title="' + t("拖动调整调用顺序") + '"><svg class="ico" aria-hidden="true"><use href="#i-grip"></use></svg></span>' +
      '<span class="pprio">#' + (i + 1) + "</span>" +
      '<span class="klabel" title="' + esc(k.label || "") + '">' +
        esc(k.label || t("密钥") + " " + k.id.slice(1)) + "</span>" +
      '<span class="kval hint">' + esc(k.key) + "</span>" +
      (inUse ? '<span class="tag ok">' + t("使用中") + "</span>" : "") + badge + err +
      '<span class="row-ops">' +
      (k.cooling ? '<button class="ghost small row-op" onclick="keyOp(\'' + jsq(p.id) + '\', \'' + jsq(k.id) + '\', \'reset\')" title="' + t("充值后手动恢复（清掉冷却）") + '">' + t("恢复") + "</button>" : "") +
      '<label class="tog-mini" title="' + (k.enabled ? t("停用该密钥（编排自动跳过）") : t("启用")) + '">' +
        '<input type="checkbox" ' + (k.enabled ? "checked" : "") +
        ' onchange="keyOp(\'' + jsq(p.id) + '\', \'' + jsq(k.id) + '\', this.checked ? \'enable\' : \'disable\')"><i></i></label>' +
      '<button class="danger small row-op" onclick="keyOp(\'' + jsq(p.id) + '\', \'' + jsq(k.id) + '\', \'delete\')">' + t("删除") + "</button>" +
      "</span></div>";
  }).join("");
  return '<div class="keys-box"><div class="keys-head"><b>' + t("密钥（按顺序调用，欠费自动切备用）") + "</b>" +
    (single ? '<span class="hint">' + t("点「添加密钥」配备用号") + "</span>" : "") +
    '<button class="ghost small" onclick="promptAddKey(\'' + jsq(p.id) + '\')">＋ ' + t("添加密钥") + "</button></div>" +
    (rows || '<div class="hint" style="padding:4px 8px">' + t("尚未配置密钥") + "</div>") +
    "</div>";
}

function bindKeyRowDnD(pid, root) {
  const box = root.querySelector(".keys-box");
  if (!box) return;
  box.querySelectorAll(".krow").forEach((row) => {
    row.addEventListener("dragstart", () => { S.draggingKey = row.dataset.kid; row.classList.add("dragging"); });
    row.addEventListener("dragend", () => {
      S.draggingKey = null;
      box.querySelectorAll(".krow").forEach((r) => r.classList.remove("dragging", "drag-over"));
    });
    row.addEventListener("dragover", (e) => {
      if (!S.draggingKey || S.draggingKey === row.dataset.kid) return;
      e.preventDefault();
      row.classList.add("drag-over");
    });
    row.addEventListener("dragleave", () => row.classList.remove("drag-over"));
    row.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!S.draggingKey || S.draggingKey === row.dataset.kid) return;
      const p = (S.providers || []).find((x) => x.id === pid);
      const order = (p.keys || []).map((k) => k.id);
      const i = order.indexOf(S.draggingKey), j = order.indexOf(row.dataset.kid);
      if (i < 0 || j < 0) return;
      order.splice(j, 0, order.splice(i, 1)[0]);
      keyReorder(pid, order);
    });
  });
}

async function keyReorder(pid, ids) {
  try {
    await api("/api/models/key-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, op: "reorder", ids }) });
  } catch (e) { toast(t("排序失败：") + e.message, true); }
  poll();
}

/* 「＋ 添加密钥」：两问（密钥、备注名）走应用内弹框，不用原生 prompt */
async function promptAddKey(pid) {
  const key = await uiPrompt(t("新密钥（sk-...）"), "");
  if (key === null) return;
  if (!key.trim()) { toast(t("已取消：密钥为空"), true); return; }
  const label = await uiPrompt(t("备注名（可空，如：备用号）"), "");
  if (label === null) label = "";
  await keyOpCall(pid, "add", "", key.trim(), (label || "").trim());
  toast(t("已添加密钥"));
}

async function keyOpCall(pid, op, keyId, key, label) {
  try {
    await api("/api/models/key-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, op, key_id: keyId, key, label }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  // 操作期间轮询照跑（uiPrompt 弹框不阻塞轮询），S.modelsSig 还是旧值：必须
  // 清签名强制重绘，否则 KEY 写盘成功界面也看不到。
  S.modelsSig = null;
  await poll();
}

async function keyOp(pid, keyId, op) {
  if (op === "delete" && !await uiConfirm(t("删除该密钥？（不影响其它密钥）"),
      { danger: true, ok: t("删除") })) return;
  await keyOpCall(pid, op, keyId);
}

async function duplicateProvider(pid) {
  try {
    const r = await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids: [pid], op: "duplicate" }) });
    if (r.ok) toast(t("已复制供应商（启用状态，绑定不随带）"));
  } catch (e) { toast(t("复制失败：") + e.message, true); }
  poll();
}

/* 多 wire 网关的「另一条协议面」徽章：适配测试实测通过、又不是当前分组的 wire。
 * 同一份模型列表在两条 wire 上都能注入（解析走适配端点），列表不重复摆两份，
 * 但得把另一面亮出来——否则页面看上去只有一种协议能用，OpenAI 面永远被忽略。
 * 形态必须标出：chat 形态除 codex 外都能用（codex 0.154+ 只讲 responses），
 * 不标的话模型接入页一片 ✓、codex 链上却 ⚠ 协议不匹配，两个页面自相矛盾。 */
function wireCapTags(p, excludeProto) {
  return Object.keys((p || {}).wire_caps || {}).filter((pr) => pr !== excludeProto).map((pr) => {
    const cap = (p.wire_caps || {})[pr] || {};
    const chat = (cap.wire_api || "responses") === "chat";
    const tip = (chat
      ? t("适配测试实测：该面为 chat 形态——除 codex 外的 openai 系 CLI 可用；codex 只讲 responses，链上注入会被跳过")
      : t("适配测试实测：同密钥也可走 {0} wire——这组模型同样可注入 {0} 系 CLI（codex/dsh 等），运行时自动走适配端点", pr)) +
      (cap.checked_at ? " · " + cap.checked_at : "");
    return '<span class="tag ok" title="' + esc(tip) + '">' +
      esc(pr) + " ✓" + (chat ? " · chat" : "") + "</span>";
  }).join("");
}

/* 模型分组区 HTML（全量重绘与过滤重绘共用；过滤时暂停拖拽排序） */
function provModelGroupsHtml(p) {
  const kw = ((S.modelFilter || {})[p.id] || "").trim().toLowerCase();
  const mview = S.mlistStatus || "enabled";
  const models = (p.models || []).filter((m) => !m.hidden)
    .filter((m) => mview === "all" || (mview === "off" ? m.enabled === false : m.enabled !== false))
    .filter((m) => !kw || (m.name || "").toLowerCase().includes(kw))
    .sort((a, b) => (a.priority || 0) - (b.priority || 0));
  const sel = modelSel(p.id);
  const groups = {};
  for (const m of models) {
    const g = m.protocol || p.protocol || t("其他");
    (groups[g] = groups[g] || []).push(m);
  }
  const gnames = Object.keys(groups).sort();
  if (!gnames.length) {
    const offAll = (p.models || []).filter((m) => !m.hidden && m.enabled === false).length;
    const msg = kw
      ? t("没有匹配「") + esc(kw) + t("」的模型。")
      : mview === "off"
        ? t("没有已停用的模型。")
        : (mview === "enabled" && offAll
          ? t("%1 个模型已停用——点上方「已停用」查看。").replace("%1", offAll)
          : t("该供应商没有可用模型（或全部被停用）。"));
    return '<div class="empty">' + msg + "</div>";
  }
  let html = "";
  for (const g of gnames) {
    const gm = groups[g];
    const allSel = gm.every((m) => sel[m.name]);
    html += '<div class="pgroup"><div class="pgroup-title">' +
      '<label class="pcheck-all"><input type="checkbox"' + (allSel ? " checked" : "") +
      ' onchange="toggleGroupSel(\'' + jsq(p.id) + '\', \'' + jsq(g) + '\', this.checked)">' + t("全选") + '</label>' +
      esc(g) + t(" 协议 · ") + gm.length + t(" 个") +
      wireCapTags(p, g) +
      (kw ? t("（过滤中，拖拽排序暂停）") : t("（拖动 ☰ 调序；启用的排最前）")) + "</div>";
    for (const m of gm) html += provModelRow(p.id, m, g);
    html += "</div>";
  }
  return html;
}

/* 搜索框输入：只重绘分组区，避免输入框失焦 */
function filterModels(pid, val) {
  S.modelFilter = S.modelFilter || {};
  S.modelFilter[pid] = val;
  const p = (S.providers || []).find((x) => x.id === pid);
  const gbox = $("pm-groups");
  if (p && gbox) {
    gbox.innerHTML = provModelGroupsHtml(p);
    bindModelRowDnD(pid, gbox);
  }
  updateModelCount(pid);
}

function updateModelCount(pid) {
  const el = $("pm-count-" + pid);
  const p = (S.providers || []).find((x) => x.id === pid);
  if (!el || !p || !p.models) return;
  const kw = (S.modelFilter || {})[pid] || "";
  const mview = S.mlistStatus || "enabled";
  const inView = (m) => !m.hidden &&
    (mview === "all" || (mview === "off" ? m.enabled === false : m.enabled !== false));
  const total = p.models.filter(inView).length;
  const shown = total && kw.trim()
    ? p.models.filter((m) => inView(m) &&
        (m.name || "").toLowerCase().includes(kw.trim().toLowerCase())).length
    : total;
  el.textContent = kw.trim() ? (shown + " / " + total + t(" 个模型")) : (total + t(" 个模型"));
}

function bindModelRowDnD(pid, root) {
  root.querySelectorAll(".prow").forEach((row) => {
    row.addEventListener("dragstart", (e) => {
      S.dragging = { group: row.dataset.group, name: row.dataset.name };
      row.classList.add("dragging");
      if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
    });
    row.addEventListener("dragend", () => {
      S.dragging = false;
      row.classList.remove("dragging");
      root.querySelectorAll(".prow").forEach((r) => r.classList.remove("drag-over"));
    });
    row.addEventListener("dragover", (e) => {
      if (!S.dragging || S.dragging.group !== row.dataset.group) return;
      e.preventDefault();
      row.classList.add("drag-over");
    });
    row.addEventListener("dragleave", () => row.classList.remove("drag-over"));
    row.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!S.dragging || S.dragging.group !== row.dataset.group) return;
      moveModelInGroup(pid, row.dataset.group, S.dragging.name, row.dataset.name);
    });
  });
}

function provModelRow(pid, m, group) {
  const key = pid + "|" + m.name;
  const tm = (S.testModelState || {})[key];
  const tmHtml = tm ? (tm.ok
    ? '<span class="badge ok">✓ ' + tm.latency_ms + "ms</span>"
    : '<span class="badge bad" title="' + esc(tm.error || "") + '">✗ ' +
      esc((tm.error || "").slice(0, 24)) + "</span>") : "";
  const price = (m.price_in != null && m.price_out != null)
    ? '<span class="hint">¥' + esc(m.price_in) + "/¥" + esc(m.price_out) + "</span>" : "";
  const priceBtn = '<span class="tag" title="' + t("手标单价（¥/百万 tokens），台账记账与花费预算按此折算") + '"' +
    ' onclick="editModelPrice(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\')">' + t("价") + "</span>";
  const imgcap = '<span class="tag imgcap' + (m.image_in ? " ok" : "") + '" title="' +
    (m.image_in ? t("支持图片输入，点击关闭")
                : t("纯文本模型，点击开启图片输入（内置智能体传图以此为准）")) + '"' +
    ' onclick="toggleModelImage(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\')">' + t("图") + "</span>";
  const sel = modelSel(pid);
  return '<div class="prow' + (m.enabled ? "" : " off") + '" draggable="true" data-group="' +
    esc(group) + '" data-name="' + esc(m.name) + '">' +
    '<input type="checkbox" class="pcheck"' + (sel[m.name] ? " checked" : "") +
    ' title="' + t("勾选以批量操作") + '"' +
    ' onchange="toggleModelSel(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\', this.checked)">' +
    '<span class="drag" title="' + t("拖动调整优先级") + '"><svg class="ico" aria-hidden="true"><use href="#i-grip"></use></svg></span>' +
    '<span class="pprio">#' + m.priority + "</span>" +
    '<span class="pname" title="' + esc(m.name) + '">' + esc(m.name) + "</span>" +
    price + priceBtn + imgcap + tmHtml +
    '<span class="row-ops">' +
    '<button class="ghost small row-op" onclick="testModelBtn(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\')">' + t("测试") + '</button>' +
    '<button class="danger small row-op" title="' + t("从列表删除：刷新/重新导入不会再带回，可在分组底部恢复") + '"' +
    ' onclick="delModel(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\')">' + t("删除") + '</button>' +
    '<label class="tog-mini" title="' + (m.enabled ? t("停用（不影响配置，仅编排选模跳过）") : t("启用")) + '">' +
    '<input type="checkbox" ' + (m.enabled ? "checked" : "") +
    ' onchange="modelOp(\'' + jsq(pid) + '\', \'' + jsq(m.name) + '\', this.checked ? \'enable\' : \'disable\')"><i></i></label>' +
    "</span></div>";
}

function moveModelInGroup(pid, group, fromName, toName) {
  const p = (S.providers || []).find((x) => x.id === pid);
  if (!p || !p.models) return;
  // 组内顺序调整后，按分组展示顺序重排该供应商全部模型的优先级
  const groups = {};
  for (const m of (p.models || []).filter((x) => !x.hidden)
      .sort((a, b) => (a.priority || 0) - (b.priority || 0))) {
    const g = m.protocol || p.protocol || t("其他");
    (groups[g] = groups[g] || []).push(m.name);
  }
  const arr = groups[group] || [];
  const i = arr.indexOf(fromName), j = arr.indexOf(toName);
  if (i < 0 || j < 0) return;
  arr.splice(j, 0, arr.splice(i, 1)[0]);
  groups[group] = arr;
  const names = Object.keys(groups).sort().reduce((acc, g) => acc.concat(groups[g]), []);
  api("/api/models/reorder", { method: "POST",
    body: JSON.stringify({ provider_id: pid, names }) })
    .then(poll).catch((e) => toast(t("排序失败：") + e.message, true));
}

async function testProv(pid) {
  S.testProvState = S.testProvState || {};
  S.testProvState[pid] = { ok: false, error: t("测试中…") };
  renderProvDetail();
  try {
    S.testProvState[pid] = await api("/api/models/test-provider",
      { method: "POST", body: JSON.stringify({ id: pid }) });
  } catch (e) { S.testProvState[pid] = { ok: false, error: e.message }; }
  S.modelsSig = null;
  renderModels();
}

async function testModelBtn(pid, name) {
  S.testModelState = S.testModelState || {};
  const key = pid + "|" + name;
  S.testModelState[key] = { ok: false, error: t("测试中…") };
  renderProvDetail();
  try {
    S.testModelState[key] = await api("/api/models/test-model",
      { method: "POST", body: JSON.stringify({ provider_id: pid, name }) });
  } catch (e) { S.testModelState[key] = { ok: false, error: e.message }; }
  S.modelsSig = null;
  renderModels();
}

/* 适配测试：实测该网关同一密钥是否也支持另一条 wire 协议（结果存 wire_caps，
 * 绑定链/默认绑定的解析随之放宽）。「获取模型列表」成功后后端也会自动测一次。 */
async function probeWire(pid) {
  S.probeState = S.probeState || {};
  S.probeState[pid] = { busy: true };
  renderProvDetail();
  try {
    const res = await api("/api/models/probe-wire",
      { method: "POST", body: JSON.stringify({ id: pid }) });
    const names = Object.keys(res.wire_caps || {});
    S.probeState[pid] = names.length
      ? { ok: true, message: t("已适配：") + names.map((n) => n + " wire").join(t("、")) }
      : { ok: false, message: t("未发现可适配的 wire") + (res.note ? t("：") + res.note : "") };
  } catch (e) { S.probeState[pid] = { ok: false, message: e.message }; }
  S.modelsSig = null;
  renderModels();
  poll();  // wire_caps 已落盘：拉最新供应商状态，绑定页徽标同步
}

async function modelOp(pid, name, op) {
  try {
    await api("/api/models/model-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, name, op }) });
    const s = modelSel(pid);            // 单行操作后同步清掉该行勾选
    if (s[name]) { delete modelSelSet(pid)[name]; }
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  S.modelsSig = null;
  poll();
}

function toggleModelImage(pid, name) {
  const p = (S.providers || []).find((x) => x.id === pid);
  const m = p && (p.models || []).find((x) => x.name === name);
  api("/api/models/model-caps", { method: "POST",
    body: JSON.stringify({ provider_id: pid, name, image_in: !(m && m.image_in) }) })
    .then(() => { S.modelsSig = null; poll(); })
    .catch((e) => toast(t("保存失败：") + e.message, true));
}

/* 手标模型单价（¥/百万 tokens）：台账记账与花费预算按此折算；清空=回落价表 */
function editModelPrice(pid, name) {
  const p = (S.providers || []).find((x) => x.id === pid);
  const m = p && (p.models || []).find((x) => x.name === name);
  const body = '<p class="hint">' +
    t("单价按 ¥/百万 tokens 填（输入价/输出价）。手标优先于导入价表；台账「费用」列与花费预算按它折算——不标则不记账。") + "</p>" +
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("输入单价 ¥/M") + '</label><input id="mp-in" type="number" step="0.01" min="0" value="' +
      (m && m.price_in != null ? m.price_in : "") + '"></div>' +
    '<div class="field"><label>' + t("输出单价 ¥/M") + '</label><input id="mp-out" type="number" step="0.01" min="0" value="' +
      (m && m.price_out != null ? m.price_out : "") + '"></div></div>';
  openModal(t("标定单价：") + name, body,
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>' +
    '<button class="primary" onclick="saveModelPrice(\'' + jsq(pid) + '\', \'' + jsq(name) + '\')">' + t("保存") + '</button>');
}

async function saveModelPrice(pid, name) {
  try {
    await api("/api/models/set-price", { method: "POST", body: JSON.stringify({
      provider_id: pid, name,
      price_in: ($("mp-in") || {}).value ?? "", price_out: ($("mp-out") || {}).value ?? "" }) });
    closeModal();
    S.modelsSig = null; S.providers = null;
    poll();
    toast(t("单价已标定"));
  } catch (e) { toast(t("保存失败：") + e.message, true); }
}

/* 反查模型是否声明图片输入（绑定页 chip/列表只读徽标用） */
function modelHasImage(pid, name) {
  const p = (S.providers || []).find((x) => x.id === pid);
  return !!(p && (p.models || []).some((x) => x.name === name && x.image_in));
}

/* ---- 模型批量选择 ---- */
function toggleModelSel(pid, name, on) {
  const s = modelSelSet(pid);
  if (on) s[name] = true; else delete s[name];
  S.modelsSig = null;
  renderProvDetail();
  renderProvList();
}

function toggleGroupSel(pid, group, on) {
  const p = (S.providers || []).find((x) => x.id === pid);
  if (!p) return;
  const kw = ((S.modelFilter || {})[pid] || "").trim().toLowerCase();
  const mview = S.mlistStatus || "enabled";
  const s = modelSelSet(pid);
  for (const m of p.models || []) {
    if (m.hidden) continue;
    if (mview !== "all" && (mview === "off" ? m.enabled !== false : m.enabled === false)) continue;
    if ((m.protocol || p.protocol || t("其他")) !== group) continue;
    if (kw && !(m.name || "").toLowerCase().includes(kw)) continue;  // 过滤时只作用于可见行
    if (on) s[m.name] = true; else delete s[m.name];
  }
  S.modelsSig = null;
  renderProvDetail();
}

/* 模型列表状态过滤 chip：默认只看启用 */
function setModelStatus(v) {
  S.mlistStatus = v;
  S.modelsSig = null;
  renderProvDetail();
}

function clearModelSel(pid) {
  if (S.selModels) delete S.selModels[pid];
  S.modelsSig = null;
  renderProvDetail();
  renderProvList();
}

async function batchModelOp(pid, op) {
  const names = Object.keys(modelSel(pid));
  if (!names.length) return;
  const tips = {
    enable: t("启用所选 ") + names.length + t(" 个模型？"),
    disable: t("停用所选 ") + names.length + t(" 个模型？\n停用只影响编排选模，不删除配置。"),
    delete: t("删除所选 ") + names.length + t(" 个模型？\n刷新 / 重新导入都不会再带回，可在「已删除」里恢复。"),
    restore: t("恢复所选 ") + names.length + t(" 个模型？\n它们会重新启用并自动置顶。"),
  };
  if (!await uiConfirm(tips[op] || (t("执行「") + op + t("」？")))) return;
  try {
    await api("/api/models/model-op", { method: "POST",
      body: JSON.stringify({ provider_id: pid, names, op }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  clearModelSel(pid);
  poll();
}

async function delModel(pid, name) {
  if (!await uiConfirm(t("删除模型「") + name + t("」？\n刷新 / 重新导入模型列表都不会再带回，可在分组底部「恢复全部」找回。"), { ok: t("删除"), danger: true })) return;
  modelOp(pid, name, "delete");
}

async function toggleProviderEnabled(pid, enabled) {
  const p = (S.providers || []).find((x) => x.id === pid) || {};
  const off = p.enabled === false;
  if (!off && !await uiConfirm(t("停用供应商「") + (p.name || pid) +
      t("」？\n停用后它的绑定会回落为 CLI 默认；配置与模型列表保留，可随时再启用。"), { ok: t("停用") })) return;
  try {
    await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids: [pid], op: off ? "enable" : "disable" }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  S.modelsSig = null;
  poll();
}

async function restoreHidden(pid) {
  if (!await uiConfirm(t("恢复该供应商下全部已删除的模型？\n它们会回到优先级末尾。"), { ok: t("恢复") })) return;
  modelOp(pid, "", "restore-all");
}

async function refreshAllModels() {
  // 按钮内是 SVG 图标，不能用 textContent 改文案（会抹掉图标）；
  // 加载态用 class 驱动图标旋转，结束时移除
  const btn = $("btn-refresh-models");
  btn.disabled = true; btn.classList.add("loading"); btn.title = t("正在刷新全部模型列表…");
  try {
    const r = await api("/api/models/refresh-all", { method: "POST" });
    btn.title = r.message || t("正在刷新…");
  } catch (e) { toast(t("刷新失败：") + e.message, true); }
  setTimeout(() => {
    btn.disabled = false; btn.classList.remove("loading");
    btn.title = t("全部重新拉取模型列表");
  }, 1500);
  setTimeout(poll, 2500);
}

/* 手工添加模型：有的厂商列表接口调不通（或只返回部分），直接填模型名也能进列表。
 * 后端打 manual 标记，之后刷新即使厂商列表里没有它也不丢。 */
function pmAddHtml(p) {
  return '<div class="pm-add">' +
    '<input id="pm-add-' + esc(p.id) + '" type="text" autocomplete="off" spellcheck="false"' +
    ' placeholder="' + t("手工添加模型名（列表接口调不通时用），回车添加") + '"' +
    ' onkeydown="pmAddKey(event, \'' + jsq(p.id) + '\')">' +
    '<button class="ghost small" title="' + esc(t("厂商列表接口调不通时，直接把模型名加进列表")) + '"' +
    ' onclick="addModelManual(\'' + jsq(p.id) + '\')">' +
    '<svg class="ico" aria-hidden="true"><use href="#i-plus"/></svg>' + t("添加") + '</button></div>';
}

function pmAddKey(ev, pid) {
  if (ev.key === "Enter") { ev.preventDefault(); addModelManual(pid); }
}

async function addModelManual(pid) {
  const inp = $("pm-add-" + pid);
  const name = ((inp && inp.value) || "").trim();
  if (!name) { toast(t("先填模型名"), true); return; }
  try {
    const r = await api("/api/models/add", { method: "POST", body: JSON.stringify({ id: pid, name }) });
    if (!r.ok) { toast(t("添加失败：") + (r.message || ""), true); return; }
    toast(t("已添加模型 ") + name);
    S.modelsSig = null;   // 新模型落盘后签名必变，这里主动置空确保立刻重绘
    poll();
  } catch (e) { toast(t("添加失败：") + e.message, true); }
}

async function refreshProviderModels(id) {
  toast(t("正在获取模型列表…"));
  try {
    const r = await api("/api/models/refresh", { method: "POST", body: JSON.stringify({ id }) });
    if (!r.ok && r.message) toast(t("获取失败：") + r.message, true);
    else if (r.note) toast(r.note);   // 网关无模型列表接口（404）：良性提示，不算失败
    else toast(t("已获取模型列表 · wire 适配测试后台进行中"));
  } catch (e) { toast(t("获取失败：") + e.message, true); }
  poll();
}

/* 供应商编辑卡：协议可选「自动」；显式选定时它是主协议（用于需要唯一协议的
 * 场景，如 opencode 配置生成），auto 则完全按实测能力集（wire_caps）走。 */
function providerCard(p) {
  const fld = (id, label, val, ph, full) =>
    '<div class="field' + (full ? " full" : "") + '"><label>' + label + '</label>' +
    '<input id="' + id + '" value="' + esc(val) + '" placeholder="' + esc(ph) + '"></div>';
  const cur = p.protocol || "auto";
  const protoSel =
    '<div class="field"><label>' + t("协议") + '</label><select id="pproto-' + esc(p.id) + '">' +
    [["auto", t("自动（按实测能力集）")],
     ["anthropic", "anthropic"],
     ["openai", "openai"],
     ["google", t("google（仅登记）")]].map(([v, label]) =>
      '<option value="' + v + '"' + (cur === v ? " selected" : "") + ">" + esc(label) + "</option>").join("") +
    "</select></div>";
  const managedUrl = p.builtin
    ? '<div class="field full"><label>' + t("API 地址（standalone 管理）") + '</label>' +
      '<input id="purl-' + esc(p.id) + '" value="' + esc(p.base_url) + '" readonly></div>'
    : fld("purl-" + p.id, t("API 地址"), p.base_url, "base_url", true);
  return '<div class="card" id="pcard-' + esc(p.id) + '">' +
    '<div class="head"><span class="name">' + esc(p.name) + '</span><span class="tag">' + esc(cur) + "</span>" +
    srcTag(p.source) + "</div>" +
    '<div class="fields grid">' +
    fld("pname-" + p.id, t("名称"), p.name, t("名称")) +
    protoSel +
    fld("pmodel-" + p.id, t("默认模型"), p.model || "", t("默认模型")) +
    managedUrl +
    (p.builtin
      ? '<div class="field full"><label>' + t("API 密钥（standalone 管理）") + '</label>' +
        '<input value="' + esc(p.api_key || t("未设置")) + '" readonly></div>'
      : fld("pkey-" + p.id, t("首选密钥（填了=替换 #1；备用号在下方密钥区添加）"), "", t("（") + (p.api_key || t("未设置")) + t("，留空=不改）"), true)) +
    fld("peasy-" + p.id, t("简单任务模型"), p.model_easy || "", t("难度路由 · 简单")) +
    fld("phard-" + p.id, t("困难任务模型"), p.model_hard || "", t("难度路由 · 困难")) +
    "</div>" +
    (p.builtin
      ? '<p class="hint">' + t("该供应商由 dsh-our-free-model standalone 管理，端点和密钥只从本机服务读取。") + '</p>'
      : "") +
    (cur === "auto"
      ? '<p class="hint">' + t("协议=自动：该网关支持哪些 wire 由「适配测试」实测决定（上方能力标签）。") + '</p>' : "") +
    '<div class="ops"><button class="ghost small" onclick="saveProvider(\'' + jsq(p.id) + '\')">' + t("保存") + '</button>' +
    '<button class="danger small" onclick="delProvider(\'' + jsq(p.id) + '\')">' + t("删除") + '</button></div></div>';
}

async function saveProvider(id) {
  const body = {
    id, name: $("pname-" + id).value.trim(),
    protocol: ($("pproto-" + id) || {}).value || "auto",
    base_url: $("purl-" + id).value.trim(),
    api_key: (($('pkey-' + id) || {}).value || "").trim(),
    model: $("pmodel-" + id).value.trim(),
    model_easy: $("peasy-" + id).value.trim(),
    model_hard: $("phard-" + id).value.trim(),
  };
  try { await api("/api/models/provider", { method: "POST", body: JSON.stringify(body) }); }
  catch (e) { toast(t("保存失败：") + e.message, true); }
  poll();
}

async function delProvider(id) {
  if (!await uiConfirm(t("删除该供应商（绑定会自动解绑）？"), { ok: t("删除"), danger: true })) return;
  try {
    await api("/api/models/provider-op", { method: "POST",
      body: JSON.stringify({ ids: [id], op: "delete" }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); }
  if (S.selModels) delete S.selModels[id];
  if (S.selProvs) delete S.selProvs[id];
  S.modelsSig = null;
  poll();
}

/* 「＋」手动添加供应商：弹框表单（替代原来的多段 prompt）。
 * 协议默认「自动」——聚合网关一个密钥常同时开多条 wire，保存后由后台探测
 * 分类（wire_caps），不必先问用户。 */
function openAddProviderDialog() {
  const protoOpts =
    '<option value="auto">' + t("自动探测（推荐 · 聚合网关多协议都开）") + '</option>' +
    '<option value="anthropic">' + t("anthropic（Claude 系）") + '</option>' +
    '<option value="openai">' + t("openai（Codex / 通用）") + '</option>' +
    '<option value="google">' + t("google（Gemini，仅登记不支持注入）") + '</option>';
  openModal(t("添加供应商"),
    '<div class="form">' +
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("名称 *") + '</label><input id="np-name" placeholder="' + t("例：公司网关") + '"></div>' +
    '<div class="field"><label>' + t("协议") + '</label><select id="np-proto">' + protoOpts + "</select></div>" +
    "</div>" +
    '<div class="field"><label>' + t("API 地址 *") + '</label>' +
    '<input id="np-url" placeholder="' + t("https://host/v1（若填 /chat/completions 会自动收敛为基址）") + '"></div>' +
    '<div class="field"><label>' + t("API 密钥") + '</label>' +
    '<input id="np-key" placeholder="' + t("sk-...（可留空，稍后补填）") + '"></div>' +
    '<div class="grid-3">' +
    '<div class="field"><label>' + t("默认模型") + '</label><input id="np-model" placeholder="' + t("可留空") + '"></div>' +
    '<div class="field"><label>' + t("简单任务模型") + '</label><input id="np-easy" placeholder="' + t("可留空") + '"></div>' +
    '<div class="field"><label>' + t("困难任务模型") + '</label><input id="np-hard" placeholder="' + t("可留空") + '"></div>' +
    "</div>" +
    '<p class="hint">' + t("保存后会自动拉取模型列表并探测该网关支持的 wire 协议（未填密钥时跳过）；探测结果决定哪些 CLI 能用它。") + '</p>' +
    '<div id="add-result" class="msg"></div>' +
    "</div>",
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>' +
    '<span class="spacer"></span>' +
    '<button class="primary" id="btn-do-add" onclick="doAddProvider()">' + t("保存") + '</button>');
  setTimeout(() => { const el = $("np-name"); if (el) el.focus(); }, 0);
}

async function doAddProvider() {
  const res = $("add-result");
  const body = {
    name: $("np-name").value.trim(),
    protocol: $("np-proto").value,
    base_url: $("np-url").value.trim(),
    api_key: $("np-key").value.trim(),
    model: $("np-model").value.trim(),
    model_easy: $("np-easy").value.trim(),
    model_hard: $("np-hard").value.trim(),
  };
  if (!body.name) { res.textContent = t("请填写名称"); return; }
  if (!/^https?:\/\//.test(body.base_url)) { res.textContent = t("API 地址必须以 http:// 或 https:// 开头"); return; }
  const btn = $("btn-do-add");
  btn.disabled = true; btn.textContent = t("保存中…");
  try {
    await api("/api/models/provider", { method: "POST", body: JSON.stringify(body) });
    const r = await api("/api/models");
    const p = (r.providers || []).find((x) => x.name === body.name);
    S.selProv = p ? p.id : null;
    S.modelsSig = null;
    closeModal();
    poll();
    if (p && body.api_key) refreshProviderModels(p.id);  // 有密钥才自动拉模型列表
  } catch (e) {
    res.textContent = t("保存失败：") + e.message;
    btn.disabled = false; btn.textContent = t("保存");
  }
}

/* 「导入」：扫描本机各 AI 工具配置，勾选后可一次导入 */
async function openImportDialog() {
  openModal(t("导入供应商"), '<div class="hint">' + t("正在扫描本机 AI 工具配置…") + '</div>',
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>');
  let data;
  try {
    data = await api("/api/models/sources", { busy: true });
  } catch (e) {
    $("modal-body").innerHTML = '<div class="msg bad">' + t("扫描失败：") + esc(e.message) + "</div>";
    return;
  }
  const srcs = data.sources || [];
  const usable = srcs.filter((s) => s.found && s.count > 0);
  const rows = srcs.map((s) => {
    const ok = s.found && s.count > 0;
    let status;
    if (!s.found) status = '<span class="badge">' + t("未找到") + '</span>';
    else if (s.error) status = '<span class="badge bad">' + t("解析失败") + '</span>';
    else if (s.count > 0) status = '<span class="badge ok">' + t("发现 ") + s.count + t(" 个") + "</span>";
    else status = '<span class="badge">' + t("无可用配置") + '</span>';
    return '<label class="src-row' + (ok ? "" : " disabled") + '">' +
      '<input type="checkbox" value="' + esc(s.id) + '"' + (ok ? " checked" : " disabled") +
      (ok ? ' onchange="updateImportSelHint()"' : "") + ">" +
      '<div class="src-main">' +
      '<div class="src-name">' + esc(t(s.name)) + status + "</div>" +
      '<div class="src-desc">' + esc(t(s.desc)) + "</div>" +
      '<div class="src-path">' + esc((s.paths || []).join("  ·  ")) + "</div>" +
      (s.note ? '<div class="src-note">' + esc(t.apply(null, [s.note].concat(s.note_args || []))) + "</div>" : "") +
      (s.error ? '<div class="src-note bad">' + esc(s.error) + "</div>" : "") +
      "</div></label>";
  }).join("");
  $("modal-body").innerHTML =
    '<p class="hint">' + t("勾选要导入的来源。导入只读取这些工具的配置，不会改动它们本身；") +
    t("已导入过的供应商会原地更新（保留你设置的模型与启停状态）。") + "</p>" +
    '<div class="src-list">' + (rows || '<div class="hint">' + t("没有可扫描的来源。") + '</div>') + "</div>" +
    '<div id="import-result" class="import-result"></div>';
  $("modal-foot").innerHTML =
    '<span class="hint" id="import-sel-hint"></span>' +
    '<span class="spacer"></span>' +
    '<button class="ghost" onclick="toggleAllSources(true)">' + t("全选") + '</button>' +
    '<button class="ghost" onclick="toggleAllSources(false)">' + t("全不选") + '</button>' +
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>' +
    '<button class="primary" id="btn-do-import" onclick="doImport()"' +
    (usable.length ? "" : " disabled") + ">" + t("导入选中") + "</button>";
  updateImportSelHint();
}

function importSelBoxes() {
  return Array.from(document.querySelectorAll("#modal-body .src-row input[type=checkbox]:not(:disabled)"));
}

function updateImportSelHint() {
  const el = $("import-sel-hint");
  if (!el) return;
  const boxes = importSelBoxes();
  const n = boxes.filter((b) => b.checked).length;
  el.textContent = t("已选 ") + n + " / " + boxes.length + t(" 个来源");
  const btn = $("btn-do-import");
  if (btn && btn.textContent === t("导入选中")) btn.disabled = !n;
}

function toggleAllSources(on) {
  importSelBoxes().forEach((b) => { b.checked = on; });
  updateImportSelHint();
}

async function doImport() {
  const ids = importSelBoxes().filter((b) => b.checked).map((b) => b.value);
  if (!ids.length) { toast(t("请至少选择一个来源。"), true); return; }
  const btn = $("btn-do-import");
  const boxes = importSelBoxes();
  boxes.forEach((b) => { b.disabled = true; });
  btn.disabled = true; btn.textContent = t("导入中…");
  try {
    const r = await api("/api/models/import", { method: "POST", body: JSON.stringify({ sources: ids }) });
    const lines = (r.sources || []).map((s) => {
      if (!s.found) return "<li>" + esc(s.name) + t("：未找到配置") + "</li>";
      if (s.error) return "<li>" + esc(s.name) + t("：") + '<span class="bad">' + esc(s.error) + "</span></li>";
      let txt = t("新增 ") + s.added + t("，更新 ") + s.updated;
      if (s.duplicate) txt += t("，跳过重复 ") + s.duplicate;
      const extra = s.note ? t("（") + esc(t.apply(null, [s.note].concat(s.note_args || []))) + t("）") : "";
      return "<li>" + esc(s.name) + t("：") + txt + extra + "</li>";
    }).join("");
    $("import-result").innerHTML =
      '<div class="import-done"><b>' + esc(r.message) + "</b><ul>" + lines + "</ul></div>";
    btn.textContent = t("完成");
    btn.disabled = false;
    btn.onclick = closeModal;
    if (r.imported) { S.selProv = null; S.modelsSig = null; poll(); }
  } catch (e) {
    $("import-result").innerHTML = '<div class="msg bad">' + t("导入失败：") + esc(e.message) + "</div>";
    btn.disabled = false; btn.textContent = t("导入选中");
    boxes.forEach((b) => { b.disabled = false; });
    updateImportSelHint();
  }
}

async function saveBinding(id) {
  const st = bindSelById(id);
  const provSel = $("bindprov-" + id);
  // 主供应商跟链首走：模型链是唯一真源，链首非空时供应商下拉必须与之一致
  // （下拉是旧状态时把旧值发上去，后端「显式指定」就会盖回停用的旧供应商）。
  // 空链时保留下拉选择：这是“只锁定供应商，模型按该供应商默认/难度选”的
  // 合法显式覆盖，不能重置成自动模式。
  const headP = st.chain.length ? st.chain[0].p : (provSel ? provSel.value : "");
  if (st.chain.length && provSel && provSel.value !== (headP || "")) {
    provSel.value = headP || "";
  }
  try {
    await api("/api/models/binding", { method: "POST", body: JSON.stringify({
      agent_id: id, provider_id: provSel ? provSel.value : "",
      chain: st.chain.map((c) => ({ provider_id: c.p, model: c.m })),
      difficulty_routing: $("binddiff-" + id).checked }) });
    st.dirty = false;
    st.key = chainKey(st.chain);
  } catch (e) {
    toast(t("保存失败：") + e.message, true);
    return;
  }
  poll();
}

/* ---------------------------------------------------------- 任务表单 */
function renderImplSelects() {
  // 演示智能体（mock）不上选择器：手动编排不该误选到它。
  // 仅当本机一个真实智能体都没有时才回退显示（全新用户仍可零消耗试用）
  const all = (S.state && S.state.agents) || [];
  const real = all.filter((a) => a.mode !== "mock");
  const agents = real.length ? real : all;
  const sel = $("f-impl");
  const prev = sel.value;
  sel.innerHTML = agents.map((a) =>
    '<option value="' + esc(a.id) + '">' + esc(a.label) + "</option>").join("");
  if (prev && agents.some((a) => a.id === prev)) sel.value = prev;

  // 继续会话：已安装且支持会话扫描的 CLI（不要求启用编排——续会话是显式指定）
  const rsel = $("f-resume-agent");
  const rprev = rsel.value;
  const rAgents = (S.catalog || []).filter((e) =>
    e.installed && e.orch_kind && S.sessionAgents.has(e.id));
  rsel.innerHTML = '<option value="">' + t("不沿用（全新开始）") + '</option>' +
    rAgents.map((e) => '<option value="' + esc(e.id) + '">' + esc(e.name) + t(" 的会话") + "</option>").join("");
  if (rprev && rAgents.some((e) => e.id === rprev)) rsel.value = rprev;

  const box = $("critic-box");
  if (flowById($("f-type").value)?.engine === "review") {
    box.classList.remove("hidden");
    const saved = new Set(Array.from($("f-critics").querySelectorAll("input:checked")).map((i) => i.value));
    $("f-critics").innerHTML = agents.map((a) =>
      '<label><input type="checkbox" value="' + esc(a.id) + '"' +
      (saved.size ? (saved.has(a.id) ? " checked" : "") : " checked") + ">" + esc(a.label) + "</label>"
    ).join("");
  } else {
    box.classList.add("hidden");
  }
}

/* 需求拷问采访卡（借鉴 grill-me 一次一问的折中：一卡多问、芯片点选）：
 * 点选项把「问题+所选」追加进目标框，凑齐后用户补一句即可发送；「跳过」直接创建 */
function renderClarify(questions, goal, resetSubmit) {
  const box = $("clarify-box");
  if (!box) { resetSubmit(); return; }
  box.classList.remove("hidden");
  box.innerHTML =
    '<div class="cl-head"><svg class="ico" aria-hidden="true"><use href="#i-chat"></use></svg>' +
    '<b>' + esc(t("先对齐几个点，再做更准")) + "</b>" +
    '<button type="button" class="ghost small" id="clarify-skip">' + esc(t("跳过，直接做")) + "</button></div>" +
    questions.map((it, i) =>
      '<div class="cl-q"><div class="cl-qtext">' + (i + 1) + ". " + esc(it.q) + "</div>" +
      '<div class="cl-opts">' + (it.options || []).map((o) =>
        '<button type="button" class="cl-opt" data-q="' + esc(it.q) + '" data-o="' + esc(o) + '">' +
        esc(o) + "</button>").join("") + "</div></div>").join("");
  box.querySelectorAll(".cl-opt").forEach((b) => b.addEventListener("click", () => {
    const ta = $("f-goal");
    if (!ta) return;
    const line = it0safe(b.dataset.q, b.dataset.o);
    ta.value = ta.value.trim() + (ta.value.includes(line) ? "" : (ta.value ? "\n" : "") + line);
    b.classList.add("picked");
    b.disabled = true;
    // spec 分段签核（借鉴 superpowers「分段短块逐段消化」）：全部问题选完后
    // 显示已确认摘要条 + 「确认开跑」——用户看一眼再动手，不蒙头就创建
    const allPicked = questions.every((it) =>
      Array.from(box.querySelectorAll(".cl-opt")).some(
        (x) => x.dataset.q === it.q && x.classList.contains("picked")));
    let bar = box.querySelector("#clarify-confirm");
    if (allPicked && !bar) {
      bar = document.createElement("div");
      bar.id = "clarify-confirm";
      bar.className = "cl-confirm";
      bar.innerHTML = '<button type="button" class="primary small" id="clarify-go">' +
        esc(t("已确认，开跑")) + "</button></div>";
      box.appendChild(bar);
      bar.querySelector("#clarify-go").addEventListener("click", () => {
        box.classList.add("hidden");
        box.innerHTML = "";
        S.clarifyDone = true;
        $("btn-create").click();
      });
    }
  }));
  function it0safe(q, o) { return q + "：" + o; }
  const skip = $("clarify-skip");
  if (skip) skip.addEventListener("click", () => {
    box.classList.add("hidden");
    box.innerHTML = "";
    S.clarifyDone = true;              // 跳过 = 本轮不再采访
    $("btn-create").click();
  });
  $("f-goal").focus();
}

function renderTaskTemplates() {
  const select = $("f-template");
  if (!select) return;
  const current = select.value;
  select.innerHTML = '<option value="">' + esc(t("不使用模板")) + '</option>' + (UI_FEATURES.templates || []).map((item) =>
    '<option value="' + esc(item.id || "") + '">' + esc(item.name || item.id || "") + '</option>').join("");
  if ((UI_FEATURES.templates || []).some((item) => item.id === current)) select.value = current;
}

async function loadTaskTemplates() {
  try { const result = await api("/api/task-templates", { timeout: 15000 }); UI_FEATURES.templates = result.templates || []; renderTaskTemplates(); }
  catch (error) { UI_FEATURES.templates = []; renderTaskTemplates(); }
}

function applyTaskTemplate(template, start) {
  if (!template) return;
  S.templateBudget = template.max_calls ? { max_calls: Number(template.max_calls) || 0 } : null;
  if ($("f-goal")) $("f-goal").value = template.goal || "";
  if ($("f-title") && !$("f-title").value) $("f-title").value = template.name || "";
  if ($("f-type") && template.type) {
    const type = flowById(template.type) ? template.type : (template.type === "doc" ? "document" : template.type);
    if (flowById(type)) { $("f-type").value = type; $("f-type").dispatchEvent(new Event("change")); }
  }
  // Changing the type loads its default rubric, so keep the template rubric.
  if ($("f-rubric") && Array.isArray(template.rubric)) $("f-rubric").value = template.rubric.join(", ");
  if (start) createTask();
}

function selectTaskTemplate(start) {
  const id = ($("f-template") || {}).value;
  const template = (UI_FEATURES.templates || []).find((item) => item.id === id);
  if (!template) {
    S.templateBudget = null;
    if (start) toast(t("请选择任务模板"), true);
    return;
  }
  applyTaskTemplate(template, start);
}

async function saveCurrentAsTemplate() {
  const name = await uiPrompt(t("模板名称"), ($("f-title") || {}).value || t("我的任务模板"));
  if (!name) return;
  try {
    await api("/api/task-templates", { method: "POST", body: JSON.stringify({ name: name.trim(), type: $("f-type").value,
      goal: $("f-goal").value.trim(), rubric: (($("f-rubric") || {}).value || "").split(/[,，、]/).map((x) => x.trim()).filter(Boolean),
      max_calls: 0 }) });
    await loadTaskTemplates(); toast(t("模板已保存"));
  } catch (error) { toast(t("模板保存失败：") + error.message, true); }
}

async function createTask() {
  if (cmpReferencePending) { toast(t("正在添加引用，请稍候…")); return; }
  if (S.creatingTask) return;
  S.creatingTask = true;
  const submit = $("btn-create");
  if (submit) {
    submit.disabled = true;
    submit.setAttribute("aria-busy", "true");
  }
  const resetSubmit = () => {
    S.creatingTask = false;
    if (submit) {
      submit.disabled = false;
      submit.removeAttribute("aria-busy");
    }
  };
  const msg = $("create-msg");
  msg.className = "msg"; msg.textContent = t("提交中…");
  const payload = {
    type: $("f-type").value,
    mode: $("f-mode").value,
    title: $("f-title").value.trim(),
    goal: $("f-goal").value.trim(),
    context: $("f-context").value.trim(),
    workdir: $("f-workdir").value.trim(),
    thinking: $("f-thinking").value,
  };
  if (S.templateBudget && S.templateBudget.max_calls > 0) {
    payload.max_calls = S.templateBudget.max_calls;
  }
  const expertId = (($('f-expert') || {}).value || "").trim();
  if (expertId) payload.expert_id = expertId;
  if (cmpPlanMode) payload.plan_mode = true;
  const sandboxBackend = $("f-sandbox-backend").value;
  if (sandboxBackend === "docker") {
    const dockerImage = $("f-sandbox-image").value.trim();
    if (!dockerImage) {
      msg.className = "msg err";
      msg.textContent = t("选择 Docker 后请填写镜像名");
      $("f-sandbox-image").focus();
      resetSubmit();
      return;
    }
    payload.sandbox = { backend: "docker", docker_image: dockerImage };
  }
  // 扫榜选材允许目标留空（菜单承诺：默认分析总榜热门题材），其余类型必填
  if (!payload.goal && payload.type !== "rank_scan") {
    msg.className = "msg err";
    msg.textContent = t("请先填写目标");
    $("f-goal").focus();
    resetSubmit();
    return;
  }
  if (payload.type === "direct" && !S.typeSuggestionDone) {
    const suggested = recommendTaskType(payload.goal);
    if (suggested) {
      const flow = flowById(suggested) || {};
      resetSubmit();
      // direct 目标（如 defect_retro）没有评审门禁，卖点如实换成各自的
      // 专用数据链路/产出模板；review/code 目标维持门禁口径。
      const tail = flow.engine === "direct"
        ? t("这个需求更适合「{0}」流程，能使用对应的专用数据链路与产出模板。是否切换后执行？")
        : t("这个需求更适合「{0}」流程，能使用对应的规划与质量门禁。是否切换后执行？");
      const yes = await uiConfirm(
        tail.replace("{0}", t(flow.name || suggested)),
        { title: t("推荐任务类型"), ok: t("切换类型") });
      S.typeSuggestionDone = true;
      if (yes) pickType(suggested);
      $("btn-create").click();
      return;
    }
  }
  S.typeSuggestionDone = false;
  // 需求拷问闸（借鉴 grill-me）：goal 很短且没写背景时先问 1-3 个澄清问题；
  // 采访失败/无问题照常创建——是增强不是闸门
  if (payload.goal.length < 12 && !payload.context && !S.clarifyDone) {
    msg.textContent = t("目标有点简短，先问几个问题…");
    try {
      const cq = await api("/api/tasks/clarify", {
        // 澄清只是增强，不能让建任务被模型调用拖住；超时后直接按原目标开跑。
        method: "POST", timeout: 8000, operation: false,
        body: JSON.stringify({ goal: payload.goal, type: payload.type }) });
      const qs = (cq && cq.questions) || [];
      if (qs.length) {
        S.clarifyDone = true;            // 本轮已采访；再点发送直接创建
        renderClarify(qs, payload.goal, resetSubmit);
        return;
      }
    } catch (e) {
      // 澄清服务不可用或超时不阻塞主流程，明确告诉用户已经自动继续。
      msg.textContent = t("澄清响应较慢，已直接创建任务…");
    }
  }
  S.clarifyDone = false;
  if (!payload.workdir) delete payload.workdir;  // 留空 → 服务端用「默认保存路径」（编排设置可改）
  else unhideSideDir(payload.workdir);           // 在已移除的目录新建任务 → 自动恢复显示
  const acceptance = (($('f-acceptance') || {}).value || "").split(/\r?\n/).map((x) => x.trim()).filter(Boolean);
  if (acceptance.length) payload.acceptance_criteria = acceptance.slice(0, 40);
  payload.approval_required = !!(($('f-approval-required') || {}).checked);
  if (payload.mode === "manual") payload.implementer = $("f-impl").value;
  // 附件与代码版本：任务创建时服务端把待提交附件移入 _attachments/ 并注入上下文
  if ((S.atts || []).length) payload.attachments = S.atts.filter((a) => a.id).map((a) => a.id);
  if (!$("row-git").classList.contains("hidden") && $("f-git-rev").value) {
    // 下拉值带 kind: 前缀（branch:main / tag:v1.0 / commit:abc123），提交时还原为纯 rev
    payload.git_rev = $("f-git-rev").value.split(/:(.*)/s)[1] || "";
    if (!payload.git_rev) delete payload.git_rev;
  }
  const sid = $("f-resume-session").value;
  const resumeAgent = $("f-resume-agent").value;
  if (resumeAgent && sid) {
    const opt = $("f-resume-session").selectedOptions[0];
    const hit = (S.sessionList || []).find((s) => s.session_id === sid);
    payload.resume = { agent: resumeAgent, session: sid,
      preview: opt ? opt.textContent : "", project: (hit && hit.project) || "" };
  }
  const flow = flowById(payload.type) || {};
  const _eng = flow.engine;
  if (_eng === "code") {
    payload.verify_command = $("f-verify").value.trim();
  } else if (_eng === "direct") {
    // 直连：目标+附件即全部输入，不带验证/评审参数；direct_agent 为空时走
    // 内置智能体/模型绑定（后端按空串处理）
    payload.direct_provider_id = $("f-direct-provider").value;
    payload.direct_model = $("f-direct-model-name").value;
    payload.direct_agent = cmpDirectAgentVal();
  } else {
    payload.manuscript = $("f-manuscript").value.trim() || "manuscript.md";
    payload.rounds = parseInt($("f-rounds").value, 10) || 2;
    payload.threshold = parseFloat($("f-threshold").value) || 7.0;
    payload.best_of = Math.max(1, Math.min(3, parseInt($("f-bestof").value, 10) || 1));
    const rubric = $("f-rubric").value.trim();
    if (rubric) payload.rubric = rubric.split(/[,，、]/).map((s) => s.trim()).filter(Boolean);
    if (payload.type === "short_drama") {
      const episodes = parseInt($("f-drama-episodes").value, 10);
      const seconds = parseInt($("f-drama-seconds").value, 10);
      payload.drama = {};
      if (episodes > 0) payload.drama.episodes = Math.max(1, Math.min(200, episodes));
      if (seconds > 0) payload.drama.seconds_per_episode = Math.max(15, Math.min(600, seconds));
      if (!Object.keys(payload.drama).length) delete payload.drama;
    }
    const ch = parseInt($("f-chapters").value, 10);
    if (ch >= 2) {
      payload.serial = {
        chapters: ch,
        words_per_chapter: parseInt($("f-words-per-ch").value, 10) || 2500,
        variants: Math.max(1, Math.min(3, parseInt($("f-variants").value, 10) || 1)),
        // 多线剧情推演：任务级 serial 整体替换流程默认，漏带会把流程里
        // 配好的 branches 冲掉（store.create_task 字段级不合并）
        branches: Math.max(1, Math.min(3, parseInt($("f-branches").value, 10) || 1)),
      };
      // 分卷：显式卷结构文本优先（后端解析成卷表），否则用每卷章数。
      // 两个都留空 = 不分卷（后端收到 0/缺字段即不分卷）。
      const volSpec = ($("f-vol-spec") || {}).value ? $("f-vol-spec").value.trim() : "";
      const volPer = parseInt(($("f-vol-chapters") || {}).value, 10);
      if (volSpec) payload.serial.volumes_text = volSpec;
      else if (volPer >= 2) payload.serial.volume_chapters = volPer;
    } else if (flow.serial) {
      // 显式 null 覆盖 serial_novel 的流程默认，空章节就是单稿件。
      payload.serial = null;
    }
    // 短篇规格：目标字数（story_words 平铺一份给偏好记忆，真源是 story.words）
    if (flow.story) {
      const sw = Math.max(2000, Math.min(50000,
        parseInt($("f-story-words").value, 10) || flow.story.words || 12000));
      payload.story = { words: sw };
      payload.story_words = sw;
    }
    const initialBible = ($("f-bible") || {}).value ? $("f-bible").value.trim() : "";
    if (initialBible && flow.serial && payload.serial) payload.story_bible = initialBible;
    const critics = Array.from($("f-critics").querySelectorAll("input:checked")).map((i) => i.value);
    if (critics.length) payload.critics = critics;
  }
  // 插件指令属于执行上下文；Composer 中只展示选中的插件标记。
  const pluginContext = [...S.cmpPlugins, ...cmpReferenceContext.map(row => row.id)].map((name) => {
    const item = cmpCapability(name) || cmpReferenceContext.find(row => row.id === name);
    if (!item || !item.prompt || item.enabled === false || ["broken", "blocked", "disabled"].includes(item.state)) return "";
    return item.prompt;
  }).filter(Boolean).join("\n\n");
  if (pluginContext) payload.context = [payload.context, pluginContext].filter(Boolean).join("\n\n");
  try {
    const r = await api("/api/tasks", { method: "POST", timeout: 30000, operation: "创建任务",
      body: JSON.stringify(payload) });
    msg.textContent = t("已创建，跳转运行页…");
    // 先把新任务刷进 state 再跳：chatEngineIsDirect 靠 S.state.tasks 判引擎，
    // 不刷的话对话页签不会就绪，自动选卡落不到「对话」
    try { await refreshState(); } catch (e) { /* 刷失败等轮询兜底 */ }
    jumpToRun(r.run_id);
    cmpPlanMode = false;
    cmpSyncPlanMode();
    $("f-goal").value = "";
    S.cmpPlugins = []; cmpReferenceContext = []; cmpRenderPluginChips();
    if ($("f-bible")) $("f-bible").value = "";
    S.atts = []; renderAttachChips();   // 附件已移交任务待提交区，清空本地列表
  } catch (e) {
    msg.className = "msg err"; msg.textContent = e.message;
  } finally {
    resetSubmit();
  }
}

function syncSandboxComposer() {
  const docker = $("f-sandbox-backend") && $("f-sandbox-backend").value === "docker";
  const row = $("row-sandbox-image");
  if (row) row.classList.toggle("hidden", !docker);
}

/* ---------------------------------------------------------- 附件（截图/文件） */
/* 待提交附件：选中/粘贴即上传到服务端 pending 区，创建任务时随 payload 落盘
 * 到工作目录 _attachments/ 并注入上下文。图片另走 codex 原生 -i 直读；
 * Word/Excel/PPT 由服务端抽正文生成伴生 .txt，智能体直接读文本版。 */
const ATT_EXT_OK = /\.(png|jpe?g|gif|webp|bmp|svg|txt|md|markdown|csv|json|log|py|js|ts|html?|css|xml|ya?ml|toml|pdf|docx?|xlsx?|pptx?|rtf|odt|ods)$/i;
const ATT_OFFICE_RE = /\.(docx?|xlsx?|pptx?|rtf|odt|ods)$/i;
const ATT_CAP = 8 * 1024 * 1024;         // 普通附件 8MB
const ATT_CAP_OFFICE = 24 * 1024 * 1024; // Office 文档放宽到 24MB
let cmpPlanMode = false;

function cmpAddMenu(open) {
  const menu = $("cmp-add-menu"), button = $("btn-attach");
  if (!menu || !button) return;
  const next = typeof open === "boolean" ? open : menu.classList.contains("hidden");
  menu.classList.toggle("hidden", !next);
  button.setAttribute("aria-expanded", next ? "true" : "false");
  if (next) { cmpSyncPlanMode(); cmpRenderCapabilityMenu(); cmpLoadWorkspaceFiles(); loadComposerCapabilities(); }
}

function cmpSyncPlanMode() {
  const item = document.querySelector('[data-add-action="plan"]');
  const hint = $("cmp-plan-hint");
  if (item) item.classList.toggle("is-on", cmpPlanMode);
  if (hint) hint.textContent = t(cmpPlanMode ? t("计划模式已开启") : t("开启计划模式"));
}

function cmpAddAction(action) {
  cmpAddMenu(false);
  if (action === "file") {
    _askOpen({
      title: t("文件和文件夹"),
      bodyHtml: '<div class="ask-msg">' + esc(t("选择要添加的内容：可以选择文件，也可以选择整个文件夹。")) + "</div>",
      okText: t("选择文件"), noText: t("取消"),
      extra: [{ text: t("选择文件夹"), value: "folder", cls: "ghost" }],
      onOpen: () => $("ask-yes").focus(),
    }).then((choice) => {
      if (choice === true) $("f-attach-file").click();
      else if (choice === "folder") $("f-attach-folder").click();
    });
  } else if (action === "workflow") {
    toggleTypeMenu(true);
  } else if (action === "browser") {
    const currentTask = S.currentTaskId || S.taskId || "";
    wbSetTask(currentTask || ((S.state || {}).tasks || [])[0]?.id || "");
    switchTab("browser", "main");
    toast(t("已打开工作台并关联当前任务"));
  } else if (action === "goal") {
    switchTab("overview", "main");
    goalLoad().then(() => {
      if (!(_goalCache && _goalCache.current)) $("ov-goal-title").focus();
      else $("ov-goal-error").textContent = t("已有进行中的目标，可在此查看或开始下一轮。" );
    });
  } else if (action === "plan") {
    cmpPlanMode = !cmpPlanMode;
    cmpSyncPlanMode();
    toast(t(cmpPlanMode ? t("计划模式已开启：将先生成详细计划，再按计划执行。") : t("计划模式已关闭。")));
  } else if (action === "draw") {
    cmpOpenDrawing();
  }
}

// The menu reflects the backend directory; loading failures never fabricate
// installed plugins. Selected capability instructions are kept out of the goal.
let cmpCapabilityFilter = "all";
let cmpReferenceContext = [];
let cmpReferencePending = 0;
let cmpWorkspaceFiles = [];
let cmpWorkspaceFilesDir = "";
let cmpWorkspaceFilesBusy = false;
let cmpWorkspaceFilesError = "";
let cmpCapabilitiesError = "";

function cmpCapability(id) {
  const all = S.capabilities || {};
  for (const [group, kind] of [["plugins", "plugin"], ["skills", "skill"], ["agents", "agent"]]) {
    const hit = (all[group] || []).find(x => x && x.id === id);
    if (!hit) continue;
    const label = hit.display_name || hit.name || id;
    const prompt = kind === "plugin"
      ? "已选择插件：" + label + "\n" + (hit.description || "") + "\n" +
        (hit.default_prompt || []).join("\n") + "\n" +
        ((hit.skill_prompts || []).join("\n\n") || "") +
        ((hit.unsupported || []).length ? "\n此插件的 Codex hooks、应用或 MCP 运行时未自动接入 CodeBee；请只使用当前环境实际可用的工具。" : "")
      : (hit.prompt || "请参考「" + label + "」的职责：" + (hit.description || ""));
    return { id, kind, label, prompt, state: hit.state,
      enabled: hit.enabled === true && hit.installed === true && hit.available !== false &&
        !["broken", "blocked"].includes(hit.state) && (!hit.compatibility || hit.compatibility.compatible !== false) };
  }
  return null;
}

function cmpCapabilityRows() {
  const all = S.capabilities || {};
  return [["plugins", "plugin"], ["skills", "skill"], ["agents", "agent"]]
    .flatMap(([group, kind]) => (all[group] || []).map(x => ({ ...x, kind })));
}

function cmpRenderCapabilityMenu() {
  const box = $("cmp-capability-items");
  if (!box) return;
  const query = (($("cmp-capability-search") || {}).value || "").trim().toLowerCase();
  const match = row => !query || [row.display_name, row.name, row.description, row.short_description]
    .join(" ").toLowerCase().includes(query);
  const allRows = cmpCapabilityRows();
  const groups = [["plugin", t("插件")], ["skill", t("技能")], ["agent", t("智能体")]];
  let html = groups.map(([kind, title]) => {
    if (!["all", kind].includes(cmpCapabilityFilter)) return "";
    const rows = allRows.filter(x => x.kind === kind && match(x));
    if (!rows.length) return "";
    return '<div class="cmp-add-kicker">' + esc(t(title)) + ' · ' + rows.length + '</div>' + rows.map(row => {
      const label = row.display_name || row.name || row.id;
      const desc = row.short_description || row.description || "";
      const state = row.state || "available";
      const incompatible = row.compatibility && row.compatibility.compatible === false;
      const disabled = row.installed !== true || row.enabled !== true || row.available === false || incompatible || ["broken", "blocked"].includes(state);
      const status = incompatible ? t("不适配") : ["broken", "blocked"].includes(state) ? t("损坏") : row.installed !== true
        ? t("未安装") : row.enabled !== true ? t("已停用") : (row.unsupported || []).length ? t("部分能力") : t("已安装");
      return '<button type="button" class="cmp-add-item cmp-add-plugin" data-add-capability="' + esc(row.id) + '"' +
        (disabled ? ' disabled aria-disabled="true"' : '') + ' role="menuitem" title="' + esc((row.compatibility || {}).reason || row.error || desc) + '">' +
        '<span class="cmp-plugin-mark" aria-hidden="true">' + esc(String(label).slice(0, 1).toUpperCase()) + '</span>' +
        '<span><b>' + esc(label) + '</b><small>' + esc(t(desc)) + '</small></span>' +
        '<em class="cmp-capability-state">' + esc(status) + '</em><span class="cmp-add-check" aria-hidden="true"></span></button>';
    }).join("");
  }).join("");
  if (["all", "file"].includes(cmpCapabilityFilter)) {
    const files = cmpWorkspaceFiles.filter(row => match({ name: row.name }));
    html += '<div class="cmp-add-kicker">' + esc(t("工作区文件")) + '</div>';
    html += files.map(row => '<button type="button" class="cmp-add-item" data-add-workspace-file="' + esc(row.name) + '" role="menuitem">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-file-text"></use></svg><span><b>' + esc(row.name) + '</b></span></button>').join("") ||
      '<p class="cmp-capability-empty">' + esc(cmpWorkspaceFilesBusy ? t("正在读取工作区…") : cmpWorkspaceFilesError || t("选择工作目录后可引用文件")) + '</p>';
  }
  if (["all", "chat"].includes(cmpCapabilityFilter)) {
    const tasks = ((S.state || {}).tasks || []).filter(row => match({ name: row.title, description: row.goal }));
    html += '<div class="cmp-add-kicker">' + esc(t("会话")) + '</div>' + tasks.map(row =>
      '<button type="button" class="cmp-add-item" data-add-chat="' + esc(row.id) + '" role="menuitem">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-chat"></use></svg><span><b>' + esc(row.title || row.id) + '</b>' +
      '<small>' + esc(row.goal || "") + '</small></span></button>').join("");
  }
  if (!html) html = '<p class="cmp-capability-empty">' + esc(t("没有匹配的内容")) + '</p>';
  if (!S.capabilities) html = '<p class="cmp-capability-empty">' + esc(cmpCapabilitiesError || t("正在读取能力目录…")) + '</p>' + html;
  box.innerHTML = html;
  document.querySelectorAll("[data-capability-filter]").forEach(button => {
    const active = button.dataset.capabilityFilter === cmpCapabilityFilter;
    button.classList.toggle("is-on", active);
    button.setAttribute("aria-pressed", String(active));
  });
  cmpRenderPluginChips();
}

async function cmpLoadWorkspaceFiles() {
  const dir = ($("f-workdir").value || "").trim();
  if (dir === cmpWorkspaceFilesDir) return;
  cmpWorkspaceFilesDir = dir;
  cmpWorkspaceFiles = [];
  cmpWorkspaceFilesError = "";
  cmpWorkspaceFilesBusy = !!dir;
  cmpRenderCapabilityMenu();
  if (!dir) return;
  try {
    const result = await api("/api/dir/scan?path=" + encodeURIComponent(dir), { timeout: 15000 });
    if (dir === cmpWorkspaceFilesDir) cmpWorkspaceFiles = result.files || [];
  } catch (error) {
    if (dir === cmpWorkspaceFilesDir) cmpWorkspaceFilesError = error.message;
  } finally {
    if (dir === cmpWorkspaceFilesDir) {
      cmpWorkspaceFilesBusy = false;
      cmpRenderCapabilityMenu();
    }
  }
}

async function cmpAddReference(kind, id) {
  cmpReferencePending++;
  try {
    if (kind === "file") {
      const row = cmpWorkspaceFiles.find(row => row.name === id);
      if (!row) return;
      if (row.size > (ATT_OFFICE_RE.test(id) ? ATT_CAP_OFFICE : ATT_CAP)) {
        throw new Error(t("附件超过：") + id);
      }
      if (S.atts.length >= 12) throw new Error(t("附件最多 12 个"));
      const baseName = id.split("/").pop();
      const isText = /\.(go|rs|kt|kts|java|c|h|cpp|hpp|sh|ps1|ini|cfg|conf|env|sql|tsx|jsx|lock)$/i.test(baseName) ||
        /^\.(gitignore|gitattributes|npmignore|editorconfig|env(?:\..+)?)$/i.test(baseName) ||
        /^(Dockerfile|Makefile|LICENSE)$/i.test(baseName);
      if (!ATT_EXT_OK.test(id) && !isText) throw new Error(t("不支持的附件类型：") + id);
      const response = await fetch(urlAuth("/api/dir/file?dir=" + encodeURIComponent(cmpWorkspaceFilesDir) + "&name=" + encodeURIComponent(id)));
      if (!response.ok) throw new Error(t("读取文件失败：") + response.status);
      const blob = await response.blob();
      const file = new File([blob], ATT_EXT_OK.test(id) ? baseName : baseName + ".txt", { type: blob.type });
      file.codebeeRelativePath = id;
      await addAttachFiles([file]);
    } else {
      const data = await api("/api/tasks/" + encodeURIComponent(id) + "/detail");
      const task = data.task;
      if (!task) return;
      const latest = ((S.state || {}).task_latest || {})[id] ||
        (((S.state || {}).runs || []).find(row => row.task_id === id));
      const timeline = latest ? await api("/api/runs/" + encodeURIComponent(latest.id) + "/timeline") : { items: [] };
      const messages = (timeline.items || []).filter(row => row.text).slice(-20)
        .map(row => (row.kind || row.role || "") + ": " + row.text).join("\n\n").slice(-16000);
      const refId = "chat:" + id;
      if (!cmpReferenceContext.some(row => row.id === refId)) cmpReferenceContext.push({
        id: refId, label: task.title || id,
        prompt: "引用会话：" + (task.title || id) + "\n会话目标：" + (task.goal || "") +
          "\n背景：" + (task.context || "").slice(0, 12000) + "\n会话内容：\n" + messages
      });
      cmpRenderPluginChips();
    }
    cmpAddMenu(false);
    $("f-goal").focus();
  } catch (error) { toast(error.message, true); }
  finally { cmpReferencePending--; }
}

function cmpRenderPluginChips() {
  const box = $("cmp-plugin-chips");
  if (box) box.innerHTML = [...S.cmpPlugins, ...cmpReferenceContext.map(row => row.id)].map((name) => {
    const plugin = cmpCapability(name) || cmpReferenceContext.find(row => row.id === name);
    if (!plugin) return "";
    return '<span class="cmp-plugin-chip" data-plugin="' + esc(name) + '">' +
      '<span class="cmp-plugin-mark" aria-hidden="true">' + esc(String(plugin.label || name).slice(0, 1).toUpperCase()) + '</span>' +
      '<span>' + esc(t(plugin.label || name)) + '</span><button type="button" data-plugin-remove="' + esc(name) +
      '" title="' + esc(t("移除") + " " + (plugin.label || name)) + '" aria-label="' + esc(t("移除") + " " + (plugin.label || name)) +
      '"><svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg></button></span>';
  }).join("");
  document.querySelectorAll("[data-add-capability]").forEach((item) => {
    item.classList.toggle("is-on", S.cmpPlugins.includes(item.dataset.addCapability));
  });
}

function cmpAddCapability(name) {
  cmpAddMenu(false);
  const recipe = cmpCapability(name);
  if (!recipe) return;
  if (recipe.enabled === false || ["broken", "blocked"].includes(recipe.state)) {
    toast(t("该能力当前未启用，无法添加。"), true); return;
  }
  if (!S.cmpPlugins.includes(name)) S.cmpPlugins.push(name);
  cmpRenderPluginChips();
  $("f-goal").focus();
}

function cmpAddPlugin(name) { cmpAddCapability(name); }

async function loadComposerCapabilities() {
  cmpCapabilitiesError = "";
  try {
    S.capabilities = await api("/api/capabilities", { timeout: 15000 });
  } catch (error) {
    cmpCapabilitiesError = t("读取能力目录失败：") + error.message;
  }
  cmpRenderCapabilityMenu();
}

function cmpOpenDrawing() {
  let dialog = $("cmp-draw-dialog");
  if (!dialog) {
    dialog = document.createElement("dialog");
    dialog.id = "cmp-draw-dialog";
    dialog.className = "cmp-draw-dialog";
    dialog.innerHTML = '<div class="cmp-draw-head"><div><b>' + esc(t("绘图")) + '</b><small>' + esc(t("画一张草图，完成后作为任务附件添加。")) + '</small></div><button type="button" class="ghost small" data-draw-close aria-label="' + esc(t("关闭")) + '">×</button></div><div class="cmp-draw-tools"><button type="button" class="ghost small is-active" data-draw-tool="pen">' + esc(t("画笔")) + '</button><button type="button" class="ghost small" data-draw-tool="eraser">' + esc(t("橡皮擦")) + '</button><input type="color" value="#202123" aria-label="' + esc(t("画笔颜色")) + '"><input type="range" min="1" max="24" value="4" aria-label="' + esc(t("画笔粗细")) + '"><button type="button" class="ghost small" data-draw-clear>' + esc(t("清空")) + '</button><span class="spacer"></span><button type="button" class="primary small" data-draw-add>' + esc(t("添加到任务")) + '</button></div><canvas class="cmp-draw-canvas" width="1200" height="620" aria-label="' + esc(t("绘图画布")) + '"></canvas>';
    document.body.appendChild(dialog);
    const canvas = dialog.querySelector("canvas"), ctx = canvas.getContext("2d");
    ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, canvas.width, canvas.height);
    let drawing = false, tool = "pen", color = "#202123", size = 4, hasMarks = false;
    const point = (event) => { const r = canvas.getBoundingClientRect(); return { x: (event.clientX-r.left)*canvas.width/r.width, y: (event.clientY-r.top)*canvas.height/r.height }; };
    canvas.addEventListener("pointerdown", (event) => { drawing = true; hasMarks = true; canvas.setPointerCapture(event.pointerId); const p=point(event); ctx.beginPath(); ctx.moveTo(p.x,p.y); });
    canvas.addEventListener("pointermove", (event) => { if (!drawing) return; const p=point(event); ctx.lineCap="round"; ctx.lineJoin="round"; ctx.lineWidth=size; ctx.strokeStyle=tool==="eraser"?"#fff":color; ctx.lineTo(p.x,p.y); ctx.stroke(); });
    canvas.addEventListener("pointerup", () => { drawing=false; });
    dialog.addEventListener("click", (event) => {
      const close=event.target.closest("[data-draw-close]"); if(close){dialog.close();return;}
      const toolButton=event.target.closest("[data-draw-tool]"); if(toolButton){tool=toolButton.dataset.drawTool;dialog.querySelectorAll("[data-draw-tool]").forEach(b=>b.classList.toggle("is-active",b===toolButton));return;}
      if(event.target.closest("[data-draw-clear]")){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);hasMarks=false;return;}
      if(event.target.closest("[data-draw-add]")){if(!hasMarks){toast(t("请先画一些内容。"),true);return;}canvas.toBlob(async(blob)=>{if(!blob)return;const file=new File([blob],"codebee-sketch-"+Date.now()+".png",{type:"image/png"});await addAttachFiles([file]);dialog.close();},"image/png");}
    });
    dialog.querySelector('input[type="color"]').addEventListener("input",e=>{color=e.target.value;tool="pen";});
    dialog.querySelector('input[type="range"]').addEventListener("input",e=>{size=Number(e.target.value)||4;});
    dialog.addEventListener("close",()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);hasMarks=false;});
  }
  if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", "");
}

function renderAttachChips() {
  const box = $("att-chips");
  if (!box) return;
  box.innerHTML = (S.atts || []).map((a) => {
    const name = String(a.name || "attachment");
    const id = String(a.id || "");
    const image = /^image\//i.test(String(a.mime || "")) ||
      /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(name);
    const remove = '<button type="button" class="ax" data-att-remove="' + esc(id) +
      '" title="' + esc(t("移除")) + '" aria-label="' + esc(t("移除")) + '">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg></button>';
    if (image && id) {
      const src = "/api/attachments/" + encodeURIComponent(id) + qsAuth();
      return '<span class="att-chip att-image" title="' + esc(name) + '">' +
        '<img src="' + esc(src) + '" alt="' + esc(name) + '" loading="lazy" draggable="false">' +
        '<span class="att-image-name">' + esc(name) + "</span>" + remove + "</span>";
    }
    return '<span class="att-chip" title="' + esc(name) + '">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-paperclip"></use></svg>' +
      "<span>" + esc(name) + "</span>" +
      " <i>" + fmtSize(a.size) + "</i>" + remove + "</span>";
  }).join("");
}

function fmtSize(n) {
  if (n >= 1048576) return (n / 1048576).toFixed(1) + "MB";
  if (n >= 1024) return Math.round(n / 1024) + "KB";
  return (n || 0) + "B";
}

function removeAtt(id) {
  S.atts = (S.atts || []).filter((a) => a.id !== id);
  renderAttachChips();
}
window.removeAtt = removeAtt;

async function addAttachFiles(files, opts) {
  const quiet = !!(opts && opts.quiet);   // 文件夹批量附加：超大/不支持的文件属常态，安静跳过最后汇总
  if (!files || !files.length) return;
  if ((S.atts || []).length + files.length > 12) {
    toast(t("附件最多 12 个"), true); return;
  }
  const skipped = [];
  for (const f of files) {
    if (!ATT_EXT_OK.test(f.name)) {
      if (quiet) { skipped.push(f.name); continue; }
      toast(t("不支持的附件类型：") + f.name, true); continue;
    }
    const cap = ATT_OFFICE_RE.test(f.name) ? ATT_CAP_OFFICE : ATT_CAP;
    if (f.size > cap) {
      if (quiet) { skipped.push(f.name); continue; }
      toast(t("附件超过：") + f.name, true); continue;
    }
    try {
      const b64 = await new Promise((res, rej) => {
        const rd = new FileReader();
        rd.onload = () => res(String(rd.result).split(",")[1] || "");
        rd.onerror = () => rej(new Error(t("读取失败")));
        rd.readAsDataURL(f);
      });
      const r = await api("/api/attachments", { method: "POST",
        body: JSON.stringify({ name: f.name, data: b64,
          relative_path: f.codebeeRelativePath || "" }) });
      S.atts = S.atts || [];
      if (S.atts.some((a) => a.id === r.attachment.id)) continue;  // 去重
      S.atts.push(r.attachment);
      renderAttachChips();
    } catch (e) {
      toast(t("附件上传失败：") + f.name + " — " + e.message, true);
    }
  }
  if (quiet && skipped.length) {
    const names = skipped.slice(0, 3).join("、") + (skipped.length > 3 ? " …" : "");
    toast(t("已跳过大文件或不支持的类型：") + names + t("（共") + skipped.length + t("个）"));
  }
}
window.addAttachFiles = addAttachFiles;

/* 目标框粘贴截图：Ctrl+V 直接作为附件上传 */
function onGoalPaste(e) {
  const files = [];
  for (const item of (e.clipboardData ? e.clipboardData.items : [])) {
    if (item.kind === "file") {
      const f = item.getAsFile();
      if (f) files.push(f);
    }
  }
  if (files.length) {
    e.preventDefault();
    // 截图多为无文件名 blob，起个可读名字（扩展名由服务端白名单校验）
    addAttachFiles(files.map((f, i) => {
      const when = new Date();
      const ts = when.getFullYear() + String(when.getMonth() + 1).padStart(2, "0")
        + String(when.getDate()).padStart(2, "0") + "-" + String(when.getHours()).padStart(2, "0")
        + String(when.getMinutes()).padStart(2, "0") + String(when.getSeconds()).padStart(2, "0");
      const ext = (f.name.match(/\.[a-z0-9]+$/i) || [f.type === "image/png" ? ".png" : ".png"])[0];
      return f.name ? f : new File([f], "pasted-" + ts + (files.length > 1 ? "-" + (i + 1) : "") + ext, { type: f.type });
    }));
  }
}

/* ---------------------------------------------------------- 代码版本（Git） */
/* 工作目录指向 git 仓库时给出分支/标签/提交选择；创建任务后执行前由服务端
 * 从所选版本检出任务分支 codebee/<task-id>（脏工作区会显式失败，不静默降级）。 */
let _gitProbeTimer = null;

function queueGitProbe() {
  clearTimeout(_gitProbeTimer);
  _gitProbeTimer = setTimeout(probeGit, 500);
}

async function probeGit() {
  const row = $("row-git"), sel = $("f-git-rev"), hint = $("git-hint");
  if (!row || !sel) return;
  const wd = ($("f-workdir").value || "").trim();
  if (!wd) { row.classList.add("hidden"); return; }
  let info = null;
  try {
    info = await api("/api/git/info?workdir=" + encodeURIComponent(wd));
  } catch (e) { info = null; }  // 远程端 403 / 非仓库：静默隐藏，不干扰手填路径
  if (!info || !info.repo) { row.classList.add("hidden"); return; }
  S.gitInfo = info;
  row.classList.remove("hidden");
  const prev = sel.value;
  const opt = (v, label) => '<option value="' + esc(v) + '">' + esc(label) + "</option>";
  const groups = [];
  // 首选项=跟随当前分支：胶囊上直接显示分支名（参考工作区选择器的「main ▾」），
  // 悬停胶囊看完整说明（renderGitHint 写 row.title）；换分支在「分支」组里选
  groups.push(opt("", info.branch || "HEAD"));
  groups.push('<optgroup label="' + esc(t("分支")) + '">'
    + (info.branches || []).map((b) => opt("branch:" + b, b)).join("") + "</optgroup>");
  if ((info.tags || []).length) {
    groups.push('<optgroup label="' + esc(t("标签")) + '">'
      + info.tags.map((tg) => opt("tag:" + tg, tg)).join("") + "</optgroup>");
  }
  if ((info.recent || []).length) {
    groups.push('<optgroup label="' + esc(t("最近提交")) + '">'
      + info.recent.map((c) => opt("commit:" + c.hash, c.hash + " " + c.subject)).join("") + "</optgroup>");
  }
  sel.innerHTML = groups.join("");
  // 记忆旧选择（下拉重绘不弹回）；值带 kind 前缀，服务端解析出纯 rev
  if (prev && Array.from(sel.options).some((o) => o.value === prev)) sel.value = prev;
  renderGitHint();
}

function renderGitHint() {
  const info = S.gitInfo;
  if (!info) return;
  const sel = $("f-git-rev");
  const pick = (sel.value || "").split(":");
  const kind = pick[0], rev = pick[1] || "";
  const base = t("当前分支 %1 @ %2").replace("%1", info.branch).replace("%2", (info.head || "").slice(0, 8));
  const dirty = info.dirty ? t("；工作区有 %1 处未提交改动").replace("%1", info.dirty_count) : "";
  const act = kind
    ? t("；运行时将从「%1」检出任务分支 codebee/&lt;任务ID&gt;").replace("%1", rev)
    : "";
  const text = base + dirty + act;
  $("git-hint").innerHTML = esc(text);
  // 极简：提示行不再常驻，分支胶囊的悬停 title 承载同一份详情（剥掉 innerHTML 用的实体）
  const row = $("row-git");
  if (row) row.title = text.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
}
window.probeGit = probeGit;

/* ---- 工作目录「最近文件夹」下拉：默认选中一个目录，▾ 展开最近 5 个 + 浏览/用默认 ---- */
function wdRecents() {
  const st = S.state || {};
  const seen = new Set(); const out = [];
  for (const tk of (st.tasks || []).concat(st.archived_tasks || [])) {
    const wd = (tk.workdir || "").trim();
    if (!wd || seen.has(wd)) continue;
    seen.add(wd); out.push(wd);
    if (out.length >= 5) break;
  }
  return out;
}
window.toggleWdMenu = function (ev) {
  if (ev) ev.stopPropagation();
  const menu = $("wd-menu");
  if (!menu) return;
  if (!menu.classList.contains("hidden")) { menu.classList.add("hidden"); return; }
  const cur = (($("f-workdir") || {}).value || "").trim();
  const eff = ((S.settings || {}).default_workdir_effective || "").trim();
  const base = (p) => p.split(/[\\/]/).filter(Boolean).pop() || p;
  const row = (p, label, on) =>
    '<button type="button" class="wd-item' + (on ? " on" : "") + '" data-wd="' + esc(p) +
    '" title="' + esc(p) + '">' +
    '<svg class="ico" aria-hidden="true"><use href="#i-folder"></use></svg>' +
    "<span>" + esc(label) + "</span>" +
    (on ? '<svg class="ico wd-check" aria-hidden="true"><use href="#i-check"></use></svg>' : "") +
    "</button>";
  let html = wdRecents().map((p) => row(p, base(p), p === cur)).join("");
  html += '<div class="wd-sep"></div>' +
    '<button type="button" class="wd-item" data-wd-act="browse">' +
    '<svg class="ico" aria-hidden="true"><use href="#i-folder"></use></svg>' +
    "<span>" + esc(t("浏览本机目录…")) + "</span></button>" +
    '<button type="button" class="wd-item" data-wd-act="default"' + (eff ? "" : " disabled") + ">" +
    '<svg class="ico" aria-hidden="true"><use href="#i-refresh"></use></svg>' +
    "<span>" + esc(t("用默认路径")) + "</span></button>";
  menu.innerHTML = html;
  menu.classList.remove("hidden");
};
window.wdMenuPick = function (item) {
  const inp = $("f-workdir"), menu = $("wd-menu");
  if (!item || !inp || item.disabled) return;
  if (item.dataset.wdAct === "browse") {
    if (menu) menu.classList.add("hidden");
    window.pickFolder("f-workdir");
    return;
  }
  inp.value = item.dataset.wdAct === "default"
    ? ((S.settings || {}).default_workdir_effective || "")
    : (item.dataset.wd || "");
  inp.dispatchEvent(new Event("input", { bubbles: true }));   // queueGitProbe 跟上换目录
  inp.dispatchEvent(new Event("change", { bubbles: true }));
  if (menu) menu.classList.add("hidden");
  inp.focus();
};

/* ---------------------------------------------------------- 会话延续 */
/* 后端支持会话扫描的工具集合（/api/sessions 的键）；决定继续会话下拉出现哪些工具 */
async function refreshSessionAgents() {
  try {
    const r = await api("/api/sessions");
    S.sessionAgents = new Set(Object.keys(r.sessions || {}));
  } catch (e) { /* 拉取失败保持现状，下拉由其余渲染兜底 */ }
  renderImplSelects();
}

async function loadSessions() {
  const agent = $("f-resume-agent").value;
  const row = $("row-resume-session");
  const sel = $("f-resume-session");
  if (!agent) { row.classList.add("hidden"); S.sessionList = []; return; }
  row.classList.remove("hidden");
  sel.innerHTML = '<option>' + t("（加载中…）") + '</option>';
  try {
    const r = await api("/api/sessions");
    const list = (r.sessions || {})[agent] || [];
    S.sessionList = list;   // 提交时带上 project（续会话要在该目录下启动 CLI）
    sel.innerHTML = list.length ? list.map((s) => {
      const who = s.project ? " [" + esc(String(s.project).replace(/[\\/]+$/, "").split(/[\\/]/).pop()) + "]" : "";
      return '<option value="' + esc(s.session_id) + '">[' + esc(s.mtime) + "]" + who + " " + esc(s.preview.slice(0, 60)) + "</option>";
    }).join("") : '<option value="">' + t("（未找到该智能体的本地会话）") + '</option>';
  } catch (e) {
    S.sessionList = [];
    sel.innerHTML = '<option value="">' + t("（扫描失败）") + '</option>';
  }
  showResumeHint();
}

/* 提示该会话将在哪个目录续接（CLI 需在会话项目目录下启动） */
function showResumeHint() {
  const hint = $("resume-session-hint");
  if (!hint) return;
  const hit = (S.sessionList || []).find((s) => s.session_id === $("f-resume-session").value);
  if (!hit || !hit.project) { hint.textContent = ""; return; }
  hint.textContent = t("该会话属于 ") + hit.project + t("，续接时 CLI 将在该目录下启动")
    + (hit.turns ? t("（已有 ") + hit.turns + t(" 轮对话上下文）") : "");
}

async function archiveTask(id, archived) {
  try {
    let restored = null;
    if (!archived && archivedTaskIds().has(id)) {
      restored = await loadTaskForPrefill(id);
    }
    await api("/api/tasks/" + encodeURIComponent(id) + "/archive",
      { method: "POST", body: JSON.stringify({ archived: !!archived }) });
    // 取消归档时把任务工作目录从「已移除目录」里捞回来：用户点时钟开关找回
    // 归档任务再取消归档，直觉上文件夹就该回侧栏（否则只能靠在该目录新建任务）。
    if (!archived) {
      const t0 = restored || ((S.state || {}).tasks || []).concat(((S.state || {}).archived_tasks) || [])
        .find((x) => x.id === id);
      if (t0 && t0.workdir) unhideSideDir(t0.workdir);
    }
    // 乐观挪位：归档=任务从 tasks 挪进 archived_tasks，取消归档反向。同删除的
    // 乐观清场——SSE 半死时推送不到，行要在侧栏挂到 60s 看门狗兜底才走。
    // archivedIds 参与侧栏签名，挪位即重画；显式清掉不赌签名算法。
    const st = S.state;
    if (st) {
      const from = archived ? (st.tasks || []) : (st.archived_tasks || []);
      const i0 = from.findIndex((x) => x.id === id);
      if (i0 >= 0) {
        const t0 = from.splice(i0, 1)[0];
        const moved = restored || t0;
        moved.archived = !!archived;
        if (!archived && restored) _taskDetailCache.set(id, restored);
        const to = archived ? (st.archived_tasks = st.archived_tasks || []) : (st.tasks = st.tasks || []);
        to.push(moved);
      }
      S.sideSig = "";
    }
    render();
    return true;
  } catch (e) { toast(t("操作失败：") + e.message, true); return false; }
  poll();
}

async function deleteTask(id) {
  if (!await uiConfirm(t("删除任务及其全部运行记录（含日志与报告），不可恢复；工作目录里的文件不会删"), { ok: t("删除"), danger: true })) return;
  toast(t("正在删除任务…"));
  await deleteTaskCore(id);
}

/* 删除单任务的执行段（无确认、无前置提示）：任务行单删与文件夹整删共用，
 * 批删只确认一次。返回是否删除成功（false＝服务端拒绝，如运行中/连载链前序）。 */
async function deleteTaskCore(id) {
  let gone = false;
  try {
    await api("/api/tasks/" + encodeURIComponent(id) + "/delete",
      { method: "POST", operation: "删除任务" });
  } catch (e) {
    // 任务已不在（他端删过 / 重复点）：不报错晾着，照常把视图清掉
    if (!/任务不存在/.test(e.message)) { toast(t("删除失败：") + e.message, true); return; }
    gone = true;
  }
  // 详情有两种打开方式：run 级（detailRunId）与任务级（detailTaskKey，detailRunId 为空）。
  // 删的正是当前详情对应的任务时都要关，否则右侧还挂着已删任务、再点重试就撞「任务不存在」。
  if (S.detailRunId || S.detailTaskKey === id) closeRun();
  // 乐观清场：不等 SSE 推送/轮询。删除靠 bump_state 走 SSE，SSE 半死时推送
  // 不到，看门狗要 60s 才兜底拉全量——期间已删任务就挂在侧栏（2026-09-23
  // 用户实测「任务删了，左侧列表不刷新」）。后端已删，就地清本地状态并强制
  // 重画；下一次全量推送自然对齐。
  const st = S.state;
  if (st) {
    st.tasks = (st.tasks || []).filter((x) => x.id !== id);
    st.archived_tasks = (st.archived_tasks || []).filter((x) => x.id !== id);
    if (st.task_latest) delete st.task_latest[id];
    if (st.task_stats) delete st.task_stats[id];
    const goneRuns = new Set((st.runs || []).filter((r) => r.task_id === id).map((r) => r.id));
    if (goneRuns.size) st.runs = (st.runs || []).filter((r) => !goneRuns.has(r.id));
    S.sideSig = "";   // 任务条目少了签名理应变化；显式清掉，不赌签名算法
  }
  _taskDetailCache.delete(id);
  _taskRunsCache.delete(id);
  _taskRunsAt.delete(id);
  _taskRunsPaging.delete(id);
  render();
  poll();
  if (gone) toast(t("任务已删除"));
  return true;
}

/* ---------------------------------------------------------- 右键菜单（归档/删除） */
const ORPHAN_DIR = "__orphan__";  // 无主运行（无 task_id / 任务已删）的兜底文件夹，与 renderSideTasks 共用
function archivedTaskIds() {
  return new Set((((S.state || {}).archived_tasks) || []).map((t) => t.id));
}

/* 文件夹「移除」隐藏表（localStorage）：移除的目录连同其下任务（含已归档灰显的）
 * 从侧栏隐藏——纯归档文件夹重复归档是 no-op，状态不变侧栏不重绘，必须显式隐藏；
 * 在该目录新建任务时自动恢复显示。 */
let _hiddenDirs = null;
function sideHiddenDirs() {
  if (!_hiddenDirs) {
    try { _hiddenDirs = new Set(JSON.parse(localStorage.getItem("tutti.hiddenDirs") || "[]")); }
    catch (e) { _hiddenDirs = new Set(); }
  }
  return _hiddenDirs;
}
function hideSideDir(dir) {
  const s = sideHiddenDirs();
  if (!s.has(dir)) { s.add(dir); localStorage.setItem("tutti.hiddenDirs", JSON.stringify([...s])); }
  S.sideSig = ""; renderSideTasks();
}
function unhideSideDir(dir) {
  const s = sideHiddenDirs();
  if (!dir || !s.delete(dir)) return;
  localStorage.setItem("tutti.hiddenDirs", JSON.stringify([...s]));
  S.sideSig = "";
}

/* 「显示已归档」开着时不剪已移除目录：时钟开关是被移除文件夹的唯一找回入口——
 * 移除=整目录任务归档+目录隐藏，只有灰显行右键「取消归档」才会把目录从隐藏表
 * 捞回来（unhideSideDir）。这里若无条件剪掉，开关永远照不出它，只剩「在该目录
 * 新建任务」一条兜底路（2026-10-21 不周山移除后时钟开关照不回实测案）。 */
function pruneHiddenSideDirs(dirs, showArchived) {
  if (showArchived) return;
  const hid = sideHiddenDirs();
  for (let i = dirs.length - 1; i >= 0; i--) if (hid.has(dirs[i].dir)) dirs.splice(i, 1);
}

let ctxItems = [];

function openCtxMenu(x, y, items) {
  const menu = $("ctx-menu");
  if (!menu) return;
  ctxItems = items;
  menu.innerHTML = items.map((it, i) => it === "-"
    ? '<div class="ctx-sep"></div>'
    : '<div class="ctx-item' + (it.danger ? " danger" : "") + '" data-i="' + i + '">' + esc(it.label) + "</div>").join("");
  menu.classList.remove("hidden");
  const r = menu.getBoundingClientRect();
  menu.style.left = Math.max(4, Math.min(x, window.innerWidth - r.width - 8)) + "px";
  menu.style.top = Math.max(4, Math.min(y, window.innerHeight - r.height - 8)) + "px";
  menu.onclick = (e) => {
    const el = e.target.closest(".ctx-item");
    if (!el) return;
    const it = ctxItems[+el.dataset.i];
    closeCtxMenu();
    if (it && it.fn) it.fn();
  };
}

function closeCtxMenu() {
  const menu = $("ctx-menu");
  if (menu && !menu.classList.contains("hidden")) menu.classList.add("hidden");
}

/* 任务行的「⋯」与右键共用同一组动作，避免两个入口越改越不一样。
 * det 是 .stask 元素；菜单位置由调用方提供，缺省时贴在行右下角。 */
function taskContextItems(det) {
  const taskId = det && det.dataset ? (det.dataset.task || "") : "";
  const runId = det && det.dataset ? (det.dataset.run || "") : "";
  const items = [];
  if (runId) items.push({ label: t("打开详情"), fn: () => sideOpenRun(runId) });
  if (taskId) {
    items.push("-");
    items.push({ label: t("打开工作目录"), fn: () => revealPath("tasks", taskId, true) });
    items.push({ label: t("复制工作目录路径"), fn: () => revealPath("tasks", taskId, false) });
    if (runId) items.push({ label: t("复制日志目录路径"), fn: () => revealPath("runs", runId, false) });
    const st = det.dataset.status || "";
    const latestTaskRun = ((S.state || {}).task_latest || {})[taskId] || {};
    const retryable = runNeedsRetry(latestTaskRun) ||
      st === "failed" || st === "cancelled" || st === "timeout";
    if (retryable) items.push({ label: t("↻ 继续任务"), fn: () => retryTask(taskId) });
    items.push({ label: retryable ? t("✎ 编辑重试") : t("基于此任务新建"),
      fn: () => newFromTask(taskId) });
    const sTask = ((S.state || {}).tasks || []).find((x) => x.id === taskId);
    if (sTask && sTask.serial && st !== "running" && st !== "queued")
      items.push({ label: t("继续连载（新任务）"), fn: () => continueSerial(taskId) });
    if (sTask && sTask.serial && !sTask.serial.early_finish
      && st !== "running" && st !== "queued")
      items.push({ label: t("提前完结"), fn: () => earlyFinishSerial(taskId) });
    if (sTask && sTask.serial && sTask.serial.early_finish
      && st !== "running" && st !== "queued") {
      items.push({ label: t("调整完结计划"), fn: () => editEarlyFinishSerial(taskId) });
      items.push({ label: t("撤销提前完结"), fn: () => cancelEarlyFinishSerial(taskId) });
    }
    // 连载完整跑完但未达标：给「重写未达标章」，与详情页按钮同源
    // （task_latest 全量下发最近一次 run，verdict 就在里面）
    const lrTask = ((S.state || {}).task_latest || {})[taskId];
    if (sTask && sTask.serial && lrTask && lrTask.status === "done"
      && lrTask.verdict && lrTask.verdict.publishable === false)
      items.push({ label: t("↻ 重写未达标章"), fn: () => retryTask(taskId) });
    items.push({ label: t("重命名任务"), fn: () => renameTask(taskId) });
    const archived = archivedTaskIds().has(taskId);
    items.push({ label: archived ? t("取消归档") : t("归档"), fn: () => archiveTask(taskId, !archived) });
    items.push({ label: t("删除任务"), danger: true, fn: () => deleteTask(taskId) });
  } else if (runId) {
    items.push("-");
    items.push({ label: t("复制日志目录路径"), fn: () => revealPath("runs", runId, false) });
    items.push({ label: t("删除记录"), danger: true, fn: () => deleteRun(runId) });
  }
  return items;
}

window.openTaskActions = function (det, ev) {
  if (!det) return;
  const r = det.getBoundingClientRect();
  const x = ev && Number.isFinite(ev.clientX) ? ev.clientX : r.right - 8;
  const y = ev && Number.isFinite(ev.clientY) ? ev.clientY : r.bottom;
  openCtxMenu(x, y, taskContextItems(det));
};

function bindCtxMenus() {
  // 侧栏任务树：右键任务 → 详情/目录/重试/重命名/归档/删除；管理类运行 → 详情/目录/删除记录
  $("side-tasks").addEventListener("contextmenu", (e) => {
    // .stask 在 .sdir 内部：先判任务行，点到才算文件夹自己的菜单
    const det = e.target.closest(".stask");
    if (det) {
    e.preventDefault();
    openCtxMenu(e.clientX, e.clientY, taskContextItems(det));
    return;
    }
    // 文件夹行（ZCode 桌面端式样）：查看文件 / 新建任务到该目录 / 打开工作目录 / 复制路径 /
    // 置顶切换 / 移除。
    // 「其他」是兜底展示（无主运行的聚合），不是真实目录，不弹菜单。
    const dirEl = e.target.closest(".sdir");
    if (!dirEl) return;
    e.preventDefault();
    const dir = dirEl.dataset.dir || "";
    if (!dir || dir === ORPHAN_DIR) return;
    // 含已归档任务：「显示已归档」开着时灰显回原文件夹的那批也算在内——
    // 不然纯归档文件夹右键移除会收集到空列表，点了没反应（重复归档是无害 no-op）
    const stAll = S.state || {};
    const dirTasks = (stAll.tasks || []).concat(stAll.archived_tasks || [])
      .filter((x) => (x.workdir || "") === dir);
    const ids = dirTasks.map((x) => x.id);
    const items = [
      { label: t("查看文件"), fn: () => openFolderFiles(dir) },
      { label: t("新建任务到该目录"), fn: () => newTaskInDir(dir) },
      "-",
      { label: t("打开工作目录"), fn: () => { if (ids[0]) revealPath("tasks", ids[0], true); } },
      { label: t("复制工作目录路径"), fn: () => { if (ids[0]) revealPath("tasks", ids[0], false); } },
      "-",
    ];
    const pinned = sidePinnedSet().has(dir);
    items.push({ label: pinned ? t("取消置顶") : t("置顶该文件夹"),
      fn: () => setSidePin(dir, !pinned) });
    items.push("-");
    items.push({ label: t("移除该文件夹"), danger: true, fn: () => removeSideDir(ids, dir) });
    items.push({ label: t("删除该文件夹"), danger: true, fn: () => deleteSideDir(ids, dir) });
    openCtxMenu(e.clientX, e.clientY, items);
  });
  // 文件夹展开/折叠：toggle 事件不冒泡，用捕获监听整个侧栏，实时写回 localStorage
  $("side-tasks").addEventListener("toggle", (e) => {
    if (e.target && e.target.classList && e.target.classList.contains("sdir")) saveOpenDirs();
  }, true);
  // 侧栏文件夹拖动只管置顶块：summary 整行可拖（单击仍走折叠，浏览器只在真拖起时吞掉 click）。
  // 事件委托挂在常驻的 #side-tasks 上，重绘 innerHTML 后无需重新绑定。
  const sideBox = $("side-tasks");
  const sideDragTarget = (ev) => {
    const el = ev.target && ev.target.closest && ev.target.closest(".sdir");
    if (!el) return null;
    const dir = el.dataset.dir;
    return dir && dir !== ORPHAN_DIR ? el : null;
  };
  const sideDragPair = (ev) => {
    if (!S.sideDragDir) return null;
    const el = sideDragTarget(ev);
    if (!el) return null;
    const to = el.dataset.dir;
    if (!sideDropAccepted(S.sideDragDir, to)) return null;
    return { el, from: S.sideDragDir, to };
  };
  sideBox.addEventListener("dragstart", (e) => {
    if (!(e.target.closest && e.target.closest("summary"))) return;
    const el = sideDragTarget(e);
    if (!el) return;
    S.sideDragDir = el.dataset.dir;
    el.classList.add("dragging");
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", el.dataset.dir);
    }
  });
  sideBox.addEventListener("dragover", (e) => {
    const pair = sideDragPair(e);
    if (!pair) return;          // 落点无效时不 preventDefault，浏览器自己给出禁止光标
    e.preventDefault();
    sideBox.querySelectorAll(".sdir.drag-over").forEach((n) => n.classList.remove("drag-over"));
    pair.el.classList.add("drag-over");
  });
  sideBox.addEventListener("dragleave", (e) => {
    const el = sideDragTarget(e);
    if (el) el.classList.remove("drag-over");
  });
  sideBox.addEventListener("drop", (e) => {
    const pair = sideDragPair(e);
    const from = S.sideDragDir;
    S.sideDragDir = "";  // 落点会触发重绘并摘掉源节点，之后的 dragend 冒泡不到这里
    if (from) e.preventDefault();  // 无效落点也要吞掉，否则浏览器会去导航被丢进来的文本/链接
    if (pair) applySideDrop(pair.from, pair.to);
  });
  sideBox.addEventListener("dragend", () => {
    S.sideDragDir = "";
    sideBox.querySelectorAll(".sdir.dragging, .sdir.drag-over").forEach((d) => d.classList.remove("dragging", "drag-over"));
  });
  document.addEventListener("click", closeCtxMenu, true);
  window.addEventListener("blur", closeCtxMenu);
  window.addEventListener("scroll", closeCtxMenu, true);
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeCtxMenu(); });
}

/* ------------------------------------------------- 文件夹选择（工作目录「选择…」/点输入框）
 * 首选系统原生对话框：服务端 tkinter 子进程弹真窗口（/api/pick_folder，仅本机），
 * 前端只收回填路径。机器没有 tkinter（fallback=true）时回落网页目录弹框：
 * /api/browse 浏览（服务端只给目录名、前端拼绝对路径），选定=行内「选这个」或
 * 底部「使用当前目录」。远端设备两条通道都被 403 拒：点输入框不再弹框，继续手输。 */
const pickerSt = { target: "", cwd: "", parent: "", local: null };   // local: null=未知 true=本机 false=远端

function pickerRender(r) {
  pickerSt.cwd = r.path;
  pickerSt.parent = r.parent || "";
  const atDrives = r.path === "此电脑";
  // 服务端只给目录名，这里拼回绝对路径（盘符行本身就是绝对路径）
  const sep = r.path.indexOf("\\") >= 0 ? "\\" : "/";
  const rows = (r.dirs || []).map((d) => {
    const full = /:[\\\/]$/.test(d) ? d : r.path.replace(/[\\/]+$/, "") + sep + d;
    return '<div class="pk-row" data-p="' + esc(full) + '" onclick="pickEnterP(this.dataset.p)">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-folder"></use></svg>' +
      '<span class="pk-name">' + esc(d) + "</span>" +
      '<button class="ghost small" onclick="event.stopPropagation();pickUseP(this.closest(\'.pk-row\').dataset.p)">' +
      esc(t("选这个")) + "</button></div>";
  }).join("");
  const body = $("pk-body");
  if (!body) return;
  body.innerHTML =
    '<div class="pk-tools">' +
    (atDrives ? "" :
      '<button class="ghost small" onclick="pickDrivesP()">' + esc(t("此电脑")) + "</button>" +
      (pickerSt.parent ? '<button class="ghost small" onclick="pickParentP()">' + esc(t("上级")) + "</button>" : "")) +
    '<span class="pk-path" title="' + esc(r.path === "此电脑" ? t("此电脑") : r.path) + '">' + esc(r.path === "此电脑" ? t("此电脑") : r.path) + "</span></div>" +
    '<div class="pk-list">' + (rows || '<div class="pk-empty hint">' + esc(t("（没有子目录）")) + "</div>") + "</div>";
}

async function pickerBrowse(p) {
  const body = $("pk-body");
  if (body) body.innerHTML = '<div class="hint">' + esc(t("正在读取目录…")) + "</div>";
  let r = null;
  try { r = await api("/api/browse?path=" + encodeURIComponent(p)); }
  catch (e) {
    if (/仅限本机/.test(e.message || "")) pickerSt.local = false;
    if (body) body.innerHTML = '<div class="msg bad">' + esc(t("读取失败：") + (e.message || e)) + "</div>";
    return false;
  }
  if (!r || r.error) {
    if (r && r.error && /仅限本机/.test(r.error)) pickerSt.local = false;
    if (body) body.innerHTML = '<div class="msg bad">' + esc((r && r.error) || t("读取失败")) + "</div>";
    return false;
  }
  pickerSt.local = true;
  pickerRender(r);
  return true;
}

/* 网页目录弹框（原生对话框不可用时的回落通道） */
async function webPickFolder(targetId, cur) {
  openModal(t("选择文件夹"), '<div id="pk-body" class="hint">' + esc(t("正在读取目录…")) + "</div>",
    '<button class="ghost" onclick="closeModal();pkRefocus()">' + esc(t("取消")) + "</button>" +
    '<button class="primary" onclick="pickUseP(pickerCwd())">' + esc(t("使用当前目录")) + "</button>");
  await pickerBrowse(cur || "__drives__");
}

// 目标可以是输入框 id，也可以直接是元素（禅道档案卡等工作目录输入框无 id）
const pickTargetEl = (tgt) => (typeof tgt === "string" ? $(tgt) : tgt) || null;

window.pickFolder = async function (targetId, fromClick) {
  if (fromClick && pickerSt.local === false) return;   // 远端已确认被拒：点击不打扰
  pickerSt.target = targetId;
  const cur = ((pickTargetEl(targetId) || {}).value || "").trim();
  let r = null;
  try {
    r = await api("/api/pick_folder", { method: "POST",
      body: JSON.stringify({ initial: cur, title: t("选择文件夹") }) });
  } catch (e) {
    if (/仅限本机/.test(e.message || "")) {
      pickerSt.local = false;
      if (fromClick) toast(t("目录选择仅限本机使用，请手动输入路径"), true);
      return;
    }
    toast(t("操作失败：") + (e.message || e), true);
    return;
  }
  if (r.busy) { toast(t("已有一个选择窗口正在等待"), true); return; }
  if (r.fallback) { await webPickFolder(targetId, cur); return; }
  if (r.path) pickUseP(r.path);
  else window.pkRefocus();   // 用户取消：焦点还给输入框，方便手输
};
window.pickEnterP = (p) => pickerBrowse(p);
window.pickParentP = () => pickerBrowse(pickerSt.parent || "__drives__");
window.pickDrivesP = () => pickerBrowse("__drives__");
window.pickerCwd = () => pickerSt.cwd;
// 取消/选定后把焦点还给输入框：点框弹出选择是常态，想手输的人取消后能直接打字
window.pkRefocus = () => { const el = pickTargetEl(pickerSt.target); if (el) el.focus(); };
window.pickUseP = (p) => {
  if (!p || p === "此电脑") { toast(t("请先进入一个具体目录"), true); return; }
  const el = pickTargetEl(pickerSt.target);
  if (el) {
    el.value = p;
    // 程序化赋值不触发原生事件：手动补，让 git 探测等既有联动照常走
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }
  closeModal();
  window.pkRefocus();
};

/* 右键菜单：打开/复制路径。open=true 由服务端在资源管理器打开目录；false 回传路径复制到剪贴板 */
async function revealPath(kind, id, open) {
  let r;
  try {
    r = await api("/api/" + kind + "/" + encodeURIComponent(id) + "/reveal",
      { method: "POST", body: JSON.stringify({ open: !!open }) });
  } catch (e) { toast(t("操作失败：") + e.message, true); return; }
  if (open) return;
  const txt = r.path || "";
  const done = () => toast(t("已复制：") + txt);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(done, () => fallbackCopy(txt, done));
  } else {
    fallbackCopy(txt, done);
  }
}

async function renameTask(id) {
  const task = ((S.state && S.state.tasks) || []).find((x) => x.id === id);
  // 局部变量不能叫 t：会遮蔽 i18n 函数 t()，下面的文案调用会直接 TypeError
  const name = (await uiPrompt(t("重命名任务"), (task && task.title) || "") || "").trim();
  if (!name) return;
  try {
    await api("/api/tasks/" + encodeURIComponent(id) + "/rename",
      { method: "POST", body: JSON.stringify({ title: name }) });
  } catch (e) { toast(t("重命名失败：") + e.message, true); return; }
  poll();
}

async function retryTask(id) {
  try {
    const r = await api("/api/tasks/" + encodeURIComponent(id) + "/retry", { method: "POST" });
    chatJumpLatest();   // 续跑副本开新一轮：时间线要跳到最新，别停在原地或历史中间
    jumpToRun(r.run_id);
  } catch (e) { toast(t("重试失败：") + e.message, true); return; }
  poll();
}

/* 继续连载：在旧任务基础上新建任务接着写下一批章节。沿用目标/目录/评审设置，
 * 章节号衔接（旧章不动），成书合并仍是完整一本。 */
async function continueSerial(id) {
  let info;
  try {
    info = await api("/api/tasks/" + encodeURIComponent(id) + "/continue-info", { busy: true });
  } catch (e) { toast(t("无法续写：") + e.message, true); return; }
  if (!info || !info.can) {
    toast(t("无法续写：") + ((info && info.reason) || t("当前状态不支持")), true);
    return;
  }
  const tip = t("已写到第 %1 章，将从第 %2 章接着写（同一工作目录，成书合并全本）。续写章数：")
    .replace("%1", info.last_chapter).replace("%2", info.last_chapter + 1);
  const raw = await uiPrompt(tip, String(info.default_chapters || 8));
  const ch = parseInt(raw, 10);
  if (!ch || ch < 1) return;
  let r;
  try {
    r = await api("/api/tasks/" + encodeURIComponent(id) + "/continue",
      { method: "POST", body: JSON.stringify({ chapters: ch }) });
  } catch (e) { toast(t("创建续写任务失败：") + e.message, true); return; }
  chatJumpLatest();   // 续写批次开新一轮：对话时间线跳到最新
  jumpToRun(r.run_id);
  poll();
}
window.continueSerial = continueSerial;

/* 提前完结：保留已完成章节，按用户给出的最终章号创建一批收束用续写任务。
 * 后端把目标章固化到连载链，后续章节继续正常起草、评审和发布，直到目标章。
 */
async function earlyFinishSerial(id) {
  let info;
  try {
    info = await api("/api/tasks/" + encodeURIComponent(id) + "/continue-info", { busy: true });
  } catch (e) { toast(t("无法读取连载进度：") + e.message, true); return; }
  if (!info || !info.can) {
    toast(t("无法提前完结：") + ((info && info.reason) || t("当前状态不支持")), true);
    return;
  }
  const last = Number(info.last_chapter || 0);
  const suggested = last + Math.max(1, Number(info.default_chapters || 8));
  const raw = await uiPrompt(
    t("当前已完成第 {0} 章。请输入新的最终章号；系统会重新规划收束路线并继续写完、发布到该章。", last),
    String(suggested));
  const target = parseInt(raw, 10);
  if (!target || target <= last) {
    if (raw != null && String(raw).trim()) toast(t("最终章号必须大于当前已完成章节"), true);
    return;
  }
  const reason = await uiPrompt(t("可选：请输入需要优先回收的伏笔或结局要求"), "");
  if (reason == null) return;
  let result;
  try {
    result = await api("/api/tasks/" + encodeURIComponent(id) + "/early-finish",
      { method: "POST", body: JSON.stringify({ target_chapter: target, reason }) });
  } catch (e) { toast(t("创建提前完结规划失败：") + e.message, true); return; }
  chatJumpLatest();
  if (result && result.run_id) jumpToRun(result.run_id);
  poll();
}
window.earlyFinishSerial = earlyFinishSerial;

async function editEarlyFinishSerial(id) {
  let info;
  try {
    info = await api("/api/tasks/" + encodeURIComponent(id) + "/continue-info", { busy: true });
  } catch (e) { toast(t("无法读取完结规划：") + e.message, true); return; }
  if (!info || !info.early_finish) {
    toast(t("当前没有提前完结规划"), true);
    return;
  }
  const targetRaw = await uiPrompt(t("请输入新的最终章号（当前第 {0} 章）", info.last_chapter),
    String(info.planned_end_chapter || info.last_chapter + 1));
  if (targetRaw == null) return;
  const target = parseInt(targetRaw, 10);
  if (!target || target <= Number(info.last_chapter || 0)) {
    toast(t("最终章号必须大于当前已完成章节"), true);
    return;
  }
  const reason = await uiPrompt(t("可选：请输入需要优先回收的伏笔或结局要求"),
    String(info.early_finish.reason || ""));
  if (reason == null) return;
  try {
    await api("/api/tasks/" + encodeURIComponent(id) + "/early-finish", {
      method: "POST",
      body: JSON.stringify({ action: "update", target_chapter: target, reason }),
    });
    toast(t("提前完结规划已更新"));
    poll();
  } catch (e) { toast(t("更新提前完结规划失败：") + e.message, true); }
}
window.editEarlyFinishSerial = editEarlyFinishSerial;

async function cancelEarlyFinishSerial(id) {
  if (!await uiConfirm(t("撤销后将允许继续扩写，但不会删除或回滚已有章节。确定撤销提前完结规划吗？"),
    { ok: t("撤销规划"), danger: true })) return;
  try {
    await api("/api/tasks/" + encodeURIComponent(id) + "/early-finish", {
      method: "POST", body: JSON.stringify({ action: "cancel" }),
    });
    toast(t("提前完结规划已撤销"));
    poll();
  } catch (e) { toast(t("撤销提前完结规划失败：") + e.message, true); }
}
window.cancelEarlyFinishSerial = cancelEarlyFinishSerial;

function setSelectionSerialButton(task) {
  const button = $("btn-selection-serial");
  if (!button) return;
  button.classList.toggle("hidden", !(task && task.type === "rank_scan"));
  button.disabled = !!(task && (task.status === "running" || task.status === "queued"));
}

async function serialFromSelection(id) {
  let info;
  try { info = await api("/api/tasks/" + encodeURIComponent(id) + "/selection", { busy: true }); }
  catch (e) { toast(e.message, true); return; }
  openModal(t("从选材新开连载"),
    '<p class="hint">' + esc(t("选择已审核方案，自动在选材目录下按书名新建文件夹并开始试写。内部通过不代表平台签约。")) + '</p>' +
    '<div class="field"><label for="sel-book">' + t("立项方案") + '</label><select id="sel-book">' +
    info.candidates.map((c) => '<option value="' + esc(c.id) + '">' + esc(c.title + ' · ' + c.platform) + '</option>').join("") +
    '</select></div><p id="sel-premise" class="hint"></p><p id="sel-path" class="hint"></p>' +
    '<div class="field"><label for="sel-chapters">' + t("试写章数") + '</label><input id="sel-chapters" type="number" min="2" max="20" value="8"></div>' +
    '<div class="field"><label for="sel-words">' + t("每章字数") + '</label><input id="sel-words" type="number" min="500" max="8000" value="2500"></div>' +
    '<p id="sel-error" class="msg" role="alert"></p>',
    '<button id="sel-cancel" class="ghost">' + t("取消") + '</button><button id="sel-start" class="primary">' + t("新建目录并开始连载") + '</button>');
  const showCandidate = () => {
    const c = info.candidates.find((x) => x.id === $("sel-book").value);
    $("sel-premise").textContent = c ? c.premise : "";
    $("sel-path").textContent = c ? info.parent_dir.replace(/[\\/]$/, "") + "/" + c.title : "";
  };
  $("sel-book").addEventListener("change", showCandidate);
  showCandidate();
  $("sel-cancel").onclick = closeModal;
  $("sel-start").onclick = async () => {
    const button = $("sel-start");
    const error = $("sel-error");
    const chapters = Number($("sel-chapters").value);
    const words = Number($("sel-words").value);
    if (!Number.isInteger(chapters) || chapters < 2 || chapters > 20 ||
        !Number.isInteger(words) || words < 500 || words > 8000) {
      error.textContent = t("章节数范围2-20，每章字数范围500-8000"); return;
    }
    const body = { run_id: info.run_id, candidate_id: $("sel-book").value,
      chapters, words_per_chapter: words };
    button.disabled = true;
    try {
      const result = await api("/api/tasks/" + encodeURIComponent(id) + "/selection/serial",
        { method: "POST", body: JSON.stringify(body) });
      closeModal();
      chatJumpLatest(); jumpToRun(result.run_id); poll();
    } catch (e) {
      // Keep the chosen book and editable inputs after validation/queue errors.
      error.textContent = e.message;
      button.disabled = false;
    }
  };
}

/* 基于此任务新建（通用，不限连载）：把旧任务的类型/目标/目录/评审设置预填进
 * 新建表单，确认或修改后提交——「接着写下一批章节」请用连载任务的「继续连载」，
 * 那里才带章节衔接；这里开的是一个全新任务。 */
const _taskDetailCache = new Map();
const _taskDetailInflight = new Map();
const _taskRunsCache = new Map();
const _taskRunsInflight = new Map();
const _taskRunsAt = new Map();
const _taskRunsPaging = new Map();
const _runMessagesCache = new Map();
const _runMessagesInflight = new Map();
let _taskStepRenderToken = 0;

async function loadTaskForPrefill(id) {
  const active = ((S.state || {}).tasks || []).find((x) => x.id === id);
  // state 里的活动任务 goal 超限会被截断（goal_truncated 打标）：预填必须
  // 拿全量，否则用户一保存就把旧任务的 goal 覆盖成残文——落到 /detail 取原文
  if (active && !active.goal_truncated) return active;
  const cached = _taskDetailCache.get(id);
  if (cached) return cached;
  if (_taskDetailInflight.has(id)) return _taskDetailInflight.get(id);
  const request = api("/api/tasks/" + encodeURIComponent(id) + "/detail",
    { timeout: 15000, busy: true, operation: "读取任务详情" })
    .then((data) => {
      if (!data || !data.task) throw new Error(t("任务不存在或已删除"));
      _taskDetailCache.set(id, data.task);
      return data.task;
    })
    .finally(() => _taskDetailInflight.delete(id));
  _taskDetailInflight.set(id, request);
  return request;
}

function newFromTask(id) {
  newFromTaskAsync(id);
}

async function newFromTaskAsync(id) {
  // 局部变量不能叫 t：会遮蔽 i18n 函数 t()，下面的文案调用会直接 TypeError
  let tk;
  try {
    const inState = ((S.state || {}).tasks || []).some((x) => x.id === id);
    if (!inState && !_taskDetailCache.has(id)) toast(t("正在读取任务详情…"));
    tk = await loadTaskForPrefill(id);
  } catch (e) { toast(t("读取任务详情失败：") + e.message, true); return; }
  exitSettings();   // 回到新建任务表单
  const flow = flowById(tk.type);
  if (flow && $("f-type").value !== tk.type) {
    $("f-type").value = tk.type;
    onTypeChange();  // 先带出流程默认（引擎区显隐/稿件名/维度），再覆盖为任务值
  }
  // 基于任务新建时保留原专家模板；仅当模板仍绑定当前流程时回填。
  const expertSel = $("f-expert");
  if (expertSel) {
    const expertId = String(tk.expert_id || (tk.expert_snapshot || {}).id || "");
    const expert = expertById(expertId);
    expertSel.value = expert && expert.flow_id === tk.type ? expert.id : "";
  }
  $("f-title").value = tk.title || "";
  $("f-goal").value = tk.goal || "";
  S.cmpPlugins = []; cmpReferenceContext = []; cmpRenderPluginChips();
  // context 里的「附件材料」块是服务端注入的（文件已在工作目录 _attachments/ 里），
  // 不随预填带走：新任务要么重新上传，要么由 _attachments 路径引用
  $("f-context").value = (tk.context || "").split("\n## 附件材料")[0].trimEnd();
  $("f-workdir").value = tk.workdir || "";
  const taskSandbox = tk.sandbox || {};
  $("f-sandbox-backend").value = taskSandbox.backend === "docker" ? "docker" : "native";
  $("f-sandbox-image").value = taskSandbox.docker_image || "";
  syncSandboxComposer();
  S.atts = []; renderAttachChips();  // 附件清单不继承：同目录引用已随 context 保留
  queueGitProbe();  // 工作目录变了，重新探测代码版本
  $("f-mode").value = ["fast", "expert", "manual"].includes(tk.mode) ? tk.mode : "auto";
  $("f-thinking").value = ["low", "standard", "high"].includes(tk.thinking)
    ? tk.thinking : "auto";
  $("f-manual-only").classList.toggle("hidden", $("f-mode").value !== "manual");
  renderImplSelects();
  if (tk.implementer) $("f-impl").value = tk.implementer;
  if (flow && flow.engine === "code") {
    $("f-verify").value = tk.verify_command || "";
  } else if (flow && flow.engine === "direct") {
    renderDirectModelPicker();
    $("f-direct-provider").value = tk.direct_provider_id || "";
    renderDirectModelPicker();
    $("f-direct-model-name").value = tk.direct_model || "";
    $("f-direct-agent").value = tk.direct_agent || "";
    cmpDirectBtnSync();
  } else {
    $("f-manuscript").value = tk.manuscript || "manuscript.md";
    $("f-rounds").value = tk.rounds || 2;
    $("f-threshold").value = (tk.threshold != null ? tk.threshold : 7.0);
    $("f-bestof").value = tk.best_of || 1;
    $("f-rubric").value = (tk.rubric || []).join(", ");
    $("f-drama-episodes").value = tk.drama ? tk.drama.episodes || "" : "";
    $("f-drama-seconds").value = tk.drama ? tk.drama.seconds_per_episode || "" : "";
    // 连载参数只带批次设置：不带 start_chapter/continues（那是「继续连载」的衔接语义）
    $("f-chapters").value = tk.serial ? tk.serial.chapters : "";
    $("f-words-per-ch").value = tk.serial ? tk.serial.words_per_chapter : "";
    $("f-variants").value = tk.serial && tk.serial.variants ? tk.serial.variants : "";
    $("f-branches").value = tk.serial && tk.serial.branches ? tk.serial.branches : "";
    // 分卷：还原每卷章数；指定卷结构还原成可读文本（卷名 + 章数/章号范围）
    $("f-vol-chapters").value = tk.serial && tk.serial.volume_chapters ? tk.serial.volume_chapters : "";
    $("f-vol-spec").value = tk.serial && Array.isArray(tk.serial.volumes)
      ? tk.serial.volumes.map((v) => {
          const ttl = (v && v.title) || t("未命名");
          if (v && v.start && v.end) return ttl + " " + t("第") + v.start + "-" + v.end + t("章");
          if (v && v.chapters) return ttl + " " + t("第") + v.chapters + t("章");
          return ttl;
        }).join(t("；"))
      : "";
    const want = new Set(tk.critics || []);
    $("f-critics").querySelectorAll("input").forEach((i) => { i.checked = want.has(i.value); });
    // 同目录同稿件名再开一篇会覆盖旧产出——提醒但不阻止（有意重写也合理）
    const hint = $("f-workdir-hint");
    if (hint) hint.textContent = tk.serial
      ? t("注意：沿用原目录时，提交会覆盖原书的章节与成书文件；续写请用「继续连载」")
      : t("注意：沿用原目录且稿件名相同时，提交会覆盖原稿件");
  }
  // 会话延续是那个任务当时的上下文，不跟着复制
  $("f-resume-agent").value = "";
  const rr = $("row-resume-session");
  if (rr) rr.classList.add("hidden");
  toast(t("已按「%1」预填新任务表单，确认或修改后提交").replace("%1", tk.title || tk.id));
}
window.newFromTask = newFromTask;

/* 文件夹右键「查看文件」：左侧栏整体切到文件浏览页（同设置视图的整页切换），
 * 递归列出该工作目录下全部文件，按目录层级渲染成可折叠树；点文件中央弹窗预览。
 * 返回 = 「返回任务列表」按钮，恢复任务树。 */
function openFolderFiles(dir) {
  S.sfDir = dir;   // 迟到响应比对用：返回后丢弃
  document.body.classList.add("files-mode");
  document.body.classList.remove("settings-mode");
  const last = String(dir || "").split(/[\\/]/).filter(Boolean).pop() || dir;
  const titleEl = $("sf-dir"), rowEl = $("sf-dir-row");
  if (titleEl) titleEl.textContent = last;
  if (rowEl) rowEl.title = dir;
  if ($("sf-count")) $("sf-count").textContent = "";
  if ($("sf-body")) $("sf-body").innerHTML = '<div class="sf-msg">' + esc(t("加载中…")) + "</div>";
  loadFolderFiles(dir);
}

/* 相对路径文件数组 → 嵌套树节点 {dirs:{名:节点}, files:[...]} */
function sfBuildTree(files) {
  const root = { dirs: {}, files: [] };
  (files || []).forEach((f) => {
    const parts = String(f.name).split("/");
    let node = root;
    for (let i = 0; i < parts.length - 1; i++)
      node = node.dirs[parts[i]] || (node.dirs[parts[i]] = { dirs: {}, files: [] });
    node.files.push(f);
  });
  return root;
}

function sfFIcon(n) {
  const ext = String(n).split(".").pop().toLowerCase();
  return ext === "md" || ext === "txt" ? "#i-book" : "#i-file";
}

/* 目录内文件行：点击中央弹窗预览（不开新标签页）。
 * data-dir 记文件名相对的目录（根扫=根目录，懒加载子目录=该子目录）——
 * 取内容按行上自己的目录拼 URL，不能用根目录，否则子目录文件必 404。 */
function sfFileHtml(f, depth, dir) {
  return '<a class="sf-file" style="--sf-d:' + depth + '" data-name="' + esc(f.name) +
    '" data-dir="' + esc(dir || "") + '" data-size="' + (Number(f.size) || 0) +
    '" href="javascript:void(0)"' +
    ' title="' + esc(f.name + " · " + fmtSize(f.size)) + '">' +
    '<svg class="ico" aria-hidden="true"><use href="' + sfFIcon(f.name) + '"/></svg>' +
    "<span>" + esc(String(f.name).split("/").pop()) + "</span><i>" + fmtSize(f.size) + "</i></a>";
}

/* 树节点渲染层：目录字典序在前、目录内文件 mtime 新→旧；
 * lazyDirs 是旧后端 scan 只扫一层时回的 subdirs 名单 → 渲染成懒加载文件夹，
 * 点开（ontoggle）再拉该子目录。dir 用于拼懒加载子目录的绝对路径。 */
function sfRenderLevel(node, depth, lazyDirs, dir) {
  const dirs = Object.keys(node.dirs).sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
  const fs = node.files.slice().sort((a, b) => (b.mtime - a.mtime) || a.name.localeCompare(b.name));
  const countOf = (nd) => nd.files.length +
    Object.keys(nd.dirs).reduce((n, k) => n + countOf(nd.dirs[k]), 0);
  return dirs.map((n) => {
    const sub = node.dirs[n];
    return '<details class="sf-dir" open style="--sf-d:' + depth + '">' +
      '<summary title="' + esc(n) + '"><svg class="ico" aria-hidden="true"><use href="#i-folder"/></svg>' +
      "<span>" + esc(n) + "</span><i>" + countOf(sub) + "</i></summary>" +
      sfRenderLevel(sub, depth + 1, null, dir) + "</details>";
  }).join("") +
    (lazyDirs || []).map((n) => {
      const sep = String(dir).indexOf("\\") >= 0 ? "\\" : "/";
      const full = String(dir).replace(/[\\/]+$/, "") + sep + n;
      return '<details class="sf-dir sf-lazy" style="--sf-d:' + depth + '" data-lazy="' + esc(full) +
        '" ontoggle="sfLazyToggle(this)">' +
        '<summary title="' + esc(n) + '"><svg class="ico" aria-hidden="true"><use href="#i-folder"/></svg>' +
        "<span>" + esc(n) + '</span><i class="sf-lc"></i></summary>' +
        '<div class="sf-kids"></div></details>';
    }).join("") + fs.map((f) => sfFileHtml(f, depth, dir)).join("");
}

/* 懒加载文件夹展开：第一次展开时扫该子目录并填充；失败清标记可重开重试 */
window.sfLazyToggle = async function (det) {
  if (!det.open || det.dataset.loaded) return;
  const dir = det.dataset.lazy || "";
  if (!dir) return;
  const kids = det.querySelector(".sf-kids");
  const badge = det.querySelector(".sf-lc");
  if (kids) kids.innerHTML = '<div class="sf-msg">' + esc(t("加载中…")) + "</div>";
  let d = null, err = "";
  try { d = await api("/api/dir/scan?path=" + encodeURIComponent(dir)); }
  catch (e) { err = (e && e.message) || String(e); }
  if (!det.open) return;   // 加载期间又被收起：丢弃
  if (!d || d.error) {
    if (kids) kids.innerHTML = '<div class="sf-msg sf-error">' +
      esc(t("读取失败：") + (err || (d && d.error) || t("未知错误"))) + "</div>";
    det.dataset.loaded = "";   // 允许下次展开重试
    return;
  }
  det.dataset.loaded = "1";
  let depth = 0;
  for (let p = det.parentElement; p; p = p.parentElement)
    if (p.classList && p.classList.contains("sf-dir")) depth++;
  if (kids) kids.innerHTML = sfRenderLevel(sfBuildTree(d.files), depth, d.subdirs, dir);
  if (badge) badge.textContent = (d.files || []).length ? String(d.files.length) : "";
};

async function loadFolderFiles(dir) {
  let d = null, err = "";
  try { d = await api("/api/dir/scan?path=" + encodeURIComponent(dir)); }
  catch (e) { err = (e && e.message) || String(e); }
  // 已返回任务列表 / 已切去别的文件夹：丢弃迟到响应
  if (!document.body.classList.contains("files-mode") || S.sfDir !== dir) return;
  const body = $("sf-body");
  if (!body) return;
  const cnt = $("sf-count");
  if (cnt) cnt.textContent = "";
  if (!d || (d.error && !(d.files || []).length)) {
    body.innerHTML = '<div class="sf-msg sf-error">' +
      esc(t("读取失败：") + (err || (d && d.error) || t("未知错误"))) + "</div>";
    return;
  }
  const files = d.files || [];
  if (cnt) cnt.textContent = files.length ? files.length + t(" 个文件") : "";
  if (!files.length && !(d.subdirs || []).length) {
    body.innerHTML = '<div class="sf-msg">' + esc(t("该目录下暂无文件")) + "</div>";
    return;
  }
  body.innerHTML = sfRenderLevel(sfBuildTree(files), 0, d.subdirs, dir);
}

/* 返回任务列表：左栏恢复任务树（文件页不留状态，重进即重扫） */
function closeFolderFiles() {
  S.sfDir = "";
  document.body.classList.remove("files-mode");
}

/* 文件夹右键「新建任务到该目录」：只预填工作目录，其余留白（ZCode 式——在该工作区里开新活） */
function newTaskInDir(dir) {
  exitSettings();   // 回到新建任务表单
  $("f-workdir").value = dir;
  unhideSideDir(dir);  // 在已移除的目录建任务 → 恢复显示
  queueGitProbe();  // 工作目录变了，重新探测代码版本
}

/* 文件夹右键「移除」：未归档任务整体归档后，整个目录从侧栏隐藏（可随时从
 * localStorage 的 tutti.hiddenDirs 找回，或在该目录新建任务自动恢复）；
 * 文件与运行记录都不动，运行中/排队的任务也照常归档——归档只是隐藏，运行不受影响。 */
async function removeSideDir(ids, dir) {
  if (!ids.length) {
    if (dir) hideSideDir(dir);
    return;
  }
  const ok = await uiConfirm(
    t("把该文件夹下 %1 个任务移出侧栏？文件与运行记录不会删除；移除后文件夹从侧栏隐藏，点侧栏时钟开关（显示已归档）可找回，在该目录新建任务也会重新显示。")
      .replace("%1", ids.length),
    { ok: t("移除") });
  if (!ok) return;
  // 有归档失败就不能藏文件夹：藏是 localStorage 假成功，服务端任务没归档，
  // 手机端等其他设备照样看得到这批任务（服务重启窗口实测案）。留文件夹让用户重试。
  let failed = 0;
  for (const id of ids) if (!await archiveTask(id, true)) failed++;
  if (failed) {
    toast(t("有 {0} 个任务归档失败，文件夹先保留；任务与文件都没动，稍后重试即可").replace("{0}", failed), true);
    return;
  }
  if (dir) hideSideDir(dir);
}

/* 文件夹右键「删除该文件夹」：目录下全部任务（含已归档灰显的）连同运行记录、
 * 日志、评审史一并删除——与任务行「删除」同一条后端链路（store.delete_task），
 * 工作目录磁盘上的文件不动。运行中/连载链前序任务会被服务端拒绝：有失败就
 * 保留文件夹让用户重试（部分已删不可回收，如实提示）；全成功才藏目录。 */
async function deleteSideDir(ids, dir) {
  if (!ids.length) return;
  const ok = await uiConfirm(
    t("把该文件夹下 %1 个任务连同全部运行记录（含日志与报告）一起删除？不可恢复；工作目录里的文件不会删。")
      .replace("%1", ids.length),
    { ok: t("删除"), danger: true });
  if (!ok) return;
  let failed = 0;
  for (const id of ids) if (!await deleteTaskCore(id)) failed++;
  if (failed) {
    toast(t("有 {0} 个任务删除失败，文件夹先保留；已删的不回收，稍后可重试其余任务").replace("{0}", failed), true);
    return;
  }
  if (dir) hideSideDir(dir);
}

/* ---------------------------------------------------------- 运行列表 */
/* 运行中/排队中的记录不可删除，勾选框置灰 */
function runDeletable(r) { return r.status !== "queued" && r.status !== "running"; }

function renderPauseAllButton() {
  const btn = $("btn-pause-all");
  if (!btn) return;
  const control = (S.state && S.state.pause_control) || { active: 0, paused: 0 };
  const shouldPause = control.paused < control.active;
  btn.classList.toggle("hidden", control.active === 0);
  btn.dataset.i18n = shouldPause ? t("全部暂停") : t("全部放行");
  btn.textContent = t(btn.dataset.i18n);
  btn.dataset.i18nTitle = shouldPause
    ? t("暂停所有编排任务：当前步骤结束后挂起；新建任务不受影响")
    : t("放行所有已暂停的编排任务");
  btn.title = t(btn.dataset.i18nTitle);
}

function renderRunList() {
  renderPauseAllButton();
  if (S.detailRunId) return;
  const box = $("run-list");
  if (!box) return;
  const allRuns = (S.state && S.state.runs) || [];
  const runs = allRuns.slice(0, 30);
  const pickable = new Set(runs.filter(runDeletable).map((r) => r.id));
  // 记录被删/转为活跃后清掉残留勾选，避免下次批量误删
  S.selRuns = S.selRuns || {};
  for (const id of Object.keys(S.selRuns)) if (!pickable.has(id)) delete S.selRuns[id];
  const selN = Object.keys(S.selRuns).length;
  const clr = $("btn-clear-runs");
  if (clr) clr.disabled = !allRuns.some(runDeletable);
  if (!runs.length) { box.innerHTML = '<div class="empty">' + t("暂无运行记录") + '</div>'; return; }
  const tools = '<div class="run-tools">' +
    '<label class="toggle"><input type="checkbox"' +
    (pickable.size && selN === pickable.size ? " checked" : "") +
    ' onchange="toggleAllRunSel(this.checked)">' + t(" 全选") + '</label>' +
    '<span class="n">' + (selN ? t("已选 ") + selN + t(" 条") : t("勾选可批量删除")) + "</span>" +
    (selN ? '<button class="danger small" onclick="deleteSelectedRuns()">' + t("删除所选") + '</button>' +
            '<button class="ghost small" onclick="clearRunSel()">' + t("取消选择") + '</button>' : "") +
    "</div>";
  box.innerHTML = tools + runs.map((r) => {
    const can = runDeletable(r);
    // 行结构照参考站的「主副标题 + 右侧状态与相对时间」：标题与摘要竖排成一块，
    // 状态点用侧栏同款字形（staskGlyph），时间用相对档（完整时间戳挪进悬停提示）
    const sub = String(r.summary || r.error || (r.step_count ? r.step_count + t(" 个步骤") : "")).trim();
    return '<div class="item" onclick="openRun(\'' + jsq(r.id) + '\')">' +
      '<div class="t">' +
      '<input type="checkbox" class="rcheck"' + (S.selRuns[r.id] ? " checked" : "") + (can ? "" : " disabled") +
      ' title="' + (can ? t("勾选以批量删除") : t("运行中的记录不可删除，请先取消")) + '"' +
      ' onclick="event.stopPropagation()" onchange="toggleRunSel(\'' + jsq(r.id) + '\', this.checked)">' +
      '<span class="rglyph">' + staskGlyph(r.status || "") + "</span>" +
      '<div class="rt">' +
      '<span class="name">' + esc(r.title) + runKindTag(r.kind) + "</span>" +
      (sub ? '<span class="desc">' + esc(t(sub)) + "</span>" : "") +
      "</div>" +
      '<span class="chip ' + esc(r.status || "") + (r.paused ? " pause-" + esc(r.pause_phase || "requested") : "") + '">' + esc(runStatusText(r)) + "</span>" +
      '<span class="time" title="' + esc(r.created_at) + '">' + esc(relTime(r.created_at)) + "</span>" +
      '<button class="danger small" title="' + (can ? t("删除该记录") : t("运行中的记录不可删除，请先取消")) + '"' + (can ? "" : " disabled") +
      ' onclick="event.stopPropagation(); deleteRun(\'' + jsq(r.id) + '\')">' + t("删除") + '</button></div></div>';
  }).join("");
}

/* 相对时间（紧凑档，ZCode 桌面端式样）："YYYY-MM-DD HH:MM:SS" → 刚刚/N 分/N 小时/昨天/N 天/MM-DD */
function relTime(s, now) {
  const m = String(s || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (!m) return String(s || "");
  // 局部变量不能叫 t：会遮蔽全局 i18n 函数 t()，下面 t("刚刚") 直接 TypeError
  const ts = new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]).getTime();
  const d = ((now || Date.now()) - ts) / 1000;
  if (d < 60) return t("刚刚");
  if (d < 3600) return Math.max(1, Math.floor(d / 60)) + t(" 分");
  if (d < 86400) return Math.floor(d / 3600) + t(" 小时");
  if (d < 172800) return t("昨天");
  if (d < 7 * 86400) return Math.floor(d / 86400) + t(" 天");
  return m[2] + "-" + m[3];
}

/* 任务行状态字形（ZCode 桌面端式样）：进行中旋转✻ / 完成绿点 / 失败红点 /
 * 取消橙点 / 排队空圈 / 从未运行暗点 */
function staskGlyph(status) {
  if (status === "running") return '<span class="sglyph ast">✻</span>';
  if (status === "done") return '<span class="sglyph ok"></span>';
  if (status === "failed") return '<span class="sglyph bad"></span>';
  if (status === "cancelled") return '<span class="sglyph warn"></span>';
  if (status === "timeout") return '<span class="sglyph tout">⏱</span>';
  if (status === "queued") return '<span class="sglyph ring"></span>';
  return '<span class="sglyph none"></span>';
}

/* 工作目录 → 展示名：取路径末段（Windows/Linux 分隔符都吃）；空或盘符根回落全路径。
 * demo-workdir 与 demo-workdir\qimao-20k 是不同目录，末段名不同，不会误合并。 */
function dirName(p) {
  const parts = String(p || "").split(/[\\/]+/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : (String(p || "") || "—");
}

/* 文件夹折叠态持久化：会话内以 DOM 为准，跨刷新靠 localStorage 记回上次展开的目录集合 */
const SIDE_DIRS_KEY = "orch.sideDirs";
function loadOpenDirs() {
  try {
    const raw = localStorage.getItem(SIDE_DIRS_KEY);
    if (!raw) return null;
    const a = JSON.parse(raw);
    return Array.isArray(a) ? new Set(a) : null;
  } catch (e) { return null; }
}
function saveOpenDirs() {
  try {
    const box = $("side-tasks");
    if (!box) return;
    const open = Array.from(box.querySelectorAll("details.sdir[open]")).map((d) => d.dataset.dir);
    localStorage.setItem(SIDE_DIRS_KEY, JSON.stringify(open));
  } catch (e) { /* 隐私模式忽略 */ }
}

/* 侧栏「置顶块 + 活跃度尾」：置顶的项目按用户摆的顺序恒在上，其余仍按最近活动倒序自动浮沉。
 * 只存置顶目录的有序数组（目录绝对路径才是稳定身份，dirs 每轮从任务重算，存下标会飘），
 * 空数组＝纯活跃度排序（改造前的默认行为）。「其他」是兜底聚合，恒垫底且不可置顶。 */
const SIDE_PIN_KEY = "orch.sidePinned";
function loadSidePins() {
  try {
    const a = JSON.parse(localStorage.getItem(SIDE_PIN_KEY) || "[]");
    return Array.isArray(a) ? a.filter((d) => typeof d === "string") : [];
  } catch (e) { return []; }
}
function sidePinnedSet() { return new Set(loadSidePins()); }
function saveSidePins(pins) {
  try { localStorage.setItem(SIDE_PIN_KEY, JSON.stringify(pins)); } catch (e) { /* 隐私模式忽略 */ }
  S.sideSig = ""; renderSideTasks();
}
function sortSideDirs(dirs, orphanDir) {
  const byTime = (a, b) => String(b.time || "").localeCompare(String(a.time || ""));
  const byOrphan = (a, b) => (a.dir === orphanDir ? 1 : 0) - (b.dir === orphanDir ? 1 : 0);
  const rank = {};
  loadSidePins().forEach((d, i) => { if (!(d in rank)) rank[d] = i; });
  const pk = (d) => (d.dir in rank ? rank[d.dir] : Number.MAX_SAFE_INTEGER);
  dirs.sort((a, b) => byOrphan(a, b) || (pk(a) - pk(b)) || byTime(a, b));
}
/* 右键菜单的显式开关：置顶＝插到置顶块最前，取消＝从块里摘掉、落回活跃度尾 */
function setSidePin(dir, on) {
  const pins = loadSidePins().filter((d) => d !== dir);
  if (on) pins.unshift(dir);
  saveSidePins(pins);
}
/* 拖动落点只管置顶块，其余交给活跃度：
 * 落在置顶行上 → 插到该行之前（块内改序，或把外面的项目拖进来顺手置顶）；
 * 落在非置顶行上 → 摘掉拖动的置顶项（把它拖出块）。
 * 两边都不在块里时没有可表达的顺序，dragover 直接不接受，浏览器显示禁止光标。 */
function sideDropAccepted(fromDir, toDir) {
  if (!fromDir || fromDir === toDir) return false;
  const pins = sidePinnedSet();
  return pins.has(toDir) || pins.has(fromDir);
}
function applySideDrop(fromDir, toDir) {
  const pins = loadSidePins().filter((d) => d !== fromDir);
  const at = pins.indexOf(toDir);
  if (at >= 0) pins.splice(at, 0, fromDir);
  saveSidePins(pins);
}

/* 侧栏「任务」树：文件夹（工作目录）→ 任务，两级。
 * 一级文件夹 = 任务 workdir 末段名（无主运行归「其他」垫底）；二级任务行 = 单行按钮：
 * 状态字形 + 单行省略标题 + 徽章 + 相对时间，点击主栏直开任务详情。
 * 以任务表为底：每个任务恒有一行，近况取后端全量下发的最近一次运行（task_latest）；
 * run 窗口只用来捞无主运行（管理操作/任务已删）。任务不因别人刷屏而消失。 */
/* 闸门等待提醒（Baton 式徽章 + 可选提示音）：
 * 任务进入「待裁决」（任务分支 isolated）或失败/取消时，侧栏行打徽标，
 * 并（默认）响一声短促提示——转移检测按任务快照比对，同状态不重复响。
 * 开关存 localStorage（orch.sound，默认开），侧栏「任务」标题旁的铃铛切换。 */
function soundEnabled() { return localStorage.getItem("orch.sound") !== "0"; }

function beepAttention() {
  if (!soundEnabled()) return;
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    if (!S._ac) S._ac = new AC();
    const ac = S._ac;
    if (ac.state === "suspended") { ac.resume().catch(() => {}); return; }  // 无手势激活时静默跳过
    const t0 = ac.currentTime;
    [[880, 0], [1320, 0.14]].forEach(([freq, dt]) => {
      const o = ac.createOscillator(), gn = ac.createGain();
      o.type = "sine"; o.frequency.value = freq;
      gn.gain.setValueAtTime(0.0001, t0 + dt);
      gn.gain.exponentialRampToValueAtTime(0.12, t0 + dt + 0.02);
      gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dt + 0.16);
      o.connect(gn); gn.connect(ac.destination);
      o.start(t0 + dt); o.stop(t0 + dt + 0.2);
    });
  } catch (e) { /* 音频不可用则忽略 */ }
}

/* 注意力状态快照：每任务 [git_state, 最近 run 状态, 未解除阻塞数]；
 * 新进入 待裁决/失败/出现阻塞 才响 */
function scanAttention(groups) {
  const cur = {};
  groups.forEach((g) => {
    if (!g.taskId) return;
    cur[g.taskId] = (g.verdict ? "isolated" : "") + "|" + (g.status || "") + "|" + (g.blockers || 0);
  });
  const prev = S._attention || {};
  S._attention = cur;
  const fired = Object.keys(cur).some((id) => {
    const was = prev[id];
    if (was === undefined || was === cur[id]) return false;   // 新任务/无变化不响
    const parts = cur[id].split("|");
    const wasBlockers = Number((was.split("|")[2] || "0"));
    return parts[0] === "isolated" || parts[1] === "failed" ||
           Number(parts[2] || 0) > wasBlockers;   // 反向通道：新阻塞浮现
  });
  if (fired) beepAttention();
}

window.toggleNotifySound = function () {
  const on = soundEnabled();
  localStorage.setItem("orch.sound", on ? "0" : "1");
  paintNotifyToggle();
  if (!on) beepAttention();
};

function paintNotifyToggle() {
  CodeBeeActivity.paintToggle();
  const b = $("activity-sound");
  if (!b) return;
  const on = soundEnabled();
  b.classList.toggle("off", !on);
  b.title = on ? t("提示音已开（点击关闭）") : t("提示音已关（点击开启）");
  b.setAttribute("aria-label", b.title);
  b.setAttribute("aria-pressed", String(on));
}

// 「展开全部」钮：文件夹全开时箭头翻成收起朝向，提示文案跟着换（renderSideTasks 末尾与点击后各同步一次）
function syncSideExpandBtn() {
  const b = $("btn-side-expand");
  if (!b) return;
  const dlist = Array.from($("side-tasks").querySelectorAll("details.sdir"));
  const allOpen = dlist.length > 0 && !dlist.some((d) => !d.open);
  b.classList.toggle("up", allOpen);
  b.title = t(allOpen ? t("收起全部") : t("展开全部"));
  b.setAttribute("aria-label", b.title);
}

// 「显示已归档」开关：点亮状态连同提示文案一起刷（原 HTML 里是写死的「显示已归档」）
function paintArchToggle() {
  const b = $("btn-side-arch");
  if (!b) return;
  b.classList.toggle("on", S.showArchived);
  const tip = t(S.showArchived ? t("隐藏已归档") : t("显示已归档"));
  b.title = tip;
  b.setAttribute("aria-label", tip);
}

/* 手机首页与侧栏共用目录/任务真源，保留独立的卡片展开态。 */
function renderMobileWorkspaces(dirs) {
  const box = $("mobile-workspace-list");
  if (!box) return;
  const painted = box.querySelector("details");
  const open = new Set(Array.from(box.querySelectorAll("details[open]")).map((d) => d.dataset.dir));
  $("sub-tasks").classList.toggle("mobile-has-workspaces", dirs.length > 0);
  $("mobile-workspaces-count").textContent = t("{0} 个工作区 · {1} 个任务", dirs.length,
    dirs.reduce((n, d) => n + d.groups.length, 0));
  box.innerHTML = dirs.map((d, i) => {
    const label = d.dir === ORPHAN_DIR ? t("其他") : dirName(d.dir);
    const expanded = painted ? open.has(d.dir) : d.active || i === 0;
    return '<article class="mobile-workspace-card"><details class="mobile-workspace" data-dir="' + esc(d.dir) + '"' + (expanded ? ' open' : '') + '>' +
      '<summary><svg class="ico mobile-folder" aria-hidden="true"><use href="#i-folder"/></svg>' +
      '<span class="mobile-workspace-copy"><b>' + esc(label) + '</b><span title="' + esc(d.dir) + '">' + esc(d.dir === ORPHAN_DIR ? t("其他") : d.dir) + '</span>' +
      '<small>' + esc(relTime(d.time)) + '</small></span><span class="mobile-workspace-total">' + d.groups.length + '</span>' +
      '<svg class="ico mobile-workspace-chevron" aria-hidden="true"><use href="#i-chevron-r"/></svg></summary>' +
      '<div class="mobile-workspace-tasks">' + d.groups.map((g) =>
        '<button type="button" class="mobile-task" data-task="' + esc(g.taskId) + '" data-run="' + esc(g.runIds[0] || '') + '">' +
        '<span class="mobile-task-copy"><b>' + esc(g.title) + '</b><small>' + esc(relTime(g.time)) + '</small></span>' +
        (g.verdict ? '<span class="sbadge">' + t("待裁决") + '</span>' : '') +
        (g.archived ? '<span class="sbadge">' + t("已归档") + '</span>' : statusChip(g.active ? 'running' : g.status || t("未运行"))) + '</button>'
      ).join('') + '</div></details>' +
      (d.dir === ORPHAN_DIR ? '' : '<button type="button" class="ghost mobile-workspace-new" data-new-dir="' + esc(d.dir) + '" title="' + esc(t("在此工作区新建任务")) + '" aria-label="' + esc(t("在此工作区新建任务")) + '"><svg class="ico" aria-hidden="true"><use href="#i-plus"/></svg></button>') + '</article>';
  }).join('');
}

function mobileNewTask(dir) {
  exitSettings();
  $("sub-tasks").classList.add("mobile-composing");
  if (dir) {
    $("f-workdir").value = dir;
    $("f-workdir").dispatchEvent(new Event("input", { bubbles: true }));
  }
  document.querySelector("main").scrollTop = 0;
}

/* 看板（2026-10-22 multica 视角落地）：issue 式任务组织——按生命周期分列，
 * 卡片即任务，点卡复用侧栏行激活链直开详情。列序：待办 → 排队 → 进行中 →
 * 待裁决 → 已完结；待裁决列聚合三源：agent 阻塞汇报（反向通道）、分支待裁决
 * （git_state=isolated）、审批待批（approval_pending）。数据与侧栏同源
 * （/api/state），无独立请求。 */
const KB_TERMINAL = { done: 1, failed: 1, cancelled: 1, timeout: 1 };
function renderKanban() {
  const box = $("kanban-board");
  if (!box) return;
  bindKanbanOnce();
  const st = S.state || {};
  const tasks = st.tasks || [];
  const latest = st.task_latest || {};
  const attn = st.task_attention || {};
  const cols = [
    { key: "todo", label: t("待办") },
    { key: "queued", label: t("排队中") },
    { key: "running", label: t("进行中") },
    { key: "review", label: t("待裁决") },
    { key: "done", label: t("已完结") },
  ];
  const buckets = {};
  cols.forEach((c) => { buckets[c.key] = []; });
  tasks.forEach((tk) => {
    const lr = latest[tk.id] || {};
    const runSt = lr.status || "";
    const a = attn[tk.id] || {};
    let col;
    if ((a.blocker && a.blocker.count) || a.approval_pending || tk.git_state === "isolated") col = "review";
    else if (runSt === "running" || tk.status === "running") col = "running";
    else if (runSt === "queued" || tk.status === "queued") col = "queued";
    else if (KB_TERMINAL[runSt]) col = "done";
    else col = "todo";
    buckets[col].push({
      id: tk.id, title: tk.title || tk.id, type: tk.type || "",
      runId: lr.id || "", status: runSt || tk.status || "",
      time: lr.started_at || lr.created_at || tk.created_at || "",
      blockers: (a.blocker && a.blocker.count) || 0,
      blockerText: (a.blocker && a.blocker.text) || "",
      verdict: tk.git_state === "isolated", approval: !!a.approval_pending,
    });
  });
  Object.keys(buckets).forEach((k) =>
    buckets[k].sort((a, b) => String(b.time || "").localeCompare(String(a.time || ""))));
  box.innerHTML = cols.map((c) => {
    const cards = buckets[c.key];
    return '<div class="kb-col" data-col="' + c.key + '">' +
      '<div class="kb-col-head"><span>' + esc(c.label) + '</span><b>' + cards.length + "</b></div>" +
      '<div class="kb-col-body">' +
      (cards.length ? cards.map((cd) =>
        '<button type="button" class="kb-card' + (cd.status === "running" ? " running" : "") +
        (c.key === "review" ? " attention" : "") + '"' +
        ' data-task="' + esc(cd.id) + '" data-run="' + esc(cd.runId) + '"' +
        ' data-status="' + esc(cd.status) + '" title="' + esc(cd.title) + '">' +
        '<span class="kb-card-title">' + esc(cd.title) + "</span>" +
        '<span class="kb-card-meta">' +
        (cd.type ? '<i class="kb-type">' + esc(cd.type) + "</i>" : "") +
        statusChip(cd.status || t("未运行")) +
        (cd.time ? "<small>" + esc(relTime(cd.time)) + "</small>" : "") +
        "</span>" +
        ((cd.blockers || cd.verdict || cd.approval)
          ? '<span class="kb-card-flags">' +
            (cd.blockers ? '<i class="kb-flag blocker">' + esc(t("阻塞")) + " " + cd.blockers + "</i>" : "") +
            (cd.verdict ? '<i class="kb-flag">' + esc(t("分支待裁决")) + "</i>" : "") +
            (cd.approval ? '<i class="kb-flag">' + esc(t("待审批")) + "</i>" : "") +
            "</span>" : "") +
        (cd.blockerText ? '<span class="kb-blocker-text">' + esc(cd.blockerText) + "</span>" : "") +
        "</button>").join("")
        : '<div class="kb-empty">' + esc(t("暂无任务")) + "</div>") +
      "</div>" +
      "</div>";
  }).join("");
}

/* 看板卡片点击：一次绑定长期生效（innerHTML 整块重建也不丢监听） */
function bindKanbanOnce() {
  const box = $("kanban-board");
  if (!box || box.dataset.bound) return;
  box.dataset.bound = "1";
  box.addEventListener("click", (e) => {
    const card = e.target.closest(".kb-card");
    if (card) sideRowActivate(card);
  });
}

function renderSideTasks() {
  const box = $("side-tasks");
  if (!box) return;
  const runs = ((S.state && S.state.runs) || []).slice(0, 40);
  // 「最近任务」面板已移除：归档找回走侧栏——开关打开时已归档任务灰显回原文件夹
  const tasks = ((S.state && S.state.tasks) || [])
    .concat(S.showArchived ? ((S.state && S.state.archived_tasks) || []) : []);
  const latest = (S.state && S.state.task_latest) || {};
  const archivedIds = archivedTaskIds();
  const tasksById = {};
  tasks.forEach((t) => { tasksById[t.id] = t; });
  // 标题、工作目录参与签名：重命名/换目录后侧栏要跟着重排，缺了会顶着旧分组
  // （内嵌步骤层已移除，run 步骤数不再上侧栏，不参与签名）
  const attn = (S.state && S.state.task_attention) || {};
  const sig = JSON.stringify([
    runs.map((r) => [r.id, r.status, r.title]),
    tasks.map((t) => [t.id, t.title, t.workdir, t.git_state || ""]),
    Object.keys(latest).map((k) => [k, latest[k].id, latest[k].status]),
    Object.keys(attn).map((k) => [k, (attn[k].blocker || {}).count || 0, !!attn[k].approval_pending]),
    S.detailRunId, S.detailTaskKey, archivedIds.size, S.showArchived, S.sideQ || "",
  ]);
  if (sig === S.sideSig && box.children.length) return;
  S.sideSig = sig;
  const ORPHAN = ORPHAN_DIR;  // 无主运行（无 task_id / 任务已删）的兜底文件夹
  const groups = [], byKey = {};
  const push = (key, taskId, title, status, time, dir) => {
    if (!byKey[key]) {
      byKey[key] = { key, taskId: taskId || "", title, status: status || "", time: time || "",
        dir: dir || ORPHAN, active: false, runIds: [] };
      groups.push(byKey[key]);
    }
    return byKey[key];
  };
  for (const t of tasks) {
    const isArch = archivedIds.has(t.id);
    if (isArch && !S.showArchived) continue;  // 已归档任务默认不上侧栏（开关打开则灰显找回）
    const lr = latest[t.id];
    const g = push(t.id, t.id, t.title || t.id, lr ? lr.status : "",
      lr ? (lr.started_at || lr.created_at) : t.created_at, t.workdir || ORPHAN);
    g.verdict = t.git_state === "isolated";   // 闸门等待：任务分支待裁决
    g.blockers = ((attn[t.id] || {}).blocker || {}).count || 0;   // 反向通道：agent 阻塞汇报未解除数
    g.archived = isArch;
    if (lr) {
      g.runIds.push(lr.id);
      if (lr.status === "running") g.active = true;
    }
  }
  for (const r of runs) {
    if (r.task_id && (tasksById[r.task_id] || archivedIds.has(r.task_id))) continue;  // 任务行已覆盖/已归档
    const g = push(r.task_id || r.id, r.task_id || "", r.title || r.id, r.status,
      r.started_at || r.created_at, ORPHAN);
    g.runIds.push(r.id);
    if (r.status === "running") g.active = true;
  }
  // 侧栏搜索（Ctrl+K）：按任务标题模糊过滤，文件夹随命中任务自动聚拢/消失
  const q = (S.sideQ || "").trim().toLowerCase();
  const fGroups = q ? groups.filter((g) => (g.title || "").toLowerCase().includes(q)) : groups;
  // 按工作目录聚成文件夹：文件夹时间取组内最近活动（排序用），有 running 任务则标记 active
  const dirs = [], dirMap = {};
  for (const g of fGroups) {
    let d = dirMap[g.dir];
    if (!d) { d = dirMap[g.dir] = { dir: g.dir, groups: [], time: "", active: false }; dirs.push(d); }
    d.groups.push(g);
    if (String(g.time || "") > String(d.time || "")) d.time = g.time;
    if (g.active) d.active = true;
  }
  // 已移除（隐藏）的目录不上侧栏；「其他」兜底永远保留（时钟开关打开时不剪，见 pruneHiddenSideDirs）
  pruneHiddenSideDirs(dirs, S.showArchived);
  // 组内任务按活动时间倒序；文件夹：无主运行「其他」恒垫底，其余按自动（最近活动倒序，
  // 活跃项目浮上来）或用户拖动后的手动顺序
  dirs.forEach((d) => d.groups.sort((a, b) => String(b.time || "").localeCompare(String(a.time || ""))));
  sortSideDirs(dirs, ORPHAN);
  // 文件夹展开态：会话内已渲染过 → 以 DOM 为准（保留用户点击）；首轮 → 读 localStorage，无则启发式
  const paintedDirs = !!box.querySelector("details.sdir");
  let openDirs;
  if (paintedDirs) {
    openDirs = new Set(Array.from(box.querySelectorAll("details.sdir[open]")).map((d) => d.dataset.dir));
  } else {
    const saved = loadOpenDirs();
    if (saved) openDirs = saved;
    else {
      openDirs = new Set();
      // 有 running 任务的文件夹优先展开；全折叠时至少展开最近活动那一个（真实数据里恒为
      // 非「其他」的首个文件夹；纯无主运行的测试场景下它就是唯一目录，必须展开否则几何断言全 0）
      const act = dirs.filter((d) => d.active);
      (act.length ? act : dirs.slice(0, 1)).forEach((d) => openDirs.add(d.dir));
    }
  }
  // 二级任务行：单行即全部——点击主栏直开任务详情。
  // 内嵌步骤层已砍：步骤/运行明细在任务详情里更全，侧栏只留状态字形 + 徽章 + 相对时间。
  // 右键菜单仍吃 data-task / data-run；主栏开着某任务详情时行保持高亮。
  const row = (g) => {
    if (g.active) g.status = "running";
    const sel = (g.key === S.detailTaskKey || g.runIds.indexOf(S.detailRunId) >= 0) ? " active" : "";
    return '<div class="stask' + sel + (g.archived ? " archived" : "") + '" tabindex="0" role="button" data-key="' + esc(g.key) +
      '" data-task="' + esc(g.taskId || "") + '" data-run="' + esc(g.runIds[0] || "") +
      '" data-status="' + esc(g.status || "") + '">' + staskGlyph(g.status) +
      '<span class="t">' + esc(g.title) + "</span>" +
      (g.archived ? '<span class="sbadge archb">' + t("已归档") + "</span>" : "") +
      (g.verdict ? '<span class="sbadge">' + t("待裁决") + "</span>" : "") +
      (g.blockers ? '<span class="sbadge kbb" title="' + esc(t("智能体上报的阻塞待处理，回信即解除")) + '">⚠ ' + g.blockers + "</span>" : "") +
      '<span class="tm">' + esc(relTime(g.time)) + "</span>" +
      '<button class="stask-more" type="button" aria-haspopup="menu" aria-label="' + esc(t("任务操作")) + '" title="' + esc(t("任务操作")) +
      '" onclick="event.stopPropagation();openTaskActions(this.closest(\'.stask\'), event)">⋯</button></div>';
  };
  // 一级文件夹行：折叠箭头 + 目录图标（已置顶的换成图钉，让置顶块边界一眼可辨）
  // + 末段名（hover 显全路径）+ 任务计数徽标
  const pinnedDirs = sidePinnedSet();
  box.innerHTML = dirs.map((d) => {
    const isOrphan = d.dir === ORPHAN;
    const label = isOrphan ? t("其他") : dirName(d.dir);
    const inner = d.groups.map(row).join("");
    const isOpen = openDirs.has(d.dir);
    const isPinned = pinnedDirs.has(d.dir);
    const canDrag = !isOrphan;
    return '<details class="sdir' + (isPinned ? " pinned" : "") + '" data-dir="' + esc(d.dir) + '"' +
      (isOpen ? " open" : "") + "><summary" + (canDrag ? ' draggable="true"' : "") + ">" +
      '<svg class="chev"><use href="#i-chevron-r"/></svg>' +
      '<svg class="fico"><use href="' + (isPinned ? "#i-pin" : "#i-folder") + '"/></svg>' +
      '<span class="t"' + (isOrphan ? "" : ' title="' + esc(d.dir) + '"') + ">" + esc(label) + "</span>" +
      '<span class="cnt">' + d.groups.length + "</span>" +
      (canDrag ? '<span class="drag" title="' + esc(t("拖动调整顺序")) + '"><svg class="ico" aria-hidden="true"><use href="#i-grip"/></svg></span>' : "") +
      "</summary>" +
      '<div class="dirbody">' + inner + "</div></details>";
  }).join("") || ('<div class="side-empty">' + (q ? t("无匹配任务") : t("暂无任务")) + "</div>");
  renderMobileWorkspaces(dirs);
  scanAttention(groups);
  paintNotifyToggle();
  syncSideExpandBtn();
  // 底部 pill 上的待裁决徽章：数量跟随全量任务（不受搜索过滤影响）
  const vcount = groups.filter((g) => g.verdict).length;
  const vb = $("prov-side-badge");
  if (vb) {
    vb.textContent = vcount > 9 ? "9+" : String(vcount);
    vb.classList.toggle("hidden", !vcount);
    vb.title = vcount ? vcount + t(" 个任务待裁决") : "";
  }
  // 急停钮现身条件同源侧栏真相（全量组，不受搜索过滤）：有排队/运行中任务
  // 才显示。点击走后端全量扫描，窗口外/侧栏外的活跃运行也一并取消。
  const acount = groups.filter((g) => g.status === "running" || g.status === "queued").length;
  const kb = $("btn-kill-all");
  if (kb) {
    kb.classList.toggle("hidden", !acount);
    kb.title = acount ? t("急停：取消全部进行中（排队/运行）任务") + "（" + acount + "）" : "";
  }
}

/* 主视图打开详情面板的公共部分：留在任务树，主栏切到运行/任务详情 */
function showDetailInMain() {
  S.tab = "runs";
  // 本函数刻意不走 switchTab（name==="runs" 且详情未开时会先 closeRun），离开主页的
  // composer 搬回契约就得自己扛：否则 .cmp-box 困在隐藏 page-home，对话「返回」回
  // #sub-tasks 只剩问候语和类型 chips（2026-10-22 实案）
  homeUnmountComposer();
  atlasLiveStop();   // 本函数刻意不走 switchTab（见下）：从图谱页点侧栏任务，动画与 atlas-live 得自己停
  const main = document.querySelector("main");
  if (main) main.classList.remove("browser-page-active");
  // 详情面板住在 page-settings 壳里：暖色皮肤停在工作台主页（page-home）时点侧栏任务行，
  // 壳必须一并翻回 page-settings，否则详情在隐藏页面里铺开＝点了没反应（2026-10-21 实案，
  // 同 homeOpenRun 先 switchTab 的老坑）。这里不走 switchTab：name==="runs" 且 detailRunId
  // 还没设时会先 closeRun，把调用方刚写好的 detailTaskKey 抹掉。
  document.querySelectorAll(".page").forEach((p) => p.classList.toggle("hidden", p.id !== "page-settings"));
  document.querySelectorAll("#page-settings .subpage").forEach((d) => d.classList.toggle("hidden", d.id !== "sub-runs"));
  document.querySelectorAll(".set-item").forEach((b) => b.classList.remove("active"));
  document.querySelectorAll(".qitem").forEach((b) => b.classList.toggle("active", b.dataset.page === "runs"));
  document.body.classList.remove("settings-mode", "files-mode");
  syncRailState();
  syncInspBtn();
  renderPageCrumb();
  collapseDrawerIfMobile();
  syncInspectorVis();    // 从设置子页点进运行详情：任务上下文，检查器跟着回来
}

/* 重试/续写/建任务产生新 run 后的统一去向：任务树主视图就地进详情（左栏不动），
 * 只有本来就在设置导航里才切 runs 子页（目录页「完整运行」按钮进来仍留在设置侧栏）。
 * 顺带清步骤定位，别把旧 run 的 focusStep 带进新详情。 */
function jumpToRun(id) {
  S.focusStep = 0;
  S.focusDone = false;
  if (document.body.classList.contains("settings-mode")) switchTab("runs", "settings");   // 已在设置里：留在设置侧栏
  else showDetailInMain();
  openRun(id);
}

/* 任务行激活（点击/键盘）：点任务 = 主栏（侧栏右边的中间区域）直接展开任务详情，
 * 聚合该任务全部 run 的步骤；不允许任何行点了没反应。
 * 无主运行行（任务已删/管理运行，data-task 为空）→ 直开它自己的运行详情；
 * 已归档任务 → toast 指路（归档行先取消归档）；
 * 从未跑过 → toast 说明；跑过但最新 run 排队中（自动续跑退避窗口）→ 照常开
 * 任务详情，能回看历史轮次的步骤与日志。 */
function sideRowActivate(det) {
  const taskId = det.dataset.task || "", runId = det.dataset.run || "";
  if (!taskId) {
    if (runId) sideOpenRun(runId);   // 无主运行：直开运行详情
    return;
  }
  const known = ((S.state || {}).tasks || []).some((x) => x.id === taskId);
  if (!known) {
    const arch = archivedTaskIds().has(taskId);
    toast(arch ? t("已归档任务：先在右键菜单里取消归档，再看任务详情") : t("任务不存在或已删除"), true);
    return;
  }
  if (!inspEligible(taskId)) {
    const lr = ((S.state || {}).task_latest || {})[taskId];
    if (!lr) { toast(t("该任务还没跑过，还没有任务详情"), true); return; }
  }
  sideOpenTask(taskId);
}

/* 打开单条运行详情（右键菜单「打开详情」/检查器步骤条）：不跳设置页——
 * 留在任务树主视图，主栏直接展示运行详情。
 * 带步骤号 n 时，详情渲染完自动定位到该步：滚动 + 高亮 + 展开它的日志。 */
window.sideOpenRun = function (id, n, pinTab) {
  _taskStepRenderToken++;
  const earlierRunsButton = $("rd-load-earlier");
  if (earlierRunsButton) earlierRunsButton.hidden = true;
  S.focusStep = Number(n) || 0;
  S.focusDone = false;
  S.detailTaskKey = null;
  if (!S.histJump && typeof histPush === "function") histPush({ m: "main", tab: "run-detail" });
  showDetailInMain();
  openRun(id, pinTab || (n ? "steps" : null));   // 活动视图可直达对应分区
};

/* 打开任务级详情：任务可能被续跑/重试过多次，步骤分散在多条 run 里。
 * 按时间顺序列出该任务全部 run 的全部步骤，run 之间加分隔条。 */
window.sideOpenTask = function (key, pinTab) {
  _taskStepRenderToken++;
  chatJumpLatest();   // 首开任务详情：默认进对话，时间线落最新
  $("rd-steps").innerHTML = '<div class="hint" role="status">' + esc(t("正在加载任务详情…")) + "</div>";
  S.lastRun = null;
  S.detailTaskKey = key;
  try { localStorage.setItem("orch.lastTask", key); } catch (e) { /* 隐私模式等 */ }
  S.activityTarget = pinTab ? { key, tab: pinTab } : null;
  S.detailRunId = null;
  S.focusStep = 0;
  S.taskSig = "";
  S.runDetailSig = "";   // 详情在任务态/运行态间共用同一套 DOM：切走必须作废运行态签名
  rdTabReset();
  if (!S.histJump && typeof histPush === "function") histPush({ m: "main", tab: "run-detail" });
  showDetailInMain();
  syncInspBtn();
  $("run-detail").classList.remove("hidden");
  document.querySelector("#sub-runs .panel:first-child").classList.add("hidden");
  detailSideReset();     // 换详情目标：任务级 side 缓存作废，等首拉
  const olderRunsButton = $("rd-load-earlier");
  if (olderRunsButton) olderRunsButton.hidden = true;
  S.rdTab = pinTab || null;   // 活动入口钉住目标页签；任务点击默认进对话（用户 2026-10-13），选卡交给 rdTabsSync
  S.rdTabPin = !!pinTab;
  S.rdTabSig = "";
  applyRdTabs();
  if (S.rdTab === "chat") chatScrollBottomNow($("rd-chat-flow"));
  syncInspectorVis();    // 详情已铺开：检查器让位（选中保留，返回列表自动滑回）
  renderTaskDetail();
};
window.openRunInRuns = function (id) { jumpToRun(id); };

/* 详情页右侧「✎ 编辑重试」开关：失败/取消的任务把「基于此任务新建」换成
 * 「编辑重试」——同一预填行为（newFromTask），标签贴合「改完再跑」的意图；
 * 其余状态维持原标签。两按钮互斥出现，按钮区不因新增功能多占一行。 */
function setEditRetry(taskId, status, taskExists) {
  const failedish = !!taskId && (status === "failed" || status === "cancelled" || status === "timeout");
  const be = $("btn-editretry");
  if (be) be.classList.toggle("hidden", !failedish);
  const bn = $("btn-newfrom");
  if (bn) bn.classList.toggle("hidden", !taskExists || failedish);
}

/* 详情页归档按钮：非运行中显示；已归档任务显示「取消归档」。
 * 点击走 archiveTask（与右键菜单同一链路：取消归档会自动恢复侧栏目录显示）。 */
function syncArchBtn(task, active) {
  const b = $("btn-arch");
  if (!b) return;
  const show = !!task && !active;
  b.classList.toggle("hidden", !show);
  if (!show) return;
  const archived = !!task.archived;
  b.textContent = archived ? t("取消归档") : t("归档任务");
  b.onclick = async () => {
    try {
      await archiveTask(task.id, !archived);
      b.textContent = archived ? t("归档任务") : t("取消归档");
    } catch (e) { /* archiveTask 内部已 toast */ }
  };
}

/* 质量未通过的代码任务也必须能重试：代码流水线会把「实现完成但验收未通过」
 * 收在 done + verdict.pass=false，不能因此把唯一的重试入口隐藏。 */
function runNeedsRetry(run) {
  if (!run || !run.task_id) return false;
  if (["failed", "cancelled", "timeout"].includes(run.status)) return true;
  if (run.status !== "done") return false;
  const v = run.verdict || {};
  return v.pass === false || v.publishable === false ||
    v.verify_pass === false || v.review_pass === false;
}

function retrySnapshotForTask(taskId, task, latestSummary) {
  const summary = latestSummary || {};
  if (task && (task.status === "running" || task.status === "queued"))
    return { task_id: taskId, status: task.status };
  if (runNeedsRetry(summary)) return summary;
  if (task && ["failed", "cancelled", "timeout"].includes(task.status))
    return { task_id: taskId, status: task.status };
  return summary;
}

/* 重试按钮三态：失败/取消/质量未通过 → 「↻ 继续任务」（断点续跑语义）；连载任务完整跑完
 * 但质量未达标（verdict.publishable=false）→ 「↻ 重写未达标章」——后端 retry
 * 会把未过线章从继承清单剔除，只重写重评这几章（store.retry_task 未达标分支）；
 * 其余状态隐藏。 */
function setRetryBtn(run, task) {
  const b = $("btn-retry");
  if (!b) return;
  const retryable = runNeedsRetry(run);
  const rewrite = !!(run.task_id && task && task.serial && run.status === "done"
    && run.verdict && run.verdict.publishable === false);
  b.classList.toggle("hidden", !(retryable || rewrite));
  b.textContent = rewrite ? t("↻ 重写未达标章")
    : (run.status === "done" ? t("↻ 重试任务")
      : run.status === "timeout" ? t("↻ 从超时进度继续") : t("↻ 继续任务"));
  b.title = rewrite
    ? t("只重写上一遍未过线的章节，已过线章节沿用成稿与评分")
    : run.status === "timeout"
      ? t("从最近一次已保存的大纲和已完成章节断点续跑")
      : t("再跑一次这个任务；连载任务会断点续跑，已完成章节不重写");
}

/* 「立即重试」：退避窗口内的续跑副本（将于 HH:MM 自动续跑）可跳过等待直接
 * 入队。只认 queued + 未来时刻的 resume_enqueue_at；普通并发排队每 15s 有
 * 补跑心跳，用不上这个按钮。退避相位在两处渲染的签名里都有（resumePending /
 * etaBucket 分钟桶），到点后下一帧自然隐藏。 */
function setResumeNowBtn(run) {
  const b = $("btn-resume-now");
  if (!b) return;
  const at = run && run.status === "queued"
    ? Date.parse(String(run.resume_enqueue_at || "").replace(" ", "T")) : NaN;
  const inBackoff = !isNaN(at) && Date.now() < at;
  b.classList.toggle("hidden", !inBackoff);
  S.resumeNowRunId = inBackoff ? run.id : null;
}

/* 「强制起跑」：被同工作目录互斥挡下的排队 run（blocked_by 非空）可人工
 * 放行并行起跑。只认 queued + blocked_by；点按钮先过确认弹窗（共享任务
 * 计划/项目记忆的风险），后端落 force_start 标记，起跑后的互斥检查见标记
 * 放行并留痕 warning。占用解除后自然起跑的 run 不亮按钮（无需强制）。 */
function setForceStartBtn(run) {
  const b = $("btn-force-start");
  if (!b) return;
  const blocked = !!(run && run.status === "queued" && run.blocked_by);
  b.classList.toggle("hidden", !blocked);
  S.forceStartRunId = blocked ? run.id : null;
}

/* 任务级详情：聚合该任务所有 run 的步骤。
 * 有任务档案的从 /api/tasks/<id>/runs 拉全量——前端 run 窗口只有最近 40 条，
 * 窗口外的历史会被算丢；无主运行组（管理操作/任务已删）仍用窗口数据。
 * 签名没变就不重画；报告与成品取最新一次 run 的（缓存避免轮询期反复拉取）。 */
function renderTaskDetail() {
  const key = S.detailTaskKey;
  if (!key) return;
  // 任务级按钮只看任务本身（state 里有 serial），不依赖 run 拉取——
  // 没跑过运行的任务也不能残留上一个任务留下的按钮状态
  const tk = ((S.state || {}).tasks || []).find((x) => x.id === key);
  const latestSummary = ((S.state || {}).task_latest || {})[key] || {};
  const latestSerial = latestSerialBatch(tk);
  const latestSerialSummary = latestSerial
    && (((S.state || {}).task_latest || {})[latestSerial.id]) || {};
  const earlyPlan = (latestSerial && latestSerial.serial && latestSerial.serial.early_finish)
    || (tk && tk.serial && tk.serial.early_finish) || null;
  const plannedEnd = Number(earlyPlan && earlyPlan.target_chapter || 0);
  const latestEnd = Number(latestSerialSummary.verdict
    && latestSerialSummary.verdict.end_chapter || 0);
  const reachedPlannedEnd = plannedEnd > 0 && latestEnd >= plannedEnd;
  const earlyFinishContentComplete = !!(plannedEnd > 0
    && latestSerialSummary.status === "done"
    && latestSerialSummary.verdict
    && latestSerialSummary.verdict.publishable === true
    && latestEnd >= plannedEnd);
  setSelectionSerialButton(tk);
  const bc = $("btn-continue");
  if (bc) bc.classList.toggle("hidden",
    !(tk && latestSerial && tk.serial
      && tk.status !== "running" && tk.status !== "queued"
      && !reachedPlannedEnd && !earlyFinishContentComplete));
  const bef = $("btn-early-finish");
  if (bef) bef.classList.toggle("hidden",
    !(tk && latestSerial && tk.id === latestSerial.id && tk.serial && !earlyPlan
      && tk.status !== "running" && tk.status !== "queued"));
  const befe = $("btn-early-finish-edit");
  if (befe) befe.classList.toggle("hidden",
    !(tk && earlyPlan && !earlyFinishContentComplete
      && latestSerial.status !== "running" && latestSerial.status !== "queued"));
  const befc = $("btn-early-finish-cancel");
  if (befc) befc.classList.toggle("hidden",
    !(tk && earlyPlan && !earlyFinishContentComplete
      && latestSerial.status !== "running" && latestSerial.status !== "queued"));
  setRetryBtn(retrySnapshotForTask(key, tk, latestSummary), tk);
  setEditRetry(tk ? tk.id : "", tk ? tk.status : "", !!tk);
  syncArchBtn(tk, tk && (tk.status === "running" || tk.status === "queued"));
  setResumeNowBtn(null);   // 退避与否要看 run 数据，先收起防上一个任务残留
  setForceStartBtn(null);   // 同理：blocked_by 要看 run 数据，先收起防残留
  const isTask = ((S.state || {}).tasks || []).some((t2) => t2.id === key);
  renderProjectMemoryControls(key);
  if (isTask) {
    refreshEarlyFinishChainInfo(tk, latestSummary.id || "");
    renderCheckpointControls(latestSummary.id || "", true);
    refreshCheckpointRestoreAvailability(latestSummary);
    if (latestSummary.id && S._checkpointRun !== latestSummary.id) {
      S._checkpointRun = latestSummary.id;
      loadRunCheckpoints(latestSummary.id);
    }
    loadTaskRuns(key, latestSummary);
    return;
  }
  drawTaskDetail(key, ((S.state || {}).runs || []).filter((r) => (r.task_id || r.id) === key));
}

function renderCheckpointControls(runId, visible) {
  const box = $("rd-checkpoints");
  if (!box) return;
  box.classList.toggle("hidden", !visible || !runId);
  if (runId && box.dataset.runId !== runId) {
    box.dataset.runId = runId;
    box.dataset.hasRestorable = "false";
    const restore = $("rd-checkpoints-restore");
    if (restore) restore.classList.add("hidden");
    box.classList.add("needs-load");
  }
}

function refreshCheckpointRestoreAvailability(run) {
  const box = $("rd-checkpoints");
  const button = $("rd-checkpoints-restore");
  if (!box || !button) return;
  const terminal = !!run && ["done", "failed", "cancelled", "timeout"].includes(run.status);
  button.classList.toggle("hidden", !terminal || box.dataset.hasRestorable !== "true");
}

function currentProjectMemoryTaskId() {
  return S.detailTaskKey || S.lastRun?.task_id || S.lastRunTask?.id;
}

function renderProjectMemoryControls(taskId) {
  const box = $("rd-project-memory");
  if (!box) return;
  const state = S.state || {};
  const task = [...(state.tasks || []), ...(state.archived_tasks || [])].find((item) => item.id === taskId);
  box.classList.toggle("hidden", !task || !task.workdir);
  if (!task || !task.workdir) {
    S._projectMemoryTask = "";
    S._projectMemorySeq = (S._projectMemorySeq || 0) + 1;
    return;
  }
  const latest = (state.task_latest || {})[taskId] || {};
  const workspaceMemories = [...(state.tasks || []), ...(state.archived_tasks || [])]
    .filter((item) => item.workdir === task.workdir)
    .map((item) => [item.id, state.task_latest?.[item.id]?.project_memory_id]);
  const signature = JSON.stringify([taskId, task.workdir, latest.id, latest.status, latest.project_memory_id, workspaceMemories]);
  if (S._projectMemoryTask !== signature) {
    S._projectMemoryTask = signature;
    loadProjectMemory(taskId);
  }
}

window.loadProjectMemory = async function (taskId) {
  taskId = taskId || currentProjectMemoryTaskId();
  if (!taskId) return;
  const requestSeq = S._projectMemorySeq = (S._projectMemorySeq || 0) + 1;
  const box = $("rd-project-memory-body");
  if (!box) return;
  box.textContent = t("正在加载项目记忆…");
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory");
    if (requestSeq !== S._projectMemorySeq) return;
    if (S.detailTaskKey && S.detailTaskKey !== taskId) return;
    const entries = data.entries || [];
    if (!entries.length) { box.innerHTML = '<span class="hint">' + esc(t("暂无项目记忆")) + "</span>"; return; }
    box.innerHTML = entries.map((entry) => {
      const canApprove = entry.status === "pending" && !entry.expired && entry.verified;
      const canRestore = entry.status === "archived" && !entry.expired && entry.verified;
      const feedback = entry.status === "approved" ? '<button type="button" class="ghost small" onclick="feedbackProjectMemory(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',true,' + Number(entry.version) + ')">' + esc(t("有用")) + '</button><button type="button" class="ghost small" onclick="feedbackProjectMemory(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',false,' + Number(entry.version) + ')">' + esc(t("无用")) + '</button>' : "";
      const feedbackCount = Number(entry.feedback_count || 0);
      const feedbackScore = Number(entry.feedback_score || 0);
      const feedbackSummary = feedbackCount > 0
        ? '<span class="hint rd-memory-feedback">' + esc(t("反馈")) + '：' +
          esc(feedbackScore > 0 ? t("有用") : (feedbackScore < 0 ? t("无用") : t("中性"))) +
          ' · ' + feedbackCount + esc(t("次")) + '</span>' : "";
      const actions = feedback + (canApprove ? '<button type="button" class="ghost small" onclick="decideProjectMemory(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',\'approve\',' + Number(entry.version) + ')">' + esc(t("批准")) + "</button><button type=\"button\" class=\"ghost small\" onclick=\"decideProjectMemory('" + jsq(taskId) + "','" + jsq(entry.id) + "','reject'," + Number(entry.version) + ')">' + esc(t("拒绝")) + "</button>" : "") +
        (entry.status === "approved" ? '<button type="button" class="ghost small" onclick="decideProjectMemory(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',\'archive\',' + Number(entry.version) + ')">' + esc(t("归档")) + "</button>" : "") +
        (canRestore ? '<button type="button" class="ghost small" onclick="decideProjectMemory(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',\'restore\',' + Number(entry.version) + ')">' + esc(t("恢复")) + "</button>" : "");
      return '<article class="rd-memory-row"><div><strong>' + esc(entry.title || t("项目记忆")) + '</strong><span class="chip">' + esc(entry.status || "") + (entry.expired ? " · " + esc(t("已过期")) : "") + '</span>' + feedbackSummary + '</div><pre>' + esc(entry.content || "") + '</pre><div class="rd-memory-actions">' + actions + "</div></article>";
    }).join("");
  } catch (error) {
    if (requestSeq !== S._projectMemorySeq || (S.detailTaskKey && S.detailTaskKey !== taskId)) return;
    S._projectMemoryTask = ""; // Allow the next detail refresh to retry a transient read failure.
    box.innerHTML = '<span class="hint">' + esc(t("加载项目记忆失败：")) + esc(error.message) + "</span>";
  }
};

window.previewProjectMemory = async function (taskId) {
  taskId = taskId || currentProjectMemoryTaskId();
  if (!taskId) return;
  const box = $("rd-project-memory-body");
  if (!box) return;
  const requestSeq = S._projectMemorySeq;
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory/preview?cap=4000");
    if (requestSeq !== S._projectMemorySeq || currentProjectMemoryTaskId() !== taskId) return;
    const entries = (data.entries || []).map((entry) =>
      '<span class="chip">' + esc(entry.title || t("项目记忆")) + ' · v' + esc(String(entry.version || 1)) + '</span>').join(" ");
    const text = data.text ? '<pre>' + esc(data.text) + '</pre>' : '<span class="hint">' + esc(t("暂无可注入记忆")) + '</span>';
    box.insertAdjacentHTML("afterbegin", '<div class="rd-memory-preview"><strong>' + esc(t("本次注入预览")) + '</strong><span class="hint">' + esc(t("已使用 {0}/{1} 字符", data.budget?.used || 0, data.budget?.cap || 0)) + '</span><div>' + entries + '</div>' + text + '</div>');
  } catch (error) { toast(t("项目记忆预览失败：") + error.message, true); }
};

window.decideProjectMemory = async function (taskId, id, action, version) {
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory", {
      method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()),
      body: JSON.stringify({ id, action, expected_version: version }),
    });
    await loadProjectMemory(taskId);
    const labels = { approve: t("批准"), reject: t("拒绝"), archive: t("归档"), restore: t("恢复") };
    toast(t("项目记忆已更新") + (labels[action] ? "：" + t(labels[action]) : ""));
  } catch (error) {
    toast(error && error.status === 423 ? error.message : t("项目记忆操作失败：") + error.message, true);
  }
};

window.feedbackProjectMemory = async function (taskId, id, useful, version) {
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory", {
      method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()),
      body: JSON.stringify({ id, action: "feedback", useful, expected_version: version }),
    });
    await loadProjectMemory(taskId);
    toast(t("项目记忆反馈已记录") + "：" + t(useful ? t("有用") : t("无用")));
  } catch (error) {
    toast(error && error.status === 423 ? error.message : t("项目记忆反馈失败：") + error.message, true);
  }
};

window.loadRunCheckpoints = async function (requestedRunId) {
  const runId = requestedRunId || S.detailRunId || ((S.state || {}).task_latest || {})[S.detailTaskKey]?.id;
  if (!runId) return;
  const requestSeq = S._checkpointRequestSeq = (S._checkpointRequestSeq || 0) + 1;
  const body = $("rd-checkpoints-body");
  const box = $("rd-checkpoints");
  box.classList.remove("hidden");
  body.textContent = t("正在读取文件检查点…");
  try {
    const data = await api("/api/runs/" + encodeURIComponent(runId) + "/checkpoints");
    if (requestSeq !== S._checkpointRequestSeq) return;
    if (S.detailRunId && S.detailRunId !== runId) return;
    if (S.detailTaskKey) {
      const current = ((S.state || {}).task_latest || {})[S.detailTaskKey];
      if (current && current.id !== runId) return;
    }
    const files = data.files && data.files.files || [];
    const restore = $("rd-checkpoints-restore");
    const latest = S.detailTaskKey && ((S.state || {}).task_latest || {})[S.detailTaskKey];
    const run = (S.lastRun && S.lastRun.id === runId) ? S.lastRun : latest;
    box.dataset.hasRestorable = files.some((file) => file.restorable) ? "true" : "false";
    refreshCheckpointRestoreAvailability(run);
    const checkpoint = data.checkpoint || {};
    const steps = Array.isArray(checkpoint.steps) ? checkpoint.steps : [];
    const stepSummary = steps.length ? '<div class="rd-checkpoint-steps"><strong>' + esc(t("步骤回放预览")) + '</strong>' +
      steps.map((step) => '<div class="rd-checkpoint-step"><span>#' + esc(String(step.step ?? "")) + ' · ' + esc(step.role || t("未命名步骤")) + '</span><span class="chip">' + esc(step.status || step.event || "unknown") + (step.attempt ? ' · ' + esc(t("第{0}次", step.attempt)) : "") + '</span></div>').join("") +
      (checkpoint.truncated ? '<p class="hint">' + esc(t("仅显示最近 200 个步骤，共 ") + (checkpoint.total_steps || steps.length)) + '</p>' : '') +
      (checkpoint.replayable ? '<p class="hint">' + esc(t("所有步骤均已完成，可人工复核后继续")) + '</p>' : '<p class="hint">' + esc(t("无法安全自动回放：") + (checkpoint.blocked_reason || t("需要人工核对"))) + '</p>') + '</div>' : '';
    body.innerHTML = (data.files && data.files.warning ? '<p class="hint">' + esc(data.files.warning) + "</p>" : "") + stepSummary +
      (files.length ? files.map((file) => '<article class="rd-checkpoint-row"><strong>' + esc(file.path) + '</strong><span class="chip">' + esc(file.status) + (file.restorable ? " · " + esc(t("可恢复")) : "") + '</span><pre>' + esc(file.diff || "") + "</pre></article>").join("") : '<span class="hint">' + esc(t("此运行没有文件快照")) + "</span>");
    box.dataset.runId = runId;
    box.classList.remove("needs-load");
  } catch (error) { body.innerHTML = '<span class="hint">' + esc(t("检查点读取失败：")) + esc(error.message) + "</span>"; }
};

window.restoreRunCheckpoints = async function () {
  const runId = $("rd-checkpoints")?.dataset.runId;
  if (!runId || !await uiConfirm(t("恢复会覆盖检查点记录的文件，shell、MCP 和外部服务副作用不保证可回滚。确定继续？"), { ok: t("恢复文件"), danger: true })) return;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(runId) + "/checkpoints/restore", {
      method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()),
      body: JSON.stringify({ confirm: true }),
    });
    toast(t("已恢复 ") + (result.restored || 0) + t(" 个文件") + ((result.conflicts || []).length ? "；" + t("冲突 ") + result.conflicts.join(", ") : ""));
    await loadRunCheckpoints();
  } catch (error) { toast(t("恢复失败：") + error.message, true); }
};

function loadTaskRuns(key, latestSummary) {
  const cached = _taskRunsCache.get(key);
  if (cached) {
    _taskRunsCache.delete(key);
    _taskRunsCache.set(key, cached);
  }
  if (cached && cached.length && latestSummary && cached[0].id === latestSummary.id) {
    const detailVerdict = cached[0].verdict;
    Object.assign(cached[0], latestSummary);
    if (detailVerdict) cached[0].verdict = Object.assign({}, latestSummary.verdict || {}, detailVerdict);
    drawTaskDetail(key, cached);
  }
  const latest = cached && cached[0];
  const hasNewRun = !!(latestSummary && latestSummary.id && (!latest || latestSummary.id !== latest.id));
  const active = !!(latestSummary && ["running", "queued"].includes(latestSummary.status));
  const minAge = active ? 2000 : 12000;
  const pageState = _taskRunsPaging.get(key);
  if (pageState && pageState.loading) return;
  if (_taskRunsInflight.has(key) ||
      (!hasNewRun && cached && Date.now() - (_taskRunsAt.get(key) || 0) < minAge)) return;
  if (!cached) {
    const task = ((S.state || {}).tasks || []).find((x) => x.id === key);
    $("rd-title").textContent = (task && task.title) || key;
    const chip = $("rd-status");
    chip.className = "chip queued";
    chip.textContent = t("加载中…");
    $("rd-steps").innerHTML = '<div class="hint" role="status">' + esc(t("正在加载任务详情…")) + "</div>";
  }
  _taskRunsAt.set(key, Date.now());
  const refreshLatestOnly = !!(cached && cached.length && latestSummary && cached[0].id === latestSummary.id);
  const url = refreshLatestOnly
    ? "/api/runs/" + encodeURIComponent(latestSummary.id)
    : "/api/tasks/" + encodeURIComponent(key) + "/runs?limit=3&offset=0";
  const request = api(url, { timeout: 20000 })
    .then((data) => {
      if (S.detailTaskKey !== key) return;
      let runs = (data && data.runs) || [];
      if (refreshLatestOnly && data && data.run) {
        runs = cached.slice();
        const prior = runs[0];
        runs[0] = data.run;
        const totals = (_taskRunsPaging.get(key) || {}).totals;
        if (totals) {
          const settled = (run) => (run.steps || []).filter((step) =>
            !["running", "queued"].includes(String(step.status || ""))).length;
          totals.steps += (data.run.steps || []).length - (prior.steps || []).length;
          totals.settled_steps += settled(data.run) - settled(prior);
          totals.cost_usd += (Number(data.run.cost_usd) || 0) - (Number(prior.cost_usd) || 0);
          totals.tokens += (Number(data.run.tokens) || 0) - (Number(prior.tokens) || 0);
        }
      }
      if (!refreshLatestOnly && data.total != null) _taskRunsPaging.set(key, {
        offset: Number(data.offset) + runs.length, total: Number(data.total),
        hasMore: !!data.has_more, totals: data.totals || null, loading: false,
      });
      if (data && data.contract) S.taskContracts[key] = data.contract;
      _taskRunsCache.delete(key);
      _taskRunsCache.set(key, runs);
      while (_taskRunsCache.size > 3) {
        const oldest = _taskRunsCache.keys().next().value;
        _taskRunsCache.delete(oldest);
        _taskRunsAt.delete(oldest);
        _taskRunsPaging.delete(oldest);
      }
      if (S.detailTaskKey === key) {
        if (runs.length) drawTaskDetail(key, runs);
        else {
          $("rd-status").textContent = t("暂无运行步骤");
          $("rd-steps").innerHTML = '<div class="empty">' + esc(t("暂无运行步骤")) + "</div>";
        }
      }
    })
    .catch((e) => {
      _taskRunsAt.set(key, 0);
      if (S.detailTaskKey === key && !_taskRunsCache.has(key)) {
        const chip = $("rd-status");
        chip.className = "chip failed";
        chip.textContent = t("加载失败");
        $("rd-steps").innerHTML = '<div class="hint">' + esc(t("加载失败：")) + esc(e.message) +
          ' <button type="button" class="ghost small" onclick="renderTaskDetail()">' + esc(t("重试")) + "</button></div>";
      }
    })
    .finally(() => _taskRunsInflight.delete(key));
  _taskRunsInflight.set(key, request);
}

async function loadEarlierTaskRuns(key) {
  const page = _taskRunsPaging.get(key);
  if (!page || !page.hasMore || page.loading) return;
  page.loading = true;
  _taskRunsPaging.set(key, page);
  const button = $("rd-load-earlier");
  if (button) { button.disabled = true; button.textContent = t("正在加载…"); }
  const request = api("/api/tasks/" + encodeURIComponent(key) + "/runs?limit=3&offset=" + page.offset,
    { timeout: 20000 });
  try {
    const data = await request;
    if (S.detailTaskKey !== key) return;
    const runs = _taskRunsCache.get(key) || [];
    const older = (data && data.runs) || [];
    const appendFrom = runs.length;
    _taskRunsCache.set(key, runs.concat(older));
    page.offset = Number(data.offset) + older.length;
    page.total = Number(data.total) || page.total;
    page.hasMore = !!data.has_more;
    if (data && data.contract) S.taskContracts[key] = data.contract;
    drawTaskDetail(key, _taskRunsCache.get(key), appendFrom);
  } catch (e) {
    toast(t("加载历史运行失败：") + e.message, true);
  } finally {
    page.loading = false;
    _taskRunsPaging.set(key, page);
    if (S.detailTaskKey === key && $("rd-load-earlier")) {
      const button = $("rd-load-earlier");
      button.disabled = !!page.rendering;
      button.textContent = t("加载更早运行") + " · " + Math.max(0, page.total - page.offset);
    }
  }
}
window.loadEarlierTaskRuns = loadEarlierTaskRuns;

function drawTaskDetail(key, runs, appendFrom) {
  if (!runs.length) return;
  // 消息数/未消费数也入签名：新指令或被 drain 后重画指挥区；步骤状态入签名：
  // 取消收尾把僵尸步骤落成「已取消」时要立即重画，不等条数变化；
  // 作品信息状态入签名：后台一键生成 running→done 要立刻反映到成果区面板。
  // 续写批次签名盯的是链上根任务的 book_meta（都是用第一个）+ 本任务封面状态
  const bmTask = ((S.state || {}).tasks || []).find((x) => x.id === key);
  const bmRoot = bmRootTask(bmTask || {});
  // 自动续跑退避相位入签名：预定启动时刻过了之后 chip 翻为「正在启动」
  const lr0 = runs[0] || {};
  const resumePending = (lr0.resume_enqueue_at &&
    Date.now() < Date.parse(String(lr0.resume_enqueue_at).replace(" ", "T"))) ? 1 : 0;
  // cost_usd/tokens 故意不入签名：运行中每次记账都在变，入签名会把整帧
  // 重绘变回「几秒一闪」；步骤状态翻转自然带上新数字，任务累计统计另有
  // detailSide 通道（2s 节流）保实时，两者都够新鲜。
  // 消息数/verdict 必须归一化再入签名：loadTaskRuns 每轮把 state 的摘要
  // 投影（message_count 等）assign 进缓存 run，下一轮干净 run 又洗掉这些
  // 键——裸取字段会在 null↔0 / 全量↔精简 verdict 间来回摆，每 8s 必重画
  // 一帧（2026-09-30 任务页闪烁实案）。归一后两种形状取值一致。
  const msgN = (r) => r.message_count != null ? Number(r.message_count)
    : (r.messages || []).length;
  const msgP = (r) => r.pending_message_count != null ? Number(r.pending_message_count)
    : (r.messages || []).filter((m) => !m.consumed).length;
  const vcmp = (r) => { const v = r.verdict || null;
    return v ? JSON.stringify([v.pass, v.publishable, v.verify_pass, v.review_pass]) : null; };
  const sig = JSON.stringify(runs.map((r) => [r.id, r.status, (r.steps || []).length,
    (r.steps || []).map((s) => s.status).join(""),
    msgN(r), msgP(r),
    r.summary, r.error, vcmp(r)])
    .concat([JSON.stringify([(bmRoot || {}).book_meta || null,
      (bmTask || {}).cover_gen || null]), resumePending]));
  if (sig === S.taskSig) return;
  S.taskSig = sig;
  const latest = runs[0];                       // runs 新→旧
  const ordered = runs.slice();                 // 详情按最近运行优先，方便排查
  const totalSteps = runs.reduce((a, r) => a + (r.steps || []).length, 0);
  const paging = _taskRunsPaging.get(key);
  const taskStats = ((S.state || {}).task_stats || {})[key] || {};
  const totalRuns = Number(taskStats.runs) || (paging && paging.total) || runs.length;
  const allSteps = Number(taskStats.steps) || (paging && paging.totals && paging.totals.steps) || totalSteps;
  const active = runs.some((r) => r.status === "running" || r.status === "queued");
  // 活跃态细分真实状态：queued 仅用于自动续跑退避或创建到起跑的瞬时状态；
  // 前者在 chip 上写明下一轮何时起跑，避免退避窗口看起来像卡死。
  const activeRun0 = runs.find((r) => r.status === "running" || r.status === "queued");
  const st = activeRun0 ? activeRun0.status : latest.status;
  const resumeIn = (st === "queued" && resumePending)
    ? String(latest.resume_enqueue_at).slice(11, 16) : "";
  $("rd-title").textContent = latest.title || key;
  const chip = $("rd-status");
  chip.className = "chip " + st;
  chip.textContent = resumeIn
    ? t("将于 ") + resumeIn + t(" 自动续跑（第 ") + (Number(latest.auto_resumes) || 0) + t(" 次）")
    : ({ queued: t("排队中"), running: t("运行中"), done: t("完成"), failed: t("失败"), cancelled: t("已取消") }[st] || st);
  const bpt = $("btn-pause");
  if (bpt) bpt.classList.add("hidden");
  $("btn-delete").classList.add("hidden");
  setRetryBtn(latest, bmTask);
  $("btn-talk").classList.toggle("hidden", !(latest.task_id && !chatEngineIsDirect(latest)));
  setEditRetry(latest.task_id, latest.status,
    !!((S.state || {}).tasks || []).some((x) => x.id === latest.task_id));
  S.lastRun = latest;
  syncBrowserSplitTask(latest.task_id);
  const sum = (f) => runs.reduce((a, r) => a + (Number(r[f]) || 0), 0);
  const aggregate = paging ? Object.assign({}, paging.totals || {}, {
    steps: allSteps,
    settled_steps: (paging.totals || {}).settled_steps != null
      ? Number(paging.totals.settled_steps) : totalSteps,
    cost_usd: (paging.totals || {}).cost_usd != null
      ? Number(paging.totals.cost_usd) : sum("cost_usd"),
    tokens: (paging.totals || {}).tokens != null
      ? Number(paging.totals.tokens) : sum("tokens"),
  }) : null;
  renderRunOutcome(latest, runs, aggregate);
  renderDetailOverview(latest, runs, bmTask, aggregate);
  // 指挥区指向最新的活跃运行（无则隐藏整个指挥区，避免终态任务误导用户以为指令还能生效）
  const activeRun = runs.find((r) => r.status === "queued" || r.status === "running");
  // 活跃运行（含排队中）显示取消按钮；取消目标钉在活跃 run——任务级详情没有
  // S.detailRunId，cancelRun 靠 S.cancelTargetRunId 知道取消谁
  $("btn-cancel").classList.toggle("hidden", !activeRun);
  S.cancelTargetRunId = activeRun ? activeRun.id : null;
  setResumeNowBtn(activeRun && activeRun.status === "queued" ? activeRun : null);
  setForceStartBtn(activeRun && activeRun.status === "queued" ? activeRun : null);
  const bp2 = $("btn-pause");
  if (bp2 && activeRun) {
    bp2.classList.toggle("hidden", false);
    bp2.textContent = activeRun.paused ? t("继续执行") : t("暂停");
  }
  renderDirector(activeRun || null, !!activeRun);
  renderHive(activeRun || latest);   // 终态回看最近一次运行的蜂巢
  renderChat(latest, active);        // 直连任务：对话时间线在任务级详情同样渲染（S.lastRun 已指向 latest）
  $("rd-meta").innerHTML =
    '<span class="stat">' + t("运行 ") + '<b>' + runs.length + "/" + totalRuns + "</b>" + t(" 次") + "</span>" +
    '<span class="stat">' + t("步骤 ") + '<b>' + totalSteps + "/" + allSteps + "</b>" + t(" 步") + "</span>" +
    '<span class="stat">' + t("成本 ") + '<b>¥' + (aggregate ? aggregate.cost_usd : sum("cost_usd")).toFixed(3) + "</b></span>" +
    '<span class="stat">tokens <b>' + (aggregate ? aggregate.tokens : sum("tokens")) + "</b></span>" +
    (latest.error ? '<span class="stat err">' + errTag(latest.error) + esc(latest.error.slice(0, 200)) + "</span>" : "");
  $("rd-plan").classList.add("hidden");
  renderRouting(latest);
  renderChapterScores(latest);
  const renderItems = [];
  ordered.forEach((r, i) => {
    if (appendFrom && i < appendFrom) return;
    renderItems.push({ run: r, runNo: totalRuns - i });
    const steps = r.steps || [];
    for (let stepIndex = steps.length - 1; stepIndex >= 0; stepIndex--)
      renderItems.push({ step: steps[stepIndex], runId: r.id });
  });
  const stepsBox = $("rd-steps");
  const appendOnly = Number.isInteger(appendFrom) && appendFrom > 0;
  if (!appendOnly) stepsBox.replaceChildren();
  let earlier = $("rd-load-earlier");
  if (!earlier) {
    earlier = document.createElement("button");
    earlier.id = "rd-load-earlier";
    earlier.type = "button";
    earlier.className = "ghost small";
    earlier.addEventListener("click", () => loadEarlierTaskRuns(S.detailTaskKey));
    stepsBox.after(earlier);
  }
  earlier.hidden = !paging || !paging.hasMore;
  earlier.disabled = !!(paging && (paging.loading || paging.rendering)) || renderItems.length > 30;
  if (paging) paging.rendering = renderItems.length > 30;
  earlier.textContent = t("加载更早运行") + (paging && paging.hasMore
    ? " · " + Math.max(0, paging.total - paging.offset) : "");
  const renderToken = ++_taskStepRenderToken;
  if (!renderItems.length) {
    stepsBox.innerHTML = '<div class="empty">' + t("尚无步骤") + '</div>';
  } else {
    let renderIndex = 0;
    const renderBatch = () => {
      if (renderToken !== _taskStepRenderToken || S.detailTaskKey !== key) return;
      const batch = [];
      const end = Math.min(renderIndex + 30, renderItems.length);
      for (; renderIndex < end; renderIndex++) {
        const item = renderItems[renderIndex];
        if (item.run) {
          const r = item.run;
          batch.push('<div class="run-sep"><span class="rs-i">' + t("第 ") + item.runNo + "/" + totalRuns + t(" 次运行") + '</span>' +
            '<span class="rs-t">' + esc(String(r.created_at || "").slice(5, 16)) + "</span>" +
            '<span class="chip ' + esc(r.status || "") + (r.paused ? " pause-" + esc(r.pause_phase || "requested") : "") + '">' + esc(runStatusText(r)) + "</span>" +
            (r.error ? '<span class="rs-err" title="' + esc(r.error.slice(0, 200)) + '">' + esc(r.error.slice(0, 60)) + "</span>" : "") +
            "</div>");
          continue;
        }
        const s = item.step;
        batch.push('<div class="step" data-n="' + Number(s.n) + '" data-run-id="' + esc(item.runId) + '" data-log="' + esc(s.log || "") + '" title="' + esc(s.note || "") + '">' +
          '<span class="n">' + String(s.n).padStart(2, "0") + "</span>" +
          '<span class="role">' + esc(s.role) + "</span>" +
          '<span class="who">' + esc(t(s.agent_label || s.agent)) + "</span>" +
          (String(s.model || "").trim() ? '<span class="st-model" title="' + esc(t("实际派发模型")) + '">' + esc(String(s.model).trim()) + "</span>" : "") +
          (String(s.provider || "").trim() ? '<span class="st-prov" title="' + esc(t("实际用上游（厂商@网关）")) + '">' + esc(String(s.provider).trim()) + "</span>" : "") +
          '<span class="sum">' + esc((s.note ? "◆ " + s.note + " — " : "") + (verdictDigestText(s.summary) || s.summary || "")) + "</span>" +
          '<span class="dur">' + (s.duration_s != null ? s.duration_s + "s" : "") + "</span>" +
          statusChip(s.status) +
          (s.log ? '<button class="step-log-btn" type="button" data-log-run="' + esc(item.runId) + '" data-log-rel="' + esc(s.log) + '" title="' + esc(t("查看日志")) + '">' + esc(t("CLI 日志")) + "</button>" : "") +
          "</div>");
      }
      stepsBox.insertAdjacentHTML("beforeend", batch.join(""));
      if (renderIndex < renderItems.length) requestAnimationFrame(renderBatch);
      else {
        if (paging) paging.rendering = false;
        earlier.disabled = !!(paging && paging.loading);
        applyStepFocus();
      }
    };
    renderBatch();
  }
  // 轮询重画不收起已打开的日志框：运行中日志靠 2.5s live 刷新持续更新，
  // 收起+清 currentLog 会让刚点开的输出被下一轮轮询弹掉
  if (currentLog && !stepsMatch(runs, currentLog)) window.rdLogClose();
  // 报告：最新一次 run 的（缓存，轮询重画不重复拉取）
  const drawReport = async () => {
    const hint = (msg) => {
      if (S.detailTaskKey !== key) return;   // 拉取期间切了详情：别糊到别的任务上
      $("rd-report").innerHTML = '<div class="hint">' + esc(msg) + "</div>";
    };
    if (S.taskReport && S.taskReport.key === key && S.taskReport.runId === latest.id) {
      $("rd-report").innerHTML = S.taskReport.html; return;
    }
    if (latest.status === "done" || latest.report) {
      try {
        const r = await fetch("/api/runs/" + encodeURIComponent(latest.id) + "/report",
          { headers: authHeaders() });
        if (!r.ok) throw new Error("HTTP " + r.status);
        const md = await r.text();
        if (!md.trim()) throw new Error("empty");
        const html2 = md2html(md);
        if (S.detailTaskKey !== key) return;   // 拉取期间切了详情：过期报告不落缓存/不落盘
        S.taskReport = { key, runId: latest.id, html: html2 };
        $("rd-report").innerHTML = html2;
      } catch (e) {
        // 拉取失败不再静默留白（手机端「报告空空」的来源之一）：给可见提示，
        // 不落缓存，下一轮轮询签名变化时自动重试
        hint(t("报告读取失败（{0}），稍后自动重试", (e || {}).message || t("网络异常")));
      }
    } else if (latest.status === "running" || latest.status === "queued") {
      hint(t("本次运行进行中：报告结束后在这里生成，实时进度看「步骤」页签"));
    } else {
      const st = { failed: t("失败"), cancelled: t("已取消"), timeout: t("超时") }[latest.status] || latest.status || "";
      hint(t("本次运行没有生成报告") + (st ? t("（状态：") + st + t("）") : "") +
        t("；各步骤日志在「步骤」页签"));
    }
  };
  drawReport();
  loadArtifacts(latest.id);   // 成品文件双入口同源：主栏「成果」分区 + 检查器（列表上下文）
  renderPreview(latest.id);   // 网页成品预览：入口页 + 可运行 iframe（无成品则整块隐藏）
  // 任务级详情：git 面板吃任务级 side（实时/最新快照），side 未到先以最新 run 快照落位
  const tk = ((S.state || {}).tasks || []).find((x) => x.id === key);
  S.lastRunTask = tk || null;
  renderGitPanel(latest, tk);
  renderBiblePanel(tk);
  renderBookMetaPanel(tk);
  refreshDetailSide();   // 有变化才重画版本面板；meta 累计组任务级详情已有全量 sums，不重复出
  const actSteps = ((activeRun || latest).steps || []);
  rdTabsSync({
    running: active, status: st, gitState: (tk || {}).git_state || "",
    steps: totalSteps,
    runningCount: actSteps.filter((x) => x.status === "running").length,
    hasResult: latest.status === "done" || !!latest.report,
  });
}

async function deleteRun(id) {
  if (!await uiConfirm(t("把该记录移出运行列表？任务、日志与成果文件都会保留。"), { ok: t("删除"), danger: true })) return;
  try {
    await api("/api/runs/" + encodeURIComponent(id) + "/delete", { method: "POST" });
  } catch (e) { toast(t("删除失败：") + e.message, true); return; }
  if (S.selRuns) delete S.selRuns[id];
  if (S.detailRunId === id) closeRun();
  poll();
}

/* 运行记录批量删除 / 一键全部清除 */
function toggleRunSel(id, on) {
  S.selRuns = S.selRuns || {};
  if (on) S.selRuns[id] = true; else delete S.selRuns[id];
  renderRunList();
}

function toggleAllRunSel(on) {
  S.selRuns = {};
  if (on) {
    const runs = ((S.state && S.state.runs) || []).slice(0, 30);
    for (const r of runs) if (runDeletable(r)) S.selRuns[r.id] = true;
  }
  renderRunList();
}

function clearRunSel() { S.selRuns = {}; renderRunList(); }

async function deleteSelectedRuns() {
  const ids = Object.keys(S.selRuns || {});
  if (!ids.length) return;
  if (!await uiConfirm(t("把所选 ") + ids.length + t(" 条记录移出运行列表？任务、日志与成果文件都会保留。"), { ok: t("删除"), danger: true })) return;
  let r;
  try {
    r = await api("/api/runs/delete", { method: "POST", body: JSON.stringify({ ids }) });
  } catch (e) { toast(t("批量删除失败：") + e.message, true); return; }
  S.selRuns = {};
  if (S.detailRunId && ids.indexOf(S.detailRunId) >= 0) closeRun();
  if (r && r.message) toast(r.message, true);
  poll();
}

async function clearRuns() {
  if (!await uiConfirm(t("把全部已结束记录移出运行列表？任务、日志与成果文件都会保留；运行中的记录不能清除。"), { ok: t("清除"), danger: true })) return;
  let r;
  try {
    r = await api("/api/runs/clear", { method: "POST" });
  } catch (e) { toast(t("清除失败：") + e.message, true); return; }
  S.selRuns = {};
  if (r && r.skipped) toast(t("已从列表移除 ") + r.count + t(" 条；另有 ") + r.skipped + t(" 条运行中的记录已保留（请先取消再清除）。"));
  else if (r) toast(t("已从列表移除 ") + r.count + t(" 条记录。"));
  poll();
}

/* 急停（kill switch）：取消全部排队/运行中任务。危险操作——确认框点名
 * 数量；后端全量扫，侧栏窗口外的活跃运行也一并取消。防双击：busy 期间
 * 直接吞掉重复点击。 */
async function cancelAllRuns() {
  const btn = $("btn-kill-all");
  if (!btn || btn.classList.contains("busy")) return;
  if (!await uiConfirm(t("确认急停：取消全部进行中（排队/运行）任务？"), { ok: t("急停"), danger: true })) return;
  btn.classList.add("busy");
  try {
    const d = await api("/api/runs/cancel_all", { method: "POST", timeout: 30000 });
    toast(t("已取消 ") + ((d && d.count) || 0) + t(" 个进行中任务"));
  } catch (e) {
    toast(t("急停失败：") + e.message, true);
  } finally {
    btn.classList.remove("busy");
  }
  poll();
}
window.cancelAllRuns = cancelAllRuns;

/* 蜂群级暂停：保留每个 run 的上下文和消息，只在下一步闸门统一挂起。 */
async function pauseAllRuns() {
  const btn = $("btn-pause-all");
  if (!btn || btn.classList.contains("busy")) return;
  const control = (S.state && S.state.pause_control) || { active: 0, paused: 0 };
  if (!control.active) return;
  const to = control.paused < control.active;
  const action = to ? t("暂停") : t("放行");
  btn.classList.add("busy");
  btn.disabled = true;
  try {
    const prompt = to
      ? t("暂停所有编排任务？当前步骤会继续执行，结束后在下一步前挂起；新建任务不受影响。")
      : t("放行所有已暂停的编排任务？这些任务将继续执行。");
    if (!await uiConfirm(prompt, { ok: action })) return;
    const d = await api("/api/runs/pause_all", {
      method: "POST", body: JSON.stringify({ paused: to }), timeout: 30000,
    });
    toast(t(to ? t("已为 {0} 个任务设置步骤间暂停") : t("已放行 {0} 个任务"), (d && d.count) || 0));
  } catch (e) {
    toast(t("批量操作失败：") + e.message, true);
  } finally {
    btn.classList.remove("busy");
    btn.disabled = false;
  }
  poll();
}
window.pauseAllRuns = pauseAllRuns;

async function openRun(id, pinTab) {
  _taskStepRenderToken++;
  chatJumpLatest();   // 首开运行详情：对话时间线落最新（历史长时别停在顶部）
  S.detailRunId = id;
  S.detailTaskKey = null;
  S.runDetailSig = "";   // 新目标首帧必画；也兜住「任务态改过 DOM 后回到本运行」的串台
  renderPageCrumb();   // 标题「运行详情」；必须在赋值后画——showDetailInMain 先于本函数跑，那边画不到
  rdTabReset(pinTab || null);   // sideOpenRun 带步骤号时钉住步骤分区
  document.querySelector("#sub-runs .panel:first-child").classList.add("hidden");
  $("run-detail").classList.remove("hidden");
  syncInspBtn();
  detailSideReset();     // 换详情目标：任务级 side 缓存作废，等首拉
  syncInspectorVis();    // 详情已铺开：检查器让位（选中保留，返回列表自动滑回）
  chatScrollBottomNow($("rd-chat-flow"));
  renderRunDetail();
}

function closeRun() {
  S.detailRunId = null;
  S.detailTaskKey = null;
  S.taskSig = "";
  S.runDetailSig = "";
  S.focusStep = 0;
  rdTabReset();
  stopLogLive();
  stopHiveTick();
  atlasLiveStop();   // 详情里点「返回」直连回任务页：不经 switchTab，图谱停表同契约
  closeBrowserSplit();   // 并排工作台只属于详情视图：离开详情（设置/主页/列表）一并收起
  detailSideReset();
  $("run-detail").classList.add("hidden");
  syncInspBtn();
  renderChatNav();   // 解除 main.chat-fill（对话为主的固定高度），恢复外层滚动
  if (document.body.classList.contains("settings-mode") || S.mainPage === "runs") {
    // 回运行列表：设置导航里点进来的，或主栏本就停在运行记录页（快捷导航/概览的入口）
    document.querySelector("#sub-runs .panel:first-child").classList.remove("hidden");
    renderPageCrumb();   // 详情关了，标题从「运行详情」回到当前页名
  } else if (S.mainPage) {
    // 主栏停在别的快捷导航页（概览/自动化）：返回点开详情前那一页，左栏任务树不动
    switchTab(S.mainPage, "main");
  } else {
    // 从主视图（侧栏点任务行）进来的详情：返回直接回任务页，不露出运行列表。
    // S.tab 还停在 "runs"（showDetailInMain 设的），视图既然回到任务页就一并归位，
    // 否则标题会拿 "runs" 的页名显示成「运行记录」
    S.tab = "tasks";
    document.querySelectorAll("#page-settings .subpage").forEach((d) => d.classList.toggle("hidden", d.id !== "sub-tasks"));
    document.querySelectorAll(".set-item").forEach((b) => b.classList.toggle("active", b.dataset.sub === "tasks"));
    document.querySelectorAll(".qitem").forEach((b) => b.classList.remove("active"));
    renderPageCrumb();
  }
  syncInspectorVis();    // 离开详情：回设置运行列表时检查器按各上下文规则重新落位
}

/* 侧栏点了具体子任务后：在运行详情里标出那一步。轮询会不停重画步骤区，
 * 所以高亮是持久的（.focus），而滚动 + 闪烁 + 展开日志只做一次（.flash）。 */
function applyStepFocus() {
  const n = S.focusStep;
  if (!n) return;
  const el = document.querySelector('#rd-steps .step[data-n="' + n + '"]');
  if (!el) return;
  el.classList.add("focus");
  if (S.focusDone) return;
  S.focusDone = true;
  el.classList.add("flash");
  try { el.scrollIntoView({ block: "center", behavior: "smooth" }); }
  catch (e) { el.scrollIntoView(); }
  if (el.dataset.log) toggleLog(el.dataset.runId || S.detailRunId, el.dataset.log);
  setTimeout(() => el.classList.remove("flash"), 1800);
}

/* ---------------- 详情页标签分区：蜂巢（实时）/ 步骤 / 成果 / 版本 / 圣经 ----------------
 * 主栏详情从一根长条改成五个分区：实时监控、历史步骤、交付成果、代码版本、故事圣经。
 * 分区内容的 hidden 语义保持不变（没数据整块收起）；标签页只切外层 .rd-pane，
 * 测试/代码对 #rd-hive、#rd-git 等 hidden 的判断不受影响。
 * 自动选卡只在「详情目标 + run 状态 + git 裁决态」签名变化时触发一次——
 * 轮询重画不抢用户手选的分区；带步骤号打开详情（sideOpenRun，检查器步骤条入口）钉住步骤分区。 */
function rdTabAvail() {
  return {
    chat: !$("rd-chat").classList.contains("hidden"),
    hive: !$("rd-hive").classList.contains("hidden"),
    steps: true,
    result: true,
    git: !$("rd-git").classList.contains("hidden"),
    bible: !$("rd-bible").classList.contains("hidden"),
    bookmeta: !$("rd-bookmeta").classList.contains("hidden"),
    preview: !$("rd-preview").classList.contains("hidden"),
  };
}

function applyRdTabs() {
  const avail = rdTabAvail();
  if (S.rdTab !== "hive" && typeof hiveFullscreenFallback !== "undefined" && hiveFullscreenFallback) {
    hiveFullscreenFallback = false;
    syncHiveFullscreenButton();
  }
  // 「切进对话页签」以 pane 入口前的真实显隐为准：rdChatNavGo/setRdTab 等
  // 入口都是先改 S.rdTab 再进来，函数内抓 S.rdTab 旧值抓不到过渡。
  const _chatPaneIn = document.querySelector('#run-detail .rd-pane[data-pane="chat"]');
  const chatWasHidden = !_chatPaneIn || _chatPaneIn.classList.contains("hidden");
  if (!S.rdTab || !avail[S.rdTab]) {
    S.rdTab = ["chat", "hive", "steps", "result", "preview", "git", "bible", "bookmeta"]
      .find((k) => avail[k]) || "steps";
  }
  document.querySelectorAll("#rd-tabs .rd-tab").forEach((b) => {
    b.classList.toggle("hidden", !avail[b.dataset.tab]);
    b.classList.toggle("active", b.dataset.tab === S.rdTab);
  });
  document.querySelectorAll("#run-detail .rd-pane").forEach((p) =>
    p.classList.toggle("hidden", p.dataset.pane !== S.rdTab));
  document.querySelectorAll("#rd-tabs .rd-tab").forEach((b) => {
    const active = b.dataset.tab === S.rdTab && !b.classList.contains("hidden");
    b.setAttribute("aria-selected", active ? "true" : "false");
    b.tabIndex = active ? 0 : -1;
  });
  document.querySelectorAll("#run-detail .rd-pane").forEach((p) =>
    p.setAttribute("aria-hidden", p.dataset.pane === S.rdTab ? "false" : "true"));
  const focusedTab = document.activeElement;
  if (focusedTab && focusedTab.matches && focusedTab.matches("#rd-tabs .rd-tab.hidden")) {
    const nextTab = document.querySelector('#rd-tabs .rd-tab[data-tab="' + S.rdTab + '"]:not(.hidden)');
    if (nextTab) nextTab.focus({ preventScroll: true });
  }
  // 对话页签不放日志抽屉：会盖住贴底输入条（手动切来/自动选卡都覆盖）
  if (S.rdTab === "chat" && !$("rd-log").classList.contains("hidden")) window.rdLogClose();
  renderChatNav();
  // 每次进入对话都落到最新；在同一页签内的轮询不改变回看历史的位置。
  // 内容已与当前 run 对齐（drawChatFlow 盖的 run 戳）才就地落底并消费——内容
  // 还是上一轮的旧帧（续跑换 run、/timeline 在途）则保留标记，等 drawChatFlow
  // 重建完新内容再落底，避免停在旧帧尾、新一轮气泡压在折叠线下面。
  if (S.rdTab === "chat" && chatWasHidden) {
    chatForceBottom = true;
    const fl = $("rd-chat-flow");
    if (fl && fl.offsetParent !== null && fl.dataset.runId === S.lastRun?.id) {
      chatScrollBottomNow(fl);
      chatForceBottom = false;
    }
  }
}

/* 直连任务「对话为主」布局：收起常规页签条，右上角一排小胶囊按需打开
 * 蜂巢/步骤/成果等分区；离开对话时给「返回对话」入口（用户 2026-09-17 拍板：
 * 对话场景其它页签用处不大，默认关掉、需要再点开）。 */
function renderChatNav() {
  const nav = $("rd-chat-nav"), detail = $("run-detail");
  if (!nav || !detail) return;
  const direct = !detail.classList.contains("hidden") && !!S.lastRun &&
    chatEngineIsDirect(S.lastRun);
  detail.classList.toggle("chat-mode", direct);
  // 对话为主时锁死外层滚动（main 是滚动根）；离开详情必须解锚，否则任务列表滚不动
  const mainEl = document.querySelector("main");
  if (mainEl) mainEl.classList.toggle("chat-fill", direct);
  renderChatContext(direct);
  if (!direct) { nav.classList.add("hidden"); nav.innerHTML = ""; return; }
  const labels = { hive: t("蜂巢"), steps: t("步骤"), result: t("成果"),
    preview: t("预览"), git: "Git", bible: t("圣经"), bookmeta: t("作品信息") };
  const avail = rdTabAvail();
  let pills = "";
  for (const k of ["preview", "hive", "steps", "result", "git", "bible", "bookmeta"]) {
    if (!avail[k]) continue;
    // 徽章直接镜像隐藏页签上的（蜂巢在岗数/步骤数/待裁决/成果数），不另设状态源
    const badge = document.querySelector('#rd-tabs .rd-tab[data-tab="' + k + '"] .rd-badge');
    pills += '<button class="cn-pill' + (S.rdTab === k ? " on" : "") +
      '" onclick="rdChatNavGo(\'' + k + '\')">' + labels[k] +
      (badge && badge.textContent ? "<b>" + esc(badge.textContent) + "</b>" : "") + "</button>";
  }
  nav.innerHTML = (S.rdTab !== "chat"
    ? '<button class="cn-back" onclick="rdChatNavBack()">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-arrow-left"></use></svg>' +
      t("返回对话") + "</button>"
    : "") +
    '<span class="cn-pills">' + pills + "</span>";
  nav.classList.remove("hidden");
}

function executionConfigHtml(run) {
  const config = ((run || {}).execution_snapshot || {}).configuration || {};
  const parameters = config.parameters || {};
  const steps = (run.steps || []).filter(step => step.configuration);
  if (!Object.keys(parameters).length && !steps.length) return "";
  const labels = { "task.request": t("任务指定"), "task.params": t("任务修改"), flow: t("流程"), default: t("默认"),
    "default.workload": t("按工作量默认"), environment: t("环境配置"), "task.implementer": t("手动执行者"),
    "task.direct_agent": t("指定 CLI"), "task.direct_provider": t("指定厂商"), "task.resume": t("续接会话"),
    "binding.explicit": t("显式模型绑定"), "binding.automatic": t("自动模型推荐"), "cli.default": t("CLI 默认"),
    orchestrator: t("编排者配置"), "provider.default": t("厂商默认"), automatic: t("自动选择"), unknown: t("未知"), mock: t("演示") };
  const label = source => t(labels[source] || source || t("未知"));
  const rows = Object.entries(parameters).map(([key, item]) => '<div class="rd-context-row"><span>' + esc(key) +
    '</span><span>' + esc(typeof item.value === "object" ? JSON.stringify(item.value) : String(item.value ?? "")) +
    ' · ' + esc(label(item.source)) + '</span></div>').join("");
  const actual = steps.map(step => {
    const binding = step.configuration, result = binding.result || {};
    const model = result.model || binding.model || "";
    const provider = result.provider_id || binding.provider_id || "";
    return '<div class="rd-context-row"><span>' + esc(step.role || String(step.n)) + '</span><span>' +
      esc([binding.agent, provider, model, label(binding.binding_source)].filter(Boolean).join(" · ")) + '</span></div>';
  }).join("");
  const selection = config.selection || {};
  return '<details class="rd-context-section" data-config-details><summary>' + esc(t("配置来源")) + '</summary>' +
    '<div class="hint">' + esc(t("任务选择：") + label(selection.source)) + '</div>' +
    ((selection.overrides || []).length ? '<div class="hint">' + esc(t("已被覆盖：") + selection.overrides.join(", ")) + '</div>' : "") + rows + actual + '</details>';
}

function renderChatContext(direct) {
  const box = $("rd-context");
  if (!box) return;
  if (!direct || !S.lastRun) {
    box.classList.add("hidden");
    $("rd-rail").classList.remove("context-open");
    return;
  }
  const key = detailSideTaskKey();
  const side = S.detailSide && S.detailSide.task && S.detailSide.task.id === key ? S.detailSide : null;
  const sideRun = side && side.run && side.run.id === S.lastRun.id ? side : null;
  const task = [S.lastRunTask].concat((S.state && S.state.tasks) || [], (S.state && S.state.archived_tasks) || [])
    .find(item => item && item.id === key) || (side && side.task) || {};
  const wb = S.gitWbKey === key && S.gitWb && S.gitWb.repo ? S.gitWb : null;
  const git = (side && side.git) || S.lastRun.git || {};
  const changes = (side && side.changes) || S.lastRun.changes || {};
  const branch = (wb && wb.branch) || git.branch || "";
  const path = String(task.workdir || "").replace(/[\\/]+$/, "");
  const project = path.split(/[\\/]/).filter(Boolean).pop() || task.title || t("项目");
  const steps = (sideRun && sideRun.steps) || S.lastRun.steps || [];
  const run = (sideRun && sideRun.run) || S.lastRun;
  const progress = (sideRun && sideRun.progress) || {};
  const done = progress.done == null ? steps.filter(step => step.status === "done").length : Number(progress.done);
  const total = progress.total == null ? steps.length : Number(progress.total);
  const current = steps.find(step => step.status === "running");
  const withLog = current && current.log ? current : steps.slice().reverse().find(step => step.log);
  const agentSteps = task.engine !== "direct" ? (S.lastRun.steps || []) : [];
  const agents = new Map();
  agentSteps.forEach(step => {
    const agent = step.agent || step.agent_label;
    if (agent) agents.set(agent, step.status);
  });
  const agentDone = [...agents.values()].filter(status => status === "done").length;
  const agentRunning = [...agents.values()].filter(status => status === "running" || status === "queued").length;
  const runId = run.id || S.lastRun.id;
  const timeline = $("rd-chat-flow").dataset.runId === S.lastRun.id ? chatTimelineItems : [];
  const sources = (task.attachments || []).map(item => ({ item, runId: S.lastRun.id }))
    .concat(timeline.filter(item => item.kind === "user").flatMap(item =>
      (item.attachments || []).map(attachment => ({ item: attachment, runId: item.run || S.lastRun.id }))));
  const seenSources = new Set();
  const atts = sources.map(({ item, runId }) => {
    const rel = typeof item === "string" ? item : (item && (item.path || item.name)) || "";
    const name = typeof item === "string" ? item.split(/[\\/]/).pop() : (item && item.name) || rel.split(/[\\/]/).pop();
    if (!rel || !name) return null;
    const normalized = String(rel).replace(/\\/g, "/");
    const path = normalized.startsWith("_attachments/") ? normalized : "_attachments/" + normalized.split("/").pop();
    const sourceKey = runId + "\n" + path;
    if (seenSources.has(sourceKey)) return null;
    seenSources.add(sourceKey);
    return { rel: path, name: String(name), runId };
  }).filter(Boolean);
  const sig = JSON.stringify([key, run.id, branch, changes.add_total, changes.del_total, done, total,
    steps.map(s => [s.n, s.status, s.summary, s.log, s.duration_s, s.configuration]), run.status, run.started_at,
    atts, project, !!wb, wb && wb.ahead, agents.size, agentDone, agentRunning,
    run.status === "running" ? Math.floor(Date.now() / 10000) : 0]);
  if (box.dataset.signature === sig) { box.classList.remove("hidden"); return; }
  box.dataset.signature = sig;
  const icon = name => '<svg class="ico" aria-hidden="true"><use href="#i-' + name + '"></use></svg>';
  let html = '<div class="rd-context-section"><div class="rd-context-heading"><span>' +
    esc(project) + '</span><button type="button" class="rd-context-icon" data-context-action="git" title="' +
    esc(t("打开 Git 工作台")) + '" aria-label="' + esc(t("打开 Git 工作台")) + '">···</button></div>';
  const add = changes.add_total, del = changes.del_total;
  if (branch || add != null || del != null) {
    html += '<button type="button" class="rd-context-row" data-context-action="git">' + icon("file-text") +
      '<span>' + esc(t("变更")) + '</span><span class="rd-context-spacer"></span>' +
      (add != null ? '<b class="rd-context-add">+' + Number(add) + '</b>' : "") +
      (del != null ? '<b class="rd-context-del">-' + Number(del) + '</b>' : "") + '</button>' +
      (branch ? '<button type="button" class="rd-context-row" data-context-action="git">' + icon("git-branch") +
      '<span class="rd-context-truncate" title="' + esc(branch) + '">' + esc(branch) + '</span>' + icon("chevron-r") + '</button>' : "") +
      '<button type="button" class="rd-context-row" data-context-action="git">' + icon("workflow") +
      '<span>' + esc(t("提交或推送")) + '</span>' +
      (wb && wb.ahead > 0 ? '<span class="rd-context-muted">↑' + wb.ahead + '</span>' : "") + '</button>';
  } else {
    html += '<div class="rd-context-muted rd-context-empty">' + esc(t("暂无 Git 变更")) + '</div>';
  }
  html += '</div>';
  if (total) {
    html += '<div class="rd-context-section"><div class="rd-context-subhead">' + esc(t("进程")) +
      '<span>' + done + '/' + total + '</span></div><div class="rd-context-steps">' +
      steps.slice(0, 8).map(step => '<button type="button" class="rd-context-step ' +
        esc(step.status || "") + '" data-context-action="step" data-step-n="' + Number(step.n || 0) +
        '" title="' + esc(step.summary || step.role || "") + '"><span class="rd-context-dot"></span>' +
        '<span>' + esc(step.summary || step.role || t("步骤")) + '</span></button>').join("") +
      '</div>' + (steps.length > 8 ? '<button type="button" class="rd-context-link" data-context-action="steps">' +
        esc(t("查看全部")) + '</button>' : "") + '</div>';
  }
  if (agents.size) {
    html += '<div class="rd-context-section"><div class="rd-context-subhead">' + esc(t("子智能体")) + '</div>' +
      '<button type="button" class="rd-context-row rd-context-agent" data-context-action="steps">' +
      icon("sun") + '<span>' + agentDone + ' ' + esc(t("完成")) + '</span>' +
      (agentRunning ? '<span class="rd-context-muted">' + agentRunning + ' ' + esc(t("运行中")) + '</span>' : '') +
      '</button></div>';
  }
  if (run.started_at || withLog) {
    const start = Date.parse(String(run.started_at || "").replace(" ", "T"));
    const end = Date.parse(String(run.ended_at || "").replace(" ", "T"));
    const seconds = Number.isFinite(start) ? Math.max(0, Math.floor(((Number.isFinite(end) ? end : Date.now()) - start) / 1000)) : 0;
    const duration = seconds >= 60 ? Math.floor(seconds / 60) + t("分") + Math.round(seconds % 60) + t("秒") : seconds + t("秒");
    html += '<div class="rd-context-section rd-context-terminal"><button type="button" class="rd-context-row" data-context-action="terminal"' +
      (withLog ? ' data-log-rel="' + esc(withLog.log) + '" data-log-run="' + esc(runId) + '"' : "") + '>' +
      '<span>' + esc(t("终端")) + '</span><span class="rd-context-muted">' + esc(duration) +
      (current ? ' · ' + esc(t("运行中")) : "") + '</span></button></div>';
  }
  html += '<div class="rd-context-section"><div class="rd-context-subhead">' + esc(t("来源")) +
    '<button type="button" class="rd-context-icon" data-context-action="attach" title="' +
      esc(t("添加附件")) + '" aria-label="' + esc(t("添加附件")) + '">' + icon("plus") + '</button>' +
    '</div><div class="rd-context-sources">' + (atts.length ? atts.map((att, i) =>
      '<button type="button" class="rd-context-source' + (i >= 3 ? ' rd-context-extra hidden' : '') +
      '" data-context-action="source" data-source-rel="' + esc(att.rel) + '" data-source-run="' + esc(att.runId) +
      '" title="' + esc(att.name) + '">' +
      icon("file-text") + '<span>' + esc(att.name) + '</span></button>').join("") :
      '<span class="rd-context-muted rd-context-empty">' + esc(t("暂无附件")) + '</span>') + '</div>' +
    (atts.length > 3 ? '<button type="button" class="rd-context-link" data-context-action="all-sources">' +
      icon("link") + esc(t("查看全部")) + '</button>' : "") + '</div>';
  html += executionConfigHtml(run);
  const configOpen = !!box.querySelector('[data-config-details][open]');
  box.innerHTML = html;
  if (configOpen && box.querySelector('[data-config-details]')) box.querySelector('[data-config-details]').open = true;
  if (box.dataset.sourcesExpanded === "true") {
    box.querySelectorAll(".rd-context-extra").forEach(row => row.classList.remove("hidden"));
    const all = box.querySelector('[data-context-action="all-sources"]');
    if (all) all.lastChild.textContent = t("收起");
  }
  box.classList.remove("hidden");
}
window.rdChatNavGo = function (tab) {
  S.rdTab = tab;
  S.rdTabPin = true;   // 用户主动去看其它分区：别被自动选卡拽回对话
  applyRdTabs();
};
window.rdChatNavBack = function () {
  S.rdTab = "chat";
  S.rdTabPin = false;
  S.rdTabSig = "";
  applyRdTabs();
};

/* 徽章：蜂巢=在岗数（运行中）、步骤=总步数、版本=待裁决、成果=文件数（loadArtifacts 里刷） */
function rdTabBadges() {
  const c = S._rdCtx || {};
  const set = (tab, text, cls) => {
    const el = document.querySelector('#rd-tabs .rd-tab[data-tab="' + tab + '"] .rd-badge');
    if (!el) return;
    el.textContent = text;
    el.className = "rd-badge" + (text ? (cls ? " " + cls : "") : " hidden");
  };
  set("hive", c.runningCount ? "● " + c.runningCount : "");
  set("steps", c.steps ? String(c.steps) : "");
  set("git", c.gitState === "isolated" ? t("待裁决") : "", "verdict");
}

/* ctx 可省略：省略时沿用上次的 _rdCtx 做自动选卡判断（renderHive/renderGitPanel/
 * renderPreview 等收尾调用——预览可用性是异步翻过来的，翻过来这次必须重选卡）。 */
function rdTabsSync(ctx) {
  if (ctx) S._rdCtx = ctx;
  const target = S.activityTarget;
  if (target && target.key === S.detailTaskKey && rdTabAvail()[target.tab]) {
    S.rdTab = target.tab;
    S.rdTabPin = true;
    S.activityTarget = null;
  }
  const c = ctx || S._rdCtx || {};
  if (!S.rdTabPin) {
    const chatAvail = $("rd-chat") && !$("rd-chat").classList.contains("hidden");
    // 预览可用性入签名：网页成品是跑完才落盘的，从不可用变可用时要重选一次卡
    const pvAvail = $("rd-preview") && !$("rd-preview").classList.contains("hidden");
    const sig = (S.detailTaskKey || S.detailRunId || "") + "|" + (c.status || "") +
      "|" + (c.gitState || "") + "|" + (c.running ? 1 : 0) + "|" + (chatAvail ? 1 : 0) +
      "|" + (pvAvail ? 1 : 0);
    if (S.rdTabSig !== sig) {
      S.rdTabSig = sig;
      const avail = rdTabAvail();
      const direct = chatAvail && chatEngineIsDirect(S.lastRun);
      const finishing = !c.running && ["done", "failed", "cancelled", "timeout"].includes(c.status);
      // 任务点击默认进对话（用户 2026-10-13）：有任务归属的运行（direct）直接落
      // 对话页签；蜂巢留给无主运行与管理型入口，手选页签/rdTabReset 后仍走本链。
      S.rdTab = (direct && avail.chat ? "chat" : null)
        // 跑出了能打开的网页成品：第一视线给「预览」——这正是用户做完一个
        // 前端任务最想看到的（借鉴对话式编程产品：跑完先看东西跑起来）。
        || (finishing && avail.preview ? "preview" : null)
        || (avail.hive ? "hive" : null)
        || (avail.chat ? "chat" : null)
        || (c.running ? "steps"
          : (c.gitState === "isolated" && avail.git ? "git"
            : (c.hasResult && finishing ? "result" : "steps")));
    }
  }
  applyRdTabs();
  rdTabBadges();
}

/* 详情头部的按需信息面板：统计和任务概览不再常驻挤占蜂巢/对话空间。 */
function setRdMetaOpen(open) {
  const detail = $("run-detail");
  const pop = $("rd-meta-popover");
  const toggle = $("rd-more-toggle");
  if (!pop || !toggle) return;
  const on = !!open;
  pop.classList.toggle("hidden", !on);
  if (detail) detail.classList.toggle("rd-info-open", on);
  toggle.setAttribute("aria-expanded", on ? "true" : "false");
}

/* 换一个详情目标时清空选卡状态：下一次渲染按新目标自动落位 */
function rdTabReset(pin) {
  S.rdTab = pin || null;
  S.rdTabSig = "";
  S.rdTabPin = !!pin;
  S._rdCtx = {};
  S._rdHeavy = { runId: "", report: false, artifacts: false, preview: false };
  S._rdDetailToken = (S._rdDetailToken || 0) + 1;
  pvReset();   // 预览也随详情目标清空：别家的 iframe/页签绝不带到新详情
  syncChatLogSpace(false);
  setRdMetaOpen(false);
}

const _rdReportCache = new Map();

function rdCurrent(id, token) {
  return S.detailRunId === id && !S.detailTaskKey &&
    (!token || token === S._rdDetailToken) &&
    !$('run-detail').classList.contains('hidden');
}

function rdScheduleNonCritical(fn) {
  const run = () => { try { fn(); } catch (e) { /* optional detail panels */ } };
  if (typeof window.requestIdleCallback === "function")
    window.requestIdleCallback(run, { timeout: 1200 });
  else setTimeout(run, 80);
}

function rdEnsureHeavyState(id) {
  if (!S._rdHeavy || S._rdHeavy.runId !== id)
    S._rdHeavy = { runId: id, status: "", report: false, artifacts: false, preview: false };
  return S._rdHeavy;
}

async function rdLoadReport(id, token) {
  const state = rdEnsureHeavyState(id);
  if (state.report || !rdCurrent(id, token)) return;
  const run = S.lastRun;
  if (!run || !(run.status === "done" || run.report)) return;
  state.report = true;
  const cached = _rdReportCache.get(id);
  if (cached) { $("rd-report").innerHTML = cached; return; }
  $("rd-report").innerHTML = '<div class="hint" role="status">' + esc(t("正在读取报告…")) + "</div>";
  try {
    const r = await fetch("/api/runs/" + encodeURIComponent(id) + "/report", { headers: authHeaders() });
    if (!r.ok) throw new Error("HTTP " + r.status);
    const md = await r.text();
    if (!md.trim()) throw new Error("empty");
    const html = md2html(md);
    if (!rdCurrent(id, token)) return;
    _rdReportCache.set(id, html);
    if (_rdReportCache.size > 3) _rdReportCache.delete(_rdReportCache.keys().next().value);
    $("rd-report").innerHTML = html;
  } catch (e) {
    if (rdCurrent(id, token)) {
      state.report = false;
      $("rd-report").innerHTML = '<div class="hint">' +
        esc(t("报告读取失败（{0}），稍后可重试", (e || {}).message || t("网络异常"))) + "</div>";
    }
  }
}

function rdEnsureActiveTabData() {
  if (S.detailTaskKey || !S.detailRunId) return;
  const id = S.detailRunId;
  const token = S._rdDetailToken;
  const state = rdEnsureHeavyState(id);
  if (S.rdTab === "result") {
    rdLoadReport(id, token);
    if (!state.artifacts) { state.artifacts = true; loadArtifacts(id); }
  } else if (S.rdTab === "preview" && !state.preview) {
    state.preview = true;
    renderPreview(id);
  } else if (S.rdTab === "git") {
    renderGitPanel(S.lastRun, S.lastRunTask);
  } else if (S.rdTab === "bible") {
    renderBiblePanel(S.lastRunTask);
  } else if (S.rdTab === "bookmeta") {
    renderBookMetaPanel(S.lastRunTask);
  }
}

function renderRunDetailSteps(run, token) {
  const box = $("rd-steps");
  if (!box) return;
  const rows = (run.steps || []).slice().reverse();
  if (!rows.length) { box.innerHTML = '<div class="empty">' + t("尚无步骤") + '</div>'; return; }
  box.replaceChildren();
  let index = 0;
  const renderBatch = () => {
    if (token !== S._rdDetailToken || S.detailRunId !== run.id || S.detailTaskKey) return;
    const html = [];
    const end = Math.min(index + 30, rows.length);
    for (; index < end; index++) {
      const s = rows[index];
      html.push('<div class="step" data-n="' + Number(s.n) + '" data-run-id="' + esc(run.id) + '" data-log="' + esc(s.log || "") +
        '" title="' + esc(s.note || "") + '">' +
        '<span class="n">' + String(s.n).padStart(2, "0") + "</span>" +
        '<span class="role">' + esc(s.role) + "</span>" +
        '<span class="who">' + esc(t(s.agent_label || s.agent)) + "</span>" +
        (s.model ? '<span class="st-model" title="' + esc(t("实际派发模型")) + '">' + esc(s.model) + "</span>" : "") +
        (String(s.provider || "").trim() ? '<span class="st-prov" title="' + esc(t("实际用上游（厂商@网关）")) + '">' + esc(String(s.provider).trim()) + "</span>" : "") +
        '<span class="sum">' + esc((s.note ? "◆ " + s.note + " — " : "") + (verdictDigestText(s.summary) || s.summary || "")) + "</span>" +
        '<span class="dur">' + (s.duration_s != null ? s.duration_s + "s" : "") + "</span>" +
        statusChip(s.status) +
        (s.log ? '<button class="step-log-btn" type="button" data-log-run="' + esc(run.id) + '" data-log-rel="' + esc(s.log) + '" title="' + esc(t("查看日志")) + '">' + esc(t("CLI 日志")) + "</button>" : "") +
        "</div>");
    }
    box.insertAdjacentHTML("beforeend", html.join(""));
    if (index < rows.length) requestAnimationFrame(renderBatch);
    else applyStepFocus();
  };
  renderBatch();
}

async function renderRunDetail() {
  const id = S.detailRunId;
  if (S.detailTaskKey) { renderTaskDetail(); return; }   // 任务级详情（轮询也会走到这里刷新）
  if (!id) return;
  const token = S._rdDetailToken || (S._rdDetailToken = 1);
  const fetchSeq = S._rdFetchSeq = (S._rdFetchSeq || 0) + 1;
  let run;
  try { run = (await api("/api/runs/" + encodeURIComponent(id))).run; }
  catch (e) { return; }
  if (!run) return;
  if (!rdCurrent(id, token) || fetchSeq !== S._rdFetchSeq) return;   // 拉取期间已切走/被更新请求取代
  $("rd-title").textContent = run.title;
  const chip = $("rd-status");
  chip.className = "chip " + run.status + (run.paused
    ? " pause-" + (run.pause_phase || "requested") : "") +
    (run.status === "done" && run.verdict && run.verdict.pass === false ? " unqualified" : "");
  chip.textContent = runStatusText(run);
  const active = run.status === "queued" || run.status === "running";
  $("btn-cancel").classList.toggle("hidden", !active);
  S.cancelTargetRunId = active ? run.id : null;
  setResumeNowBtn(run.status === "queued" ? run : null);   // 在 sig 守卫前：退避相位由 etaBucket 分钟桶兜底刷新
  setForceStartBtn(run.status === "queued" ? run : null);   // 同在前：blocked_by 随 run 刷新
  $("btn-delete").classList.toggle("hidden", active);
  $("btn-share").classList.toggle("hidden", active);   // 分享页：结束后可生成自包含 HTML
  $("btn-talk").classList.toggle("hidden", !(run.task_id && !chatEngineIsDirect(run)));
  const rcTask = [...((S.state || {}).tasks || []), ...((S.state || {}).archived_tasks || [])].find((x) => x.id === run.task_id);
  const rcLatestTask = latestSerialBatch(rcTask);
  const rcEarlyPlan = (rcLatestTask && rcLatestTask.serial && rcLatestTask.serial.early_finish)
    || (rcTask && rcTask.serial && rcTask.serial.early_finish) || null;
  const runPlannedEnd = Number(rcEarlyPlan && rcEarlyPlan.target_chapter || 0);
  const rcLatestSummary = rcLatestTask
    && (((S.state || {}).task_latest || {})[rcLatestTask.id]) || {};
  const rcLatestEnd = Number(rcLatestSummary.verdict
    && rcLatestSummary.verdict.end_chapter || 0);
  const runReachedPlannedEnd = runPlannedEnd > 0 && rcLatestEnd >= runPlannedEnd;
  const runEarlyFinishComplete = !!(runPlannedEnd > 0
    && rcLatestSummary.status === "done" && rcLatestSummary.verdict
    && rcLatestSummary.verdict.publishable === true
    && rcLatestEnd >= runPlannedEnd);
  if (rcTask) {
    renderProjectMemoryControls(rcTask.id);
  } else {
    const memoryBox = $("rd-project-memory");
    if (memoryBox) memoryBox.classList.add("hidden");
  }
  renderCheckpointControls(run.id, !!rcTask);
  refreshCheckpointRestoreAvailability(run);
  if (rcTask && S._checkpointRun !== run.id) {
    S._checkpointRun = run.id;
    loadRunCheckpoints(run.id);
  }
  // 签名守卫（模型页/检查器同款）：数据没变不重绘。详情区是全页最重的
  // 渲染面，此前 SSE 推送+轮询每 8s 无差别整块重写，是「页面一闪一闪、
  // 发布表单填一半被清空」的总根源（2026-09-30 用户实案）。运行中 ETA
  // 随墙钟走，签名带 1 分钟桶让「预计剩余」每分钟翻新，不必跟轮询同频。
  const etaBucket = (run.status === "running" || run.status === "queued")
    ? Math.floor(Date.now() / 60000) : 0;
  const rdSig = JSON.stringify([run, rcTask || null, rcLatestTask || null,
    rcLatestSummary || null, etaBucket]);
  if (rdSig === S.runDetailSig) return;
  S.runDetailSig = rdSig;
  // 归档按钮：非运行中任务可归档/取消归档（此前只有侧栏右键菜单入口，
  // 用户反馈「归档按钮不见了」——补显式入口，文案随状态切换）
  syncArchBtn(rcTask, active);
  setSelectionSerialButton(rcTask);
  setRetryBtn(run, rcTask);
  $("btn-continue").classList.toggle("hidden",
    !(rcTask && rcLatestTask && rcTask.serial
      && run.status !== "running" && run.status !== "queued"
      && !runReachedPlannedEnd && !runEarlyFinishComplete));
  $("btn-early-finish").classList.toggle("hidden",
    !(rcTask && rcLatestTask && rcTask.id === rcLatestTask.id && rcTask.serial && !rcEarlyPlan
      && run.status !== "running" && run.status !== "queued"));
  $("btn-early-finish-edit").classList.toggle("hidden",
    !(rcTask && rcEarlyPlan && !runEarlyFinishComplete
      && rcLatestTask.status !== "running" && rcLatestTask.status !== "queued"));
  $("btn-early-finish-cancel").classList.toggle("hidden",
    !(rcTask && rcEarlyPlan && !runEarlyFinishComplete
      && rcLatestTask.status !== "running" && rcLatestTask.status !== "queued"));
  setEditRetry(run.task_id, run.status, !!rcTask);
  S.lastRun = run;
  syncBrowserSplitTask(run.task_id);
  renderRunOutcome(run);
  renderDetailOverview(run, [run], rcTask);
  const bp = $("btn-pause");
  if (bp) { bp.classList.toggle("hidden", !active);
    bp.textContent = run.paused ? t("继续执行") : t("暂停"); }
  renderDirector(run, active);
  renderHive(run);
  renderChat(run, active);
  $("rd-meta").innerHTML =
    '<span class="stat">' + t("创建 ") + '<b>' + esc(run.created_at) + "</b></span>" +
    '<span class="stat">' + t("成本 ") + '<b>$' + Number(run.cost_usd || 0).toFixed(3) + "</b></span>" +
    '<span class="stat">tokens <b>' + (run.tokens || 0) + "</b></span>" +
    (run.mode ? '<span class="stat">' + t("模式 ") + '<b>' + ({auto: t("自动"), fast: t("快速"), expert: t("专家"), manual: t("手动")}[run.mode] || esc(run.mode)) + "</b></span>" : "") +
    (runEtaText(run) ? '<span class="stat eta">' + esc(runEtaText(run)) + "</span>" : "") +
    (run.error ? '<span class="stat err">' + errTag(run.error) + esc(run.error.slice(0, 200)) + "</span>" : "") +
    '<span class="stat tasksum hidden" id="rd-meta-task"></span>';
  if (S.detailSide) fillMetaTask(S.detailSide.stats || {});   // 缓存命中：轮询重画不闪丢累计组
  renderTimeoutRow(rcTask, run);
  renderPlan(run);
  renderRouting(run);
  renderChapterScores(run);
  // 首帧只输出一小批步骤，剩余内容交给浏览器下一帧，避免大运行记录堵住交互。
  renderRunDetailSteps(run, token);
  applyStepFocus();
  const heavy = rdEnsureHeavyState(id);
  if (heavy.status !== run.status) {
    heavy.status = run.status;
    heavy.report = false;
    heavy.artifacts = false;
    heavy.preview = false;
  }
  const reportHint = run.status === "done" || run.report
    ? t("点击“成果”页签后加载报告和成品文件")
    : ({ running: t("本次运行进行中：报告结束后在这里生成，实时进度看「步骤」页签"), queued: t("本次运行排队中：实时进度看「步骤」页签") }[run.status] || t("本次运行没有生成报告"));
  $("rd-report").innerHTML = '<div class="hint">' + esc(reportHint) + "</div>";
  // 预览只在首屏空闲时探测，报告及其 Markdown 解析仍等用户打开「成果」。
  rdScheduleNonCritical(() => {
    if (!rdCurrent(id, token)) return;
    const currentHeavy = rdEnsureHeavyState(id);
    if (!currentHeavy.preview) { currentHeavy.preview = true; renderPreview(id); }
  });
  // 成品文件双入口同源：主栏「成果」分区 + 检查器成品 TAB（列表上下文），
  // 详情上下文检查器让位后主栏是唯一可见面
  S.lastRunTask = rcTask || null;
  rdTabsSync({
    running: active, status: run.status, gitState: (rcTask || {}).git_state || "",
    steps: (run.steps || []).length,
    runningCount: (run.steps || []).filter((x) => x.status === "running").length,
    hasResult: run.status === "done" || !!run.report,
  });
  // 自动选中的页签也先让首帧交互完成；用户主动点击页签时，点击处理器
  // 会直接调用 rdEnsureActiveTabData，不会让这次延迟影响明确操作。
  rdScheduleNonCritical(rdEnsureActiveTabData);
  rdScheduleNonCritical(() => {
    if (!rdCurrent(id, token)) return;
    renderGitPanel(run, rcTask);
    renderBiblePanel(rcTask);
    renderBookMetaPanel(rcTask);
    refreshDetailSide();
    rdTabsSync();
  });
}

/* 代码版本隔离面板：run 检出任务分支 codebee/<id> 后，产物提交在该分支上、
 * 用户工作区已切回原分支。分支是「每任务一条」，裁决（合并/丢弃）在任务级生效。
 * 数据源两路：任务级 side（详情页自拉，运行中实时 numstat、结束后最新 run 快照，
 * 续跑/重试的新 run 没带 git 字段也能从任务带出分支）优先；side 不可用
 * （无主运行/任务已删）退回本 run 自带快照。两路都没有分支时整块隐藏。 */
const GIT_STATUS_LABEL = { M: t("改"), A: t("新"), D: t("删"), R: t("移"), C: t("新"), "?": t("新") };
/* 状态徽章文案：新数据后端已归一成单字符；旧 run 快照里可能还存着 "??"/"MM"
 * 这类原始 XY，取首字符兜底查表，查不到再退原文，绝不把 "??" 当文案渲染。 */
function gitStatusLabel(s) {
  const c = String(s == null ? "" : s);
  const key = GIT_STATUS_LABEL[c] != null ? c : c[0];
  return t(GIT_STATUS_LABEL[key] || key) || key;
}
const GIT_STATE_CHIP = {
  isolated: ["isolated", t("待裁决")],
  merged: ["merged", t("已合并")],
  discarded: ["discarded", t("已丢弃")],
};

/* 故事圣经面板：查看/编辑工作目录里的 story-bible.md（每章起草与评审
 * 自动注入的「本书宪法」）。运行中锁定编辑——圣经是提示词前缀的一部分，
 * 运行中改动会打碎供应商前缀缓存，也让本轮各章看到的设定不一致。
 * 只对连载任务渲染：注入点全在连载引擎，非连载任务配了也不生效，
 * 代码类任务更不该看到小说面板。 */
async function renderBiblePanel(task) {
  const box = $("rd-bible");
  if (!box || !(task || {}).id) { if (box) box.classList.add("hidden"); rdTabsSync(); return; }
  if (!task.serial) { box.classList.add("hidden"); rdTabsSync(); return; }
  // 拉取期间可能切详情：过期响应不落盘（把 A 任务的圣经写进 B 详情的串台面）
  const detailKey = S.detailTaskKey || S.detailRunId || "";
  let d;
  try { d = await api("/api/tasks/" + encodeURIComponent(task.id) + "/bible"); }
  catch (e) { box.classList.add("hidden"); rdTabsSync(); return; }
  if ((S.detailTaskKey || S.detailRunId || "") !== detailKey ||
      ((S.lastRunTask || {}).id || "") !== (task.id || "")) {
    box.classList.add("hidden"); rdTabsSync(); return;
  }
  const running = task.status === "running" || task.status === "queued";
  const text = d.text || "";
  const editing = S._bibleEdit === task.id;
  let html = '<div class="bible-head"><svg class="ico" aria-hidden="true"><use href="#i-book"/></svg>' +
    '<span class="sec-title">' + t("故事圣经") + '</span>' +
    '<span class="hint">' + esc(t("story-bible.md · 人物/世界观/伏笔台账，每章起草与评审自动注入")) + "</span>" +
    '<span class="flex1"></span>';
  if (editing) {
    html += '<button class="primary" onclick="bibleSave(\'' + jsq(task.id) + '\')">' + t("保存") + "</button>" +
      '<button class="ghost" onclick="bibleCancel()">' + t("取消") + "</button>";
  } else {
    html += '<button class="ghost" onclick="bibleEdit(\'' + jsq(task.id) + '\')"' +
      (running ? ' disabled title="' + esc(t("运行中不能修改")) + '"' : "") + ">" +
      '<svg class="ico" aria-hidden="true"><use href="#i-gear"/></svg>' + t("编辑") + "</button>";
  }
  html += "</div>";
  if (editing) {
    html += '<textarea id="bible-editor" class="bible-editor" rows="12" spellcheck="false">' +
      esc(text) + "</textarea>";
  } else if (text) {
    const head = text.split(/\n/).slice(0, 14).join("\n");
    const more = text.split(/\n/).length > 14;
    html += '<pre class="bible-view">' + esc(head) + (more ? "\n…" : "") + "</pre>";
  } else {
    html += '<div class="hint">' + esc(t("尚未创建。点「编辑」写下人物卡/世界观/伏笔台账，下一轮起草即刻生效。")) + "</div>";
  }
  box.classList.remove("hidden");
  box.innerHTML = html;
  rdTabsSync();   // 圣经面板显隐决定「圣经」标签可用性
}

window.bibleEdit = function (taskId) { S._bibleEdit = taskId; renderBiblePanel(S.lastRunTask || findTask(taskId)); };
window.bibleCancel = function () { S._bibleEdit = null; renderBiblePanel(S.lastRunTask || findTask(S._bibleKey || "")); };
window.bibleSave = async function (taskId) {
  const ta = $("bible-editor");
  if (!ta) return;
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/bible", {
      method: "POST", body: JSON.stringify({ text: ta.value }) });
    S._bibleEdit = null;
    toast(t("故事圣经已保存"));
    renderBiblePanel(S.lastRunTask || findTask(taskId));
  } catch (e) { toast(t("保存失败：") + e.message, true); }
};

function findTask(taskId) {
  return ((S.state || {}).tasks || []).find((x) => x.id === taskId);
}

/* ---------------- 作品信息一键生成（番茄/七猫建书表单资料） ----------------
 * 独立 TAB（仅连载任务）：用户手动点按钮触发生成（不自动调模型），后台线程跑，
 * 状态随任务 JSON（SSE 全量状态）自动刷进来。生成完字段直接内联在平台卡片里，
 * 每个字段带复制按钮——用户的目的就是往番茄/七猫建书表单里逐格粘贴。 */
const BOOKMETA_PLATFORMS = [
  { id: "fanqie", label: "番茄" },
  { id: "qimao", label: t("七猫") },
];
const BOOKMETA_FIELDS = {
  fanqie: [["book_name", t("作品名")], ["signing_mode", t("签约模式")], ["target_reader", t("目标读者")],
    ["category", t("主分类")], ["tags_theme", t("主题标签")], ["tags_role", t("角色标签")],
    ["tags_plot", t("情节标签")], ["content_plot", t("内容·情节")], ["content_emotion", t("内容·情感")],
    ["content_character", t("内容·人设")], ["content_world", t("内容·世界观")],
    ["protagonist_1", t("主角名1")], ["protagonist_2", t("主角名2")], ["summary", t("作品简介")]],
  qimao: [["book_name", t("作品名称")], ["target_reader", t("目标读者")], ["category_main", t("一级分类")],
    ["category_sub", t("二级分类")], ["tags_style", t("风格标签")], ["tags_role", t("角色标签")],
    ["tags_plot", t("情节标签")], ["tags_bg", t("背景标签")], ["protagonist_1", t("主角名1")],
    ["protagonist_2", t("主角名2")], ["status", t("作品状态")], ["summary", t("作品简介")]],
};

function bmFieldValue(v) {
  if (Array.isArray(v)) return v.length ? v.join("、") : t("（待补充）");
  const s = String(v == null ? "" : v).trim();
  return s || t("（待补充）");
}

function bmStatusChip(st) {
  const map = { done: ["ok", t("已生成")], running: ["run", "生成中"], failed: ["bad", t("生成失败")] };
  const m = map[st];
  return m ? '<span class="bm-st ' + m[0] + '">' + (m[1] === "生成中" ? "● " : "") + t(m[1]) + "</span>" : "";
}

/* 作品信息 TAB：所有连载任务都展示（一本书一份开书资料，都是用第一个）。
 * 续写批次（serial.continues 指向首批）只读沿用根任务的资料，生成/重生成回
 * 首批任务做——面板上给指路入口。serial_novel 类型但未配连载批次（如只建书
 * 投稿的任务，2026-10-21 实案）同样展示，否则任务详情里找不到作品信息页签。 */
function bmNeedsPanel(task) {
  const t = task || {};
  // short_story（2026-10-23）：短篇发布/存草稿入口也挂在这块面板
  return !!(t.serial || t.type === "serial_novel" || t.type === "short_story");
}

/* 连载链根任务：沿 serial.continues 上溯（环/断链停在当前）。状态里找不到
 * 父任务（已删除等）返回当前任务，面板退化为自身数据。 */
function bmRootTask(task) {
  let cur = task || null;
  const seen = {};
  while (cur && ((cur.serial || {}).continues) && !seen[cur.id]) {
    seen[cur.id] = 1;
    const parent = (((S.state || {}).tasks || [])
      .find((x) => x.id === cur.serial.continues)) || null;
    if (!parent) break;
    cur = parent;
  }
  return cur || task;
}

function renderBookMetaPanel(task) {
  const box = $("rd-bookmeta");
  if (!box || !(task || {}).id || !bmNeedsPanel(task)) {
    if (box) box.classList.add("hidden");
    return;
  }
  // 输入/展开态保护（检查器 insp-msg-input 同款纪律）：面板里有输入焦点
  //（正在填登记表单）或章节清单正展开时跳过本帧整块重绘——innerHTML
  // 重建会把没提交的字清掉、把展开列表折回去。轮询链继续转，blur/收起
  // 后下一轮数据变化自然跟上；登记草稿另有 S.pbRegDraft 兜底回填。
  // 守卫只保护同一任务（box.dataset.taskId）：切到别的任务的详情时，
  // 上一任务的展开态没有保留价值，放行重绘——否则新任务详情的作品信息
  // 页签一直挂着上一本书的建书/发布数据（2026-09-30 用户实案）。
  const ae = document.activeElement;
  if (box.dataset.taskId === task.id &&
      ((ae && box.contains(ae) &&
        (ae.tagName === "INPUT" || ae.tagName === "TEXTAREA" || ae.isContentEditable)) ||
       box.querySelector(".pb-chapters:not(.hidden)"))) {
    pbSyncState(task);
    return;
  }
  const src = bmRootTask(task);          // 都是用第一个：开书资料读链上根任务
  const inherited = src.id !== task.id;
  const bm = src.book_meta || {};
  const taskBusy = task.status === "running" || task.status === "queued";
  let html = '<div class="bm-head"><svg class="ico" aria-hidden="true"><use href="#i-idcard"/></svg>' +
    '<span class="sec-title">' + t("作品信息") + "</span>" +
    (inherited ? '<span class="bm-inherit" title="' + esc(src.title || src.id) + '">' +
      esc(t("继承自首批") + "《" + (src.title || src.id) + "》") + "</span>" : "") +
    '<span class="hint">' + esc(t("按发布平台生成建书表单资料，逐字段复制过去")) + "</span>" +
    '<button class="hhelp" data-help-topic="publish" title="' + esc(t("这是什么？点开看帮助")) + '" aria-label="' + esc(t("帮助")) + '"><svg class="ico" aria-hidden="true"><use href="#i-help"></use></svg></button>' +
    '<span class="flex1"></span>';
  if (taskBusy) html += '<span class="bm-warn">' + esc(t("任务运行中，生成将在本轮结束后可用")) + "</span>";
  html += "</div>";
  if (!bm.fanqie && !bm.qimao && !taskBusy) {
    // 生成入口不再区分首批/续写（2026-09-30 放开；后端落点统一在链上根任务），指引文案只留一份
    html += '<div class="bm-guide"><svg class="ico" aria-hidden="true"><use href="#i-idcard"/></svg>' +
      '<div><b>' + esc(t("章节已就绪，创建作品还差开书资料")) + "</b>" +
      "<p>" + esc(t("点平台卡片上的「生成」按钮，一键产出书名/简介/标签/主角名等建书资料，生成后逐字段复制进建书表单。")) + "</p></div></div>";
  }
  html += '<div class="bm-cards">' + BOOKMETA_PLATFORMS.map((p) => {
    const entry = bm[p.id] || {};
    const st = entry.status || "";
    let body = "";
    if (st === "running") {
      body = '<div class="bm-skwrap">' + BOOKMETA_FIELDS[p.id].map(() =>
        '<div class="bm-sk"><span class="bm-sk-l"></span><span class="bm-sk-v"></span></div>').join("") + "</div>";
    } else if (st === "done" && entry.data) {
      body = '<div class="bm-fields">' + (BOOKMETA_FIELDS[p.id] || []).map(([key, label]) => {
        const raw = entry.data[key];
        const long = key === "summary";
        const tags = Array.isArray(raw) && raw.length;
        const val = bmFieldValue(raw);
        // 标签类字段渲染成 chips（复制仍复制顿号串），长字段独占整行
        const v = tags
          ? '<span class="bm-chips">' + raw.map((x) => '<span class="bm-chip">' + esc(String(x)) + "</span>").join("") + "</span>"
          : '<span class="bm-f-v' + (long ? " bm-f--scroll" : "") + '" title="' + esc(val) + '">' + esc(val) + "</span>";
        // 书名行加「换名」（2026-10-02 撞名实案）：只换书名一个字段，其余
        // 已核对过的分类/标签/简介不被重摇覆盖；换名中禁用态由 S.bmRenaming
        // 跨重绘保持（轮询整块 innerHTML 重建会把按钮态复位）
        let rename = "";
        if (key === "book_name") {
          const renaming = S.bmRenaming === task.id + "|" + p.id;
          rename = '<button class="bm-rename" data-task="' + esc(task.id) +
            '" data-plat="' + p.id + '" data-old="' + esc(val) + '"' + (renaming ? " disabled" : "") +
            ' title="' + esc(t("书名与本站已有作品重名时，点这里换一个新书名（其余字段不动）")) + '"' +
            ' onclick="bmRename(this)">' +
            (renaming
              ? '<svg class="ico spin" aria-hidden="true"><use href="#i-refresh"/></svg>' + esc(t("换名中…"))
              : '<svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg>' + esc(t("换名"))) +
            "</button>";
        }
        return '<div class="bm-f' + (long || tags ? " bm-f--full" : "") + '">' +
          '<span class="bm-f-k">' + esc(t(label)) + "</span>" + v +
          '<button class="bm-copy" data-text="' + esc(val) + '" data-label="' + esc(t(label)) +
          '" title="' + esc(t("点击复制")) + '" onclick="bmCopyBtn(this)"><svg class="ico" aria-hidden="true"><use href="#i-file-text"/></svg>' + t("复制") + "</button>" +
          rename + "</div>";
      }).join("") + "</div>";
    } else if (st === "failed") {
      body = '<div class="bm-errhint">' + esc(entry.error || t("生成失败")) + "</div>";
    } else {
      body = '<div class="bm-empty">' + esc(t("尚未生成")) + "</div>";
    }
    let action;
    if (st === "running") {
      action = '<button class="ghost" disabled><svg class="ico spin" aria-hidden="true"><use href="#i-refresh"/></svg>' + t("生成中…") + "</button>";
    } else if (st === "done") {
      action = '<button class="ghost" onclick="bmGen(\'' + jsq(task.id) + "', '" + p.id + '\')" title="' + esc(t("重新生成会覆盖现有内容")) + '">' +
        '<svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg>' + t("重新生成") + "</button>";
    } else {
      action = '<button class="primary" onclick="bmGen(\'' + jsq(task.id) + "', '" + p.id + '\')">' +
        (st === "failed" ? t("重试") : t("生成")) + "</button>";
    }
    // 头部行：平台名 + 状态徽章 + 右侧操作按钮（action 必须在 head 内闭合，
    // 否则头部 div 吞掉后面的字段区，卡片会嵌套叠在一起）
    const head = '<div class="bm-card-head">' +
      '<span class="bm-plat-name"><svg class="ico" aria-hidden="true"><use href="#i-library"/></svg>' + esc(t(p.label)) + "</span>" +
      bmStatusChip(st) + '<span class="flex1"></span>' + action + "</div>";
    return '<div class="bm-card st-' + esc(st || "new") + '">' + head + body +
      (entry.source && st === "done" ? '<div class="bm-src">' + esc(t("来源：") + entry.source) + "</div>" : "") +
      pbBlock(task, p.id) +
      "</div>";
  }).join("") + "</div>";
  // 封面卡（covergen，借鉴 oh-story 封面图环节）：curl 落盘运行目录，
  // done 后卡片内直接嵌缩略图（/api/runs/<id>/cover 专用通道），点开新页看大图。
  // 封面也是「这本书」的：本任务没生成过就沿用根任务的封面；点生成则落本任务自己的
  const cgSrc = (task.cover_gen && (task.cover_gen.status || task.cover_gen.run_id)) ? task : src;
  const cg = cgSrc.cover_gen || {};
  const cgInherited = cgSrc !== task;
  const cgSt = cg.status || "";
  let cgBody = "";
  if (cgSt === "running") {
    cgBody = '<div class="bm-empty"><svg class="ico spin" aria-hidden="true"><use href="#i-refresh"/></svg> ' + esc(t("生成中…")) + "</div>";
  } else if (cgSt === "done" && cg.run_id) {
    const covUrl = "/api/runs/" + encodeURIComponent(cg.run_id) + "/cover" +
      (cg.at ? "?ts=" + encodeURIComponent(cg.at) : "");   // at 当缓存戳，重生成后缩略图跟着换
    cgBody = '<div class="bm-cover-wrap">' +
      '<a href="' + esc(urlAuth(covUrl)) + '" target="_blank" rel="noopener" title="' + esc(t("点击查看大图")) + '">' +
      '<img class="bm-cover-img" src="' + esc(urlAuth(covUrl)) + '" alt="cover.png" ' +
      'onerror="this.closest(&quot;.bm-cover-wrap&quot;).classList.add(&quot;noimg&quot;)"></a>' +
      '<span class="bm-cover-fallback">' + esc(t("cover.png 已不在运行目录")) + "</span>" +
      '<div class="bm-cover-meta">' + esc([cg.model, cg.provider, cg.size,
        cgInherited ? t("继承自首批") : ""].filter(Boolean).join(" · ")) + "</div></div>";
  } else if (cgSt === "done") {
    cgBody = '<div class="bm-empty">' + esc(t("封面已生成，但缺少运行记录归属")) + "</div>";
  } else if (cgSt === "failed") {
    cgBody = '<div class="bm-errhint">' + esc(cg.error || t("生成失败")) + "</div>";
  } else {
    cgBody = '<div class="bm-empty">' + esc(t("生成竖版封面插画，产出 cover.png")) + "</div>";
  }
  const cgBusy = taskBusy || cgSt === "running";
  // 生成前提示词预览确认（drama-skills 借鉴③「先预览确认再生产」）：点
  // 「生成封面」先只读拉提示词展示，确认后才走 coverGen 的 POST 付费链；
  // S.coverPrompt 让预览态跨轮询重绘保持（同 bmRenaming 模式）
  // 排除 running（生成中不出确认钮）与 done（已出图预览无意义，挂回 done 卡误导）
  const cgPrev = (S.coverPrompt && S.coverPrompt.taskId === task.id
                  && cgSt !== "running" && cgSt !== "done") ? S.coverPrompt : null;
  const cgAction = cgSt === "running"
    ? '<button class="ghost" disabled><svg class="ico spin" aria-hidden="true"><use href="#i-refresh"/></svg>' + t("生成中…") + "</button>"
    : cgPrev
      ? '<button class="primary" onclick="coverConfirm(\'' + jsq(task.id) + '\')">' + t("确认生成") + "</button>" +
        '<button class="ghost" onclick="coverCancel(\'' + jsq(task.id) + '\')">' + t("取消") + "</button>"
      : '<button class="primary" onclick="coverPreview(\'' + jsq(task.id) + '\')">' +
        (cgSt === "failed" ? t("重试") : t("生成封面")) + "</button>";
  if (cgPrev) {
    cgBody += '<div class="bm-cover-preview"><div class="bm-cover-preview-hint">' +
      esc(t("生成前请确认图像提示词（确认后才调用图像接口）：")) + "</div>" +
      '<div class="bm-cover-preview-text">' + esc(cgPrev.prompt || "") + "</div></div>";
  }
  html += '<div class="bm-cards"><div class="bm-card st-' + (cgSt || "new") + '">' +
    '<div class="bm-card-head"><span class="bm-plat-name"><svg class="ico" aria-hidden="true"><use href="#i-book-open"/></svg>' + esc(t("封面图")) + "</span>" +
    bmStatusChip(cgSt) + '<span class="flex1"></span>' + cgAction + "</div>" + cgBody + "</div></div>";
  box.classList.remove("hidden");
  box.innerHTML = html;
  box.dataset.taskId = task.id;   // 跨任务守卫标记：展开态/输入保护只对同一任务生效
  pbRefreshSelectionDialog(task);
  // TAB 徽章：已生成平台数（生成中显示 ●，随下次轮询刷新）
  const badge = document.querySelector('#rd-tabs .rd-tab[data-tab="bookmeta"] .rd-badge');
  if (badge) {
    const n = BOOKMETA_PLATFORMS.filter((p) => (bm[p.id] || {}).status === "done").length;
    const anyRun = BOOKMETA_PLATFORMS.some((p) => (bm[p.id] || {}).status === "running");
    badge.textContent = anyRun ? "●" : (n ? n + "/" + BOOKMETA_PLATFORMS.length : "");
    badge.className = "rd-badge" + (badge.textContent ? (anyRun ? " live" : "") : " hidden");
  }
  pbSyncState(task);   // 发布状态独立于 SSE（/api/publish），节流拉取+变化重渲染
}

window.bmGen = async function (taskId, platform) {
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/book-meta",
      { method: "POST", body: JSON.stringify({ platform }) });
    toast(t("已开始生成，完成后这里会自动更新"));
    await refreshState(); render();   // 立即翻到「生成中」，不等 SSE 推送/下一轮轮询
  } catch (e) { toast(t("生成失败：") + e.message, true); }
};

/* 换名（书名撞名专用）：同步接口单次轻模型调用，成功后新书名随 SSE/轮询
 * 回填；失败 toast 报错，现有字段原样保留。期间 S.bmRenaming 让按钮禁用态
 * 跨轮询重绘保持，防连点打两个换名请求。 */
window.bmRename = async function (btn) {
  if (btn.disabled) return;
  // 立即禁用+换文案（防 await 期间双击发第二个请求）；S.bmRenaming 让禁用态
  // 跨轮询重绘保持（轮询整块 innerHTML 重建会把按钮态复位，渲染端按它还原）
  btn.disabled = true;
  btn.innerHTML = '<svg class="ico spin" aria-hidden="true"><use href="#i-refresh"/></svg>' + esc(t("换名中…"));
  const taskId = btn.dataset.task, platform = btn.dataset.plat;
  S.bmRenaming = taskId + "|" + platform;
  try {
    const r = await api("/api/tasks/" + encodeURIComponent(taskId) + "/book-meta/rename",
      { method: "POST", body: JSON.stringify({ platform }) });
    toast(t("已换名：") + "《" + (r.old || btn.dataset.old || "") + "》→《" + (r.new || "") + "》");
  } catch (e) {
    toast(t("换名失败：") + e.message, true);
  } finally {
    S.bmRenaming = "";
    // 就地恢复按钮：render 的详情签名守卫在服务端数据没变时（换名失败正是）
    // 会跳过重绘，按钮不能指望 render 归位；若 render 真重建了整卡，btn 已
    // detach，改它是无害空操作
    btn.disabled = false;
    btn.innerHTML = '<svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg>' + esc(t("换名"));
    try { await refreshState(); render(); } catch (e) { /* 拉状态失败不影响上面的恢复 */ }
  }
};

/* 封面图生成（covergen）：curl 子进程直接落盘运行目录，Python 不经手图像字节 */
window.coverGen = async function (taskId) {
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/cover",
      { method: "POST", body: "{}" });
    toast(t("已开始生成封面，完成后这里会自动更新"));
    await refreshState(); render();
  } catch (e) { toast(t("封面生成失败：") + e.message, true); }
};

/* 生成前提示词预览（drama-skills 借鉴③「先预览确认再生产」）：只读拉取
 * 后端 _cover_prompt 结果展示，不发图像请求；「确认生成」才走既有 coverGen
 * 的 POST /cover 付费链，「取消」只清预览态重绘、零请求。
 * 三个处理器都作废详情签名再 render：S.coverPrompt 不在 drawTaskDetail/
 * renderRunDetail 的数据签名里，服务端数据没变时守卫会整帧跳过重绘
 * （bmRename 同陷阱，见其 :5877 注释）——不作废则预览框不上屏、取消后残留。 */
function coverInvalidateDetail() {
  S.taskSig = "";
  S.runDetailSig = "";
  render();
}
window.coverPreview = async function (taskId) {
  try {
    const r = await api("/api/tasks/" + encodeURIComponent(taskId) + "/cover/prompt");
    S.coverPrompt = { taskId: taskId, prompt: r.prompt || "" };
    coverInvalidateDetail();
  } catch (e) { toast(t("封面提示词获取失败：") + e.message, true); }
};
window.coverConfirm = function (taskId) {
  S.coverPrompt = null;
  coverInvalidateDetail();   // 先归位成单按钮再发 POST，失败时界面不留旧预览框
  window.coverGen(taskId);
};
window.coverCancel = function (taskId) {
  if (S.coverPrompt && S.coverPrompt.taskId === taskId) S.coverPrompt = null;
  coverInvalidateDetail();
};

window.bmCopyBtn = function (btn) {
  // 只在真实复制成功后报「已复制」——剪贴板不可用时 fallbackCopy 会弹失败提示
  copyText(btn.dataset.text || "", () => toast(t("已复制：") + (btn.dataset.label || "")));
};

/* ---------------- 一键发布（bookmeta 分区内每平台卡的发布行） ----------------
 * 状态独立于 SSE（/api/publish 轮询，5s 节流；waiting_login/busy 靠主轮询周期
 * 自然刷新）。正常建书、单章和批量发布请求统一走 auto_submit=true，由服务端
 * 处理平台弹层、提交和回执校验；草稿模式仍明确不上线。 */
const PB_ST = {
  none: [t("未连接"), "pb-st-none"], waiting_login: [t("等登录/验证…"), "pb-st-wait"],
  connected: [t("已连接"), "pb-st-ok"], busy: [t("操作中…"), "pb-st-busy"],
  error: [t("出错"), "pb-st-err"],
};

function pbBlock(task, platform, selectionOnly = false) {
  const ps = (S.pubState && S.pubState.platforms && S.pubState.platforms[platform]) || {};
  const st = ps.status || "none";
  const books = (S.pubTaskInfo && S.pubTaskInfo.books) || {};
  const book = books[platform];
  // A create-book flow can finish without a remote id. Keep that binding
  // retryable instead of presenting it as a ready-to-publish book.
  const bookReady = !!(book && (book.book_id || book.source === "manual"));
  // A named book binding uses its own browser profile. The platform-level
  // status describes the default profile and can otherwise report "connected"
  // while the actual publishing account is offline.
  const boundAccount = String((book && book.account) || "").trim();
  const boundAccountState = boundAccount
    ? (ps.accounts || []).find((a) => String(a.id || "") === boundAccount)
    : null;
  const displayStatus = boundAccount
    ? ((boundAccountState && boundAccountState.status) || "none") : st;
  const [label, cls] = PB_ST[displayStatus] || PB_ST.none;
  const hist = (S.pubTaskInfo && S.pubTaskInfo.history) || [];
  const pubCnt = (S.pubTaskInfo && S.pubTaskInfo.published) || {};
  // 已发口径：平台实况（点过校准）优先；否则本地台账去重章号数
  //（直接数记录会因重试虚高，见 2026-09-28 校准案）
  const localN = (typeof pubCnt[platform] === "number") ? pubCnt[platform]
    : new Set(hist.filter((r) => r.platform === platform && r.action === "upload_chapter"
        && r.ok && (r.chapter_no || 0) > 0).map((r) => r.chapter_no)).size;
  const hasRemote = book && (typeof book.remote_total === "number"
    || typeof book.remote_published === "number");
  const remoteN = hasRemote ? ((typeof book.remote_total === "number")
    ? book.remote_total : book.remote_published) : null;
  const nCh = hasRemote ? remoteN : localN;
  const publishedLatest = Math.max(Number(book && book.confirmed_published_through) || 0,
    ((book && book.remote_published_nos) || []).reduce((max, n) => Math.max(max, Number(n) || 0), 0));
  let chTitle = "";
  if (hasRemote) {
    const parts = [];
    parts.push(remoteN !== localN
      ? t("平台实况 ") + remoteN + t(" 章，本地台账 ") + localN + t(" 章，已按平台纠正")
      : t("已按平台实况校准：") + remoteN + t(" 章"));
    if (book.remote_published != null && book.remote_published !== remoteN)
      parts.push(t("其中已发布 ") + book.remote_published +
        (book.remote_review ? t("，审核中 ") + book.remote_review : ""));
    // 平台定时队列（2026-10-16）：手工提交的定时章只在平台实况里，
    // 不展示的话「已发73章」和发布台待发清单会对不上账
    if (book.remote_scheduled)
      parts.push(t("定时排期 ") + book.remote_scheduled + t(" 章") +
        (book.remote_last_schedule_at
          ? t("，排至 ") + book.remote_last_schedule_at : ""));
    if (book.remote_last_publish_at)
      parts.push(t("最后发布 ") + book.remote_last_publish_at);
    if (book.remote_synced_at) parts.push(t("校准于 ") + book.remote_synced_at);
    chTitle = parts.join(t("；"));
  } else {
    chTitle = t("本地台账口径，点「校准」按平台实况纠正");
  }
  const busy = displayStatus === "busy";
  const isShort = String(task.type || "").toLowerCase() === "short_story";
  let btns = "";
  let pendHtml = "";   // 批量选择 chips（bookReady 分支里填充，extra 段落拼接）
  if (displayStatus === "none" || displayStatus === "error" || displayStatus === "waiting_login") {
    if (boundAccount) {
      btns += '<button class="ghost" onclick="pbConnectAcc(\'' + platform + '\',\'' + jsq(boundAccount) + '\')">' +
        (displayStatus === "error" ? t("重连") : t("登录")) + "</button>";
    } else {
      btns += '<button class="ghost" onclick="pbConnect(\'' + platform + '\')">' +
        (displayStatus === "error" ? t("重连") : t("连接平台")) + "</button>";
    }
  } else if (displayStatus === "connected") {
    if (boundAccount) {
      btns += '<button class="ghost" onclick="pbDisconnectAcc(\'' + platform + '\',\'' + jsq(boundAccount) + '\')" title="' + esc(t("关掉该平台账号的浏览器窗口（登录态保留）")) + '">' + t("断开") + "</button>";
    } else {
      btns += '<button class="ghost" onclick="pbDisconnect(\'' + platform + '\')" title="' + esc(t("关掉该平台的浏览器窗口（登录态保留）")) + '">' + t("断开") + "</button>";
    }
  }
  btns += '<button class="ghost pb-tool" onclick="' + (boundAccount ? "pbProbeAcc('" + jsq(platform) + "','" + jsq(boundAccount) + "')" : "pbProbe('" + jsq(platform) + "')") + '" title="' +
    esc(t("dump 平台表单结构（校准自动填表用）")) + '">' + t("探测") + "</button>";
  // 多账号（2026-10-18）：每台账号独立浏览器/独立配额，chips 带各自登录/断开
  const accList = ps.accounts || [];
  if (accList.length) {
    btns += '<div class="pb-accounts">';
    for (const acc of accList) {
      const accSt = acc.status === "connected" ? t("已连接")
        : (acc.status === "busy" ? t("操作中") : (acc.status === "error" ? t("出错") : t("未连接")));
      btns += '<span class="pb-acc-chip" title="' + esc(t("独立浏览器账号：") + (acc.profile || "")) + '">' +
        esc(acc.id + "·" + accSt) +
        ' <button class="ghost pb-tool" onclick="pbConnectAcc(\'' + platform + '\',\'' + jsq(acc.id) + '\')">' + t("登录") + "</button>" +
        ' <button class="ghost pb-tool" onclick="pbDisconnectAcc(\'' + platform + '\',\'' + jsq(acc.id) + '\')">' + t("断开") + "</button></span>";
    }
    btns += "</div>";
  }
  btns += ' <button class="ghost pb-tool" onclick="pbAddAccount(\'' + platform + '\')" title="' +
    esc(t("新增一台独立浏览器账号（独立登录/独立建书配额），建书时可下拉选用")) + '">' + t("+账号") + "</button>";
  if (bookReady) {
    btns += '<span class="pb-book" title="' + esc(t("已在此平台创建的作品")) + '">' +
      esc(t("已建书：") + (book.title || "")) + "</span>";
    if (isShort) {
      // 短篇是单文档：整篇发布/存草稿，不出现任何按章 UI（发一章/批量
      // 清单对短篇都是误操作面）。凭据行读台账 publish_short_story 动作。
      const shortOk = hist.find((r) => r.platform === platform &&
        r.action === "publish_short_story" && r.ok);
      btns += ' <button class="primary" ' + (busy ? "disabled" : "") +
        ' onclick="pbShortStory(\'' + jsq(task.id) + "', '" + platform + '\', false)" title="' +
        esc(t("整篇自动填入并完成设置/封面/协议后提交发布，以平台管理页状态为凭据；发布后不可撤回")) + '">' +
        t("发布短篇") + (shortOk ? t("（已提交）") : "") + "</button>";
      btns += ' <button class="ghost pb-tool" ' + (busy ? "disabled" : "") +
        ' onclick="pbShortStory(\'' + jsq(task.id) + "', '" + platform + '\', true)" title="' +
        esc(t("整篇自动填入并点「存为草稿」：落平台草稿箱不上线，之后到平台检查并提交")) + '">' +
        t("存草稿") + "</button>";
      if (shortOk) {
        btns += '<div class="pb-hint">' +
          esc(t("短篇已提交发布（{0}）：状态以平台短故事管理页为准", shortOk.ts || "")) +
          "</div>";
      }
    } else {
    btns += ' <button class="primary" ' + (busy ? "disabled" : "") +
      ' onclick="pbUploadChapter(\'' + jsq(task.id) + "', '" + platform + '\')" title="' +
      esc(chTitle) + '">' +
      t("发一章") + (publishedLatest ? t("（已发布至 {0} 章）", publishedLatest)
        : nCh ? t("（已发 ") + nCh + t("）") : "") + "</button>";
    }
    btns += ' <button class="ghost pb-tool" ' + (busy ? "disabled" : "") +
      ' onclick="pbSyncPublished(\'' + jsq(task.id) + "', '" + platform + '\')" title="' +
      esc(t("按平台实况纠正已发章数")) + '">' + t("校准") + "</button>";
    // 改绑定/解除绑定（2026-10-16）：登记的书名/ID对不上或书已废时就地
    // 纠错/清位，不再只能手工翻 books.json（登记在连载链根任务上根本不好找）
    btns += ' <button class="ghost pb-tool" ' + (busy ? "disabled" : "") +
      ' onclick="pbRegToggle(\'' + jsq(task.id) + "','" + platform + '\')" title="' +
      esc(t("登记的书名或ID与平台对不上？在这里改成真实的作品名/ID，改完直接发章")) + '">' + t("改绑定") + "</button>";
    btns += ' <button class="ghost pb-tool" ' + (busy ? "disabled" : "") +
      ' onclick="pbUnbind(\'' + jsq(task.id) + "', '" + platform + '\')" title="' +
      esc(t("只清除本地的作品登记，不动平台上的作品；清掉后可重新创建作品或改绑其他书")) + '">' + t("解除绑定") + "</button>";
    // 批量发布（publish/auto.py）：待发清单 + 护栏 + 进度都来自 /pending 视图
    // 短篇没有章形态，整块按章 UI（批量/选择/进度）不渲染
    if (!isShort) {
    const au = (((S.pubAuto && S.pubAuto.books) || [])
      .find((b) => b.platform === platform)) || {};
    const run = (S.pubAuto && S.pubAuto.running &&
      S.pubAuto.running.platform === platform) ? S.pubAuto.running : null;
    const retry = (S.pubAuto && S.pubAuto.retry &&
      S.pubAuto.retry.platform === platform) ? S.pubAuto.retry : null;
    if (run && run.status === "running") {
      btns += '<span class="pb-book">' + esc((run.as_draft ? t("存草稿中 ") : t("自动发布中 ")) + run.done + "/" + run.total) + "</span>";
    }
    if (retry && retry.status === "retry_wait") {
      const retryAt = retry.next_retry_at
        ? new Date(retry.next_retry_at * 1000).toLocaleString() : t("稍后");
      btns += '<span class="pb-book" title="' + esc(retry.error || "") + '">' +
        esc(t("自动发布将在 {0} 重试", retryAt)) + "</span>";
    }
    if (au.quality_forced && Array.isArray(au.quality_warnings) &&
        au.quality_warnings.length) {
      btns += '<div class="pb-hint pb-quality-warning" title="' +
        esc(au.quality_warnings.join("；")) + '">' +
        esc(t("自动发布质量警告：") + au.quality_warnings.join("；")) + "</div>";
    }
    if (run && Array.isArray(run.notes) && run.notes.length) {
      // 对账剔除/跳过/重试的过程记录（auto 层 notes），最近三条
      btns += '<div class="pb-hint">' +
        esc(run.notes.slice(-3).join("；")) + "</div>";
    } else if (au.pending > 0) {
      // 门禁不再禁用按钮：点了走 pbApiWithQualityOverride 的复审/强制对话，
      // 死按钮只会让用户无路可走（2026-10-08 实案：guard false 全灰点不了）
      btns += ' <button class="ghost" ' + (busy ? "disabled" : "") +
      ' title="' + esc(au.guard_ok ? t("按章号顺序逐章自动提交；成功后自动对账并继续下一章") : t("护栏提示：") + (au.guard_reason || "")) + '"' +
        ' onclick="pbPublishAll(\'' + jsq(task.id) + "', '" + platform + '\')">' +
        t("发布全部待发") + t("（") + au.pending + t("）") + "</button>";
      // 全部发草稿（2026-10-09）：质量闸拦发布不拦草稿——逐章自动填稿点
      // 「存草稿」连跑到清空，提交发布由用户到平台草稿箱手工完成
      btns += ' <button class="ghost" ' + (busy || au.draft_ok === false ? "disabled" : "") +
        ' title="' + esc(au.draft_ok !== false ? t("逐章自动填稿并点「存草稿」：内容落平台草稿箱不上线，不受质量门禁拦截，无需逐章人工确认；完成后到平台检查并提交发布") : t("护栏提示：") + (au.draft_reason || "")) + '"' +
        ' onclick="pbDraftAll(\'' + jsq(task.id) + "', '" + platform + '\')">' +
        t("全部存草稿") + t("（") + au.pending + t("）") + "</button>";
    }
    // 批量选择：待发章号 chips 按卷分组（卷计划来自服务端 items[].volume），
    // 所选章节统一走逐章无人值守提交（护栏照常生效）。
    // 分卷由服务端按卷计划自动选/建（volumes.py），界面上不用管卷。
    const its = (au.items && au.items.length ? au.items : [])
      .map((x) => ({ n: Number(x.chapter_no), v: x.volume || "", review: x.review_status || "pending",
        reason: x.review_reason || "", ready: x.publish_ready === true }))
      .filter((x) => x.n > 0);
    if (its.length && !run) {
      const key = task.id + ":" + platform;
      const sig = its.map((x) => x.n).join(",");
      S.pbSel = S.pbSel || {};
      // 连续段按卷名分组；无卷计划的整块平铺不显示卷头
      const groups = [];
      for (const x of its) {
        const g = groups[groups.length - 1];
        if (g && g.v === x.v) g.ns.push(x.n);
        else groups.push({ v: x.v, ns: [x.n] });
      }
      if (!S.pbSel[key] || S.pbSel[key].sig !== sig)
        S.pbSel[key] = { sig, sel: new Set(its.map((x) => x.n)), groups };
      S.pbSel[key].groups = groups;
      S.pbSel[key].ready = new Set(its.filter((x) => x.ready).map((x) => x.n));
      const sel = S.pbSel[key].sel;
      let chips = "";
      for (let gi = 0; gi < groups.length; gi++) {
        const g = groups[gi];
        chips += '<section class="pb-pend-volume" data-volume="' + gi + '">';
        if (groups.length > 1 || g.v) {
          // 卷头＝整卷开关：全选打勾、部分选中显示 已选/总（2026-10-10 按卷选章）
          const cnt = g.ns.filter((n) => sel.has(n)).length;
          const allOn = cnt === g.ns.length;
          chips += '<div class="pb-vol"><label class="pb-vol-sel' + (allOn ? " on" : cnt ? " partial" : "") +
            '" title="' + esc(t("勾选卷头＝整卷进所选，再点取消")) + '">' +
            '<input type="checkbox" ' + (allOn ? "checked" : "") +
            ' onchange="pbSelVolume(\'' + jsq(task.id) + "','" + platform + "'," + gi + ',this.checked)">' +
            '<span class="pb-vol-name">' + esc(g.v || t("未分卷")) + '</span>' +
            '<span class="pb-vol-count">' + esc(t("已选 {0}/{1} 章", cnt, g.ns.length)) + "</span></label></div>";
        }
        chips += '<div class="pb-chapter-grid">';
        for (const n of g.ns) {
          const item = its.find((x) => x.n === n);
          const states = { ready: t("已过审 · 可直发"), passed_blocked: t("已过审 · 发布受限"),
            failed: t("审稿未通过"), stale: t("已修改 · 需重审"), pending: t("待审或评审不足") };
          const review = Object.hasOwn(states, item.review) ? item.review : "pending";
          chips += '<label class="pb-chip review-' + review + (sel.has(n) ? " on" : "") + '" data-chapter="' + n + '" title="' +
            esc(t("第 {0} 章", n) + (item.reason ? " · " + item.reason : "")) + '">' +
            '<input type="checkbox" ' + (sel.has(n) ? "checked" : "") +
            ' onchange="pbSelToggle(\'' + jsq(task.id) + "','" + platform + "'," + n + ',this.checked)">' +
            '<span class="pb-chip-number">' + n + '</span><small class="pb-chip-review">' + esc(t(states[review])) + "</small></label>";
        }
        chips += "</div></section>";
      }
      pendHtml += '<div class="pb-pend" data-key="' + esc(key) + '">' +
        '<div class="pb-pend-head">' +
        '<div class="pb-pend-heading"><strong>' + esc(t("待发 ")) + its.length + esc(t(" 章")) + '</strong>' +
        '<span>' + esc(t("按卷计划自动分卷")) + "</span></div>" +
        '<button class="ghost pb-ready-select" ' + (S.pbSel[key].ready.size ? "" : "disabled") +
        ' title="' + esc(t("仅选择单章审稿和发布门禁均已通过的章节")) + '" onclick="pbSelReady(\'' + jsq(task.id) + "','" + platform + '\')">' + esc(t("只选可直发")) + '</button>' +
        '<a href="javascript:void(0)" onclick="pbSelAll(\'' + jsq(task.id) + "','" + platform + "',true)" + '">' + esc(t("全选")) + "</a>" +
        '<a href="javascript:void(0)" onclick="pbSelAll(\'' + jsq(task.id) + "','" + platform + "',false)" + '">' + esc(t("清空")) + "</a>" +
        "</div>" +
        '<div class="pb-review-legend" aria-label="' + esc(t("章节审核状态说明")) + '">' +
        '<span class="review-ready"><i aria-hidden="true"></i>' + esc(t("已过审 · 可直发")) + '</span>' +
        '<span class="review-passed_blocked"><i aria-hidden="true"></i>' + esc(t("已过审 · 发布受限")) + '</span>' +
        '<span class="review-failed"><i aria-hidden="true"></i>' + esc(t("审稿未通过")) + '</span>' +
        '<span class="review-pending"><i aria-hidden="true"></i>' + esc(t("待审或评审不足")) + '</span>' +
        "</div>" +
        '<div class="pb-pend-progress">' +
        (au.published_latest ? '<strong>' + esc(t("已发布至第 {0} 章", au.published_latest)) + '</strong>' : '') +
        (au.scheduled ? '<span>' + esc(t("定时队列 {0} 章（尚未计入已发布）", au.scheduled) +
          (au.last_schedule_at ? t("，排至 {0}", au.last_schedule_at) : "")) + '</span>' : '') +
        (au.next_chapter ? '<span>' + esc(t("下一章：第 {0} 章", au.next_chapter)) + '</span>' : '') +
        '<span>' + esc(t("可直发 {0} 章 · 单章过审 {1} 章", au.ready_count || 0, au.review_passed_count || 0)) + '</span></div>' +
        '<div class="pb-pend-chips">' + chips + "</div>" +
        (au.drafted_nos && au.drafted_nos.length ? '<details class="pb-drafted-list"><summary>' +
          esc(t("已存草稿 {0} 章（未发布）", au.drafted_nos.length)) + '</summary><p>' +
          esc(au.drafted_nos.map((n) => t("第 {0} 章", n)).join(" · ")) + '</p></details>' : '') +
        '<div class="pb-pend-foot"><span class="pb-pend-count" aria-live="polite">' + esc(t("已选 {0}/{1} 章", sel.size, its.length)) + '</span>' +
        '<span class="pb-pend-mode-hint">' + esc(t("批量发布自动提交；失败会停止并保留现场，草稿不上线。")) + '</span>' +
        '<div class="pb-pend-btns">' +
        '<button class="ghost" data-selection-action data-locked="' + busy + '" ' + (busy || !sel.size ? "disabled" : "") +
        ' title="' + esc(t("所选章节逐章自动提交（无人值守），护栏每日上限/连败退避照常生效") +
          (au.guard_ok ? "" : "；" + t("护栏提示：") + (au.guard_reason || ""))) + '"' +
        ' onclick="pbPublishSelected(\'' + jsq(task.id) + "','" + platform + '\',true)">' +
        t("直发所选") + t("（") + sel.size + t("）") + "</button>" +
        '<button class="ghost" data-selection-action data-locked="' + (busy || au.draft_ok === false) + '" ' + (busy || !sel.size || au.draft_ok === false ? "disabled" : "") +
        ' title="' + esc(t("所选章节逐章自动存草稿（不上线、不受质量门禁拦截），完成后到平台检查并提交发布") +
          (au.draft_ok !== false ? "" : "；" + t("护栏提示：") + (au.draft_reason || ""))) + '"' +
        ' onclick="pbDraftSelected(\'' + jsq(task.id) + "','" + platform + '\')">' +
        t("存草稿所选") + t("（") + sel.size + t("）") + "</button>" +
        "</div></div></div>";
    }
    if (au.pending > 0 && au.draft_ok === false) {
      // 硬护栏（建书未确认/每日上限/连败退避）：存草稿也走不了，红色示警
      btns += '<div class="pb-err">' + esc(au.draft_reason || au.guard_reason || t("护栏拦截")) + "</div>";
    } else if (au.pending > 0 && !au.guard_ok && au.quality_blockers && au.quality_blockers.length) {
      // 纯质量闸拦截：不给死路——提示先存草稿（2026-10-09 全部发草稿通路）
      btns += '<div class="pb-hint">' + esc(t("质量闸未过：") + au.quality_blockers.join(t("；")) +
        t("——可先「全部存草稿」落平台（不上线），正式发布前需复审达标或强制放行")) + "</div>";
    }
    if (au.drafted > 0) {
      btns += '<div class="pb-hint">' + esc(t("已存草稿 {0} 章（未发布）：到平台章节管理/草稿箱逐章检查后提交发布", au.drafted)) + "</div>";
    }
    if (au.scheduled > 0) {
      btns += '<div class="pb-hint">' + esc(t("已有 {0} 章进入定时发布队列，平台确认上线后才计入已发布", au.scheduled)) + "</div>";
    }
    if (run && run.status === "manual_pause") {
      // 人工模式一轮只填一章：等用户在浏览器提交后再发起（连发会导航离开
      // 未提交的编辑器丢稿）。message 是下一步指引，不是错误。
      btns += '<div class="pb-hint">' + esc(run.message || t("已填好一章，请在浏览器确认提交")) + "</div>";
      if (run.last_chapter) {
        btns += '<button class="ghost pb-tool" onclick="pbConfirmChapter(\'' +
          jsq(task.id) + "', '" + platform + "', " + Number(run.last_chapter) +
          ')">' + t("我已在平台提交") + "</button>";
      }
    } else if (run && run.status !== "running") {
      const doneLine = run.status === "done"
        ? t("自动发布完成：") + run.done + "/" + run.total + (run.message ? t("。") + run.message : "")
        : t("自动发布中断：") + (run.error || "");
      btns += '<div class="' + (run.status === "done" ? "pb-hint" : "pb-err") + '">' +
        esc(doneLine + t("（") + (run.at || "") + t("）")) + "</div>";
    }
    }
  } else {
    if (book && book.title) {
      btns += '<span class="pb-book pb-err">' + esc(t("建书未确认：") + book.title) + "</span>";
    }
    // 多账号（2026-10-18）：建书用哪台账号的浏览器/配额，下拉选择
    btns += '<span class="pb-acc-sel-wrap">' + pbAccountSelectHtml(platform) + "</span>";
    btns += '<button class="primary" ' + (busy ? "disabled" : "") +
      ' onclick="pbCreateBook(\'' + jsq(task.id) + "', '" + platform + '\')">' + t("创建作品") + "</button>";
    btns += '<button class="ghost" onclick="pbRegToggle(\'' + jsq(task.id) + "','" + platform + '\')" title="' +
      esc(t("作品已在平台建好（建书流程没走通或手工建的）？补登记后直接发章，不会在平台新建")) + '">' + t("登记已有作品") + "</button>";
  }
  if (selectionOnly) return pendHtml;
  if (pendHtml) {
    const pending = (((S.pubAuto || {}).books || []).find((b) => b.platform === platform) || {}).pending || 0;
    const view = (((S.pubAuto || {}).books || []).find((b) => b.platform === platform) || {});
    pendHtml = '<div class="pb-pend-summary"><span>' + esc(t("待发 ")) + pending + esc(t(" 章")) +
      (view.next_chapter ? ' · ' + esc(t("下一章：第 {0} 章", view.next_chapter)) : '') + '</span>' +
      '<button class="primary" onclick="pbOpenSelection(\'' + jsq(task.id) + "','" + platform + '\')">' +
      esc(t("选择章节并发布")) + '</button></div>';
  }
  let extra = "";
  extra += pendHtml;
  if (st === "error" && !bookReady && ps.last_action === "create_book") {
    extra += '<div class="pb-hint">' + esc(t("若作品其实已在平台建好，点「登记已有作品」补登记，勿重复创建")) + "</div>";
  }
  // 展开态+草稿值外置（S.pbRegDraft，按任务+平台键）：整块重绘不再清空
  // 用户填了一半的作品名/ID——输入即存，重绘按草稿回填，登记成功才清。
  // 已建书态的「改绑定」复用这块表单：展开才渲染，没草稿就回填当前绑定值，
  // 改起来不用先抄一遍旧值。
  const reg = (S.pbRegDraft || {})[task.id + ":" + platform] || {};
  if (!bookReady || reg.open) {
    const curTitle = reg.title != null ? reg.title : (book && book.title || "");
    const curId = reg.id != null ? reg.id : (book && book.book_id || "");
    extra += '<div class="pb-reg' + (reg.open ? "" : " hidden") + '" id="pb-reg-' + platform + '">' +
      '<input id="pb-reg-title-' + platform + '" value="' + esc(curTitle) +
      '" placeholder="' + esc(t("平台上的作品名（必填）")) +
      '" oninput="pbRegDraftSave(\'' + jsq(task.id) + "','" + platform + '\',\'title\',this.value)">' +
      '<input id="pb-reg-id-' + platform + '" value="' + esc(curId) +
      '" placeholder="' + esc(t("作品ID（选填，管理页URL里有）")) +
      '" oninput="pbRegDraftSave(\'' + jsq(task.id) + "','" + platform + '\',\'id\',this.value)">' +
      '<button class="ghost" onclick="pbRegister(\'' + jsq(task.id) + "', '" + platform + '\'' + (bookReady ? ", true" : "") + ')">' +
      t(bookReady ? t("确认修改") : t("确认登记")) + "</button>" +
      "</div>";
  }
  return '<div class="bm-pub">' +
    '<span class="pb-badge ' + cls + '">' + esc(t(label)) + "</span>" +
    btns +
    (st === "error" && ps.error ? '<div class="pb-err">' + esc(ps.error) + "</div>" : "") +
    extra +
    '<div class="pb-chapters hidden" id="pb-ch-' + platform + '"></div>' +
    "</div>";
}

let _pbTimer = 0;
async function pbPrepareChapter(taskId, platform) {
  const r = await api("/api/publish/task/" + encodeURIComponent(taskId) + "/prepare-chapter",
    { method: "POST", body: JSON.stringify({ platform }) });
  // 让批量选择弹框立即使用校准后的清单；保留另一平台的状态，避免面板
  // 重绘时把它的卡片信息清掉。
  if (r && r.book) {
    const old = S.pubAuto || {};
    const books = (old.books || []).filter((b) => b.platform !== platform);
    books.push(r.book);
    S.pubAuto = Object.assign({}, old, { books, running: r.running || null });
  }
  return r;
}

window.pbOpenSelection = async function (taskId, platform) {
  const task = ((S.state || {}).tasks || []).find((x) => x.id === taskId);
  if (!task) return;
  try {
    toast(t("正在校准平台章节状态…"));
    await pbPrepareChapter(taskId, platform);
  } catch (e) {
    toast(t("发布前校准失败：") + e.message, true);
    return;
  }
  const html = pbBlock(task, platform, true);
  if (!html) { toast(t("当前没有可选择的待发章节")); return; }
  const title = t("选择章节并发布") + " · " + t(platform === "fanqie" ? "番茄" : t("七猫"));
  const returnFocus = document.activeElement;
  openModal(title, "", "");
  _pbReturnFocus = returnFocus;
  $("modal").dataset.pbKey = taskId + ":" + platform;
  $("modal").classList.add("pb-selection-modal");
  pbRefreshSelectionDialog(task);
  const first = $("modal-body").querySelector("input");
  if (first) first.focus({ preventScroll: true });
};

function pbRefreshSelectionDialog(task) {
  const modal = $("modal");
  if (!modal || modal.classList.contains("hidden") || !modal.dataset.pbKey) return;
  const platform = ["fanqie", "qimao"].find((p) => modal.dataset.pbKey === task.id + ":" + p);
  if (!platform) { closeModal(); return; }
  const html = pbBlock(task, platform, true);
  if (!html) { closeModal(); return; }
  const shell = document.createElement("div");
  shell.innerHTML = html;
  const foot = shell.querySelector(".pb-pend-foot");
  foot.remove();
  const body = $("modal-body");
  const scrollTop = body.scrollTop;
  const active = document.activeElement;
  const hadFocus = modal.contains(active);
  const chip = active && active.closest(".pb-chip");
  const volume = active && active.closest(".pb-pend-volume");
  const action = active && active.getAttribute("onclick");
  const chapter = chip ? chip.dataset.chapter : "";
  const volumeIndex = volume ? volume.dataset.volume : "";
  body.innerHTML = shell.innerHTML;
  body.scrollTop = scrollTop;
  $("modal-foot").innerHTML = foot.outerHTML;
  pbSelCountSync(modal.dataset.pbKey);
  let target = null;
  if (chapter) target = [...body.querySelectorAll(".pb-chip")].find((c) => c.dataset.chapter === chapter)?.querySelector("input");
  else if (volumeIndex) target = body.querySelector('[data-volume="' + volumeIndex + '"] .pb-vol-sel input');
  else if (action && hadFocus) target = [...modal.querySelectorAll("[onclick]")].find((el) => el.getAttribute("onclick") === action);
  if (target) target.focus({ preventScroll: true });
}

function pbSyncState(task) {
  clearTimeout(_pbTimer);
  // 5s 节流折进调度间隔：距上一拉未满 5s 就等满再拉（pbKick 置 0 可立即拉）
  const delay = Math.max(120, 5000 - (Date.now() - (S.pubFetchAt || 0)));
  _pbTimer = setTimeout(async () => {
    // 自续轮询链：详情区签名守卫上线后，主渲染泵不再每 8s 带跑本面板，
    // 发布状态自己转——面板可见且仍指向同一任务就 5s 一拉，收起/切走
    // 自然停，下次 renderBookMetaPanel 重新点火。task 对象可能已老，
    // 一律按 id 从 S.state 重解析，渲染吃的永远是新数据。
    const box = $("rd-bookmeta");
    if (!task || !task.id || !box || box.classList.contains("hidden") ||
        $("run-detail").classList.contains("hidden")) return;
    const tk = ((S.state || {}).tasks || []).find((x) => x.id === task.id);
    if (!tk || ((S.lastRunTask || {}).id || "") !== tk.id) return;
    S.pubFetchAt = Date.now();
    let sig = "";
    try {
      const v = await api("/api/publish");
      S.pubState = v;
      sig += JSON.stringify(v.platforms || {});
    } catch (e) { pbSyncState(tk); return; }
    try {
      const ti = await api("/api/publish/task/" + encodeURIComponent(tk.id) + "/history");
      S.pubTaskInfo = ti;
      sig += "#" + JSON.stringify(ti.books || {}) + "#" + (ti.history || []).length;
      // 已发章数自动校准：平台在线且登记在案、超 10 分钟没对过账就静默对一次
      //（服务端只 attach 在跑的浏览器，绝不因此弹新窗口；结果落 books.json，
      // 下一轮轮询带回来重渲染）。失败不打扰——旧数继续显示。
      const nowMs = Date.now();
      Object.keys(ti.books || {}).forEach((p) => {
        const bk = ti.books[p] || {};
        const ps2 = ((S.pubState && S.pubState.platforms) || {})[p] || {};
        const at = bk.remote_synced_at
          ? Date.parse(String(bk.remote_synced_at).replace(/-/g, "/")) || 0 : 0;
        if (ps2.status === "connected" && nowMs - at > 600000 &&
            nowMs - (S["_pbSyncAt_" + p] || 0) > 600000) {
          S["_pbSyncAt_" + p] = nowMs;
          api("/api/publish/task/" + encodeURIComponent(tk.id) + "/sync-published",
            { method: "POST", body: JSON.stringify({ platform: p }) }).catch(() => {});
        }
      });
    } catch (e) { /* 任务级失败不阻塞平台状态 */ }
    try {
      // 批量发布视图（待发数/护栏/进度）——进行中时靠本节流轮询自然刷新
      const au = await api("/api/publish/task/" + encodeURIComponent(tk.id) + "/pending");
      S.pubAuto = au;
      sig += "@" + JSON.stringify(au.books || {}) + "@" + JSON.stringify(au.running || {}) +
        "@" + JSON.stringify(au.retry || null);
    } catch (e) { /* 视图缺失（老服务）不阻塞 */ }
    if (sig !== (S._pbSig || "")) {
      S._pbSig = sig;
      renderBookMetaPanel(tk);
    } else S._pbSig = sig;
    pbSyncState(tk);   // 续链：面板还开着就下一轮 5s 后再来
  }, delay);
}

window.pbSyncPublished = async function (taskId, platform) {
  // 手动校准：允许服务端 attach-or-launch（用户点了按钮，弹窗口是预期内）
  try {
    const r = await api("/api/publish/task/" + encodeURIComponent(taskId) +
      "/sync-published", { method: "POST",
        body: JSON.stringify({ platform: platform, manual: true }) });
    if (r.skipped && r.skipped[platform])
      toast(t("校准未执行：") + r.skipped[platform], true);
    else toast(t("正在按平台实况校准，几秒后自动更新"));
  } catch (e) { toast(t("校准失败：") + e.message, true); }
};

