window.pbUploadChapter = async function (taskId, platform) {
  const box = $("pb-ch-" + platform);
  if (!box) return;
  if (!box.classList.contains("hidden")) { box.classList.add("hidden"); return; }
  box.classList.remove("hidden");
  box.innerHTML = '<div class="pb-loading">' + esc(t("正在列出章节文件…")) + "</div>";
  let wd = "", pubTask = null;
  try {
    pubTask = ((S.state || {}).tasks || []).find((x) => x.id === taskId);
    wd = (pubTask && pubTask.workdir) || "";
  } catch (e) { /* 兜底空 */ }
  if (!wd) { box.innerHTML = '<div class="pb-err">' + esc(t("找不到任务工作目录")) + "</div>"; return; }
  let files = [];
  try {
    // 章节选择必须建立在刚刚完成的平台实况校准上。旧的 GET /pending
    // 只读本地台账，平台手工补交后会把已发布章再次列出来；prepare-chapter
    // 同步章节管理页并返回校准后的待发清单。
    box.innerHTML = '<div class="pb-loading">' + esc(t("正在校准平台章节状态…")) + "</div>";
    const r = await pbPrepareChapter(taskId, platform);
    const book = r.book || (r.books || []).find((b) => b.platform === platform);
    files = ((book && book.items) || []).map((f) => ({ name: f.file, chapter_no: f.chapter_no }));
  } catch (e) {
    box.innerHTML = '<div class="pb-err">' + esc(t("发布前校准失败：") + e.message) + "</div>";
    return;
  }
  if (!files.length) { box.innerHTML = '<div class="pb-hint">' + esc(t("暂无待发章节，已发布和已存草稿的章节已排除")) + "</div>"; return; }
  files.sort((a, b) => a.chapter_no - b.chapter_no);
  const item = (f) =>
    '<button class="ghost pb-ch-item" onclick="pbSendChapter(\'' + jsq(taskId) + "', '" + platform +
    '\',\'' + jsq(f.name) + '\')" title="' + esc(f.name) + '">' + esc(f.name.split("/").pop()) + "</button>";
  const hint = '<div class="pb-hint">' + esc(t("选一章后自动提交并核验平台结果；已成功发布的章节会被台账拦下：")) + "</div>";
  // 最高章号：让卷规划表铺到最后一章（否则超出显式卷表的章节会掉进「其他」）
  let maxCh = 0;
  files.forEach((f) => {
    const n = chapterNumOf(f.name);
    if (n > maxCh) maxCh = n;
  });
  const plan = volumePlanOf(pubTask, maxCh);
  if (!plan.length) { box.innerHTML = hint + files.map(item).join(""); return; }
  // 分卷：按卷分组列出可发章节（章号取自 chapter-NN.md）。未落入卷的文件归「其他」。
  const groups = plan.map((v) => ({ v: v, files: [] }));
  const rest = [];
  files.forEach((f) => {
    const n = chapterNumOf(f.name);
    if (!n) { rest.push(f); return; }
    const g = groups.find((x) => n >= x.v.first && (x.v.last == null || n <= x.v.last));
    if (g) g.files.push(f); else rest.push(f);
  });
  box.innerHTML = hint + groups.filter((g) => g.files.length).map((g) => {
    const label = t("第") + " " + g.v.vol + " " + t("卷") + (g.v.title ? " " + t("《") + g.v.title + t("》") : "");
    return '<div class="pb-vol"><div class="pb-vol-head">' + esc(label) + "</div>" +
      g.files.map(item).join("") + "</div>";
  }).join("") + (rest.length ? '<div class="pb-vol"><div class="pb-vol-head">' +
    esc(t("其他文件")) + "</div>" + rest.map(item).join("") + "</div>" : "");
};

window.pbSendChapter = async function (taskId, platform, relName) {
  try {
    const r = await pbApiWithQualityOverride(
      "/api/publish/task/" + encodeURIComponent(taskId) + "/chapter",
      { platform, file: relName, auto_submit: true }, t("发章前的质量门禁未通过"), taskId);
    if (!(r && r.gate_reviewed)) {
      toast(t("正在自动填写并提交章节…"));
      const box = $("pb-ch-" + platform);
      if (box) {
        const n = chapterNumOf(relName);
        box.classList.remove("hidden");
        box.innerHTML = '<div class="pb-hint">' + esc(t("章节已提交，正在核验平台结果")) +
          '</div>';
      }
    }
  } catch (e) { toast(t("发章失败：") + e.message, true); }
  S._pbSig = ""; pbKick();
};

window.pbConfirmChapter = async function (taskId, platform, chapterNo) {
  try {
    const r = await api("/api/publish/task/" + encodeURIComponent(taskId) + "/confirm-chapter",
      { method: "POST", body: JSON.stringify({ platform, chapter_no: chapterNo }) });
    toast(r && r.continued
      ? t("已确认提交，正在自动处理下一章")
      : t((r && r.message) || t("已确认提交，台账已更新")));
  } catch (e) { toast(t("确认提交失败：") + e.message, true); }
  // The confirmation endpoint records the chapter and starts the next batch;
  // invalidate both cached views so CodeBee's published/pending counters
  // reflect that hand-off on the next poll immediately.
  S.pubAuto = null;
  S.pubTaskInfo = null;
  S._pbSig = ""; pbKick();
};

function pbSelCountSync(key) {
  // 就地对账：按钮计数/禁用态与全部 chip 勾选态向状态层看齐——重绘链一旦
  // 断掉（poll 失败/详情上下文切换），勾选与计数也不许脱节（2026-10-08 实案
  // 「勾了 18 计数 48」即重绘未跟上）。
  const modal = $("modal");
  const box = modal && modal.dataset.pbKey === key ? modal
    : [...document.querySelectorAll(".pb-pend")].find((el) => el.dataset.key === key);
  const ent = (S.pbSel || {})[key];
  if (!box || !ent) return;
  const count = box.querySelector(".pb-pend-count");
  if (count) count.textContent = t("已选 {0}/{1} 章", ent.sel.size, ent.sig.split(",").length);
  for (const b of box.querySelectorAll("[data-selection-action]")) {
    const action = b.getAttribute("onclick") || "";
    const label = action.includes("pbDraftSelected") ? t("存草稿所选") : t("直发所选");
    b.textContent = t(label) + t("（") + ent.sel.size + t("）");
    b.disabled = ent.sel.size === 0 || b.dataset.locked === "true";
    if (!b.hasAttribute("data-ready-title")) b.dataset.readyTitle = b.title;
    b.title = ent.sel.size === 0 ? t("请先选择章节") : b.dataset.readyTitle;
  }
  for (const section of box.querySelectorAll(".pb-pend-volume")) {
    const g = ent.groups[Number(section.dataset.volume)];
    const label = section.querySelector(".pb-vol-sel");
    if (!g || !label) continue;
    const cnt = g.ns.filter((n) => ent.sel.has(n)).length;
    const input = label.querySelector("input");
    input.checked = cnt === g.ns.length;
    input.indeterminate = cnt > 0 && cnt < g.ns.length;
    label.classList.toggle("on", input.checked);
    label.classList.toggle("partial", input.indeterminate);
    label.querySelector(".pb-vol-count").textContent = t("已选 {0}/{1} 章", cnt, g.ns.length);
  }
  for (const c of box.querySelectorAll(".pb-chip")) {
    const inp = c.querySelector("input");
    const num = Number(c.dataset.chapter);
    if (!inp || !num) continue;
    const on = ent.sel.has(num);
    if (inp.checked !== on) inp.checked = on;
    c.classList.toggle("on", on);
  }
}

window.pbSelToggle = function (taskId, platform, no, on) {
  const key = taskId + ":" + platform;
  const ent = (S.pbSel || {})[key];
  if (!ent) return;
  if (on) ent.sel.add(Number(no)); else ent.sel.delete(Number(no));
  pbSelCountSync(key);       // 选择只在本地同步，避免重绘打断滚动和键盘焦点
};

window.pbSelAll = function (taskId, platform, all) {
  const key = taskId + ":" + platform;
  const ent = (S.pbSel || {})[key];
  if (!ent) return;
  if (all) for (const n of ent.sig.split(",")) ent.sel.add(Number(n));
  else ent.sel.clear();
  pbSelCountSync(key);
};

window.pbSelReady = function (taskId, platform) {
  const key = taskId + ":" + platform;
  const ent = (S.pbSel || {})[key];
  if (!ent) return;
  ent.sel = new Set(ent.ready || []);
  pbSelCountSync(key);
};

window.pbSelVolume = function (taskId, platform, gi, on) {
  const key = taskId + ":" + platform;
  const ent = (S.pbSel || {})[key];
  const g = ent && ent.groups && ent.groups[gi];
  if (!g || !g.ns.length) return;
  if (on) for (const n of g.ns) ent.sel.add(n);
  else for (const n of g.ns) ent.sel.delete(n);
  pbSelCountSync(key);
};

