function pbKick() {
  const key = detailSideTaskKey();
  if (!key) return;
  const tk = ((S.state || {}).tasks || []).find((x) => x.id === key);
  if (tk) { S.pubFetchAt = 0; pbSyncState(tk); }
}

/* ---------------- 详情页任务级 side 数据（检查器让位后的主栏自给） ----------------
 * 检查器收进列表上下文后，任务累计统计与 git 实时状态由详情页自己轮询
 * /api/tasks/<id>/side（KB 级、2s 节流，与检查器同款）。拉不到（无主运行、
 * 任务已删、接口失败）就静默保持 null，版本面板退回 run 快照、meta 不出累计组。 */
function detailSideReset() {
  S.detailSide = null;
  S.detailSideSig = "";
  S.detailSideAt = 0;
}

function detailSideTaskKey() {
  return (S.detailTaskKey || (S.lastRun && S.lastRun.task_id) || "");
}

async function refreshDetailSide(force) {
  const key = detailSideTaskKey();
  if (!key || $("run-detail").classList.contains("hidden")) return;
  const now = Date.now();
  if (!force && now - (S.detailSideAt || 0) < 2000) return;
  S.detailSideAt = now;
  let d;
  try { d = await api("/api/tasks/" + encodeURIComponent(key) + "/side"); }
  catch (e) { return; }                      // 拉取失败静默，等下一轮节流重试
  if (detailSideTaskKey() !== key) return;   // 期间已切到别的详情：过期响应不落盘
  if (!d || !d.task) {
    S.detailSide = null;
    renderChangeSummary();
    renderChatContext(true);
    chatSig = ""; chatLiveSig = "";
    if (S.lastRun && S.lastRun.task_id === key) renderChat(S.lastRun, ["running", "queued"].includes(S.lastRun.status));
    return;
  }
  S.detailSide = d;
  renderChangeSummary();
  renderChatContext(true);
  const sig = JSON.stringify([d.task.git_state, d.git, d.changes, d.stats]);
  if (sig === S.detailSideSig) return;       // 没变化不重画（保住文件行 hover 态）
  S.detailSideSig = sig;
  applyDetailSide();
  // side 快照独立于时间线轮询返回；变更卡片需要在同一轮对话中即时出现/更新。
  if (S.lastRun && S.lastRun.task_id === key) {
    chatSig = ""; chatLiveSig = "";
    renderChat(S.lastRun, ["running", "queued"].includes(S.lastRun.status));
  }
}

/* Compact Git receipt from the desktop reference. It follows the task currently
 * shown in the conversation and uses the same task-side snapshot as the Git tab. */
function renderChangeSummary() {
  const card = $("change-summary");
  if (!card) return;
  const detail = $("run-detail");
  const key = detailSideTaskKey();
  const data = S.detailSide;
  const task = data && data.task;
  const changes = data && data.changes;
  const hasRepoContext = !!(data && data.git && data.git.branch);
  if (!detail || detail.classList.contains("hidden") || !key || !task || task.id !== key || !hasRepoContext || !changes) {
    card.classList.add("hidden");
    return;
  }
  const path = String(task.workdir || "").replace(/[\\/]+$/, "");
  const project = path.split(/[\\/]/).filter(Boolean).pop() || task.title || t("项目变更");
  $("change-summary-project").textContent = project;
  $("change-summary-project").title = task.workdir || project;
  $("change-summary-add").textContent = "+" + (Number(changes.add_total) || 0);
  $("change-summary-del").textContent = "-" + (Number(changes.del_total) || 0);
  card.classList.remove("hidden");
}

function openChangeSummaryGit() {
  const key = detailSideTaskKey();
  if (!key || !S.detailSide || !S.detailSide.git || !S.detailSide.git.branch) return;
  S.rdTab = "git";
  S.rdTabPin = true;
  if (S.lastRun && S.lastRun.task_id === key) renderGitPanel(S.lastRun, S.lastRunTask);
  applyRdTabs();
}

window.toggleBrowserSplit = function () {
  const detail = $("run-detail");
  if (!detail || detail.classList.contains("hidden")) {
    toast(t("请先打开一个任务对话。"), true);
    return;
  }
  const open = !document.body.classList.contains("browser-split-open");
  if (open) {
    if (detailSideTaskKey()) wbTaskId = detailSideTaskKey();
    try { if (wbTaskId) localStorage.setItem(WB_TASK_STORAGE_KEY, wbTaskId); } catch (e) { /* local preference only */ }
    applyBrowserSplit(true);
    wbDraw();
  } else {
    applyBrowserSplit(false);
  }
};

/* 并排工作台是详情视图的附属面板：开关状态同步到 body 与顶栏按钮。
 * 离开详情时由 closeRun 统一关闭——设置/主页/任务列表都没有任务上下文，
 * 留着会横盖半个页面。 */
function applyBrowserSplit(open) {
  document.body.classList.toggle("browser-split-open", open);
  const button = $("btn-browser-split");
  if (!button) return;
  button.classList.toggle("active", open);
  button.setAttribute("aria-pressed", open ? "true" : "false");
  const label = t(open ? t("关闭并排浏览器") : t("并排打开浏览器"));
  button.title = label;
  button.setAttribute("aria-label", label);
}

function closeBrowserSplit() {
  if (document.body.classList.contains("browser-split-open")) applyBrowserSplit(false);
}

/* 并排工作台跟着详情目标走：切到另一个任务就把它切过去，别让右栏停在上一个任务。 */
function syncBrowserSplitTask(key) {
  if (!document.body.classList.contains("browser-split-open") || !key || key === wbTaskId) return;
  wbTaskId = key;
  try { localStorage.setItem(WB_TASK_STORAGE_KEY, wbTaskId); } catch (e) { /* local preference only */ }
  wbDraw();
}

/* side 数据落位：meta 条任务累计组 + 版本面板重画（内部再按数据源取舍） */
function applyDetailSide() {
  const d = S.detailSide;
  if (!d) return;
  fillMetaTask((d.stats || {}));
  renderGitPanel(S.lastRun, S.lastRunTask);
}

/* meta 条的任务累计 pill：run 级统计旁边给任务全貌。renderRunDetail 每轮
 * 轮询都会重建 rd-meta，所以渲染时也要回填（S.detailSide 有缓存就即时填） */
function fillMetaTask(st) {
  const el = $("rd-meta-task");
  if (!el) return;
  el.classList.remove("hidden");
  el.innerHTML = esc(t("任务累计")) + " <b>" + (st.runs || 0) + "</b> " + esc(t("次运行")) +
    " · <b>" + (st.steps || 0) + "</b> " + esc(t("步")) +
    ' · <b>$' + (Number(st.cost_usd) || 0).toFixed(3) + "</b> · tok <b>" + (st.tokens || 0) + "</b>";
}

/* ---------------- GIT 工作台（详情页「版本」页签） ----------------
 * 工作目录是 git 仓库 → 完整工作台：分支切换 / 三组变更文件（暂存·取消暂存·
 * 丢弃/删除）/ 提交 / fetch·pull·push / stash 收起还原；数据走
 * /api/tasks/<id>/git（workdir 由服务端按任务推导，不接受任意路径），
 * 5s 节流轮询、写操作后立即重拉。非仓库 → 退回「代码版本隔离」快照面板。
 * 写操作在任务运行中被服务端 409 拒绝，前端同步禁用并给只读提示。 */
async function loadGitWb(force) {
  const key = detailSideTaskKey();
  if (!key || S.gitWbBusy) return;
  if (!force && S.gitWbKey === key && Date.now() - (S.gitWbAt || 0) < 5000) return;
  S.gitWbBusy = true;
  try {
    const d = await api("/api/tasks/" + encodeURIComponent(key) + "/git");
    if (detailSideTaskKey() !== key) return;   // 期间已切详情目标：过期响应不落盘
    S.gitWb = d; S.gitWbKey = key; S.gitWbAt = Date.now();
    renderGitPanel(S.lastRun, S.lastRunTask);
    renderChatContext(true);
  } catch (e) { /* 静默：下一轮节流重试 */ }
  finally { S.gitWbBusy = false; }
}

function renderGitPanel(run, task) {
  const box = $("rd-git");
  if (!box) return;
  const tid = (task || {}).id || "";
  if (tid) {
    loadGitWb();   // 5s 节流；写操作后 force 立即重拉
    const wb = (S.gitWbKey === tid) ? S.gitWb : null;
    if (wb && wb.repo) { renderGitWbMain(wb, task); return; }
    // 探测未回（wb=null）：先按快照落位不闪空；确认非仓库（repo=false）也走快照
  }
  _renderGitSnapshot(run, task);
}

function _renderGitSnapshot(run, task) {
  const box = $("rd-git");
  if (!box) return;
  const tid = (task || {}).id || "";
  // 数据源取舍：side 命中且确实属于当前详情的任务才用，否则退 run 快照
  const sTask = ((S.detailSide || {}).task || {});
  const useSide = !!sTask.id && sTask.id === ((run || {}).task_id || tid);
  const side = useSide ? S.detailSide : null;
  const g = side ? (side.git || {}) : ((run || {}).git || {});
  const state = side ? (sTask.git_state || "") : ((task || {}).git_state || "");
  const revChosen = side ? (sTask.git_rev || "") : ((task || {}).git_rev || "");
  const ch = side ? (side.changes || {}) : ((run || {}).changes || {});
  const files = ch.files || [];
  const active = ["running", "queued"].indexOf(side ? sTask.status : ((task || {}).status)) >= 0;
  if (!g || !g.branch) {
    // 没有任务分支：区分「没启用」（未指定代码版本 → 整块隐藏）和
    // 「启用了但检出失败」（给原因，不能误报成没启用——同检查器口径）
    if (revChosen) {
      const lastErr = side ? (((side.run || {}).error) || "") : ((run || {}).error || "");
      box.classList.remove("hidden");
      box.innerHTML =
        '<div class="git-head"><svg class="ico" aria-hidden="true"><use href="#i-git-branch"></use></svg>' +
        '<span class="sec-title">' + t("代码版本隔离") + '</span>' +
        '<span class="chip failed">' + t("检出失败") + "</span>" +
        '<code class="git-branch">codebee/' + esc(tid || t("（无主运行）")) + t("（") + esc(t("未创建")) + t("）") + "</code></div>" +
        (lastErr ? '<div class="hint warn">' + esc(lastErr) + "</div>" : "") +
        '<div class="hint">' + esc(t("处理后点「继续任务」，运行会重新检出任务分支。")) + "</div>";
      rdTabsSync();
      return;
    }
    box.classList.add("hidden"); box.innerHTML = ""; rdTabsSync(); return;
  }
  const chip = GIT_STATE_CHIP[state] || ["muted", "—"];
  let html =
    '<div class="git-head"><svg class="ico" aria-hidden="true"><use href="#i-git-branch"></use></svg>' +
    '<span class="sec-title">' + t("代码版本隔离") + '</span>' +
    '<button class="hhelp" data-help-topic="code" title="' + esc(t("这是什么？点开看帮助")) + '" aria-label="' + esc(t("帮助")) + '"><svg class="ico" aria-hidden="true"><use href="#i-help"></use></svg></button>' +
    '<code class="git-branch" title="' + esc(t("任务分支：产物提交在此，原分支未受影响")) + '">' + esc(g.branch) + "</code>";
  const addT = ch.add_total, delT = ch.del_total;
  if (addT != null && delT != null) {
    html += '<span class="insp-plus">+' + addT + '</span><span class="insp-minus">-' + delT + "</span>";
  }
  html += '<span class="chip ' + chip[0] + '">' + t(chip[1]) + "</span>" +
    "</div>";
  html += '<div class="git-meta">' +
    "<span>" + esc(t("基线")) + " <b>" + esc(g.rev || "-") + "</b> → " + esc(g.from_branch || "-") + "</span>" +
    (g.commit ? "<span>" + esc(t("分支提交")) + " <b>" + esc(g.commit) + "</b></span>" : "") +
    (side ? "" : "<span>" + esc(t("本 run 快照")) + "</span>") +
    "</div>";
  if (g.restore_error) {
    html += '<div class="hint warn">' + esc(t("收尾出错：")) + esc(g.restore_error) + "</div>";
  }
  // 变更行双击看 diff：diff 文本挂在 run 的 changes 快照上，side 场景取最新 run
  const diffRunId = (side && (side.run || {}).id) || (run || {}).id || "";
  html += '<div class="git-files">' + (files.length
    ? files.slice(0, 40).map((f) =>
        '<button class="gf" data-p="' + esc(f.path) + '" data-rid="' + esc(diffRunId) +
        '" ondblclick="fileDiffPopup(this.dataset.p, this.dataset.rid)" title="' +
        esc(t("双击弹窗查看该文件的变更")) + '"><i class="gs ' + (f.status === "M" ? "m" : f.status === "D" ? "d" : "n") + '">' +
        esc(gitStatusLabel(f.status)) + "</i>" + esc(f.path) + "</button>").join("") +
      (files.length > 40 ? '<span class="gm">+' + (files.length - 40) + " " + esc(t("个文件")) + "</span>" : "")
    : '<span class="hint">' + esc(t(active ? t("运行中：工作区变更会实时出现在这里。") : t("本次运行没有产生工作区变更。"))) + "</span>") +
    "</div>";
  // 裁决是任务级动作：只在待裁决且任务空闲时给出（运行/排队中合并会踩正在写的分支）
  if (state === "isolated" && tid && !active) {
    html += '<div class="git-actions">' +
      '<button class="primary" onclick="gitMerge(\'' + jsq(tid) + "')\">" +
      '<svg class="ico" aria-hidden="true"><use href="#i-check"></use></svg>' + t("合并回原分支") + "</button>" +
      '<button class="danger ghost" onclick="gitDiscard(\'' + jsq(tid) + "')\">" +
      '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg>' + t("丢弃分支") + "</button>" +
      '<span class="hint">' + esc(t("合并＝采纳产物回原分支；丢弃＝删除任务分支（不可恢复）。")) + "</span></div>";
  }
  box.classList.remove("hidden");
  box.innerHTML = html;
  rdTabsSync();   // 版本面板显隐决定「版本」标签可用性
}

/* 工作台文件行：状态字 + 路径 + ±统计，悬停出 暂存/取消暂存/丢弃(删除) 按钮，
 * 点击/双击弹实时 diff（/api/tasks/<id>/git/diff，读工作区，不依赖 run 快照） */
function _gwbRow(f, kind, ro) {
  const p = f.path || "";
  const cls = f.status === "M" ? "m" : f.status === "D" ? "d" : "n";
  let acts = "";
  if (!ro) {
    const stage = '<button class="ghost gwb-act" data-p="' + esc(p) + '" onclick="gitWbStage(this.dataset.p)" title="' +
      esc(t("暂存")) + '">+</button>';
    const unstage = '<button class="ghost gwb-act" data-p="' + esc(p) + '" onclick="gitWbUnstage(this.dataset.p)" title="' +
      esc(t("取消暂存")) + '">−</button>';
    const discard = '<button class="ghost gwb-act gwb-danger" data-p="' + esc(p) + '" onclick="gitWbDiscard(this.dataset.p)" title="' +
      esc(t("丢弃改动")) + '">↶</button>';
    const del = '<button class="ghost gwb-act gwb-danger" data-p="' + esc(p) + '" onclick="gitWbDelete(this.dataset.p)" title="' +
      esc(t("删除文件")) + '">✕</button>';
    if (kind === "staged") acts = unstage + discard;
    else if (kind === "unstaged") acts = stage + discard;
    else acts = stage + del;
  }
  return '<div class="gwb-row">' +
    '<button class="gf" data-p="' + esc(p) + '" onclick="gitWbDiff(this.dataset.p)" ' +
    'ondblclick="gitWbDiff(this.dataset.p)" title="' + esc(t("点击查看该文件的变更内容")) + '">' +
    '<i class="gs ' + cls + '">' + esc(gitStatusLabel(f.status)) + "</i>" +
    '<span class="p">' + esc(p) + "</span>" +
    (f.add ? '<span class="insp-plus">+' + f.add + "</span>" : "") +
    (f.del ? '<span class="insp-minus">-' + f.del + "</span>" : "") +
    "</button>" + acts + "</div>";
}

function _gwbGroup(title, files, kind, ro, emptyHint) {
  const n = (files || []).length;
  return '<div class="gwb-group" data-kind="' + kind + '">' +
    '<div class="gwb-ghead"><b>' + esc(title) + '</b><span class="gm">' + n + "</span></div>" +
    (n ? files.map((f) => _gwbRow(f, kind, ro)).join("")
       : '<span class="hint">' + esc(emptyHint) + "</span>") +
    "</div>";
}

function renderGitWbMain(d, task) {
  const box = $("rd-git");
  if (!box) return;
  const tid = (task || {}).id || "";
  const ro = d.task && (d.task.status === "running" || d.task.status === "queued");
  const prevMsg = (box.querySelector("#gwb-msg") || {}).value || "";
  const dis = ro ? " disabled" : "";
  // 分支下拉：本地 + 远程两组；游离 HEAD 时当前值给占位项
  const cur = d.branch || "";
  const opt = (b) => '<option value="' + esc(b) + '"' + (b === cur ? " selected" : "") + ">" + esc(b) + "</option>";
  let sel = '<select id="gwb-branch" class="git-branch gwb-branch" title="' + esc(t("切换分支")) + '"' + dis + ">";
  if (d.detached) sel += '<option value="" selected disabled>' + esc(t("(游离 HEAD)")) + "</option>";
  if ((d.branches || []).length) sel += '<optgroup label="' + esc(t("本地分支")) + '">' + d.branches.map(opt).join("") + "</optgroup>";
  if ((d.remote_branches || []).length) sel += '<optgroup label="' + esc(t("远程分支")) + '">' + d.remote_branches.map(opt).join("") + "</optgroup>";
  sel += "</select>";
  let html =
    '<div class="git-head"><svg class="ico" aria-hidden="true"><use href="#i-git-branch"></use></svg>' +
    '<span class="sec-title">' + t("Git 工作台") + "</span>" +
    '<button class="hhelp" data-help-topic="code" title="' + esc(t("这是什么？点开看帮助")) + '" aria-label="' + esc(t("帮助")) + '"><svg class="ico" aria-hidden="true"><use href="#i-help"></use></svg></button>' + sel +
    '<code class="git-branch" title="HEAD">' + esc(d.head || "") + "</code>" +
    (d.upstream ? '<span class="gm" title="' + esc(d.upstream) + '">↑' + (d.ahead || 0) + " ↓" + (d.behind || 0) + "</span>" : "") +
    '<span class="flex1"></span>' +
    '<button class="ghost" onclick="loadGitWb(true)" title="' + esc(t("刷新")) + '">' +
    '<svg class="ico" aria-hidden="true"><use href="#i-refresh"></use></svg></button></div>';
  // 工具条：抓取/拉取/推送 + 全部暂存 + stash；无远程时网络类禁用
  const noRemote = !(d.remotes || []).length;
  const hasChg = (d.staged || []).length + (d.unstaged || []).length + (d.untracked || []).length;
  html += '<div class="gwb-toolbar">' +
    '<button class="ghost"' + (noRemote || ro ? " disabled" : "") + ' onclick="gitWbFetch()">' + t("抓取") + "</button>" +
    '<button class="ghost"' + (noRemote || ro ? " disabled" : "") + ' onclick="gitWbPull()">' + t("拉取") + "</button>" +
    '<button class="ghost"' + (noRemote || ro ? " disabled" : "") + ' onclick="gitWbPush()">' + t("推送") + "</button>" +
    '<button class="ghost"' + (noRemote || ro || d.detached ? " disabled" : "") + ' onclick="gitWbPrCreate()" title="' +
    esc(t("推送当前分支并用 gh 创建 PR（目标分支自动取 main/master）")) + '">' + t("建 PR") + "</button>" +
    '<button class="ghost"' + (!hasChg || ro ? " disabled" : "") + ' onclick="gitWbStageAll()">' + t("全部暂存") + "</button>" +
    '<button class="ghost"' + (!hasChg || ro ? " disabled" : "") + ' onclick="gitWbStash()" title="' +
    esc(t("把未提交改动收进 stash（不含 _attachments）")) + '">' + t("收起改动") + "</button>" +
    (ro ? '<span class="hint">' + esc(t("任务运行中：Git 写操作暂停（只读查看）。")) + "</span>" : "") +
    "</div>";
  (d.stashes || []).forEach((s) => {
    html += '<div class="gwb-stash"><span class="gm">' + esc(s.ref) + '</span><span class="p">' + esc(s.subject) + "</span>" +
      (ro ? "" : '<button class="ghost" onclick="gitWbStashPop(\'' + jsq(s.ref) + '\')">' + t("还原") + "</button>" +
        '<button class="ghost gwb-danger" onclick="gitWbStashDrop(\'' + jsq(s.ref) + '\')">' + t("删除") + "</button>") +
      "</div>";
  });
  // 三组变更文件
  html += _gwbGroup(t("暂存的变更"), d.staged, "staged", ro, t("暂存区为空")) +
    _gwbGroup(t("变更（未暂存）"), d.unstaged, "unstaged", ro, t("没有未暂存的改动")) +
    _gwbGroup(t("未跟踪"), d.untracked, "untracked", ro, t("没有未跟踪文件"));
  // 提交区
  html += '<div class="gwb-commit">' +
    '<input id="gwb-msg" maxlength="500" placeholder="' + esc(t("提交信息（提交暂存区里的文件）")) + '"' + dis + ">" +
    '<button class="primary" onclick="gitWbCommit()"' + (!(d.staged || []).length || ro ? " disabled" : "") + ">" + t("提交") + "</button></div>";
  // 最近提交时间线
  if ((d.recent || []).length) {
    html += '<div class="gwb-log">' + d.recent.map((c) =>
      '<div class="gwb-lc"><code>' + esc(c.hash) + '</code><span class="p">' + esc(c.subject) + "</span>" +
      '<span class="gm">' + esc(c.author) + " · " + esc(c.age) + "</span></div>").join("") + "</div>";
  }
  // 任务分支隔离区（沿用快照面板的裁决按钮）
  const iso = d.isolation || {};
  if (iso.rev && !iso.state) {
    html += '<div class="hint">' + esc(t("已配置代码版本隔离，但任务分支尚未创建（检出失败见运行错误）。")) + "</div>";
  } else if (iso.state === "isolated") {
    html += '<div class="git-meta"><span>' + esc(t("任务分支")) + " <b>codebee/" + esc(tid) + "</b></span>" +
      '<span class="chip isolated">' + t("待裁决") + "</span></div>";
    if (!ro) {
      html += '<div class="git-actions">' +
        '<button class="primary" onclick="gitMerge(\'' + jsq(tid) + "')\">" +
        '<svg class="ico" aria-hidden="true"><use href="#i-check"></use></svg>' + t("合并回原分支") + "</button>" +
        '<button class="danger ghost" onclick="gitDiscard(\'' + jsq(tid) + "')\">" +
        '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg>' + t("丢弃分支") + "</button>" +
        '<span class="hint">' + esc(t("合并＝采纳产物回原分支；丢弃＝删除任务分支（不可恢复）。")) + "</span></div>";
    }
  } else if (iso.state) {
    const chip = GIT_STATE_CHIP[iso.state] || ["muted", "—"];
    html += '<div class="git-meta"><span>' + esc(t("任务分支")) + " <b>codebee/" + esc(tid) + "</b></span>" +
      '<span class="chip ' + chip[0] + '">' + t(chip[1]) + "</span></div>";
  }
  box.classList.remove("hidden");
  box.innerHTML = html;
  const bs = box.querySelector("#gwb-branch");
  if (bs) bs.addEventListener("change", () => { if (bs.value) window.gitWbCheckout(bs.value); });
  const mi = box.querySelector("#gwb-msg");
  if (mi) {
    if (prevMsg) mi.value = prevMsg;   // 轮询重画不丢用户正在写的提交信息
    mi.addEventListener("keydown", (e) => { if (e.key === "Enter") window.gitWbCommit(); });
  }
  rdTabsSync();   // 版本面板显隐决定「版本」标签可用性
}

/* 工作台单文件实时 diff：点击文件行即弹（读工作区，运行中也能看最新状态） */
window.gitWbDiff = async function (path) {
  const key = detailSideTaskKey();
  if (!key || !path) return;
  _fpSaveCtx = null; _fpRawText = ""; _fpDirty = false; _fpCopyText = null;   // 复用单例弹窗，别带上一个文件的编辑态
  _fpOpen(String(path).split("/").pop(), "",
    '<button class="ghost" onclick="copyFPText()">' + esc(t("复制")) + "</button>");
  let d;
  try { d = await api("/api/tasks/" + encodeURIComponent(key) + "/git/diff?path=" + encodeURIComponent(path)); }
  catch (e) { _fpSetBody('<div class="fp-hint">' + esc(t("diff 读取失败：") + e.message) + "</div>"); return; }
  if (!filePopIsOpen()) return;   // 读取期间被 Esc 关掉：别把内容又糊上去
  const lines = String(d.diff || "").split("\n");
  _fpCopyText = (d.diff && lines.length) ? lines.join("\n") : "";   // 复制给 diff 原文，行号槽不进剪贴板
  _fpSetBody((d.diff && lines.length)
    ? '<div class="fp-diff">' + lines.map((ln, i) => _fpDiffLine(ln, i + 1)).join("") + "</div>"
    : '<div class="fp-hint">' + esc(t("该文件当前没有未提交的变更。")) + "</div>");
};

async function _gitWbPost(action, params, okMsg) {
  const key = detailSideTaskKey();
  if (!key) return null;
  let res = null;
  try {
    res = await api("/api/tasks/" + encodeURIComponent(key) + "/git",
      { method: "POST", body: JSON.stringify(Object.assign({ action }, params || {})) });
    if (okMsg) toast(typeof okMsg === "function" ? okMsg(res || {}) : okMsg);
  } catch (e) { toast(e.message, true); }
  loadGitWb(true);   // 成败都立即重拉：失败信息已在 toast，列表反映真实状态
  return res;
}

window.gitWbStage = function (p) { return _gitWbPost("stage", { path: p }); };
window.gitWbUnstage = function (p) { return _gitWbPost("unstage", { path: p }); };
window.gitWbStageAll = function () { return _gitWbPost("stage_all", null, t("已暂存全部变更")); };
window.gitWbFetch = function () { return _gitWbPost("fetch", null, t("已抓取远程更新")); };
window.gitWbPull = function () { return _gitWbPost("pull", null, t("已拉取远程更新")); };
window.gitWbPush = function () { return _gitWbPost("push", null, t("已推送到远程")); };
window.gitWbPrCreate = async function () {
  // 提交信息框有字时兼作 PR 标题（一处输入两用，不为 PR 单开输入框）
  const mt = ((($("gwb-msg") || {}).value || "").trim());
  const q = mt
    ? t("把当前分支推送到远程并用 gh 创建 PR？（目标分支自动取 main/master；提交信息框内容将作为 PR 标题）")
    : t("把当前分支推送到远程并用 gh 创建 PR？（目标分支自动取 main/master）");
  if (!await uiConfirm(q, { ok: t("建 PR") })) return null;
  const res = await _gitWbPost("pr_create", mt ? { title: mt.slice(0, 120) } : null,
    (r) => (r && r.url ? t("PR 已创建：") + r.url : t("PR 已创建")));
  if (res && res.url) window.open(res.url, "_blank", "noopener");
  return res;
};
window.gitWbCheckout = function (br) {
  if (!br) return;
  return _gitWbPost("checkout", { branch: br }, t("已切换到 ") + br);
};
window.gitWbDiscard = async function (p) {
  if (!await uiConfirm(t("丢弃该文件的全部未提交改动？此操作不可恢复。"), { ok: t("丢弃"), danger: true })) return;
  return _gitWbPost("discard", { path: p, confirm: true });
};
window.gitWbDelete = async function (p) {
  if (!await uiConfirm(t("删除这个未跟踪文件？此操作不可恢复。"), { ok: t("删除"), danger: true })) return;
  return _gitWbPost("delete", { path: p, confirm: true });
};
window.gitWbStash = function () { return _gitWbPost("stash_push", null, t("未提交改动已收进 stash")); };
window.gitWbStashPop = function (ref) { return _gitWbPost("stash_pop", { ref }, t("已还原 stash 改动")); };
window.gitWbStashDrop = async function (ref) {
  if (!await uiConfirm(t("删除这条 stash？收起的改动将永久丢弃。"), { ok: t("删除"), danger: true })) return;
  return _gitWbPost("stash_drop", { ref, confirm: true });
};
window.gitWbCommit = async function () {
  const msg = (($("gwb-msg") || {}).value || "").trim();
  if (!msg) { toast(t("请先填写提交信息"), true); return; }
  const d = await _gitWbPost("commit", { message: msg },
    (r) => t("已提交 ") + (r.files || 0) + t(" 个文件 → ") + (r.commit || ""));
  if (d && $("gwb-msg")) $("gwb-msg").value = "";
};

async function _gitVerdictDone() {
  poll();
  S.gitWbAt = 0;            // 工作台缓存作废：裁决改了 git_state，5s 节流内也要立刻重拉
  if (S.detailTaskKey) { S.taskSig = ""; renderTaskDetail(); }
  else if (S.detailRunId) renderRunDetail();
  refreshDetailSide(true);  // 裁决改变 git_state：立即重拉任务级数据重画面板
  refreshInspector(true);   // 检查器开着时同步裁决结果
}

window.gitMerge = async function (taskId) {
  if (!await uiConfirm(t("把任务分支的产物合并回原分支？"), { ok: t("合并") })) return;
  try {
    const d = await api("/api/tasks/" + encodeURIComponent(taskId) + "/git-merge", { method: "POST" });
    toast(t("已合并：") + Number(d.commits || 0) + " " + t("个提交 → ") + (d.merged_into || ""));
    if (d.restore_error) toast(t("合并成功，但你之前的未提交改动没能自动还原，") + d.restore_error, true);
    await _gitVerdictDone();
  } catch (e) { toast(t("合并失败：") + e.message, true); }
};

window.gitDiscard = async function (taskId) {
  if (!await uiConfirm(t("丢弃任务分支？该分支上的产物将永久删除，不可恢复。"), { ok: t("丢弃"), danger: true })) return;
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/git-discard", { method: "POST", body: JSON.stringify({ confirm: true }) });
    toast(t("已丢弃任务分支"));
    await _gitVerdictDone();
  } catch (e) { toast(t("丢弃失败：") + e.message, true); }
};

/* ------------------------------------------------- 任务检查器（右缘停靠列）
 * 参考桌面端的 Git 工具 + 进程浮窗：顶栏「任务详情」按钮开合（点任务树的任务行
 * 现在主栏直开任务级详情，检查器入口收拢到按钮/刷新恢复），
 * 五张卡——Git 工具（分支 + +/- 统计 + 变更清单 + 合并/丢弃裁决）、进度
 * （x/y 步 + 状态点清单）、运行统计、成品文件快捷区、迷你指挥区。
 * 数据走 /api/tasks/<id>/side（KB 级、可轮询、无 diff 文本）；主视图不动，
 * 步骤点进主栏详情的旧路径原样保留。 */
let inspRunId = null;   // 迷你指挥区指向的活跃 run

/* 检查器准入：任务「跑过」才有得看——task_latest 全量下发，没有记录或最新 run
 * 还在排队（刚建的新任务/重试排在后面）都算没跑过，右缘不滑出。 */
function inspEligible(key) {
  const lr = ((S.state || {}).task_latest || {})[key];
  return !!lr && lr.status !== "queued";
}

window.openInspector = function (key) {
  if (!key) return;
  if (!((S.state || {}).tasks || []).some((x) => x.id === key)) return;   // 无主运行不进检查器
  if (!inspEligible(key)) return;   // 还没跑过的新任务不滑出：Git/进度/成品全空，弹出来只有噪声
  if (S.inspKey !== key) { S.inspSig = ""; inspRunId = null; }
  S.inspKey = key;
  S.inspAt = 0;                      // 换任务立刻拉一次
  document.body.classList.add("inspector-open");
  $("inspector").classList.remove("hidden");
  syncInspBtn();
  try { localStorage.setItem("orch.inspector", key); } catch (e) { /* 存储不可用则不记忆 */ }
  refreshInspector(true);
};

window.closeInspector = function () {
  document.body.classList.remove("inspector-open");
  $("inspector").classList.add("hidden");
  S.inspKey = null;
  S.inspData = null;
  S.inspSig = "";
  syncInspBtn();
  try { localStorage.removeItem("orch.inspector"); } catch (e) { /* ignore */ }
};

/* 顶栏「任务详情」开合按钮：开着显示 ‹（收起）、关着显示 ›（展开）——箭头方向
 * 靠 CSS 变量穿透 use 影子树翻转，这里只同步悬浮提示。 */
function syncInspBtn() {
  const b = $("btn-insp");
  if (!b) return;
  const detailOpen = !!($("run-detail") && !$("run-detail").classList.contains("hidden"));
  const inTaskWorkspace = !document.body.classList.contains("settings-mode") && !S.mainPage && !detailOpen;
  b.classList.toggle("hidden", !inTaskWorkspace);
  const tip = document.body.classList.contains("inspector-open") ? t("收起任务详情") : t("打开任务详情");
  b.title = tip;
  b.setAttribute("aria-label", tip);
}

function syncRailState() {
  const buttons = Array.from(document.querySelectorAll(".side-rail .rail-btn"));
  buttons.forEach((b) => b.classList.remove("active"));
  if (!buttons.length) return;
  if (document.body.classList.contains("settings-mode")) {
    buttons[buttons.length - 1].classList.add("active");
    return;
  }
  const page = S.mainPage || S.tab;
  const index = page === "runs" ? 1 : page === "automation" ? 2 : page === "browser" ? 3 : 0;
  (buttons[index] || buttons[0]).classList.add("active");
}

/* 手动开合检查器。没选中过任务时兜底拿最近一个跑过的（树序即最新在前），
 * 一个都没有才提示；选中过但已失效（被删）同样落到兜底。 */
window.toggleInspector = function () {
  if (document.body.classList.contains("inspector-open")) { closeInspector(); return; }
  const tasks = ((S.state || {}).tasks || []);
  const ok = (k) => !!k && tasks.some((x) => x.id === k) && inspEligible(k);
  const key = ok(S.inspKey) ? S.inspKey : (tasks.find((x) => ok(x.id)) || {}).id;
  if (!key) { toast(t("还没有可展示的任务详情"), true); return; }
  openInspector(key);
};

/* 检查器只属于「列表快捷预览」上下文：设置子页、快捷导航页、新建表单、运行/任务详情一律收起。
 * 详情页已铺开全部信息（蜂巢/步骤/成果/版本/圣经/指挥），检查器留着只会同屏
 * 出现两份标题/成品/Git——让它让位，但不丢选中，回到列表上下文自动滑回 */
function syncInspectorVis() {
  const insp = $("inspector");
  if (!insp) return;
  syncInspBtn();
  // 兜底只认「run 记录全部没了」（清理/删除）：排空档不动已开着的检查器，
  // 否则自动续跑的 run 间隙（done→queued→running）会闪关
  const runsGone = S.state && S.inspKey && !((S.state.task_latest || {})[S.inspKey]);
  // 主视图下正在看「要完成什么？」新建表单：不是任务上下文，不自动滑出。
  // （本函数只在模式切换时调用，不在轮询里——用户在表单页手动点树里的任务，
  //   openInspector 直接开，不会被这里关掉）
  const onComposer = !S.mainPage && !document.body.classList.contains("settings-mode") &&
    !$("sub-tasks").classList.contains("hidden");
  // 主栏正开着运行/任务详情：详情页是全功能视图，检查器同屏只会重复
  const onDetail = !$("run-detail").classList.contains("hidden");
  // 主栏停在快捷导航页（概览/运行记录/自动化）：同设置子页，检查器让位不抢版面
  if (document.body.classList.contains("settings-mode") || S.mainPage || onComposer || onDetail ||
      !S.inspKey || runsGone) {
    document.body.classList.remove("inspector-open");
    insp.classList.add("hidden");
    return;                      // 隐藏态不轮询，refreshInspector 的闸门在 body 类上
  }
  document.body.classList.add("inspector-open");
  insp.classList.remove("hidden");
  refreshInspector(true);
}

/* 刷新/重开后恢复最近打开的任务对话（用户拍板 1013：返回对话默认加载到最新）。
 * 任务已被删或已归档则保持关闭。只在首帧 state 到达时尝试一次（SSE 后续帧不再动）。 */
function restoreLastTask() {
  if (S.lastTaskRestored) return;
  S.lastTaskRestored = true;
  let key = "";
  try { key = localStorage.getItem("orch.lastTask") || ""; } catch (e) { return; }
  if (key && ((S.state || {}).tasks || []).some((x) => x.id === key)) {
    sideOpenTask(key);
  }
}

/* 刷新后恢复检查器：回到上次打开的任务（任务已被删则保持关闭）。
 * 首帧 state 到达时任务清单才可信，所以挂在这里而不是 DOMContentLoaded。 */
function restoreInspector() {
  if (document.body.classList.contains("inspector-open")) return;
  let key = "";
  try { key = localStorage.getItem("orch.inspector") || ""; } catch (e) { /* ignore */ }
  if (key && ((S.state || {}).tasks || []).some((x) => x.id === key)) {
    S.inspKey = key;             // 只记选中，显不显示交给 syncInspectorVis——
    syncInspectorVis();          // 刷新时停在设置子页或新建表单就不滑出
  }
}

/* 节流拉取：SSE 唤醒的 render() 每次都调，2s 内只发一次请求 */
async function refreshInspector(force) {
  if (!document.body.classList.contains("inspector-open") || !S.inspKey) return;
  const now = Date.now();
  if (!force && now - (S.inspAt || 0) < 2000) return;
  S.inspAt = now;
  const key = S.inspKey;
  let d;
  try { d = await api("/api/tasks/" + encodeURIComponent(key) + "/side"); }
  catch (e) { return; }              // 拉取失败静默，等下一轮节流重试
  if (!S.inspKey || S.inspKey !== key) return;   // 期间已切走/收起：过期响应不落盘
  S.inspData = d;
  drawInspector();
}

/* 签名没变不重画；指挥区输入中跳过整帧重绘——整块重绘会把正在打的字弹掉 */
function drawInspector() {
  const d = S.inspData;
  if (!d || !d.task) return;
  // 已收起（详情页让位/用户关闭）就整帧不落盘：在途响应回来时用户多半已切到
  // 别的详情，落盘只会让 loadArtifacts 等渲染面拿到别人任务的 run（串台源头）
  if (!document.body.classList.contains("inspector-open")) return;
  const ta = $("insp-msg-input");
  if (ta && document.activeElement === ta) return;
  const sig = JSON.stringify([
    S.inspKey, d.task.status, d.task.git_state, d.run && d.run.status,
    d.progress, (d.steps || []).map((s) => [s.n, s.status, s.summary]),
    d.changes.count, d.changes.add_total, d.changes.del_total,
    (d.changes.files || []).map((f) => [f.path, f.add, f.del]),
    (d.files || []).map((f) => f.name),
  ]);
  if (sig === S.inspSig) return;
  S.inspSig = sig;
  $("insp-title").textContent = d.task.title || d.task.id;
  $("insp-title").title = d.task.workdir || "";
  const runId = (d.run || {}).id || "";
  inspRunId = (d.run && (d.run.status === "running" || d.run.status === "queued")) ? runId : null;

  /* —— Git 工具卡 —— */
  const chipEl = $("insp-git-chip");
  const g = d.git || {};
  const main = $("insp-git-main");
  const boxDiff = $("insp-diff");
  if (!g.branch) {
    // 没有任务分支：区分「没启用」和「启用了但检出失败」——后者要给出错原因，
    // 不能误报成"该任务未指定代码版本"
    const revChosen = (d.task || {}).git_rev || "";
    const lastErr = ((d.run || {}).error || "");
    if (revChosen) {
      chipEl.className = "chip failed"; chipEl.textContent = t("检出失败"); chipEl.classList.remove("hidden");
      main.innerHTML = '<div class="insp-branch"><code>codebee/' + esc(d.task.id || "") +
        t("（") + esc(t("未创建")) + t("）") + '</code></div>' +
        (lastErr ? '<div class="hint warn">' + esc(lastErr) + "</div>" : "") +
        '<span class="insp-hint">' + esc(t("处理后点「继续任务」，运行会重新检出任务分支。")) + "</span>";
    } else {
      // 没指定代码版本：没有任务分支，卡里只留一句说明
      chipEl.classList.add("hidden");
      main.innerHTML = '<span class="insp-hint">' + esc(t("未启用代码版本隔离（该任务未指定代码版本）。")) + "</span>";
    }
  } else {
    const chip = GIT_STATE_CHIP[g.state] || (g.state ? [g.state, g.state] : null);
    if (chip) { chipEl.className = "chip " + chip[0]; chipEl.textContent = t(chip[1]); chipEl.classList.remove("hidden"); }
    else chipEl.classList.add("hidden");
    let html = '<div class="insp-branch">' +
      '<code title="' + esc(t("任务分支：产物提交在此，原分支未受影响")) + '">' + esc(g.branch) + "</code>";
    // +/- 行级统计：运行中实时、结束后快照；旧 run 没有统计字段显示 —
    const addT = d.changes.add_total, delT = d.changes.del_total;
    if (addT != null && delT != null) {
      html += '<span class="insp-plus">+' + addT + "</span><span class=\"insp-minus\">-" + delT + "</span>";
    }
    html += "</div>";
    html += '<div class="git-meta"><span>' + esc(t("基线")) + " <b>" + esc(g.rev || "-") + "</b> → " + esc(g.from_branch || "-") + "</span>" +
      (g.commit ? "<span>" + esc(t("分支提交")) + " <b>" + esc(g.commit) + "</b></span>" : "") + "</div>";
    if (g.restore_error) html += '<div class="hint warn">' + esc(t("收尾出错：")) + esc(g.restore_error) + "</div>";
    const cfs = d.changes.files || [];
    html += '<div class="insp-changes">' + (cfs.length
      ? cfs.map((f) =>
          '<button class="insp-cf" onclick="inspDiffFile(this.dataset.p)" ondblclick="fileDiffPopup(this.dataset.p)" data-p="' + esc(f.path) + '" title="' +
          esc(t("单击：卡内展开 diff；双击：弹窗查看")) + '">' +
          '<i class="gs ' + (f.status === "M" ? "m" : f.status === "D" ? "d" : "n") + '">' + esc(gitStatusLabel(f.status)) + "</i>" +
          '<span class="p">' + esc(f.path) + "</span>" +
          (f.add ? '<span class="add">+' + f.add + "</span>" : "") +
          (f.del ? '<span class="del">-' + f.del + "</span>" : "") + "</button>").join("")
      : '<span class="insp-hint">' + esc(t("暂无工作区变更。")) + "</span>") + "</div>";
    const canVerdict = g.state === "isolated" && d.task.status !== "running" && d.task.status !== "queued";
    html += '<div class="insp-actions"' + (canVerdict ? "" : ' style="display:none"') + ">" +
      '<button class="primary small" onclick="gitMerge(\'' + jsq(d.task.id) + "')\">" +
      '<svg class="ico" aria-hidden="true"><use href="#i-check"></use></svg>' + t("合并回原分支") + "</button>" +
      '<button class="danger ghost small" onclick="gitDiscard(\'' + jsq(d.task.id) + "')\">" +
      '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg>' + t("丢弃分支") + "</button></div>";
    main.innerHTML = html;
    if (boxDiff.dataset.run !== runId) { boxDiff.classList.add("hidden"); boxDiff.dataset.run = runId; }
  }
  /* —— 徽标 + 自动选 TAB（用户手点后同状态内不再抢）——
   * 规则：运行/排队 → 进度（盯着跑）；待裁决 → Git（该裁断了）；完成有产物 → 成品；其余 → 进度。
   * 状态没变就不动用户当前所在分区。 */
  const badgeGit = $("insp-badge-git"), badgeProg = $("insp-badge-progress"), badgeFiles = $("insp-badge-files");
  if (g.state === "isolated") { badgeGit.textContent = t("待裁决"); badgeGit.className = "insp-badge verdict"; badgeGit.classList.remove("hidden"); }
  else badgeGit.classList.add("hidden");
  badgeProg.textContent = ((d.progress || {}).done || 0) + "/" + ((d.progress || {}).total || 0);
  badgeProg.classList.toggle("hidden", !((d.progress || {}).total || 0));
  if (badgeFiles) {
    badgeFiles.textContent = String((d.files || []).length);
    badgeFiles.classList.toggle("hidden", !(d.files || []).length);
  }
  const autoSig = S.inspKey + "|" + ((d.run || {}).status || "none") + "|" + g.state;
  if (S.inspAutoSig !== autoSig) {
    S.inspAutoSig = autoSig;
    const active = d.run && (d.run.status === "running" || d.run.status === "queued");
    S.inspTab = active ? "progress"
      : (g.state === "isolated" ? "git"
      : ((d.files || []).length ? "files" : "progress"));
  }
  applyInspectorTab();
  loadArtifacts(runId);   // 成品 TAB：工作目录新产出（运行中轮询刷新文件列表）

  /* —— 进度分区：环形进度 + 步骤清单 —— */
  const pr = d.progress || {};
  $("insp-progress-n").textContent = (pr.done || 0) + "/" + (pr.total || 0);
  // 环只改 attribute 不重建 DOM：CSS transition 接管，推进时平滑生长
  const ring = $("insp-ring");
  if (ring) {
    const C = 226.2;
    const pct = (pr.total || 0) ? (pr.done || 0) / pr.total : 0;
    ring.style.strokeDashoffset = String(C * (1 - Math.min(1, Math.max(0, pct))));
  }
  $("insp-steps").innerHTML = (d.steps || []).map((s) =>
    '<button class="insp-step ' + esc(s.status || "") + '" onclick="sideOpenRun(\'' + jsq(runId) + "', " + (Number(s.n) || 0) + ')" title="' +
    esc(verdictDigestText(s.summary) || s.summary || "") + '">' +
    '<span class="sdot ' + esc(s.status || "") + '"></span>' +
    '<span class="role">' + esc(s.role || "") + "</span>" +
    '<span class="sum">' + esc(verdictDigestText(s.summary) || s.summary || s.note || "") + "</span>" +
    '<span class="dur">' + (s.duration_s != null ? s.duration_s + "s" : "") + "</span></button>"
  ).join("") || '<span class="insp-hint">' + esc(t("尚无步骤")) + "</span>";

  /* —— 统计条（常驻，不占分区；件数在成品 TAB 徽标上，不重复）—— */
  const st = d.stats || {};
  $("insp-stats").innerHTML =
    "<span>" + esc(t("运行")) + " <b>" + (st.runs || 0) + "</b></span>" +
    "<span>" + esc(t("步骤")) + " <b>" + (st.steps || 0) + "</b></span>" +
    "<span>" + esc(t("成本")) + " <b>$" + (Number(st.cost_usd) || 0).toFixed(3) + "</b></span>" +
    "<span>tokens <b>" + (st.tokens || 0) + "</b></span>";

  /* —— 成品文件分区（主栏详情不再展示，这里是唯一入口）——
   * 与 Git 变更清单同款行样式：扩展名徽标 + 文件名 + 右侧大小；点开弹内容 */
  const arts = d.files || [];
  const artBox = $("insp-artifacts");
  if (artBox) artBox.innerHTML = arts.length
    ? arts.map((f) =>
        '<a class="file-chip" href="' + urlAuth("/api/runs/" + encodeURIComponent(runId) + "/file?name=" +
        encodeURIComponent(f.name)) + '" target="_blank" rel="noopener" title="' +
        esc(f.name + " · " + fmtSize(f.size)) + '" data-file-run="' + esc(runId) +
        '" data-file-name="' + esc(f.name) + '" data-file-size="' + (Number(f.size) || 0) + '">' +
        '<i class="fx">' + esc(_crFileBadge(f.name)) + "</i>" +
        '<span class="p">' + esc(f.name) + "</span><i>" + fmtSize(f.size) + "</i></a>").join("")
    : '<span class="insp-hint">' + esc(t("本次运行没有在工作目录里产出新文件。")) + "</span>";

  /* —— 迷你指挥区：仅活跃 run 显示 —— */
  $("insp-card-direct").classList.toggle("hidden", !inspRunId);
}

/* 变更清单点开单文件 diff：从该 run 的 changes.diff 按文件头切片（零后端开销）。
 * 运行中的 run 还没落 changes 快照，提示结束后可看。
 * 双击同一行 → fileDiffPopup 弹大窗（行着色、可复制），小窗仍在原位。 */
function _sliceDiff(diff, path) {
  const lines = String(diff || "").split("\n");
  const out = [];
  let take = false;
  for (const ln of lines) {
    if (ln.indexOf("diff --git ") === 0) take = ln.indexOf(" b/" + path) >= 0;
    if (take) out.push(ln);
  }
  return out;
}

window.inspDiffFile = async function (path) {
  const box = $("insp-diff");
  const runId = (S.inspData || {}).run && S.inspData.run.id;
  if (!box || !runId) return;
  if (!box.classList.contains("hidden") && box.dataset.path === path) { box.classList.add("hidden"); return; }
  let d;
  try { d = await api("/api/runs/" + encodeURIComponent(runId)); }
  catch (e) { toast(t("diff 读取失败：") + e.message, true); return; }
  const diff = ((d.run || {}).changes || {}).diff || "";
  box.dataset.path = path;
  box.textContent = _sliceDiff(diff, path).join("\n") ||
    t("暂无该文件的已保存 diff（运行结束后生成变更快照，或该运行没有保存变更内容）。");
  box.classList.remove("hidden");
};

/* ------------------------------------------------- 文件内容弹窗（单例）
 * 两个入口共用：Git 变更行双击 → 该文件的 diff（行着色）；成品文件点开 →
 * 内容预览（md 渲染 / 代码等宽 / 图片直显 / 二进制给下载）。
 * z-index 240：高于主 modal(200)、低于 #ask(250)——弹窗上再弹确认不遮眼。 */
let _fpUrls = [];   // 图片预览的 objectURL，关窗统一回收
/* 编辑态：_fpRawText=开窗时取到的原文（json 展示会美化，编辑始终用原文）；
 * _fpSaveCtx={dir,name,mtime} 非空=该弹窗可编辑（目录文件弹窗专属，成品只读）；
 * _fpDirty=编辑框有改动未保存——关窗/退出编辑先确认，防误丢；
 * _fpCopyText=复制按钮要吐的原文（正文是行号表格，innerText 会连行号列一起带出）；
 * null=非文本内容，回退 innerText。 */
let _fpRawText = "", _fpSaveCtx = null, _fpDirty = false, _fpCopyText = null;

function filePopIsOpen() {
  const el = document.getElementById("file-pop");
  return !!el && !el.classList.contains("hidden");
}

window.filePopClose = async function () {
  const el = document.getElementById("file-pop");
  if (!el) return;
  if (_fpDirty) {
    const ok = await uiConfirm(t("有未保存的修改，确定关闭？"));
    if (!ok) return;
  }
  _fpDirty = false; _fpSaveCtx = null; _fpRawText = ""; _fpCopyText = null;
  el.classList.add("hidden");
  el.querySelector(".fp-body").innerHTML = "";
  el.querySelector(".fp-acts").innerHTML = "";
  _fpUrls.forEach((u) => { try { URL.revokeObjectURL(u); } catch (e) { /* 回收失败忽略 */ } });
  _fpUrls = [];
};

function _fpEnsure() {
  let el = document.getElementById("file-pop");
  if (el) return el;
  el = document.createElement("div");
  el.id = "file-pop";
  el.innerHTML = '<div class="fp-panel" role="dialog" aria-modal="true">' +
    '<div class="fp-head"><code class="fp-title"></code><span class="fp-sub"></span><span class="fp-flex"></span>' +
    '<span class="fp-acts"></span>' +
    '<button class="ghost fp-x" title="' + esc(t("关闭")) + ' (Esc)"><svg class="ico" aria-hidden="true"><use href="#i-x"/></svg></button></div>' +
    '<div class="fp-body"></div></div>';
  document.body.appendChild(el);
  el.addEventListener("click", (e) => { if (e.target === el) window.filePopClose(); });
  el.querySelector(".fp-x").addEventListener("click", window.filePopClose);
  // 编辑模式下 Ctrl/Cmd+S = 保存（拦掉浏览器默认的「保存网页」）
  el.addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && (e.key === "s" || e.key === "S")) {
      const ta = el.querySelector(".fp-edit");
      if (ta && !ta.classList.contains("hidden")) { e.preventDefault(); window.fpSaveEdit(); }
    }
  });
  return el;
}

/* 开窗骨架：标题 + 副信息（±行数/大小）+ 动作按钮，正文先放加载态 */
function _fpOpen(title, sub, acts) {
  const el = _fpEnsure();
  el.querySelector(".fp-title").textContent = title;
  el.querySelector(".fp-sub").innerHTML = sub || "";
  el.querySelector(".fp-acts").innerHTML = acts || "";
  el.querySelector(".fp-body").innerHTML = '<div class="fp-hint">' + esc(t("加载中…")) + "</div>";
  el.classList.remove("hidden");
  return el;
}

function _fpSetBody(html) {
  const el = _fpEnsure();
  el.querySelector(".fp-body").innerHTML = html;
}

/* 复制源：文本类正文优先给预留原文（不带行号/着色槽），其余回退 innerText */
window.fpCopySource = function () {
  const body = document.querySelector("#file-pop .fp-body");
  if (!body) return "";
  return _fpCopyText !== null ? _fpCopyText : (body.innerText || "");
};

window.copyFPText = function () {
  try { navigator.clipboard.writeText(window.fpCopySource() || ""); toast(t("已复制")); } catch (e) { /* 剪贴板不可用则忽略 */ }
};

/* diff 行着色：+/− 上色、@@ 小节、头部落灰；"--- "/"+++ " 先判，避免内容行误染。
 * no 传行序号：开着「显示行号」时前置一个行号槽（diff 的行号 = 文件切片内序号，
 * 与 hunk 头的源行号不严格对应，仅作定位参考）。 */
function _fpDiffLine(ln, no) {
  const cls = (ln.indexOf("diff --git ") === 0 || ln.indexOf("index ") === 0 ||
    ln.indexOf("--- ") === 0 || ln.indexOf("+++ ") === 0 || ln.indexOf("old mode") === 0 ||
    ln.indexOf("new mode") === 0 || ln.indexOf("new file") === 0 || ln.indexOf("deleted file") === 0 ||
    ln.indexOf("rename ") === 0 || ln.indexOf("similarity ") === 0 || ln.indexOf("\\ No newline") === 0)
    ? "fp-meta" : (ln.indexOf("@@") === 0) ? "fp-hunk"
    : (ln.indexOf("+") === 0) ? "fp-add" : (ln.indexOf("-") === 0) ? "fp-del" : "";
  const noHtml = (codeLineNum() && no) ? '<span class="fp-no">' + no + "</span>" : "";
  return '<div class="fp-ln ' + cls + '">' + noHtml + esc(ln.length ? ln : " ") + "</div>";
}

/* Git 变更行双击：弹窗展示该文件的完整 diff。runId 可显式传（主栏 Git 面板），
 * 不传则按 检查器 → 主栏详情 → 最近 run 的顺序兜底。 */
window.fileDiffPopup = async function (path, runId) {
  runId = runId || ((S.inspData || {}).run || {}).id || S.detailRunId || (S.lastRun || {}).id || "";
  if (!runId) return;
  _fpSaveCtx = null; _fpRawText = ""; _fpDirty = false; _fpCopyText = null;   // diff 弹窗只读，别带上一个目录文件的编辑态
  let sub = "";
  for (const fs of [((S.inspData || {}).changes || {}).files, ((S.lastRun || {}).changes || {}).files]) {
    const f = (fs || []).find((x) => x.path === path);
    if (f) { sub = '<span class="insp-plus">+' + (f.add || 0) + '</span><span class="insp-minus">-' + (f.del || 0) + "</span>"; break; }
  }
  _fpOpen(path, sub, '<button class="ghost" onclick="copyFPText()">' + esc(t("复制")) + "</button>");
  let d;
  try { d = await api("/api/runs/" + encodeURIComponent(runId)); }
  catch (e) { _fpSetBody('<div class="fp-hint">' + esc(t("diff 读取失败：") + e.message) + "</div>"); return; }
  if (!filePopIsOpen()) return;   // 读取期间被 Esc 关掉：别把内容又糊上去
  const lines = _sliceDiff(((d.run || {}).changes || {}).diff || "", path);
  _fpCopyText = lines.length ? lines.join("\n") : "";   // 复制给切片原文，行号槽(.fp-no)不进剪贴板
  _fpSetBody(lines.length
    ? '<div class="fp-diff">' + lines.map((ln, idx) => _fpDiffLine(ln, idx + 1)).join("") + "</div>"
    : '<div class="fp-hint">' + esc(t("暂无该文件的已保存 diff（运行结束后生成变更快照，或该运行没有保存变更内容）。")) + "</div>");
};

const FP_IMG = new Set(["png", "jpg", "jpeg", "gif", "webp", "bmp", "ico", "svg", "avif"]);
const FP_TXT = new Set(["md", "txt", "log", "csv", "yml", "yaml", "ini", "toml", "json",
  "py", "js", "ts", "jsx", "tsx", "html", "htm", "css", "svg", "bat", "sh", "ps1",
  "c", "h", "cpp", "hpp", "java", "go", "rs", "xml", "sql", "mqtt", "proto"]);
const FP_DOCX = new Set(["docx"]);   // 只认 OOXML；legacy .doc 二进制不在此列
const FP_PDF = new Set(["pdf"]);
const FP_XLSX = new Set(["xlsx"]);   // 只认 OOXML；legacy .xls 二进制不在此列
// 媒体成品：video/audio 标签原生播放（与后端 /preview、/file 的媒体白名单同口径）
const FP_MEDIA_VIDEO = new Set(["mp4", "m4v", "mov", "webm", "ogv"]);
const FP_MEDIA = new Set([...FP_MEDIA_VIDEO, "mp3", "m4a", "wav", "ogg"]);
// 详情页预览页签里浏览器原生可渲染的成品（不走 codeBlockHTML 的集合）：
// 媒体播放器 / 图片直显 / PDF 交给内置阅读器——二进制当文本渲染就是乱码墙
const FP_IMG_PV = new Set(["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg", "ico", "avif"]);
const FP_NATIVE_PV = new Set([...FP_MEDIA, ...FP_IMG_PV, "pdf"]);

/* 媒体播放器（弹窗与详情页页签共用）：src 由调用方给完整已鉴权地址。
 * 不自动播——弹窗里突然出声是惊吓；preload=metadata 只拉时长不整包下载。 */
function fpMediaHTML(url, isVideo) {
  const tag = isVideo ? "video" : "audio";
  return '<div class="fp-media"><' + tag + ' controls preload="metadata" src="' + url + '"></' + tag + "></div>";
}

function _fpExt(name) { return (String(name).split(".").pop() || "").toLowerCase(); }

/* docx 只读预览（试探功能）：渲染器走 jsdelivr 懒加载（docx-preview 依赖
 * JSZip，两者只在首次打开 docx 时加载，平时零请求零开销）；加载/渲染失败
 * 优雅回落到下载提示。渲染内容是用户自己工作目录的文件，信任面与网页成品
 * 预览页签一致。版本钉死，升级要走一次人工验证。 */
let _docxLibs = null;
function _loadDocxLibs() {
  if (_docxLibs) return _docxLibs;
  const load = (src) => new Promise((res, rej) => {
    const s = document.createElement("script");
    s.src = src; s.onload = () => res(); s.onerror = () => rej(new Error("load fail: " + src));
    document.head.appendChild(s);
  });
  _docxLibs = Promise.all([
    load("https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js"),
    load("https://cdn.jsdelivr.net/npm/docx-preview@0.4.1/dist/docx-preview.min.js"),
  ]).then(() => {
    if (!window.docx || !window.JSZip) throw new Error(t("docx 渲染器未就绪"));
  });
  _docxLibs.catch(() => { _docxLibs = null; });   // 失败不缓存，下次打开可重试
  return _docxLibs;
}

async function _fpRenderDocx(url) {
  const el = _fpEnsure();
  try {
    const [r] = await Promise.all([fetch(url), _loadDocxLibs()]);
    if (!r.ok) throw new Error("HTTP " + r.status);
    if (!filePopIsOpen()) return;
    _fpSetBody('<div class="fp-docx"><div class="fp-docx-load">' + esc(t("渲染中…")) + "</div></div>");
    const box = el.querySelector(".fp-docx");
    await window.docx.renderAsync(await r.arrayBuffer(), box, null, { inWrapper: true });
    if (!filePopIsOpen()) return;
    const loader = box.querySelector(".fp-docx-load");
    if (loader) loader.remove();
  } catch (e) {
    if (filePopIsOpen())
      _fpSetBody('<div class="fp-hint">' + esc(t("docx 预览不可用（渲染器需联网首次加载）；可下载后查看。")) + "</div>");
  }
}

/* PDF 只读预览（WorkDSH「真任务以可读产物收尾」切片）：pdf.js 走 jsdelivr
 * 懒加载，钉 3.11.174（最后带 UMD 构建的版本，4.x 转 ESM 不适用 script 注入）；
 * 渲染进 canvas，按弹窗宽度适配；大 PDF 封顶 20 页防渲染爆内存，超页给下载
 * 提示。加载/渲染失败优雅回落下载提示，与 docx 同款。 */
const FP_PDF_MAX_PAGES = 20;
let _pdfLib = null;
function _loadPdfLib() {
  if (_pdfLib) return _pdfLib;
  const base = "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/";
  const load = (src) => new Promise((res, rej) => {
    const s = document.createElement("script");
    s.src = src; s.onload = () => res(); s.onerror = () => rej(new Error("load fail: " + src));
    document.head.appendChild(s);
  });
  _pdfLib = load(base + "pdf.min.js").then(() => {
    if (!window.pdfjsLib) throw new Error(t("pdf 渲染器未就绪"));
    window.pdfjsLib.GlobalWorkerOptions.workerSrc = base + "pdf.worker.min.js";
  });
  _pdfLib.catch(() => { _pdfLib = null; });   // 失败不缓存，下次打开可重试
  return _pdfLib;
}

async function _fpRenderPdf(url) {
  const el = _fpEnsure();
  try {
    const [r] = await Promise.all([fetch(url), _loadPdfLib()]);
    if (!r.ok) throw new Error("HTTP " + r.status);
    if (!filePopIsOpen()) return;
    _fpSetBody('<div class="fp-pdf"><div class="fp-docx-load">' + esc(t("渲染中…")) + "</div></div>");
    const box = el.querySelector(".fp-pdf");
    const doc = await window.pdfjsLib.getDocument({ data: await r.arrayBuffer() }).promise;
    if (!filePopIsOpen()) return;
    const loader = box.querySelector(".fp-docx-load");
    if (loader) loader.remove();
    const total = doc.numPages;
    const width = Math.max(320, (box.clientWidth || 800) - 8);
    for (let i = 1; i <= Math.min(total, FP_PDF_MAX_PAGES); i++) {
      const page = await doc.getPage(i);
      if (!filePopIsOpen()) return;
      const vp1 = page.getViewport({ scale: width / page.getViewport({ scale: 1 }).width });
      const canvas = document.createElement("canvas");
      canvas.className = "fp-pdf-page";
      canvas.width = Math.floor(vp1.width); canvas.height = Math.floor(vp1.height);
      await page.render({ canvasContext: canvas.getContext("2d"), viewport: vp1 }).promise;
      box.appendChild(canvas);
    }
    if (total > FP_PDF_MAX_PAGES)
      box.insertAdjacentHTML("beforeend", '<div class="fp-hint">' +
        esc(t("仅渲染前 {0} 页（共 {1} 页），完整内容请下载。")
          .replace("{0}", FP_PDF_MAX_PAGES).replace("{1}", total)) + "</div>");
  } catch (e) {
    if (filePopIsOpen())
      _fpSetBody('<div class="fp-hint">' + esc(t("PDF 预览不可用（渲染器需联网首次加载）；可下载后查看。")) + "</div>");
  }
}

/* xlsx 只读预览：SheetJS 走 jsdelivr 懒加载（钉 0.18.5，npm 末版）；多工作表
 * 给页签切换；单元格按文本渲染（raw:false，日期/数字走显示值），200 行 ×
 * 40 列封顶，超限给下载提示。只认 OOXML 的 .xlsx——legacy .xls 仍走下载。 */
const FP_XLS_MAX_ROWS = 200, FP_XLS_MAX_COLS = 40;
let _xlsxLib = null;
function _loadXlsxLib() {
  if (_xlsxLib) return _xlsxLib;
  const load = (src) => new Promise((res, rej) => {
    const s = document.createElement("script");
    s.src = src; s.onload = () => res(); s.onerror = () => rej(new Error("load fail: " + src));
    document.head.appendChild(s);
  });
  _xlsxLib = load("https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js")
    .then(() => { if (!window.XLSX) throw new Error(t("xlsx 渲染器未就绪")); });
  _xlsxLib.catch(() => { _xlsxLib = null; });
  return _xlsxLib;
}

async function _fpRenderXlsx(url) {
  const el = _fpEnsure();
  try {
    const [r] = await Promise.all([fetch(url), _loadXlsxLib()]);
    if (!r.ok) throw new Error("HTTP " + r.status);
    if (!filePopIsOpen()) return;
    _fpSetBody('<div class="fp-xlsx"><div class="fp-docx-load">' + esc(t("渲染中…")) + "</div></div>");
    const box = el.querySelector(".fp-xlsx");
    const wb = window.XLSX.read(await r.arrayBuffer(), { type: "array" });
    if (!filePopIsOpen()) return;
    box.innerHTML = "";
    const tabs = document.createElement("div");
    tabs.className = "fp-xls-tabs";
    const pane = document.createElement("div");
    box.appendChild(tabs); box.appendChild(pane);
    const drawSheet = (idx) => {
      const ws = wb.Sheets[wb.SheetNames[idx]];
      const rows = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: "", raw: false });
      let html = '<table class="fp-xls"><tbody>';
      rows.slice(0, FP_XLS_MAX_ROWS).forEach((row, ri) => {
        const tag = ri === 0 ? "th" : "td";
        html += "<tr>" + row.slice(0, FP_XLS_MAX_COLS).map((c) =>
          "<" + tag + ">" + esc(String(c == null ? "" : c)) + "</" + tag + ">").join("") + "</tr>";
      });
      html += "</tbody></table>";
      if (rows.length > FP_XLS_MAX_ROWS)
        html += '<div class="fp-hint">' +
          esc(t("已截断：仅显示前 {0} 行 × {1} 列；完整内容请下载。")
            .replace("{0}", FP_XLS_MAX_ROWS).replace("{1}", FP_XLS_MAX_COLS)) + "</div>";
      pane.innerHTML = html;
      tabs.querySelectorAll(".fp-xls-tab").forEach((b, i) =>
        b.classList.toggle("active", i === idx));
    };
    wb.SheetNames.forEach((sn, i) => {
      const b = document.createElement("button");
      b.className = "ghost fp-xls-tab" + (i === 0 ? " active" : "");
      b.type = "button"; b.textContent = sn;
      b.addEventListener("click", () => drawSheet(i));
      tabs.appendChild(b);
    });
    if (!wb.SheetNames.length) throw new Error("empty workbook");
    drawSheet(0);
  } catch (e) {
    if (filePopIsOpen())
      _fpSetBody('<div class="fp-hint">' + esc(t("表格预览不可用（渲染器需联网首次加载）；可下载后查看。")) + "</div>");
  }
}

/* 按 URL 弹窗预览：图片 blob 直显、md 渲染、文本/代码等宽原文、json 美化、
 * 其余二进制只给下载。成品弹窗与目录文件弹窗共用；目录文件弹窗带 save
 * 上下文 → 额外给「编辑」，改完保存回工作目录（POST /api/dir/save）。 */
async function _fpPreviewUrl(url, name, size, opts) {
  opts = opts || {};
  url = urlAuth(url);   // 预览 fetch 与下载链接都走这个 URL：远程会话在此统一补令牌
  const ext = _fpExt(name);
  _fpSaveCtx = opts.save || null;
  _fpRawText = ""; _fpDirty = false; _fpCopyText = null;
  _fpOpen(String(name).split("/").pop(), size ? "<i>" + esc(fmtSize(size)) + "</i>" : "",
    '<a class="ghost" href="' + url + '" download="' + esc(String(name).split("/").pop()) + '">' + esc(t("下载")) + "</a>");
  const el = _fpEnsure();
  try {
    if (FP_IMG.has(ext)) {
      const r = await fetch(url);
      if (!r.ok) throw new Error("HTTP " + r.status);
      const u = URL.createObjectURL(await r.blob());
      _fpUrls.push(u);
      if (!filePopIsOpen()) return;
      _fpSetBody('<div class="fp-img"><img alt="' + esc(name) + '" src="' + u + '"></div>');
      return;
    }
    if (FP_TXT.has(ext)) {
      const r = await fetch(url);
      if (!r.ok) throw new Error("HTTP " + r.status);
      const text = await r.text();
      if (!filePopIsOpen()) return;
      _fpRawText = text;
      if (_fpSaveCtx) _fpSaveCtx.mtime = r.headers.get("X-Tutti-Mtime") || "";
      let shown = text;
      if (ext === "json") { try { shown = JSON.stringify(JSON.parse(text), null, 2); } catch (e) { /* 坏 json 原样展示 */ } }
      _fpCopyText = shown;   // 复制=看到的原文；行号列不进剪贴板（编辑/保存仍用 _fpRawText 原文）
      const codeHtml = codeBlockHTML(shown);
      const body = '<div class="fp-code">' + '<div class="fp-vp">' + codeHtml + "</div>" +
        (_fpSaveCtx ? '<textarea class="fp-edit hidden" spellcheck="false"></textarea>' : "") + "</div>";
      _fpSetBody(body);
      if (_fpSaveCtx) {
        el.querySelector(".fp-edit").addEventListener("input", () => { _fpDirty = true; });
      }
      const btns = [];
      if (_fpSaveCtx) btns.push('<button class="ghost fp-b-edit" onclick="fpEnterEdit()">' + esc(t("编辑")) + "</button>");
      btns.push('<button class="ghost" onclick="copyFPText()">' + esc(t("复制")) + "</button>");
      if (_fpSaveCtx) btns.push('<button class="ghost fp-b-save hidden" onclick="fpSaveEdit()">' + esc(t("保存")) + "</button>" +
        '<button class="ghost fp-b-cancel hidden" onclick="fpExitEdit()">' + esc(t("退出编辑")) + "</button>");
      el.querySelector(".fp-acts").insertAdjacentHTML("afterbegin", btns.join(""));
      return;
    }
    if (FP_DOCX.has(ext)) { await _fpRenderDocx(url); return; }
    if (FP_PDF.has(ext)) { await _fpRenderPdf(url); return; }
    if (FP_XLSX.has(ext)) { await _fpRenderXlsx(url); return; }
    if (FP_MEDIA.has(ext)) { _fpSetBody(fpMediaHTML(url, FP_MEDIA_VIDEO.has(ext))); return; }
    _fpSetBody('<div class="fp-hint">' + esc(t("二进制文件不预览，可下载查看。")) + "</div>");
  } catch (e) {
    _fpSetBody('<div class="fp-hint">' + esc(t("内容读取失败：") + (e.message || e)) + "</div>");
  }
}

/* 弹窗编辑模式切换：编辑按钮 ⇄ 保存/退出编辑；预览视图 ⇄ 文本编辑框 */
function _fpToggleActs(editing) {
  const el = _fpEnsure();
  const q = (c) => el.querySelector(".fp-acts " + c);
  if (q(".fp-b-edit")) q(".fp-b-edit").classList.toggle("hidden", editing);
  if (q(".fp-b-save")) q(".fp-b-save").classList.toggle("hidden", !editing);
  if (q(".fp-b-cancel")) q(".fp-b-cancel").classList.toggle("hidden", !editing);
}

window.fpEnterEdit = function () {
  if (!_fpSaveCtx) return;
  const el = _fpEnsure();
  const ta = el.querySelector(".fp-edit");
  if (!ta) return;
  ta.value = _fpRawText;
  el.querySelector(".fp-vp").classList.add("hidden");
  ta.classList.remove("hidden");
  _fpToggleActs(true);
  _fpDirty = false;
  ta.focus();
};

window.fpExitEdit = async function () {
  if (_fpDirty) {
    const ok = await uiConfirm(t("有未保存的修改，确定退出编辑？"));
    if (!ok) return;
  }
  const el = _fpEnsure();
  el.querySelector(".fp-edit").classList.add("hidden");
  el.querySelector(".fp-vp").classList.remove("hidden");
  _fpToggleActs(false);
  _fpDirty = false;
};

window.fpSaveEdit = async function () {
  const el = _fpEnsure();
  const ta = el.querySelector(".fp-edit");
  if (!ta || !_fpSaveCtx) return;
  const btn = el.querySelector(".fp-b-save");
  if (btn) btn.disabled = true;
  try {
    const d = await api("/api/dir/save", { method: "POST", body: JSON.stringify({
      dir: _fpSaveCtx.dir, name: _fpSaveCtx.name, content: ta.value, mtime: _fpSaveCtx.mtime,
    }) });
    _fpRawText = ta.value;
    _fpCopyText = ta.value;
    _fpSaveCtx.mtime = String(d.mtime || "");
    _fpDirty = false;
    // 回到预览层并重画为保存后的内容（同一个框，只换里子）
    el.querySelector(".fp-vp").innerHTML = codeBlockHTML(_fpRawText);
    ta.classList.add("hidden");
    el.querySelector(".fp-vp").classList.remove("hidden");
    _fpToggleActs(false);
    toast(t("已保存"));
  } catch (e) {
    toast(t("保存失败：") + e.message, true);
  } finally {
    if (btn) btn.disabled = false;
  }
};

/* 成品文件弹窗预览 */
window.artPopup = async function (runId, name, size) {
  // 成果文本沿用目录文件弹窗的编辑器：先取得该 run 的真实工作目录，
  // 再把保存上下文交给同一套 mtime 冲突保护。二进制文件仍然只读预览。
  let save = null;
  if (FP_TXT.has(_fpExt(name))) {
    try {
      const d = await api("/api/runs/" + encodeURIComponent(runId) + "/files");
      if (d && d.workdir) save = { dir: d.workdir, name: String(name) };
    } catch (e) { /* 读取清单失败时保持只读预览 */ }
  }
  return _fpPreviewUrl("/api/runs/" + encodeURIComponent(runId) + "/file?name=" + encodeURIComponent(name), name, size,
    save ? { editable: true, save } : undefined);
};

/* 对话结果卡「运行展示」：HTML 成品在弹窗里真跑——复用 /preview 只读挂载
 * （令牌走路径段，style.css/script.js 相对子资源照常加载）；拿不到挂载信息
 * （非网页成品/工作目录不在了）回落源码预览，按钮永远不会点了没反应。 */
window.artRunPopup = async function (runId, name, size) {
  const nm = String(name).split("/").pop();
  _fpSaveCtx = null; _fpRawText = ""; _fpDirty = false; _fpCopyText = null;
  const dl = urlAuth("/api/runs/" + encodeURIComponent(runId) + "/file?name=" + encodeURIComponent(name));
  _fpOpen(nm, size ? "<i>" + esc(fmtSize(size)) + "</i>" : "",
    '<a class="ghost" href="' + dl + '" download="' + esc(nm) + '">' + esc(t("下载")) + "</a>");
  let app = null;
  try { app = await api("/api/runs/" + encodeURIComponent(runId) + "/preview"); }
  catch (e) { /* 挂载不可用：走回落 */ }
  if (!filePopIsOpen()) return;
  if (app && app.ok && app.base) {
    _fpSetBody('<iframe class="fp-frame" src="' + esc(urlAuth(app.base + name)) +
      '" title="' + esc(t("运行预览")) +
      '" sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-popups allow-downloads"></iframe>');
    return;
  }
  return _fpPreviewUrl("/api/runs/" + encodeURIComponent(runId) + "/file?name=" + encodeURIComponent(name), name, size);
};

/* 文件浏览页点文件：中央弹窗预览工作目录里的文件（dir=根目录，name=相对路径）。
 * 带 save 上下文 → 弹窗内可直接编辑并保存回该文件。 */
window.dirFilePopup = async function (dir, name, size) {
  return _fpPreviewUrl("/api/dir/file?dir=" + encodeURIComponent(String(dir).replace(/\\/g, "/")) +
    "&name=" + encodeURIComponent(name), name, size,
    { editable: true, save: { dir: String(dir), name: String(name) } });
};

/* 迷你指挥：与详情页指挥区同一个消息端点，只是不带附件 */
window.inspSend = async function () {
  if (!inspRunId) return;
  const ta = $("insp-msg-input");
  const text = (ta.value || "").trim();
  if (!text) return;
  const btn = $("insp-send-btn");
  btn.disabled = true;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(inspRunId) + "/messages", {
      method: "POST", body: JSON.stringify({ text, attachments: [] }),
    });
    ta.value = "";
    if (result.created_task) { toast(t("已新建 CodeBee 任务，开始执行")); jumpToRun(result.run_id); return; }
    toast(t("指令已入箱，将在下一个步骤下达"));
  } catch (e) { toast(t("发送失败：") + e.message, true); }
  finally { btn.disabled = false; }
};

function applyInspectorTab() {
  const tab = S.inspTab || "git";
  document.querySelectorAll("#insp-tabs .insp-tab").forEach((b) =>
    b.classList.toggle("active", b.dataset.tab === tab));
  for (const name of ["git", "progress", "files"]) {
    const pane = $("insp-pane-" + name);
    if (pane) pane.classList.toggle("hidden", name !== tab);
  }
}

function bindInspector() {
  $("insp-close").addEventListener("click", closeInspector);
  $("insp-mask").addEventListener("click", closeInspector);
  syncInspBtn();   // 顶栏开合按钮的初始悬浮提示（关着 → 打开任务详情）
  $("insp-full").addEventListener("click", () => { if (S.inspKey) sideOpenTask(S.inspKey); });
  $("insp-send-btn").addEventListener("click", window.inspSend);
  $("insp-msg-input").addEventListener("keydown", (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); window.inspSend(); }
  });
  // 分区 TAB：手点即切；任务状态变化时的自动选中见 drawInspector（autoSig 没变不抢）
  $("insp-tabs").addEventListener("click", (e) => {
    const b = e.target.closest(".insp-tab");
    if (!b) return;
    S.inspTab = b.dataset.tab;
    applyInspectorTab();
  });
  // 任务树点任务行：主栏（中间区域）直开任务详情；任务行无内嵌层，整行即按钮；
  // 文件夹行折叠 / 右键菜单不受影响。不在详情准入范围内的行也不允许点了没反应：
  // 无主运行行直开运行详情，归档/没跑过给 toast 说明。
  $("side-tasks").addEventListener("click", (e) => {
    const det = e.target.closest(".stask");
    if (det) sideRowActivate(det);
  });
  $("side-tasks").addEventListener("keydown", (e) => {
    if (e.key !== "Enter" && e.key !== " ") return;
    if (e.target.closest("button, a, input, select, textarea, summary")) return;
    const det = e.target.closest(".stask");
    if (det) { e.preventDefault(); sideRowActivate(det); }
  });
}

/* 成品文件：run 开始后工作目录里新产生/修改过的文件，点击直接查看内容 */
function fmtArtifactSize(n) {
  n = Number(n) || 0;
  if (n >= 1 << 20) return (n / (1 << 20)).toFixed(1) + " MB";
  if (n >= 1024) return (n / 1024).toFixed(1) + " KB";
  return n + " B";
}

/* 成品文件行（检查器「成品文件」与主栏「成果」分区共用一套标记）：
 * fc-row＝清单行；动作钮收进右端固定双列 fc-acts（对比占左列、预览钉右列，
 * solo＝无对比时预览落第 2 列）——列不随行漂移，按钮永不换行。
 * 点文件名与点「预览」同款 artPopup 弹窗，行为一致不 surprise。 */
function artifactsChips(runId, files, prevRun, hasPlan) {
  // 活计划入口（批3）：task_plan.md 不进成品扫描，存在时首行给「任务计划」
  // 独立入口（file 端点按名可取，浏览器直接看勾选进度）。
  const planChip = hasPlan
    ? '<span class="fc-row">' +
      '<a class="file-chip artifact-file-open" href="' + urlAuth("/api/runs/" + encodeURIComponent(runId) + "/file?name=" +
      encodeURIComponent(".codebee/task_plan.md")) + '" target="_blank" rel="noopener" ' +
      'title=".codebee/task_plan.md">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-git-branch"/></svg>' +
      '<span class="p">' + t("任务计划") + "</span><i>plan</i></a></span>"
    : "";
  return planChip + files.map((f) => {
    const isTxt = FP_TXT.has(_fpExt(f.name));   // 文本/代码都有弹窗预览（按代码格式展示）
    // 与上一版对比（OpenCreator「版本化对比」借鉴）：同名文本文件在上一版
    // run 也存在时给 diff 入口；prevRun=null（无历史/清单拉取失败）静默不给
    const diffable = isTxt && prevRun && prevRun.names.has(f.name);
    const acts =
      (diffable ? '<a class="file-chip prev artifact-file-diff" title="' +
        esc(prevRun.ver ? t("与第 {0} 版对比").replace("{0}", prevRun.ver) : t("与上一版对比")) +
        '" data-file-run="' + esc(runId) + '" data-prev-run="' + esc(prevRun.id) +
        '" data-prev-ver="' + (prevRun.ver || "") +
        '" data-file-name="' + esc(f.name) + '" data-file-size="' + (Number(f.size) || 0) + '">' +
        '<svg class="ico" aria-hidden="true"><use href="#i-git-branch"/></svg>' + t("对比") + "</a>" : "") +
      (isTxt ? '<a class="file-chip prev artifact-file-preview" title="' + esc(t("查看内容")) +
        '" data-file-run="' + esc(runId) + '" data-file-name="' + esc(f.name) + '" data-file-size="' + (Number(f.size) || 0) + '">' +
        '<svg class="ico" aria-hidden="true"><use href="#i-book"/></svg>' + t("预览") + "</a>" : "");
    return '<span class="fc-row">' +
      '<a class="file-chip artifact-file-open" href="' + urlAuth("/api/runs/" + encodeURIComponent(runId) + "/file?name=" +
      encodeURIComponent(f.name)) + '" target="_blank" rel="noopener" ' +
      'title="' + esc(f.name + " · " + fmtArtifactSize(f.size)) + '" data-file-run="' + esc(runId) + '" data-file-name="' + esc(f.name) + '" data-file-size="' + (Number(f.size) || 0) + '">' +
      '<i class="fx">' + esc(_crFileBadge(f.name)) + "</i>" +
      '<span class="p">' + esc(f.name) + '</span><i>' + fmtArtifactSize(f.size) + "</i></a>" +
      (acts ? '<span class="fc-acts' + (diffable ? '' : ' solo') + '">' + acts + "</span>" : "") +
      "</span>";
  }).join("");
}

/* 两版 diff 弹窗正文（纯函数在 artdiff.js，node 直测）：统一 diff 行 + 长
 * 相同段折叠；中段超限诚实给整块计数（不装作逐行对齐）。 */
function artifactDiffBody(a, b) {
  const d = ArtifactDiff.diff(a, b);
  if (d.identical) return '<div class="fp-hint">' + esc(t("两版内容一致。")) + "</div>";
  const gap = (n) => '<div class="dl-gap">… ' + esc(t("{0} 行相同（已折叠）").replace("{0}", n)) + " …</div>";
  const ln = (cls, s, mark) => '<div class="dl-ln dl-' + cls + '"><i>' + mark + "</i>" + esc(s || "") + "</div>";
  let html = "";
  if (d.prefix) html += gap(d.prefix);
  if (d.oversized) {
    html += '<div class="dl-gap">' +
      esc(t("变更过大（旧 {0} 行 → 新 {1} 行），不逐行对齐；可分别打开两版查看。")
        .replace("{0}", d.oversized.a).replace("{1}", d.oversized.b)) + "</div>";
  } else {
    const rows = d.rows || [];
    let run = 0, runAt = 0;   // 连续相同行折叠：≥6 行合并成一个 gap
    rows.forEach((r, idx) => {
      if (r.t === "=") { if (!run) runAt = idx; run++; return; }
      if (run < 6) for (let k = runAt; k < runAt + run; k++) html += ln("eq", rows[k].s, " ");
      else html += gap(run);
      run = 0;
      html += r.t === "+" ? ln("add", r.s, "+") : ln("del", r.s, "−");
    });
    if (run < 6) for (let k = runAt; k < runAt + run; k++) html += ln("eq", rows[k].s, " ");
    else if (run) html += gap(run);
  }
  if (d.suffix) html += gap(d.suffix);
  return '<pre class="art-diff">' + html + "</pre>";
}

/* 对比上一版弹窗：取两版文本 → diff 渲染（复用成品弹窗骨架）。
 * prevVer 在场时副标用「第 N 版 → 当前」（序号比 run_id 前 8 位对用户可读）；
 * 缺号退回原 run_id 摘要，审计语义不丢。 */
window.artDiffPopup = async function (runId, prevRunId, name, prevVer) {
  _fpSaveCtx = null; _fpRawText = ""; _fpDirty = false; _fpCopyText = null;
  const nm = String(name).split("/").pop();
  const sub = prevVer
    ? '<i>' + esc(t("第 {0} 版 → 当前").replace("{0}", prevVer)) +
      " · " + esc(String(prevRunId).slice(0, 8)) + " → " + esc(String(runId).slice(0, 8)) + "</i>"
    : '<i>' + esc(String(prevRunId).slice(0, 8)) + " → " + esc(String(runId).slice(0, 8)) + "</i>";
  _fpOpen(nm + " · " + t("与上一版对比"), sub, "");
  _fpSetBody('<div class="fp-hint">' + esc(t("正在取两版内容…")) + "</div>");
  const u1 = urlAuth("/api/runs/" + encodeURIComponent(prevRunId) + "/file?name=" + encodeURIComponent(name));
  const u2 = urlAuth("/api/runs/" + encodeURIComponent(runId) + "/file?name=" + encodeURIComponent(name));
  try {
    const [r1, r2] = await Promise.all([fetch(u1), fetch(u2)]);
    if (!r1.ok || !r2.ok) throw new Error("HTTP " + (r1.ok ? r2.status : r1.status));
    const [a, b] = await Promise.all([r1.text(), r2.text()]);
    if (!filePopIsOpen()) return;
    if (a.length + b.length > 4 * 1024 * 1024)
      _fpSetBody('<div class="fp-hint">' + esc(t("文件过大，不在线对比；可分别打开两版查看。")) + "</div>");
    else _fpSetBody(artifactDiffBody(a, b));
  } catch (e) {
    if (filePopIsOpen())
      _fpSetBody('<div class="fp-hint">' + esc(t("内容读取失败：") + (e.message || e)) + "</div>");
  }
};

async function loadArtifacts(runId) {
  // 双入口同源渲染：检查器「成品文件」TAB + 主栏详情「成果」分区。
  let d;
  try { d = await api("/api/runs/" + encodeURIComponent(runId) + "/files"); }
  catch (e) {
    // D5（三轮审查）：成果拉取失败原静默吞掉，主栏「成果」与检查器成品 TAB
    // 无任何错误态。给出明确 toast，但不阻断其它面板渲染。
    toast(t("成果加载失败：") + (e && e.message ? e.message : t("网络异常")), true);
    return;
  }
  // 成果分区/徽章只吃当前详情目标的 run：详情开着但 runId 是别的任务（检查器
  // 后台跟刷旧选中）时，绝不能把别家的文件写进主栏——那是肉眼可见的串台
  const detailOpen = !$("run-detail").classList.contains("hidden");
  const detailOwns = detailOpen &&
    (S.detailRunId === runId ||
     (S.detailTaskKey && S.lastRun && S.lastRun.id === runId));
  // 检查器入口只在「开着且 runId 仍是检查器当前 run」时认领；两边都不认 → 过期响应丢弃
  const inspOpen = document.body.classList.contains("inspector-open") && S.inspKey !== null;
  const inspOwns = inspOpen &&
    runId === ((S.inspData && S.inspData.run && S.inspData.run.id) || "");
  if (!detailOwns && !inspOwns) return;
  const files = d.files || [];
  const box = inspOwns ? $("insp-artifacts") : null;
  const mainBox = detailOwns ? $("rd-arts") : null;
  // 成果分区徽章：文件数（终态才有产出，运行中不计）；只随 detailOwns 一起刷
  const fb = detailOwns ? document.querySelector('#rd-tabs .rd-tab[data-tab="result"] .rd-badge') : null;
  if (fb) { const cnt = files.length + (d.has_plan ? 1 : 0);
    fb.textContent = cnt ? String(cnt) : "";
    fb.className = "rd-badge" + (cnt ? "" : " hidden"); }
  if (!files.length && !d.has_plan) {
    if (box) box.innerHTML = '<span class="insp-hint">' + esc(t("本次运行没有在工作目录里产出新文件。")) + "</span>";
    if (mainBox) { mainBox.classList.add("hidden"); mainBox.innerHTML = ""; }
    return;
  }
  // 上一版 run 的文件清单（详情上下文才有）：同名文本文件给「对比」入口；
  // 拉不到/无历史静默降级——对比是增强不是闸门。
  // 版本序号（OpenCreator「版本化」剩余面）：任务 run 列表最新在前，序号 =
  // run 总数 - 列表内序位；total 缺失（分页未拉过）就不编版本号，徽章/对比
  // 标题退回原样——序号是可读性增强不是闸门
  let prevRun = null, curVer = 0;
  if (detailOwns && S.detailTaskKey) {
    const runs = _taskRunsCache.get(S.detailTaskKey) || [];
    const total = ((_taskRunsPaging.get(S.detailTaskKey) || {}).total) || 0;
    const idx = runs.findIndex((r) => r.id === runId);
    if (total && idx >= 0) curVer = total - idx;
    const prev = runs.find((r) => r.id !== runId);
    if (prev) {
      try {
        const pd = await api("/api/runs/" + encodeURIComponent(prev.id) + "/files");
        if (pd && (pd.files || []).length) {
          const pIdx = runs.indexOf(prev);
          prevRun = { id: prev.id, names: new Set(pd.files.map((f2) => f2.name)),
            ver: (total && pIdx >= 0) ? total - pIdx : 0 };
        }
      } catch (e) { /* 上一版清单不可用就不给对比 */ }
    }
  }
  const verBadge = curVer > 1
    ? '<span class="ver-badge" title="' + esc(t("该任务第 N 次运行的产出，序号含修订与重试")) + '">' +
      esc(t("第 {0} 版").replace("{0}", curVer)) + "</span>"
    : "";
  const chips = artifactsChips(runId, files, prevRun, d.has_plan);
  const head = '<div class="files-head"><span class="sec-title">' + t("成品文件") + '</span>' +
    verBadge +
    '<span class="wd" title="' + esc(t("点击复制")) + '" onclick="copyText(this.textContent)">' + esc(d.workdir) + "</span></div>";
  if (box) box.innerHTML = head + '<div class="file-chips">' + chips + "</div>";
  if (mainBox) { mainBox.classList.remove("hidden");
    mainBox.innerHTML = head + '<div class="file-chips">' + chips + "</div>"; }
}

/* ---------------- 网页成品预览（借鉴对话式编程产品的预览窗） ----------------
 * 代码任务跑完，用户要的是「看到东西跑起来」，而不是逐个点开文件读代码。
 * 左「运行」= 入口 HTML 的 iframe（后端 /preview/<run>/<令牌>/ 只读挂载工作
 * 目录，令牌走路径段让 style.css / script.js 这些相对子资源也带上）；
 * 右各文件页签 = 源码视图（复用 codeBlockHTML：行号+高亮，与成果预览同款）。
 * 「刷新」重挂 iframe（改完文件不用退出详情页），「打开新窗口」给真全屏。
 * 页签在无网页成品时整体隐藏（见 rdTabAvail），不打扰小说/普通任务。 */
let pvRunId = null;      // 当前预览归属的 run（换 run 必须重挑入口与页签）
let pvApp = null;        // 后端 /api/runs/<id>/preview 的返回（入口 + 文件清单 + base）
let pvView = "run";      // "run" = 运行视图；否则是文件名
let pvCodeSig = "";      // 代码视图去抖签名（轮询重画不重取同一个文件）

function pvReset() {
  pvRunId = null; pvApp = null; pvView = "run"; pvCodeSig = "";
}

/* 预览 iframe 的地址：base 已带令牌与尾部斜杠，相对路径交给 <base href> 解析 */
function pvRunUrl() {
  if (!pvApp || !pvApp.base) return "";
  return urlAuth(pvApp.base + (pvApp.entry || ""));
}

function pvTabsHTML() {
  const f = (pvApp && pvApp.files) || [];
  const mk = (key, label, title) =>
    '<button class="pv-tab' + (pvView === key ? " on" : "") + '" role="tab" ' +
    'aria-selected="' + (pvView === key ? "true" : "false") + '" data-pv="' + esc(key) + '" ' +
    'title="' + esc(title || label) + '">' + esc(label) + "</button>";
  let h = mk("run", t("运行视图"), t("实时运行入口页面"));
  for (const it of f) h += mk(it.name, it.name.split("/").pop(), it.name);
  return h;
}

function pvBodyHTML() {
  if (!pvApp || !pvApp.ok) return "";
  if (pvView === "run") {
    // 每次重挂 iframe 都换 src 尾参，绕开浏览器缓存：用户点「刷新」就是要看新代码
    const src = pvRunUrl();
    return '<iframe class="pv-frame" id="rd-pv-frame" src="' + esc(src) +
      '" title="' + esc(t("运行预览")) + '" sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-popups allow-downloads"></iframe>';
  }
  return '<div class="pv-code"><div class="fp-vp" id="rd-pv-code">' +
    '<div class="fp-hint">' + esc(t("正在读取文件…")) + "</div></div></div>";
}

async function pvLoadCode(name) {
  const el = $("rd-pv-code");
  if (!el) return;
  const url = "/api/runs/" + encodeURIComponent(pvRunId) + "/file?name=" + encodeURIComponent(name);
  try {
    const r = await fetch(urlAuth(url), { headers: authHeaders() });
    if (!r.ok) throw new Error("HTTP " + r.status);
    const text = await r.text();
    if (!el.isConnected || pvView !== name) return;   // 拉取期间切走了：过期响应不落盘
    el.innerHTML = codeBlockHTML(text);
  } catch (e) {
    if (el.isConnected && pvView === name)
      el.innerHTML = '<div class="fp-hint">' + esc(t("内容读取失败：") + (e.message || e)) + "</div>";
  }
}

/* 原生渲染成品页签（视频/音频/图片/PDF）：交给浏览器原生能力，不走
 * codeBlockHTML——二进制当文本渲染就是乱码墙。src 均带鉴权的 file 地址。 */
function pvLoadNativeFile(name) {
  const el = $("rd-pv-code");
  if (!el) return;
  const ext = _fpExt(name);
  const url = urlAuth("/api/runs/" + encodeURIComponent(pvRunId) + "/file?name=" + encodeURIComponent(name));
  let inner;
  if (FP_MEDIA.has(ext)) {
    const tag = FP_MEDIA_VIDEO.has(ext) ? "video" : "audio";
    inner = '<' + tag + ' controls preload="metadata" src="' + url + '"></' + tag + ">";
  } else if (FP_IMG_PV.has(ext)) {
    inner = '<img alt="' + esc(name) + '" src="' + url + '">';
  } else {
    inner = '<iframe src="' + url + '" title="' + esc(name) + '"></iframe>';   // pdf：内置阅读器
  }
  el.innerHTML = '<div class="pv-native">' + inner + "</div>";
}

function pvDraw() {
  const box = $("rd-preview");
  if (!box) return;
  if (!pvApp || !pvApp.ok) {
    box.classList.add("hidden");
    // iframe 一并摘掉：hidden 只是不可见，留在 DOM 里旧页面还在跑（定时器/
    // 音频不会停）；换成无预览的 run 时更不能留上一家的残影
    const body = $("rd-pv-body");
    if (body) body.innerHTML = "";
    return;
  }
  box.classList.remove("hidden");
  $("rd-pv-tabs").innerHTML = pvTabsHTML();
  const open = $("rd-pv-open");
  if (open) open.href = urlAuth(pvRunUrl());
  $("rd-pv-body").innerHTML = pvBodyHTML();
  const hint = $("rd-pv-hint");
  if (hint) {
    // 工作目录路径给出来：预览的是哪个目录一目了然（与「成果」同款可点复制）
    hint.innerHTML = '<span data-i18n-x>' + esc(t("预览工作目录：")) + "</span>" +
      '<span class="pv-wd" title="' + esc(t("点击复制")) + '" onclick="copyText(this.textContent)">' +
      esc(pvApp.workdir || "") + "</span>";
    hint.classList.remove("hidden");
  }
  if (pvView !== "run") {
    pvCodeSig = pvView;
    if (FP_NATIVE_PV.has(_fpExt(pvView))) pvLoadNativeFile(pvView);
    else pvLoadCode(pvView);
  }
}

window.pvGo = function (view) {
  pvView = view;
  pvCodeSig = "";
  pvDraw();
};
window.pvReload = function () {
  // 重挂 iframe：加时间戳绕缓存；原生渲染页签重挂播放器/图片/PDF；代码视图则重取
  if (pvView === "run") {
    const f = $("rd-pv-frame");
    if (f) f.src = urlAuth(pvRunUrl()) + (String(pvRunUrl()).includes("?") ? "&" : "?") + "_=" + Date.now();
  } else if (FP_NATIVE_PV.has(_fpExt(pvView))) {
    pvLoadNativeFile(pvView);
  } else {
    pvLoadCode(pvView);
  }
};

async function renderPreview(runId) {
  const box = $("rd-preview");
  if (!box) return;
  if (!runId) { box.classList.add("hidden"); rdTabsSync(); return; }
  if (pvRunId !== runId) { pvRunId = runId; pvApp = null; pvView = "run"; pvCodeSig = ""; }
  let d = null;
  try { d = await api("/api/runs/" + encodeURIComponent(runId) + "/preview"); }
  catch (e) { d = null; }
  // 过期闸门：拉取期间切了详情就丢弃响应（同 loadArtifacts 的双入口闸门）
  if (pvRunId !== runId) return;
  if (!$("run-detail") || $("run-detail").classList.contains("hidden")) { rdTabsSync(); return; }
  pvApp = d || { ok: false };
  const badge = document.querySelector('#rd-tabs .rd-tab[data-tab="preview"] .rd-badge');
  if (badge) {
    const n = pvApp && pvApp.ok ? (pvApp.files || []).length : 0;
    badge.textContent = n ? String(n) : "";
    badge.className = "rd-badge" + (n ? "" : " hidden");
  }
  pvDraw();
  rdTabsSync();   // 预览可用性（rdTabAvail 认 #rd-preview 的显隐）随之更新
}

/* 复制文本到剪贴板：writeText 只在安全上下文（https / localhost）可用，
 * 用局域网 IP 或远程地址打开页面时 navigator.clipboard 是 undefined 或直接
 * 拒绝——必须回退 execCommand，否则按钮点了、剪贴板却是空的。done=真实
 * 复制成功后的回调；失败由 fallbackCopy 统一弹错误提示。 */
window.copyText = function (t, done) {
  const ok = () => { if (done) done(); };
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      // 未处理的 promise 拒绝会以控制台错误冒出来（测试断言 0 错误会被它打爆）
      navigator.clipboard.writeText(t).then(ok, () => fallbackCopy(t, ok));
      return;
    }
  } catch (e) { /* 落到 execCommand 兜底 */ }
  fallbackCopy(t, ok);
};

let currentLog = null; // { runId, rel }：同一路径在不同轮次也必须能切换

/* 当前打开的日志是否仍属于这批步骤（重画后日志路径消失说明步骤被重建，才收起） */
function stepsMatch(runs, current) {
  if (!current) return false;
  return (runs || []).some((r) => String(r.id || "") === String(current.runId || "") &&
    (r.steps || []).some((s) => s.log === current.rel));
}

/* 从章稿文件名取全书章号：chapter-07.md → 7；非章稿（或解析不出）返回 0。
 * 只认「chapter-数字.md」这一约定（与后端 _CH_FILE_RE 一致）。 */
function chapterNumOf(name) {
  const base = String(name || "").split("/").pop();
  if (!/^chapter-\d{1,4}\.md$/i.test(base)) return 0;
  const digits = base.slice("chapter-".length, -3);
  const n = parseInt(digits, 10);
  return n > 0 ? n : 0;
}

/* 分卷规划表（前端只读副本）：把任务的 serial 分卷配置还原成
 * [{vol, title, first, last}]，供发布页按卷分组列章。后端 volumes.py 是唯一
 * 真源（写作与成书都走它）；这里只做「列清单」这一用途的最小推导，取不到
 * 分卷配置时返回 []（调用方退化为平铺列表）。
 *   serial.volumes        显式卷表：[{title, chapters|start/end}]（优先）
 *   serial.volume_chapters 每卷章数：等长切卷（兜底）
 * last=null 表示开放到书末。 */
function volumePlanOf(task, upto) {
  const s = (task || {}).serial || {};
  const spec = Array.isArray(s.volumes) ? s.volumes : [];
  let per = parseInt(s.volume_chapters, 10);
  if (!(per >= 2)) per = 0;
  if (!spec.length && !per) return [];
  const plan = [];
  let prevLast = 0;
  const push = (title, first, last) => plan.push({ vol: plan.length + 1, title: title || "", first: first, last: last });
  for (const it of spec) {
    if (!it) continue;
    const first = (it.start > 0) ? it.start : prevLast + 1;
    let last = null;
    if (it.end > 0) last = it.end;
    else if (it.chapters > 0) last = first + it.chapters - 1;
    if (last != null && last < first) last = first;
    push(it.title, first, last);
    if (last == null) return plan;     // 开放卷：后面不再有卷
    prevLast = last;
  }
  // 显式卷表用尽后按每卷章数（或末卷长度）续卷，保证覆盖到 upto（与后端
  // volumes.build_plan 同规则）——否则第 21 章起会掉进「其他文件」分组。
  const fb = per || (plan.length && plan[plan.length - 1].last != null
    ? plan[plan.length - 1].last - plan[plan.length - 1].first + 1 : 0);
  if (fb > 0) {
    let cursor = prevLast + 1;
    const limit = (upto > 0) ? upto : (plan.length ? prevLast : fb);
    while (cursor <= limit && plan.length < 200) {
      push("", cursor, cursor + fb - 1);
      cursor += fb;
    }
  }
  return plan;
}


/* 连载章节评审卡：每章均分/是否达标/字数 + 逐项目标审稿结果（event_check，
 * 借鉴 AI-Novel-Writer：大纲要点逐项判定+正文证据）。非连载 run 无
 * chapter_scores 保持隐藏。
 * 分卷：章节卡按卷分组显示（卷名来自 run.volumes / chapter_scores[].vol_title），
 * 不分卷时退化为原来的平铺列表，视觉零变化。 */
function renderChapterScores(run) {
  const box = $("rd-chapters");
  if (!box) return;
  const cs = run && run.chapter_scores;
  if (!Array.isArray(cs) || !cs.length) { box.classList.add("hidden"); return; }
  box.classList.remove("hidden");
  // 卷名表：优先 run.volumes（全书卷规划），退到章节自带的 vol_title
  const volTitles = {};
  (run.volumes || []).forEach((v) => { volTitles[v.vol] = v.title || ""; });
  cs.forEach((c) => {
    if (c.vol && c.vol_title && !volTitles[c.vol]) volTitles[c.vol] = c.vol_title;
  });
  const rowHtml = (c) => {
    const means = c.means || {};
    const dims = Object.keys(means).map((d) =>
      '<span class="ch-dim' + (means[d] >= 7 ? "" : " low") + '">' + esc(d) + " " + means[d] + "</span>").join("");
    const ev = (c.event_check || []).map((line) => {
      const ok = /已完成/.test(line), bad = /未完成/.test(line);
      return '<div class="ch-ev' + (ok ? " ok" : bad ? " bad" : "") + '">' + esc(line) + "</div>";
    }).join("");
    return '<div class="ch-row' + (c.passed ? "" : " fail") + '">' +
      '<div class="ch-head"><b>' + esc(t("第") + " " + c.chapter + " " + t("章")) + '</b>' +
      '<span class="ch-title">' + esc(c.title || "") + "</span>" +
      '<span class="tag">' + (c.passed ? t("达标") : t("未达标")) + "</span>" +
      (c.reused ? '<span class="tag">' + t("沿用") + "</span>" : "") +
      '<span class="ch-meta">' + Number(c.words || 0) + t(" 字") +
      (c.rounds > 1 ? " · " + c.rounds + t(" 轮") : "") + "</span></div>" +
      (dims ? '<div class="ch-dims">' + dims + "</div>" : "") +
      (ev ? '<div class="ch-evs"><span class="hint">' + t("逐项目标核对：") + "</span>" + ev + "</div>" : "") +
      "</div>";
  };
  const head = '<h3 class="sec-title">' + t("章节评审") +
    '<span class="tag">' + cs.filter((c) => c.passed).length + "/" + cs.length + " " + t("达标") + "</span></h3>";
  const hasVol = cs.some((c) => c.vol);
  if (!hasVol) { box.innerHTML = head + cs.map(rowHtml).join(""); return; }
  // 按卷分组（章号顺序，卷内保持原序）
  const groups = [];
  cs.forEach((c) => {
    const v = c.vol || 0;
    let g = groups.find((x) => x.vol === v);
    if (!g) { g = { vol: v, rows: [] }; groups.push(g); }
    g.rows.push(c);
  });
  box.innerHTML = head + groups.map((g) => {
    const title = volTitles[g.vol] || "";
    const nPass = g.rows.filter((c) => c.passed).length;
    const label = g.vol ? (t("第") + " " + g.vol + " " + t("卷") + (title ? " " + t("《") + title + t("》") : "")) : t("未分卷");
    return '<div class="ch-vol"><div class="ch-vol-head"><b>' + esc(label) + "</b>" +
      '<span class="tag">' + nPass + "/" + g.rows.length + " " + t("达标") + "</span>" +
      '<span class="ch-meta">' + t("第 ") + g.rows[0].chapter + "–" +
      g.rows[g.rows.length - 1].chapter + t(" 章") + "</span></div>" +
      g.rows.map(rowHtml).join("") + "</div>";
  }).join("");
}

function renderPlan(run) {
  const box = $("rd-plan");
  const plan = run.plan;
  if (!plan || !plan.steps || !plan.steps.length) { box.classList.add("hidden"); return; }
  const route = run.route || {};
  const routeHtml = Object.keys(route).length
    ? '<div class="route">' + t("路由依据：") +
      Object.keys(route).map((k) => "<b>" + esc(k) + "</b> " + esc(route[k])).join(t("　|　")) + "</div>"
    : "";
  box.classList.remove("hidden");
  box.innerHTML = '<h3 class="sec-title">' + t("编排计划 ") + '<span class="tag">' + t("来源 ") + esc(plan.source || "?") + "</span></h3>" +
    '<div class="steps">' + plan.steps.map((s, i) =>
      '<div class="step plan"><span class="n">' + String(i + 1).padStart(2, "0") + "</span>" +
      '<span class="role">' + esc(s.title || "") + "</span>" +
      '<span class="sum">' + esc(s.detail || "") + "</span></div>").join("") + "</div>" + routeHtml;
}

/* 运行详情的统一调度审计：任务画像和实际选路来自同一次编译结果。
 * 旧运行没有 task_spec/route_plan 时保持隐藏，避免把历史数据伪装成当前决策。 */
function renderRouting(run) {
  let box = $("rd-routing");
  if (!box) {
    const steps = $("rd-steps");
    if (!steps || !steps.parentNode) return;
    box = document.createElement("div");
    box.id = "rd-routing";
    box.className = "rd-routing hidden";
    steps.parentNode.insertBefore(box, steps);
  }
  const spec = run && run.task_spec;
  const plan = run && run.route_plan;
  if (!spec || !plan) { box.classList.add("hidden"); box.innerHTML = ""; return; }
  const type = spec.type || "direct";
  const difficulty = spec.difficulty || "default";
  const dimension = spec.dimension || "reasoning";
  const caps = Array.isArray(spec.capabilities) ? spec.capabilities.filter(Boolean) : [];
  const typeLabel = ((flowById(type) || {}).name) || type;
  const difficultyLabel = t(({ easy: t("简单"), default: t("标准"), hard: t("困难") })[difficulty] || difficulty);
  const dimensionLabel = t(({ coding: t("编码"), writing: t("写作"), reasoning: t("推理"), vision: t("视觉") })[dimension] || dimension);
  const capLabels = {
    coding: t("编码"), writing: t("写作"), reasoning: t("推理"), vision: t("视觉"),
    filesystem: t("文件读写"), verification: t("验证"), long_context: t("长上下文"),
    continuity: t("连续性"), attachments: t("附件"),
  };
  const capsText = caps.length ? caps.map((x) => t(capLabels[x] || x)).join(t("、")) : t("通用能力");
  const selectedLabel = (entry) => entry && (entry.label || entry.agent_id || "") || t("未选定");
  const roleBlock = (key, title) => {
    const route = plan[key] || {};
    const candidates = Array.isArray(route.candidates) ? route.candidates : [];
    if (!route.selected && !candidates.length) return "";
    const selected = candidates.find((x) => x.agent_id === route.selected) || candidates[0];
    const participants = Array.isArray(route.participants) ? route.participants : [];
    const activeIds = participants.length ? participants.slice() : (route.selected ? [route.selected] : []);
    if (route.selected && activeIds.includes(route.selected)) {
      activeIds.splice(activeIds.indexOf(route.selected), 1);
      activeIds.unshift(route.selected);
    }
    const activeLabels = activeIds.map((id) => {
      const item = candidates.find((x) => x.agent_id === id);
      return selectedLabel(item || { agent_id: id });
    }).filter(Boolean);
    const fallback = Array.isArray(route.fallback) ? route.fallback : [];
    const fallbackLabels = fallback.map((id) => {
      const item = candidates.find((x) => x.agent_id === id);
      return selectedLabel(item || { agent_id: id });
    }).filter(Boolean);
    const rows = candidates.map((x) =>
      '<div class="rd-route-row"><span class="rd-route-score">' + esc(Number(x.score || 0).toFixed(1)) +
      '</span><span class="rd-route-agent">' + esc(selectedLabel(x)) + '</span><span class="rd-route-reason">' +
      esc(x.reason || "") + '</span></div>').join("");
    return '<div class="rd-route-role"><div class="rd-route-role-head"><b>' + esc(title) +
      '</b><span>' + esc(activeLabels.join(" + ") || selectedLabel(selected)) + '</span></div>' +
      (route.selection_reason ? '<div class="rd-route-selection">' + esc(route.selection_reason) + '</div>' : "") +
      (fallbackLabels.length ? '<div class="rd-route-fallback">' + esc(t("降级：")) + esc(fallbackLabels.join(" → ")) + '</div>' : "") +
      (rows ? '<details class="rd-route-candidates"><summary>' + esc(t("查看候选评分")) + '</summary>' + rows + '</details>' : "") +
      '</div>';
  };
  const roles = [roleBlock("implement", t("实现")), roleBlock("review", t("评审"))].filter(Boolean).join("");
  if (!roles) { box.classList.add("hidden"); box.innerHTML = ""; return; }
  box.classList.remove("hidden");
  box.innerHTML = '<div class="rd-routing-head"><span class="rd-routing-title">' + esc(t("任务画像与调度")) +
    '</span><span class="rd-routing-spec">' + esc(t("{0} · {1} · {2}", t(typeLabel), difficultyLabel, dimensionLabel)) + '</span></div>' +
    '<div class="rd-routing-caps"><span>' + esc(t("需要：")) + '</span>' + esc(capsText) + '</div>' +
    '<div class="rd-route-roles">' + roles + '</div>';
}
/* 日志框顶部状态条：运行中 → ● 实时（呼吸点 + 最后刷新时间）；结束 → 灰字已结束。
 * 没有它，用户分不清"日志在刷但 CLI 暂无输出"和"刷新坏了"——两者长得一模一样。 */
function logLiveBadge(live) {
  const dot = $("rd-log-live"), at = $("rd-log-at");
  if (!dot) return;
  const hm = () => new Date().toTimeString().slice(0, 8);
  if (live) {
    dot.className = "log-live on";
    dot.textContent = t("● 实时");
    at.textContent = t("刚刚更新 ") + hm();
  } else {
    dot.className = "log-live";
    dot.textContent = t("已结束");
    at.textContent = hm();
  }
}

/* 复制抽屉日志全文：报错 JSON 动辄几十行还带横向滚动，手动圈选很折磨 */
window.rdLogCopy = function () {
  const pre = $("rd-log-text");
  const text = ((pre && pre.textContent) || "").trim();
  const idle = [t("（等待输出…）"), t("（无输出）")];
  if (!text || idle.includes(text)) return;
  const done = () => toast(t("已复制"));
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text, done));
  } else fallbackCopy(text, done);
};

/* 抽屉标题：按 (runId, 日志路径) 反查步骤角色与执行者——不知道在看谁的日志，
 * 抽屉就成了无名黑框 */
function rdLogStepLabel(runId, rel) {
  const pools = [];
  if (S.lastRun && S.lastRun.id === runId) pools.push(S.lastRun.steps || []);
  if (S.state && S.state.runs) {
    const r = S.state.runs.find((x) => x.id === runId);
    if (r) pools.push(r.steps || []);
  }
  for (const steps of pools) {
    const s = steps.find((x) => x.log === rel);
    if (s) return [s.role || "", s.agent_label || s.agent || ""].filter(Boolean).join(" · ");
  }
  return rel || "";
}

/* 直连任务的输入框只在日志抽屉真正打开时才让出底部空间。
 * 日志和聊天 pane 位于同一个主区，不能靠普通兄弟选择器反向联动，
 * 所以用详情根节点的状态类做显式同步。 */
function syncChatLogSpace(open) {
  const detail = $("run-detail");
  if (detail) detail.classList.toggle("chat-log-open", !!open);
}

window.rdLogClose = function () {
  const box = $("rd-log");
  syncChatLogSpace(false);
  if (!box) return;
  box.classList.add("hidden");
  currentLog = null;
  stopLogLive();
  const st = $("rd-log-step");
  if (st) st.textContent = "";
};

async function toggleLog(runId, rel) {
  const box = $("rd-log"), pre = $("rd-log-text");
  if (currentLog && currentLog.runId === runId && currentLog.rel === rel && !box.classList.contains("hidden")) {
    window.rdLogClose(); return;
  }
  try {
    const r = await api("/api/runs/" + encodeURIComponent(runId) + "/log?step=" + encodeURIComponent(rel) + "&pretty=1");
    // 拉取期间可能切详情：过期日志不落盘（A 的步骤输出写进 B 详情的抽屉）。
    // 检查器蜂巢/步骤点开日志同款：run 属检查器当前 run 也算在场
    const owned = S.detailRunId === runId ||
      // 任务级直连时间线会跨多轮 run 回放；按钮上的 run 可能不是最新一轮，
      // 只按 latest.id 判断会让旧轮次的「CLI 日志」点击后悄悄失效。
      (S.detailTaskKey && S.lastRun && S.lastRun.task_id === S.detailTaskKey) ||
      ((S.inspData || {}).run || {}).id === runId;
    if (!owned) return;
    // 占位符跟状态走：运行中才「等待输出」，终态没产出就是「无输出」——
    // 否则内置合成器这类不落 CLI 日志的步骤结束后，一直挂「等待输出…」
    // 假装还在产字（2026-09-22 merge 卡已结束却等待输出案）
    pre.textContent = r.log ||
      (r.step_status === "running" ? t("（等待输出…）") : t("（无输出）"));
    box.classList.remove("hidden");
    syncChatLogSpace(true);
    currentLog = { runId, rel };
    const st = $("rd-log-step");
    if (st) st.textContent = rdLogStepLabel(runId, rel);
    pre.scrollTop = pre.scrollHeight;   // 打开即看最新输出
    // 输出是流式写入的：运行中点开就持续刷新；步骤结束（后端带 step_status）即停
    const live = r.step_status === "running";
    logLiveBadge(live);
    stopLogLive();
    if (!live) return;
    S.logLive = setInterval(async () => {
      if (!currentLog || currentLog.runId !== runId || currentLog.rel !== rel) return stopLogLive();
      try {
        const rr = await api("/api/runs/" + encodeURIComponent(runId) + "/log?step=" + encodeURIComponent(rel) + "&pretty=1");
        if (currentLog && currentLog.runId === runId && currentLog.rel === rel) {
          // 贴底跟随：用户滚到底部附近才自动滚到最新输出，回看历史不打扰
          const stick = pre.scrollHeight - pre.scrollTop - pre.clientHeight < 48;
          // 最后一帧常在步骤翻终态后才拉到：此刻仍无输出就该换「无输出」
          pre.textContent = rr.log ||
            (rr.step_status === "running" ? t("（等待输出…）") : t("（无输出）"));
          if (stick) pre.scrollTop = pre.scrollHeight;
          logLiveBadge(true);   // 每帧都打时间戳：内容没变也能证明通道活着
          if (rr.step_status && rr.step_status !== "running") {
            logLiveBadge(false);
            stopLogLive();      // 步骤终态：拉完最后一帧就停
          }
        }
      } catch (e) { /* 网络抖动保留上一帧 */ }
    }, 2500);
  } catch (e) { pre.textContent = t("日志读取失败: ") + e.message; box.classList.remove("hidden");
    syncChatLogSpace(true);
    const st = $("rd-log-step"); if (st) st.textContent = rdLogStepLabel(runId, rel);
    logLiveBadge(false); }
}
/* ---------------- 蜂巢工作台：每个智能体一格，点开即看实时输出 ---------------- */
let hiveTimer = null;                    // 卡片尾巴轮询表
let hiveClock = null;                    // running 秒表（1s 走动）
const hiveTails = {};                    // "runid|rel" -> 最近一行输出缓存
const hiveThink = {};                    // "runid|rel" -> 最近思考片段（【思考】行提取）

function stopHiveTick() { if (hiveTimer) { clearInterval(hiveTimer); hiveTimer = null; } }

/* run.steps -> 阶段泳道流水线：规划→起草→评审→修订→打磨→合成，先后关系一眼可见；
 * 运行中蜜蜂摆动+秒表走动+蜜光呼吸；彗尾光点流向下一阶段；点格即看实时输出；
 * 入场瀑布只在步骤结构真变时重播（签名闸门，轮询空转不重建 DOM）。 */
function hiveStage(role) {
  const r = String(role || "");
  if (/^(plan|outline)/.test(r)) return t("规划");
  if (/^draft/.test(r)) return t("起草");
  if (/critique/.test(r) || r === "review") return t("评审");
  if (/^(revise|fix)/.test(r)) return t("修订");
  if (/^polish/.test(r)) return t("打磨");
  if (/^(merge|verify)/.test(r)) return t("合成");
  if (/^implement/.test(r)) return t("实现");
  return t("执行");
}

/* running 卡片秒表：started_at HH:MM:SS → 走动计时（跨天/解析失败回退原值） */
function hiveElapsed(started) {
  const m = /^(\d{2}):(\d{2}):(\d{2})$/.exec(String(started || ""));
  if (!m) return String(started || "");
  const now = new Date();
  const secs = Math.max(0, now.getHours() * 3600 + now.getMinutes() * 60 + now.getSeconds()
    - (+m[1] * 3600 + +m[2] * 60 + +m[3]));
  const h = Math.floor(secs / 3600), mn = Math.floor((secs % 3600) / 60), sc = secs % 60;
  return (h ? h + ":" + String(mn).padStart(2, "0") : String(mn)) + ":" + String(sc).padStart(2, "0");
}

/* 尾巴去噪：codex 遥测 WARN/折叠标记/半行 JSON 不是"它在干什么"；翻译后的【消息】行是正文 */
function hiveCleanLine(lines) {
  for (let i = lines.length - 1; i >= 0; i--) {
    const l = String(lines[i] || "").trim();
    if (!l) continue;
    if (/warn\b|telemetry|metrics|failed to flush|mcp|已折叠/i.test(l)) continue;
    // 二进制/UTF-16 残渣与乱码墙不配当「它在干什么」（claude 流里实测出现过
    // \u0000 夹正文的残渣行，展示出来就是一串占位符）
    if ((l.match(/\x00|\\u0000/gi) || []).length >= 2) continue;
    if ((l.match(/\ufffd/g) || []).length > 6) continue;
    if (l.startsWith("{") && /"type"\s*:/.test(l)) {
      try {
        const ev = JSON.parse(l);
        if (ev.type === "item.completed" && ev.item && ev.item.type === "agent_message" && ev.item.text)
          return String(ev.item.text).slice(-160);
      } catch (e) { /* 半行 JSON 等下一轮 */ }
      continue;
    }
    return l.slice(-160);
  }
  return "";
}

/* 思考片段：pretty 日志里最近的【思考】/思考心跳行——运行中卡片的一条
 * 「💭 …」弱化行，让用户不用点开日志也能看到模型在想什么。没有思考行
 * （qwen/mimo 等一次性输出）返回空，卡片不多占一行。 */
function hiveThinkLine(lines) {
  for (let i = lines.length - 1; i >= 0; i--) {
    const l = String(lines[i] || "").trim();
    if (!l) continue;
    if (l.startsWith("【思考】")) return l.slice(0, 220);
    if (/^— 思考中（心跳/.test(l)) return l;
  }
  return "";
}

/* —— 3D 场景（WebGL 蜂巢塔）控制层：引擎在 hive3d.js，这里只管模式切换/
 * localStorage 持久化/WebGL 不可用降级，以及把 renderHive 的泳道数据翻译给场景。 —— */
let hiveScene = null;          // Hive3D 场景实例（懒创建）
let hiveSceneDead = false;     // WebGL 不可用/上下文丢失——本次页面周期内不再尝试
let hiveMode = "reference";  // 模块级占位；setup 按存储应用视图——默认 2D 列表（1013 拍板），live3d 仅内部 QA
let hiveRunId = "";            // 最近一次 renderHive 的 run.id（尾巴/思考缓存键前缀）
const hiveLiveMeta = {};       // rel -> { started_at }（3D 芯片秒表用）
let hiveDialogPoll = null;
let hiveDialogKey = "";

function setHiveSceneButtons(mode) {
  document.querySelectorAll("[data-hive-view]").forEach((button) => {
    // 自由 3D 尚未达到发布质量：保留引擎给内部 QA，但不把入口暴露给用户。
    // hidden/aria-hidden 双保险，避免旧缓存或浏览器恢复状态重新显示它。
    const internalOnly = button.dataset.hiveView === "live3d";
    button.hidden = internalOnly;
    button.setAttribute("aria-hidden", internalOnly ? "true" : "false");
    const active = button.dataset.hiveView === mode;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function ensureHiveScene() {
  if (hiveScene || hiveSceneDead) return hiveScene;
  const canvas = $("rd-hive-gl"), overlay = $("rd-hive-overlay");
  if (!canvas || !overlay || !window.Hive3D) { hiveSceneDead = true; return null; }
  hiveScene = window.Hive3D.create({
    canvas, overlay,
    onCellActivate(rid, rel, cell) { openHiveMonitorLog(rid, rel, cell); },
    /* 悬停气泡与运行中芯片的实时内容：尾巴/思考来自 hiveTick 的缓存，秒表现算 */
    cellRefresh(rel) {
      const key = hiveRunId + "|" + rel;
      const meta = hiveLiveMeta[rel] || {};
      return {
        tail: hiveTails[key] || "",
        think: hiveThink[key] || "",
        elapsed: meta.started_at ? hiveElapsed(meta.started_at) : "",
      };
    },
    onFatal() {   // 上下文丢失等不可恢复故障：退回 2D 并禁用 3D 入口
      hiveSceneDead = true;
      hiveScene = null;
      setHiveSceneMode("2d", { silent: true });
      toast(t("3D 场景不可用，已切换 2D 列表"), true);
    },
  });
  if (!hiveScene) hiveSceneDead = true;
  return hiveScene;
}

async function openHiveMonitorLog(runId, rel, cell) {
  if (!rel) { toast(t("该步骤无日志"), true); return; }
  const dialog = $("hive-log-dialog"), title = $("hive-log-title"), meta = $("hive-log-meta"), pre = $("hive-log-text"), error = $("hive-log-error");
  if (!dialog || !title || !meta || !pre) { hiveOpenLog(runId, rel); return; }
  if (hiveDialogPoll) { clearInterval(hiveDialogPoll); hiveDialogPoll = null; }
  hiveDialogKey = runId + "|" + rel;
  title.textContent = cell && cell.role ? t(cell.role) : rdLogStepLabel(runId, rel);
  const status = cell && cell.status ? t({ running: t("运行中"), done: t("完成"), queued: t("排队中"), failed: "失败", timeout: t("超时"), cancelled: t("已取消") }[cell.status] || cell.status) : "";
  meta.textContent = [status, cell && cell.displayAgent, cell && (cell.displayElapsed || cell.started_at)].filter(Boolean).join(" · ");
  pre.textContent = t("加载日志中…");
  if (error) error.textContent = "";
  if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", "");
  const load = async () => {
    try {
      const r = await api("/api/runs/" + encodeURIComponent(runId) + "/log?step=" + encodeURIComponent(rel) + "&pretty=1");
      if (hiveDialogKey !== runId + "|" + rel) return;
      pre.textContent = r.log || (r.step_status === "running" ? t("（等待输出…）") : t("（无输出）"));
      pre.scrollTop = pre.scrollHeight;
      if (r.step_status !== "running" && hiveDialogPoll) { clearInterval(hiveDialogPoll); hiveDialogPoll = null; }
    } catch (e) {
      if (error) error.textContent = t("日志读取失败：") + (e && e.message ? e.message : "");
    }
  };
  await load();
  if (cell && cell.status === "running") hiveDialogPoll = setInterval(load, 2500);
}

function closeHiveMonitorLog() {
  hiveDialogKey = "";
  if (hiveDialogPoll) { clearInterval(hiveDialogPoll); hiveDialogPoll = null; }
  const dialog = $("hive-log-dialog");
  if (dialog && dialog.open) dialog.close();
}

function setHiveSceneMode(mode, opts) {
  const viewport = $("rd-hive-viewport");
  if (!viewport) return;
  // Public mode selection is deliberately limited to the polished artwork and 2D list.
  // live3d remains callable by internal QA, but can never be restored from user state.
  // Keep the public high-fidelity artwork selectable; unknown values still
  // fall back to the 2D list, while live3d remains an internal QA mode.
  let selected = ["reference", "live3d", "2d"].includes(mode) ? mode : "2d";
  if (selected !== "2d") {
    const sc = ensureHiveScene();
    if (!sc) {
      selected = "2d";
      if (!(opts && opts.silent)) toast(t("当前环境不支持 WebGL，已切换 2D 列表"), true);
    }
  }
  hiveMode = selected;
  if (hiveScene) {
    hiveScene.setDisplayMode(selected);
    hiveScene.setActive(selected !== "2d");
  }
  viewport.classList.toggle("hive-mode-3d", selected === "reference");
  viewport.classList.toggle("hive-mode-live3d", selected === "live3d");
  viewport.classList.toggle("hive-mode-2d", selected === "2d");
  const tools = document.querySelector(".hive-scene-tools");
  if (tools) tools.classList.toggle("hive-2d", selected === "2d");
  setHiveSceneButtons(selected);
  const hint = document.querySelector(".hive-scene-hint");
  if (hint) {
    const hintKey = selected === "live3d"
      ? t("拖动旋转 · Shift+拖动平移 · 滚轮缩放 · 双击复位 · 点击屏幕看日志")
      : selected === "2d" ? t("点击格子看日志")
      : t("拖动平移 · 滚轮缩放 · 双击复位 · 点击屏幕看日志");
    hint.dataset.i18n = hintKey;
    hint.textContent = t(hintKey);
  }
  try { localStorage.setItem("orch.hiveView.v3", hiveMode); } catch (e) { /* 隐私模式等 */ }
}

let hiveFullscreenFallback = false;

function hiveFullscreenElement() {
  return document.fullscreenElement || document.webkitFullscreenElement || null;
}

function syncHiveFullscreenButton() {
  const stage = $("hive-scene-stage");
  const button = $("hive-scene-fullscreen");
  const active = !!stage && (hiveFullscreenElement() === stage || hiveFullscreenFallback);
  if (stage) stage.classList.toggle("is-fullscreen", active);
  document.body.classList.toggle("hive-fallback-fullscreen", active && hiveFullscreenFallback);
  if (!button) return;
  const textKey = active ? t("退出全屏") : t("全屏");
  const labelKey = active ? t("退出全屏") : t("进入全屏");
  button.dataset.i18n = textKey;
  button.dataset.i18nTitle = labelKey;
  button.dataset.i18nAria = labelKey;
  button.textContent = t(textKey);
  button.title = t(labelKey);
  button.setAttribute("aria-label", t(labelKey));
  button.setAttribute("aria-pressed", active ? "true" : "false");
}

async function toggleHiveFullscreen() {
  const stage = $("hive-scene-stage");
  if (!stage) return;
  try {
    if (hiveFullscreenElement() === stage) {
      const exit = document.exitFullscreen || document.webkitExitFullscreen;
      if (typeof exit === "function") await exit.call(document);
      hiveFullscreenFallback = false;
      syncHiveFullscreenButton();
      return;
    }
    if (hiveFullscreenFallback) {
      hiveFullscreenFallback = false;
      syncHiveFullscreenButton();
      return;
    }
    const request = stage.requestFullscreen || stage.webkitRequestFullscreen;
    if (typeof request !== "function" || document.fullscreenEnabled === false) {
      hiveFullscreenFallback = true;
      syncHiveFullscreenButton();
      return;
    }
    await request.call(stage);
    // Embedded shells can expose the API but reject the permission check or
    // resolve without changing fullscreenElement. Keep the button useful by
    // falling back to the same viewport-sized layout in those environments.
    if (hiveFullscreenElement() !== stage) hiveFullscreenFallback = true;
    syncHiveFullscreenButton();
  } catch (error) {
    hiveFullscreenFallback = true;
    syncHiveFullscreenButton();
  }
}

function setupHiveSceneControls() {
  const viewport = $("rd-hive-viewport");
  if (!viewport || viewport.dataset.controlsReady) return;
  viewport.dataset.controlsReady = "true";
  const fullscreenButton = $("hive-scene-fullscreen");
  if (fullscreenButton) fullscreenButton.addEventListener("click", toggleHiveFullscreen);
  document.addEventListener("fullscreenchange", syncHiveFullscreenButton);
  document.addEventListener("webkitfullscreenchange", syncHiveFullscreenButton);
  syncHiveFullscreenButton();
  const hiveDialog = $("hive-log-dialog");
  const hiveClose = $("hive-log-close");
  if (hiveClose) hiveClose.addEventListener("click", closeHiveMonitorLog);
  if (hiveDialog) hiveDialog.addEventListener("close", () => {
    hiveDialogKey = "";
    if (hiveDialogPoll) { clearInterval(hiveDialogPoll); hiveDialogPoll = null; }
  });
  document.querySelectorAll("[data-hive-view]").forEach((button) => {
    button.addEventListener("click", () => setHiveSceneMode(button.dataset.hiveView));
  });
  document.querySelectorAll("[data-hive-scene-action]").forEach((button) => {
    button.addEventListener("click", () => {
      if (hiveMode === "2d" || !hiveScene) return;
      if (button.dataset.hiveSceneAction === "reset") hiveScene.resetView();
      else hiveScene.zoomAt(button.dataset.hiveSceneAction === "zoom-in" ? 1 / 1.18 : 1.18);
    });
  });
  // 蜂巢默认 2D 列表（用户拍板 1013）。v2 曾把旧默认 "reference" 自动持久化，
  // 分不清「主动选择」还是「被动默认」——升 v3 只记用户点选的视图，没记录落 2D。
  let saved = "";
  try { saved = localStorage.getItem("orch.hiveView.v3") || ""; } catch (e) { /* ignore */ }
  if (saved !== "2d" && saved !== "reference") saved = "2d";
  setHiveSceneMode(saved, { silent: true });
}

/* renderHive → 场景数据翻译：泳道=蜂巢塔的一层，格子按状态映射高度/颜色。
 * 气泡卡 HTML 在这里用 esc() 拼好（场景端 innerHTML 直用，自己不转义）；
 * 运行中格子的尾巴/思考行留空，由场景每 2Hz 经 cellRefresh 回填。 */
function hiveSceneSync(run, lanes, byStage) {
  hiveRunId = run.id;
  for (const k of Object.keys(hiveLiveMeta)) delete hiveLiveMeta[k];
  const model = { runId: run.id, lanes: [] };
  lanes.forEach((stage, i) => {
    const list = byStage[stage];
    const hasRun = list.some((s) => s.status === "running");
    const settled = list.filter((s) => !["running", "queued"].includes(s.status)).length;
    model.lanes.push({
      name: stage, count: list.length, settled, active: hasRun,
      /* 工位悬停气泡（阶段级）：进度 + 最近落定步骤 */
      tip:
        '<b class="hg-tip-role">' + esc(stage) + "</b>" +
        '<i class="hg-tip-who">' + esc(settled + " / " + list.length) +
        (hasRun ? " · " + esc(t("进行中")) : "") + "</i>" +
        '<p class="hg-tip-tail">' +
        esc(list.filter((s) => !["running", "queued"].includes(s.status)).slice(-1).map((s) => s.role || "").join("")) +
        "</p>" +
        '<u class="hg-tip-meta">' + esc(t("点击工位看该阶段最新日志")) + "</u>",
      cells: list.slice(-8).map((s) => {
        const st = s.status === "queued" ? "queued"
          : s.status === "running" ? "running"
          : s.status === "failed" ? "failed"
          : s.status === "cancelled" ? "cancelled"
          : s.status === "timeout" ? "timeout" : "done";
        const who = s.agent_label || s.agent || "";
        const mdl = String(s.model || "").trim();
        const whoShow = who + (mdl ? " · " + mdl : "");
        const rel = s.log || "";
        if (st === "running") hiveLiveMeta[rel] = { started_at: s.started_at || "" };
        const concl = (verdictDigestText(s.summary) || String(s.summary || "")).replace(/\s+/g, " ").trim();
        const elapsed = s.duration_s != null ? s.duration_s + "s" : hiveElapsed(s.started_at);
        const stWord = { running: t("运行中"), done: t("完成"), failed: t("失败"),
          timeout: t("超时"), cancelled: t("已取消"), queued: t("排队中") }[st] || s.status;
        const metaBits = [stWord, elapsed, rel ? t("点击格子看日志") : ""].filter(Boolean).join(" · ");
        const tip =
          '<b class="hg-tip-role">' + esc(s.role || "") + "</b>" +
          (whoShow ? '<i class="hg-tip-who">' + esc(whoShow) + "</i>" : "") +
          '<p class="hg-tip-tail">' + (st === "running" ? "" : esc(concl)) + "</p>" +
          '<em class="hg-tip-think"></em>' +
          '<u class="hg-tip-meta">' + esc(metaBits) + "</u>";
        return {
          rel, role: s.role || "", status: st, tip,
          displayTail: st === "running" ? "" : concl,
          displayStatus: stWord,
          displayElapsed: elapsed,
          displayAgent: whoShow,
        };
      }),
    });
  });
  const sc = ensureHiveScene();
  if (!sc) return;
  sc.sync(model);                    // 2D 模式也同步：切回 3D 时数据即 ready（画布未激活零 GPU 开销）
  sc.setDisplayMode(hiveMode);
  sc.setActive(hiveMode !== "2d");
}

window.renderHive = function (run) {
  const box = $("rd-hive");
  if (!box) return;
  const steps = (run && run.steps) || [];
  if (!run || !steps.length) {
    hiveFullscreenFallback = false;
    syncHiveFullscreenButton();
    box.classList.add("hidden");
    stopHiveTick();
    if (hiveScene) hiveScene.setActive(false);
    return;
  }
  box.classList.remove("hidden");
  setupHiveSceneControls();
  // 按步骤首次出现顺序分泳道（流水线天然有序）
  const lanes = [], byStage = {};
  steps.forEach((s) => {
    const stg = hiveStage(s.role);
    if (!byStage[stg]) { byStage[stg] = []; lanes.push(stg); }
    byStage[stg].push(s);
  });
  const running = steps.filter((s) => s.status === "running");
  const sub = $("rd-hive-sub");
  if (sub) {
    const done = steps.filter((s) => ["done", "completed", "success"].includes(String(s.status || "").toLowerCase())).length;
    const issues = steps.filter((s) => ["failed", "timeout", "cancelled"].includes(String(s.status || "").toLowerCase())).length;
    sub.innerHTML = '<span class="hive-count hive-count-live"><i class="live-dot"></i>' +
      esc(t("在岗")) + " " + running.length + '</span>' +
      '<span class="hive-count hive-count-done">✓ ' + done + '</span>' +
      (issues ? '<span class="hive-count hive-count-issue">! ' + issues + '</span>' : "") +
      '<span class="hive-count hive-count-total">' + steps.length + ' ' + esc(t("步骤")) + '</span>' +
      '<span class="hive-hint">' + esc(t("点击步骤卡片查看 CLI 日志")) + '</span>';
  }
  const activeIdx = lanes.map((l) => byStage[l].some((s) => s.status === "running")).lastIndexOf(true);
  const cell = (s, laneIdx, cellIdx) => {
    // 五归一：取消/超时的格子不再冒充「完成」——与步骤芯片同三色体系
    const st = s.status === "running" || s.status === "queued" ? "running"
      : s.status === "failed" ? "failed"
      : s.status === "cancelled" ? "cancelled"
      : s.status === "timeout" ? "timeout" : "done";
    const who = s.agent_label || s.agent || "";
    // 当前使用的模型：起跑即有（解析到的链首），收尾以实际使用覆盖；空则不显示
    const model = String(s.model || "").trim();
    const whoShow = who + (model ? " · " + model : "");
    // 完成即给结论：终态格子定格在 summary（智能体最终回答/失败原因），
    // 悬停 title 展示全文；运行中格子才跟实时尾巴
    const concl = (verdictDigestText(s.summary) || String(s.summary || "")).replace(/\s+/g, " ").trim();
    const key = run.id + "|" + (s.log || "");
    if (st !== "running") { delete hiveTails[key]; delete hiveThink[key]; }
    const tailText = st === "running" ? (hiveTails[key] || concl) : concl;
    // 思考行（仅运行中）：内置智能体步骤自带 s.thinking（流式落盘），CLI 步骤
    // 由 hiveTick 从 pretty 日志提取【思考】行；终态格子的结论已定格，不再补
    const thinkText = st === "running"
      ? (hiveThink[key] ||
         (s.thinking ? "💭 " + String(s.thinking).replace(/\s+/g, " ").trim().slice(-180) : ""))
      : "";
    const title = [s.role, whoShow,
                   (s.duration_s != null ? s.duration_s + "s" : ""),
                   s.started_at ? t("开始于 ") + s.started_at : "",
                   (s.note ? "◆ " + s.note : "")].filter(Boolean).join(" · ")
      + (concl && st !== "running" ? "\n" + t("结论：") + concl : "");
    // --d：入场瀑布逐格延迟（泳道间 110ms + 同泳道逐格 45ms），样式端消费
    return '<div class="hive-cell st-' + st + (st === "running" ? " hc-breathe" : "") + '" role="button" tabindex="0"' +
      ' data-hive-run="' + esc(run.id) + '" data-hive-log="' + esc(s.log || "") + '"' +
      ' style="--d:' + (laneIdx * 110 + cellIdx * 45) + 'ms"' +
      ' title="' + esc(title) + '" ' +
      '>' +
      '<div class="hc-head">' +
      '<img class="hc-bee" src="icons/bee.svg" alt="" aria-hidden="true">' +
      '<span class="hc-role">' + esc(s.role || "") + "</span>" +
      '<span class="hc-who">' + esc(whoShow) + "</span></div>" +
      '<div class="hc-tail" data-log="' + esc(s.log || "") + '">' +
      esc(tailText) + "</div>" +
      // 运行中始终渲染 hc-think（空时高度为 0）：hiveTick 拉到思考片段后
      // 要有元素可写；终态格子连元素都不留
      (st === "running" ? '<div class="hc-think" data-think="' + esc(s.log || "") + '">' + esc(thinkText) + "</div>" : "") +
      '<div class="hc-meta"><span class="hc-elapsed" data-started="' + esc(s.started_at || "") + '">' +
      (s.duration_s != null ? s.duration_s + "s" : hiveElapsed(s.started_at)) + "</span>" +
      (st === "running" ? '<span class="hc-live"><i class="live-dot"></i>' + t("工作中") + "</span>" : "") +
      (st === "timeout" ? '<span class="hc-dead">⏱ ' + t("超时") + "</span>" : "") +
      (st === "cancelled" ? '<span class="hc-dead">' + t("已取消") + "</span>" : "") +
      (s.log ? '<span class="hc-log-link">' + esc(t("CLI 日志")) + "</span>" : "") +
      "</div></div>";
  };
  const dots = (list, laneIdx) => list.slice(-12).map((s, di) => {
    const dc = s.status === "running" ? "run" : s.status === "failed" ? "fail"
      : s.status === "cancelled" ? "cancel" : s.status === "timeout" ? "time" : "done";
    const stx = { running: t("运行中"), failed: t("失败"), cancelled: t("已取消"),
                  timeout: t("超时"), done: t("完成") }[dc] || s.status;
    // --d：与格子同款级联延迟——入场时整条轨道按执行顺序"哗"地点亮（进度回放感）
    return '<i class="ld ld-' + dc + '" style="--d:' + (laneIdx * 110 + di * 45) + 'ms"' +
      ' title="' + esc((s.role || "") + " · " + stx) + '"></i>';
  }).join("");
  $("rd-hive-cells").innerHTML = lanes.map((stage, i) => {
    const list = byStage[stage];
    const hasRun = list.some((s) => s.status === "running");
    // 无 running（终态回看）：全部视为已完成泳道；有 running 时 activeIdx 之前算完成
    const cls = hasRun ? "lane-active"
      : (activeIdx === -1 || i < activeIdx ? "lane-done" : "lane-idle");
    // 泳道头视觉 v2：阶段序号徽章（01/02…流水线站序）+ 已完成进度（settled/total）
    const settled = list.filter((s) => !["running", "queued"].includes(s.status)).length;
    const meter = list.length ? Math.round((settled / list.length) * 100) : 0;
    return '<div class="hive-lane ' + cls + '">' +
      '<div class="lane-head">' +
      '<span class="lane-idx">' + String(i + 1).padStart(2, "0") + "</span>" +
      '<span class="lane-name">' + esc(stage) + '</span>' +
      '<span class="lane-n">×' + list.length + "</span>" +
      (settled ? '<span class="lane-prog">' + settled + "/" + list.length + "</span>" : "") +
      '<span class="lane-meter" aria-label="' + meter + '%"><i style="width:' + meter + '%"></i></span>' +
      (hasRun ? '<span class="lane-live"><i class="live-dot"></i>' + t("进行中") + "</span>" : "") + "</div>" +
      '<div class="lane-track">' + dots(list, i) + "</div>" +
      '<div class="lane-cells">' + list.slice(-8).map((s, ci) => cell(s, i, ci)).join("") + "</div></div>";
  }).join('<div class="lane-flow" aria-hidden="true">'
    + '<svg class="flow-line flow-line-down" viewBox="0 0 36 44" aria-hidden="true">'
    + '<path class="flow-path" d="M14 2 C14 16 22 28 22 42"/><path class="flow-tip" d="M16 36 L22 43 L28 36"/></svg>'
    + '<svg class="flow-line flow-line-up" viewBox="0 0 36 44" aria-hidden="true">'
    + '<path class="flow-path" d="M22 2 C22 16 14 28 14 42"/><path class="flow-tip" d="M8 36 L14 43 L20 36"/></svg>'
    + '<span class="flow-bee"><img src="icons/bee.svg" alt="" aria-hidden="true"></span>'
    + '</div>');
  // 入场瀑布闸门：只按"结构"（泳道数/格数/状态构成）签名；运行中尾巴/秒表每 2s
  // 变化不能触重播。签名没变就不动 DOM——格子不闪、动画不重启、悬停不弹手。
  const sig = lanes.map((l) => l + ":" + byStage[l].length + "(" +
    byStage[l].map((s) => s.status[0] || "?").join("") + ")").join("|");
  const cellsBox = $("rd-hive-cells");
  if (cellsBox.dataset.hiveSig !== sig) {
    const fresh = cellsBox.dataset.hiveSig == null;   // 首次展开详情也照播，先落框架再逐格亮起
    cellsBox.dataset.hiveSig = sig;
    // hive-enter 只在下一帧就摘（Rune/Hermes 式一闪而过的瀑布），全程保留会锁死
    // 入场帧；1400ms 定时是 RAF 被后台标签页冻结时的兜底。
    if (!fresh) cellsBox.classList.remove("hive-enter");
    cellsBox.classList.add("hive-enter");
    if (cellsBox._hiveEnterRAF) cancelAnimationFrame(cellsBox._hiveEnterRAF);
    cellsBox._hiveEnterRAF = requestAnimationFrame(() => {
      requestAnimationFrame(() => cellsBox.classList.remove("hive-enter"));
      cellsBox._hiveEnterRAF = null;
    });
    if (cellsBox._hiveEnterT) clearTimeout(cellsBox._hiveEnterT);
    cellsBox._hiveEnterT = setTimeout(() => cellsBox.classList.remove("hive-enter"), 1400);
  }
  hiveSceneSync(run, lanes, byStage);   // WebGL 蜂巢塔吃同一份泳道数据（内部自管激活）
  const live = running.length && (run.status === "running" || run.status === "queued");
  if (hiveClock) { clearInterval(hiveClock); hiveClock = null; }
  if (live) {
    if (!hiveTimer) hiveTimer = setInterval(() => hiveTick(run.id), 2000);
    hiveTick(run.id);
    // 秒表走动：running 卡计时每秒刷新，页面一眼可见"在动"
    hiveClock = setInterval(() => {
      document.querySelectorAll("#rd-hive-cells .hc-elapsed[data-started]").forEach((el) => {
        el.textContent = hiveElapsed(el.dataset.started);
      });
    }, 1000);
    // 日志抽屉一律手动打开（点蜂巢格/步骤行）：自动弹开会盖住对话输入条，
    // 用户要求所有页面默认不展示日志（2026-09-17）
  } else stopHiveTick();
  rdTabsSync();   // 蜂巢显隐直接决定「蜂巢」标签可用性
};

/* 活跃步骤的实时尾巴：拉 900 字符窗口，去噪后取最后一行正文。
 * 只刷运行中格子——终态格子的结论一旦定格，不再被命令回显覆盖。 */
async function hiveTick(rid) {
  if (document.hidden || !rid) return;
  // 换详情目标后旧蜂巢定时器必须停：先把 run.id 记下来，拉回来不是它就停表，
  // 否则 A 任务的步骤尾巴会持续写进 B 详情的蜂巢格
  if (!((S.inspData || {}).run || {}).id && S.detailRunId !== rid &&
      !(S.detailTaskKey && S.lastRun && S.lastRun.id === rid)) { stopHiveTick(); return; }
  const box = $("rd-hive-cells");
  if (!box) return;
  const rels = Array.from(box.querySelectorAll(".hive-cell.st-running .hc-tail[data-log]"))
    .map((el) => el.dataset.log).filter(Boolean);
  for (const rel of rels) {
    try {
      const r = await api("/api/runs/" + encodeURIComponent(rid) +
        "/log?step=" + encodeURIComponent(rel) + "&tail=2400&pretty=1");
      const lines = String(r.log || "").split("\n").filter((l) => l.trim());
      const last = hiveCleanLine(lines);
      const key = rid + "|" + rel;
      if (last && hiveTails[key] !== last) {
        hiveTails[key] = last;
        box.querySelectorAll(".hive-cell.st-running .hc-tail").forEach((el) => {
          if (el.dataset.log === rel) el.textContent = last;
        });
      }
      // 思考行与尾巴同源（pretty 日志）：有新【思考】片段就推进卡片
      const thk = hiveThinkLine(lines);
      if (thk && hiveThink[key] !== thk) {
        hiveThink[key] = thk;
        box.querySelectorAll(".hive-cell.st-running .hc-think").forEach((el) => {
          if (el.dataset.think === rel) el.textContent = thk;
        });
      }
    } catch (e) { /* 网络抖动保留上一帧 */ }
  }
}

/* 蜂巢格点击 → 打开该步骤实时日志（toggleLog 自带 2.5s 跟随 + 贴底滚动） */
window.hiveOpenLog = function (runId, rel) {
  if (!rel) { toast(t("该步骤无日志"), true); return; }
  toggleLog(runId, rel);
};

function stopLogLive() { if (S.logLive) { clearInterval(S.logLive); S.logLive = null; } }

async function cancelRun() {
  // 任务级详情没有 S.detailRunId，取消目标用渲染时钉好的 cancelTargetRunId
  const rid = S.detailRunId || S.cancelTargetRunId;
  if (!rid) return;
  if (!await uiConfirm(t("确定取消该运行？运行将立即强制终止。"), { ok: t("确定") })) return;
  let r;
  try {
    r = await api("/api/runs/" + encodeURIComponent(rid) + "/cancel", { method: "POST" });
  } catch (e) { toast(t("取消失败：") + (e && e.message ? e.message : t("网络异常")), true); return; }
  toast(r && r.ok ? t("已强制终止运行") : t("该运行已结束，无需取消"));
}

/* 立即重试：跳过自动续跑的退避等待，马上把续跑副本入队。任务级详情没有
 * S.detailRunId，目标用渲染时钉好的 resumeNowRunId（与 cancel 同款约定）。 */
async function resumeNow() {
  const rid = S.detailRunId || S.resumeNowRunId;
  if (!rid) return;
  let r;
  try {
    r = await api("/api/runs/" + encodeURIComponent(rid) + "/resume_now", { method: "POST" });
  } catch (e) { toast(t("操作失败：") + (e && e.message ? e.message : t("网络异常")), true); return; }
  if (r && r.ok) {
    toast(t("已跳过等待，马上继续"));
    chatJumpLatest();   // 续跑副本接着跑：新步骤落时间线尾部，跳过去看最新
    refreshState();   // 后端 bump 也会推 SSE，这里主动刷一轮让按钮立刻消失
  } else {
    toast((r && r.error) || t("操作失败"), true);
  }
}

/* 强制起跑：人工判定两个任务不冲突，跳过工作目录互斥立即并行。任务级详情
 * 没有 S.detailRunId，目标用渲染时钉好的 forceStartRunId（与 resumeNow 同款
 * 约定）。确认弹窗明示共享状态风险，同意才发请求。 */
async function forceStart() {
  const rid = S.detailRunId || S.forceStartRunId;
  if (!rid) return;
  const ok = await uiConfirm(
    t("强制并行起跑：两个任务将共用同一工作目录的任务计划与项目记忆，可能互相覆盖。确认它们互不冲突？"),
    { ok: t("强制起跑") });
  if (!ok) return;
  let r;
  try {
    r = await api("/api/runs/" + encodeURIComponent(rid) + "/force_start", { method: "POST" });
  } catch (e) { toast(t("操作失败：") + (e && e.message ? e.message : t("网络异常")), true); return; }
  if (r && r.ok) {
    toast(t("已强制起跑，与占用任务并行"));
    chatJumpLatest();
    refreshState();
  } else {
    toast((r && r.error) || t("操作失败"), true);
  }
}

/* ---------------------------------------------------- 运行中指挥（消息信箱） */
/* 用户在详情页往运行中的任务「递话」：文字 + 附件（截图/文件）。
 * 无头 CLI 插不进正在跑的进程，指令在下一次步骤下达前由后端 drain 注入。
 * 附件先 POST /api/attachments 进待提交区拿 id，发送时随消息一起提交到工作目录。 */
const DIR_ATT_MAX = 12;
const DIR_ATT_BYTES = 8 * 1024 * 1024;
let dirAtts = [];        // [{id,name,size}] 已上传待发送的附件
let dirRunId = null;     // 指挥区当前指向的 run

function fileToB64(file) {
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onload = () => resolve(String(fr.result).split(",")[1] || "");
    fr.onerror = () => reject(new Error(t("读取文件失败")));
    fr.readAsDataURL(file);
  });
}

async function dirUploadFiles(files) {
  for (const f of files) {
    if (dirAtts.length >= DIR_ATT_MAX) { toast(t("附件最多 ") + DIR_ATT_MAX + t(" 个"), true); break; }
    if (f.size > DIR_ATT_BYTES) { toast(f.name + t("：超过 8MB，已跳过"), true); continue; }
    try {
      const b64 = await fileToB64(f);
      const d = await api("/api/attachments", { method: "POST",
        body: JSON.stringify({ name: f.name, data: b64 }) });
      if (d.attachment) dirAtts.push(d.attachment);
    } catch (e) { toast(t("附件上传失败：") + e.message, true); }
  }
  drawDirAtts();
}

function drawDirAtts() {
  const box = $("rd-attach-list");
  if (!box) return;
  box.innerHTML = dirAtts.map((a, i) =>
    '<span class="att-chip2">' + esc(a.name) + "<b onclick=\"dirRemoveAtt(" + i + ")\" title=\"" +
    t("移除") + "\">×</b></span>").join("");
}
window.dirRemoveAtt = function (i) { dirAtts.splice(i, 1); drawDirAtts(); };

/* 渲染指挥区：只认当前详情页指向的运行；messages 随 run 对象来（SSE 刷新即更新）。
 * 放在「蜂巢」分区蜂巢下方——运行中的驾驶舱：看着蜜蜂干活，随手递话/贴截图。 */
function renderDirector(run, active) {
  const box = $("rd-direct");
  if (!box) return;
  if (!run || !active) { box.classList.add("hidden"); return; }
  if (dirRunId !== run.id) { dirRunId = run.id; dirAtts = []; drawDirAtts(); }
  box.classList.remove("hidden");
  const cached = _runMessagesCache.get(run.id);
  const expectedCount = run.message_count == null ? null : Number(run.message_count);
  const expectedPending = run.pending_message_count == null ? null : Number(run.pending_message_count);
  const runMessages = Array.isArray(run.messages) ? run.messages : null;
  const runPending = runMessages ? runMessages.filter((m) => !m.consumed).length : null;
  const runMessagesCurrent = !!runMessages && (expectedCount == null ||
    (runMessages.length === expectedCount && runPending === expectedPending));
  const msgs = runMessagesCurrent ? runMessages : (cached ? cached.messages : []);
  if (runMessagesCurrent) {
    const pending = msgs.filter((m) => !m.consumed).length;
    _runMessagesCache.set(run.id, { messages: msgs, count: msgs.length, pending });
  }
  if (expectedCount != null) {
    const messageCache = _runMessagesCache.get(run.id);
    if (!messageCache || messageCache.count !== expectedCount || messageCache.pending !== expectedPending) {
      if (!_runMessagesInflight.has(run.id)) {
        const request = api("/api/runs/" + encodeURIComponent(run.id) + "/messages", { timeout: 10000 })
          .then((data) => {
            if (dirRunId !== run.id || !S.lastRun || S.lastRun.id !== run.id) return;
            const messages = (data && data.messages) || [];
            _runMessagesCache.clear();
            _runMessagesCache.set(run.id, {
              messages, count: messages.length,
              pending: messages.filter((m) => !m.consumed).length,
            });
            renderDirector(Object.assign({}, S.lastRun, { messages }),
              S.lastRun.status === "running" || S.lastRun.status === "queued");
          })
          .catch(() => {})
          .finally(() => _runMessagesInflight.delete(run.id));
        _runMessagesInflight.set(run.id, request);
      }
    }
  }
  const mb = $("rd-msgs");
  mb.innerHTML = msgs.map((m) =>
    '<div class="rd-msg' + (m.consumed ? " m-consumed" : "") + '">' +
    '<span class="m-when">' + esc(m.created_at || "") + "</span>" +
    '<span class="m-who">' + esc(m.sender || "") + "</span>" +
    esc(m.text || t("（仅附件）")) +
    ((m.attachments || []).length
      ? '<span class="m-atts">' + t("附件：") + m.attachments.map(esc).join(t("、")) + "</span>" : "") +
    (m.consumed && m.consumed_by && m.consumed_by.step
      ? '<span class="m-atts">' + t("已随步骤送达：") + "#" + Number(m.consumed_by.step) +
        " " + esc(m.consumed_by.role || "") + "</span>"
      : (m.consumed ? "" :
        '<button class="m-retract ghost small" title="' + esc(t("尚未送达，可撤回")) +
        '" onclick="dirRetract(\'' + jsq(String(m.id || "")) + '\')">' + t("撤回") + "</button>")) +
    "</div>").join("");
  const hint = $("rd-direct-hint");
  if (hint) hint.textContent = run.paused
    ? (run.pause_phase === "paused"
      ? t("已到达暂停点：当前步骤已结束，放行后继续")
      : t("暂停请求已接收：当前步骤完成后挂起"))
    : (msgs.some((m) => !m.consumed) ? t("将在下一个步骤开始前送达执行者") : "");
}

window.dirTogglePause = async function () {
  const run = S.lastRun;
  if (!run) return;
  const to = !run.paused;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(run.id) + "/pause",
      { method: "POST", body: JSON.stringify({ paused: to }) });
    toast(to
      ? (result && result.pause_phase === "paused"
        ? t("已到达暂停点：当前步骤已结束，放行后继续")
        : t("暂停请求已接收：当前步骤完成后挂起"))
      : t("已放行，继续执行"));
  } catch (e) { toast(t("操作失败：") + e.message, true); }
};

window.dirSend = async function () {
  if (!dirRunId) return;
  const ta = $("rd-msg-input");
  const text = (ta.value || "").trim();
  if (!text && !dirAtts.length) return;
  const btn = $("rd-send-btn");
  btn.disabled = true;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(dirRunId) + "/messages", {
      method: "POST",
      body: JSON.stringify({ text, attachments: dirAtts.map((a) => a.id) }),
    });
    ta.value = "";
    dirAtts = []; drawDirAtts();
    if (result.created_task) { toast(t("已新建 CodeBee 任务，开始执行")); jumpToRun(result.run_id); return; }
    toast(t("指令已入箱，将在下一个步骤下达"));
    // 不等 SSE 回程：本地立即拉一次该 run 刷新消息流
    const d = await api("/api/runs/" + encodeURIComponent(dirRunId));
    if (d.run && dirRunId === d.run.id) renderDirector(d.run,
      d.run.status === "running" || d.run.status === "queued");
  } catch (e) { toast(t("发送失败：") + e.message, true); }
  finally { btn.disabled = false; }
};

/* 撤回尚未下达的指令：drain 前从信箱删除；已随步骤送达的后端会拒绝。 */
window.dirRetract = async function (msgId) {
  if (!dirRunId || !msgId) return;
  try {
    await api("/api/runs/" + encodeURIComponent(dirRunId) + "/messages/retract", {
      method: "POST", body: JSON.stringify({ id: msgId }),
    });
    toast(t("指令已撤回，不会送达执行"));
  } catch (e) { toast(t("撤回失败：") + e.message, true); }
  // 本地立即重拉该 run 重画消息流（不等 SSE 回程）
  try {
    const d = await api("/api/runs/" + encodeURIComponent(dirRunId));
    if (d.run && dirRunId === d.run.id) renderDirector(d.run,
      d.run.status === "running" || d.run.status === "queued");
  } catch (e) { /* 下一轮轮询兜底 */ }
};

/* 人工干预（非直连任务）：运行中=递话入箱，下一个步骤开始前送达主智能体
 * （它判断后引导执行方向）；已结束=发送后自动断点续跑，主智能体带着
 * 反馈重新规划。后端链路：信箱 → retry 继承未消费消息 → 规划 peek/执行 drain。 */
window.rdTalkToggle = function () {
  const box = $("rd-talk");
  if (!box) return;
  const show = box.classList.contains("hidden");
  box.classList.toggle("hidden", !show);
  const hint = $("rd-talk-hint");
  if (hint) {
    const run = S.lastRun;
    const active = !!run && (run.status === "running" || run.status === "queued");
    hint.textContent = active ? t("运行中：下一个步骤开始前送达主智能体")
      : t("已结束：发送后自动断点续跑，主智能体带着反馈重新规划");
  }
  if (show) { const ta = $("rd-talk-input"); if (ta) setTimeout(() => ta.focus(), 0); }
};

window.rdTalkSend = async function () {
  const run = S.lastRun;
  const ta = $("rd-talk-input");
  const text = ((ta && ta.value) || "").trim();
  if (!run || !run.id) return;
  if (!text && !talkAtts.length) { if (ta) ta.focus(); return; }
  const btn = $("rd-talk-send");
  btn.disabled = true;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(run.id) + "/messages",
      { method: "POST", body: JSON.stringify({ text, attachments: talkAtts.map((a) => a.id) }) });
    if (ta) ta.value = "";
    talkAtts = []; drawTalkAtts();
    const box = $("rd-talk");
    if (box) box.classList.add("hidden");
    if (result.created_task) { toast(t("已新建 CodeBee 任务，开始执行")); jumpToRun(result.run_id); return; }
    const active = run.status === "running" || run.status === "queued";
    if (!active && run.task_id) {
      await retryTask(run.task_id);
      toast(t("已转交：带着你的反馈断点续跑，主智能体会重新规划"));
    } else {
      toast(t("已递话：主智能体在下一个步骤开始前会看到"));
    }
  } catch (e) { toast(t("发送失败：") + e.message, true); }
  finally { btn.disabled = false; }
};

/* 递话附件：与运行中指挥同一落盘通道（/api/attachments 待提交区 → 随消息入箱） */
let talkAtts = [];
async function talkUploadFiles(files) {
  for (const f of files) {
    if (talkAtts.length >= DIR_ATT_MAX) { toast(t("附件最多 ") + DIR_ATT_MAX + t(" 个"), true); break; }
    if (f.size > DIR_ATT_BYTES) { toast(f.name + t("：超过 8MB，已跳过"), true); continue; }
    try {
      const b64 = await fileToB64(f);
      const d = await api("/api/attachments", { method: "POST",
        body: JSON.stringify({ name: f.name, data: b64 }) });
      if (d.attachment) talkAtts.push(d.attachment);
    } catch (e) { toast(t("附件上传失败：") + e.message, true); }
  }
  drawTalkAtts();
}
function drawTalkAtts() {
  const box = $("rd-talk-atts");
  if (!box) return;
  box.innerHTML = talkAtts.map((a, i) =>
    '<span class="att-chip2">' + esc(a.name) + "<b onclick=\"talkRemoveAtt(" + i + ')" title="' +
    t("移除") + "\">×</b></span>").join("");
}
window.talkRemoveAtt = function (i) { talkAtts.splice(i, 1); drawTalkAtts(); };

function bindDirector() {
  $("rd-attach-btn").addEventListener("click", () => $("rd-attach-file").click());
  $("btn-pause").addEventListener("click", window.dirTogglePause);
  $("rd-attach-file").addEventListener("change", (e) => {
    dirUploadFiles(Array.from(e.target.files || []));
    e.target.value = "";  // 允许再次选同名文件
  });
  $("rd-send-btn").addEventListener("click", window.dirSend);
  $("rd-msg-input").addEventListener("keydown", (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); window.dirSend(); }
  });
  // 粘贴截图：图片走上传，纯文本交回默认行为
  $("rd-msg-input").addEventListener("paste", (e) => {
    const items = Array.from((e.clipboardData || {}).items || [])
      .filter((it) => it.kind === "file" && it.type.startsWith("image/"));
    if (!items.length) return;
    e.preventDefault();
    const files = items.map((it) => {
      const f = it.getAsFile();
      return f && !f.name ? new File([f], "paste-" + Date.now() + ".png", { type: f.type }) : f;
    }).filter(Boolean);
    dirUploadFiles(files);
  });
}


/* ---------------- 对话分区（所有任务默认视图） ----------------
 * 时间线把任务目标、用户消息与各智能体每轮输出混排成气泡；蜂巢/步骤/成果
 * 仍是同一详情工作区的辅助分区。运行中发送 = 信箱（下一步送达）；已结束发送
 * = /chat（后端自动起新一轮 run 接着做）。默认排队；需要改变方向时，用户可选
 * 「立即发送并引导」，系统会先停止当前轮、等待旧写入者退出，再安全起新轮。 */
let chatRunId = null;
let chatAtts = [];
let chatTimelineItems = [];   // renderChat 每次重建时间线时刷新；复制/编辑重发按索引回查
let chatSending = false;

function chatCloseSendMenu() {
  const menu = $("rd-chat-send-menu"), toggle = $("rd-chat-send-options");
  if (menu) menu.classList.add("hidden");
  if (toggle) toggle.setAttribute("aria-expanded", "false");
}

function syncChatSendControls(run = S.lastRun || {}) {
  const active = run.status === "running" || run.status === "queued";
  const shortcut = /Mac|iPhone|iPad/.test(navigator.platform || "") ? "⌘+Enter" : "Ctrl+Enter";
  const ready = !!(($("rd-chat-input")?.value || "").trim() || chatAtts.length);
  const send = $("rd-chat-send"), options = $("rd-chat-send-options");
  if (send) {
    send.disabled = chatSending || !ready;
    send.title = active ? t("排队（默认）") + " · Enter" : t("发送") + " · Enter";
    send.setAttribute("aria-label", active ? t("排队（默认）") : t("发送"));
  }
  if ($("rd-chat-send-label")) $("rd-chat-send-label").textContent = t(active ? t("排队") : t("发送"));
  if (options) { options.classList.toggle("hidden", !active || !ready); options.disabled = chatSending; }
  if (send) send.classList.toggle("hidden", active && !ready);
  const stop = $("rd-chat-stop");
  if (stop) { stop.classList.toggle("hidden", !active || ready); stop.disabled = chatSending; }
  if (!active) chatCloseSendMenu();
  document.querySelectorAll("[data-chat-delivery]").forEach(button => { button.disabled = chatSending || !ready; });
  document.querySelectorAll("[data-chat-steer], [data-chat-retract]").forEach(button => {
    button.disabled = chatSending;
  });
  document.querySelectorAll("[data-chat-now-shortcut]").forEach(label => { label.textContent = shortcut; });
  const hint = $("rd-chat-hint");
  if (hint) hint.textContent = active
    ? t("Enter 默认排队 · {0} 立即发送并引导 · Shift+Enter 换行", shortcut)
    : t("Enter 发送 · Shift+Enter 换行");
}

/* 聊天正文协议清洗：剥 DIRECT_DONE/<followups> 尾巴与「本轮做了什么」复读头。
 * 渲染与「复制」共用同一口径——复制出来的就是看到的内容。 */
function chatCleanText(raw) {
  return String(raw || "")
    .replace(/^\s*本轮做了什么\s*[：:][^\n]*\n+(回复\s*[：:]\s*\n?)?/, "")
    .replace(/\n*DIRECT_DONE:.*\s*$/s, "")
    .replace(/\n*<followups>[\s\S]*?<\/followups>\s*$/s, "")
    .trim();
}

/* 对话记忆手动压缩（A4，dsh /compact 借鉴）：把当前对话任务的历史输出交给
 * 编排者模型滚动摘要，之后的续轮自动携带「之前对话摘要」块——长对话里
 * 早前的决策不再只剩「上一轮输出尾部 3000 字」。 */
async function chatSummarizeDirect() {
  const run = S.lastRun || {};
  const taskId = run.task_id;
  if (!taskId) return toast(t("当前对话没有任务归属，无法总结"));
  const btn = $("rd-chat-summarize");
  if (btn) { btn.disabled = true; }
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/direct-summary", {
      method: "POST", body: "{}" });
    if (data && data.ok && data.summary)
      toast(t("已生成对话摘要（{0} 字，覆盖 {1} 轮），续轮自动携带",
        String(data.summary.text || "").length, String(data.summary.runs_covered || 0)));
    else toast(t("摘要生成失败"));
  } catch (e) {
    toast(t("摘要生成失败：") + (e.message || ""));
  } finally {
    if (btn) { btn.disabled = false; }
  }
}

/* 评审裁定 JSON 原文 → 结构化摘要（文本摘要与结构化评审卡共用一份解析）。
 * 后端已把新 run 的步骤 summary 落成摘要（runner_parsing.verdict_brief），
 * 但历史 run 的 summary/对话 output 已按 ```json 原文落盘，前端同样兜底。
 * 识别不出裁定形状（含被截断的残文，走 scores 片区抢分数对）返回 null，
 * 调用方回退原文；普通回答永远原样放行。 */
function verdictDigestData(txt) {
  const s = String(txt || "").trim();
  if (!s || s.indexOf('"scores"') < 0) return null;
  let obj = null;
  const fence = s.match(/```(?:json)?\s*(\{[\s\S]*?)(?:```|$)/);
  const bare = (/^\{[\s\S]*\}$/.test(s) ? s : (fence ? fence[1] : ""))
    .replace(/\s+$/, "");
  if (bare) { try { obj = JSON.parse(bare); } catch (e) { obj = null; } }
  let dims = null, issues = null, concl = "", pass = null;
  if (obj && obj.scores && typeof obj.scores === "object" && !Array.isArray(obj.scores)) {
    dims = Object.keys(obj.scores).map((k) => [k, Number(obj.scores[k])])
      .filter((pair) => Number.isFinite(pair[1]));
    issues = Array.isArray(obj.issues) ? obj.issues
      : (Array.isArray(obj.findings) ? obj.findings : null);
    concl = String(obj.summary || "");
    pass = typeof obj.pass === "boolean" ? obj.pass : null;
  } else {
    // 截断残文：只从 "scores": { … } 片区抢「维度: 数值」对（截在 600 字
    // 的老 summary 解析不了整对象，但分数表通常在前排完好）
    const sm = s.match(/"scores"\s*:\s*\{([\s\S]*?)(?:\}|$)/);
    if (!sm) return null;
    dims = (sm[1].match(/"([^"\\]{1,24})"\s*:\s*\d+(?:\.\d+)?/g) || [])
      .map((pair) => pair.match(/"([^"\\]{1,24})"\s*:\s*(\d+(?:\.\d+)?)/))
      .filter(Boolean)
      .map((mm) => [mm[1], Number(mm[2])]);
  }
  if (!dims.length) return null;
  const rows = (Array.isArray(issues) ? issues : [])
    .filter((it) => it && typeof it === "object")
    .map((it) => ({
      sev: String(it.severity || "").trim(),
      dim: String(it.dim || it.path || "").trim(),
      note: String(it.note || it.header || it.detail || "").replace(/\s+/g, " ").trim(),
    })).filter((it) => it.dim || it.note);
  return {
    pass, dims, issues: rows,
    avg: dims.reduce((a, d) => a + d[1], 0) / dims.length,
    concl: concl.replace(/\s+/g, " ").trim(),
  };
}

/* 结构化摘要 → 人读短文本（multi=true 多行版）。
 * 对话时间线另走结构化评审卡，这里服务步骤摘要与「复制」同口径。 */
function verdictDigestText(txt, multi) {
  const d = verdictDigestData(txt);
  if (!d) return "";
  const passHead = d.pass === false ? "评审未通过，" : d.pass === true ? "评审通过，" : "";
  const head = passHead + "均分 " + d.avg.toFixed(1);
  const dimTxt = d.dims.slice(0, 6).map((x) => x[0] + " " + x[1].toFixed(1)).join(" · ");
  if (!multi) {
    let out = head + "（" + dimTxt + "）";
    if (d.concl) out += "：" + d.concl.slice(0, 90);
    return out.slice(0, 240);
  }
  const lines = [head + "（" + dimTxt + "）"];
  if (d.concl) lines.push("结论：" + d.concl.slice(0, 200));
  if (d.issues.length) {
    lines.push("意见 " + d.issues.length + " 条：");
    for (const it of d.issues.slice(0, 6)) {
      const body = it.dim && it.note ? it.dim + "：" + it.note.slice(0, 110)
        : (it.note || it.dim);
      if (body) lines.push("· " + (it.sev ? "[" + it.sev + "] " : "") + body);
    }
  }
  return lines.join("\n").slice(0, 1000);
}

const CHAT_ICON_WARN = '<svg class="ico" aria-hidden="true" viewBox="0 0 24 24">' +
  '<path d="M12 3 2.5 20h19L12 3Z"/><path d="M12 10v4"/><path d="M12 17.2v.1"/></svg>';
const CHAT_ICON_REVIEW = '<svg class="ico" aria-hidden="true" viewBox="0 0 24 24">' +
  '<path d="M9 4h6"/><path d="M8 2h8a1 1 0 0 1 1 1v3H7V3a1 1 0 0 1 1-1Z"/>' +
  '<path d="M7 4H4v18h16V4h-3"/><path d="m9 12 2 2 4-4"/></svg>';

/* 时间显示统一收敛到 HH:MM（日期在 meta 条里，全量戳塞气泡就是噪音）。 */
function chatTimeText(v) {
  const s = String(v || "");
  return /^\d{4}-\d{2}-\d{2}[ T]/.test(s) ? s.slice(11, 16) : s;
}

function chatItemDur(it) {
  return (typeof it.duration_s === "number" && Number.isFinite(it.duration_s) && it.duration_s >= 0)
    ? t("用时") + " " + chatDurTxt(it.duration_s) : "";
}

function chatMetaLine(it) {
  return [String(it.who || "").trim(), chatTimeText(it.at), chatItemDur(it)]
    .filter(Boolean).join(" · ");
}

function chatCopyAction(idx) {
  return '<span class="chat-acts2"><button type="button" class="chat-act" data-cact="copy" data-ci="' +
    idx + '">' + esc(t("复制")) + "</button></span>";
}

/* 失败输出拆成「退出码/原因 + 原始 stderr + 后端诊断」三段。后端写法见
 * runner._failure_output_detail 与 banner_only 括注：
 * 「退出码 1；stderr/stdout: > build · …（仅启动横幅、无错误文本：疑似…）」。
 * 识别不出这个形状（捕获上限、codex/claude 定制错误）整段当正文，不硬拆。 */
function chatFailureParts(raw) {
  const text = String(raw || "").trim();
  if (!text) return null;
  let head = "", rest = text;
  const m = text.match(/^([^；;\n]{1,80}?)[；;]\s*stderr\/stdout\s*[:：]\s*([\s\S]*)$/)
    || text.match(/^(退出码\s*-?\d+|超时|取消|任务总时限已到|输出停滞[^；;\n]*)[；;]\s*([\s\S]*)$/);
  if (m) { head = m[1].trim(); rest = m[2].trim(); }
  let code = "", reason = head;
  const cm = head.match(/^退出码\s*(-?\d+)$/);
  if (cm) { code = cm[1]; reason = ""; }
  // 尾部括注含全角/半角冒号才是后端追加的诊断；真实 stderr 尾部的括注
  // 极少带冒号，误判的代价也只是把同一段话换个颜色展示。
  let diag = "";
  const dm = rest.match(/^([\s\S]*?)[（(]([^（）()\n]*[：:][^（）()\n]*)）$/);
  if (dm) { rest = dm[1].trim(); diag = dm[2].trim(); }
  return { code, reason, detail: rest, diag };
}

function chatFailBodyHTML(p) {
  if (!p) return "";
  const raw = p.detail
    ? (p.code || p.reason
      ? '<span class="chat-fail-tag">stderr/stdout</span><code>' + esc(p.detail) + "</code>"
      : esc(p.detail))
    : "";
  const diag = p.diag ? '<span class="chat-fail-diag">（' + esc(p.diag) + "）</span>" : "";
  return raw || diag ? '<div class="chat-fail-body">' + raw + diag + "</div>" : "";
}

function chatFailCodeChip(code) {
  return code ? '<span class="chat-fail-code">' + esc(t("退出码")) + " " + esc(code) + "</span>" : "";
}

/* 单个失败步骤：红卡把「执行失败」从正文里的一个词提成状态标题，退出码
 * 单独成标签，正文只留可读报错（2026-10-22 用户反馈：失败与答案同形，
 * 串场的失败墙分不清哪条是结果）。 */
function chatFailCardHTML(it, idx, raw) {
  const p = chatFailureParts(raw) || { code: "", reason: "", detail: String(raw || ""), diag: "" };
  return '<div class="chat-fail-card">' +
    '<div class="chat-fail-head">' +
    '<span class="chat-fail-title">' + CHAT_ICON_WARN + esc(t("执行失败")) + "</span>" +
    chatFailCodeChip(p.code) +
    (p.reason ? '<span class="chat-fail-reason">' + esc(p.reason) + "</span>" : "") +
    '<span class="chat-fail-meta">' + esc(chatMetaLine(it)) + chatCopyAction(idx) + "</span>" +
    "</div>" + chatFailBodyHTML(p) + "</div>";
}

/* 连续同文失败合并：同一 CLI 同一报错连发三次时，报错只写一遍，逐次尝试
 * 只留时间/用时行。单条失败仍走 chatFailCardHTML（不丢细节）。 */
function chatFailGroupHTML(list, idx) {
  const first = list[0];
  const p = chatFailureParts(chatCleanText(first.text))
    || { code: "", reason: "", detail: chatCleanText(first.text), diag: "" };
  const rows = list.map((it, i) =>
    '<li class="chat-fail-attempt"><b>' + esc(chatTimeText(it.at)) + "</b>" +
    (chatItemDur(it) ? "<span>" + esc(chatItemDur(it)) + "</span>" : "") +
    '<span class="chat-fail-nth">' + esc(t("第 {0} 次", i + 1)) + "</span></li>").join("");
  return '<div class="chat-fail-card chat-fail-group">' +
    '<div class="chat-fail-head">' +
    '<span class="chat-fail-title">' + CHAT_ICON_WARN +
    esc(t("同一失败连续 {0} 次", list.length)) + "</span>" +
    chatFailCodeChip(p.code) +
    (p.reason ? '<span class="chat-fail-reason">' + esc(p.reason) + "</span>" : "") +
    '<span class="chat-fail-meta">' + esc(String(first.who || "").trim()) +
    chatCopyAction(idx) + "</span>" +
    "</div>" + chatFailBodyHTML(p) +
    '<ul class="chat-fail-attempts">' + rows + "</ul></div>";
}

/* 评审裁定从「一整段 JSON/摘要正文」改成结构卡：均分 + 维度分数一行，
 * 意见按严重度标签分行（2026-10-22 用户反馈「展示这么一大堆根本没人看」）。 */
function chatReviewHTML(it, idx, d) {
  const flag = d.pass === false
    ? '<span class="chat-review-flag bad">' + esc(t("未通过")) + "</span>"
    : (d.pass === true ? '<span class="chat-review-flag ok">' + esc(t("通过")) + "</span>" : "");
  const scores = '<span class="chat-review-avg">' + esc(t("均分")) + " " +
    esc(d.avg.toFixed(1)) + "</span>" +
    d.dims.slice(0, 8).map((x) =>
      '<span class="chat-score-chip">' + esc(x[0]) + "<b>" + esc(x[1].toFixed(1)) + "</b></span>").join("");
  const items = d.issues.slice(0, 6).map((x) => {
    const sev = /^(minor|major|critical)$/.test(x.sev) ? x.sev : "";
    const note = x.note.length > 180 ? x.note.slice(0, 180) + "…" : x.note;
    return '<li class="chat-review-item">' +
      (x.sev ? '<span class="chat-sev' + (sev ? " " + sev : "") + '">' + esc(x.sev) + "</span>" : "") +
      "<div>" + (x.dim ? '<span class="chat-review-dim">' + esc(x.dim) + "：</span>" : "") +
      (note ? '<span class="chat-review-note">' + esc(note) + "</span>" : "") + "</div></li>";
  }).join("");
  return '<div class="chat-review-card">' +
    '<div class="chat-review-head">' +
    '<span class="chat-review-title">' + CHAT_ICON_REVIEW + esc(t("评审意见")) + "</span>" + flag +
    '<span class="chat-review-meta">' + esc(chatMetaLine(it)) + chatCopyAction(idx) + "</span>" +
    "</div>" +
    '<div class="chat-review-scores">' + scores + "</div>" +
    (d.concl ? '<div class="chat-review-lead">' + esc(d.concl.slice(0, 240)) + "</div>" : "") +
    (items ? '<ul class="chat-review-list">' + items + "</ul>" : "") +
    (d.issues.length > 6
      ? '<div class="chat-review-more">' +
        esc(t("…其余 {0} 条见该步日志", d.issues.length - 6)) + "</div>"
      : "") +
    "</div>";
}
let chatSig = "";
let chatLiveSig = "";        // 时间线实时增量签名（思考/正文长度变才重建 DOM）
let chatLiveTimer = null;    // 运行中快轮询句柄（1.2s，见 scheduleChatLive）
let chatLiveRunId = null;
const chatLogOpen = new Set(), chatLogClosed = new Set(), chatLogCache = new Map(), chatLogInflight = new Set(), chatLogFetchedAt = new Map();
const chatActivityCache = new Map(), chatDisclosureState = new Map();
let chatForceBottom = false; // 强制贴底一次（不管当时滚到哪，都要看到最新内容）；发送消息、继续任务、打开详情共用

// 对话右侧工作区：复用本机目录 API，让用户可以在查看 CLI 日志的同时打开、
// 修改并保存当前任务工作目录中的文本文件。状态与时间线分离，轮询重绘不会丢失编辑内容。
const chatWorkspaceState = {
  open: false, dir: "", files: [], current: "", mtime: "", dirty: false, runId: "",
};
const CHAT_WORKSPACE_TEXT_EXT = new Set((
  "txt md markdown log csv json jsonl yaml yml toml ini cfg conf py js mjs cjs ts tsx jsx " +
  "html htm css scss sass less xml svg sql sh bash ps1 bat cmd go rs java kt kts swift " +
  "c h cc cpp hpp cs php rb pl lua r vue svelte astro env gitignore dockerfile makefile " +
  "properties gradle rst tex").split(/\s+/));

function chatWorkspaceTask(run) {
  const all = (S.state && (S.state.tasks || []).concat(S.state.archived_tasks || [])) || [];
  return all.find((task) => task.id === (run && run.task_id)) || null;
}

function chatWorkspaceSetState(text, bad) {
  const el = $("rd-chat-editor-state");
  if (!el) return;
  el.textContent = text || "";
  el.classList.toggle("bad", !!bad);
}

function chatWorkspaceTree(files) {
  const root = { dirs: {}, files: [] };
  (files || []).forEach((file) => {
    const parts = String(file.name || "").split("/").filter(Boolean);
    if (!parts.length) return;
    let node = root;
    parts.slice(0, -1).forEach((part) => {
      node = node.dirs[part] || (node.dirs[part] = { dirs: {}, files: [] });
    });
    node.files.push(file);
  });
  return root;
}

function chatWorkspaceFileTreeHTML(node, depth) {
  const dirs = Object.keys(node.dirs || {}).sort((a, b) => a.localeCompare(b));
  const files = (node.files || []).slice().sort((a, b) =>
    String(a.name).localeCompare(String(b.name), undefined, { numeric: true }));
  return dirs.map((name) => {
    const child = node.dirs[name];
    return '<details class="rd-chat-file-dir"' + (depth === 0 ? ' open' : '') +
      '><summary title="' + esc(name) + '"><svg class="ico rd-chat-dir-chevron" aria-hidden="true"><use href="#i-chevron-r"></use></svg>' +
      '<svg class="ico" aria-hidden="true"><use href="#i-folder"></use></svg><span class="rd-chat-file-name">' + esc(name) + '</span>' +
      '</summary><div class="rd-chat-file-dir-children">' +
      chatWorkspaceFileTreeHTML(child, depth + 1) + "</div></details>";
  }).join("") + files.map((file) => {
    const name = String(file.name || "");
    const base = name.split("/").pop();
    return '<button type="button" class="rd-chat-file" data-chat-workspace-file="' + esc(name) +
      '" title="' + esc(name) + '"><svg class="ico rd-chat-file-icon" aria-hidden="true"><use href="#i-book"></use></svg>' +
      '<span class="rd-chat-file-name">' + esc(base) +
      '</span><span class="rd-chat-file-size">' + esc(fmtSize(file.size)) + "</span></button>";
  }).join("");
}

function chatWorkspaceRenderFiles() {
  const nav = $("rd-chat-workspace-files");
  if (!nav) return;
  // Editing only updates selection; preserve the tree's scroll and disclosure state.
  const sig = JSON.stringify([chatWorkspaceState.dir, document.documentElement.dataset.lang, chatWorkspaceState.files]);
  if (nav._workspaceSig !== sig) {
    nav._workspaceSig = sig;
    nav.innerHTML = chatWorkspaceState.files.length
      ? chatWorkspaceFileTreeHTML(chatWorkspaceTree(chatWorkspaceState.files), 0)
      : '<div class="rd-chat-workspace-empty">' + esc(t("该目录下暂无文件")) + "</div>";
  }
  nav.querySelectorAll("[data-chat-workspace-file]").forEach((button) => {
    const active = button.dataset.chatWorkspaceFile === chatWorkspaceState.current;
    button.classList.toggle("active", active);
    button.setAttribute("aria-current", active ? "true" : "false");
  });
}

function chatWorkspaceSyncLayout() {
  const box = $("rd-chat");
  const pane = $("rd-chat-workspace");
  if (!box || !pane) return;
  box.classList.toggle("chat-workspace-open", !!chatWorkspaceState.open);
  pane.classList.toggle("hidden", !chatWorkspaceState.open);
  const path = $("rd-chat-workspace-path");
  if (path) path.textContent = path.title = chatWorkspaceState.dir || "";
  const name = $("rd-chat-editor-name");
  if (name) name.textContent = name.title = chatWorkspaceState.current || t("选择文件");
  const empty = $("rd-chat-editor-empty");
  if (empty) empty.classList.toggle("hidden", !!chatWorkspaceState.current);
  const editor = $("rd-chat-editor-text");
  if (editor) editor.classList.toggle("hidden", !chatWorkspaceState.current);
  const save = document.querySelector("[data-chat-editor-save]");
  if (save) save.disabled = !chatWorkspaceState.current || !chatWorkspaceState.dirty;
  chatWorkspaceRenderFiles();
}

async function chatWorkspaceScan(run) {
  const task = chatWorkspaceTask(run);
  const dir = task && task.workdir;
  if (!dir) {
    chatWorkspaceSetState(t("当前任务没有工作目录"), true);
    return false;
  }
  chatWorkspaceState.dir = String(dir);
  chatWorkspaceState.runId = run && run.id || "";
  chatWorkspaceSetState(t("正在读取工作区…"));
  try {
    const data = await api("/api/dir/scan?path=" + encodeURIComponent(chatWorkspaceState.dir));
    if (!chatWorkspaceState.open || chatWorkspaceState.runId !== (run && run.id)) return false;
    chatWorkspaceState.files = Array.isArray(data && data.files) ? data.files : [];
    chatWorkspaceState.dir = String((data && data.path) || chatWorkspaceState.dir);
    chatWorkspaceSetState(chatWorkspaceState.files.length ? "" : t("该目录下暂无文件"));
    chatWorkspaceSyncLayout();
    return true;
  } catch (e) {
    chatWorkspaceState.files = [];
    chatWorkspaceSetState(t("读取工作区失败：") + (e.message || e), true);
    chatWorkspaceSyncLayout();
    return false;
  }
}

async function chatWorkspaceOpenFile(name) {
  if (!chatWorkspaceState.dir || !name) return;
  if (chatWorkspaceState.current === name) return;
  const ext = String(name).split("/").pop().split(".").pop().toLowerCase();
  if (!CHAT_WORKSPACE_TEXT_EXT.has(ext)) {
    chatWorkspaceSetState(t("此文件类型暂不支持文本编辑"), true);
    return;
  }
  if (chatWorkspaceState.dirty && chatWorkspaceState.current !== name) {
    const ok = await uiConfirm(t("有未保存的修改，确定切换文件？"));
    if (!ok) return;
  }
  const ta = $("rd-chat-editor-text");
  if (!ta) return;
  chatWorkspaceState.current = String(name);
  const requested = chatWorkspaceState.current;
  chatWorkspaceState.dirty = false;
  ta.value = "";
  ta.disabled = true;
  chatWorkspaceSetState(t("正在读取文件…"));
  chatWorkspaceSyncLayout();
  try {
    const url = urlAuth("/api/dir/file?dir=" + encodeURIComponent(chatWorkspaceState.dir) +
      "&name=" + encodeURIComponent(name));
    const response = await fetch(url, { headers: authHeaders() });
    if (!response.ok) throw new Error("HTTP " + response.status);
    const content = await response.text();
    if (chatWorkspaceState.current === requested) {
      ta.value = content;
      chatWorkspaceState.mtime = response.headers.get("X-Tutti-Mtime") || "";
      chatWorkspaceSetState("");
    }
  } catch (e) {
    chatWorkspaceSetState(t("读取文件失败：") + (e.message || e), true);
  } finally {
    ta.disabled = false;
    chatWorkspaceSyncLayout();
  }
}

async function chatWorkspaceSave() {
  const ta = $("rd-chat-editor-text");
  if (!ta || !chatWorkspaceState.current || !chatWorkspaceState.dirty) return;
  const save = document.querySelector("[data-chat-editor-save]");
  if (save) save.disabled = true;
  chatWorkspaceSetState(t("保存中…"));
  try {
    const data = await api("/api/dir/save", { method: "POST", body: JSON.stringify({
      dir: chatWorkspaceState.dir, name: chatWorkspaceState.current,
      content: ta.value, mtime: chatWorkspaceState.mtime,
    }) });
    chatWorkspaceState.mtime = String((data && data.mtime) || "");
    chatWorkspaceState.dirty = false;
    chatWorkspaceSetState(t("已保存"));
  } catch (e) {
    const msg = e && e.status === 409 ? t("文件已被外部修改，请重新打开后再保存") :
      t("保存失败：") + (e.message || e);
    chatWorkspaceSetState(msg, true);
    toast(msg, true);
  } finally { chatWorkspaceSyncLayout(); }
}

async function chatWorkspaceToggle(force) {
  const box = $("rd-chat");
  const run = S.lastRun;
  if (!box || !run) return;
  if (force === false || chatWorkspaceState.open) {
    if (chatWorkspaceState.dirty && !await uiConfirm(t("有未保存的修改，确定关闭？"))) return;
    chatWorkspaceState.open = false;
    chatWorkspaceSyncLayout();
    return;
  }
  const task = chatWorkspaceTask(run);
  if (!task || !task.workdir) { toast(t("当前任务没有工作目录"), true); return; }
  chatWorkspaceState.open = true;
  chatWorkspaceSyncLayout();
  await chatWorkspaceScan(run);
}
window.chatWorkspaceToggle = chatWorkspaceToggle;

/* 瞬时落底：.rd-chat-flow 带 scroll-behavior:smooth，直接赋值 scrollTop 会变
 * 成跨全时间的平滑滚动动画（长对话要滑近一秒，测试也会量到半途）——跳最新
 * 这类大跨度移动一律压成瞬时。 */
function chatScrollBottomNow(fl) {
  if (!fl) return;
  const prev = fl.style.scrollBehavior;
  fl.style.scrollBehavior = "auto";
  fl.scrollTop = fl.scrollHeight;
  fl.style.scrollBehavior = prev;
}

/* 让对话时间线跳到最新：置强制贴底标记（drawChatFlow 下一次重建时消费），
 * 并就现有内容先即时贴底，视觉零等待。「继续任务/立即续跑/继续连载」点完
 * 新一轮内容落在时间线尾部，用户要看到的是最新进展，不是停在原地或历史中间；
 * 首次打开详情同理。页签当前不可见时标记保留（drawChatFlow 不消费），
 * 切进对话页签时由 applyRdTabs 带到底。 */
function chatJumpLatest() {
  chatForceBottom = true;
  chatScrollBottomNow($("rd-chat-flow"));
}

function chatEngineIsDirect(run) {
  const st = S.state || {};
  const all = (st.tasks || []).concat(st.archived_tasks || []);
  const task = all.find((x) => x.id === (run && run.task_id));
  // 对话工作区是所有有任务归属的运行的共同入口；管理型孤立运行
  // 没有可续跑的任务，不显示可发送的对话框。
  return !!(task && task.id === (run && run.task_id));
}

/* 思考过程块（2026-09-22 用户诉求「把思考过程打印出来」）：内置智能体流式抓的
 * 模型思维链 + 工具活动。运行中=常开实时块（逐句长出来）；结束后=折叠摘要
 * （点开回看），不再让整轮只有三点打字动画。thinking 最长 2 万字（后端已截）。
 * 活动行是后端烤死的中文标签（activity 落库进步骤记录，老 run 也是中文），
 * 只能在渲染时翻：前缀命中「请求工具: 」就换字典词条，其余原样放行。 */
function chatActLine(a) {
  const s = String(a || "");
  const PRE = "请求工具: ";
  if (s.startsWith(PRE)) {
    return t("请求工具") + ": " + s.slice(PRE.length).replace(/、/g, t("、"));
  }
  return s;
}

function chatThinkHTML(it) {
  const running = it.status === "running";
  const think = String(it.thinking || "").trim();
  const acts = running ? (it.activity || []).slice(-8) : [];
  if (!think && !acts.length) return "";
  const shown = think.length > 12000 ? "…" + think.slice(-12000) : think;
  if (running) {
    return '<div class="chat-think live" data-think-live="1">' +
      '<div class="ct-head"><span class="ct-dot" aria-hidden="true"></span>' +
      (think ? esc(t("思考过程")) + '<span class="ct-live">' + esc(t("实时")) + "</span>" : esc(t("正在执行…"))) + "</div>" +
      (shown ? '<div class="ct-body">' + esc(shown) + "</div>" : "") +
      (acts.length ? '<div class="ct-acts">' +
        acts.map((a) => '<div class="chat-activity-row"><svg class="ico" aria-hidden="true"><use href="#i-code"></use></svg>' +
          '<span class="chat-activity-label" title="' + esc(chatActLine(a)) + '">' + esc(chatActLine(a)) + "</span></div>").join("") + "</div>" : "") +
      "</div>";
  }
  return '<details class="chat-think"><summary>' + esc(t("思考过程")) +
    '<span class="ct-len">' + think.length + " " + esc(t("字")) + "</span></summary>" +
    '<div class="ct-body">' + esc(think) + "</div></details>";
}

function chatAcpEventsHTML(it) {
  const rawEvents = Array.isArray(it.acp_events) ? it.acp_events.slice(-8) : [];
  if (!rawEvents.length) return "";
  // ACP can stream several updates for one compaction. Collapse those rows
  // so the latest eight visible items represent activities, not split chunks.
  const events = [];
  const compactions = new Map();
  for (const event of rawEvents) {
    const type = String(event?.sessionUpdate || "event");
    const compactionId = event?.compactionId;
    const mergeable = compactionId &&
      (type === "compaction_update" || type === "compaction_summary_chunk");
    if (!mergeable) {
      events.push(event);
      continue;
    }
    const key = String(compactionId);
    let merged = compactions.get(key);
    if (!merged) {
      merged = { ...event };
      compactions.set(key, merged);
      events.push(merged);
      continue;
    }
    if (type === "compaction_summary_chunk") {
      const part = typeof event.content === "string" ? event.content : "";
      if (part) {
        merged.content = [merged.content, part].filter(Boolean).join("\n").slice(0, 2400);
        merged._compactionHasChunks = true;
      }
    } else {
      const streamed = merged.content;
      Object.assign(merged, event);
      if (streamed && !merged.content) merged.content = streamed;
    }
  }
  const typeLabels = {
    compaction_update: t("上下文压缩"),
    compaction_summary_chunk: t("压缩摘要"),
    notice: t("通知"),
  };
  return '<details class="chat-think chat-acp-events"><summary>' + esc(t("ACP 活动")) +
    '<span class="ct-len">' + events.length + ' ' + esc(t("条")) + '</span></summary>' +
    '<div class="ct-acts">' + events.map((event) => {
      const type = String(event.sessionUpdate || "event");
      const title = type === "notice" ? event.title : "";
      const meta = [event.compactionId, event.status || event.severity]
        .filter((value) => value !== undefined && value !== null && String(value))
        .map((value) => esc(value)).join(" · ");
      const detail = type === "notice" ? event.description : event.error;
      const content = typeof event.content === "string" ? event.content : "";
      const summary = Array.isArray(event.summary) ? event.summary.map((block) =>
        block && block.type === "text" && block.text
          ? '<div class="rd-acp-summary">' + esc(block.text) + '</div>' : "").join("") : "";
      const entries = Array.isArray(event.entries) ? event.entries.map((entry) =>
        '<div class="rd-acp-plan-entry">' + esc(entry.status || "") + ' · ' + esc(entry.content || "") + '</div>').join("") : "";
      const label = typeLabels[type] || type;
      const chunkLabel = event._compactionHasChunks && type !== "compaction_summary_chunk"
        ? ' · ' + esc(t("压缩摘要")) : "";
      return '<div class="rd-acp-event"><div class="rd-acp-event-head"><code>' +
        esc(label) + chunkLabel + '</code>' + (meta ? ' · ' + meta : "") + '</div>' +
        (title ? '<div class="rd-acp-event-title">' + esc(title) + '</div>' : "") +
        (detail ? '<div class="rd-acp-event-detail">' + esc(detail) + '</div>' : "") +
        (content ? '<div class="rd-acp-summary">' + esc(content) + '</div>' : "") +
        summary + entries + '</div>';
    }).join("") + '</div></details>';
}

function chatLogKey(run, rel) { return String(run || "") + "\n" + String(rel || ""); }

function chatDisclosureAttr(key, defaultOpen = false) {
  const state = chatDisclosureState.get(key);
  return ' data-chat-disclosure="' + esc(key) + '"' +
    ((state ? state.open : defaultOpen) ? ' open' : '');
}

function chatToolActivityHTML(it, index, latestLogIndex, segment) {
  if (!it.log || !it.run) return "";
  const key = chatLogKey(it.run, it.log);
  const cached = chatActivityCache.get(key);
  const activities = segment ? segment.activities : (cached?.activities || []);
  const groupKey = key + "\ngroup" + (segment ? ":" + segment.id : "");
  // 空活动组整块不渲染：运行中默认展开的「执行过程」没有内容时只剩两行空态
  // 文案，失败/换将期一串 CLI 步骤能把半屏吃成占位符（2026-10-22 用户反馈）。
  // 进程活动仍有「查看完整 CLI 执行日志」入口；用户手动展开过的空组保留。
  if (!activities.length && !chatDisclosureState.get(groupKey)?.open) return "";
  const icons = { read: "book", command: "code", edit: "file-text", search: "search", tool: "code" };
  const labels = { read: t("读取文件"), command: t("运行命令"), edit: t("修改文件"), search: t("搜索"), tool: t("使用工具") };
  const statuses = { completed: t("完成"), running: t("执行中"), failed: t("失败"), unknown: t("工具活动") };
  const kinds = [...new Set(activities.map(a => labels[a.kind] || labels.tool))];
  const summary = kinds.length ? kinds.join(" · ") : t("执行过程");
  const rows = activities.map((a, i) => {
    const state = Object.hasOwn(statuses, a.status) ? a.status : "unknown";
    const label = [statuses[state], labels[a.kind] || labels.tool,
      a.kind === "tool" ? a.name : "", a.summary].filter(Boolean).join(" · ");
    const detailKey = key + "\nactivity:" + (a.id || i);
    return '<details class="chat-tool-row ' + state + '"' + chatDisclosureAttr(detailKey) + '><summary>' +
      '<svg class="ico" aria-hidden="true"><use href="#i-' + (icons[a.kind] || icons.tool) + '"></use></svg>' +
      '<span class="chat-tool-label" title="' + esc(label) + '">' + esc(label) + '</span></summary>' +
      '<div class="chat-tool-detail">' +
      (a.input ? '<pre>' + esc(a.input) + '</pre>' : '') +
      (a.output ? '<pre>' + esc(a.output) + '</pre>' : '') +
      (a.exit_code != null ? '<span>' + esc(t("退出码")) + ' ' + esc(a.exit_code) + '</span>' : '') +
      '</div></details>';
  }).join("");
  const empty = cached ? t("该步骤未记录可识别的工具活动，可查看执行日志。") :
    (chatLogInflight.has(key) ? t("正在读取执行过程…") : t("展开以读取执行过程"));
  return '<details class="chat-tool-group" data-chat-activity-key="' + esc(key) + '"' +
    chatDisclosureAttr(groupKey, it.status === "running" || index === latestLogIndex) + '><summary>' +
    '<svg class="ico" aria-hidden="true"><use href="#i-code"></use></svg><span>' + esc(summary) + '</span>' +
    (activities.length ? '<span class="chat-tool-count">' + activities.length + '</span>' : '') +
    '<span class="chat-tool-chevron">⌄</span></summary><div class="chat-tool-list" data-chat-activity-list="' + esc(groupKey) + '">' +
    (rows || '<div class="chat-tool-empty">' + esc(empty) + '</div>') +
    (activities.length && cached?.activities_truncated ? '<div class="chat-tool-empty">' + esc(t("仅显示最近的工具活动")) + '</div>' : '') +
    '</div></details>';
}

function chatExecutionHTML(it, index, latestLogIndex) {
  const cached = chatActivityCache.get(chatLogKey(it.run, it.log));
  if (!cached?.transcript?.length) return chatToolActivityHTML(it, index, latestLogIndex);
  const byId = new Map(cached.activities.map(a => [a.id, a]));
  let html = "", tools = [], segment = 0;
  const flush = () => {
    if (tools.length) html += chatToolActivityHTML(it, index, latestLogIndex, { activities: tools, id: segment++ });
    tools = [];
  };
  const finalText = chatCleanText(it.text);
  for (const block of cached.transcript) {
    if (block.kind === "tool") { if (byId.has(block.id)) tools.push(byId.get(block.id)); }
    else if (block.kind === "message") {
      const text = chatCleanText(block.text);
      if (!text || text === finalText) continue;
      flush();
      html += '<div class="chat-execution-message">' + chatBodyHTML(text) + '</div>';
    }
  }
  flush();
  return html;
}

function chatLogHTML(it, index, latestLogIndex) {
  if (!it.log || !it.run) return "";
  const key = chatLogKey(it.run, it.log), opened = chatLogOpen.has(key);
  const cached = chatLogCache.get(key);
  return '<details class="chat-cli-log" data-chat-log-key="' + esc(key) + '"' + (opened ? " open" : "") + ">" +
    "<summary>" + esc(t("查看完整 CLI 执行日志")) + (cached ? " · " + esc(t("已加载")) : "") + "</summary>" +
    '<pre class="chat-cli-log-text">' + esc(cached || (opened ? t("正在读取 CLI 日志…") : "")) + "</pre></details>";
}

function chatLoadLog(run, rel) {
  const key = chatLogKey(run, rel);
  const now = Date.now();
  if (!run || !rel || chatLogInflight.has(key) || now - (chatLogFetchedAt.get(key) || 0) < 2200) return;
  chatLogInflight.add(key);
  api("/api/runs/" + encodeURIComponent(run) + "/log?step=" + encodeURIComponent(rel) + "&tail=40000&pretty=1&activities=1")
    .then((data) => {
      chatLogCache.set(key, String(data?.log || "").trim() || t("当前暂无 CLI 日志输出"));
      chatActivityCache.set(key, { activities: Array.isArray(data?.activities) ? data.activities : [],
        transcript: Array.isArray(data?.transcript) ? data.transcript : [],
        activities_truncated: !!data?.activities_truncated, step_status: data?.step_status || "" });
      chatLogFetchedAt.set(key, Date.now());
    })
    .catch((error) => { chatLogCache.set(key, t("读取 CLI 日志失败：") + (error.message || "")); })
    .finally(() => {
      chatLogInflight.delete(key);
      // The newest/running CLI cards are expanded by default.  They are not
      // necessarily present in chatLogOpen, so loading their log must still
      // invalidate the timeline; otherwise the card stays on the placeholder
      // "正在读取 CLI 日志…" until the next unrelated timeline update.
      if (S.lastRun) {
        chatLiveSig = "";
        const flow = $("rd-chat-flow");
        const stillRendered = flow && flow.dataset.runId &&
          Array.from(flow.querySelectorAll("details.chat-cli-log[data-chat-log-key]"))
            .some((details) => details.dataset.chatLogKey === key);
        const viewedRun = S.lastRun.id;
        if (stillRendered)
          api("/api/runs/" + encodeURIComponent(viewedRun) + "/timeline")
          .then((timeline) => {
            if (S.lastRun?.id === viewedRun && !$("run-detail").classList.contains("hidden"))
              drawChatFlow(S.lastRun, timeline, ["running", "queued"].includes(S.lastRun.status));
          })
          .catch(() => {});
      }
    });
}

/* 运行中直连对话的快轮询：SSE/轮询最密 2s、闲时 8s，思考是逐句吐的——
 * 1.2s 直拉时间线把增量打印出来。run 终态、切详情、分区隐藏即停。 */
function stopChatLive() {
  if (chatLiveTimer) { clearInterval(chatLiveTimer); chatLiveTimer = null; }
  chatLiveRunId = null;
}

function scheduleChatLive(runId) {
  if (chatLiveTimer && chatLiveRunId === runId) return;
  stopChatLive();
  chatLiveRunId = runId;
  chatLiveTimer = setInterval(async () => {
    const run = S.lastRun;
    const flow = $("rd-chat-flow");
    if (!run || run.id !== runId || !flow ||
        !$("run-detail") || $("run-detail").classList.contains("hidden") ||
        (run.status !== "running" && run.status !== "queued")) return stopChatLive();
    try {
      const data = await api("/api/runs/" + encodeURIComponent(runId) + "/timeline");
      if (!S.lastRun || S.lastRun.id !== runId) return;   // 拉取期间切了详情
      drawChatFlow(run, data, true);
    } catch (e) { /* 网络抖动保留上一帧 */ }
  }, 1200);
}

/* 对话正文：保留 Markdown 的段落/标题/列表层级，``` 围栏复用代码块组件。
 * 模型文本先转义；链接只允许 http(s)/mailto，避免把回答内容当 HTML 或脚本执行。
 * 未闭合围栏按代码块收尾，流式输出中途也不撒裸反引号。 */
function chatBodyHTML(text) {
  const lines = String(text || "").split(/\r?\n/);
  const out = [];
  let txt = [], code = null;
  const inline = (raw) => {
    let h = esc(raw);
    h = h.replace(/`([^`]+)`/g, "<code>$1</code>");
    h = h.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    h = h.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>");
    h = h.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+|mailto:[^\s)]+)\)/g,
      '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
    return h;
  };
  const flushTxt = () => {
    if (!txt.length) return;
    const blocks = [];
    let paragraph = [], list = null;
    const closeParagraph = () => {
      if (paragraph.length) blocks.push("<p>" + paragraph.map(inline).join("<br>") + "</p>");
      paragraph = [];
    };
    const closeList = () => {
      if (list) { blocks.push("</" + list + ">"); list = null; }
    };
    for (const rawLine of txt) {
      const line = rawLine.trimEnd();
      const heading = line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);
      const bullet = line.match(/^\s{0,3}[-+*]\s+(.+)$/);
      const numbered = line.match(/^\s{0,3}\d+[.)]\s+(.+)$/);
      if (!line.trim()) { closeParagraph(); closeList(); continue; }
      if (heading) {
        closeParagraph(); closeList();
        const level = heading[1].length;
        blocks.push("<h" + level + ">" + inline(heading[2]) + "</h" + level + ">");
        continue;
      }
      if (/^\s{0,3}(---+|___+|\*\*\*+)\s*$/.test(line)) {
        closeParagraph(); closeList(); blocks.push("<hr>"); continue;
      }
      if (bullet || numbered) {
        closeParagraph();
        const kind = bullet ? "ul" : "ol";
        if (list !== kind) { closeList(); list = kind; blocks.push("<" + list + ">"); }
        blocks.push("<li>" + inline((bullet || numbered)[1]) + "</li>");
        continue;
      }
      closeList();
      const quote = line.match(/^\s{0,3}>\s?(.*)$/);
      if (quote) {
        closeParagraph(); blocks.push("<blockquote><p>" + inline(quote[1]) + "</p></blockquote>");
      } else paragraph.push(line);
    }
    closeParagraph(); closeList();
    out.push('<div class="chat-body chat-markdown">' + blocks.join("") + "</div>");
    txt = [];
  };
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, "");
    if (line.startsWith("```")) {
      if (code) { out.push(codeBlockHTML(code.join("\n"))); code = null; }
      else { flushTxt(); code = []; }
      continue;
    }
    if (code) code.push(raw);
    else txt.push(raw);
  }
  if (code) out.push(codeBlockHTML(code.join("\n")));
  flushTxt();
  return out.join("");
}

async function renderChat(run, active) {
  const box = $("rd-chat");
  if (!box) return;
  // 所有有任务归属的运行都启用对话时间线；蜂巢/步骤/成果仍按原页签保留
  if (!run || !chatEngineIsDirect(run)) { box.classList.add("hidden"); return; }
  box.classList.remove("hidden");
  syncChatSendControls(run);
  renderChatRunStatus(run, active);
  if (chatWorkspaceState.open && chatWorkspaceState.runId !== run.id) {
    chatWorkspaceState.open = false;
    chatWorkspaceState.current = "";
    chatWorkspaceState.dirty = false;
    chatWorkspaceSyncLayout();
  }
  const continueNote = $("rd-chat-continue-note");
  if (continueNote) continueNote.classList.toggle("hidden", !!active);
  if (chatRunId !== run.id) {
    chatRunId = run.id; chatAtts = []; drawChatAtts(); chatSig = ""; chatLiveSig = "";
    chatForceBottom = true;
    chatDisclosureState.clear();
  }
  // 三件套回填：任务对象来自 S.state（渲染时已就位）；只在任务未在跑时回显，
  // 防止轮询把用户正在改的值弹回（select change 重绘弹回教训）
  if (run.status !== "running" && run.status !== "queued" && S.state) {
    const task = (S.state.tasks || []).find((x) => x.id === run.task_id);
    if (task) rdPrefsFill(task);
  }
  const sig = run.id + "|" + run.status + "|" + (run.steps || []).length +
    "|" + ((run.messages || []).length) + "|" + (run.steps || []).map((s) =>
      [s.status, s.output, s.summary, s.thinking, s.stream, (s.activity || []).length].join("~")
    ).join("^");
  if (sig === chatSig) {
    // 重开同一任务时正文签名可能完全不变，时间线不会重绘；仍要消费进入详情时
    // 设置的落底请求。否则旧 pane 已经可见（只是外层 run-detail 曾隐藏），
    // applyRdTabs 看不到 pane 显隐变化，用户会留在上次回看的历史位置。
    const flow = $("rd-chat-flow");
    if (chatForceBottom && flow && flow.dataset.runId === run.id &&
        !$('rd-chat').classList.contains("hidden") && !$('rd-chat').closest(".rd-pane").classList.contains("hidden")) {
      chatScrollBottomNow(flow);
      chatForceBottom = false;
    }
    return;   // 轮询重画去抖：内容没变不重建 DOM（保住输入焦点）
  }
  const runForFetch = run.id;    // 拉取期间可能切详情：过期响应不落盘（同 renderRunDetail 闸门）
  chatSig = sig;
  let data = null;
  try { data = await api("/api/runs/" + encodeURIComponent(run.id) + "/timeline"); }
  catch (e) { data = null; }
  if (!$("run-detail") || $("run-detail").classList.contains("hidden")) return;
  // 过期闸门：run 级（renderRunDetail）与任务级（drawTaskDetail）都经 S.lastRun
  // 指向当前详情正在展示的那条 run——拉取期间切了详情就丢弃响应
  if (!S.lastRun || S.lastRun.id !== runForFetch) return;
  drawChatFlow(run, data, active);
}

/* 对话输入框上方保留当前运行上下文，避免用户滚到时间线底部后看不到目标和控制。
 * 复用详情页已有暂停/取消链路；秒表独立更新，不触发时间线重绘。 */
let chatRunStatusTimer = null;
function renderChatRunStatus(run, active) {
  const bar = $("rd-chat-run-status");
  if (!bar) return;
  if (!active) {
    bar.classList.add("hidden");
    if (chatRunStatusTimer) { clearInterval(chatRunStatusTimer); chatRunStatusTimer = null; }
    return;
  }
  const task = (S.state && (S.state.tasks || []).find((item) => item.id === run.task_id)) || {};
  const goal = task.goal || run.goal || run.title || "";
  const label = bar.querySelector("[data-chat-run-goal]");
  const elapsed = bar.querySelector("[data-chat-run-elapsed]");
  const pause = bar.querySelector("[data-chat-run-pause]");
  const expand = bar.querySelector("[data-chat-run-expand]");
  if (label) { label.textContent = goal; label.title = goal; }
  if (pause) {
    pause.textContent = run.paused ? t("继续执行") : t("暂停");
    pause.setAttribute("aria-label", pause.textContent);
    pause.title = pause.textContent;
  }
  if (elapsed) {
    const started = run.started_at || run.created_at;
    const update = () => {
      const stamp = Date.parse(String(started || "").replace(" ", "T"));
      const seconds = Number.isFinite(stamp) ? Math.max(0, Math.floor((Date.now() - stamp) / 1000)) : 0;
      elapsed.textContent = chatDurTxt(seconds);
    };
    update();
    if (!chatRunStatusTimer) chatRunStatusTimer = setInterval(() => {
      if (!bar.classList.contains("hidden")) {
        const stamp = Date.parse(String(bar.dataset.started || "").replace(" ", "T"));
        const seconds = Number.isFinite(stamp) ? Math.max(0, Math.floor((Date.now() - stamp) / 1000)) : 0;
        const current = bar.querySelector("[data-chat-run-elapsed]");
        if (current) current.textContent = chatDurTxt(seconds);
      }
    }, 1000);
    bar.dataset.started = started || "";
  }
  if (expand) {
    const expanded = $("run-detail").classList.contains("rd-chat-expanded");
    expand.textContent = expanded ? "⤢" : "⛶";
    expand.title = expanded ? t("收起对话") : t("展开对话");
    expand.setAttribute("aria-label", expand.title);
  }
  bar.classList.remove("hidden");
}

window.toggleChatExpanded = function () {
  const detail = $("run-detail");
  if (!detail) return;
  detail.classList.toggle("rd-chat-expanded");
  if (S.lastRun) renderChatRunStatus(S.lastRun,
    S.lastRun.status === "running" || S.lastRun.status === "queued");
};

/* 时间线渲染本体（renderChat 与运行中快轮询共用）：items → 气泡流。
 * force=true 时跳过增量签名闸门（快轮询拿到的一定是新帧）。 */
function drawChatFlow(run, data, active) {
  syncChatSendControls(run);
  const items = (data && data.items) || [];
  const flow = $("rd-chat-flow");
  if (!flow) return;
  flow.querySelectorAll("details[data-chat-disclosure]").forEach(details => {
    chatDisclosureState.set(details.dataset.chatDisclosure, { open: details.open });
  });
  const activityScroll = new Map(Array.from(flow.querySelectorAll("[data-chat-activity-list]")).map(list =>
    [list.dataset.chatActivityList, { top: list.scrollTop,
      pin: list.scrollHeight - list.scrollTop - list.clientHeight < 24 }]));
  // 内联 CLI 日志块同病：整体重建丢滚动位置，运行中每帧弹回头部＝永远停在
  // 「下达」审计头，CLI 真输出全在折叠线下看不见。同样记「贴底 or 上滑到哪」，
  // 重绘后恢复；首次展开（旧 DOM 无对应块）默认贴底＝打开即看最新输出。
  const logScroll = new Map(Array.from(flow.querySelectorAll("details.chat-cli-log[data-chat-log-key]")).map(d => {
    const pre = d.querySelector(".chat-cli-log-text");
    return [d.dataset.chatLogKey, pre ? { top: pre.scrollTop,
      pin: pre.scrollHeight - pre.scrollTop - pre.clientHeight < 24 } : null];
  }));
  const latestLogIndex = items.reduce((last, it, index) =>
    (it.kind === "agent" && it.log && it.run ? index : last), -1);
  // 日志是独立文件，可能在步骤状态/正文都不变时持续增长。先于时间线签名
  // 闸门轮询最新/运行中的日志，否则 DOM 不重建时 CLI 输出会停留在旧尾部。
  items.forEach((it) => {
    // 终态气泡不再渲染执行过程/CLI 日志，日志与活动轮询只服务运行中的步骤
    if (it.kind !== "agent" || it.status !== "running" || !it.log || !it.run) return;
    chatLoadLog(it.run, it.log);
  });
  // 增量闸门：时间线任何可见输入（状态/正文/思考/实时流/活动/追问/已送达）
  // 都没变才跳过重建——保滚动位置与折叠态。维度少了不行：只看 live 长度的话，
  // 没开思考的 CLI 步骤 running→done 两态签名相同，气泡会永远停在打字动画
  const liveSig = items.reduce((a, it) => a + "|" + (it.kind || "") + ":" +
    (it.status || "") + ":" + String(it.text || "").length + ":" +
    (it.cli || "") + ":" + (it.model || "") + ":" + (it.provider || "") + ":" +
    (it.duration_s == null ? "" : it.duration_s) + ":" +
    String(it.thinking || "").length + ":" + String(it.stream || "").length + ":" +
    (it.activity || []).length + ":" + (it.followups || []).length +
    ":" + (it.acp_events || []).length +
    ":" + (it.consumed ? 1 : 0) + ":" + (it.delivery || "") + ":" + (it.id || "") + ":" + (it.run || ""), "") + "|" + ((data && data.result) ? "r" : "");
  if (liveSig === chatLiveSig && flow.childElementCount) return;
  chatLiveSig = liveSig;
  flow.dataset.runId = run.id;   // run 戳：applyRdTabs 判「内容是否已对齐当前对话」用
  // 附件兼容 字符串路径 / {name|path} 对象 两种形态（对象直接拼会成 [object Object]）
  const attName = (a) => { const p = typeof a === "string" ? a
    : ((a && (a.name || a.path)) || "");
    return String(p).split(/[\\/]/).pop() || ""; };
  chatTimelineItems = items;   // 复制/编辑重发按索引回查（见 rd-chat-flow 委托）
  renderChatContext(chatEngineIsDirect(run));
  {   // 「总结对话」只对有任务归属的对话引擎亮出（A4）
    const sumBtn = $("rd-chat-summarize");
    if (sumBtn) sumBtn.classList.toggle("hidden", !chatEngineIsDirect(run));
  }
  renderChatQueue(items, run);
  // 连续同文失败合并（2026-10-22 用户反馈：同一 CLI 三次同错把时间线撑成
  // 失败墙，报错正文一模一样却抄三遍）。只合并完全相邻且清理后正文一致的
  // 失败步骤；孤立失败仍单独成卡，细节不丢。
  const failKey = (it) => (it.kind === "agent" && it.status === "failed")
    ? chatCleanText(it.text).replace(/\s+/g, " ").trim() : "";
  const failGroups = new Map(), failMembers = new Set();
  for (let i = 0; i < items.length;) {
    const key = failKey(items[i]);
    if (!key) { i++; continue; }
    let j = i + 1;
    while (j < items.length && failKey(items[j]) === key) j++;
    if (j - i >= 2) {
      failGroups.set(i, items.slice(i, j));
      for (let q = i; q < j; q++) failMembers.add(q);
    }
    i = j;
  }
  let html = items.map((it, idx) => {
    if (failMembers.has(idx))
      return failGroups.get(idx) ? chatFailGroupHTML(failGroups.get(idx), idx) : "";
    // 反向通道（2026-10-22 multica）：agent 主动汇报自成气泡——阻塞（警示
    // 描边+可回信解除）/进展（弱化）/解除（记账行）。回信走既有对话条，即
    // add_message 链，用户回复自动解除对应阻塞。
    if (it.kind === "report") {
      const isBlocker = it.report_kind === "blocker";
      const label = it.report_kind === "resolve" ? t("阻塞已解除")
        : isBlocker ? t("⚠ 阻塞汇报") : t("进展汇报");
      const meta = [it.step != null ? "#" + it.step : "",
        it.resolved ? t("已回复解除") : ""].filter(Boolean).join(" · ");
      return '<div class="chat-row"><div class="chat-bubble report' +
        (isBlocker ? " blocker" : "") + (it.resolved ? " resolved" : "") + '">' +
        '<div class="chat-step-meta">' + esc(label) + (meta ? " · " + esc(meta) : "") + "</div>" +
        (it.text ? esc(it.text) : "") +
        '<div class="chat-meta">' + esc(t("智能体汇报")) + " " + esc(chatTimeText(it.at)) +
        (isBlocker && !it.resolved
          ? ' · <button type="button" class="chat-act" data-cact="copy" data-ci="' + idx + '">' + esc(t("复制")) + "</button>"
          : "") +
        "</div></div></div>";
    }
    if (it.kind === "user") {
      if (!it.consumed && it.id && it.run) return "";
      // 用户消息：右侧浅灰圆角块，元信息与动作落在块外下方。
      // 附件胶囊可点开预览：data-att 带 _attachments/ 相对路径（老数据裸文件名
      // 在前端钉回 _attachments/，与服务端 norm_rel 同口径），事件委托绑在
      // rd-chat-flow 上——时间线整块 innerHTML 重建也不丢监听
      const atts = (it.attachments || []).map((a) => {
        const nm = attName(a);
        if (!nm) return null;
        let rel = typeof a === "string" ? a : ((a && (a.path || a.name)) || nm);
        rel = String(rel).replace(/\\/g, "/");
        if (!rel.startsWith("_attachments/")) rel = "_attachments/" + rel.split("/").pop();
        const isImg = /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(nm);
        const src = isImg && chatRunId
          ? "/api/runs/" + encodeURIComponent(chatRunId) + "/file?name=" + encodeURIComponent(rel) : "";
        return { nm, rel, img: src };
      }).filter(Boolean);
      // 悬停动作：复制原文 / 编辑重发（载入输入框改完再发，2026-09-22 用户诉求）
      const acts = '<span class="chat-acts2">' +
        '<button type="button" class="chat-act" data-cact="copy" data-ci="' + idx + '">' + esc(t("复制")) + "</button>" +
        '<button type="button" class="chat-act" data-cact="edit" data-ci="' + idx + '">' + esc(t("编辑")) + "</button>" +
        "</span>";
      return '<div class="chat-row me">' +
        '<div class="chat-user-message">' +
        '<div class="chat-bubble me">' +
        esc(it.text || t("（仅附件）")) +
        (atts.length
          ? '<div class="chat-atts">' + atts.map((a) =>
              (a.img
                ? '<span class="att-open chat-img" data-att="' + esc(a.rel) + '" title="' + esc(a.nm) + '">' +
                  '<img src="' + esc(a.img) + '" alt="' + esc(a.nm) + '" loading="lazy" draggable="false"></span>'
                : '<span class="att-chip2 att-open" data-att="' + esc(a.rel) +
                  '" title="' + esc(t("点击查看")) + '">' + esc(a.nm) + "</span>")).join("") + "</div>"
          : "") +
        '</div><div class="chat-meta"><span class="chat-meta-label">' + esc(it.who || "") + " " + esc(chatTimeText(it.at)) +
        (it.consumed ? "" : " · " + esc(t("待送达"))) + "</span>" + acts + "</div></div></div>";
    }
    // 协议尾行是给编排器判收的机器标记，不该出现在聊天正文里（真源在提示词约定）；
    // <followups> 块后端已剥并转成结构化字段，这里再兜一次底防老数据/漏剥；
    // 开场「本轮做了什么：…」+「回复：」是模型复读协议措辞的元描述（提示词已禁，
    // 这里兜历史数据），只剥消息开头的第一行
    // 评审裁定 JSON 原文整段糊泡没人读（2026-10-22 用户反馈）：换结构评审卡；
    // 完整原文在该步日志里（复制按钮同口径走 verdictDigestText，见复制处理器）
    const rawBody = chatCleanText(it.text);
    const digest = rawBody && it.status !== "running" ? verdictDigestData(rawBody) : null;
    const body = digest ? verdictDigestText(rawBody, true) : rawBody;
    // 失败步骤换成红卡：退出码/原因成标题栏，原始 stderr 与后端诊断分行。
    // 连续同文失败在 map 入口已合并，这里接的是孤立失败。
    if (it.status === "failed" && rawBody) return chatFailCardHTML(it, idx, rawBody);
    if (digest) return chatReviewHTML(it, idx, digest);
    // 运行中还没有正文：先给思考过程块（有思维链/工具活动时），正文位退化为
    // 实时预览（stream 累计值）；两者皆无才是等待提示。终态无正文不再渲染
    // 正文行——占位话并进元信息行，失败串场时每轮少占一行（2026-10-22 用户反馈）
    const liveText = it.status === "running" ? String(it.stream || "").trim() : "";
    const bodySection = body ? '<div class="chat-body">' + chatBodyHTML(body) + "</div>"
      : (liveText ? '<div class="chat-body chat-live-text">' + esc(liveText.slice(-4000)) + "</div>"
      : (it.status === "running"
        ? '<div class="chat-body chat-live-status"><span class="chat-live-dot"></span>' +
          '<span class="chat-live-label">' + esc(t("CLI 已启动，等待首段输出…")) + "</span>" +
          '<span class="chat-live-tag">' + esc(t("执行中")) + "</span></div>"
        : ""));
    // 元信息只留 名字+时间（+用时+失败标记）：路由/供应商细节属于「步骤」页签，塞这里就是噪音
    const metaBad = it.status === "failed" || it.status === "cancelled";
    const durRaw = chatItemDur(it);
    const durTxt = durRaw ? " · " + esc(durRaw) : "";
    // 智能体回复：整幅正文，元信息小字落在正文下方；
    // 悬停可复制回答原文（协议清洗后）
    const actsA = body ? '<span class="chat-acts2">' +
      '<button type="button" class="chat-act" data-cact="copy" data-ci="' + idx + '">' + esc(t("复制")) + "</button></span>" : "";
    const callMeta = [
      it.cli ? (it.cli === "builtin"
        ? t("调用通道") + " " + (it.who || t("内置直连"))
        : t("调用 CLI") + " " + it.cli) : "",
      it.model ? t("模型") + " " + it.model : "",
      it.provider ? t("供应商") + " " + it.provider : "",
    ].filter(Boolean).join(" · ");
    // 步骤行不再重复 who 与失败标记（底部元信息行都有），只留路由细节与编排注释
    const stepMeta = [it.role, it.n != null ? "#" + it.n : "", callMeta,
      it.status === "running" ? t("CLI 执行中") :
      (it.status === "failed" || it.status === "cancelled" ? "" : t("完成")), it.note].filter(Boolean).join(" · ");
    // 助手正文与工具活动共用左缘，不再为头像预留一列。
    return '<div class="chat-row">' +
      '<div class="chat-bubble agent">' +
      (stepMeta ? '<div class="chat-step-meta">' + esc(stepMeta) + "</div>" : "") +
      // 执行过程（思考/工具活动/CLI 日志）只在步骤执行中展示：终态气泡只留
      // 结果正文，过程明细去「步骤」页签回看（2026-10-22 用户拍板）
      (it.status === "running" ?
        chatThinkHTML(it) +
        chatAcpEventsHTML(it) +
        chatExecutionHTML(it, idx, latestLogIndex) : "") +
      bodySection +
      '<div class="chat-meta">' + esc(it.who || "") + " " + esc(chatTimeText(it.at)) + durTxt +
      (!body && it.status !== "running" ? " · " + esc(t("本轮无文本输出")) : "") +
      (metaBad ? " · " + esc(t(it.status === "failed" ? "失败" : "已取消")) : "") + actsA + "</div>" +
      (it.status === "running" ? chatLogHTML(it, idx, latestLogIndex) : "") +
      (Array.isArray(it.followups) && it.followups.length
        ? '<div class="chat-fups">' + it.followups.map((f) =>
          '<button type="button" class="chat-fup-btn" data-fup="' + esc(f.prompt || "") +
          '" title="' + esc(f.prompt || "") + '">' + esc(f.label || "") + "</button>").join("") + "</div>"
        : "") +
      "</div></div>";
  }).join("");
  // 时间线收尾的「执行结果」卡：run 终态后的确定性摘要（成没成/耗时/执行者/
  // 产出文件）——不依赖模型最后一句话自觉交代（用户反馈：输"1"跑完 55 秒
  // 只见一句寒暄，执行结果无处可看）。
  const res = data && data.result;
  if (res) html += chatResultHTML(run, res);
  // 代码任务的文件变更属于对话结果的一部分：把它放在助手回复之后，
  // 用户无需跳到 Git 页签就能看到本轮改了什么，并可逐文件查看 diff。
  html += chatChangeSummaryHTML(run);
  // 贴底跟随：用户滚到底部附近才自动滚到最新输出，回看历史不打扰；
  // 带强制贴底标记（发送/继续任务/首开详情置的）则无条件跳最新。
  // 页签当前不可见（display:none 时 scrollHeight 恒 0）贴底无处落：
  // 标记保留给 applyRdTabs，切进对话页签那一刻再带到底。
  const flowVisible = flow.offsetParent !== null;
  const stick = (chatForceBottom && flowVisible) ||
    flow.scrollHeight - flow.scrollTop - flow.clientHeight < 80;
  if (chatForceBottom && flowVisible) chatForceBottom = false;
  // 思考过程面板（.ct-body 自带滚动条）逐帧整体重建会丢滚动位置——重绘前
  // 记住「贴底 or 用户上滑到哪」，重绘后恢复：贴底则一直跟最新（2026-09-22
  // 用户诉求），上滑回看历史思维链则保持位置不被打扰。
  const prevThink = flow.querySelector('[data-think-live="1"] .ct-body');
  const thinkPin = prevThink
    ? prevThink.scrollHeight - prevThink.scrollTop - prevThink.clientHeight < 24
    : true;
  const thinkTop = prevThink ? prevThink.scrollTop : 0;
  flow.innerHTML = html || '<div class="hint">' + esc(t("还没有对话内容")) + "</div>";
  maskSecretsInDOM(flow);   // 密钥默认打码（A1）：所有气泡/日志表面统一后处理
  flow.querySelectorAll("[data-chat-activity-list]").forEach(list => {
    const prev = activityScroll.get(list.dataset.chatActivityList);
    if (prev) list.scrollTop = prev.pin ? list.scrollHeight : prev.top;
  });
  flow.querySelectorAll("details.chat-cli-log[data-chat-log-key]").forEach(d => {
    if (!d.open) return;
    const pre = d.querySelector(".chat-cli-log-text");
    if (!pre) return;
    const prev = logScroll.get(d.dataset.chatLogKey);
    pre.scrollTop = prev && !prev.pin ? prev.top : pre.scrollHeight;
  });
  if (stick) chatScrollBottomNow(flow);
  const newThink = flow.querySelector('[data-think-live="1"] .ct-body');
  if (newThink) {
    if (thinkPin) newThink.scrollTop = newThink.scrollHeight;
    else newThink.scrollTop = Math.min(thinkTop, newThink.scrollHeight);
  }
  // 有运行中的直连步骤 → 快轮询把思考过程/正文增量打印出来；终态即停
  const hasRunning = items.some((it) => it.kind === "agent" && it.status === "running");
  if (active && hasRunning && run && run.id) scheduleChatLive(run.id);
  else stopChatLive();
}

/* 对话内的文件变更收据。数据来自任务级 side 快照，与 Git 页签使用同一
 * 口径；运行中显示实时 numstat，运行结束后显示该 run 的落盘快照。 */
function chatChangeSummaryHTML(run) {
  if (!run || (S._chatChangeUndone && S._chatChangeUndone[run.id])) return "";
  const side = S.detailSide;
  const sideMatchesRun = !!(side && side.run && side.run.id === run.id);
  const task = sideMatchesRun ? side.task : (((S.state || {}).tasks || []).find((item) => item.id === run.task_id) || {});
  const changes = sideMatchesRun ? side.changes : run.changes;
  const git = sideMatchesRun ? side.git : run.git;
  if (!run || !task || task.id !== run.task_id || !git || !git.branch || !changes) return "";
  const files = Array.isArray(changes.files) ? changes.files.filter((f) => f && f.path) : [];
  const count = Number(changes.count) || files.length;
  if (!count || !files.length) return "";
  const active = ["running", "queued"].includes(String((sideMatchesRun && side.task || {}).status || run.status || ""));
  const add = changes.add_total == null ? 0 : Number(changes.add_total) || 0;
  const del = changes.del_total == null ? 0 : Number(changes.del_total) || 0;
  const rows = files.slice(0, 40).map((f) => {
    const status = f.status === "D" ? "d" : f.status === "A" || f.status === "?" ? "n" : "m";
    const lineStats = (f.add != null || f.del != null)
      ? '<span class="chat-change-lines"><b>+' + (Number(f.add) || 0) + '</b><b>-' + (Number(f.del) || 0) + "</b></span>" : "";
    return '<button type="button" class="chat-change-file" data-chat-change-file="' + esc(f.path) +
      '" data-chat-change-run="' + esc(run.id || "") + '" title="' + esc(t("查看该文件的变更")) + '">' +
      '<i class="gs ' + status + '">' + esc(gitStatusLabel(f.status)) + '</i><span class="chat-change-path">' +
      esc(f.path) + '</span>' + lineStats + '<span class="chat-change-chevron">›</span></button>';
  }).join("");
  const moreCount = Math.max(0, count - Math.min(files.length, 40));
  const more = moreCount ? '<div class="chat-change-more">+' + moreCount + " " + esc(t("个文件")) + "</div>" : "";
  // Isolated code runs are finalized on their task branch and then restored to
  // the user's original branch.  A checkpoint restore from that original
  // checkout cannot safely replay the task-branch snapshot, so do not advertise
  // an undo action for those runs.
  const isolatedRestored = !!((run.git && run.git.restored) ||
    (sideMatchesRun && side.git && side.git.restored));
  const undo = active || isolatedRestored ? "" : '<button type="button" class="ghost chat-change-undo" data-chat-change-undo="' +
    esc(run.id || "") + '">' + esc(t("撤销")) + "</button>";
  const submit = active || isolatedRestored ? "" : '<button type="button" class="primary chat-change-submit" data-chat-change-submit="' +
    esc(run.id || "") + '">' + esc(t("提交 Git 并推送")) + "</button>";
  return '<div class="chat-row chat-change-row"><details class="chat-change-card"' + chatDisclosureAttr("changes:" + run.id) +
    ' aria-label="' + esc(t("文件变更")) + '">' +
    '<summary class="chat-change-head"><div class="chat-change-title"><svg class="ico" aria-hidden="true"><use href="#i-git-branch"></use></svg>' +
    '<strong>' + esc(t("已编辑 {0} 个文件", count)) + '</strong><span class="chat-change-stats"><b>+' + add + '</b><b>-' + del +
    '</b></span></div><span class="chat-change-branch" title="' + esc(git.branch) + '">' + esc(git.branch) + '</span></summary>' +
    '<div class="chat-change-files">' + rows + more + '</div>' +
    '<div class="chat-change-foot">' + submit + undo + '<button type="button" class="ghost chat-change-view" data-chat-change-view="' +
    esc(run.id || "") + '">' + esc(t("查看变更")) + '</button></div>' +
    '</details></div>';
}

window.undoChatChanges = async function (runId) {
  if (!runId || !await uiConfirm(t("撤销会恢复本轮记录的文件，shell、MCP 和外部服务副作用不保证可回滚。确定继续？"),
    { ok: t("撤销文件改动"), danger: true })) return;
  try {
    const result = await api("/api/runs/" + encodeURIComponent(runId) + "/checkpoints/restore", {
      method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()),
      body: JSON.stringify({ confirm: true }),
    });
    const restored = Number(result.restored) || 0;
    const conflicts = Array.isArray(result.conflicts) ? result.conflicts : [];
    if (!restored && conflicts.length) {
      toast(t("没有文件被撤销：") + conflicts.join(", "), true);
      return;
    }
    if (!restored) {
      toast(t("没有可撤销的文件"), true);
      return;
    }
    toast(t("已撤销 ") + restored + t(" 个文件") + (conflicts.length ? "；" + t("冲突 ") + conflicts.join(", ") : ""));
    if (!conflicts.length) {
      S._chatChangeUndone = S._chatChangeUndone || {};
      S._chatChangeUndone[runId] = true;
    }
    await refreshDetailSide(true);
    chatSig = ""; chatLiveSig = "";
    if (S.lastRun && S.lastRun.id === runId) renderChat(S.lastRun, ["running", "queued"].includes(S.lastRun.status));
  } catch (error) { toast(t("撤销失败：") + error.message, true); }
};

window.submitChatChanges = async function (runId) {
  const key = detailSideTaskKey();
  if (!key || !runId) return;
  let wb;
  try { wb = await api("/api/tasks/" + encodeURIComponent(key) + "/git"); }
  catch (error) { toast(t("Git 工作台读取失败：") + error.message, true); return; }
  const side = S.detailSide;
  if (!side || !side.run || side.run.id !== runId || !side.task || side.task.id !== key) {
    toast(t("Git 工作台读取失败：") + t("任务变更状态已刷新，请重试"), true);
    return;
  }
  const taskBranch = side && side.git && side.git.branch;
  const currentBranch = wb && wb.branch;
  // 提交按钮只服务于当前卡片对应的任务分支。终态隔离任务通常已经
  // checkout 回用户原分支；缺少任一分支信息也必须拒绝，不能把当前工作区
  // 的改动误归入本轮并推送。
  if (!wb || !wb.repo) {
    toast(t("Git 工作台读取失败：") + t("当前任务没有可用的 Git 工作区"), true);
    return;
  }
  if (!taskBranch || !currentBranch) {
    toast(t("无法确认任务分支，请先在 Git 工作台打开并切换到任务分支"), true);
    return;
  }
  if (taskBranch !== currentBranch) {
    toast(t("当前工作区在 {0}，任务变更属于 {1}；请先在 Git 工作台切换分支。", currentBranch, taskBranch), true);
    return;
  }
  const changePaths = new Set(((side && side.changes && side.changes.files) || [])
    .map((file) => file && file.path).filter(Boolean));
  const pending = [].concat(wb.staged || [], wb.unstaged || [], wb.untracked || [])
    .filter((file) => file && changePaths.has(file.path));
  if (!pending.length) {
    toast(t("当前没有未提交变更，可在 Git 工作台查看任务分支提交"));
    openChangeSummaryGit();
    return;
  }
  const defaultMessage = t("CodeBee：完成本轮文件修改");
  const message = (await uiPrompt(t("提交信息"), defaultMessage) || "").trim();
  if (!message) return;
  if (!await uiConfirm(t("将提交 {0} 个文件并推送当前分支，继续吗？", pending.length), { ok: t("提交并推送") })) return;
  // 弹窗期间用户可能在 Git 工作台切换了分支；再次读取并校验，避免把
  // 确认前看到的任务文件路径写入另一条分支。
  let latestWb;
  try { latestWb = await api("/api/tasks/" + encodeURIComponent(key) + "/git"); }
  catch (error) { toast(t("Git 工作台读取失败：") + error.message, true); return; }
  if (!latestWb || !latestWb.repo || latestWb.branch !== taskBranch) {
    toast(t("当前工作区在 {0}，任务变更属于 {1}；请先在 Git 工作台切换分支。", latestWb && latestWb.branch, taskBranch), true);
    return;
  }
  for (const file of pending) {
    if (!await _gitWbPost("stage", { path: file.path })) return;
  }
  const committed = await _gitWbPost("commit", { message },
    (r) => t("已提交 ") + (r.files || 0) + t(" 个文件 → ") + (r.commit || ""));
  if (!committed) return;
  await _gitWbPost("push", null, t("已推送到远程"));
  await refreshDetailSide(true);
};

/* 产出文件归类与徽章字（时间线结果卡「等宽网格+分组」定案 2026-10-23，
 * demo app/ui/demo_artifact_chips.html 方案 D）：文档/数据·配置/媒体着色分组，
 * 其余归「其他」；dotfile（.gitignore 等）归配置组、徽章取去点后 3 字（→git），
 * 修掉 slice(0,4) 把 .gitignore 截成 giti 的旧缺陷——检查器/详情页共用。 */
function _crFileFam(name) {
  const s = String(name);
  if (s.startsWith(".")) return "data";
  const ext = _fpExt(s) || "";
  if (ext === "md" || ext === "txt" || ext === "html" || ext === "htm") return "doc";
  if (ext === "json" || ext === "csv" || ext === "yaml" || ext === "yml") return "data";
  if (ext === "mp4" || ext === "mp3" || ext === "png" || ext === "jpg" ||
      ext === "jpeg" || ext === "webm" || ext === "gif") return "media";
  return "other";
}
function _crFileBadge(name) {
  const s = String(name);
  if (s.startsWith(".")) return s.slice(1, 4) || "file";
  return _fpExt(s).slice(0, 4) || "file";
}
const _CR_FILE_GROUPS = [["doc", "文档"], ["data", "数据 · 配置"], ["media", "媒体"], ["other", "其他"]];
function chatFileGrid(run, files) {
  const buckets = {};
  files.forEach((f) => { const k = _crFileFam(f.name); (buckets[k] = buckets[k] || []).push(f); });
  return _CR_FILE_GROUPS.filter((g) => (buckets[g[0]] || []).length).map((g) => {
    const cells = buckets[g[0]].map((f) => {
      const fUrl = urlAuth("/api/runs/" + encodeURIComponent(run.id) + "/file?name=" + encodeURIComponent(f.name));
      // 网页成品给「运行」：弹窗里 iframe 真跑（源码弹窗看不出页面长什么样，
      // 用户要的是「看到东西跑起来」——与详情页「预览」页签同款挂载）
      const fExt = _fpExt(f.name);
      const runBtn = (fExt === "html" || fExt === "htm")
        ? '<button type="button" class="chip-btn" title="' + esc(t("运行展示")) +
          '" onclick="artRunPopup(\'' + jsq(run.id) + "', '" + jsq(f.name) + "', " + (Number(f.size) || 0) + ')"><svg class="ico" aria-hidden="true"><use href="#i-rocket"/></svg></button>'
        : "";
      return '<div class="file-chip has-actions">' +
        '<i class="fx fx-' + g[0] + '">' + esc(_crFileBadge(f.name)) + "</i>" +
        '<span class="p" title="' + esc(f.name + " · " + fmtSize(f.size)) + '">' + esc(f.name) + "</span>" +
        '<span class="fsz">' + fmtSize(f.size) + "</span>" +
        '<span class="fbtns">' + runBtn +
        '<button type="button" class="chip-btn" title="' + esc(t("预览")) + '" onclick="artPopup(\'' + jsq(run.id) + "', '" + jsq(f.name) + "', " + (Number(f.size) || 0) + ')"><svg class="ico" aria-hidden="true"><use href="#i-file-text"/></svg></button>' +
        '<a class="chip-btn" href="' + fUrl + '" download="' + esc(f.name) + '" title="' + esc(t("下载")) + '"><svg class="ico" aria-hidden="true"><use href="#i-download"/></svg></a>' +
        "</span></div>";
    }).join("");
    return '<div class="cr-grp"><div class="cr-grp-head"><b>' + esc(t(g[1])) + '</b><span class="n">' +
      buckets[g[0]].length + '</span></div><div class="cr-grp-grid">' + cells + "</div></div>";
  }).join("");
}

/* 执行结果卡（时间线收尾）：run 终态后的确定性摘要——成没成、跑多久、谁执行
 * 的、产出了哪些文件，全部产品明示，不依赖模型自觉交代。失败给「查看执行步骤」
 * 入口；文件 chip 复用成品预览通道（artPopup）。
 * 措辞说「本轮」不说「任务」：追话每轮都落一张卡，卡头喊「任务完成」会被读成
 * 又建了一个新任务（2026-09-22 用户反馈：其实一直都在同一个任务里）。 */
function chatResultHTML(run, res) {
  const partial = !!res.partial;
  const ok = res.status === "done" && !partial;
  const bad = res.status === "failed";
  const icon = ok ? "#i-check" : (partial ? "#i-gauge" : "#i-x");
  const label = partial ? t("本轮部分完成") : (ok ? t("本轮完成") : (bad ? t("本轮失败") : t("已取消")));
  const meta = [];
  if (res.executor) meta.push('<span class="cr-pill">' + esc(res.executor) + "</span>");
  const calls = Array.isArray(res.calls) ? res.calls : [];
  calls.forEach((call) => {
    const channelLabel = call.cli === "builtin" ? t("调用通道") : t("调用 CLI");
    const identity = String(call.label || call.cli || "");
    if (!identity) return;
    // 供应商串（prov-xx@host）又长又难读：收进悬停提示，胶囊只留通道+名称+模型
    const tip = [channelLabel + " " + identity,
      call.model ? t("模型") + " " + call.model : "",
      call.provider ? t("供应商") + " " + call.provider : ""]
      .filter(Boolean).join(" · ");
    meta.push('<span class="cr-pill" title="' + esc(tip) + '">' +
      "<b>" + esc(channelLabel) + "</b>" + esc(identity) +
      (call.model ? "<i>" + esc(call.model) + "</i>" : "") +
      "</span>");
  });
  if (res.turns) meta.push('<span class="cr-pill quiet">' + res.turns + " " + t("轮对话") + "</span>");
  if (res.duration_s != null) meta.push('<span class="cr-pill quiet">' + chatDurTxt(res.duration_s) + "</span>");
  const files = res.files || [];
  return '<div class="chat-row">' +
    '<span class="chat-avatar" aria-hidden="true"><svg class="ico"><use href="' + icon + '"></use></svg></span>' +
    '<div class="chat-result' + (partial ? " partial" : ok ? "" : bad ? " bad" : " off") + '">' +
    '<div class="cr-head"><svg class="ico" aria-hidden="true"><use href="' + icon + '"></use></svg>' +
    esc(label) + "</div>" +
    (meta.length ? '<div class="cr-meta">' + meta.join("") + "</div>" : "") +
    ((bad || partial) && res.error ? '<div class="cr-err">' + esc(res.error) + "</div>" : "") +
    '<div class="cr-files">' + (files.length
      ? '<div class="cr-files-title">' + esc(t("产出文件")) + '<b class="cr-count">' + files.length + "</b></div>" +
        chatFileGrid(run, files)
      : '<div class="cr-files-title">' + esc(t("无文件产出")) + "</div>") + "</div>" +
    (bad ? '<button class="ghost cr-steps" onclick="rdChatNavGo(\'steps\')">' +
      esc(t("查看执行步骤")) + "</button>" : "") +
    "</div></div>";
}

function chatDurTxt(s) {
  s = Math.round(Number(s) || 0);
  if (s < 60) return s + " " + t("秒");
  const m = Math.floor(s / 60), r = s % 60;
  return m + " " + t("分") + (r ? " " + r + " " + t("秒") : "");
}

/* 代码/编排任务的确定性结果摘要：报告是长文，步骤是过程，用户还需要一眼
 * 知道这次到底成没成、做了多少步、用了多久，以及失败原因。这个卡片不依赖
 * 智能体是否在最后一句话里主动总结；直连任务也能在「成果」页签看到同一口径。 */
function runDurationSeconds(run) {
  if (!run) return null;
  if (Number.isFinite(Number(run.duration_s))) return Number(run.duration_s);
  const steps = (run.steps || []).filter((s) => Number.isFinite(Number(s.duration_s)));
  if (steps.length) return steps.reduce((a, s) => a + Number(s.duration_s || 0), 0);
  const a = Date.parse(String(run.started_at || "").replace(" ", "T"));
  const b = Date.parse(String(run.ended_at || "").replace(" ", "T"));
  return Number.isFinite(a) && Number.isFinite(b) && b >= a ? (b - a) / 1000 : null;
}

function runEtaText(run) {
  if (!run || !Number.isFinite(Number(run.estimated_duration_s))) return "";
  const estimate = Math.max(1, Number(run.estimated_duration_s));
  const p90 = Math.max(estimate, Number(run.estimated_p90_s) || estimate);
  const active = run.status === "running" || run.status === "queued";
  if (!active) return t("预计完成约 {0}", chatDurTxt(Math.round(estimate)));
  if (run.status === "queued" || !run.started_at) {
    return t("预计完成约 {0}，保守不超过 {1}",
      chatDurTxt(Math.round(estimate)), chatDurTxt(Math.round(p90)));
  }
  const started = Date.parse(String(run.started_at).replace(" ", "T"));
  if (!Number.isFinite(started)) return "";
  const elapsed = Math.max(0, (Date.now() - started) / 1000);
  if (elapsed < estimate) {
    return t("预计剩余约 {0}", chatDurTxt(Math.max(1, Math.round(estimate - elapsed))));
  }
  if (elapsed < p90) {
    return t("已超过常规预估，仍在保守区间内（约剩 {0}）",
      chatDurTxt(Math.max(1, Math.round(p90 - elapsed))));
  }
  return t("已超过保守预估，正在继续执行，可查看步骤日志");
}

function runOutcomeSummary(run) {
  if (!run) return "";
  const last = (run.steps || []).slice().reverse().find((s) => s.output || s.summary);
  const raw = run.summary || (last && (last.output || last.summary)) || run.error || "";
  return String(raw).replace(/\s+/g, " ").trim().slice(0, 520);
}

function latestSerialBatch(task) {
  if (!task || !task.serial) return task || null;
  const state = S.state || {};
  const rows = [...(state.tasks || []), ...(state.archived_tasks || [])];
  let latest = task;
  for (let depth = 0; depth < 50; depth += 1) {
    const children = rows.filter((item) => item && item.serial
      && String(item.serial.continues || "") === String(latest.id));
    if (!children.length) break;
    children.sort((a, b) => {
      const an = Number(a.created_at_ns || 0);
      const bn = Number(b.created_at_ns || 0);
      return (bn - an) || String(b.created_at || b.id).localeCompare(String(a.created_at || a.id));
    });
    latest = children[0];
  }
  return latest;
}

function earlyFinishChainSummaryHtml(info) {
  if (!info || !info.early_finish) return "";
  const target = Number(info.planned_end_chapter || 0);
  const progress = Math.max(0, Math.min(100,
    Math.round(Number(info.last_chapter || 0) * 100 / Math.max(1, target))));
  const status = String(info.early_finish_state || "planned");
  const statusText = status === "completed" ? t("完结内容与评审已通过")
    : status === "review_failed" ? t("章节已写完，评审未通过，需要处理意见")
      : status === "chapters_reached" ? t("最终章稿已到位，等待终稿评审")
        : status === "running" ? t("最新批次正在运行")
          : status === "queued" ? t("最新批次正在排队")
            : ["failed", "cancelled", "timeout"].includes(status)
              ? t("最新批次状态：{0}", runStatusText({ status }))
              : t("收束章节仍待编写");
  const latestTitle = String(info.early_finish_latest_task_id || "");
  const latestTask = [...(((S.state || {}).tasks) || []), ...(((S.state || {}).archived_tasks) || [])]
    .find((item) => item.id === latestTitle);
  const latestRunStatus = info.early_finish_latest_run_status
    || info.early_finish_latest_task_status || "created";
  const latestLabel = latestTask
    ? t("最新批次：{0} · {1}", latestTask.title || latestTask.id,
      runStatusText({ status: latestRunStatus })) : "";
  const orphaned = Array.isArray(info.orphaned_chapters) ? info.orphaned_chapters : [];
  const missing = Array.isArray(info.missing_chapters) ? info.missing_chapters : [];
  const publishRows = Array.isArray(info.early_finish_publish_progress)
    ? info.early_finish_publish_progress : [];
  const publishText = publishRows.map((row) => {
    const platform = row.platform === "fanqie" ? t("番茄")
      : row.platform === "qimao" ? t("七猫") : row.platform;
    return t("{0}：已发布 {1}，排期 {2}，草稿 {3}，待处理 {4}",
      platform, row.published || 0, row.scheduled || 0,
      row.drafted || 0, row.outstanding || 0);
  }).join("；");
  const detail = [
    latestLabel,
    missing.length ? t("缺少章节：{0}", missing.slice(0, 20).join("、")) : "",
    orphaned.length ? t("最终章后的遗留稿：{0}。文件会保留，不会自动发布。", orphaned.join("、")) :
      t("提前完结后的遗留章节稿会保留，不会自动发布。"),
    publishText || t("尚无平台发布记录；发布进度与内容完结分开计算。"),
  ].filter(Boolean);
  return '<div class="rd-early-progress rd-serial-ending-summary" role="status">' +
    '<b>' + esc(t("全书提前完结状态")) + '</b>' +
    '<span>' + esc(t("第 {0} / {1} 章", info.last_chapter || 0, target)) + '</span>' +
    '<i><em style="width:' + progress + '%"></em></i>' +
    '<small>' + esc(statusText) + '</small>' +
    detail.map((line) => '<small>' + esc(line) + '</small>').join("") +
    '</div>';
}

function syncEarlyFinishChainSummary(info) {
  const box = $("rd-overview");
  if (!box) return;
  const old = box.querySelector(".rd-serial-ending-summary");
  if (old) old.remove();
  const html = earlyFinishChainSummaryHtml(info);
  if (html) box.insertAdjacentHTML("beforeend", html);
}

function refreshEarlyFinishChainInfo(task, ownerRunId) {
  if (!task || !task.serial || !task.serial.early_finish) return;
  const now = Date.now();
  if (S._earlyFinishInfoTask === task.id && now - Number(S._earlyFinishInfoAt || 0) < 6000) {
    syncEarlyFinishChainSummary(S._earlyFinishInfo);
    return;
  }
  if (S._earlyFinishInfoPending === task.id) return;
  S._earlyFinishInfoPending = task.id;
  const seq = S._earlyFinishInfoSeq = (S._earlyFinishInfoSeq || 0) + 1;
  api("/api/tasks/" + encodeURIComponent(task.id) + "/continue-info")
    .then((info) => {
      if (seq !== S._earlyFinishInfoSeq) return;
      const current = S.detailTaskKey === task.id
        || (!!ownerRunId && S.detailRunId === ownerRunId);
      if (!current) return;
      S._earlyFinishInfoTask = task.id;
      S._earlyFinishInfoAt = Date.now();
      S._earlyFinishInfo = info;
      syncEarlyFinishChainSummary(info);
      const active = ["queued", "running"].includes(info.early_finish_latest_run_status)
        || ["queued", "running"].includes(info.early_finish_latest_task_status);
      const finalReached = !!info.early_finish_chapters_reached;
      const done = !!info.early_finish_content_complete
        && !!info.early_finish_review_passed;
      const canContinue = !!info.can && !active;
      const continueButton = $("btn-continue");
      if (continueButton) continueButton.classList.toggle("hidden", !canContinue);
      const finishButton = $("btn-early-finish");
      if (finishButton) finishButton.classList.toggle("hidden",
        !(info.can && !info.early_finish && !active));
      const editButton = $("btn-early-finish-edit");
      if (editButton) editButton.classList.toggle("hidden", !info.early_finish || done || active);
      const cancelButton = $("btn-early-finish-cancel");
      if (cancelButton) cancelButton.classList.toggle("hidden", !info.early_finish || done || active);
      if (finalReached && !done && continueButton) continueButton.classList.add("hidden");
    })
    .catch(() => {})
    .finally(() => {
      if (S._earlyFinishInfoPending === task.id) S._earlyFinishInfoPending = "";
    });
}

function renderRunOutcome(run, runs, aggregate) {
  const box = $("rd-outcome");
  if (!box) return;
  if (!run) { box.classList.add("hidden"); box.innerHTML = ""; return; }
  const all = runs && runs.length ? runs : [run];
  const steps = (run.steps || []);
  const total = aggregate && Number.isFinite(Number(aggregate.steps))
    ? Number(aggregate.steps) : all.reduce((n, r) => n + ((r.steps || []).length), 0);
  const settled = aggregate && Number.isFinite(Number(aggregate.settled_steps))
    ? Number(aggregate.settled_steps) : all.reduce((n, r) => n + (r.steps || []).filter((s) =>
      !["running", "queued"].includes(String(s.status || ""))).length, 0);
  const status = String(run.status || "");
  const active = status === "running" || status === "queued";
  const bad = status === "failed" || status === "cancelled" || status === "timeout";
  const label = runStatusText(run);
  // 运行级警告（如：工作目录与运行中任务并行——计划/记忆/分支检出互相干扰）
  const warns = Array.isArray(run.warnings) ? run.warnings.filter(Boolean) : [];
  const icon = status === "done" ? "#i-check" : bad ? "#i-x" : "#i-gauge";
  const duration = runDurationSeconds(run);
  const latest = steps.slice().reverse().find((s) => s.agent_label || s.agent || s.role);
  const route = run.route && typeof run.route === "object" ? run.route.implementer : "";
  // route.implementer 是路由评分说明，不是用户真正关心的 CLI 名称；优先
  // 展示步骤上的 agent_label，只有旧数据没有步骤执行者时才回退到路由说明。
  const executor = run.executor || run.implementer || (latest && (latest.agent_label || latest.agent)) || route || "";
  const summary = runOutcomeSummary(run);
  const meta = [];
  if (executor) meta.push('<span><b>' + esc(t("执行者")) + '</b> ' + esc(executor) + "</span>");
  if (total) meta.push('<span><b>' + esc(t("步骤")) + '</b> ' + settled + "/" + total + "</span>");
  if (duration != null) meta.push('<span><b>' + esc(t("耗时")) + '</b> ' + esc(chatDurTxt(duration < 1 ? Number(duration.toFixed(1)) : Math.round(duration))) + "</span>");
  return (box.classList.remove("hidden"), box.innerHTML =
    '<div class="outcome-top">' +
      '<div class="outcome-title ' + (bad ? "bad" : active ? "live" : "ok") + '">' +
        '<svg class="ico" aria-hidden="true"><use href="' + icon + '"></use></svg>' + esc(t("执行结果")) +
        '<span class="outcome-status">' + esc(label) + "</span></div>" +
      (meta.length ? '<div class="outcome-meta">' + meta.join("") + "</div>" : "") +
    "</div>" +
    (summary ? '<div class="outcome-summary">' + esc(summary) + "</div>" : "") +
    (warns.length ? '<div class="outcome-warn">' + warns.map((w) => "⚠ " + esc(w)).join("<br>") + "</div>" : "") +
    (run.error ? '<div class="outcome-error">' + esc(run.error) + "</div>" : "") +
    (total ? '<div class="outcome-actions"><button class="ghost" type="button" onclick="rdChatNavGo(\'steps\')">' + esc(t("查看执行步骤")) + "</button></div>" : "")
  );
}

/* 任务详情首屏概览：把“这次任务做了什么、做到哪、最近发生了什么”放在
 * 蜂巢上方。直连任务仍以对话为主，由 chat-mode 隐藏概览，避免它抢走输入空间。 */
function renderDetailOverview(run, runs, task, aggregate) {
  const box = $("rd-overview");
  if (!box || !run) return;
  CodeBeeActivity.markViewed(run);
  const direct = chatEngineIsDirect(run);
  box.classList.toggle("direct-overview", direct);
  const all = runs && runs.length ? runs : [run];
  const steps = (run.steps || []);
  const total = aggregate && Number.isFinite(Number(aggregate.steps))
    ? Number(aggregate.steps) : all.reduce((n, r) => n + ((r.steps || []).length), 0);
  const settled = aggregate && Number.isFinite(Number(aggregate.settled_steps))
    ? Number(aggregate.settled_steps) : all.reduce((n, r) => n + (r.steps || []).filter((s) =>
      !["running", "queued"].includes(String(s.status || ""))).length, 0);
  const pct = total ? Math.max(0, Math.min(100, Math.round((settled / total) * 100))) : 0;
  const status = String(run.status || "");
  const active = status === "running" || status === "queued";
  const bad = status === "failed" || status === "cancelled" || status === "timeout";
  const statusText = runStatusText(run);
  const last = steps.slice().reverse().find((s) => s.summary || s.output || s.note) || steps[steps.length - 1];
  const lastText = last ? String(last.summary || last.output || last.note || "").replace(/\s+/g, " ").trim().slice(0, 240) : "";
  const executor = run.executor || run.implementer || (last && (last.agent_label || last.agent)) || "";
  const duration = runDurationSeconds(run);
  const etaText = runEtaText(run);
  const goal = (task && task.goal) || run.goal || run.title || "";
  const contract = (task && task.contract) || S.taskContracts[(task && task.id) || run.task_id] || null;
  const budget = run.budget && typeof run.budget === "object" ? run.budget : null;
  const budgetItems = budget ? [["calls", budget.calls, budget.max_calls], ["tokens", budget.tokens, budget.max_tokens], ["duration", budget.elapsed, budget.max_duration]] : [];
  const budgetHtml = budgetItems.some((item) => item[2])
    ? '<div class="rd-budget"><b>' + esc(t("预算进度")) + '</b>' + budgetItems.filter((item) => item[2]).map((item) => {
      const pct = Math.min(100, Math.round(Number(item[1] || 0) * 100 / Number(item[2])));
      const label = item[0] === "calls" ? t("调用") : item[0] === "tokens" ? t("Tokens") : t("耗时");
      return '<div class="rd-budget-row"><span>' + esc(label) + '</span><div class="rd-budget-track"><i style="width:' + pct + '%"></i></div><small>' + esc(String(item[1] || 0)) + '/' + esc(String(item[2])) + '</small></div>';
    }).join("") + '</div>' : "";
  const verdict = run.verdict && typeof run.verdict === "object" ? run.verdict : {};
  const earlyProgressHtml = ""; // 全书状态由 continue-info 聚合，避免历史 run 显示过期进度。
  const degraded = verdict.review_degraded || verdict.quality_status === "degraded";
  const reviewHtml = degraded ? '<div class="rd-review-degraded" role="status"><strong>' + esc(t("评审降级")) + '</strong><span>' + esc((verdict.review_degradation_reasons || []).join("；") || t("当前没有满足门槛的评审者")) + '</span></div>' : "";
  const dagNodes = (run.plan && run.plan.steps) || run.subtasks || [];
  const dagHtml = Array.isArray(dagNodes) && dagNodes.length ? '<div class="rd-dag"><b>' + esc(t("任务 DAG")) + '</b>' + dagNodes.map((node, index) => '<div class="rd-dag-node"><span>' + (index + 1) + '</span><strong>' + esc(node.title || node.id || node.role || t("步骤")) + '</strong>' + ((node.depends_on || []).length ? '<small>← ' + esc(node.depends_on.join(", ")) + '</small>' : '') + '</div>').join("") + '</div>' : "";
  const expert = task && task.expert_snapshot && task.expert_snapshot.id
    ? task.expert_snapshot : null;
  const actions = [];
  if (total) actions.push('<button type="button" class="ghost" data-overview-tab="steps">' + esc(t("查看步骤")) + "</button>");
  if (last && last.log) actions.push('<button type="button" class="ghost" data-overview-run="' + esc(run.id) + '" data-overview-log="' + esc(last.log) + '">' + esc(t("打开 CLI 日志")) + "</button>");
  if (status === "done" || run.report) actions.push('<button type="button" class="ghost" data-overview-tab="result">' + esc(t("查看成果")) + "</button>");
  box.innerHTML =
    '<div class="rd-overview-main">' +
      '<div class="rd-overview-kicker">' + esc(t("任务概览")) + '</div>' +
      '<div class="rd-overview-title" title="' + esc(run.title || "") + '">' + esc(run.title || "") + '</div>' +
      (goal ? '<div class="rd-overview-goal" title="' + esc(goal) + '">' + esc(goal) + '</div>' : "") +
      (expert ? '<div class="rd-expert-proof" title="' + esc((expert.prompt || "").slice(0, 300)) + '">' +
        '<span class="rd-expert-proof-label">' + esc(t("专家模板")) + '</span>' +
        '<strong>' + esc(expert.name || expert.id) + '</strong>' +
        '<span class="rd-expert-proof-version">v' + esc(expert.version || "?") + '</span>' +
        (expert.content_sha256 ? '<code>' + esc(String(expert.content_sha256).slice(0, 12)) + '</code>' : "") +
        '</div>' : "") +
    '</div>' +
    '<div class="rd-overview-state">' +
      '<span class="state-label">' + esc(t("当前状态")) + '</span>' +
      '<strong class="state-value ' + (bad ? "bad" : status === "done" ? "ok" : "") + '">' + esc(statusText) + '</strong>' +
    '</div>' +
    '<div class="rd-overview-progress" aria-label="' + esc(pct + "%") + '"><i style="width:' + pct + '%"></i></div>' +
    '<div class="rd-overview-facts">' +
      '<span><b>' + settled + "/" + total + '</b> ' + esc(t("步骤已完成")) + '</span>' +
      (executor ? '<span>' + esc(t("执行者")) + ' <b>' + esc(executor) + '</b></span>' : "") +
      (duration != null ? '<span>' + esc(t("耗时")) + ' <b>' + esc(chatDurTxt(duration < 1 ? Number(duration.toFixed(1)) : Math.round(duration))) + '</b></span>' : "") +
      (etaText ? '<span class="rd-eta">' + esc(etaText) + '</span>' : "") +
    '</div>' +
    earlyProgressHtml + reviewHtml + budgetHtml + dagHtml + capabilityEvidenceHtml(run.capabilities) +
    (lastText ? '<div class="rd-overview-last"><b>' + esc(t("最近一步")) + '</b><span>' + esc(lastText) + '</span></div>' : "") +
    (contract ? contractOverviewHtml(contract) : "") +
    (actions.length ? '<div class="rd-overview-actions">' + actions.join("") + '</div>' : "");
  box.classList.remove("hidden");
  refreshEarlyFinishChainInfo(task, run.id);
}

/* 运行时能力证据：run.capabilities 由 capability_runtime 在任务开始和
 * 内置智能体收尾时写入。这里明确区分“已纳入本次提示词/工具循环”和
 * “MCP 实际发现/调用”，避免把安装目录误显示成已使用能力。 */
function capabilityEvidenceHtml(capabilities) {
  const cap = capabilities && typeof capabilities === "object" ? capabilities : null;
  if (!cap) return "";
  const list = (value) => Array.isArray(value) ? value.filter(Boolean).map((x) => String(x)) : [];
  const skills = list(cap.skills);
  const plugins = list(cap.plugins);
  const external = list(cap.external_skills);
  const mcp = cap.mcp && typeof cap.mcp === "object" ? cap.mcp : {};
  const runtime = cap.runtime && typeof cap.runtime === "object" ? cap.runtime : {};
  const discovered = Number(mcp.discovered || 0);
  const called = list(mcp.called);
  const pills = [];
  if (skills.length) pills.push('<span class="rd-capability-pill"><b>' + esc(t("经验/内置 Skill")) + '</b> ' + esc(skills.join(", ")) + '</span>');
  if (plugins.length) pills.push('<span class="rd-capability-pill"><b>' + esc(t("插件提示")) + '</b> ' + esc(plugins.join(", ")) + '</span>');
  if (external.length) pills.push('<span class="rd-capability-pill"><b>' + esc(t("外部 Skill")) + '</b> ' + esc(external.join(", ")) + '</span>');
  if (cap.knowledge) pills.push('<span class="rd-capability-pill"><b>' + esc(t("知识库")) + '</b> ' + esc(t("已注入")) + '</span>');
  if (discovered || called.length) {
    const mcpText = called.length
      ? t("已调用") + " " + called.length + " · " + called.join(", ")
      : t("已发现") + " " + discovered;
    pills.push('<span class="rd-capability-pill"><b>MCP</b> ' + esc(mcpText) + '</span>');
  }
  const promptCalls = Number(runtime.prompt_calls || 0);
  const capabilityPrompts = Number(runtime.capability_prompts || 0);
  const promptAgents = list(runtime.agents);
  if (promptCalls || capabilityPrompts) {
    const promptText = t("CLI提示词") + " " + capabilityPrompts + "/" + promptCalls +
      (promptAgents.length ? " · " + promptAgents.join(", ") : "");
    pills.push('<span class="rd-capability-pill"><b>' + esc(t("运行时注入")) + '</b> ' + esc(promptText) + '</span>');
  }
  if (!pills.length) return '<div class="rd-capability-evidence"><b>' + esc(t("运行时能力证据")) + '</b><span class="hint">' + esc(t("本次运行未注入匹配的经验、Skill 或 MCP 工具")) + '</span></div>';
  return '<div class="rd-capability-evidence"><b>' + esc(t("运行时能力证据")) + '</b><div class="rd-capability-pills">' + pills.join("") + '</div></div>';
}

function contractOverviewHtml(contract) {
  const criteria = Array.isArray(contract.acceptance_criteria) ? contract.acceptance_criteria : [];
  const evidence = Array.isArray(contract.evidence) ? contract.evidence : [];
  const latest = {};
  evidence.forEach((e) => { if (e && e.criterion) latest[e.criterion] = e; });
  const passed = criteria.filter((c) => latest[c] && latest[c].status === "passed").length;
  const approval = contract.approval_required
    ? (contract.approval && contract.approval.status === "approved" ? t("已审批") : t("待审批")) : t("无需审批");
  const taskId = String(contract.task_id || "");
  const approvalAction = contract.approval_required && (!contract.approval || contract.approval.status !== "approved")
    ? '<button type="button" class="ghost small" onclick="contractAction(\'' + jsq(taskId) + '\',\'approve\')">' + esc(t("批准发布")) + '</button>' : "";
  const evidenceText = criteria.map((c) => {
    const e = latest[c];
    const controls = '<button type="button" class="rd-contract-mark pass" title="' + esc(t("标记通过")) + '" onclick="contractEvidenceAction(\'' + jsq(taskId) + '\',\'' + jsq(c) + '\',\'passed\')">✓</button>' +
      '<button type="button" class="rd-contract-mark fail" title="' + esc(t("标记失败")) + '" onclick="contractEvidenceAction(\'' + jsq(taskId) + '\',\'' + jsq(c) + '\',\'failed\')">×</button>';
    return '<span class="rd-contract-criterion ' + (e ? esc(e.status) : "pending") + '">' + esc(c) + ': ' + esc(e ? e.status : t("待验收")) + controls + '</span>';
  }).join("");
  const evidenceDetails = evidence.map((e) => {
    if (!e || typeof e !== "object") return "";
    const coverage = e.coverage && typeof e.coverage === "object" ? e.coverage : {};
    const provenance = e.provenance && typeof e.provenance === "object" ? e.provenance : {};
    const tags = [
      t("覆盖") + "：" + (coverage.status || "unknown") + (coverage.scope ? " · " + coverage.scope : ""),
      provenance.source || e.source ? t("来源") + "：" + (provenance.source || e.source) : "",
      provenance.run_id ? t("运行 ID") + "：" + provenance.run_id : "",
      provenance.step_id ? t("步骤 ID") + "：" + provenance.step_id : "",
      provenance.untrusted_content ? t("包含未验证内容") : "",
    ].filter(Boolean).map((value) => '<span class="rd-contract-evidence-tag">' + esc(value) + '</span>').join("");
    const lists = [
      ...(Array.isArray(e.unknown) ? e.unknown : []),
      ...(Array.isArray(e.limitations) ? e.limitations : []),
    ].filter((value) => typeof value === "string" && value.trim()).map((value) => '<li>' + esc(value) + '</li>').join("");
    return '<article class="rd-contract-evidence-item"><div><b>' + esc(e.criterion || t("补充证据")) + '</b>' +
      (e.summary ? '<p>' + esc(e.summary) + '</p>' : "") + '</div>' +
      (tags ? '<div class="rd-contract-evidence-tags">' + tags + '</div>' : "") +
      (lists ? '<ul>' + lists + '</ul>' : "") + '</article>';
  }).filter(Boolean).join("");
  return '<div class="rd-contract"><b>' + esc(t("任务契约")) + '</b>' +
    '<span>' + esc(t("验收")) + ' ' + passed + '/' + criteria.length + '</span>' +
    '<span>' + esc(t("审批")) + ' ' + esc(approval) + '</span>' +
    (evidenceText ? '<div class="rd-contract-evidence">' + evidenceText + '</div>' : "") +
    (evidenceDetails ? '<section class="rd-contract-evidence-details"><b>' + esc(t("验证证据详情")) + '</b>' + evidenceDetails + '</section>' : "") + approvalAction +
    (contract.blocked_reason ? '<span class="err">' + esc(t("Blocked：")) + esc(contract.blocked_reason) + '</span>' : "") +
    '</div>';
}

async function contractAction(taskId, op) {
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/contract", {
      method: "POST", body: JSON.stringify({ op: op, actor: "ui" })
    });
    if (data && data.contract) S.taskContracts[taskId] = data.contract;
    toast(op === "approve" ? t("已批准发布") : t("契约已更新"));
    refreshState();
  } catch (e) { toast((e && e.message) || t("操作失败"), true); }
}
window.contractAction = contractAction;

async function contractEvidenceAction(taskId, criterion, status) {
  const summary = await uiPrompt(t("证据说明（可空）"), "");
  if (summary === null) return;
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/contract", {
      method: "POST", body: JSON.stringify({ op: "evidence", actor: "ui",
        evidence: { criterion: criterion, status: status, summary: summary, source: "manual" } })
    });
    if (data && data.contract) S.taskContracts[taskId] = data.contract;
    toast(t("证据已记录"));
    refreshState();
  } catch (e) { toast((e && e.message) || t("操作失败"), true); }
}
window.contractEvidenceAction = contractEvidenceAction;

/* 对话条三件套：与任务参数双向同步（2026-09-21 用户反馈「这里面也需要同步改」）。
 * 回填自当前任务；改动即写任务（空闲态），发送 /chat 前再兜底同步一次。 */
let rdPrefsTaskId = "";
let rdModelPv = "", rdModelMv = "";   // 对话条当前模型选择（厂商 id + 模型名）
let rdModelAgent = "";                // 手动指定的执行 CLI（空 = 不指定）

function rdPrefsFill(task) {
  if (!task) return;
  const set1 = (id, v, allow) => { const el = $(id); if (el && allow.includes(v)) el.value = v; };
  set1("rd-mode", task.mode, ["auto", "fast", "expert", "manual"]);
  set1("rd-thinking", task.thinking, ["auto", "low", "standard", "high"]);
  if (rdPrefsTaskId !== task.id) {
    rdPrefsTaskId = task.id;
    rdModelPv = task.direct_provider_id || "";
    rdModelMv = task.direct_model || "";
    rdModelAgent = task.direct_agent || "";
  }
  ["rd-mode", "rd-thinking"].forEach((id) => syncCmpSelFace(id));
  rdModelFaceSync();
}

function rdModelFaceSync() {
  const face = $("rd-model-btn");
  if (!face) return;
  if (rdModelAgent) {
    const a = realCliAgents().find((x) => x.id === rdModelAgent);
    face.textContent = (a ? (a.label || a.id) : rdModelAgent) + " · CLI";
    return;
  }
  if (!rdModelPv) { face.textContent = t("自动推荐"); return; }
  const p = directProviders().find((x) => x.id === rdModelPv);
  face.textContent = (p ? (p.name || p.id) : rdModelPv) +
    (rdModelMv ? "/" + rdModelMv : "/" + t("推荐"));
}

/* 对话条模型菜单（与新建 composer 的 cmp-model-menu 同款两级钻取，独立实例） */
let rdMenuProv = "";

function rdModelMenuRender() {
  const menu = $("rd-model-menu");
  if (!menu) return;
  const chk = '<svg class="ico ti-check" aria-hidden="true"><use href="#i-check"></use></svg>';
  const arr = '<svg class="ico ti-check" aria-hidden="true"><use href="#i-chevron-r"></use></svg>';
  if (!rdMenuProv) {
    menu.innerHTML =
      '<button type="button" class="type-item" data-p="" data-m=""><span class="ti-body"><span class="ti-name">' +
        t("自动推荐") + "</span></span>" + (!rdModelPv && !rdModelAgent ? chk : "") + "</button>" +
      directProviders().map((p) =>
        '<button type="button" class="type-item" data-p="' + esc(p.id) + '"><span class="ti-body"><span class="ti-name">' +
        esc(p.name || p.id) + "</span></span>" + (rdModelPv === p.id && !rdModelAgent ? chk : arr) + "</button>").join("") +
      cliMenuSectionHtml(rdModelAgent) +
      '<div class="type-menu-foot"><button type="button" class="type-item" data-manage="1"><span class="ti-body"><span class="ti-name">' +
        t("管理模型…") + "</span></span></button></div>";
  } else {
    const p = directProviders().find((x) => x.id === rdMenuProv);
    // 只列启用模型：停用的选了也会被运行时拒（builtin_agent.resolve 对账启用名单）
    const names = p ? (p.models || []).filter((m) => !m.hidden && m.enabled !== false)
      .map((m) => m.name).filter(Boolean) : [];
    menu.innerHTML =
      '<button type="button" class="type-item" data-back="1"><span class="ti-body"><span class="ti-name">‹ ' +
        esc(p ? (p.name || p.id) : rdMenuProv) + "</span></span></button>" +
      '<button type="button" class="type-item" data-p="' + esc(rdMenuProv) + '" data-m=""><span class="ti-body"><span class="ti-name">' +
        t("随厂商推荐") + "</span></span>" + (rdModelPv === rdMenuProv && !rdModelMv ? chk : "") + "</button>" +
      names.map((n) =>
        '<button type="button" class="type-item" data-p="' + esc(rdMenuProv) + '" data-m="' + esc(n) + '"><span class="ti-body"><span class="ti-name">' +
        esc(n) + "</span></span>" + (rdModelPv === rdMenuProv && rdModelMv === n ? chk : "") + "</button>").join("");
  }
  positionFloatingModelMenu(menu, $("rd-model-wrap"));
}

function toggleRdModelMenu(force) {
  const menu = $("rd-model-menu");
  if (!menu) return;
  const show = force !== undefined ? force : menu.classList.contains("hidden");
  if (show) { rdMenuProv = ""; rdModelMenuRender(); }
  menu.classList.toggle("hidden", !show);
  if (show) positionFloatingModelMenu(menu, $("rd-model-wrap"));
}
window.toggleRdModelMenu = toggleRdModelMenu;

(function () {
  const menu = $("rd-model-menu");
  if (!menu || menu.dataset.rdBound) return;
  document.body.appendChild(menu);
  menu.dataset.rdBound = "1";
  menu.addEventListener("click", (e) => {
    e.stopPropagation();   // 同 cmp-model-menu：防「点外面收起」误判（DOM 重写竞态）
    const b = e.target.closest("[data-p],[data-back],[data-manage],[data-cli]");
    if (!b) return;
    if (b.dataset.manage) { toggleRdModelMenu(false); switchTab("models"); return; }
    if (b.dataset.back) { rdMenuProv = ""; rdModelMenuRender(); return; }
    if (b.dataset.cli !== undefined) {
      rdModelAgent = b.dataset.cli;
      rdModelFaceSync();
      toggleRdModelMenu(false);
      rdPrefsPush("model");
      return;
    }
    if (b.dataset.m === undefined) { rdMenuProv = b.dataset.p; rdModelMenuRender(); return; }
    rdModelPv = b.dataset.p;
    rdModelMv = b.dataset.m;
    rdModelAgent = "";   // 选定模型/自动推荐：CLI 指定随之清除（互斥）
    rdModelFaceSync();
    toggleRdModelMenu(false);
    rdPrefsPush("model");
  });
  document.addEventListener("click", (e) => {
    const wrap = $("rd-model-wrap");
    if (wrap && !wrap.contains(e.target) && !menu.contains(e.target)) toggleRdModelMenu(false);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") toggleRdModelMenu(false);
  });
})();

// 任务总时限（秒）选项：任务信息弹层里的空闲可改项（2026-09-24 戍边骑奴案：
// 12 章连载默认 1 小时在慢链天跑不完）。值不入轮询重建的 rd-meta，防 select 弹回。
const TASK_TIMEOUT_CHOICES = [
  [1800, t("30 分钟")], [3600, t("1 小时")], [7200, t("2 小时")], [10800, t("3 小时")],
  [14400, t("4 小时")], [21600, t("6 小时")], [43200, t("12 小时")], [86400, t("24 小时")],
];

function timeoutLabel(s) {
  const hit = TASK_TIMEOUT_CHOICES.find((c) => c[0] === Number(s));
  if (hit) return hit[1];
  const m = Math.round(Number(s) / 60);
  return (m >= 60 ? (Math.round(m / 60 * 10) / 10) + t(" 小时") : m + t(" 分钟"));
}

function renderTimeoutRow(rcTask, run) {
  const row = $("rd-timeout-row"), sel = $("rd-timeout");
  if (!row || !sel) return;
  if (!rcTask) { row.classList.add("hidden"); return; }
  row.classList.remove("hidden");
  const cur = Number(rcTask.timeout_s || 3600);
  // 选项一次性构建；当前值不在档内时补一项，避免选中丢失
  const want = TASK_TIMEOUT_CHOICES.map((c) => c[0]).concat(
    TASK_TIMEOUT_CHOICES.some((c) => c[0] === cur) ? [] : [cur]).join(",");
  if (sel.dataset.choices !== want) {
    sel.dataset.choices = want;
    sel.innerHTML = TASK_TIMEOUT_CHOICES
      .map((c) => '<option value="' + c[0] + '">' + esc(t(c[1])) + "</option>").join("") +
      (TASK_TIMEOUT_CHOICES.some((c) => c[0] === cur)
        ? "" : '<option value="' + cur + '">' + esc(t("自定义 ") + timeoutLabel(cur)) + "</option>");
  }
  const busy = ["queued", "running"].indexOf(rcTask.status) >= 0;
  sel.disabled = busy;
  // 用户正操作（含失焦瞬间）不回写 value，防轮询把刚选的值弹回旧值
  if (document.activeElement !== sel) sel.value = String(cur);
  if (!sel.dataset.bound) {
    sel.dataset.bound = "1";
    sel.addEventListener("change", async () => {
      const task = (S.state && (S.state.tasks || []).find((x) => x.id === rcTask.id)) || rcTask;
      const patch = { timeout_s: Number(sel.value) || 3600 };
      if (task.rev != null) patch.expected_rev = task.rev;
      try {
        const data = await api("/api/tasks/" + encodeURIComponent(rcTask.id) + "/params", {
          method: "POST", operation: false, body: JSON.stringify(patch) });
        if (data && data.rev != null) task.rev = data.rev;
        task.timeout_s = patch.timeout_s;   // 即时回显，不等轮询
      } catch (e) { toast(e && e.message ? e.message : t("保存失败"), true); }
    });
  }
}

async function rdPrefsPush(what) {
  // what: mode|thinking|model（变更源）；写任务参数（空闲态才允许）
  const task = (S.lastRun && S.lastRun.task_id && S.state &&
    (S.state.tasks || []).find((x) => x.id === S.lastRun.task_id)) || null;
  if (!task) return;
  const patch = {};
  if (what === "mode") patch.mode = $("rd-mode").value;
  if (what === "thinking") patch.thinking = $("rd-thinking").value;
  if (what === "model") {
    patch.direct_provider_id = rdModelPv;
    patch.direct_model = rdModelMv;
    patch.direct_agent = rdModelAgent;
  }
  // 修订 CAS（借鉴 WorkDSH 契约纪律）：带上页面所见的任务修订号，别的窗口
  // 先改过则后端拒绝过期写入；本地提示后由轮询回填最新值——「我改成功了」
  // 的假象（实际已被人覆盖）就此消失。
  if (task.rev != null) patch.expected_rev = task.rev;
  try {
    const data = await api("/api/tasks/" + encodeURIComponent(task.id) + "/params", {
      method: "POST", operation: false, body: JSON.stringify(patch) });
    if (data && data.rev != null) task.rev = data.rev;   // 续用凭据：连推时后几次不再过期
  } catch (e) {
    if (String((e && e.message) || "").indexOf("已被其他窗口修改") >= 0) {
      toast(e.message, true);   // 冲突要可见：静默吞掉=又一种假成功
    }
    /* 运行中/网络失败不打断对话，发送前还有兜底 */
  }
}

async function rdPrefsPushAll() {
  // 发送前兜底：三个一起推（/chat 开新一轮前调用）。改为顺序推——三次都带
  // expected_rev，并发推会在第一次成功后让后两次全成过期写入被拒；
  // 值已在前端，失败静默同前，下一轮 poll 的回填也不会覆盖用户刚选的值。
  await rdPrefsPush("mode");
  await rdPrefsPush("thinking");
  await rdPrefsPush("model");
}

function drawChatAtts() {
  syncChatSendControls();
  const box = $("rd-chat-att-list");
  if (!box) return;
  // 点名字开预览（待提交区原文走 /api/attachments/<id>），× 才是移除。
  // 图片直接展示缩略图（2026-09-21 用户反馈「图片要展示出来」）
  box.innerHTML = chatAtts.map((a, i) => {
    const isImg = /^image\//i.test(String(a.mime || "")) ||
      /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(a.name || "");
    if (isImg && a.id) {
      const src = "/api/attachments/" + encodeURIComponent(a.id) + qsAuth();
      return '<span class="att-view rd-att-thumb" data-att-id="' + esc(a.id) +
        '" data-att-name="' + esc(a.name) + '" title="' + esc(a.name) + '">' +
        '<img src="' + esc(src) + '" alt="' + esc(a.name) + '" loading="lazy" draggable="false">' +
        '<b onclick="chatRemoveAtt(' + i + ')" title="' + esc(t("移除")) + '">×</b></span>';
    }
    return '<span class="att-chip2 att-view" data-att-id="' + esc(a.id || "") +
      '" data-att-name="' + esc(a.name) + '" title="' + esc(t("点击查看")) + '">' + esc(a.name) +
      '<b onclick="chatRemoveAtt(' + i + ')" title="' + esc(t("移除")) + '">×' +
      '</b></span>';
  }).join("");
}
window.chatRemoveAtt = function (i) { chatAtts.splice(i, 1); drawChatAtts(); };

/* 对话附件点击预览：已落盘的走 run 工作目录 /api/runs/<id>/file（rel 为
 * _attachments/ 相对路径），待提交的走 /api/attachments/<id>；
 * 弹窗与成品预览同款——图片直接看图、文本看码、二进制给下载。 */
window.chatAttPopup = function (rel) {
  if (!rel || !chatRunId) return;
  return _fpPreviewUrl("/api/runs/" + encodeURIComponent(chatRunId) +
    "/file?name=" + encodeURIComponent(rel), rel);
};
window.chatPendingPopup = function (id, name) {
  if (!id) return;
  return _fpPreviewUrl("/api/attachments/" + encodeURIComponent(id), name || "attachment");
};

async function chatUploadFiles(files) {
  for (const f of files) {
    try {
      const b64 = await new Promise((res, rej) => {
        const rd = new FileReader();
        rd.onload = () => res(String(rd.result).split(",")[1] || "");
        rd.onerror = () => rej(new Error(t("读取失败")));
        rd.readAsDataURL(f);
      });
      const r = await api("/api/attachments", { method: "POST",
        body: JSON.stringify({ name: f.name, data: b64 }) });
      chatAtts.push(r.attachment); drawChatAtts();
      // 图片能力前置提醒：模型 image_in 未开启时收不到图（内置智能体会降级为
      // 纯文本，模型只能回复「读不到」——与其事后看模型解释，不如发图时提一句）
      if (/^image\//i.test(String(f.type || "")) || /\.(png|jpe?g|gif|webp|bmp)$/i.test(f.name || "")) {
        if (!window._chatImgTipShown) {
          window._chatImgTipShown = true;
          toast(t("已添加图片。若当前模型未开启「图」输入（模型接入页可开），模型将看不到这张图"));
        }
      }
    } catch (e) { toast(t("附件上传失败：") + f.name + " — " + e.message, true); }
  }
}

function renderChatQueue(items, run = S.lastRun || {}) {
  const box = $("rd-chat-queue");
  if (!box) return;
  const pending = items.map((item, index) => ({ item, index }))
    .filter(({ item }) => item.kind === "user" && !item.consumed && item.id && item.run);
  const active = ["running", "queued"].includes(run.status);
  const signature = JSON.stringify([pending, active, typeof getLang === "function" ? getLang() : "zh"]);
  if (box.dataset.queueSignature === signature) return;
  box.dataset.queueSignature = signature;
  box.classList.toggle("hidden", !pending.length);
  box.innerHTML = pending.map(({ item, index }) => {
    const guiding = active && item.delivery === "now";
    const text = item.text || t("（仅附件）");
    const attachments = (item.attachments || []).length;
    return '<div class="chat-queue-row' + (guiding ? ' guiding' : '') + '">' +
      '<svg class="ico chat-queue-icon" aria-hidden="true"><use href="#i-' + (guiding ? 'arrow-up' : 'grip') + '"></use></svg>' +
      '<span class="chat-queue-text" title="' + esc(text) + '">' + esc(text) + '</span>' +
      (attachments ? '<span class="chat-queue-count" title="' + esc(t("附件")) + '">+' + attachments + '</span>' : '') +
      (guiding ? '<span class="chat-queue-status" role="status">' + esc(t("正在引导")) + '</span>'
        : '<button type="button" data-chat-steer="' + index + '" title="' + esc(t("立即发送并引导")) + '">↪ <span>' + esc(t("引导")) + '</span></button>') +
      '<button type="button" class="chat-queue-remove" data-chat-retract="' + index + '" title="' + esc(t("删除排队消息")) + '" aria-label="' + esc(t("删除排队消息")) + '">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-x"></use></svg></button></div>';
  }).join("");
  syncChatSendControls();
}

async function chatPendingAction(event) {
  const button = event.target.closest("[data-chat-steer], [data-chat-retract]");
  if (!button || button.disabled || chatSending) return;
  const steering = button.hasAttribute("data-chat-steer");
  const item = chatTimelineItems[Number(steering ? button.dataset.chatSteer : button.dataset.chatRetract)];
  if (!item || item.consumed || !item.run || !item.id || !chatRunId) return;
  const viewedRun = chatRunId;
  chatSending = true;
  syncChatSendControls();
  try {
    const result = await api("/api/runs/" + encodeURIComponent(steering ? viewedRun : item.run) +
      (steering ? "/chat" : "/messages/retract"), {
      method: "POST", body: JSON.stringify(steering ? { message_id: item.id, delivery: "now" } : { id: item.id }),
    });
    // A backend without queued-message steering must never report a false success.
    if (steering && (!result.run_id || result.delivery !== "now" && result.delivery !== "sent")) {
      throw new Error(t("后端尚未支持消息引导，请更新并重启服务"));
    }
    toast(t(steering ? "已立即发送，正在按新消息继续" : t("已撤回排队消息")));
    if (chatRunId !== viewedRun) return;
    chatSig = ""; chatLiveSig = "";
    if (result.run_id) {
      if (S.detailTaskKey) { S.taskSig = ""; renderTaskDetail(); }
      else jumpToRun(result.run_id);
    } else if (S.lastRun) {
      await renderChat(S.lastRun, ["running", "queued"].includes(S.lastRun.status));
    }
  } catch (error) {
    toast(error.message, true);
    if (error.status === 409 && error.data && error.data.run_id && chatRunId === viewedRun) {
      // A stale tab can race a newer follow-up run. Keep the queued message
      // intact, but move the user to the run the server identified so the
      // next click acts on the current conversation.
      jumpToRun(error.data.run_id);
    }
    if (chatRunId === viewedRun && S.lastRun) {
      chatSig = ""; chatLiveSig = "";
      renderChat(S.lastRun, ["running", "queued"].includes(S.lastRun.status));
    }
  } finally { chatSending = false; syncChatSendControls(); }
}

window.chatSend = async function (delivery = "queue") {
  if (!chatRunId || chatSending) return;
  delivery = delivery === "now" ? "now" : "queue";
  const ta = $("rd-chat-input");
  const draft = ta.value || "", text = draft.trim();
  if (!text && !chatAtts.length) return;
  const submittedRun = chatRunId, submittedAtts = chatAtts.map((a) => a.id);
  const run = S.lastRun || {};
  const active = run.status === "running" || run.status === "queued";
  chatSending = true;
  chatCloseSendMenu();
  syncChatSendControls();
  try {
    if (!active) await rdPrefsPushAll();
    // The server decides using the current run status, so a turn ending between
    // Enter and receipt starts a follow-up instead of stranding the message.
    const r = await api("/api/runs/" + encodeURIComponent(submittedRun) + "/chat", {
      method: "POST", body: JSON.stringify({ text, attachments: submittedAtts, delivery }),
    });
    if (delivery === "now" && (!r.run_id || r.delivery !== "now" && r.delivery !== "sent")) {
      throw new Error(t("后端尚未支持消息引导，请更新并重启服务"));
    }
    toast(t(r.created_task ? t("已新建 CodeBee 任务，开始执行")
      : r.delivery === "now" ? "已立即发送，正在按新消息继续"
      : r.run_id ? t("已开新一轮，接着做…") : t("已排队：当前步骤结束后送达")));
    if (chatRunId !== submittedRun) return;
    // Preserve any new draft/attachments composed while this request was in flight.
    if (ta.value === draft) { ta.value = ""; ta.style.height = ""; }
    chatAtts = chatAtts.filter(a => !submittedAtts.includes(a.id)); drawChatAtts();
    chatSig = "";   // 强制重画时间线
    chatJumpLatest();   // 发完滚到最新：看到自己刚发的消息与正在来的回复
    if (r.run_id) {
      if (r.created_task) { jumpToRun(r.run_id); }
      else if (S.detailTaskKey) { S.taskSig = ""; renderTaskDetail(); }
      else jumpToRun(r.run_id);
    } else {
      try {
        const d = await api("/api/runs/" + encodeURIComponent(submittedRun));
        if (d.run && chatRunId === submittedRun) renderChat(d.run, d.run.status === "running" || d.run.status === "queued");
      } catch (e) { /* Delivery succeeded; a timeline refresh must not imply send failure. */ }
    }
  } catch (e) {
    if (e.status === 409 && e.data && e.data.run_id && chatRunId === submittedRun) {
      toast(t("对话已进入新一轮，已切换到最新会话，请重新发送"), true);
      jumpToRun(e.data.run_id);
    } else {
      toast(t("发送失败：") + e.message, true);
    }
  }
  finally { chatSending = false; syncChatSendControls(); }
};

function bindChat() {
  const btn = $("rd-chat-attach"), file = $("rd-chat-file"), send = $("rd-chat-send"),
        ta = $("rd-chat-input");
  if (!btn || !file || !send || !ta) return;
  const runStatus = $("rd-chat-run-status");
  if ($("rd-chat-stop")) $("rd-chat-stop").addEventListener("click", cancelRun);
  if (runStatus) {
    runStatus.querySelector("[data-chat-run-pause]").addEventListener("click", window.dirTogglePause);
    runStatus.querySelector("[data-chat-run-cancel]").addEventListener("click", cancelRun);
  }
  document.querySelectorAll("[data-chat-workspace-toggle]").forEach((toggle) =>
    toggle.addEventListener("click", () => chatWorkspaceToggle()));
  const workspace = $("rd-chat-workspace");
  if (workspace) {
    const close = workspace.querySelector("[data-chat-workspace-close]");
    if (close) close.addEventListener("click", () => chatWorkspaceToggle(false));
    const files = $("rd-chat-workspace-files");
    if (files) files.addEventListener("click", (e) => {
      const button = e.target.closest("[data-chat-workspace-file]");
      if (button) chatWorkspaceOpenFile(button.dataset.chatWorkspaceFile || "");
    });
    const editor = $("rd-chat-editor-text");
    if (editor) editor.addEventListener("input", () => {
      chatWorkspaceState.dirty = true;
      chatWorkspaceSetState(t("有未保存的修改"));
      chatWorkspaceSyncLayout();
    });
    const save = workspace.querySelector("[data-chat-editor-save]");
    if (save) save.addEventListener("click", chatWorkspaceSave);
  }
  const focusBtn = $("rd-chat-focus");
  if (focusBtn) focusBtn.addEventListener("click", () => {
    chatJumpLatest();   // 继续对话：先看到最新一轮再开口
    S.rdTab = "chat";
    S.rdTabPin = true;
    applyRdTabs();
    setTimeout(() => ta.focus(), 0);
  });
  btn.addEventListener("click", () => file.click());
  file.addEventListener("change", (e) => {
    chatUploadFiles(Array.from(e.target.files || []));
    e.target.value = "";
  });
  send.addEventListener("click", () => window.chatSend());
  $("rd-chat-queue")?.addEventListener("click", chatPendingAction);
  const sendOptions = $("rd-chat-send-options"), sendMenu = $("rd-chat-send-menu");
  if (sendOptions && sendMenu) {
    sendOptions.addEventListener("click", () => {
      const open = sendMenu.classList.contains("hidden");
      sendMenu.classList.toggle("hidden", !open);
      sendOptions.setAttribute("aria-expanded", String(open));
      if (open) sendMenu.querySelector("button:not(:disabled)")?.focus();
    });
    sendMenu.addEventListener("click", e => {
      const button = e.target.closest("[data-chat-delivery]");
      if (button) window.chatSend(button.dataset.chatDelivery);
    });
    sendMenu.addEventListener("keydown", e => {
      const buttons = [...sendMenu.querySelectorAll("button:not(:disabled)")];
      if (e.key === "Escape") { chatCloseSendMenu(); sendOptions.focus(); }
      if (["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key) && buttons.length) {
        e.preventDefault();
        const index = buttons.indexOf(document.activeElement);
        const next = e.key === "Home" ? 0 : e.key === "End" ? buttons.length - 1
          : (index + (e.key === "ArrowUp" ? -1 : 1) + buttons.length) % buttons.length;
        buttons[next].focus();
      }
    });
    document.addEventListener("click", e => { if (!e.target.closest(".chat-send-actions")) chatCloseSendMenu(); });
    document.addEventListener("keydown", e => { if (e.key === "Escape") chatCloseSendMenu(); });
  }
  // 自动伸高：跟内容走、有上限（160px 后内部滚动）；清空由 chatSend 归零。
  // 高度只由用户输入驱动，轮询重画不碰它——框框不再忽大忽小
  ta.addEventListener("input", () => {
    ta.style.height = "auto";
    ta.style.height = Math.min(ta.scrollHeight, 160) + "px";
    syncChatSendControls();
  });
  // 移动端软键盘会缩短 visual viewport；把输入条主动带回可视区，
  // 避免窄屏详情里键盘弹出后发送按钮落在屏幕下方（尤其是 Android Chrome）。
  const keepChatInputVisible = () => {
    if (document.activeElement !== ta || window.innerWidth > 720) return;
    requestAnimationFrame(() => {
      try { ta.scrollIntoView({ block: "nearest", inline: "nearest" }); }
      catch (e) { ta.scrollIntoView(); }
    });
  };
  ta.addEventListener("focus", () => setTimeout(keepChatInputVisible, 60));
  if (window.visualViewport) window.visualViewport.addEventListener("resize", keepChatInputVisible);
  ta.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault(); window.chatSend(e.ctrlKey || e.metaKey ? "now" : "queue");
    }
  });
  ta.addEventListener("paste", (e) => {
    const items = Array.from((e.clipboardData || {}).items || [])
      .filter((it) => it.kind === "file" && it.type.startsWith("image/"));
    if (!items.length) return;
    e.preventDefault();
    chatUploadFiles(items.map((it) => {
      const f = it.getAsFile();
      return f && !f.name ? new File([f], "paste-" + Date.now() + ".png", { type: f.type }) : f;
    }).filter(Boolean));
  });
  // 附件胶囊点击预览：委托绑在静态容器上——时间线轮询整块重建 innerHTML、
  // 输入条胶囊增删重画，都不丢监听。时间线胶囊走已落盘文件，输入条胶囊
  // （× 移除按钮除外）走待提交区
  $("rd-chat-flow").addEventListener("click", (e) => {
    const activityDetails = e.target.closest("details.chat-tool-group[data-chat-activity-key]");
    if (activityDetails) {
      const key = activityDetails.dataset.chatActivityKey || "";
      setTimeout(() => {
        if (!activityDetails.isConnected) return;
        chatDisclosureState.set(activityDetails.dataset.chatDisclosure, { open: activityDetails.open });
        if (activityDetails.open && !chatActivityCache.has(key)) {
          const split = key.indexOf("\n");
          if (split >= 0) chatLoadLog(key.slice(0, split), key.slice(split + 1));
        }
      }, 0);
      return;
    }
    const logDetails = e.target.closest("details.chat-cli-log[data-chat-log-key]");
    if (logDetails) {
      const key = logDetails.dataset.chatLogKey || "";
      const split = key.indexOf("\n");
      if (split >= 0) {
        const run = key.slice(0, split), rel = key.slice(split + 1);
        setTimeout(() => {
          if (logDetails.open) { chatLogOpen.add(key); chatLogClosed.delete(key); chatLoadLog(run, rel); }
          else { chatLogOpen.delete(key); chatLogClosed.add(key); }
        }, 0);
      }
      return;
    }
    const logBtn = e.target.closest("[data-chat-log-run][data-chat-log-rel]");
    if (logBtn) { e.stopPropagation(); toggleLog(logBtn.dataset.chatLogRun, logBtn.dataset.chatLogRel); return; }
    // 建议追问芯片：点击把整句回填输入框（不直接发送——用户可改后再发），焦点落输入框
    const fup = e.target.closest(".chat-fup-btn[data-fup]");
    if (fup) {
      const ta = $("rd-chat-input");
      if (ta) {
        ta.value = fup.dataset.fup;
        ta.dispatchEvent(new Event("input", { bubbles: true }));
        ta.focus();
      }
      return;
    }
    const changeFile = e.target.closest("[data-chat-change-file]");
    if (changeFile) {
      e.preventDefault();
      const path = changeFile.dataset.chatChangeFile || "";
      const runId = changeFile.dataset.chatChangeRun || "";
      if (!path) return;
      const active = ["running", "queued"].includes(String(
        ((S.detailSide || {}).task || {}).status || (S.lastRun && S.lastRun.status) || ""));
      if (active) gitWbDiff(path);
      else fileDiffPopup(path, runId);
      return;
    }
    const changeUndo = e.target.closest("[data-chat-change-undo]");
    if (changeUndo) {
      e.preventDefault();
      changeUndo.disabled = true;
      undoChatChanges(changeUndo.dataset.chatChangeUndo).catch(() => { changeUndo.disabled = false; });
      return;
    }
    const changeSubmit = e.target.closest("[data-chat-change-submit]");
    if (changeSubmit) {
      e.preventDefault();
      changeSubmit.disabled = true;
      submitChatChanges(changeSubmit.dataset.chatChangeSubmit).finally(() => { changeSubmit.disabled = false; });
      return;
    }
    const changeView = e.target.closest("[data-chat-change-view]");
    if (changeView) {
      e.preventDefault();
      if (S.detailSide && S.detailSide.git && S.detailSide.git.branch) openChangeSummaryGit();
      else {
        S.rdTab = "git";
        S.rdTabPin = true;
        if (S.lastRun) renderGitPanel(S.lastRun, S.lastRunTask);
        applyRdTabs();
      }
      return;
    }
    const file = e.target.closest(".chat-file-open[data-file-run]");
    if (file) {
      e.preventDefault();
      artPopup(file.dataset.fileRun, file.dataset.fileName || "", Number(file.dataset.fileSize) || 0);
      return;
    }
    // 复制 / 编辑重发（2026-09-22 用户诉求：已发送的对话可复制修改再次发送）。
    // 编辑=原文载入输入框，用户改完按发送即再次发出（不静默自动重发）
    const act = e.target.closest("[data-cact]");
    if (act) {
      const it = chatTimelineItems[Number(act.dataset.ci)];
      if (!it) return;
      // 复制=看到的正文（评审裁定气泡给摘要版）；编辑重发必须原文（裁定
      // 摘要回发给模型没有意义，原文才是它的上一轮输出）
      const rawTxt = it.kind === "user" ? String(it.text || "") : chatCleanText(it.text);
      const txt = act.dataset.cact === "copy"
        ? (verdictDigestText(rawTxt, true) || rawTxt) : rawTxt;
      if (act.dataset.cact === "copy") {
        copyText(txt, () => toast(t("已复制")));
      } else if (act.dataset.cact === "edit") {
        const ta = $("rd-chat-input");
        if (ta && txt) {
          ta.value = txt;
          ta.focus();
          ta.selectionStart = ta.selectionEnd = ta.value.length;
          toast(t("已载入原文，可修改后发送"));
        }
      }
      return;
    }
    const chip = e.target.closest(".att-open");
    if (chip) window.chatAttPopup(chip.dataset.att);
  });
  const attBox = $("rd-chat-att-list");
  if (attBox) attBox.addEventListener("click", (e) => {
    if (e.target.closest("b")) return;   // × 自己的 onclick 负责移除
    const chip = e.target.closest("[data-att-id]");
    if (chip) window.chatPendingPopup(chip.dataset.attId, chip.dataset.attName);
  });
  // 对话条三件套：改动即写任务参数（空闲态），face 跟随
  $("rd-mode").addEventListener("change", () => { syncCmpSelFace("rd-mode"); rdPrefsPush("mode"); });
  $("rd-thinking").addEventListener("change", () => { syncCmpSelFace("rd-thinking"); rdPrefsPush("thinking"); });
  // 语音输入（借鉴 paseo voice control）：Web Speech API 口述转文字填入输入框。
  // 仅浏览器支持时显示按钮（Chrome/Edge）；识别结果追加到光标处，不自动发送。
  bindVoiceInput();
}

function bindVoiceInput() {
  const btn = $("rd-chat-voice");
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!btn || !SR) return;   // 浏览器不支持：按钮保持 hidden
  btn.classList.remove("hidden");
  let rec = null, on = false;
  const ta = $("rd-chat-input");
  btn.addEventListener("click", () => {
    if (on) { try { rec.stop(); } catch (e) {} return; }
    rec = new SR();
    rec.lang = (getLang() === "en") ? "en-US" : "zh-CN";
    rec.continuous = true;
    rec.interimResults = false;
    rec.onresult = (e) => {
      if (!ta) return;
      let text = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) text += e.results[i][0].transcript;
      }
      if (text) {
        text = voiceFixup(text);
        ta.value = (ta.value ? ta.value.replace(/\s+$/, "") + " " : "") + text;
        ta.dispatchEvent(new Event("input", { bubbles: true }));
      }
    };
    rec.onend = () => { on = false; btn.classList.remove("live"); };
    rec.onerror = () => { on = false; btn.classList.remove("live"); };
    try { rec.start(); on = true; btn.classList.add("live"); }
    catch (e) { toast(t("语音不可用，请检查麦克风权限"), true); }
  });
}

/* 语音识别结果纠偏（借鉴 lexicon 个人词典）：设置→外观→语音输入里维护的
 * 专有名词表（localStorage orch.voice_terms，一行一个「错误→正确」或直接「术语」）。
 * 「错误→正确」整词替换；裸术语把大小写漂移的识别结果统一成给定拼法
 * （codebee/CodeBee→CodeBee），只动独立成词的出现，避免 "AI" 改坏 "said"。 */
function voiceFixup(text) {
  let terms = [];
  try {
    const raw = localStorage.getItem("orch.voice_terms") || "";
    terms = raw.split("\n").map((l) => l.trim()).filter(Boolean);
  } catch (e) {}
  for (const term of terms) {
    const m = term.split("→");
    if (m.length === 2 && m[0].trim() && m[1].trim()) {
      text = text.split(m[0].trim()).join(m[1].trim());
    } else {
      const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      try { text = text.replace(new RegExp("(?<![A-Za-z0-9])" + escaped + "(?![A-Za-z0-9])", "gi"), term); } catch (e) {}
    }
  }
  return text;
}

/* 设置页词表编辑器：词表与皮肤同族只存本机（localStorage），保存即写回，
 * 下一次口述立即生效，无需重启或刷新之外的任何动作。 */
function loadVoiceTerms() {
  const ta = $("set-voice-terms");
  if (!ta) return;
  try { ta.value = localStorage.getItem("orch.voice_terms") || ""; } catch (e) { ta.value = ""; }
}
function saveVoiceTerms() {
  const ta = $("set-voice-terms");
  if (!ta) return;
  try { localStorage.setItem("orch.voice_terms", ta.value); toast(t("语音词表已保存")); }
  catch (e) { toast(t("保存失败，请重试"), true); }
}

/* ---------------------------------------------------------- 外观：布局 + 皮肤 + 明暗（换肤） */
/* 布局与配色是两条独立配置：布局只改页面骨架（data-layout），配色只改变量（data-skin）。
 * 调色板全部在 style.css / skin-gradients.css（html[data-skin="X"]，每套含夜间/日间
 * 两版变量）；这里只放顺序与文案。卡片预览色块用 skinPalette 从 CSS 变量实时取值，
 * 不在 JS 里重复写色值——改色只需要动 CSS，预览与真实界面不会各自漂移。 */
const SKINS = [
  { id: "ocean", name: t("深海"), desc: t("藏青底色 + 天蓝强调，夜间长时间盯任务更沉静（默认）") },
  { id: "apple", name: t("苹果"), desc: t("System Blue + 毛玻璃纵深 + 大圆角，Apple HIG 风格") },
  { id: "hermes", name: t("墨金"), desc: t("暖墨底色 + 金色发丝线，Hermes 式古典优雅") },
  { id: "classic", name: t("经典"), desc: t("黑白灰 + 蓝色强调，ChatGPT 式清爽配色") },
  { id: "paper", name: t("简白"), desc: t("纯白画布 + 浅灰分区 + 克制蓝强调，Codex 式极简明亮") },
  { id: "forest", name: t("森野"), desc: t("墨绿底色 + 青翠强调，偏自然的护眼配色") },
  { id: "amber", name: t("暖阳"), desc: t("暖棕底色 + 琥珀强调，纸感暖调") },
  { id: "warm", name: t("暖纸"), desc: t("米白底色 + 琥珀强调，护眼暖调") },
  { id: "sea", name: t("海盐"), desc: t("弥散渐变：蓝紫 × 薄荷 × 湖青，清透克制") },
  { id: "blossom", name: t("樱雾"), desc: t("弥散渐变：紫罗兰 × 樱花粉 × 奶白，柔和轻盈") },
  { id: "dusk", name: t("暮霞"), desc: t("弥散渐变：薰衣草 × 蜜黄 × 藕粉，黄昏暖调") },
  { id: "coral", name: t("珊瑚"), desc: t("弥散渐变：珊瑚橘 × 暖粉 × 象牙白，落日暖调") },
  { id: "violet", name: t("霓虹"), desc: t("暗紫底色 + 品红强调，霓虹感强") },
  { id: "contrast", name: t("高对比"), desc: t("纯黑 / 纯白 + 硬边框、去阴影，弱视与强光环境更清晰") },
];
const SKIN_IDS = new Set(SKINS.map((s) => s.id));
const SKIN_KEY = "orch.skin";
const THEME_KEY = "orch.theme";

const LAYOUTS = [
  { id: "classic", name: t("经典工作区"), desc: t("左侧任务树 + 居中主栏，一屏专注当前任务") },
  { id: "workbench", name: t("工作台"), desc: t("首页输入卡 + 右侧状态栏，全局进度与待办一眼可见（默认）") },
];
const LAYOUT_IDS = new Set(LAYOUTS.map((x) => x.id));
const LAYOUT_KEY = "orch.layout";

function currentSkin() {
  const s = localStorage.getItem(SKIN_KEY) || "";
  return SKIN_IDS.has(s) ? s : "ocean";   // 值缺失/非法（如换过版本）一律回落深海
}

/* 布局独立于皮肤，默认工作台；首次进入由 applyAppearance() 把该默认值落盘，
 * 之后用户显式选过的布局不会被换肤等操作带走。 */
function currentLayout() {
  const v = localStorage.getItem(LAYOUT_KEY) || "";
  return LAYOUT_IDS.has(v) ? v : "workbench";
}

function currentMode() { return localStorage.getItem(THEME_KEY) === "dark" ? "dark" : "light"; }

/* 取某皮肤在指定明暗下的实际配色：临时拨到根属性读计算值再还原。
 * 同步执行，浏览器不会中途绘制，所以看不到闪烁。 */
function skinPalette(id, mode) {
  const root = document.documentElement;
  const skin0 = root.dataset.skin, theme0 = root.dataset.theme;
  root.dataset.skin = id;
  root.dataset.theme = mode;
  const cs = getComputedStyle(root);
  const get = (n) => cs.getPropertyValue(n).trim();
  const pal = { bg: get("--bg"), sidebar: get("--sidebar"), accent: get("--accent"), accent2: get("--accent2"), text: get("--text"), art: get("--bg-art") };
  root.dataset.skin = skin0;
  root.dataset.theme = theme0;
  return pal;
}

/* 把布局 + 皮肤 + 明暗落到根属性，并同步顶栏两个入口、手机状态栏色 */
function applyAppearance() {
  const root = document.documentElement;
  const skin = currentSkin(), mode = currentMode(), layout = currentLayout();
  if (!localStorage.getItem(LAYOUT_KEY)) localStorage.setItem(LAYOUT_KEY, layout);
  root.dataset.skin = skin;
  root.dataset.theme = mode;
  root.dataset.layout = layout;
  const dark = mode === "dark";
  const th = $("btn-theme");
  if (th) th.innerHTML = '<svg class="ico" aria-hidden="true"><use href="#i-' + (dark ? "moon" : "sun") + '"></use></svg>';
  // 手机浏览器的状态栏 / 地址栏配色跟着皮肤走（各皮肤底色差异大，写死一个色会脱节）
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) {
    const side = getComputedStyle(root).getPropertyValue("--sidebar").trim();
    if (side) meta.setAttribute("content", side);
  }
  applyCodeTheme();   // 代码主题跟随明暗：换的其实是 [data-codetheme] 指向的那套调色板
}

function setThemeMode(mode) {
  localStorage.setItem(THEME_KEY, mode === "light" ? "light" : "dark");
  applyAppearance();
  renderAppearance();
  renderCodePreviews();   // 明暗换了，「当前生效」徽章跟着挪到另一张预览卡
}

function setSkin(id) {
  if (!SKIN_IDS.has(id)) return;
  localStorage.setItem(SKIN_KEY, id);
  applyAppearance();
  renderAppearance();
  const s = SKINS.find((x) => x.id === id);
  toast(t("已换肤：") + (s ? t(s.name) : id) + t("（") + (currentMode() === "dark" ? t("夜间") : t("日间")) + t("）"));
}

/* 布局切换只动骨架：留在设置页可即时对比配色，不强行跳页；
 * 若当前已经在主页而新布局没有主页，退出设置时由 exitSettings 落到真实表单。 */
function setLayout(id) {
  if (!LAYOUT_IDS.has(id)) return;
  localStorage.setItem(LAYOUT_KEY, id);
  applyAppearance();
  renderAppearance();
  if (id !== "workbench" && S.tab === "home") exitSettings(true);
  const l = LAYOUTS.find((x) => x.id === id);
  toast(t("已切换布局：") + (l ? t(l.name) : id));
}

function toggleTheme() { setThemeMode(currentMode() === "light" ? "dark" : "light"); }

// The task board is a separate page but shares these persisted appearance
// preferences. Keep an already-open workbench in sync when the board changes
// either value in another tab/window.
window.addEventListener("storage", (event) => {
  if (event.key !== SKIN_KEY && event.key !== THEME_KEY && event.key !== LAYOUT_KEY) return;
  applyAppearance();
  renderAppearance();
  renderCodePreviews();
  if (event.key === LAYOUT_KEY && currentLayout() !== "workbench" && S.tab === "home") exitSettings(true);
});

/* 暖色皮肤主页：渲染日期 + 最近任务（数据全部来自 S.state.runs，无假数） */
function renderHome() {
  const dateEl = $("rd-home-date");
  if (dateEl) {
    const now = new Date();
    const weekdays = ["日", "一", "二", "三", "四", "五", "六"];
    dateEl.textContent = (now.getMonth() + 1) + " 月 " + now.getDate() + " 日 · 星期" + weekdays[now.getDay()];
  }

  // 快捷入口里的通道体检摘要：复用体检页缓存，60 秒内不重复请求
  homeHealthRefresh();

  // 卡头目录/分支展示已随主页假身一并移除：主页直接载真表单 composer，
  // 工作目录与分支信息由 composer 自身的 cmp-wd 行与 git 行承载。

  const listEl = $("rd-recent-list");
  if (!listEl) return;
  const runs = (S.state && S.state.runs) || [];
  const recent = runs.slice(0, 5);
  if (recent.length === 0) {
    listEl.innerHTML = '<div style="text-align:center;padding:24px;color:var(--muted);font-size:13px">' + t("暂无任务") + "</div>";
    return;
  }
  listEl.innerHTML = recent.map((r) => {
    const tone = r.status === "running" ? "run" : (r.status === "queued" || r.status === "cancelled") ? "wait" : (r.status === "failed" || r.status === "timeout") ? "bad" : "ok";
    const label = r.status === "running" ? t("运行中") : r.status === "queued" ? t("排队中")
      : r.status === "failed" ? t("失败") : r.status === "timeout" ? t("超时")
      : r.status === "cancelled" ? t("已取消") : t("已完成");
    const icon = tone === "run" ? '<span class="rd-task-spin" aria-hidden="true"></span>'
      : tone === "wait" ? '<span class="rd-task-pause" aria-hidden="true"><i></i><i></i></span>'
      : '<svg class="ico" aria-hidden="true"><use href="#i-' + (tone === "ok" ? "check" : "x") + '"></use></svg>';
    // 进度契约与状态栏一致：step_count 折算、current_step 是对象取 .n
    const total = r.step_count || 0;
    const progress = total ? Math.min(100, Math.max(0, Math.round(Number(r.progress) || 0))) : (r.progress != null ? Math.round(Number(r.progress)) : null);
    const pct = progress == null ? null : Math.min(100, Math.max(0, progress));
    const step = (r.current_step && r.current_step.n) || 0;
    const time = relTime(r.created_at || r.started_at || "");
    const metaHtml = (time ? '<svg class="ico rd-meta-clock" aria-hidden="true"><use href="#i-clock"></use></svg><span>' + esc(time) + "</span>" : "")
      + [r.flow_name || r.flow || "", total ? t("第 ") + step + "/" + total + t(" 步") : ""].filter(Boolean)
        .map((x) => '<span class="rd-m3-dot"></span><span>' + esc(String(x)) + "</span>").join("");
    return '<button type="button" class="rd-task-item" onclick="homeOpenRun(\'' + jsq(r.id || "") + '\')">'
      + '<span class="rd-task-ico ' + tone + '">' + icon + "</span>"
      + '<span class="rd-task-info">'
      + '<span class="rd-task-title">' + esc(r.title || r.id || "") + "</span>"
      + '<span class="rd-meta3">' + metaHtml + "</span>"
      + "</span>"
      + '<span class="rd-task-side ' + tone + '">'
      + '<span class="rd-task-chip">' + esc(label) + "</span>"
      + '<span class="rd-task-track"><i style="width:' + (pct == null ? 0 : pct) + '%"></i></span>'
      + '<span class="rd-task-pct">' + (pct == null ? "—" : pct + "%") + "</span>"
      + "</span>"
      + "</button>";
  }).join("");
}

/* 主页直载真表单 composer：主页不放简化假身，把 #sub-tasks .cmp-box 原样
 * 搬进 #rd-input-slot——ID 全不变，目录/类型/专家/附件/能力菜单在主页直接
 * 可用，发送即真实提交不跳页；离开主页搬回 #sub-tasks .form 原位。
 * 「新聊天」入口则直达任务表单页本身的简洁形态（exitSettings(true)）。 */
function homeMountComposer() {
  const slot = $("rd-input-slot"), box = document.querySelector("#sub-tasks .cmp-box");
  if (!slot || !box || box.parentElement === slot) return;
  slot.appendChild(box);
}
function homeUnmountComposer() {
  const box = document.querySelector("#rd-input-slot .cmp-box");
  if (!box) return;
  const form = document.querySelector("#sub-tasks .form");
  if (form) form.appendChild(box);
}

/* 暖色皮肤主页显隐：与 switchTab 同一套状态（tab/mainPage/settings-mode/页名），
 * 不走 switchTab 本体——那套会把 .page 全收进 page-settings 体系 */
function showHome() {
  if (S.detailRunId || S.detailTaskKey) closeRun();
  S.tab = "home";
  S.mainPage = "";
  stopAutoPoll();
  homeMountComposer();
  document.body.classList.remove("settings-mode", "files-mode");
  const main = document.querySelector("main");
  if (main) main.classList.remove("browser-page-active");
  document.querySelectorAll(".page").forEach((p) => p.classList.toggle("hidden", p.id !== "page-home"));
  document.querySelectorAll(".set-item").forEach((b) => b.classList.remove("active"));
  document.querySelectorAll(".qitem").forEach((b) => b.classList.toggle("active", b.id === "btn-q-home"));
  document.querySelectorAll(".rail-btn[data-rail-page]").forEach((b) => b.classList.remove("active"));
  const title = $("page-title");
  if (title) title.textContent = t("工作台");
  const crumb = $("crumb-root");
  if (crumb) crumb.classList.add("hidden");
  renderHome();
  syncInspectorVis();
}

/* 主页点最近任务：详情面板都住在 page-settings 壳里，而主页游离在壳外——
 * 先把壳切回运行页再 sideOpenRun，否则详情在一个隐藏页面里翻开（=点了没反应） */
function homeOpenRun(id) {
  switchTab("runs", "main");
  sideOpenRun(id);
}

/* 主页已直载真表单 composer（见 homeMountComposer）：旧的主页假身桥接
 * （homeToForm/homeSend/homePickWorkspace）随假身 DOM 一并移除，
 * 主页的输入/发送/目录选择全由真表单自身的 ID 链路承担。 */

/* 外观页：布局卡片 + 皮肤卡片（点选即换） + 明暗分段控。选中态同时给描边与
 * 勾选，不只靠颜色深浅传达，保证在高对比等皮肤下也一眼可辨。 */
function renderAppearance() {
  const layoutGrid = $("layout-grid");
  if (layoutGrid) {
    const curLayout = currentLayout();
    layoutGrid.innerHTML = LAYOUTS.map((l) => {
      const prev = l.id === "workbench"
        ? '<span class="layout-prev lp-workbench" aria-hidden="true"><span class="lp-side"><i></i><i></i><i></i></span><span class="lp-main"><i class="lp-card"></i><i class="lp-bar w70"></i><i class="lp-bar w45"></i></span><span class="lp-status"><i></i><i></i><i></i></span></span>'
        : '<span class="layout-prev lp-classic" aria-hidden="true"><span class="lp-rail"></span><span class="lp-side"><i></i><i></i><i></i></span><span class="lp-main"><i class="lp-bar w70"></i><i class="lp-bar w45"></i><i class="lp-card"></i></span></span>';
      return '<button type="button" class="layout-card' + (l.id === curLayout ? " active" : "") + '" data-layout="' + esc(l.id) + '" title="' + esc(t(l.desc)) + '" onclick="setLayout(\'' + jsq(l.id) + '\')">'
        + prev
        + '<span class="layout-meta"><span class="layout-name">' + esc(t(l.name)) + '</span>'
        + '<svg class="ico layout-check" aria-hidden="true"><use href="#i-check"></use></svg></span>'
        + '<span class="layout-desc">' + esc(t(l.desc)) + '</span>'
        + '</button>';
    }).join("");
  }
  const layoutTag = $("layout-cur");
  if (layoutTag) {
    const l = LAYOUTS.find((x) => x.id === currentLayout());
    layoutTag.textContent = l ? t(l.name) : currentLayout();
  }
  const grid = $("skin-grid");
  if (!grid) return;
  const cur = currentSkin(), mode = currentMode();
  grid.innerHTML = SKINS.map((s) => {
    const p = skinPalette(s.id, mode);
    return '<button type="button" class="skin-card' + (s.id === cur ? " active" : "") + '" data-skin="' + s.id + '" title="' + esc(t(s.desc)) + '">'
      + '<span class="skin-prev" aria-hidden="true">'
      + '<span class="pv-side" style="background:' + p.sidebar + '"></span>'
      + '<span class="pv-main" style="background:' + (p.art ? p.art + "," : "") + p.bg + '">'
      + '<span class="pv-bar w85" style="background:' + p.accent + '"></span>'
      + '<span class="pv-bar w60" style="background:' + p.text + ';opacity:.3"></span>'
      + '<span class="pv-bar w40" style="background:' + p.accent2 + '"></span>'
      + '</span></span>'
      + '<span class="skin-meta"><span class="skin-name">' + esc(t(s.name)) + '</span>'
      + '<svg class="ico skin-check" aria-hidden="true"><use href="#i-check"></use></svg></span>'
      + '<span class="skin-desc">' + esc(t(s.desc)) + '</span>'
      + '</button>';
  }).join("");
  document.querySelectorAll("#skin-mode [data-mode]").forEach((b) => b.classList.toggle("active", b.dataset.mode === mode));
  const tag = $("skin-cur");
  if (tag) {
    const s = SKINS.find((x) => x.id === cur);
    tag.textContent = (s ? t(s.name) : cur) + " · " + (mode === "dark" ? t("夜间") : t("日间"));
  }
}

/* ---------------------------------------------------------- 代码设置：高亮主题 + 行号/换行/字号 */
/* 只管代码内容（文件弹窗 / diff 弹窗 / 预览卡），不受界面字号影响。偏好存 localStorage
 * （与皮肤同模式，设备级）。主题 = 一小份 --ct-* CSS 变量，作用域挂
 * [data-ctheme-mode][data-codetheme]：html 上由 applyCodeTheme 落当前生效主题，
 * 预览卡同名属性拨到另一套即可同屏双色，无需 iframe。 */
const CODE_THEMES = [
  { id: "github", name: "GitHub Light", dark: false, desc: t("经典浅色，清爽不抢眼，日间界面首选") },
  { id: "vs", name: "Visual Studio Light", dark: false, desc: t("VS 家族浅色，蓝紫关键词配色") },
  { id: "xcode", name: "Xcode Light", dark: false, desc: t("苹果开发工具同款浅色，冷色克制") },
  { id: "solarized", name: "Solarized Light", dark: false, desc: t("米黄纸感底色，长时间阅读更柔和") },
  { id: "github-dark", name: "GitHub Dark", dark: true, desc: t("经典深色，夜间界面首选") },
  { id: "vs2015", name: "Visual Studio Dark", dark: true, desc: t("VS 家族深色，灰蓝底更沉稳") },
  { id: "monokai", name: "Monokai", dark: true, desc: t("高饱和黄紫粉，老牌编辑器名主题") },
  { id: "one-dark", name: "One Dark", dark: true, desc: t("Atom 出品的均衡深色，蓝灰底不刺眼") },
];
const CT_LIGHT_KEY = "orch.codeTheme.light";
const CT_DARK_KEY = "orch.codeTheme.dark";
const CT_LINENUM_KEY = "orch.code.linenum";
const CT_WRAP_KEY = "orch.code.wrap";
const CT_SIZE_KEY = "orch.code.size";
const CS_SAMPLE = [
  "const themePreview: ThemeConfig = {",
  '  surface: "sidebar",',
  '  accent: "#339CFF",',
  "  contrast: 45,",
  "};",
].join("\n");

function codeThemeFor(mode) {
  const saved = localStorage.getItem(mode === "dark" ? CT_DARK_KEY : CT_LIGHT_KEY) || "";
  const ok = CODE_THEMES.find((x) => x.id === saved && ((mode === "dark") === !!x.dark));
  return ok ? ok.id : (mode === "dark" ? "github-dark" : "github");
}
function codeLineNum() { return localStorage.getItem(CT_LINENUM_KEY) !== "0"; }   // 缺省开
function codeWrap() { return localStorage.getItem(CT_WRAP_KEY) !== "0"; }   // 缺省开：长行自动换行，别撑出横向滚动条
function codeFontSize() {
  const n = parseFloat(localStorage.getItem(CT_SIZE_KEY) || "12.5");
  return isFinite(n) ? Math.min(22, Math.max(10, n)) : 12.5;
}

/* 把当前代码主题 + 行号/换行/字号落到根属性（随明暗切换一起被 applyAppearance 调） */
function applyCodeTheme() {
  const root = document.documentElement;
  const mode = currentMode();
  root.dataset.cthemeMode = mode;
  root.dataset.codetheme = codeThemeFor(mode);
  root.classList.toggle("code-linenum", codeLineNum());
  root.classList.toggle("code-wrap", codeWrap());
  root.style.setProperty("--code-size", codeFontSize() + "px");
}

/* 单趟字符扫描 tokenize：不依赖长正则，逐字符判定注释/字符串/数字/单词。
 * 覆盖 JS/TS/Python/Go/Rust/Java/C 的常见词法；类型映射到 .ct-* 上色类。 */
const _CT_KW = new Set(("if else for while return function class import export from const let var " +
  "new this super extends implements interface type enum public private protected static async await " +
  "try catch finally throw switch case break continue default do in of typeof instanceof void delete " +
  "yield defer go func package chan select struct map nil null true false None True False self def lambda " +
  "elif pass raise with as and or not is fn impl pub use mut match loop crate mod").split(" "));

function _ctIsWordChar(d) {
  return (d >= "a" && d <= "z") || (d >= "A" && d <= "Z") || (d >= "0" && d <= "9") || d === "_" || d === "$";
}

function _ctScan(src) {
  const out = [];
  let i = 0;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === "/" && src[i + 1] === "/") {
      let j = src.indexOf("\n", i);
      if (j < 0) j = n;
      out.push({ t: "com", v: src.slice(i, j) });
      i = j;
    } else if (c === "#") {
      let j = src.indexOf("\n", i);
      if (j < 0) j = n;
      out.push({ t: "com", v: src.slice(i, j) });
      i = j;
    } else if (c === "/" && src[i + 1] === "*") {
      let j = src.indexOf("*/", i + 2);
      j = j < 0 ? n : j + 2;
      out.push({ t: "com", v: src.slice(i, j) });
      i = j;
    } else if (c === '"' || c === "'" || c === "`") {
      let j = i + 1;
      while (j < n) {
        if (src[j] === "\\") { j += 2; continue; }
        j++;
        if (src[j - 1] === c || src[j - 1] === "\n") break;   // 未闭合到行尾为止
      }
      out.push({ t: "str", v: src.slice(i, j) });
      i = j;
    } else if (c >= "0" && c <= "9") {
      let j = i;
      while (j < n && ((src[j] >= "0" && src[j] <= "9") || src[j] === ".")) j++;
      out.push({ t: "num", v: src.slice(i, j) });
      i = j;
    } else if ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c === "_" || c === "$") {
      let j = i;
      while (j < n && _ctIsWordChar(src[j])) j++;
      const w = src.slice(i, j);
      out.push({ t: _CT_KW.has(w) ? "kw" : (src[j] === "(" ? "fn" : "txt"), v: w });
      i = j;
    } else {
      out.push({ t: "txt", v: c });
      i++;
    }
  }
  return out;
}

function _ctWrapHTML(toks) {
  let html = "";
  for (const k of toks) html += k.t === "txt" ? esc(k.v) : '<span class="ct-' + k.t + '">' + esc(k.v) + "</span>";
  return html;
}

/* 行号 + 高亮二合一：单 <table>（行号列 + 代码列），滚动/换行时天然对齐。 */
function codeBlockHTML(text) {
  const lines = String(text || "").replace(/\n$/, "").split("\n");
  const rows = lines.map((ln, i) =>
    "<tr>" + '<td class="cb-ln">' + (i + 1) + "</td>" +
    '<td class="cb-code">' + _ctWrapHTML(_ctScan(ln)) + "</td></tr>");
  return '<table class="code-block"><tbody>' + rows.join("") + "</tbody></table>";
}

function renderCodeSettings() {
  const selL = $("cs-theme-light"), selD = $("cs-theme-dark");
  if (!selL) return;
  const fill = (sel, dark) => {
    sel.innerHTML = CODE_THEMES.filter((x) => !!x.dark === dark).map((x) =>
      '<option value="' + x.id + '"' + (x.id === codeThemeFor(dark ? "dark" : "light") ? " selected" : "") + ">" + esc(t(x.desc)) + "</option>").join("");
  };
  fill(selL, false);
  fill(selD, true);
  $("cs-linenum").checked = codeLineNum();
  $("cs-wrap").checked = codeWrap();
  $("cs-size").value = codeFontSize();
  renderCodePreviews();
}

function renderCodePreviews() {
  for (const mode of ["light", "dark"]) {
    const code = document.querySelector("#cs-preview-" + mode + " .cs-pv-code");
    if (!code) continue;
    const thId = codeThemeFor(mode);
    const th = CODE_THEMES.find((x) => x.id === thId);
    code.dataset.codetheme = thId;
    code.innerHTML = codeBlockHTML(CS_SAMPLE);
    const badge = document.querySelector("#cs-preview-" + mode + " .cs-pv-badge");
    const active = mode === currentMode();
    if (badge) {
      badge.textContent = active ? t("当前生效") : (mode === "dark" ? t("深色") : t("浅色"));
      badge.classList.toggle("cs-badge-on", active);
    }
    const tt = document.querySelector("#cs-preview-" + mode + " .cs-pv-theme");
    if (tt) tt.textContent = th ? t(th.desc) : thId;
  }
}

/* 代码设置改动 → 存偏好 + 立即生效 + 预览刷新；不重绘设置行本身（防选值弹回） */
function csApplyFromControls() {
  localStorage.setItem(CT_LIGHT_KEY, $("cs-theme-light").value);
  localStorage.setItem(CT_DARK_KEY, $("cs-theme-dark").value);
  localStorage.setItem(CT_LINENUM_KEY, $("cs-linenum").checked ? "1" : "0");
  localStorage.setItem(CT_WRAP_KEY, $("cs-wrap").checked ? "1" : "0");
  const n = parseFloat($("cs-size").value);
  localStorage.setItem(CT_SIZE_KEY, String(isFinite(n) ? Math.min(22, Math.max(10, n)) : 12.5));
  applyCodeTheme();
  renderCodePreviews();
}

/* 皮肤页锚点：「外观 / 代码」两胶囊。点击滚到对应面板（main 是滚动容器）；
 * main 滚动时反算当前区块高亮胶囊。只在皮肤页可见时计算，别处滚动不花开销。 */
let _apnClicking = false;   // 点击平滑滚动期间不抢高亮，落定后按位置归位

function apnScrollTo(id) {
  const el = document.getElementById(id);
  const main = document.querySelector("main");
  if (!el || !main) return;
  _apnClicking = true;
  el.scrollIntoView({ behavior: "smooth", block: "start" });
  setTimeout(() => { _apnClicking = false; apnSyncActive(); }, 600);   // 平滑滚动约 400-500ms
}

function apnSyncActive() {
  if (_apnClicking || S.tab !== "appearance") return;
  const main = document.querySelector("main");
  const anchor = document.getElementById("cs-anchor");
  if (!main || !anchor || anchor.offsetParent === null) return;   // 皮肤页没显示就不算
  const code = document.getElementById("apn-code");
  if (!code) return;
  // 代码面板顶进视口上缘（留一点余量）就算「代码」区，否则「外观」
  const onCode = code.getBoundingClientRect().top - main.getBoundingClientRect().top <= 120;
  anchor.querySelectorAll("[data-apn]").forEach((b) => b.classList.toggle("active", b.dataset.apn === (onCode ? "apn-code" : "apn-skin")));
}

/* ---------------------------------------------------------- 智能体目录：模型选择 */
const MAX_ORCH_MODELS = 3;   // 与后端 modelhub.MAX_BIND_MODELS、runner 降级链保持一致

/* 供应商有无可用密钥：keys 结构以「有启用且未冷却」为准；老数据单 KEY 看
 * api_key 镜像（与后端 _chain_keys / resolve_binding 的「无可用密钥」同口径） */
function provKeyOk(p) {
  if ((p || {}).credential_mode === "cli" && (p || {}).native_models) return true;
  const ks = (p || {}).keys || [];
  if (ks.length) return ks.some((k) => k.enabled !== false && !k.cooling);
  return !!(p || {}).api_key;
}

/* 供应商 → 已启用模型（按优先级），用于分组下拉与多选面板 */
function modelGroups() {
  const out = [];
  for (const p of S.providers || []) {
    if (p.enabled === false) continue;
    const ms = (p.models || [])
      .filter((m) => !m.hidden && m.enabled !== false)
      .sort((a, b) => (a.priority || 0) - (b.priority || 0))
      .map((m) => m.name).filter(Boolean);
    if (ms.length) out.push({ id: p.id, name: p.name, models: ms,
      protocol: p.protocol || "", caps: p.wire_caps || {}, keyOk: provKeyOk(p),
      credential_mode: p.credential_mode || "", native_cli: p.native_cli || "",
      native_models: !!p.native_models });
  }
  return out;
}

/* 供应商协议标签：auto 显示成「自动 · 实测 wire 列表」，便于一眼看出能注入什么 */
function protoLabel(p) {
  const proto = (p || {}).protocol || "";
  if (proto !== "auto") return proto;
  const caps = Object.keys((p || {}).wire_caps || {});
  return caps.length ? t("自动 · ") + caps.join("/") : t("自动（未探测）");
}

/* 供应商可否按 allow 里的某协议注入：显式协议或「模型接入」页适配测试
 * 通过的 wire_caps（auto 供应商全靠它）。返回命中的协议名，不适配返回空串。
 * 与 modelhub._entry_endpoint 同规则——它同时就是「注入本 CLI 实际走的 wire」，
 * 勾选面板据此标死解析时会被跳过的条目。 */
function provAdaptedProto(p, allow, kind) {
  if (!p) return "";
  // codex 0.154+ 只讲 responses wire：chat-only 端点（显式 wire_api=chat 或
  // wire_caps 实测为 chat）对 codex 等于没有可用协议——与后端 resolve_binding
  // 的剔除规则同源（2026-09-18 重写任务案：链显示健康、运行时必剔死的假象）
  const codexOnly = /codex/.test(String(kind || "").toLowerCase());
  const chatBlocked = (w) => codexOnly && (w || "responses") === "chat";
  if (allow.indexOf(p.protocol) >= 0) {
    if (chatBlocked(p.wire_api)) return "";
    return p.protocol;
  }
  const caps = p.wire_caps || {};
  return allow.find((pr) => (caps[pr] || {}).base
    && !chatBlocked((caps[pr] || {}).wire_api)) || "";
}

/* 死因细化：协议适配失败里最常见的一种是「openai 面实测只探到 chat 形态」
 * （codex 0.154+ 只讲 responses，其余 CLI 不受影响）。按真实死因说话——
 * 模型接入页明明亮着 openai ✓，链上却笼统说「协议不匹配」，看着就像自相矛盾。 */
function chatShapedFace(pv, allow) {
  if (!pv) return false;
  const chat = (w) => (w || "responses") === "chat";
  if (allow.indexOf(pv.protocol) >= 0 && chat(pv.wire_api)) return true;
  const caps = pv.wire_caps || {};
  return allow.some((pr) => (caps[pr] || {}).base && chat((caps[pr] || {}).wire_api));
}

/* CLI 允许注入的供应商 wire 协议——与 modelhub.resolve_binding 的 allowed 规则
 * 保持一致（codex 只吃 openai wire、claude 只吃 anthropic、dsh 只吃 OpenAI
 * 兼容端点，其余两种皆可）。后端会跳过不匹配的链条目，这里在选择层就挡住。 */
function bindAllowedProtocols(kind) {
  const k = String(kind || "").toLowerCase();
  if (/codex/.test(k)) return ["openai"];
  if (/claude/.test(k)) return ["anthropic"];
  if (/dsh|deepseek/.test(k)) return ["openai"];
  return ["anthropic", "openai"];
}

/* 默认模型下拉：按供应商分组，只列该 CLI 协议能吃的供应商（auto 靠 wire_caps 命中）；
 * 当前值不在过滤后列表里时保留为选项，避免显示丢失 */
function modelSelectHtml(id, current, kind) {
  const cur = fmtModel(current);
  const allow = bindAllowedProtocols(kind);
  // 无可用密钥的供应商不进下拉：默认模型配上去解析时也会被跳过（死配置）
  const groups = modelGroups().filter((g) => {
    const p = (S.providers || []).find((x) => x.id === g.id);
    return g.keyOk !== false && nativeCliMatches(p, kind) && provAdaptedProto(p, allow, kind);
  });
  let opts = '<option value="">' + t("（未设置）") + '</option>';
  if (cur && !groups.some((g) => g.models.includes(cur))) {
    opts += '<option value="' + esc(cur) + '" selected>' + esc(cur) + t("（当前值）") + "</option>";
  }
  for (const g of groups) {
    opts += '<optgroup label="' + esc(g.name) + '">' +
      g.models.map((m) => '<option value="' + esc(m) + '"' +
        (m === cur ? " selected" : "") + ">" + esc(m) + "</option>").join("") +
      "</optgroup>";
  }
  return '<select id="model-' + esc(id) + '">' + opts + "</select>";
}

/* 卡片右上角的更新状态徽标（进入本页时后台自动检查） */
function updateChip(c) {
  if (!c.installed) return "";
  const u = c.update || {};
  if (S.catalogChecking && u.status === "unknown") return '<span class="tag">' + t("检查更新中…") + '</span>';
  if (u.status === "updatable") return '<span class="tag upd">' + t("有新版本 ") + esc(u.latest || "") + "</span>";
  if (u.status === "current") return '<span class="tag ok">' + t("已是最新") + '</span>';
  if (u.status === "unsupported") return '<span class="tag">' + t("该渠道无法自动检查") + '</span>';
  return "";
}

/* 进入智能体目录页自动检查各 CLI 是否有新版本（后端 10 分钟缓存，前端 5 分钟节流） */
async function autoCheckUpdates() {
  if (Date.now() - (S.updateCheckAt || 0) < 5 * 60 * 1000) return;
  S.updateCheckAt = Date.now();
  // silent：进页自动检查撞上他设备控制权（423）时不准弹「接管并重试」模态框——
  // 弹框遮罩盖全屏吞滚轮，用户体感就是「所有页面都不能滚动」（2026-09-29 实测案）。
  // 用户主动点的「检查更新」走 checkUpdate(id) 通道，不受此影响。
  try { await api("/api/catalog/check-updates", { method: "POST", busy: false, silent: true }); } catch (e) { /* 忽略 */ }
  poll();
}

/* 运行时模型链（CLI 绑定页）：本地草稿态，点「保存」才写盘 */
function provName(pid) {
  const p = (S.providers || []).find((x) => x.id === pid);
  return p ? (p.name || pid) : "";
}

function bindChain(b) {
  if (b.chain && b.chain.length) return b.chain.map((c) => ({ p: c.provider_id || "", m: c.model || "" }));
  const pid = b.provider_id || "";
  const names = (b.models && b.models.length) ? b.models : (b.model ? [b.model] : []);
  return names.map((m) => ({ p: pid, m }));
}

function chainKey(chain) {
  return (chain || []).map((c) => c.p + "\u0002" + c.m).join("\u0001");
}

function bindSelById(id) {
  S.bindSel = S.bindSel || {};
  const server = bindChain((S.bindings || {})[id] || {});
  const key = chainKey(server);
  let st = S.bindSel[id];
  if (!st) {
    st = S.bindSel[id] = { open: false, chain: server, dirty: false, key };
  } else if (!st.dirty && st.key !== key) {
    st.chain = server;   // 别处改了配置 → 同步；本地有未保存改动时不覆盖
    st.key = key;
  }
  return st;
}

function bindRepaint() { S.bindSig = null; renderBindings(); }

/* 一键推荐绑定：给每个链为空的 CLI 按协议适配规则预填一条主模型。
 * 推荐顺序：显式协议原生匹配 > auto 且 wire_caps 命中；同分按 priority /
 * 数组序稳定。默认模型停用的厂商直接不推荐——它当前键位就是坏的，绑上去
 * 解析照样失败；没有合适的就什么都不绑（2026-09-17 用户拍板，不再保留
 * 「只剩它也上」的兜底）。只预填草稿态（dirty），逐条看清后各自保存
 * 或「全部保存」，健康链绝不被覆盖。 */
/* 评测台实测分（推荐选模用）：与后端 dispatch 同款软信号——只在该供应商的
 * 启用模型里挑「榜上有名且分最高」的那个，无数据保持 priority 首个（现状）。 */
async function refreshBenchScores() {
  const now = Date.now();
  if (S._benchAt && now - S._benchAt < 60000) return;   // 评测数据变化慢，60s 节流
  S._benchAt = now;
  try {
    const eb = await api("/api/evalbench");
    const map = {};
    (eb.leaderboard || []).forEach((r) => {
      if (r.overall != null) map[r.provider_id + "\n" + r.model] = r.overall;
    });
    S.benchScores = map;
  } catch (e) { /* 评测数据不可得时推荐保持原行为 */ }
}

function benchPick(pid, models) {
  const map = S.benchScores || {};
  let best = null, bestScore = -1;
  (models || []).forEach((m) => {
    const s = map[pid + "\n" + m.name];
    if (typeof s === "number" && s > bestScore) { best = m; bestScore = s; }
  });
  return best;
}

function recommendFor(c) {
  // 目录页「默认模型」下拉用 orch_kind || id 判协议（仅管理条目没有 orch_kind），
  // 推荐口径与下拉过滤保持一致；绑定页条目恒有 orch_kind，不受影响
  const allow = bindAllowedProtocols(c.orch_kind || c.id);
  const badDefault = (p) => (p.models || []).some((m) => m.name === p.model &&
    (m.hidden || m.enabled === false));
  const provs = (S.providers || []).filter((p) => !badDefault(p) && chainProvUsable(p, allow, c.orch_kind || c.id));
  if (!provs.length) return null;
  const score = (p) => (allow.indexOf(p.protocol) >= 0 ? 0 : 1) * 1000 + (p.priority || 0);
  provs.sort((a, b) => score(a) - score(b));
  const p = provs[0];
  const models = (p.models || []).filter((m) => !m.hidden && m.enabled !== false);
  if (!models.length) return null;
  // 供应商级选择规则保持不变（协议适配/优先级/冷却）；实测分只在模型级做偏好，
  // 且不覆盖「默认模型停用+500 降权」等既有防线——见 0922 禁自动调度拍板
  const bench = benchPick(p.id, models);
  return { p: p.id, m: (bench || models[0]).name };
}

/* 供应商对某 CLI 是否「推荐可用」：启用、协议适配，且至少有一把不在冷却期的
 * KEY（全冷却=欠费失效，推荐了也白推荐——解析层照样失败）。 */
function chainProvUsable(p, allow, kind) {
  if (!p || p.enabled === false) return false;
  if (!provAdaptedProto(p, allow, kind)) return false;
  if (p.credential_mode === "cli" && p.native_models) {
    return String(p.native_cli || "").toLowerCase() === String(kind || "").toLowerCase();
  }
  const ks = p.keys || [];
  if (!ks.length) return !!p.api_key;   // 老数据单 KEY（api_key 镜像）；两者皆无=没配密钥，不推荐
  return ks.some((k) => k.enabled !== false && !k.cooling);
}

function nativeCliMatches(p, kind) {
  if (!p || p.credential_mode !== "cli" || !p.native_models) return true;
  return String(p.native_cli || "").toLowerCase() === String(kind || "").toLowerCase();
}

function nativeCliHint(p) {
  const cli = String((p || {}).native_cli || "").toLowerCase();
  const labels = { opencode: "OpenCode", "gemini-cli": "Gemini CLI", "kimi-code": "Kimi Code", "grok-build": "Grok Build", pi: "Pi", "codex-cli": "Codex CLI", "claude-code": "Claude Code", "mimo-code": "MiMo Code" };
  return t("仅支持 {cli} 原生模型").replace("{cli}", labels[cli] || cli || t("该 CLI"));
}

/* 绑定链里的死条目：厂商已删/停用/协议不再适配/KEY 全冷却，或该模型已被
 * 隐藏停用。这些条目解析时会被跳过，留在链首等于配了个寂寞。 */
function chainDeadReasons(c, chain) {
  const allow = bindAllowedProtocols(c.orch_kind);
  const dead = (chain || []).map((x) => {
    if (!x.p) return ""; // 空 p = CLI 默认凭据，不算死
    const pv = (S.providers || []).find((p) => p.id === x.p);
    if (!pv) return t("供应商已删除");
    if (pv.enabled === false) return t("供应商已停用");
    if (pv.credential_mode === "cli" && pv.native_models)
      return nativeCliMatches(pv, c.orch_kind) ? "" : nativeCliHint(pv);
    if (!provAdaptedProto(pv, allow, c.orch_kind))
      return chatShapedFace(pv, allow)
        ? t("openai 面仅 chat 形态（codex 只讲 responses）")
        : t("协议不匹配");
    const ks = pv.keys || [];
    if (ks.length && !ks.some((k) => k.enabled !== false && !k.cooling))
      return t("密钥全部冷却中");
    const mm = (pv.models || []).find((m) => m.name === x.m);
    if (mm && (mm.hidden || mm.enabled === false)) return t("模型已停用");
    return "";
  });
  return dead;
}

/* 单条显式绑定链的推荐修复动作：需要改返回新链，不动返回 null。
 * 空链代表默认自动调度，不能悄悄写成持久绑定；已有链失效时才推荐替代链。 */
function bindRepairAction(c, st, includeEmpty) {
  const rec = recommendFor(c);
  if (!st.chain.length) return includeEmpty && rec ? [rec] : null;
  const dead = chainDeadReasons(c, st.chain);
  const allDead = dead.every((d) => d);
  const headDead = dead[0] !== ""; // 空 p = CLI 默认凭据，是有意配置不算死
  if (allDead) return rec ? [rec] : null;
  if (headDead && rec && chainKey(st.chain) !== chainKey([rec]))
    return [rec].concat(st.chain.filter((x) => !(x.p === rec.p && x.m === rec.m)));
  return null;
}

function autoBindAll() {
  const targets = (S.catalog || []).filter((c) => c.installed && c.orch_kind);
  let filled = 0, skipped = 0, noProv = 0, refilled = 0;
  for (const c of targets) {
    const st = bindSelById(c.id);
    const act = bindRepairAction(c, st, true);
    if (!act) {
      // 没动它：分清「健康链无需推荐」和「没有可推荐的」两种落空
      if (!st.chain.length) { noProv++; continue; }
      const dead = chainDeadReasons(c, st.chain);
      if (dead.every((d) => d)) noProv++; else skipped++;
      continue;
    }
    const wasEmpty = !st.chain.length;
    st.chain = act;
    st.dirty = true;
    if (wasEmpty) filled++; else refilled++;
  }
  bindRepaint();
  if (filled && refilled) {
    toast(t("已为 %1 个空链 CLI 预填推荐，并修复 %2 条失效链——确认后保存。")
      .replace("%1", filled).replace("%2", refilled));
  } else if (filled) {
    toast(t("已为 %1 个 CLI 预填推荐模型，确认无误后点各卡片「保存」，或点右上「全部保存」。").replace("%1", filled));
  } else if (refilled) {
    toast(t("已为 %1 条失效链重新推荐（原厂商失效/停用/模型停用）——确认后点「全部保存」生效。")
      .replace("%1", refilled));
  } else if (noProv && !skipped) {
    toast(t("没有可推荐的：先到「模型接入」页导入与 CLI 协议匹配的供应商。"), true);
  } else if (skipped && !filled && !refilled) {
    toast(t("所有 CLI 都已配置模型链，无需推荐。"));
  }
}

/* 厂商/模型停用·删除后不再自动改写绑定链（2026-09-22 用户拍板：不要去动
 * 模型调度）——后端在停用/删除时已把死条目从链里剔除（modelhub._prune_binding_chains），
 * 空链回落 CLI 默认；要补推荐用「一键推荐绑定」手动来。 */

async function saveAllBindings() {
  const targets = (S.catalog || []).filter((c) => c.installed && c.orch_kind);
  const dirty = targets.filter((c) => (S.bindSel[c.id] || {}).dirty);
  for (const c of dirty) await saveBinding(c.id);
  if (dirty.length) toast(t("已保存 %1 个 CLI 的绑定。").replace("%1", dirty.length));
}

/* 有未保存草稿时显示「全部保存」按钮（在 poll 重绘里顺带刷新） */
function syncSaveAllBtn() {
  const btn = $("btn-saveall-bind");
  if (!btn) return;
  const anyDirty = Object.values(S.bindSel || {}).some((st) => st.dirty);
  btn.classList.toggle("hidden", !anyDirty);
}

function bindModelBox(c, provId) {
  const st = bindSelById(c.id);
  const allow = bindAllowedProtocols(c.orch_kind);
  const chips = st.chain.length
    ? st.chain.map((c2, i) => {
        const pname = c2.p ? provName(c2.p) : t("CLI 默认凭据");
        const pv = c2.p ? (S.providers || []).find((p) => p.id === c2.p) : null;
        const adapted = provAdaptedProto(pv, allow, c.orch_kind);
        const dead = c2.p && !adapted;
        // auto 供应商按实测 wire 注入是常态，说「自动」；显式协议靠适配才通的
        // 才叫「已适配」——两者含义不同，别混成一句。
        const badge = !c2.p || !adapted ? ""
          : (pv.protocol === "auto"
             ? ' <span class="hint ok">✓ ' + esc(t("自动 · %1 wire").replace("%1", adapted)) + "</span>"
             : (pv.protocol !== adapted
                ? ' <span class="hint ok">✓ ' + esc(t("已适配（%1 wire）").replace("%1", adapted)) + "</span>"
                : ""));
        return '<span class="ochip' + (i === 0 ? " primary" : "") + '">' +
          "<b>" + (i === 0 ? t("主") : t("备")) + "</b>" + esc(pname) + " · " + esc(c2.m) +
          (modelHasImage(c2.p, c2.m)
            ? ' <span class="tag ok" title="' + esc(t("支持图片输入")) + '">' + t("图") + "</span>" : "") +
          (dead ? ' <span class="hint warn">⚠ ' + esc(chatShapedFace(pv, allow)
            ? t("openai 面仅 chat 形态（codex 只讲 responses），解析时跳过")
            : t("协议不匹配，解析时跳过")) + "</span>" : badge) +
          (i > 0 ? '<button class="mini" data-m="' + esc(c2.m) + '" data-p="' + esc(c2.p) +
                  '" title="' + t("设为主模型") + '" onclick="bindPromote(\'' + jsq(c.id) + '\', this)">' +
                  '<svg class="ico" aria-hidden="true"><use href="#i-arrow-up"></use></svg></button>' : "") +
          '<button class="mini" data-m="' + esc(c2.m) + '" data-p="' + esc(c2.p) +
            '" title="' + t("移除") + '" onclick="bindRemove(\'' + jsq(c.id) + '\', this)">×</button>' +
          "</span>";
      }).join("")
    : '<span class="hint">' + t("未设置") + (provId
        ? t("（按供应商/难度自动解析——供应商协议不匹配或被停用时解析为空，相关步骤将判失败）")
        : t("（自动推荐厂商与模型；没有兼容可用供应商时才使用 CLI 自身配置）")) + "</span>";
  return '<div class="field"><label>' + t("运行时模型链（跨厂商，最多 ") + MAX_ORCH_MODELS + t(" 条）") + "</label>" +
    '<div class="orch-row">' + chips +
    '<button class="ghost small" onclick="bindToggle(\'' + jsq(c.id) + '\')">' +
    (st.open ? t("收起") : t("＋ 添加")) + "</button>" +
    (st.dirty ? ' <span class="hint">' + t("有未保存改动") + '</span>' : "") +
    "</div>" +
    (st.chain.length ? '<div class="hint">' + t("链先生效（覆盖「按难度自动选模型」）；主模型瞬态失败自动降级到下一条——可以是另一家厂商。") + '</div>' : "") +
    (st.open ? bindPanel(c) : "") + "</div>";
}

function bindPanel(c) {
  const st = bindSelById(c.id);
  const allow = bindAllowedProtocols(c.orch_kind);
  const all = modelGroups();
  // 原生协议匹配，或适配测试过 allow 里某条 wire 的供应商都可勾选
  const groups = all.filter((g) => provAdaptedProto(g, allow, c.orch_kind));
  const hiddenN = all.length - groups.length;
  if (!groups.length) {
    return '<div class="ohint">' + esc(all.length
      ? t("该 CLI 只接受特定 wire 协议的供应商，当前没有匹配项——先到「模型接入」页导入对应协议的网关。")
      : t("还没有可用模型——先到「模型接入」页导入供应商并获取模型列表。")) + "</div>";
  }
  return '<div class="opanel">' +
    '<div class="ohint">' + t("勾选该 CLI 编排运行时的模型（可跨供应商混选）：第 1 条是主模型，其余按顺序作降级备选，每条自带该供应商的凭据注入。") +
    (hiddenN ? "<br>" + esc(t("%1 个供应商 wire 协议不匹配已隐藏（降级只在同协议网关间进行）。").replace("%1", hiddenN)) : "") +
    "</div>" +
    groups.map((g) =>
      '<div class="ogroup"><div class="ogname">' + esc(g.name) +
      ' <span class="tag">' + (g.protocol === "auto"
        ? t("自动 · 注入该厂商凭据")
        : (provAdaptedProto(g, allow, c.orch_kind) === g.protocol
           ? t("注入该厂商凭据") : t("已适配 · 注入该厂商凭据"))) + '</span></div>' +
      g.models.map((m) => {
        // 本供应商注入本 CLI 实际走的 wire（与后端 _entry_endpoint 同规则）；
        // 无命中 = 勾了也会被解析层整条跳过，标死防止白配。
        // 无可用密钥同理：勾了也是死条目（解析层「无可用密钥」跳过）
        const wire = provAdaptedProto(g, allow, c.orch_kind);
        const nativeOk = g.credential_mode === "cli" && g.native_models &&
          String(g.native_cli || "").toLowerCase() === String(c.orch_kind || "").toLowerCase();
        const nativeWrong = g.credential_mode === "cli" && g.native_models && !nativeOk;
        const dead = nativeWrong || !wire || (g.keyOk === false && !nativeOk);
        const has = st.chain.some((x) => x.p === g.id && x.m === m);
        return '<label class="oitem' + (dead ? " dim" : "") + '"><input type="checkbox" value="' + esc(m) + '" data-p="' + esc(g.id) + '"' +
          (has ? " checked" : "") + (dead ? " disabled" : "") +
          " onchange=\"bindPick('" + esc(c.id) + "', this, this.checked)\">" + esc(m) +
          (modelHasImage(g.id, m)
            ? ' <span class="tag ok" title="' + esc(t("支持图片输入")) + '">' + t("图") + "</span>" : "") +
          (dead ? ' <span class="hint warn">' + esc(nativeWrong
            ? nativeCliHint(g)
            : (!wire
            ? t("无可用 wire，解析时跳过")
            : t("无可用密钥，解析时跳过"))) + "</span>" : "") +
          "</label>";
      }).join("") +
      "</div>").join("") + "</div>";
}

function bindToggle(id) {
  const st = bindSelById(id);
  st.open = !st.open;
  bindRepaint();
}

function bindPick(id, el, on) {
  const st = bindSelById(id), model = el.value, pid = el.dataset.p || "";
  const i = st.chain.findIndex((x) => x.p === pid && x.m === model);
  if (on && i < 0) {
    if (st.chain.length >= MAX_ORCH_MODELS) {
      toast(t("最多选 ") + MAX_ORCH_MODELS + t(" 条（1 个主模型 + ") +
            (MAX_ORCH_MODELS - 1) + t(" 个降级备选）。"), true);
      bindRepaint();
      return;
    }
    st.chain.push({ p: pid, m: model });
  } else if (!on && i >= 0) {
    st.chain.splice(i, 1);
  }
  st.dirty = true;
  bindRepaint();
}

function bindRemove(id, el) {
  const st = bindSelById(id), m = el.dataset.m, p = el.dataset.p || "";
  st.chain = st.chain.filter((x) => !(x.p === p && x.m === m));
  st.dirty = true;
  bindRepaint();
}

function bindPromote(id, el) {
  const st = bindSelById(id), m = el.dataset.m, p = el.dataset.p || "";
  const hit = st.chain.find((x) => x.p === p && x.m === m);
  if (hit) st.chain = [hit].concat(st.chain.filter((x) => x !== hit));
  st.dirty = true;
  bindRepaint();
}

/* ---------------------------------------------------------- 智能体管理 */
function renderCatalog() {
  const cat = S.catalog || [];
  // 数据没变化就不重绘，避免轮询打断正在编辑的下拉/输入。
  const sig = JSON.stringify([cat, S.mgmt || {}, S.catalogChecking]);
  if (sig === S.catSig) return;
  S.catSig = sig;
  const groups = { installed: [], installable: [] };
  for (const c of cat) (groups[c.group] || groups.installable).push(c);
  $("ag-installed").innerHTML = groups.installed.map(card).join("");
  $("ag-installable").innerHTML = groups.installable.map(card).join("");
  // 日志流式刷新后定位到最新一行（除非用户主动往上翻看历史）
  document.querySelectorAll("pre.mgmt-log").forEach((el) => {
    if (el.scrollHeight - el.scrollTop - el.clientHeight < 40) el.scrollTop = el.scrollHeight;
  });
}

/* 该条目有管理操作在跑（queued/running）时，写操作按钮置灰防重复触发；
   页面刷新后按钮恢复，后端同条目去重闸仍然兜底 */
function mgmtBusy(id) {
  const st = (S.mgmt || {})[id];
  return !!st && (st.status === "queued" || st.status === "running");
}

function card(c) {
  const orchBox = c.orch_kind
    ? '<label class="toggle"><input type="checkbox" ' + (c.orch_enabled ? "checked" : "") +
      ' onchange="toggleOrch(\'' + jsq(c.id) + '\', this.checked)">' + t(" 参与编排") + '</label>'
    : '<span class="tag">' + t("仅管理") + '</span>';
  const capability = c.capabilities || {};
  const capTags = [capability.transport, capability.resume ? t("支持续会话") : "",
    capability.mcp ? "MCP" : "", capability.sandbox].filter(Boolean)
    .map((x) => '<span class="tag">' + esc(t(x)) + '</span>').join("");
  const dis = mgmtBusy(c.id) ? " disabled" : "";
  const hasModels = modelGroups().length > 0;
  const modelBox = c.config_writable
    ? (hasModels
        ? '<div class="field"><label>' + t("默认模型（写入配置文件）") + '</label><div class="input-row">' +
          modelSelectHtml(c.id, c.model, c.orch_kind || c.id) +
          '<button class="ghost small" onclick="saveModel(\'' + jsq(c.id) + '\')">' + t("保存") + '</button></div></div>'
        : '<div class="field"><label>' + t("默认模型（写入配置文件）") + '</label>' +
          '<div class="hint warn">' + t("还没有可选模型：先到「模型接入」页导入供应商并获取模型列表。") + '</div></div>')
    : (c.model ? '<div class="facts">' + t("模型：") + '<b>' + esc(fmtModel(c.model)) + "</b></div>" : "");
  const ops = [
    // 一键打开（web 类开浏览器 / console 类新终端跑 TUI）：已安装且配了 launch 才出
    c.installed && c.launch ? '<button class="primary small" onclick="openAgent(\'' + jsq(c.id) + '\')">' +
      (c.launch.kind === "web" ? t("打开网页") : t("打开")) + "</button>" : "",
    c.installed && c.orch_kind ? '<button class="ghost small"' + dis + ' onclick="mgmt(\'' + jsq(c.id) + '\', \'smoke\')">' + t("冒烟测试") + '</button>' : "",
    c.installed && c.has_upgrade ? '<button class="ghost small"' + dis + ' onclick="mgmt(\'' + jsq(c.id) + '\', \'upgrade\')">' + t("升级") + '</button>' : "",
    c.installed && c.has_upgrade ? '<button class="ghost small" onclick="checkUpdate(\'' + jsq(c.id) + '\')">' + t("检查更新") + '</button>' : "",
    !c.installed && c.has_install ? '<button class="ghost small"' + dis + ' onclick="mgmt(\'' + jsq(c.id) + '\', \'install\')">' + t("安装") + '</button>' : "",
    c.installed ? '<button class="ghost small" onclick="showMgmtLog(\'' + jsq(c.id) + '\')">' + t("日志") + '</button>' : "",
    !c.installed && !c.has_install ? '<span class="hint">' + t("安装命令待配置（编辑 data/catalog.json）") + '</span>' : "",
  ].join("");
  return '<div class="card">' +
    '<div class="head"><span class="name">' + esc(c.name) + "</span>" +
    (c.installed ? statusChip("done") : '<span class="tag">' + t("未安装") + '</span>') + updateChip(c) +
    // 卸载放卡片右上角（与状态徽标同行），不再吊在操作行尾部
    (c.installed && c.uninstall_cmd ? '<button class="danger small"' + dis + ' onclick="mgmt(\'' + jsq(c.id) + '\', \'uninstall\')">' + t("卸载") + '</button>' : "") +
    "</div>" +
    '<div class="note">' + esc(t(c.note || "")) + "</div>" +
    (capTags ? '<div class="facts capability-tags">' + capTags + '</div>' : "") +
    '<div class="facts">' + t("版本 ") + '<b>' + esc(c.version || "-") + "</b>" + t("　模型 ") + "<b>" + esc(fmtModel(c.model) || "-") + "</b>" +
    ((c.detail || c.config_path) ? "<br>" + esc(c.detail || c.config_path) : "") + "</div>" +
    mgmtPanel(c.id) +
    '<div class="ops">' + orchBox + ops + "</div>" + modelBox + "</div>";
}

/* 管理操作（升级/安装/卸载/冒烟）的就地反馈面板：状态 + 版本对比 + 流式日志 */
function mgmtPanel(agentId) {
  const st = (S.mgmt || {})[agentId];
  if (!st) return "";
  const running = st.status === "queued" || st.status === "running";
  const chip = statusChip(st.status || "queued");
  // 占位符「-」彼此也相等：版本里没有数字就不配宣称「已是最新」（2026-10-22 minimax 假完成实案）
  const vcmp = (st.versionBefore || st.versionAfter)
    ? '<span class="hint">' + t("版本 ") + esc(st.versionBefore || "?") + " → <b>" +
      esc(st.versionAfter || "…") + "</b>" +
      (st.status === "done" && /\d/.test(st.versionBefore || "") &&
       st.versionAfter === st.versionBefore
        ? t("（已是最新版本，无需升级）") : "") + "</span>"
    : "";
  // 运行且暂无输出时给"等待中"提示（npm 下载阶段本来就有一段静默期）
  const empty = running ? t("（等待输出…安装/下载阶段可能有一段静默期）") : t("（无输出）");
  const logBox = st.showLog
    ? '<pre class="mgmt-log' + (st.log ? "" : " muted") + '">' +
      esc(st.log || empty) + "</pre>" : "";
  return '<div class="mgmt-panel ' + esc(st.status || "queued") + '">' +
    '<div class="mgmt-head">' + (running ? '<span class="live-dot"></span>' : "") + chip +
    '<span class="mgmt-title">' + esc(st.opLabel || "") + "</span>" + vcmp +
    '<span class="mgmt-ops">' +
    '<button class="ghost small" onclick="toggleMgmtLog(\'' + jsq(agentId) + '\')">' +
    (st.showLog ? t("收起日志") : t("查看日志")) + "</button>" +
    (st.runId ? '<button class="ghost small" onclick="openRunInRuns(\'' + jsq(st.runId) + '\')">' + t("完整运行") + '</button>' : "") +
    '<button class="ghost small" onclick="clearMgmt(\'' + jsq(agentId) + '\')">×</button>' +
    "</span></div>" +
    (st.summary ? '<div class="hint">' + esc(String(st.summary).slice(0, 300)) + "</div>" : "") +
    logBox + "</div>";
}

async function toggleOrch(id, enabled) {
  await api("/api/orchestration", { method: "POST", body: JSON.stringify({ agent_id: id, enabled }) });
  poll();
}

async function saveModel(id) {
  const v = $("model-" + id).value.trim();
  if (!v) { toast(t("请先在下拉里选择一个模型（要清除配置请手动编辑配置文件）。"), true); return; }
  try {
    const r = await api("/api/catalog/" + encodeURIComponent(id) + "/model", { method: "POST", body: JSON.stringify({ model: v }) });
    toast(t("已写入：") + (r.model || v));
  } catch (e) { toast(t("失败：") + e.message, true); }
  poll();
}

/* 一键绑定推荐模型（智能体目录页）：给「默认模型」还空着的已安装智能体按
 * 协议适配规则（复用绑定页 recommendFor 评分）挑一家厂商的启用模型并直接
 * 写入该 CLI 自身配置（写入侧先自动 .bak 备份）。已配置的不动——目录页的
 * 默认模型会写进 CLI 全局配置，手工设置过的值（含 CLI 订阅自带的默认）不
 * 该被一键覆盖；要换模型逐卡下拉改就行。 */
async function catAutoBindAll() {
  const targets = (S.catalog || []).filter((c) => c.installed && c.config_writable);
  if (!targets.length) { toast(t("没有支持写入默认模型的已安装智能体。"), true); return; }
  const empty = targets.filter((c) => !fmtModel(c.model));
  if (!empty.length) { toast(t("所有已安装智能体都已配置默认模型，无需绑定。")); return; }
  let done = 0, failed = 0, noProv = 0, firstErr = "";
  for (const c of empty) {
    const rec = recommendFor(c);
    if (!rec) { noProv++; continue; }
    try {
      const r = await api("/api/catalog/" + encodeURIComponent(c.id) + "/model",
        { method: "POST", body: JSON.stringify({ model: rec.m }) });
      c.model = r.model || rec.m;
      done++;
    } catch (e) {
      failed++;
      if (!firstErr) firstErr = c.name + t("：") + e.message;
    }
  }
  S.catSig = null;
  renderCatalog();
  if (done && failed) {
    toast(t("已为 %1 个智能体写入推荐模型，%2 个失败。").replace("%1", done).replace("%2", failed) +
      (firstErr ? " " + firstErr : ""), true);
  } else if (done) {
    toast(t("已为 %1 个智能体写入推荐模型（原配置已自动备份 .bak）。").replace("%1", done));
  } else if (failed) {
    toast(t("推荐模型写入失败：") + firstErr, true);
  } else {
    toast(t("没有可推荐的：先到「模型接入」页导入与 CLI 协议匹配的供应商。"), true);
  }
  poll();
}

/* 一键升级全部（智能体目录页）：把所有「已安装且配了升级命令」的条目批量
 * 送进 mgmt 队列，服务端跳过「已是最新的」；每条复用单条升级的就地面板跟踪。
 * 批量起跑的日志默认收起（要看点「查看日志」），防止十几张卡同时摊开刷屏。 */
async function catUpgradeAll() {
  const btn = $("btn-catalog-upgrade-all");
  if (btn) btn.disabled = true;
  try {
    const r = await api("/api/catalog/upgrade-all", { method: "POST" });
    S.mgmt = S.mgmt || {};
    for (const s of (r.started || [])) {
      const before = ((S.catalog || []).find((x) => x.id === s.id) || {}).version;
      S.mgmt[s.id] = { opLabel: t("升级"), status: "queued", versionBefore: before,
                       log: "", showLog: false };
      pollMgmt(s.id, s.run_id);
    }
    S.catSig = null; renderCatalog();
    const n = (r.started || []).length, skip = (r.busy || []).length, bad = (r.failed || []).length;
    let msg;
    if (n) {
      msg = t("已开始升级 %1 个智能体").replace("%1", n);
      if (skip) msg += t("，%1 个忙于其他管理操作未动").replace("%1", skip);
      if (bad) msg += t("，%1 个任务创建失败").replace("%1", bad);
    } else if (skip) {
      msg = t("没有新的升级任务：%1 个条目正忙于其他管理操作。").replace("%1", skip);
    } else if (bad) {
      msg = t("升级任务创建失败：") + (r.failed || []).join("、");
    } else {
      msg = t("没有需要升级的智能体（都已最新，或未安装/未配置升级命令）。");
    }
    toast(msg, !n);
  } catch (e) {
    toast(t("失败：") + e.message, true);
  } finally {
    if (btn) btn.disabled = false;
  }
  poll();
}

/* 一键打开：web 类后台起服务并自动开浏览器；console 类新开终端窗口跑交互 TUI。
   用的模型就是目录页「默认模型」已写入该 CLI 配置文件的那份；密钥由服务端按编排同款规则注入 */
async function openAgent(id) {
  try {
    const r = await api("/api/catalog/" + encodeURIComponent(id) + "/launch", { method: "POST", body: "{}" });
    toast(r.message || t("已发出打开指令"));
  } catch (e) { toast(t("失败：") + e.message, true); }
}

async function mgmt(id, op) {
  const names = { install: t("安装"), upgrade: t("升级"), uninstall: t("卸载"), smoke: t("冒烟测试") };
  const entry = (S.catalog || []).find((x) => x.id === id) || {};
  if (op === "install" && !await uiConfirm(t("确定执行安装？命令来自 data/catalog.json，可在管理页查看。"), { ok: t("安装") })) return;
  if (op === "uninstall") {
    // 卸载不可逆：把将要执行的真实命令摊开给用户确认
    const cmd = entry.uninstall_cmd || t("（未能推导，请先在 catalog 配置 uninstall）");
    if (!await uiConfirm(t("确定卸载 ") + entry.name + t("？\n\n将执行：\n") + cmd +
                 t("\n\n该 CLI 会从本机移除（配置文件保留）。此操作不可撤销。"), { ok: t("卸载"), danger: true })) return;
  }
  const before = ((S.catalog || []).find((x) => x.id === id) || {}).version;
  S.mgmt = S.mgmt || {};
  // 安装/升级/卸载默认展开日志：输出就是用户要看的进度（流式实时刷新）
  S.mgmt[id] = { opLabel: names[op] || op, status: "queued", versionBefore: before,
                 log: "", showLog: op !== "smoke" };
  S.catSig = null;
  renderCatalog();
  let r;
  try {
    r = await api("/api/catalog/" + encodeURIComponent(id) + "/" + op, { method: "POST" });
  } catch (e) {
    S.mgmt[id].status = "failed";
    S.mgmt[id].summary = e.message;
    S.catSig = null; renderCatalog();
    return;
  }
  S.mgmt[id].runId = r.run_id;
  if (r.deduped) toast(t("该条目已有进行中的任务，已转为跟踪该任务"));
  S.catSig = null; renderCatalog();
  pollMgmt(id, r.run_id);   // 就地跟踪，不再跳转页面
}

/* 跟踪一次管理操作：更新状态、完成后拉日志并对比版本 */
async function pollMgmt(agentId, runId) {
  const st = S.mgmt[agentId];
  if (!st) return;
  try {
    const r = await api("/api/runs/" + encodeURIComponent(runId));
    const run = r.run;
    if (!run) return;
    st.status = run.status;
    st.summary = run.summary || run.error || "";
    st.retries = 0;
    // 运行中也持续拉日志：输出是流式写入的，边跑边看才有意义
    if (st.showLog || run.status === "failed") {
      try { st.log = await fetchRunLog(runId); } catch (e) { /* 网络抖动时保留上一份日志 */ }
    }
    if (run.status === "queued" || run.status === "running") {
      S.catSig = null; renderCatalog();
      setTimeout(() => pollMgmt(agentId, runId), 2000);
      return;
    }
    // 结束：重新拉 catalog 拿最新版本，做前后对比
    const cat = await api("/api/catalog");
    S.catalog = cat.catalog;
    const now = (cat.catalog || []).find((x) => x.id === agentId) || {};
    st.versionAfter = now.version;
    if (!st.showLog) {
      try { st.log = await fetchRunLog(runId); } catch (e) { /* 保留上一次日志 */ }
    }
    S.catSig = null; renderCatalog();
    if (S.tab === "agents") poll();
  } catch (e) {
    // 升级/安装期间服务重启或网络抖动会让 fetch 直接失败（Failed to fetch）。
    // 只要运行还没结束就继续重试，否则面板会永久停在错误上。
    st.retries = (st.retries || 0) + 1;
    const pending = !st.status || st.status === "queued" || st.status === "running";
    if (pending && st.retries <= 15) {
      st.summary = t("连接中断，正在重试（") + e.message + t("）");
      S.catSig = null; renderCatalog();
      setTimeout(() => pollMgmt(agentId, runId), 3000);
      return;
    }
    st.summary = e.message;
    S.catSig = null; renderCatalog();
  }
}

/* 取一次运行最后一个步骤的输出日志；失败时抛出，由调用方决定如何提示 */
async function fetchRunLog(runId) {
  const r = await api("/api/runs/" + encodeURIComponent(runId));
  const steps = (r.run && r.run.steps) || [];
  if (!steps.length) return t("（尚无输出）");
  const last = steps[steps.length - 1];
  const res = await api("/api/runs/" + encodeURIComponent(runId) +
                        "/log?step=" + encodeURIComponent(last.log || "") + "&pretty=1");
  return res.log || t("（无输出）");
}

async function toggleMgmtLog(agentId) {
  const st = S.mgmt[agentId];
  if (!st) return;
  st.showLog = !st.showLog;
  if (st.showLog && st.runId) {
    try { st.log = await fetchRunLog(st.runId); }
    catch (e) { st.log = t("日志读取失败：") + e.message; }
  }
  S.catSig = null; renderCatalog();
}

function clearMgmt(agentId) {
  if (S.mgmt) delete S.mgmt[agentId];
  S.catSig = null; renderCatalog();
}

/* 「日志」按钮：查看该智能体最近一次管理操作的输出 */
async function showMgmtLog(agentId) {
  const st = (S.mgmt || {})[agentId];
  if (st && st.runId) return toggleMgmtLog(agentId);
  // 没有本次会话记录时，从运行历史里找该智能体最近一次管理运行
  try {
    const r = await api("/api/runs");
    const run = (r.runs || []).find((x) => x.kind === "mgmt" && x.entry_id === agentId);
    if (!run) { toast(t("还没有该智能体的管理操作记录（先点升级/安装/冒烟测试）。"), true); return; }
    S.mgmt = S.mgmt || {};
    S.mgmt[agentId] = { opLabel: run.title, status: run.status, runId: run.id,
                        summary: run.summary || run.error || "",
                        log: await fetchRunLog(run.id), showLog: true };
    S.catSig = null; renderCatalog();
  } catch (e) { toast(t("读取失败：") + e.message, true); }
}

/* 「检查更新」：查询远端最新版本，明确告知是否已是最新（避免"升级没反应"的误解） */
async function checkUpdate(agentId) {
  S.mgmt = S.mgmt || {};
  const prev = S.mgmt[agentId] || {};
  S.mgmt[agentId] = Object.assign({}, prev, {
    opLabel: t("检查更新"), status: "running", summary: t("正在查询远端最新版本…"),
    showLog: prev.showLog, runId: prev.runId, versionBefore: prev.versionBefore,
  });
  S.catSig = null; renderCatalog();
  try {
    const r = await api("/api/catalog/" + encodeURIComponent(agentId) + "/check-update",
                        { method: "POST" });
    const up = r.updatable;
    let msg;
    if (up === true) {
      msg = t("发现新版本：") + (r.current || "?") + " → " + (r.latest || "?") + t("，可点「升级」更新。");
    } else if (up === false) {
      msg = t("已是最新版本（") + (r.latest || r.current || "?") + t("），无需升级。");
    } else {
      msg = r.note || t("无法判断是否有更新。");
    }
    S.mgmt[agentId] = Object.assign({}, S.mgmt[agentId], {
      status: up === true ? "done" : (up === false ? "done" : "failed"),
      summary: msg, log: t("当前版本：") + (r.current || "?") +
        t("\n最新版本：") + (r.latest || t("(未知)")) +
        t("\n可更新：") + (up === true ? t("是") : up === false ? t("否") : t("未知")) +
        (r.note ? t("\n说明：") + r.note : ""),
      showLog: true, versionAfter: r.latest || undefined,
    });
  } catch (e) {
    S.mgmt[agentId] = Object.assign({}, S.mgmt[agentId],
      { status: "failed", summary: t("检查失败：") + e.message });
  }
  S.catSig = null; renderCatalog();
}

/* ---------------------------------------------------------- 自定义流程管理 */
function openFlowsManager() {
  const flows = S.flows || [];
  const rows = flows.map((f) =>
    '<div class="item"><div class="t"><span class="name">' + flowIconHtml(f) + " " + esc(t(f.name)) +
    '</span><span class="tag">' + esc(f.id) + "</span>" +
    '<span class="tag">' + (f.engine === "code" ? t("代码引擎")
      : f.engine === "direct" ? t("直连引擎") : t("评审引擎")) + "</span>" +
    (f.serial ? '<span class="tag">' + t("连载 ") + f.serial.chapters + t(" 章") + "</span>" : "") +
    (f.builtin ? '<span class="tag ok">' + t("预置") + '</span>' : '<span class="tag">' + t("自定义") + '</span>') +
    (f.edited ? '<span class="tag">' + t("已改") + '</span>' : "") +
    '<button class="ghost small" onclick="flowForm(\'' + jsq(f.id) + '\')">' + t("编辑") + '</button>' +
    '<button class="ghost small" onclick="flowExport(\'' + jsq(f.id) + '\')">' + t("导出") + '</button>' +
    '<button class="ghost small" onclick="flowHistory(\'' + jsq(f.id) + '\')">' + t("历史") + '</button>' +
    (f.builtin
      ? (f.edited ? '<button class="ghost small" onclick="flowReset(\'' + jsq(f.id) + '\')">' + t("恢复默认") + '</button>' : "")
      : '<button class="danger small" onclick="deleteFlow(\'' + jsq(f.id) + '\')">' + t("删除") + '</button>') +
    '</div><div class="desc">' + esc(t(f.note || "")) +
    (f.rubric ? t("　维度：") + esc(f.rubric.map((d) => t(d)).join(" / ")) : "") +
    (f.threshold ? t("　阈值：") + f.threshold : "") +
    (f.serial ? t("　每章 ") + f.serial.words_per_chapter + t(" 字") : "") + "</div></div>").join("");
  const body = '<p class="hint">' + t("预置流程可直接编辑（阈值/轮数/维度/章节数/提示词），改动随时可「恢复默认」；") +
    t("自定义流程只需填名称与引擎，其余留空走默认。") + '</p>' +
    '<div class="list">' + rows + "</div>" +
    '<div class="input-row" style="margin-top:10px">' +
    '<button class="primary" onclick="flowForm()">' + t("＋ 新建自定义流程") + '</button>' +
    '<button class="ghost" onclick="flowImport()">' + t("导入分享码") + '</button></div>';
  openModal(t("🧩 任务类型管理"), body, "");
}

/* 流程分享码：导出 = 拿码 + 尝试复制到剪贴板；导入 = 粘贴码 + 覆盖确认 */
async function flowExport(fid) {
  let r;
  try { r = await api("/api/flows/export", { method: "POST", body: JSON.stringify({ id: fid }) }); }
  catch (e) { toast(t("导出失败：") + e.message, true); return; }
  const body = '<p class="hint">' +
    t("把这段分享码发给任何人，对方在「任务类型管理 → 导入分享码」粘贴即可一键安装：") + '</p>' +
    '<textarea id="fl-share-code" rows="6" readonly style="width:100%;font-family:var(--mono,monospace);font-size:12px;word-break:break-all">' +
    esc(r.code) + "</textarea>";
  openModal(t("📤 导出流程：") + (r.name || fid), body, "");
  const ta = $("fl-share-code");
  if (ta) { ta.focus(); ta.select(); }
  try { await navigator.clipboard.writeText(r.code); toast(t("分享码已复制到剪贴板")); } catch (e) { /* 无剪贴板权限时保持手选 */ }
}

/* 版本历史（Langfuse prompt management 借鉴）：当前版 + 历史版清单，每版带
 * 实测战绩；恢复前弹确认——被顶下来的当前版会进历史，错了还能翻回来。 */
const FLOW_SOURCE_TXT = { manual: t("手动修改"), import: t("分享码导入"), restore: t("恢复顶下") };

async function flowHistory(fid) {
  let versions;
  try { versions = (await api("/api/flows/versions?id=" + encodeURIComponent(fid))).versions || []; }
  catch (e) { toast(t("历史读取失败：") + e.message, true); return; }
  const statTxt = (st) => !st ? "" :
    '<span class="tag">' + t("任务 ") + st.runs +
    (st.pass_rate != null ? t("　通过 ") + Math.round(st.pass_rate * 100) + "%" : "") +
    (st.avg_overall != null ? t("　均分 ") + st.avg_overall : "") + "</span>";
  const rows = versions.map((v) => {
    const src = v.current ? '<span class="tag ok">' + t("当前") + "</span>"
      : '<span class="tag">' + t(FLOW_SOURCE_TXT[v.source] || v.source) + " " + esc(v.ts) + "</span>";
    const btn = v.current ? "" :
      '<button class="ghost small" onclick="flowRestore(\'' + jsq(fid) + "', '" + jsq(v.ts) + '\')">' + t("恢复") + "</button>";
    return '<div class="item"><div class="t"><span class="name">' + esc(v.name || fid) +
      "</span>" + src + '<span class="tag">' + esc(v.digest) + "</span>" + statTxt(v.stats) + btn +
      "</div></div>";
  }).join("");
  openModal(t("🕘 流程版本历史：") + fid,
    '<p class="hint">' +
    t("每次保存/导入覆盖前的版本自动留档（每流程最多 10 份）。战绩按任务钉住的流程指纹对账——改提示词前先看看现在这版跑得怎么样。") + "</p>" +
    '<div class="list">' + (rows || '<div class="hint">' + t("还没有历史版本。") + "</div>") + "</div>", "");
}

async function flowRestore(fid, ts) {
  if (!await uiConfirm(t("把该流程恢复到 ") + ts + t(" 的版本？当前版本会先存进历史，随时可再翻回。"), { ok: t("恢复") })) return;
  try { await api("/api/flows/restore", { method: "POST", body: JSON.stringify({ id: fid, ts }) }); }
  catch (e) { toast(t("恢复失败：") + e.message, true); return; }
  invalidateFlowRubricDraft(fid);
  await loadFlows();
  openFlowsManager();
  toast(t("已恢复历史版本"));
}

function flowImport() {
  const body = '<p class="hint">' +
    t("粘贴他人分享的流程码，先解析预览再确认导入。") + '</p>' +
    '<textarea id="fl-import-code" rows="6" placeholder="CBFLOW1.…" style="width:100%;font-family:var(--mono,monospace);font-size:12px;word-break:break-all"></textarea>' +
    '<div id="fl-import-view"></div>';
  openModal(t("📥 导入流程分享码"), body,
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>' +
    '<button class="primary" id="fl-import-btn" onclick="flowImportPreview()">' + t("解析预览") + '</button>');
}

async function flowImportPreview() {
  const code = ($("fl-import-code") || {}).value || "";
  const view = $("fl-import-view"), btn = $("fl-import-btn");
  if (!code.trim()) { toast(t("请先粘贴分享码"), true); return; }
  let p;
  try { p = await api("/api/flows/preview", { method: "POST", body: JSON.stringify({ code }) }); }
  catch (e) { toast(t("解析失败：") + e.message, true); return; }
  if (!view) return;
  const conflict = p.exists
    ? (p.builtin
        ? t("⚠ 将覆盖预置流程「") + esc(p.existing_name) + t("」的自定义改动（可恢复默认回滚）")
        : t("⚠ 将覆盖现有自定义流程「") + esc(p.existing_name) + t("」"))
    : t("✓ 新流程，直接创建");
  view.innerHTML = '<div class="item"><div class="t"><span class="name">' + esc(p.name || p.id) +
    "</span>" + '<span class="tag">' + esc(p.id) + "</span>" +
    '<span class="tag">' + esc(t(p.engine === "code" ? "代码引擎"
      : p.engine === "direct" ? "直连引擎" : t("评审引擎"))) + "</span>" +
    (p.serial ? '<span class="tag">' + t("连载") + "</span>" : "") +
    (p.has_prompts ? '<span class="tag ok">' + t("含自定义提示词") + "</span>" : "") + "</div>" +
    '<div class="desc">' + (p.rubric || []).map((d) => esc(t(d))).join(" / ") +
    (p.threshold != null ? t("　阈值：") + p.threshold : "") +
    (p.rounds != null ? t("　轮数：") + p.rounds : "") + "</div>" +
    '<div class="desc">' + conflict + "</div></div>";
  btn.textContent = t("确认导入");
  btn.onclick = flowImportDo;
  S._importCode = code;
}

async function flowImportDo() {
  const code = S._importCode || (($("fl-import-code") || {}).value || "");
  if (!code.trim()) { toast(t("请先粘贴分享码"), true); return; }
  let r;
  try { r = await api("/api/flows/import", { method: "POST", body: JSON.stringify({ code }) }); }
  catch (e) { toast(t("导入失败：") + e.message, true); return; }
  closeModal();
  invalidateFlowRubricDraft(r.id);
  await loadFlows();
  openFlowsManager();
  const how = r.status === "noop" ? t("（与现有内容一致）")
    : r.status === "updated" ? t("（已覆盖现有定义）") : "";
  toast(t("已导入流程「") + (r.name || r.id) + "」" + how);
}

async function flowReset(fid) {
  if (!await uiConfirm(t("把「") + fid + t("」恢复为内置默认配置？"), { ok: t("恢复") })) return;
  try { await api("/api/flows/" + encodeURIComponent(fid) + "/reset", { method: "POST" }); }
  catch (e) { toast(t("恢复失败：") + e.message, true); return; }
  invalidateFlowRubricDraft(fid);
  await loadFlows();
  openFlowsManager();
  toast(t("已恢复默认"));
}

