/* 技能草稿（B7，dsh「让 Agent 创建插件·保留草稿」借鉴）：Agent 在对话中经
 * save_skill_draft 沉淀到 drafts/，默认不生效；此处审核启用（promote 后走
 * 与用户自建包完全相同的注入/安检链）或丢弃。 */
async function loadSkillDrafts() {
  try {
    const data = await api("/api/skillpacks/drafts", { method: "POST", body: JSON.stringify({ action: "list" }) });
    S.skillDrafts = Array.isArray(data && data.drafts) ? data.drafts : [];
  } catch (e) { S.skillDrafts = []; }
  renderSkillDrafts();
}

function renderSkillDrafts() {
  const box = $("skill-drafts");
  if (!box) return;
  const drafts = S.skillDrafts || [];
  box.innerHTML = drafts.map((d) =>
    '<div class="card"><div class="head">' +
    '<span class="name">📝 ' + esc(d.name) + "</span>" +
    '<span class="tag">' + esc((d.scopes || []).join(" / ") || t("全部流程")) + "</span>" +
    '<span class="tag">' + t("草稿") + "</span></div>" +
    (d.note ? '<div class="note">' + esc(d.note) + "</div>" : "") +
    '<div class="facts">' + t("正文 ") + "<b>" + (d.chars || 0) + "</b>" + t(" 字 · 更新于 ") + esc(d.updated_at || "") + "</div>" +
    '<div class="ops">' +
    '<button class="ghost small" onclick="skillDraftOp(\'' + jsq(d.file) + '\', \'promote\')">' + t("审阅通过，启用") + "</button>" +
    '<button class="danger small" onclick="skillDraftOp(\'' + jsq(d.file) + '\', \'discard\')">' + t("丢弃") + "</button>" +
    "</div></div>").join("")
    || '<div class="empty">' + t("暂无草稿——在对话里让智能体「把这条方法论存成技能」即可在此出现。") + "</div>";
}

async function skillDraftOp(file, action) {
  if (action === "discard" && !await uiConfirm(t("丢弃这份技能草稿？"), { ok: t("丢弃"), danger: true })) return;
  if (action === "promote" && !await uiConfirm(t("启用后该草稿将成为经验包，按适用流程自动注入后续任务。确认审阅通过？"), { ok: t("启用") })) return;
  try {
    const data = await api("/api/skillpacks/drafts", { method: "POST", body: JSON.stringify({ action, file }) });
    toast(action === "promote" ? t("已启用经验包：") + esc(data.enabled || "") : t("已丢弃草稿"));
  } catch (e) { toast(e.message, true); return; }
  loadSkills();   // 级联刷新草稿区 + 经验包区（promote 后包立即出现在上方列表）
}

function renderSkills() {
  const box = $("skill-packs");
  if (!box || !S.skills) return;
  const packs = (S.skills.packs || []).filter((p) => !p.agent), lessons = S.skills.lessons || [];
  box.innerHTML = packs.map((p) => {
    const card = p.card;
    const cardHtml = card
      ? '<div class="facts" style="margin-top:4px">' +
        '<span class="tag" title="' + esc(t("来源：") + (card.source && card.source.market || "-")) + '">' +
        t("来源 ") + esc((card.source && card.source.market) || "-") + "</span>" +
        (card.digest ? '<span class="tag" title="' + t("内容指纹（重装突变对账用）") + '">' +
          t("指纹 ") + esc(card.digest) + "</span>" : "") +
        (card.scan ? (card.scan.indexOf("高风险") >= 0
          ? '<span class="tag" style="color:var(--err,#d33)">' + esc(card.scan.split("：")[0]) + "</span>"
          : '<span class="tag">' + esc(card.scan.split("：")[0]) + "</span>") : "") +
        "</div>" +
        (card.declares ? '<div class="note" style="margin-top:2px">📝 ' + t("自述：") +
          esc(card.declares.slice(0, 120)) + (card.declares.length > 120 ? "…" : "") + "</div>" : "")
      : "";
    return '<div class="card"><div class="head"><span class="name">📚 ' + esc(t(p.name)) + "</span>" +
      '<span class="tag">' + esc((p.scopes || []).map((s) => t(s)).join(" / ")) + "</span>" +
      (p.enabled ? '<span class="tag ok">' + t("启用中") + "</span>" : '<span class="tag">' + t("已停用") + "</span>") + "</div>" +
      '<div class="note">' + esc(t(p.note || "")) + "</div>" +
      '<div class="facts">' + t("正文 ") + "<b>" + p.chars + "</b>" + t(" 字（自动注入该类任务的规划与评审提示词）") + "</div>" +
      cardHtml +
      '<div class="ops"><button class="ghost small" onclick="skillPackOp(\'' + jsq(p.id) + '\', \'' +
      (p.enabled ? "disable" : "enable") + '\')">' + (p.enabled ? t("停用") : t("启用")) + "</button></div></div>";
  }).join("")
    || '<div class="empty">' + t("暂无经验包") + "</div>";
  // 分类 chip 过滤：药丸按钮 + 彩色圆点 + 计数，选中态高亮。值 = 分类名，空串 = 全部。
  const cats = S.skills.categories || [];
  const counts = S.skills.counts || {};
  let filt = S.skillCat || "";
  if (filt && !cats.includes(filt)) filt = "";   // 过滤的分类已空，回落全部
  const chipBox = $("skill-cat-chips");
  if (chipBox) {
    const chip = (val, label) =>
      '<button class="cat-chip' + (filt === val ? " active" : "") + '" onclick="skillCatFilter(\'' +
      jsq(val) + '\')">' + (val ? '<span class="cdot" style="background:' + CAT_COLOR[val] + '"></span>' : "") +
      esc(label) + "<b>" + (val ? (counts[val] || 0) : lessons.length) + "</b></button>";
    chipBox.innerHTML = cats.length > 1 ? chip("", t("全部")) + cats.map((c) => chip(c, t(c))).join("") : "";
  }
  const shown = filt ? lessons.filter((x) => (x.category || "未分类") === filt) : lessons;
  const cnt = $("skill-count");
  if (cnt) cnt.textContent = lessons.length
    ? (filt ? shown.length + t(" / 共 ") + lessons.length + t(" 条") : lessons.length + t(" 条"))
    : t("（暂无，跑一次任务后自动生成）");
  $("skill-lessons").innerHTML = shown.map((x) =>
    '<div class="card' + (x.enabled === false ? " off" : "") + '"><div class="head">' +
    '<span class="name">' + esc(t(x.title)) + "</span>" +
    (x.kind === "做法" ? '<span class="tag ok" title="' + t("已验证有效的做法（程序性记忆）") + '">' + t("做法") + "</span>" : "") +
    (x.category ? '<span class="tag cat" style="color:' + (CAT_COLOR[x.category] || "var(--muted)") + '" ' +
      'onclick="skillCatFilter(\'' + jsq(x.category) + '\')" title="' + t("只看该类") + '">' + esc(t(x.category)) + "</span>" : "") +
    '<span class="tag">' + esc(x.scope === "*" ? t("通用") : x.scope) + "</span>" +
    (x.seen > 1 ? '<span class="tag">' + t("出现 ") + x.seen + t(" 次") + "</span>" : "") +
    ((x.merged_titles || []).length ? '<span class="tag" title="' + t("被近似题合并吸收的变体标题数") + '">' + t("吸收 ") + x.merged_titles.length + t(" 个近似题") + "</span>" : "") +
    (x.hits ? '<span class="tag">' + t("已注入 ") + x.hits + t(" 次") + "</span>" : "") +
    (x.won > 0 ? '<span class="tag ok" title="' + t("注入后任务过审的次数（真实帮上忙）") + '">' + t("有效 ") + x.won + "</span>" : "") +
    (x.lost > 0 ? '<span class="tag" style="color:var(--bad)" title="' + t("注入后任务仍失败的次数（没防住）") + '">' + t("失守 ") + x.lost + "</span>" : "") +
    (x.useless ? '<span class="tag" style="color:var(--bad)" title="' + t("用户标记无用的次数（显式负反馈，排序下沉）") + '">' + t("没用 ") + x.useless + "</span>" : "") +
    (x.enabled === false ? '<span class="tag">' + t("已停用") + "</span>" : "") + "</div>" +
    '<div class="note">' + esc(t(x.content)) + "</div>" +
    '<div class="ops">' +
    '<button class="ghost small" onclick="skillLessonOp(\'' + jsq(x.id) + '\', \'' +
    (x.enabled === false ? "enable" : "disable") + '\')">' + (x.enabled === false ? t("启用") : t("停用")) + "</button>" +
    '<button class="ghost small" onclick="skillLessonOp(\'' + jsq(x.id) + '\', \'useless\')" title="' + t("标记这条教训没帮上忙？将停用并记一次无用反馈") + '">' + t("没用") + "</button>" +
    '<button class="danger small" onclick="skillLessonOp(\'' + jsq(x.id) + '\', \'delete\')">' + t("删除") + "</button>" +
    "</div></div>").join("") ||
    (filt ? '<div class="empty">' + t("该分类下暂无教训") + "</div>"
          : '<div class="empty">' + t("还没有自动教训——完成一次真实任务后，系统会自己复盘并沉淀。") + "</div>");
}

