/* ---------------------------------------------------------- 记忆中心 */
let MEMORY_CENTER = { data: null };

function memoryCenterSignature() {
  const state = S.state || {};
  const latest = state.task_latest || {};
  return JSON.stringify([
    [...(state.tasks || []), ...(state.archived_tasks || [])].map((task) => [task.id, task.workdir]),
    Object.keys(latest).sort().map((id) => [id, latest[id].id, latest[id].project_memory_id]),
  ]);
}

function memoryCenterMaybeRefresh() {
  if (S.tab === "memory" && MEMORY_CENTER.stateSignature !== memoryCenterSignature()) loadMemoryCenter();
}

/* ==================== 记忆图谱 (Memory Atlas) ==================== */
const ATLAS = { data: null, items: [], sky: [], ready: false };

/* 离开图谱页的统一停表：取消 rAF 动画并摘掉 atlas-live。摘类不能省——
 * #sub-atlas.atlas-live 的 display:flex!important 压得过 .hidden 的
 * display:none!important，类不摘＝图谱钉死在任何子页上（2026-10-22 实案：
 * 图谱→侧栏点任务，主区仍是记忆图谱）。所有不走 switchTab 的出口
 * （showDetailInMain / closeRun / exitSettings）必须各自调用；可重复调用。 */
function atlasLiveStop() {
  if (!ATLAS._stop) return;
  try { ATLAS._stop(); } catch (e) { /* 动画句柄已失效等 */ }
  ATLAS._stop = null;
}
window.loadAtlas = async function loadAtlas() {
  if (ATLAS._stop) { try { ATLAS._stop(); } catch(e){} ATLAS._stop = null; }
  if (ATLAS.ready) return;
  try {
    const data = await api("/api/memory");
    ATLAS.data = data;
    ATLAS.ready = true;
    ATLAS._init(data);
  } catch (e) {
    ATLAS.data = null;
    ATLAS.ready = false;
    const el = $("atlas-stream-list");
    if (el) el.innerHTML = '<div class="a-empty-inj" style="padding:24px;text-align:center">' + esc(e.message) + '</div>';
  }
};

ATLAS._init = function(data) {
  (function() {
    'use strict';
    const $a = (s, r) => (r || document).querySelector(s);
    const $$a = (s, r) => Array.from((r || document).querySelectorAll(s));
    const TAU = Math.PI * 2;
    const esc2 = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const fmt = (n) => Number(n || 0).toLocaleString('en-US');

    /* --- data transform --- */
    const g = data.global || {};
    const sk = g.skills || {};
    const kb = g.knowledge || {};
    const projs = data.projects || [];

    const SCOPE_LABEL = { novel: '长篇', serial_novel: '连载', code: '代码', research: '调研', article: '文章', '*': '通用' };
    const scopeText = (arr) => { if (!arr || !arr.length) return '通用'; return arr.map(s => SCOPE_LABEL[s] || s).join(' / '); };
    const normScope = (s) => { if (!s) return ['*']; if (typeof s === 'string') return s === '*' ? ['*'] : [s]; return Array.isArray(s) ? s : ['*']; };
    const calcKarma = (hits, won, lost) => { const base = Math.min(1, (hits || 0) * 0.02 + (won || 0) * 0.08); return Math.max(0.1, Math.min(0.99, base - (lost || 0) * 0.04)); };
    const calcChars = (t, b) => (t || '').length + (b || '').length;

    const packs = (sk.packs || []).map(p => ({
      id: 'pk_' + (p.id || p.name), source: 'pack', title: p.name || p.id, body: p.note || '',
      category: '经验包', scope: normScope(p.scopes), tags: [], karma: 0.9, hits: p.hits || 0,
      won: 0, lost: 0, seen: 1, stale: false, enabled: p.enabled !== false, star: true, asOf: null,
      chars: p.chars || calcChars(p.name, p.note)
    }));

    const lessons = (sk.lessons || []).map(x => ({
      id: 'l_' + (x.id || x.title), source: 'lesson', title: x.title || '', body: x.content || '',
      category: x.category || '未分类', scope: normScope(x.scope), tags: [],
      karma: calcKarma(x.hits, x.won, x.lost), hits: x.hits || 0, won: x.won || 0, lost: x.lost || 0,
      seen: x.seen || 1, stale: false, enabled: x.enabled !== false, star: true, asOf: null,
      chars: calcChars(x.title, x.content)
    }));

    const knowledge = (kb.entries || []).map(x => ({
      id: 'k_' + (x.id || x.title), source: 'knowledge', title: x.title || '', body: x.body || '',
      category: '领域事实', scope: normScope(x.scope), tags: x.tags || [],
      karma: calcKarma(x.hits, 0, 0), hits: x.hits || 0, won: 0, lost: 0,
      seen: x.seen || 1, stale: !!x.stale, enabled: x.enabled !== false, star: true,
      asOf: x.as_of || '', chars: calcChars(x.title, x.body)
    }));

    const projects = [];
    (projs || []).forEach(proj => {
      (proj.entries || []).forEach(e => {
        projects.push({
          id: 'p_' + (e.id || e.title), source: 'project', title: e.title || '', body: e.content || '',
          category: '项目记忆', scope: ['*'], tags: [],
          karma: calcKarma(0, 0, 0), hits: 0, won: 0, lost: 0,
          seen: 1, stale: !!e.expired, enabled: e.status === 'approved', star: true, asOf: null,
          chars: calcChars(e.title, e.content)
        });
      });
    });

    const allItems = [].concat(packs, lessons, knowledge, projects);
    const byId = new Map(allItems.map(it => [it.id, it]));

    const SOURCE_LABEL = { pack: '经验包', lesson: '经验', knowledge: '知识', project: '项目' };
    const SOURCE_COLOR = { pack: 'var(--text)', lesson: 'var(--accent)', knowledge: 'var(--ok)', project: 'var(--warn)' };

    const TOTALS = {
      lessons: lessons.length, knowledge: knowledge.length, projects: projects.length,
      packs: packs.length, all: allItems.length,
      never: lessons.filter(x => !x.hits).length,
      stale: knowledge.filter(x => x.stale).length,
      lost: lessons.filter(x => x.lost > 0).length,
      dup: lessons.filter(x => x.seen > 1).length,
      won: lessons.filter(x => x.won > 0).length,
      hit: lessons.filter(x => x.hits > 0).length
    };

    ATLAS.items = allItems;
    ATLAS.totals = TOTALS;

    /* --- state --- */
    const state = {
      q: '', source: 'all', gfilter: null, selectedId: null, hoverId: null,
      mode: 'source', scenario: 'code', goal: '', excluded: new Set(),
      matches: null, beam: null, mouse: { x: 0, y: 0, tx: 0, ty: 0 },
      pointer: { x: 0, y: 0, inside: false }, time: 0, ping: -9999,
      govLost: TOTALS.lost, govStale: TOTALS.stale, govDup: TOTALS.dup
    };

    const SCENARIOS = {
      code: { label: '代码修复', scopes: ['code'], goal: '', keys: ['复现', '日志', '测试', '端口', '根因', '回归', '幂等', '队列'] },
      novel: { label: '长篇写作', scopes: ['novel', 'serial_novel'], goal: '', keys: ['章节', '衔接', '钩子', '伏笔', '签约', '平台', '人物', '开篇', '卷末'] },
      research: { label: '调研报告', scopes: ['research', 'article', '*'], goal: '', keys: ['来源', '证据', '结论', '时效', '抽样', '对比'] }
    };

    /* --- helpers --- */
    const reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const norm = (s) => String(s || '').toLowerCase();

    /* canvas 读不到 CSS 变量：按当前皮肤解析一次调色板，换肤/明暗切换时
       由 frame() 的签名比对重建。日间皮肤的 --text 是深墨，经验包节点与星尘
       因此自动从近白转深——原来写死的 #e7eefb 在白底上等于隐身。 */
    const themeRoot = document.documentElement;
    const probeCtx = document.createElement('canvas').getContext('2d');
    const cssVar = (n, f) => (getComputedStyle(themeRoot).getPropertyValue(n).trim() || f);
    function rgbOf(v) {
      probeCtx.fillStyle = '#000000'; probeCtx.fillStyle = v;
      const s = probeCtx.fillStyle;
      const h = /^#([0-9a-f]{6})$/i.exec(s);
      if (h) { const n = parseInt(h[1], 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }
      const m = /^rgba?\(([^)]+)\)/i.exec(s);
      if (m) { const p = m[1].split(',').map(Number); return [p[0] | 0, p[1] | 0, p[2] | 0]; }
      return [31, 111, 208];
    }
    const rgbaOf = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
    const rgbCss = (c) => 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
    function readPalette() {
      const light = themeRoot.getAttribute('data-theme') !== 'dark';
      const accent = rgbOf(cssVar('--accent', '#1f6fd0'));
      const ok = rgbOf(cssVar('--ok', '#0d9a72'));
      const warn = rgbOf(cssVar('--warn', '#a9761a'));
      const bad = rgbOf(cssVar('--bad', '#d23c58'));
      const muted = rgbOf(cssVar('--muted', '#5d7290'));
      const text = rgbOf(cssVar('--text', '#0c1a2c'));
      return {
        light, accent, ok, warn, bad, muted, text,
        src: { pack: text, lesson: accent, knowledge: ok, project: warn },
        starBase: light ? .06 : .08, starSpan: light ? .16 : .25
      };
    }
    let PAL = null, palSig = '';
    function syncPalette() {
      const sig = (themeRoot.getAttribute('data-theme') || '') + '|' + (themeRoot.getAttribute('data-skin') || '');
      if (sig === palSig) return;
      palSig = sig; PAL = readPalette();
    }
    syncPalette();

    function searchScore(it, q) {
      const needle = norm(q);
      if (!needle) return 0;
      const t = norm(it.title), b = norm(it.body), tags = norm((it.tags || []).join(' '));
      let s = 0;
      if (t.includes(needle)) s += 140 + Math.max(0, 36 - t.indexOf(needle));
      if (b.includes(needle)) s += 45;
      if (tags.includes(needle)) s += 70;
      const parts = needle.split(/[\s,，、]+/).filter(x => x.length > 1);
      for (const p of parts) { if (t.includes(p)) s += 60; else if (b.includes(p)) s += 22; }
      return s > 0 ? s * (.6 + it.karma) : 0;
    }

    function healthOf(it) {
      if (it.source === 'knowledge' && it.stale) return ['warn', '过期'];
      if (it.lost >= 2 && it.lost > it.won) return ['bad', '失守 ' + it.lost];
      if (it.won > 0) return ['ok', '有效 ' + it.won];
      if (!it.hits && it.source !== 'pack') return ['dim', '未上场'];
      return null;
    }

    function healthColor(it) {
      if (it.source === 'knowledge' && it.stale) return PAL.warn;
      if (it.lost > it.won) return PAL.bad;
      if (it.won > 0) return PAL.ok;
      if (!it.hits) return PAL.muted;
      return PAL.accent;
    }

    const GP = {
      never: (it) => !it.hits && it.source !== 'pack',
      stale: (it) => it.source === 'knowledge' && it.stale,
      lost: (it) => it.source === 'lesson' && it.lost > 0,
      dup: (it) => it.source === 'lesson' && it.seen > 1
    };
    const GF_LABEL = { never: '从未上场', stale: '可能过期', lost: '失守记录', dup: '近似重复' };

    function currentList() {
      let arr = allItems;
      if (state.source !== 'all') arr = arr.filter(x => x.source === state.source);
      if (state.gfilter) arr = arr.filter(GP[state.gfilter]);
      if (state.q) {
        arr = arr.map(it => [it, searchScore(it, state.q)]).filter(x => x[1] > 0)
          .sort((a, b) => b[1] - a[1]).map(x => x[0]);
      } else {
        arr = arr.slice().sort((a, b) => b.karma - a.karma);
      }
      return arr;
    }

    function groupRows(list) {
      const map = new Map(); const out = [];
      list.forEach(it => {
        const key = it.title.split(' · ')[0];
        let g = map.get(key);
        if (!g) { g = { key, it, items: [] }; map.set(key, g); out.push(g); }
        g.items.push(it);
      });
      return out;
    }

    function refreshMatches() {
      const active = state.q || state.source !== 'all' || state.gfilter;
      if (!active) { state.matches = null; state.beam = null; return; }
      const list = currentList();
      state.matches = new Set(list.map(x => x.id));
      state.beam = state.q ? state.matches : null;
      if (state.selectedId && !state.matches.has(state.selectedId)) state.selectedId = null;
    }

    function toast(msg) {
      let el = $a('.a-toast');
      if (!el || !document.body.contains(el)) {
        el = document.createElement('div');
        el.className = 'a-toast';
        el.setAttribute('role', 'status');
        document.body.appendChild(el);
      }
      el.textContent = msg;
      el.classList.add('show');
      clearTimeout(toast._t);
      toast._t = setTimeout(() => el.classList.remove('show'), 2400);
    }

    /* --- stream --- */
    const FILTERS = [
      ['all', '全部', () => TOTALS.all],
      ['lesson', '经验', () => TOTALS.lessons],
      ['knowledge', '知识', () => TOTALS.knowledge],
      ['project', '项目', () => TOTALS.projects],
      ['pack', '经验包', () => TOTALS.packs]
    ];

    function renderChips() {
      const el = $a('#atlas-source-chips');
      if (!el) return;
      el.innerHTML = FILTERS.map(([v, label, cnt]) =>
        '<button class="a-chip' + (state.source === v ? ' active' : '') + '" data-src="' + v + '">' +
        esc2(label) + '<b>' + fmt(cnt()) + '</b></button>').join('');
    }

    function renderStream() {
      const full = currentList();
      const grouped = (state.q || state.gfilter) && state.gfilter !== 'dup';
      const entries = grouped ? groupRows(full) : full.map(it => ({ key: it.title, it, items: [it] }));
      const rows = entries.slice(0, state.q || state.gfilter ? 60 : 24);
      const totalForSource = state.source === 'all' ? TOTALS.all : TOTALS[state.source === 'lesson' ? 'lessons' : state.source === 'knowledge' ? 'knowledge' : state.source === 'project' ? 'projects' : 'packs'];

      const cntEl = $a('#atlas-stream-count');
      if (cntEl) cntEl.textContent = state.q || state.gfilter
        ? '命中 ' + fmt(full.length) + ' 条' + (grouped ? ' · ' + fmt(entries.length) + ' 组' : '')
        : 'Top ' + rows.length + ' · 全库 ' + fmt(totalForSource);

      const noteEl = $a('#atlas-filter-note');
      if (noteEl) noteEl.innerHTML = state.gfilter
        ? '<div class="a-filter-note"><span>治理筛选 · ' + esc2(GF_LABEL[state.gfilter]) + '</span><button data-clear-filter="1">清除 ×</button></div>'
        : '';

      const listEl = $a('#atlas-stream-list');
      if (listEl) listEl.innerHTML = rows.map(g => {
        const it = g.it; const count = g.items.length;
        const hits = g.items.reduce((a, x) => a + x.hits, 0);
        const h = healthOf(it);
        const col = SOURCE_COLOR[it.source] || 'var(--accent)';
        const active = g.items.some(x => x.id === state.selectedId);
        const sub = SOURCE_LABEL[it.source] + ' · ' + (it.source === 'knowledge' ? scopeText(it.scope) : it.category) +
          ' · 注入 ' + hits + (count > 1 ? ' · 组内 ' + count + ' 条' : '');
        const tail = count > 1
          ? '<span class="a-sbadge dim">×' + count + '</span>'
          : (h ? '<span class="a-sbadge ' + h[0] + '">' + esc2(h[1]) + '</span>' : '');
        return '<button class="a-srow' + (active ? ' active' : '') + '" data-id="' + esc(it.id) + '" style="--c:' + col + '" title="' + esc2(it.title) + '">' +
          '<span class="a-sdot"></span>' +
          '<span class="a-sbody"><span class="a-stitle">' + esc2(g.key) + '</span><span class="a-ssub">' + esc2(sub) + '</span></span>' +
          tail + '</button>';
      }).join('') || '<div class="a-empty-inj" style="padding:24px 8px;text-align:center">没有命中的记忆<br><span style="color:var(--muted)">试试搜索关键词</span></div>';

      const footEl = $a('#atlas-foot-left');
      if (footEl) footEl.innerHTML = state.q || state.gfilter
        ? '命中 <b>' + fmt(full.length) + '</b> 条' + (grouped ? ' · 归并 <b>' + fmt(entries.length) + '</b> 组' : ' · 逐条列出')
        : '载入 <b>Top ' + rows.length + '</b> · 按 karma 排序';

      const libEl = $a('#atlas-lib-total');
      if (libEl) libEl.textContent = fmt(TOTALS.all);

      const chipsEl = $a('#atlas-source-chips');
      if (chipsEl) chipsEl.querySelectorAll('[data-src]').forEach(b => b.classList.toggle('active', b.dataset.src === state.source));
    }

    /* --- detail --- */
    function renderDetail() {
      const card = $a('#atlas-node-card');
      const tel = $a('#atlas-telemetry');
      if (!card) return;
      if (!state.selectedId) { card.classList.remove('show'); if (tel) tel.classList.remove('hidden'); return; }
      const it = byId.get(state.selectedId);
      if (!it) return;
      if (tel) tel.classList.add('hidden');
      const h = healthOf(it);
      const excluded = state.excluded.has(it.id);
      card.innerHTML =
        '<div class="a-nc-top"><span class="a-nc-src">' + esc2(SOURCE_LABEL[it.source]) + '</span>' +
        '<span class="a-nc-cat">' + esc2(it.category) + ' · ' + esc2(scopeText(it.scope)) + '</span>' +
        '<button class="a-nc-close" data-close="1" aria-label="关闭"><svg class="ico" style="width:11px;height:11px"><use href="#i-x"/></svg></button></div>' +
        '<h3 class="a-nc-title">' + esc2(it.title) + '</h3>' +
        '<p class="a-nc-body">' + esc2(it.body) + '</p>' +
        '<div class="a-nc-karma"><span>KARMA</span><div class="a-kbar"><i style="width:' + Math.round(it.karma * 100) + '%"></i></div><b>' + it.karma.toFixed(2) + '</b></div>' +
        '<div class="a-nc-stats">' +
          '<div><b>' + fmt(it.hits) + '</b><span>注入</span></div>' +
          '<div><b style="color:' + (it.won ? 'var(--ok)' : 'var(--muted)') + '">' + fmt(it.won) + '</b><span>有效</span></div>' +
          '<div><b style="color:' + (it.lost ? 'var(--bad)' : 'var(--muted)') + '">' + fmt(it.lost) + '</b><span>失守</span></div>' +
        '</div>' +
        '<div class="a-nc-acts">' +
          (it.source === 'pack' ? '<button class="a-btn-ghost" disabled>整包注入 · ' + fmt(it.chars) + ' 字</button>' :
            '<button class="a-btn-gold" data-exclude="' + esc(it.id) + '">' + (excluded ? '恢复注入' : '排除预演') + '</button>') +
          '<button class="a-btn-ghost" data-review="' + esc(it.id) + '">已复核</button>' +
        '</div>' +
        (h ? '<div class="a-tel-hint" style="margin-top:7px"><i style="background:' + (h[0] === 'bad' ? 'var(--bad)' : h[0] === 'warn' ? 'var(--warn)' : 'var(--accent)') + '"></i>' + esc2(h[1]) + (it.stale && it.asOf ? ' · 截至 ' + esc2(it.asOf) : '') + '</div>' : '');
      card.classList.add('show');
    }

    function selectItem(id) {
      state.selectedId = state.selectedId === id ? null : id;
      renderDetail(); renderStream();
      const it = state.selectedId && byId.get(state.selectedId);
      if (it) toast('已聚焦 · ' + it.title);
    }

    /* --- injection preview --- */
    function goalTerms() {
      const scen = SCENARIOS[state.scenario];
      const extra = [];
      const clean = state.goal.replace(/[，。：；、,.!?！？：；\s]/g, '');
      for (let i = 0; i < clean.length - 1 && extra.length < 14; i++) {
        const t = clean.slice(i, i + 2);
        if (!['我们', '这个', '一个', '上一', '一章', '并补', '确认'].includes(t)) extra.push(t);
      }
      return Array.from(new Set((scen ? scen.keys : []).concat(extra)));
    }

    function scoreFor(it, terms) {
      const hay = it.title + ' ' + it.body + ' ' + (it.tags || []).join(' ');
      const hits = terms.filter(t => hay.includes(t));
      let s = it.karma * 46 + Math.min(it.hits, 22) * .85 + it.won * 4.2 - it.lost * 2.3;
      for (const t of hits) s += t.length > 1 ? 17 : 9;
      return { s, hits };
    }

    function computeInjection() {
      const scen = SCENARIOS[state.scenario] || SCENARIOS.code;
      const terms = goalTerms();
      const packList = packs.filter(p => p.scope.some(s => scen.scopes.includes(s)));
      const cands = allItems.filter(it => it.source !== 'pack' && !state.excluded.has(it.id) &&
        (it.scope.includes('*') || it.scope.some(s => scen.scopes.includes(s))))
        .map(it => ({ it, ...scoreFor(it, terms) })).sort((a, b) => b.s - a.s);
      const pick = (src, n, cap) => {
        const out = []; let chars = 0;
        for (const c of cands) {
          if (c.it.source !== src) continue;
          const len = c.it.chars;
          if (out.length >= n) break;
          if (cap && chars + len > cap) continue;
          out.push(c); chars += len;
        }
        return { rows: out, chars };
      };
      const packChars = packList.reduce((a, p) => a + p.chars, 0);
      const lessonPick = pick('lesson', 8, Math.max(900, 9000 - packChars));
      const knowledgePick = pick('knowledge', 6, 3000);
      const projectPick = pick('project', 3, 1200);
      return { scen, terms, packList, packChars, lessons: lessonPick, knowledge: knowledgePick, project: projectPick,
        expChars: packChars + lessonPick.chars, knowChars: knowledgePick.chars, expBudget: 9000, knowBudget: 3000 };
    }

    function whyChips(c) {
      const chips = [];
      if (c.hits.length) chips.push('<i class="hit">命中「' + esc2(c.hits[0]) + '」</i>');
      if (c.it.won) chips.push('<i class="good">有效 ' + c.it.won + '</i>');
      if (c.it.lost) chips.push('<i>失守 ' + c.it.lost + '</i>');
      if (!chips.length) chips.push('<i>karma ' + c.it.karma.toFixed(2) + '</i>');
      return chips.join('');
    }

    function renderInjection() {
      const R = computeInjection();
      const pct = (v, cap) => Math.min(100, Math.round(v / cap * 100));
      const bEl = $a('#atlas-budgets');
      if (bEl) bEl.innerHTML =
        '<div class="a-budget"><div class="b-head"><span>经验注入</span><b>' + fmt(R.expChars) + ' <i>/ 9,000</i></b></div>' +
          '<div class="a-b-track"><i style="width:' + pct(R.expChars, 9000) + '%"></i></div></div>' +
        '<div class="a-budget k"><div class="b-head"><span>知识注入</span><b>' + fmt(R.knowChars) + ' <i>/ 3,000</i></b></div>' +
          '<div class="a-b-track"><i style="width:' + pct(R.knowChars, 3000) + '%"></i></div></div>';

      const rowsHtml = (rows, start) => rows.map((c, i) =>
        '<div class="a-inj-row" style="animation-delay:' + Math.min(280, (start + i) * 22) + 'ms">' +
          '<span class="a-ir-idx">' + String(start + i + 1).padStart(2, '0') + '</span>' +
          '<span class="a-ir-main"><span class="a-ir-title">' + esc2(c.it.title) + '</span>' +
          '<span class="a-ir-why">' + whyChips(c) + '</span></span>' +
          '<button class="a-eye" data-ex="' + esc(c.it.id) + '" title="排除并补位"><svg><use href="#i-eye"/></svg></button>' +
        '</div>').join('');

      const packHtml = R.packList.length
        ? '<div class="a-pack-chips">' + R.packList.map(p =>
            '<button class="a-pack-chip" data-pack="' + esc(p.id) + '" title="' + esc2(p.title) + ' · ' + fmt(p.chars) + ' 字">' +
            '<span>' + esc2(p.title) + '</span><b>' + fmt(p.chars) + ' 字</b></button>').join('') + '</div>'
        : '<div class="a-empty-inj">该任务类型无匹配经验包</div>';

      const injEl = $a('#atlas-inj-groups');
      if (injEl) injEl.innerHTML =
        '<div class="a-igroup"><div class="a-ig-head"><span class="a-ig-name"><i></i>经验包</span><span class="a-ig-meta">' + R.packList.length + ' 个 · ' + fmt(R.packChars) + ' 字</span></div>' + packHtml + '</div>' +
        '<div class="a-igroup"><div class="a-ig-head"><span class="a-ig-name"><i></i>教训</span><span class="a-ig-meta">' + R.lessons.rows.length + ' 条 · ' + fmt(R.lessons.chars) + ' 字</span></div>' +
          (rowsHtml(R.lessons.rows, 0) || '<div class="a-empty-inj">无匹配教训</div>') + '</div>' +
        '<div class="a-igroup"><div class="a-ig-head"><span class="a-ig-name"><i></i>知识</span><span class="a-ig-meta">' + R.knowledge.rows.length + ' 条 · ' + fmt(R.knowledge.chars) + ' 字</span></div>' +
          (rowsHtml(R.knowledge.rows, 0) || '<div class="a-empty-inj">无匹配知识</div>') + '</div>' +
        '<div class="a-igroup"><div class="a-ig-head"><span class="a-ig-name"><i></i>项目记忆</span><span class="a-ig-meta">' + R.project.rows.length + ' 条 · ' + fmt(R.project.chars) + ' 字</span></div>' +
          (rowsHtml(R.project.rows, 0) || '<div class="a-empty-inj">无匹配项目记忆</div>') + '</div>';

      const footEl = $a('#atlas-inj-foot');
      if (footEl) footEl.innerHTML = state.excluded.size
        ? '<span>已排除 ' + state.excluded.size + ' 条 · 候选自动补位</span><button data-reset-ex="1">全部恢复</button>'
        : '<span>排序 = karma × 目标相关度</span><span>预算独立 · 不挤占正文</span>';
    }

    function renderScen() {
      const el = $a('#atlas-scen');
      if (!el) return;
      el.innerHTML = Object.entries(SCENARIOS).map(([k, s]) =>
        '<button data-scen="' + k + '" class="' + (state.scenario === k ? 'active' : '') + '">' + esc2(s.label) + '</button>').join('');
      const goalEl = $a('#atlas-goal');
      if (goalEl) goalEl.value = state.goal;
    }

    let goalTimer = null;
    function sweepAndRender() {
      const pv = $a('#atlas-preview');
      if (pv) pv.classList.add('scanning');
      setTimeout(() => { renderInjection(); setTimeout(() => { if (pv) pv.classList.remove('scanning'); }, 280); }, 180);
    }

    /* --- governance --- */
    function renderGov() {
      const tiles = [
        { k: 'never', label: '从未上场', value: fmt(TOTALS.never), sub: '/ ' + fmt(TOTALS.lessons), pct: TOTALS.never / Math.max(1, TOTALS.lessons) * 100, cls: 'warn' },
        { k: 'stale', label: '事实可能过期', value: fmt(state.govStale), sub: '/ ' + fmt(TOTALS.knowledge) + ' 知识', pct: state.govStale / Math.max(1, TOTALS.knowledge) * 100, cls: 'warn' },
        { k: 'lost', label: '失守记录', value: fmt(state.govLost), sub: '条教训', pct: state.govLost / Math.max(1, TOTALS.lessons) * 100, cls: 'bad' },
        { k: 'dup', label: '近似重复', value: fmt(state.govDup), sub: '条待合并', pct: state.govDup / Math.max(1, TOTALS.lessons) * 100, cls: '' }
      ];
      const gEl = $a('#atlas-gov-grid');
      if (gEl) gEl.innerHTML = tiles.map(t =>
        '<button class="a-gov-tile ' + t.cls + '" data-gov="' + t.k + '">' +
          '<b>' + t.value + '</b><span>' + esc2(t.label) + '</span><em>' + t.sub + '</em>' +
          '<div class="gbar" style="width:' + Math.max(4, Math.min(100, t.pct)) + '%"></div>' +
        '</button>').join('');

      const qEl = $a('#atlas-queue');
      if (qEl) qEl.innerHTML = '<div class="a-q-row"><div><b style="color:var(--muted);font-size:9px">治理操作需到对应管理页执行</b></div></div>';
    }

    /* --- canvas atlas --- */
    const canvas = $a('#atlas-sky');
    const atlasWrap = $a('#atlas-canvas-wrap');
    if (!canvas || !atlasWrap) return;
    const ctx = canvas.getContext('2d');
    let W = 0, H = 0, DPR = 1, cx = 0, cy = 0, R = 0;
    const TILT = .7;
    const BANDS = {
      pack: { r: .34, speed: -.000034 },
      lesson: { r: .585, speed: .000019 },
      knowledge: { r: .805, speed: -.000015 },
      project: { r: 1.015, speed: .000011 }
    };
    const sky = [];
    const sprites = new Map();
    const stars = [];
    const pulses = [];
    let nextPulse = 0, nextShot = 0;
    const shots = [];
    let animId = null;

    function hash01(str) {
      let h = 2166136261;
      for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
      return ((h >>> 0) % 10000) / 10000;
    }

    function buildSky() {
      sky.length = 0;
      const top = (arr, n) => arr.slice().sort((a, b) => b.karma - a.karma).slice(0, n);
      const chosen = [].concat(packs, top(lessons, 46), top(knowledge, 18), top(projects, 12));
      const groups = { pack: [], lesson: [], knowledge: [], project: [] };
      chosen.forEach(it => groups[it.source].push(it));
      Object.keys(groups).forEach(src => {
        const arr = groups[src].sort((a, b) => String(a.category).localeCompare(String(b.category), 'zh'));
        arr.forEach((it, i) => {
          const h = hash01(it.id);
          sky.push({
            it, source: src, id: it.id,
            a0: (i / Math.max(1, arr.length)) * TAU + .4 + (h - .5) * .05,
            spin: (hash01(it.id + 's') - .5) * .000004,
            rj: 1 + (hash01(it.id + 'r') - .5) * .055,
            x: 0, y: 0
          });
        });
      });
    }

    function makeSprite(rgb) {
      const c = document.createElement('canvas');
      c.width = c.height = 64;
      const g = c.getContext('2d');
      const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
      grd.addColorStop(0, rgbaOf(rgb, 1));
      grd.addColorStop(.22, rgbaOf(rgb, .7));
      grd.addColorStop(.55, rgbaOf(rgb, .22));
      grd.addColorStop(1, rgbaOf(rgb, 0));
      g.fillStyle = grd;
      g.fillRect(0, 0, 64, 64);
      return c;
    }
    function spriteFor(rgb) {
      const key = rgb.join(',');
      if (!sprites.has(key)) sprites.set(key, makeSprite(rgb));
      return sprites.get(key);
    }

    function makeStars() {
      stars.length = 0;
      const n = Math.min(240, Math.round(W * H / 4200));
      for (let i = 0; i < n; i++) stars.push({ x: Math.random(), y: Math.random(), r: .3 + Math.random() * 1, p: Math.random() * TAU, s: .3 + Math.random() * .8 });
    }

    function resize() {
      const r = atlasWrap.getBoundingClientRect();
      W = Math.max(200, r.width); H = Math.max(200, r.height);
      DPR = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(W * DPR); canvas.height = Math.round(H * DPR);
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      cx = W / 2; cy = H * .52;
      R = Math.min(W * .45, H * .44);
      makeStars();
    }

    function layout(now) {
      const rot = -.15 + state.mouse.x * .045;
      sky.forEach(n => {
        const band = BANDS[n.source];
        const r = R * band.r * n.rj;
        const a = n.a0 + now * (band.speed + n.spin);
        const x0 = Math.cos(a) * r;
        const y0 = Math.sin(a) * r * TILT;
        n.x = cx + x0 * Math.cos(rot) - y0 * Math.sin(rot);
        n.y = cy + x0 * Math.sin(rot) + y0 * Math.cos(rot);
        n.a = a; n.r = r; n.rot = rot;
      });
    }

    function matchOf(n) { return !state.matches || state.matches.has(n.id); }

    function nodeColor(n) {
      if (state.mode === 'health') return healthColor(n.it);
      return PAL.src[n.source] || PAL.accent;
    }

    function drawOrbits(now) {
      const rot = -.15 + state.mouse.x * .045;
      Object.keys(BANDS).forEach((src, bi) => {
        const rr = R * BANDS[src].r;
        ctx.beginPath();
        ctx.ellipse(cx, cy, rr, rr * TILT, rot, 0, TAU);
        ctx.strokeStyle = rgbaOf(PAL.accent, bi === 3 ? .18 : .11);
        ctx.lineWidth = .7;
        ctx.stroke();
        const ticks = 72;
        for (let i = 0; i < ticks; i++) {
          const a = (i / ticks) * TAU + now * .000004;
          const x0 = Math.cos(a) * rr, y0 = Math.sin(a) * rr;
          const x1 = cx + x0 * Math.cos(rot) - y0 * Math.sin(rot);
          const y1 = cy + x0 * Math.sin(rot) + y0 * Math.cos(rot);
          const x2 = Math.cos(a) * (rr + (i % 7 === 0 ? 4 : 2));
          const y2 = Math.sin(a) * (rr + (i % 7 === 0 ? 4 : 2));
          const x3 = cx + x2 * Math.cos(rot) - y2 * Math.sin(rot);
          const y3 = cy + x2 * Math.sin(rot) + y2 * Math.cos(rot);
          ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x3, y3);
          ctx.strokeStyle = i % 7 === 0 ? rgbaOf(PAL.accent, .2) : rgbaOf(PAL.accent, .07);
          ctx.lineWidth = .5; ctx.stroke();
        }
      });
      ctx.strokeStyle = rgbaOf(PAL.accent, .07); ctx.lineWidth = .5;
      ctx.beginPath(); ctx.moveTo(cx - R * 1.04, cy); ctx.lineTo(cx + R * 1.04, cy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx, cy - R * .64); ctx.lineTo(cx, cy + R * .64); ctx.stroke();
    }

    function drawSweep(now) {
      const rot = -.15 + state.mouse.x * .045;
      const ang = (reduced ? 12000 : now) * .00016;
      ctx.save();
      ctx.translate(cx, cy); ctx.rotate(rot); ctx.scale(1, TILT);
      const rr = R * 1.08;
      const g = ctx.createRadialGradient(0, 0, R * .06, 0, 0, rr);
      g.addColorStop(0, rgbaOf(PAL.accent, .06));
      g.addColorStop(.72, rgbaOf(PAL.accent, .03));
      g.addColorStop(1, rgbaOf(PAL.accent, 0));
      ctx.beginPath(); ctx.moveTo(0, 0);
      ctx.arc(0, 0, rr, ang - .34, ang); ctx.closePath();
      ctx.fillStyle = g; ctx.fill();
      ctx.beginPath(); ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(ang) * rr, Math.sin(ang) * rr);
      ctx.strokeStyle = rgbaOf(PAL.accent, .1); ctx.lineWidth = .6; ctx.stroke();
      ctx.restore();
    }

    function drawLinks() {
      const groups = new Map();
      sky.forEach(n => {
        if (!matchOf(n)) return;
        const key = n.source + '|' + n.it.category;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(n);
      });
      ctx.lineWidth = .6;
      groups.forEach(arr => {
        arr.sort((a, b) => a.a - b.a);
        for (let i = 0; i < arr.length - 1; i++) {
          const a = arr[i], b = arr[i + 1];
          if (Math.abs(b.a - a.a) > .5) continue;
          ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y);
          const g = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
          g.addColorStop(0, rgbaOf(PAL.accent, .14));
          g.addColorStop(.5, rgbaOf(PAL.accent, .05));
          g.addColorStop(1, rgbaOf(PAL.accent, .14));
          ctx.strokeStyle = g; ctx.stroke();
        }
      });
    }

    function drawBeams(now) {
      if (state.beam) {
        let count = 0;
        sky.forEach(n => {
          if (!state.beam.has(n.id) || count++ > 40) return;
          const col = nodeColor(n);
          ctx.beginPath(); ctx.setLineDash([2, 7]);
          ctx.lineDashOffset = -(now * .035);
          ctx.moveTo(cx, cy); ctx.lineTo(n.x, n.y);
          ctx.strokeStyle = rgbaOf(PAL.accent, .3); ctx.lineWidth = .8; ctx.stroke();
          ctx.setLineDash([]);
          ctx.beginPath(); ctx.arc(n.x, n.y, 2.2, 0, TAU);
          ctx.fillStyle = rgbCss(col); ctx.fill();
        });
      }
      if (state.selectedId) {
        const n = sky.find(x => x.id === state.selectedId);
        if (n) {
          const g = ctx.createLinearGradient(cx, cy, n.x, n.y);
          g.addColorStop(0, rgbaOf(PAL.accent, .5));
          g.addColorStop(1, rgbaOf(PAL.accent, .04));
          ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(n.x, n.y);
          ctx.strokeStyle = g; ctx.lineWidth = .9; ctx.stroke();
        }
      }
    }

    function drawPulses(now) {
      for (let i = pulses.length - 1; i >= 0; i--) {
        const p = pulses[i];
        const t = (now - p.t0) / 1500;
        if (t >= 1) { pulses.splice(i, 1); continue; }
        const n = p.n;
        const px = n.x + (cx - n.x) * t;
        const py = n.y + (cy - n.y) * t;
        const g = ctx.createLinearGradient(n.x, n.y, cx, cy);
        g.addColorStop(0, rgbaOf(PAL.accent, .14));
        g.addColorStop(1, rgbaOf(PAL.accent, .02));
        ctx.beginPath(); ctx.moveTo(n.x, n.y); ctx.lineTo(cx, cy);
        ctx.strokeStyle = g; ctx.lineWidth = .6; ctx.stroke();
        ctx.beginPath(); ctx.arc(px, py, 1.6, 0, TAU);
        ctx.fillStyle = rgbaOf(PAL.accent, .7 * (1 - t) + .15); ctx.fill();
      }
    }

    function drawCorePing(now) {
      const age = (now - state.ping) / 900;
      if (age < 0 || age >= 1) return;
      ctx.beginPath(); ctx.arc(cx, cy, 40 + age * (R * .5), 0, TAU);
      ctx.strokeStyle = rgbaOf(PAL.accent, .3 * (1 - age)); ctx.lineWidth = .8; ctx.stroke();
      ctx.beginPath(); ctx.arc(cx, cy, 30 + age * (R * .3), 0, TAU);
      ctx.strokeStyle = rgbaOf(PAL.accent, .16 * (1 - age)); ctx.stroke();
    }

    function drawStars(now) {
      stars.forEach(s => {
        const tw = .35 + .65 * (.5 + .5 * Math.sin(now * .001 * s.s + s.p));
        ctx.beginPath(); ctx.arc(s.x * W, s.y * H, s.r, 0, TAU);
        ctx.fillStyle = rgbaOf(PAL.text, PAL.starBase + tw * PAL.starSpan); ctx.fill();
      });
      for (let i = shots.length - 1; i >= 0; i--) {
        const s = shots[i];
        const t = (now - s.t0) / s.dur;
        if (t >= 1) { shots.splice(i, 1); continue; }
        const x = s.x * W + s.vx * t * 40;
        const y = s.y * H + s.vy * t * 40;
        const g = ctx.createLinearGradient(x, y, x - s.vx * 80, y - s.vy * 80);
        g.addColorStop(0, rgbaOf(PAL.accent, .45 * (1 - t)));
        g.addColorStop(1, rgbaOf(PAL.accent, 0));
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - s.vx * 80, y - s.vy * 80);
        ctx.strokeStyle = g; ctx.lineWidth = .8; ctx.stroke();
      }
    }

    function drawNodes(now) {
      const t = reduced ? 0 : now;
      sky.forEach((n, idx) => {
        const matched = matchOf(n);
        const hover = state.hoverId === n.id;
        const selected = state.selectedId === n.id;
        const alpha = matched ? 1 : .12;
        const col = nodeColor(n);
        const size = 1.5 + n.it.karma * 4.5 + (selected ? 1.2 : 0);
        const pulse = state.beam && state.beam.has(n.id) ? 1 + .16 * Math.sin(t * .005 + idx) : 1;
        const gs = (9 + size * 3) * pulse;
        ctx.globalAlpha = alpha;
        if (matched && (n.it.karma > .55 || (state.matches && state.matches.has(n.id)))) {
          ctx.drawImage(spriteFor(col), n.x - gs / 2, n.y - gs / 2, gs, gs);
        }
        ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, TAU);
        ctx.fillStyle = rgbCss(col); ctx.fill();
        if (n.it.won > 0 && state.mode === 'source') {
          ctx.beginPath(); ctx.arc(n.x, n.y, size + 2.2, 0, TAU);
          ctx.strokeStyle = rgbaOf(PAL.ok, .28); ctx.lineWidth = .6; ctx.stroke();
        } else if (n.it.lost > n.it.won && state.mode === 'source') {
          ctx.beginPath(); ctx.arc(n.x, n.y, size + 2.2, 0, TAU);
          ctx.strokeStyle = rgbaOf(PAL.bad, .3); ctx.lineWidth = .6; ctx.stroke();
        }
        if (hover || selected) {
          ctx.beginPath(); ctx.arc(n.x, n.y, size + 5 + (selected ? 2 * Math.sin(t * .004) : 0), 0, TAU);
          ctx.strokeStyle = rgbaOf(PAL.accent, selected ? .75 : .5);
          ctx.lineWidth = .8; ctx.stroke();
          ctx.beginPath(); ctx.arc(n.x, n.y, size + 9, 0, TAU);
          ctx.strokeStyle = rgbaOf(PAL.accent, .14);
          ctx.setLineDash([1.5, 3.5]); ctx.stroke(); ctx.setLineDash([]);
        }
        ctx.globalAlpha = 1;
      });
    }

    function draw(now) {
      ctx.clearRect(0, 0, W, H);
      drawStars(now);
      drawSweep(now);
      drawOrbits(now);
      drawLinks();
      drawCorePing(now);
      drawPulses(now);
      drawBeams(now);
      drawNodes(now);
    }

    function nearestNode(x, y) {
      let best = null, bd = 18 * 18;
      sky.forEach(n => {
        if (!matchOf(n) && !state.q) return;
        const d = (n.x - x) ** 2 + (n.y - y) ** 2;
        if (d < bd) { bd = d; best = n; }
      });
      return best;
    }

    function showTip(n, clientX, clientY) {
      const tip = $a('#atlas-tip');
      if (!tip) return;
      if (!n) { tip.classList.remove('show'); return; }
      const it = n.it;
      tip.innerHTML = '<div class="a-tt-src">' + esc2(SOURCE_LABEL[it.source]) + ' · ' + esc2(it.category) + '</div>' +
        '<div class="a-tt-title">' + esc2(it.title) + '</div>' +
        '<div class="a-tt-meta">KARMA ' + it.karma.toFixed(2) + ' · 注入 ' + it.hits + ' · 有效 ' + it.won + ' · 失守 ' + it.lost + '</div>';
      const r = atlasWrap.getBoundingClientRect();
      const x = clientX - r.left, y = clientY - r.top;
      tip.style.left = Math.min(W - 220, x + 12) + 'px';
      tip.style.top = Math.min(H - 64, y + 14) + 'px';
      tip.classList.add('show');
    }

    function frame(now) {
      syncPalette();
      state.time = now;
      state.mouse.x += (state.mouse.tx - state.mouse.x) * .06;
      state.mouse.y += (state.mouse.ty - state.mouse.y) * .06;
      if (!reduced) {
        if (!state.q && now > nextPulse && sky.length) {
          nextPulse = now + 4200 + Math.random() * 2200;
          const n = sky[Math.floor(Math.random() * sky.length)];
          pulses.push({ n, t0: now });
          const coreEl = $a('#atlas-core');
          if (coreEl) { coreEl.classList.add('ping'); setTimeout(() => coreEl.classList.remove('ping'), 420); }
        }
        if (now > nextShot) {
          nextShot = now + 6800 + Math.random() * 5400;
          shots.push({ x: .18 + Math.random() * .62, y: .08 + Math.random() * .26, vx: .55, vy: .34, t0: now, dur: 880 });
        }
      }
      layout(now);
      if (state.pointer.inside) {
        const n = nearestNode(state.pointer.x, state.pointer.y);
        const id = n ? n.id : null;
        if (id !== state.hoverId) {
          state.hoverId = id;
          canvas.style.cursor = n ? 'pointer' : 'default';
          if (n) {
            const rr = canvas.getBoundingClientRect();
            showTip(n, rr.left + state.pointer.x, rr.top + state.pointer.y);
          } else showTip(null);
        }
      }
      draw(now);
      animId = requestAnimationFrame(frame);
    }

    /* --- chrome updates --- */
    function updateAtlasChrome() {
      const m = state.matches;
      const inSky = m ? sky.filter(n => m.has(n.id)).length : 0;
      const total = m ? m.size : TOTALS.all;
      const coreNumEl = $a('#atlas-core-num');
      const coreLabelEl = $a('#atlas-core-label');
      if (coreNumEl) coreNumEl.textContent = fmt(total);
      if (coreLabelEl) coreLabelEl.textContent = m ? 'MATCHES' : 'MEMORY';
      const statusEl = $a('#atlas-status');
      if (statusEl) {
        if (state.q) statusEl.innerHTML = '命中 <b>' + fmt(m ? m.size : 0) + '</b> 条 · 星图 <b>' + fmt(inSky) + '</b> 体';
        else if (state.gfilter) statusEl.innerHTML = '治理 · <b>' + esc2(GF_LABEL[state.gfilter]) + '</b> · <b>' + fmt(inSky) + '</b> 体';
        else if (state.source !== 'all') statusEl.innerHTML = '来源 · <b>' + esc2(SOURCE_LABEL[state.source]) + '</b> · <b>' + fmt(inSky) + '</b> 体';
        else statusEl.innerHTML = '载入 <b>' + sky.length + '</b> 个记忆体';
      }
    }

    function renderLegend() {
      const el = $a('#atlas-legend');
      if (!el) return;
      const rows = state.mode === 'source'
        ? [['var(--text)', '经验包'], ['var(--accent)', '经验/教训'], ['var(--ok)', '知识'], ['var(--warn)', '项目记忆']]
        : [['var(--ok)', '有效'], ['var(--bad)', '失守'], ['var(--warn)', '过期'], ['var(--muted)', '未上场']];
      el.innerHTML = '<div class="a-lg-title">' + (state.mode === 'source' ? 'SOURCE' : 'HEALTH') + '</div>' +
        rows.map(([c, l]) => '<div class="a-lg-row"><i class="a-lg-dot" style="--c:' + c + '"></i><span>' + esc2(l) + '</span></div>').join('');
    }

    function refreshAll() {
      refreshMatches(); renderStream(); renderDetail(); updateAtlasChrome(); renderLegend();
    }

    /* --- event binding --- */
    function bind() {
      const qEl = $a('#atlas-q');
      if (qEl) qEl.addEventListener('input', e => { state.q = e.target.value.trim(); state.gfilter = null; state.ping = performance.now(); refreshAll(); });

      const chipsEl = $a('#atlas-source-chips');
      if (chipsEl) chipsEl.addEventListener('click', e => { const b = e.target.closest('[data-src]'); if (!b) return; state.source = b.dataset.src; state.gfilter = null; refreshAll(); });

      const noteEl = $a('#atlas-filter-note');
      if (noteEl) noteEl.addEventListener('click', e => { if (e.target.closest('[data-clear-filter]')) { state.gfilter = null; state.q = ''; const qEl = $a('#atlas-q'); if (qEl) qEl.value = ''; refreshAll(); } });

      const listEl = $a('#atlas-stream-list');
      if (listEl) {
        listEl.addEventListener('click', e => { const row = e.target.closest('[data-id]'); if (row) selectItem(row.dataset.id); });
        listEl.addEventListener('mouseover', e => { const row = e.target.closest('[data-id]'); if (row) state.hoverId = row.dataset.id; });
        listEl.addEventListener('mouseleave', () => { state.hoverId = null; });
      }

      const cardEl = $a('#atlas-node-card');
      if (cardEl) cardEl.addEventListener('click', e => {
        const close = e.target.closest('[data-close]');
        if (close) { state.selectedId = null; renderDetail(); renderStream(); return; }
        const ex = e.target.closest('[data-exclude]');
        if (ex) {
          const id = ex.dataset.exclude;
          if (state.excluded.has(id)) { state.excluded.delete(id); toast('已恢复注入资格'); }
          else { state.excluded.add(id); toast('已从注入预演排除'); }
          renderInjection(); renderDetail(); return;
        }
        const rv = e.target.closest('[data-review]');
        if (rv) toast('已复核 · ' + (byId.get(rv.dataset.review) || {}).title);
      });

      const modeEl = $a('#atlas-mode');
      if (modeEl) modeEl.addEventListener('click', e => {
        const b = e.target.closest('[data-mode]');
        if (!b) return;
        state.mode = b.dataset.mode;
        $$a('#atlas-mode button').forEach(x => { x.classList.toggle('active', x === b); x.setAttribute('aria-pressed', x === b ? 'true' : 'false'); });
        renderLegend();
        toast(state.mode === 'source' ? '按来源着色' : '按健康度着色');
      });

      const scenEl = $a('#atlas-scen');
      if (scenEl) scenEl.addEventListener('click', e => {
        const b = e.target.closest('[data-scen]');
        if (!b) return;
        state.scenario = b.dataset.scen;
        state.goal = SCENARIOS[state.scenario].goal;
        state.excluded.clear();
        renderScen(); sweepAndRender(); state.ping = performance.now();
        toast('切换到「' + SCENARIOS[state.scenario].label + '」');
      });

      const goalEl = $a('#atlas-goal');
      if (goalEl) goalEl.addEventListener('input', e => {
        state.goal = e.target.value;
        clearTimeout(goalTimer);
        goalTimer = setTimeout(() => { renderInjection(); state.ping = performance.now(); }, 320);
      });

      const recalcEl = $a('#atlas-recalc');
      if (recalcEl) recalcEl.addEventListener('click', () => { sweepAndRender(); toast('重新演算完成'); });

      const buildEl = $a('#atlas-build');
      if (buildEl) buildEl.addEventListener('click', () => { sweepAndRender(); toast('演算完成'); });

      const injEl = $a('#atlas-inj-groups');
      if (injEl) injEl.addEventListener('click', e => {
        const pk = e.target.closest('[data-pack]');
        if (pk) { selectItem(pk.dataset.pack); return; }
        const btn = e.target.closest('[data-ex]');
        if (!btn) return;
        state.excluded.add(btn.dataset.ex);
        renderInjection(); renderDetail();
        toast('已排除一条');
      });

      const footEl = $a('#atlas-inj-foot');
      if (footEl) footEl.addEventListener('click', e => {
        if (e.target.closest('[data-reset-ex]')) { state.excluded.clear(); renderInjection(); renderDetail(); toast('已恢复全部'); }
      });

      const govEl = $a('#atlas-gov-grid');
      if (govEl) govEl.addEventListener('click', e => {
        const t = e.target.closest('[data-gov]');
        if (!t) return;
        state.gfilter = state.gfilter === t.dataset.gov ? null : t.dataset.gov;
        state.q = ''; const qEl = $a('#atlas-q'); if (qEl) qEl.value = '';
        refreshAll();
        toast(state.gfilter ? '治理筛选 · ' + GF_LABEL[state.gfilter] : '已清除筛选');
      });

      canvas.addEventListener('mousemove', e => {
        const r = canvas.getBoundingClientRect();
        state.pointer.x = e.clientX - r.left;
        state.pointer.y = e.clientY - r.top;
        state.pointer.inside = true;
        const n = nearestNode(state.pointer.x, state.pointer.y);
        if (n && state.hoverId !== n.id) { state.hoverId = n.id; showTip(n, e.clientX, e.clientY); }
        else if (!n) { state.hoverId = null; showTip(null); }
        else if (n) showTip(n, e.clientX, e.clientY);
      });
      canvas.addEventListener('mouseleave', () => { state.pointer.inside = false; state.hoverId = null; showTip(null); });
      canvas.addEventListener('click', e => {
        const r = canvas.getBoundingClientRect();
        const n = nearestNode(e.clientX - r.left, e.clientY - r.top);
        if (n) selectItem(n.id); else { state.selectedId = null; renderDetail(); renderStream(); }
      });
      atlasWrap.addEventListener('mousemove', e => {
        const r = atlasWrap.getBoundingClientRect();
        state.mouse.tx = ((e.clientX - r.left) / r.width) * 2 - 1;
        state.mouse.ty = ((e.clientY - r.top) / r.height) * 2 - 1;
      });
      atlasWrap.addEventListener('mouseleave', () => { state.mouse.tx = 0; state.mouse.ty = 0; });

      document.addEventListener('keydown', e => {
        if (S.tab !== 'atlas') return;
        if (e.key === '/' && document.activeElement !== qEl) { e.preventDefault(); qEl.focus(); qEl.select(); }
        if (e.key === 'Escape') {
          if (document.activeElement === qEl || state.q) { const qEl2 = $a('#atlas-q'); if (qEl2) { qEl2.value = ''; } state.q = ''; refreshAll(); }
          else { state.selectedId = null; renderDetail(); renderStream(); }
        }
      });

      const ro = new ResizeObserver(() => resize());
      ro.observe(atlasWrap);
      window.addEventListener('resize', resize);
    }

    /* --- init --- */
    function countUp(el, target) {
      if (!el) return;
      const start = performance.now(), dur = 1200;
      const step = (now) => {
        const t = Math.min(1, (now - start) / dur);
        const e = 1 - Math.pow(1 - t, 3);
        el.textContent = fmt(Math.round(target * e));
        if (t < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }

    /* --- boot --- */
    const subEl = $a('#sub-atlas');
    if (subEl) subEl.classList.add('atlas-live');

    buildSky();
    resize();
    renderChips();
    renderScen();
    refreshAll();
    renderInjection();
    renderGov();
    renderDetail();
    renderLegend();
    countUp($a('#atlas-total'), TOTALS.all);

    const hitEl = $a('#atlas-tel-hit');
    if (hitEl && TOTALS.lessons > 0) hitEl.textContent = (TOTALS.hit / TOTALS.lessons * 100).toFixed(1) + '%';
    const wonEl = $a('#atlas-tel-won');
    if (wonEl) wonEl.textContent = fmt(TOTALS.won);
    const lostEl = $a('#atlas-tel-lost');
    if (lostEl) lostEl.textContent = fmt(TOTALS.lost);

    bind();
    animId = requestAnimationFrame(frame);

    ATLAS._stop = function() {
      if (animId) { cancelAnimationFrame(animId); animId = null; }
      const subEl = $a('#sub-atlas');
      if (subEl) subEl.classList.remove('atlas-live');
    };
  })();
};


window.loadMemoryCenter = async function () {
  const requestSeq = MEMORY_CENTER.requestSeq = (MEMORY_CENTER.requestSeq || 0) + 1;
  MEMORY_CENTER.stateSignature = memoryCenterSignature();
  const projects = $("memory-projects");
  if (projects) projects.innerHTML = '<div class="hint">' + esc(t("正在加载项目记忆…")) + '</div>';
  try {
    const data = await api("/api/memory");
    if (requestSeq !== MEMORY_CENTER.requestSeq) return;
    MEMORY_CENTER.data = data;
  } catch (e) {
    if (requestSeq !== MEMORY_CENTER.requestSeq) return;
    MEMORY_CENTER.stateSignature = "";
    MEMORY_CENTER.data = null;
    if (projects) projects.innerHTML = '<div class="hint">' + esc(e.message) + '</div>';
    return;
  }
  renderMemoryCenter();
};

function memoryStatusLabel(status) {
  return ({ pending: t("待批准"), approved: t("已批准"), archived: t("已归档"), rejected: t("已拒绝") }[status] || status || "");
}

function renderMemoryCenter() {
  const data = MEMORY_CENTER.data || {};
  const global = data.global || {};
  const skills = global.skills || {};
  const knowledge = global.knowledge || {};
  const summary = $("memory-global-cards");
  if (summary) summary.innerHTML =
    '<article class="memory-summary-card"><strong>' + esc(t("经验库")) + '</strong><b>' + Number(skills.total || skills.lessons || 0) + '</b><span>' + esc(t("跨任务复用的教训与做法")) + '</span><button class="ghost small" onclick="switchTab(\'skills\')">' + esc(t("打开经验库")) + '</button></article>' +
    '<article class="memory-summary-card"><strong>' + esc(t("知识库")) + '</strong><b>' + Number(knowledge.total || (knowledge.entries || []).length || 0) + '</b><span>' + esc(t("可复用的事实与资料")) + '</span><button class="ghost small" onclick="switchTab(\'knowledge\')">' + esc(t("打开知识库")) + '</button></article>';
  const projects = data.projects || [];
  const count = $("memory-project-count");
  if (count) count.textContent = projects.length ? projects.length + t(" 个工作区") : t("暂无");
  const box = $("memory-projects");
  if (!box) return;
  if (!projects.length) { box.innerHTML = '<div class="empty">' + esc(t("完成任务后，这里会显示按项目隔离的记忆。")) + '</div>'; return; }
  box.innerHTML = projects.map((project) => {
    const taskId = (project.task_ids || [])[0] || "";
    const entries = project.entries || [];
    const eligiblePending = entries.filter((entry) => entry.status === "pending" && !entry.expired && entry.verified).length;
    const rows = entries.map((entry) => {
      const ver = Number(entry.version || 1);
      const canApprove = entry.status === "pending" && !entry.expired && entry.verified;
      const canRestore = entry.status === "archived" && !entry.expired && entry.verified;
      const action = (name, label) => '<button type="button" class="ghost small" onclick="memoryCenterAction(\'' + jsq(taskId) + '\',\'' + jsq(entry.id) + '\',\'' + name + '\',' + ver + ')">' + esc(t(label)) + '</button>';
      return '<article class="rd-memory-row"><div><strong>' + esc(entry.title || t("项目记忆")) + '</strong><span class="chip">' + esc(memoryStatusLabel(entry.status)) + (entry.expired ? ' · ' + esc(t("已过期")) : '') + '</span></div><pre>' + esc(entry.content || "") + '</pre><div class="rd-memory-actions">' + (canApprove ? action("approve", t("批准")) + action("reject", t("拒绝")) : "") + (entry.status === "approved" ? action("archive", t("归档")) : "") + (canRestore ? action("restore", t("恢复")) : "") + (entry.status === "approved" ? action("preview", t("查看注入预览")) : "") + '</div></article>';
    }).join("");
    const bulk = eligiblePending ? '<button type="button" class="ghost small" onclick="memoryCenterAction(\'' + jsq(taskId) + '\',\'\',\'approve_all\',0)">' + esc(t("一键批准全部待批准 ({0})", eligiblePending)) + '</button>' : '';
    return '<section class="memory-project-card"><div class="memory-project-head"><div><h4>' + esc(project.name || t("项目记忆")) + '</h4><span class="hint">' + esc(t("{0} 条记忆", entries.length)) + '</span></div><div class="memory-project-actions">' + bulk + '<span class="tag">' + esc(t("按工作区隔离")) + '</span></div></div>' + (rows || '<div class="empty">' + esc(t("暂无项目记忆")) + '</div>') + '</section>';
  }).join("");
}

window.memoryCenterApproveAll = async function () {
  try {
    const data = await api("/api/memory", { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()), body: JSON.stringify({ action: "approve_all" }) });
    toast(t("已批准 {0} 条项目记忆", Number(data.approved_count || 0)), false);
    await loadMemoryCenter();
  } catch (e) { toast(t("项目记忆操作失败：") + e.message, true); }
};

window.memoryCenterAction = async function (taskId, id, action, version) {
  if (action === "approve_all") {
    try {
      const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory", { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()), body: JSON.stringify({ action: "approve_all" }) });
      toast(t("已批准 {0} 条项目记忆", Number(data.approved_count || 0)), false);
      await loadMemoryCenter();
    } catch (e) { toast(t("项目记忆操作失败：") + e.message, true); }
    return;
  }
  if (action === "preview") {
    try {
      const data = await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory/preview?cap=4000");
      const text = data.text || t("暂无可注入记忆");
      toast(text.slice(0, 240), false);
    } catch (e) { toast(t("项目记忆预览失败：") + e.message, true); }
    return;
  }
  try {
    await api("/api/tasks/" + encodeURIComponent(taskId) + "/memory", { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()), body: JSON.stringify({ id, action, expected_version: version }) });
    await loadMemoryCenter();
  } catch (e) { toast(t("项目记忆操作失败：") + e.message, true); }
};

function renderKnowledge() {
  const box = $("kb-cards");
  if (!box || !KB.data) return;
  const entries = KB.data.entries || [];
  const drafts = entries.filter((x) => (x.status || "draft") !== "approved").length;
  // 状态 chips 只在还有草稿时出现（默认直接转正后草稿是例外态，不值得常驻占位）；
  // chips 隐藏时同步清掉残留的草稿过滤态，否则列表会被看不见的过滤器扣成空
  if (KB.status === "draft" && !drafts) KB.status = "";
  const stBox = $("kb-status-chips");
  if (stBox) {
    const cnt = (s) => s ? entries.filter((x) => (x.status || "draft") === s).length : entries.length;
    stBox.innerHTML = drafts ? [["", t("全部")], ["draft", t("草稿")], ["approved", t("已转正")]].map((p) =>
      '<button class="cat-chip' + (KB.status === p[0] ? " active" : "") + '" onclick="kbSetFilter(\'status\',\'' + p[0] + '\')">' +
      esc(t(p[1])) + "<b>" + cnt(p[0]) + "</b></button>").join("") : "";
  }
  const tags = KB.data.tags || [];
  const tagBox = $("kb-tag-chips");
  if (tagBox) {
    tagBox.innerHTML = tags.length
      ? '<button class="cat-chip' + (!KB.tag ? " active" : "") + '" onclick="kbSetFilter(\'tag\',\'\')">' + esc(t("全部标签")) + "</button>" +
        tags.map((tg) => '<button class="cat-chip' + (KB.tag === tg ? " active" : "") +
          '" onclick="kbSetFilter(\'tag\',\'' + jsq(tg) + '\')">' + esc(tg) + "<b>" + (KB.data.tag_counts[tg] || 0) + "</b></button>").join("")
      : "";
  }
  let shown = entries;
  if (KB.status) shown = shown.filter((x) => (x.status || "draft") === KB.status);
  if (KB.tag) shown = shown.filter((x) => (x.tags || []).includes(KB.tag));
  if (KB.q) shown = shown.filter((x) =>
    (x.title || "").toLowerCase().includes(KB.q) || (x.body || "").toLowerCase().includes(KB.q) ||
    (x.tags || []).some((tg) => tg.toLowerCase().includes(KB.q)));
  const cnt = $("kb-count");
  if (cnt) cnt.textContent = shown.length ? shown.length + t(" / 共 ") + entries.length + t(" 条") : t("（暂无）");
  box.innerHTML = shown.map(kbCard).join("") ||
    '<div class="empty">' + t("还没有知识条目——完成一次产出型任务后自动提炼并直接转正，也可以点右上角手动新建。") + "</div>";
}

function kbCard(x) {
  const draft = (x.status || "draft") !== "approved";
  // 标题独占首行（.name 不再被标签挤成省略号）；状态徽章与可点标签合并为
  // 标题下方的单行元信息区，视觉层级：标题 > 状态/标签 > 正文 > 元信息 > 操作。
  // 默认即转正：approved 不再挂「已转正」徽章（全员都有 = 没有信息量），
  // 只把例外态「草稿」标出来（琥珀圆点）。
  const badges =
    (draft ? '<span class="tag warn"><span class="cdot"></span>' + esc(t("草稿")) + "</span>" : "") +
    (x.stale ? '<span class="tag" title="' + esc(t("事实较旧，注入时会标注可能过期")) + '">' + esc(t("可能过期")) + "</span>" : "") +
    (x.confidence === "high" ? '<span class="tag ok" title="' + esc(t("产出材料中有明确来源或数据支撑")) + '">' + esc(t("有据")) + "</span>" : "") +
    '<span class="tag">' + esc(x.scope === "*" ? t("通用") : x.scope) + "</span>" +
    (x.seen > 1 ? '<span class="tag">' + t("出现 ") + x.seen + t(" 次") + "</span>" : "") +
    ((x.merged_titles || []).length ? '<span class="tag" title="' + t("被近似题合并吸收的变体标题数") + '">' + t("吸收 ") + x.merged_titles.length + t(" 个近似题") + "</span>" : "") +
    (x.hits ? '<span class="tag">' + t("已注入 ") + x.hits + t(" 次") + "</span>" : "") +
    (x.enabled === false ? '<span class="tag">' + t("已停用") + "</span>" : "");
  const tags = (x.tags || []).map((tg) =>
    '<span class="tag kt" onclick="kbSetFilter(\'tag\',\'' + jsq(tg) + '\')" title="' + t("只看该标签") + '">' + esc(tg) + "</span>").join("");
  return '<div class="card' + (x.enabled === false ? " off" : "") + '" data-kb-id="' + esc(x.id) + '">' +
    '<div class="head">' +
    '<span class="name">' + esc(x.title) + "</span>" +
    '<span class="kb-meta">' + badges + tags + "</span></div>" +
    '<div class="note">' + esc(x.body) + "</div>" +
    '<div class="facts">' + (x.as_of ? t("事实截至 ") + esc(x.as_of) : "") +
    (x.source ? (x.as_of ? '<span class="sep">·</span>' : "") +
      '<a href="#" onclick="openRun(\'' + jsq(x.source) + '\');return false">' + t("来源运行") + "</a>" : "") + "</div>" +
    '<div class="ops">' +
    (draft ? '<button class="ghost small" onclick="kbOp(\'' + jsq(x.id) + '\', \'approve\')">' + t("转正") + "</button>" : "") +
    '<button class="ghost small" onclick="kbEditOpen(\'' + jsq(x.id) + '\')">' + t("编辑") + "</button>" +
    '<button class="ghost small" onclick="kbOp(\'' + jsq(x.id) + '\', \'' + (x.enabled === false ? "enable" : "disable") + '\')">' + (x.enabled === false ? t("启用") : t("停用")) + "</button>" +
    '<button class="danger small" onclick="kbOp(\'' + jsq(x.id) + '\', \'delete\')">' + t("删除") + "</button>" +
    "</div></div>";
}

function kbSetFilter(k, v) {
  KB[k] = v || "";
  renderKnowledge();   // 客户端过滤，无需重拉
}

function kbSearch(v) {
  KB.q = String(v || "").trim().toLowerCase();
  renderKnowledge();
}

async function kbOp(id, op) {
  if (op === "delete" && !await uiConfirm(t("删除这条知识？转正条目不再注入，删除后不可恢复。"), { ok: t("删除"), danger: true })) return;
  try { await api("/api/knowledge/op", { method: "POST", body: JSON.stringify({ id, op }) }); }
  catch (e) { toast(e.message, true); return; }
  loadKnowledge();
}

function kbFormOpen(x) {   // x 为空 = 新建（保存即转正），否则编辑（不改状态）
  const isNew = !x;
  openModal(isNew ? t("新建知识条目") : t("编辑知识条目"),
    '<div class="form">' +
    '<div class="field"><label>' + t("标题") + ' <span class="req">*</span></label><input id="kb-f-title" value="' + esc(x ? x.title || "" : "") + '"></div>' +
    '<div class="field"><label>' + t("正文") + ' <span class="req">*</span></label><textarea id="kb-f-body" rows="5">' + esc(x ? x.body || "" : "") + "</textarea></div>" +
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("标签（逗号分隔）") + '</label><input id="kb-f-tags" value="' + esc((x ? x.tags || [] : []).join(", ")) + '" placeholder="' + t("例：番茄, 签约") + '"></div>' +
    '<div class="field"><label>' + t("事实截至") + '</label><input id="kb-f-asof" value="' + esc(x ? x.as_of || "" : "") + '" placeholder="YYYY-MM-DD"></div>' +
    "</div>" +
    '<div class="field"><label>' + t("适用范围（任务类型，* 为通用）") + '</label><input id="kb-f-scope" value="' + esc(x ? x.scope || "*" : "*") + '" placeholder="novel / serial_novel / code / *"></div>' +
    "</div>",
    '<button class="ghost" onclick="closeModal()">' + t("取消") + "</button>" +
    '<button onclick="kbFormSave(' + (isNew ? "" : "'" + esc(x.id) + "'") + ')">' + t("保存") + "</button>");
}

async function kbFormSave(id) {
  const fields = {
    title: $("kb-f-title").value.trim(),
    body: $("kb-f-body").value.trim(),
    tags: $("kb-f-tags").value.split(/[,，]/).map((s) => s.trim()).filter(Boolean),
    scope: $("kb-f-scope").value.trim() || "*",
    as_of: $("kb-f-asof").value.trim(),
  };
  if (!fields.title || !fields.body) { toast(t("标题与正文不能为空"), true); return; }
  try {
    await api("/api/knowledge/op", { method: "POST", body: JSON.stringify(id
      ? { id, op: "edit", fields }
      : { op: "create", fields }) });
  } catch (e) { toast(e.message, true); return; }
  closeModal();
  loadKnowledge();
}

function kbEditOpen(id) {
  kbFormOpen((KB.data && KB.data.entries || []).find((x) => x.id === id));
}

/* ---------------------------------------------------------- 自动化（定时任务） */
/* 进页拉一次 + 每次操作后重拉 + 页面可见时每 8s 轮询（离页停表）。
 * 后端 /api/automation → {tasks, templates}；任务/模板操作走子路径。 */
let AUTO_TIMER = null;   // 自动化页轮询句柄
let SERIAL_DAILY_JOBS = [];
let SERIAL_DAILY_TASKS = [];

const AUTO_WD = [t("周一"), t("周二"), t("周三"), t("周四"), t("周五"), t("周六"), t("周日")];   // 0=周一

async function loadAutomation() {
  try {
    const r = await api("/api/automation");
    S.autoTasks = r.tasks || [];
    S.autoTpl = r.templates || [];
    SERIAL_DAILY_JOBS = r.serial_daily || [];
    SERIAL_DAILY_TASKS = r.serial_tasks || [];
  } catch (e) {
    S.autoTasks = null;
  }
  renderAutomation();
}

function startAutoPoll() {
  if (AUTO_TIMER) return;
  AUTO_TIMER = setInterval(() => {
    if (S.tab === "automation" && !document.hidden) loadAutomation();
  }, 8000);
}

function stopAutoPoll() {
  if (AUTO_TIMER) { clearInterval(AUTO_TIMER); AUTO_TIMER = null; }
}

/* kind → 中文可读节奏：「每天 09:00」「每 6 小时」「每周一 09:00」「…执行一次」 */
function autoKindText(tsk) {
  const wd = (n) => (n >= 0 && n <= 6) ? t(AUTO_WD[n]) : "";
  if (tsk.kind === "daily") return t("每天 ") + (tsk.time || "");
  if (tsk.kind === "interval") return t("每 ") + (tsk.interval_hours || 0) + t(" 小时");
  if (tsk.kind === "weekly") return t("每") + wd(tsk.weekday) + " " + (tsk.time || "");
  if (tsk.kind === "once") return (tsk.run_at || "") + t(" 执行一次");
  return t("未设置节奏");
}

/* 模板的建议节奏（复用任务节奏文案，字段带 suggested_ 前缀） */
function autoTplPace(tp) {
  return autoKindText({
    kind: tp.suggested_kind,
    time: tp.suggested_time,
    interval_hours: tp.suggested_interval_hours,
    weekday: tp.suggested_weekday != null ? tp.suggested_weekday : -1,
    run_at: tp.suggested_run_at || "",
  });
}

/* last_status → 徽章：started=正常灰、error=红「拉起失败」、missed=黄「已错过」；
 * done/failed/cancelled=运行终态（2026-09-23 回写接线后会出现，失败必须可见） */
function autoStatusTag(tsk) {
  if (tsk.last_status === "error") return '<span class="tag auto-tag-err">' + t("拉起失败") + "</span>";
  if (tsk.last_status === "missed") return '<span class="tag auto-tag-miss">' + t("已错过") + "</span>";
  if (tsk.last_status === "started" || tsk.last_status === "queued") return '<span class="tag">' + t("正常") + "</span>";
  if (tsk.last_status === "failed") return '<span class="tag auto-tag-err">' + t("上次失败") + "</span>";
  if (tsk.last_status === "cancelled") return '<span class="tag auto-tag-miss">' + t("已取消") + "</span>";
  if (tsk.last_status === "done") return '<span class="tag">' + t("已完成") + "</span>";
  return "";
}

/* 运行偏好标签：只显示「偏离默认」的那些（编排默认 auto、思考默认 standard），
 * 否则每张卡都挂两颗没有信息量的胶囊，反而盖住真正要看的节奏与流程 */
function autoPrefTags(tsk) {
  const MODE = { auto: t("自动"), fast: t("快速"), expert: t("专家"), manual: t("手动") };
  const TH = { auto: t("自动"), low: t("快速"), standard: t("标准"), high: t("深度") };
  const out = [];
  if (tsk.mode && tsk.mode !== "auto" && MODE[tsk.mode]) {
    out.push(t("编排模式") + t("：") + t(MODE[tsk.mode]));
  }
  if (tsk.thinking && tsk.thinking !== "standard" && TH[tsk.thinking]) {
    out.push(t("思考程度") + t("：") + t(TH[tsk.thinking]));
  }
  if (tsk.direct_agent) {
    const a = realCliAgents().find((x) => x.id === tsk.direct_agent) ||
      ((S.state && S.state.agents) || []).find((x) => x.id === tsk.direct_agent);
    out.push(t("执行 CLI") + t("：") + (a ? (a.label || a.id) : tsk.direct_agent));
  }
  if (tsk.direct_provider_id) {
    const p = directProviders().find((x) => x.id === tsk.direct_provider_id);
    out.push(t("对话模型") + t("：") + (p ? (p.name || p.id) : tsk.direct_provider_id) +
      "/" + (tsk.direct_model || t("随厂商推荐")));
  }
  out.push(tsk.fresh_chat ? t("每次新聊天") : t("延续上轮"));
  return out.map((s) => '<span class="tag">' + esc(s) + "</span>").join("");
}

function autoCardHtml(tsk) {
  const flow = tsk.flow ? flowById(tsk.flow) : null;
  return '<div class="card' + (tsk.enabled ? "" : " off") + '"><div class="head">' +
    '<span class="name">' + esc(tsk.name) + "</span>" +
    autoStatusTag(tsk) +
    '<label class="toggle" title="' + t("启用 / 停用") + '"><input type="checkbox"' + (tsk.enabled ? " checked" : "") +
    ' onchange="autoToggle(\'' + jsq(tsk.id) + '\', this.checked)"><span>' + (tsk.enabled ? t("启用中") : t("已停用")) + "</span></label>" +
    "</div>" +
    '<div class="auto-kind">' + esc(autoKindText(tsk)) +
    (flow ? '<span class="tag">' + t("流程：") + esc(t(flow.name)) + "</span>" : "") +
    (tsk.task_id ? '<span class="tag">' + t("会话复用") + "</span>" : "") +
    autoPrefTags(tsk) + "</div>" +
    '<div class="auto-prompt">' + esc(tsk.prompt) + "</div>" +
    '<div class="auto-meta">' +
    (tsk.enabled && tsk.next_run ? "<span>" + t("下次运行 ") + esc(tsk.next_run) + "</span>" : "") +
    "<span>" + t("已运行 ") + (tsk.run_count || 0) + t(" 次") + "</span>" +
    "</div>" +
    '<div class="ops">' +
    '<button class="primary small" onclick="autoRunNow(\'' + jsq(tsk.id) + '\')">' + t("立即执行") + "</button>" +
    '<button class="ghost small" onclick="autoEdit(\'' + jsq(tsk.id) + '\')">' + t("编辑") + "</button>" +
    '<button class="danger small" onclick="autoRemove(\'' + jsq(tsk.id) + '\')">' + t("删除") + "</button>" +
    "</div></div>";
}

/* 定时任务表单草稿：借鉴 OpenHands 1.27.0 的 automation draft 持久化，
 * 只保存在本机浏览器，不把未提交的提示词写进服务端任务列表。编辑已有
 * 任务不覆盖草稿；新建表单重新打开时恢复，成功保存后清掉。 */
const AUTO_DRAFT_KEY = "codebee.automationDraft.v1";
let autoDraftTimer = null;
let autoDraftFormToken = 0;

function readAutoDraft() {
  try {
    const raw = localStorage.getItem(AUTO_DRAFT_KEY);
    const value = raw ? JSON.parse(raw) : null;
    return value && typeof value === "object" && !Array.isArray(value) ? value : null;
  } catch (e) { return null; }
}

function clearAutoDraft() {
  if (autoDraftTimer) clearTimeout(autoDraftTimer);
  autoDraftTimer = null;
  try { localStorage.removeItem(AUTO_DRAFT_KEY); } catch (e) { /* 隐私模式等 */ }
}

function autoDraftValues() {
  const value = {
    name: ($("au-name") || {}).value || "",
    prompt: ($("au-prompt") || {}).value || "",
    workdir: ($("au-workdir") || {}).value || "",
    kind: ($("au-kind") || {}).value || "daily",
    flow: ($("au-flow") || {}).value || "",
    mode: ($("au-mode") || {}).value || "auto",
    thinking: ($("au-thinking") || {}).value || "standard",
    fresh_chat: !!(($("au-fresh") || {}).checked),
    direct_provider_id: ($("au-direct-provider") || {}).value || "",
    direct_model: ($("au-direct-model-name") || {}).value || "",
    time: ($("au-time") || {}).value || "",
    weekday: ($("au-weekday") || {}).value || "",
    interval_hours: ($("au-interval") || {}).value || "",
    run_at: ($("au-runat") || {}).value || "",
  };
  return value.name.trim() || value.prompt.trim() || value.workdir.trim()
    ? value : null;
}

function scheduleAutoDraftSave(formToken) {
  if (autoDraftTimer) clearTimeout(autoDraftTimer);
  autoDraftTimer = setTimeout(() => {
    autoDraftTimer = null;
    // 用户可能在 180ms 内关闭并打开另一个弹窗；旧表单的定时器不能读取新表单。
    if (formToken !== autoDraftFormToken || !$("au-name")) return;
    const value = autoDraftValues();
    try {
      if (value) localStorage.setItem(AUTO_DRAFT_KEY, JSON.stringify(value));
      else localStorage.removeItem(AUTO_DRAFT_KEY);
    } catch (e) { /* 隐私模式或配额不足：表单仍可正常提交 */ }
  }, 180);
}

function bindAutoDraftAutosave(formToken) {
  ["au-name", "au-prompt", "au-workdir", "au-kind", "au-flow", "au-mode",
    "au-thinking", "au-fresh", "au-direct-provider", "au-direct-model-name",
    "au-time", "au-weekday", "au-interval", "au-runat"].forEach((id) => {
    const el = $(id);
    if (el) el.addEventListener("input", () => scheduleAutoDraftSave(formToken));
    if (el) el.addEventListener("change", () => scheduleAutoDraftSave(formToken));
  });
}

function autoDiscardDraft() {
  clearAutoDraft();
  closeModal();
  toast(t("已清除未保存的定时任务草稿"));
}

function renderAutomation() {
  renderSerialDaily();
  const box = $("auto-list");
  if (!box) return;
  if (!S.autoTasks) {
    box.innerHTML = '<div class="empty">' + t("加载失败：服务未连接") + "</div>";
  } else {
    let shown = S.autoTasks;
    if (S.autoFilter === "on") shown = shown.filter((x) => x.enabled);
    if (S.autoFilter === "off") shown = shown.filter((x) => !x.enabled);
    box.innerHTML = shown.map(autoCardHtml).join("") ||
      (S.autoTasks.length ? '<div class="empty">' + t("没有符合条件任务") + "</div>"
        : '<div class="empty">' + t("还没有定时任务——点右上「新建定时任务」，或从下面的模板一键创建。") + "</div>");
  }
  const tpl = $("auto-tpl");
  if (tpl) {
    tpl.innerHTML = (S.autoTpl || []).map((tp) =>
      '<div class="card auto-tpl-card"><div class="head"><span class="name">' + esc(t(tp.name)) + "</span></div>" +
      '<div class="note">' + esc(t(tp.desc || "")) + "</div>" +
      '<div class="ops"><span class="auto-pace">' + esc(autoTplPace(tp)) + "</span>" +
      '<button class="ghost small" onclick="autoTemplate(\'' + jsq(tp.id) + '\')">' + t("用此模板") + "</button></div></div>"
    ).join("") || '<div class="empty">' + t("暂无模板") + "</div>";
  }
}

function renderSerialDaily() {
  const box = $("serial-daily-list");
  if (!box) return;
  const status = { active: t("运行中"), paused: t("已暂停"), cancelled: t("已取消") };
  box.innerHTML = (SERIAL_DAILY_JOBS || []).map((job) => {
    const result = job.last_day_status === "done" ? t("今日已完成")
      : job.last_day_status === "alerted" ? t("今日未完成，已告警") : t("今日执行中");
    const controls = job.status === "active"
      ? '<button class="ghost small" onclick="serialDailyAction(\'' + jsq(job.id) + '\',\'pause\')">' + t("暂停") + "</button>"
      : job.status === "paused"
        ? '<button class="ghost small" onclick="serialDailyAction(\'' + jsq(job.id) + '\',\'resume\')">' + t("恢复") + "</button>" : "";
    return '<div class="card"><div class="head"><span class="name">' + esc(job.task_title) + "</span>" +
      '<span class="tag">' + t(status[job.status] || job.status) + "</span></div>" +
      '<div class="auto-kind">' + t("每天") + " " + job.chapters_per_day + " " + t("章 ·") + " " +
      job.publish_time + " " + t("发布") + ' <span class="tag">' + esc(job.platform) + "</span></div>" +
      '<div class="auto-meta"><span>' + esc(result) + (job.day ? " · " + esc(job.day) : "") + "</span>" +
      (job.last_error ? '<span class="auto-tag-err">' + esc(job.last_error) + "</span>" : "") + "</div>" +
      '<div class="ops">' + controls +
      (job.status !== "cancelled" ? '<button class="danger small" onclick="serialDailyAction(\'' + jsq(job.id) + '\',\'cancel\')">' + t("取消计划") + "</button>" : "") +
      "</div></div>";
  }).join("");
}

async function serialDailyForm() {
  if (!SERIAL_DAILY_TASKS.length) { toast(t("没有可用的连载小说任务"), true); return; }
  const taskOptions = SERIAL_DAILY_TASKS.map((task) => '<option value="' + esc(task.id) + '">' +
    esc(task.title || task.goal || task.id) + "</option>").join("");
  const body = '<div class="form">' +
    '<div class="field"><label>' + t("连载任务") + '</label><select id="sd-task">' + taskOptions + "</select></div>" +
    '<div class="grid-2"><div class="field"><label>' + t("发布平台") + '</label><select id="sd-platform"><option value="fanqie">' + t("番茄") + '</option><option value="qimao">' + t("七猫") + "</option></select></div>" +
    '<div class="field"><label>' + t("每天章节数") + '</label><input id="sd-count" type="number" min="1" max="20" value="1"></div></div>' +
    '<div class="field"><label>' + t("每天发布时间") + '</label><input id="sd-time" type="time" value="21:00"></div>' +
    '<p class="hint">' + t("系统会在每天开始续写，按设定时间发布；当天未完成会持续重试并告警。") + "</p></div>";
  openModal(t("一键设置连载日更"), body, "");
  const foot = $("modal-foot");
  if (foot) foot.innerHTML = '<button class="primary" onclick="saveSerialDaily()">' + t("创建日更任务") + "</button>" +
    '<button class="ghost" onclick="closeModal()">' + t("取消") + "</button>";
}

async function saveSerialDaily() {
  const payload = { task_id: $("sd-task").value, platform: $("sd-platform").value,
    chapters_per_day: Number($("sd-count").value), publish_time: $("sd-time").value,
    auto_submit: true };
  try { await api("/api/serial-daily", { method: "POST", body: JSON.stringify(payload) }); }
  catch (e) { toast(t("创建失败：") + e.message, true); return; }
  closeModal();
  toast(t("连载日更任务已创建"));
  loadAutomation();
}

async function serialDailyAction(id, action) {
  if (action === "cancel" && !(await uiConfirm(t("取消后将停止后续写作和发布，确定取消吗？")))) return;
  try { await api("/api/serial-daily/" + encodeURIComponent(id) + "/" + action,
    { method: "POST", body: "{}" }); }
  catch (e) { toast(e.message, true); return; }
  loadAutomation();
}

/* 创建 / 编辑表单（通用弹框）：task 空 = 新建；tpl = 模板预填 */
async function autoForm(task, tpl) {
  if (!S.flows) await loadFlows();   // 流程下拉数据源（一般启动时已就绪）
  const formToken = ++autoDraftFormToken;
  const restoredDraft = !task && !tpl ? readAutoDraft() : null;
  const f = task || restoredDraft || {};
  const kind = f.kind || (tpl && tpl.suggested_kind) || "daily";
  const curFlow = f.flow || (tpl && tpl.suggested_flow) || "";
  const mode = f.mode || "auto";
  const thinking = f.thinking || "standard";
  const wdOpts = AUTO_WD.map((w, i) =>
    '<option value="' + i + '"' + (Number(f.weekday) === i || (!task && tpl && tpl.suggested_weekday === i) ? " selected" : "") + ">" + t(w) + "</option>").join("");
  const runAt = f.run_at ? String(f.run_at).replace(" ", "T").slice(0, 16) : "";
  const draftHint = restoredDraft
    ? '<p class="hint">' + t("已恢复上次未保存的定时任务草稿；保存后会自动清除。") + "</p>" : "";
  const body = '<div class="form">' + draftHint +
    '<div class="field"><label>' + t("名称") + ' <span class="req">*</span></label><input id="au-name" value="' +
      esc(f.name || (tpl ? tpl.name : "")) + '" placeholder="' + t("例：每日仓库巡检") + '"></div>' +
    '<div class="field"><label>' + t("执行内容") + ' <span class="req">*</span></label><textarea id="au-prompt" rows="5" placeholder="' +
      t("到点要完成什么，一句话或分步说明均可") + '">' + esc(f.prompt || (tpl ? tpl.prompt : "")) + "</textarea></div>" +
    '<div class="field"><label>' + t("工作目录") + '</label><input id="au-workdir" value="' + esc(f.workdir || "") +
      '" placeholder="' + t("留空 = 默认保存路径；或填绝对路径") + '"></div>' +
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("类型") + '</label><select id="au-kind">' +
      '<option value="daily"' + (kind === "daily" ? " selected" : "") + ">" + t("每天") + "</option>" +
      '<option value="interval"' + (kind === "interval" ? " selected" : "") + ">" + t("每隔 N 小时") + "</option>" +
      '<option value="weekly"' + (kind === "weekly" ? " selected" : "") + ">" + t("每周") + "</option>" +
      '<option value="once"' + (kind === "once" ? " selected" : "") + ">" + t("仅一次") + "</option>" +
      "</select></div>" +
    '<div class="field"><label>' + t("流程") + '</label><select id="au-flow">' +
      '<option value="">' + t("默认流程") + "</option>" +
      (S.flows || []).map((fl) =>
        '<option value="' + esc(fl.id) + '"' + (fl.id === curFlow ? " selected" : "") + ">" + esc(t(fl.name)) + "</option>").join("") +
      "</select></div>" +
    "</div>" +
    /* 运行偏好：与新建任务 Composer 的三颗胶囊同一套取值（编排模式/思考程度/
       对话模型），到点拉起的运行与手动建的任务完全等价 */
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("编排模式") + "</label>" +
      autoPillHtml("au-mode", AUTO_MODES, mode) + "</div>" +
    '<div class="field"><label>' + t("思考程度") + "</label>" +
      autoPillHtml("au-thinking", AUTO_THINKINGS, thinking) + "</div>" +
    "</div>" +
    /* 会话延续：默认延续上一轮（巡检/盯梢类任务能感知上次进展）；打开则每次全新 */
    '<div class="field"><label class="toggle"><input id="au-fresh" type="checkbox"' +
      (f.fresh_chat ? " checked" : "") + '> <span>' + t("每次运行时都开启新聊天") + "</span></label>" +
      '<p class="hint">' + t("默认关闭：到点运行延续同一任务上一轮的会话与成果（知道上次干到哪）；打开则每次从零开始。") + "</p></div>" +
    '<div id="au-model-field" class="field hidden"><label>' + t("对话模型（可选）") + '</label><div class="grid-2">' +
      '<select id="au-direct-provider" aria-label="' + t("对话厂商") + '"></select>' +
      '<select id="au-direct-model-name" aria-label="' + t("对话模型") + '"></select>' +
      '</div><p class="hint">' + t("只对「直接执行」类流程生效；留「自动推荐」时按系统路由挑模型。") + "</p></div>" +
    '<div class="grid-2">' +
    '<div class="field au-fld" data-k="time"><label>' + t("时间") + '</label><input id="au-time" type="time" value="' +
      esc(f.time || (tpl && tpl.suggested_time) || "09:00") + '"></div>' +
    '<div class="field au-fld hidden" data-k="interval"><label>' + t("间隔小时（1-720）") + '</label><input id="au-interval" type="number" min="1" max="720" value="' +
      (f.interval_hours || (tpl && tpl.suggested_interval_hours) || 6) + '"></div>' +
    '<div class="field au-fld hidden" data-k="weekday"><label>' + t("星期几") + '</label><select id="au-weekday">' + wdOpts + "</select></div>" +
    '<div class="field au-fld hidden" data-k="runat"><label>' + t("执行时间") + '</label><input id="au-runat" type="datetime-local" value="' + esc(runAt) + '"></div>' +
    "</div>" +
    '<p class="hint">' + t("首次到点创建任务，后续到点重复触发同一任务；错过的一次性任务不补跑。") + "</p>" +
    "</div>";
  openModal(task ? t("编辑定时任务") : t("新建定时任务"), body, "");
  const foot = $("modal-foot");
  if (foot) foot.innerHTML = '<button class="primary" onclick="saveAutoForm(\'' + jsq(task ? task.id : "") + '\')">' + t("保存") + "</button>" +
    (restoredDraft ? '<button class="ghost" onclick="autoDiscardDraft()">' + t("清除草稿") + "</button>" : "") +
    '<button class="ghost" onclick="closeModal()">' + t("取消") + "</button>";
  const kindSel = $("au-kind");
  if (kindSel) {
    kindSel.addEventListener("change", autoFormSyncKind);
    autoFormSyncKind();
  }
  ["au-mode", "au-thinking"].forEach((id) => {
    const sel = $(id);
    if (sel) sel.addEventListener("change", () => syncCmpSelFace(id));
    syncCmpSelFace(id);   // 弹框是动态插入的：选项文字要在这里同步一次
  });
  renderAuModelPicker(f.direct_provider_id || "", f.direct_model || "");
  const flowSel = $("au-flow");
  if (flowSel) {
    flowSel.addEventListener("change", autoFormSyncFlow);
    autoFormSyncFlow();
  }
  if (!task) bindAutoDraftAutosave(formToken);
}

/* 运行偏好取值（真源 = automation.py 的 MODES/THINKINGS，选项文案与 Composer 共用） */
const AUTO_MODES = [
  { v: "auto", label: t("自动（推荐）：按任务类型与风险动态决定步骤") },
  { v: "fast", label: t("快速：少步骤优先，先做确定性验收") },
  { v: "expert", label: t("专家：完整规划、多评审、失败修复与换将") },
  { v: "manual", label: t("手动：自行指定实现者与评审组") },
];
const AUTO_THINKINGS = [
  { v: "standard", label: t("标准：平衡质量与速度") },
  { v: "auto", label: t("自动：随任务难度调整") },
  { v: "low", label: t("快速：少推理、优先响应") },
  { v: "high", label: t("深度：更多推理与检查") },
];

/* 偏好胶囊：外观与 Composer 同款（透明原生 select 铺满整颗，短名由
 * syncCmpSelFace 从选中 option 文本截取——语言切换后短名跟着换） */
function autoPillHtml(id, opts, cur) {
  return '<span class="cmp-sel"><select id="' + id + '" class="cmp-sel-native" aria-label="' +
    esc(id === "au-mode" ? t("编排模式") : t("思考程度")) + '">' +
    opts.map((o) => '<option value="' + o.v + '"' + (o.v === cur ? " selected" : "") +
      ' data-i18n="' + esc(o.label) + '">' + esc(t(o.label)) + "</option>").join("") +
    '</select><span class="cmp-sel-face" id="' + id + '-face"></span>' +
    '<svg class="ico chev" aria-hidden="true"><use href="#i-chevron-r"></use></svg></span>';
}

/* 对话模型（仅 direct 流程）：复用 Composer 的厂商/模型数据源与重建规则 */
function renderAuModelPicker(pid, model) {
  const ps = $("au-direct-provider"), ms = $("au-direct-model-name");
  if (!ps || !ms) return;
  const provs = directProviders();
  const keepP = pid != null ? pid : ps.value;
  ps.innerHTML = '<option value="">' + t("自动推荐") + "</option>" + provs.map((p) =>
    '<option value="' + esc(p.id) + '">' + esc(p.name || p.id) + "</option>").join("");
  ps.value = provs.some((p) => p.id === keepP) ? keepP : "";
  const fillModels = (keepM) => {
    const p = provs.find((x) => x.id === ps.value);
    // 只列启用模型：停用的不允许在定时任务里选（运行时同样会拒）
    const names = p ? (p.models || []).filter((m) => !m.hidden && m.enabled !== false)
      .map((m) => m.name).filter(Boolean) : [];
    ms.innerHTML = '<option value="">' + t("随厂商推荐") + "</option>" + names.map((name) =>
      '<option value="' + esc(name) + '">' + esc(name) + "</option>").join("");
    ms.value = names.includes(keepM) ? keepM : "";
  };
  fillModels(model != null ? model : ms.value);
  // 换厂商 = 旧模型名多半不在新厂商名录里：回「随厂商推荐」，不留悬空值
  ps.onchange = () => fillModels("");
}

/* 流程 → 对话模型字段显隐：只有 direct 引擎流程用得上（其余流程模型由系统路由） */
function autoFormSyncFlow() {
  const flow = flowById(($("au-flow") || {}).value);
  const box = $("au-model-field");
  if (box) box.classList.toggle("hidden", !(flow && flow.engine === "direct"));
}

/* 类型 → 字段联动：daily/weekly→时间；weekly→星期几；interval→N 小时；once→未来时间 */
function autoFormSyncKind() {
  const sel = $("au-kind");
  if (!sel) return;
  const kind = sel.value;
  const show = {
    time: kind === "daily" || kind === "weekly",
    interval: kind === "interval",
    weekday: kind === "weekly",
    runat: kind === "once",
  };
  document.querySelectorAll("#modal-body .au-fld").forEach((el) =>
    el.classList.toggle("hidden", !show[el.dataset.k]));
}

async function saveAutoForm(id) {
  const name = ($("au-name").value || "").trim();
  const prompt = ($("au-prompt").value || "").trim();
  if (!name) { toast(t("请填写名称"), true); return; }
  if (!prompt) { toast(t("请填写执行内容"), true); return; }
  const kind = $("au-kind").value;
  const payload = { name, prompt, workdir: ($("au-workdir").value || "").trim(), kind, flow: $("au-flow").value };
  // 运行偏好：与 Composer 同名字段，后端 _apply_run_prefs 再归一一次
  payload.mode = $("au-mode") ? $("au-mode").value : "";
  payload.thinking = $("au-thinking") ? $("au-thinking").value : "";
  payload.fresh_chat = !!(($("au-fresh") || {}).checked);
  if (!$("au-model-field") || !$("au-model-field").classList.contains("hidden")) {
    payload.direct_provider_id = $("au-direct-provider") ? $("au-direct-provider").value : "";
    payload.direct_model = $("au-direct-model-name") ? $("au-direct-model-name").value : "";
    if (payload.direct_model && !payload.direct_provider_id) {
      toast(t("选择对话模型前请先选厂商"), true);
      return;
    }
  }
  if (kind === "daily" || kind === "weekly") payload.time = $("au-time").value;
  if (kind === "weekly") payload.weekday = parseInt($("au-weekday").value, 10);
  if (kind === "interval") payload.interval_hours = parseInt($("au-interval").value, 10) || 0;
  if (kind === "once") {
    payload.run_at = $("au-runat").value;
    if (!payload.run_at) { toast(t("请选择执行时间"), true); return; }
  }
  try {
    if (id) await api("/api/automation/" + encodeURIComponent(id), { method: "POST", body: JSON.stringify(payload) });
    else await api("/api/automation", { method: "POST", body: JSON.stringify(payload) });
  } catch (e) { toast(t("保存失败：") + e.message, true); return; }
  if (!id) clearAutoDraft();
  closeModal();
  toast(id ? t("定时任务已更新") : t("定时任务已创建，到点自动运行"));
  loadAutomation();
}

async function autoToggle(id, enabled) {
  try {
    await api("/api/automation/" + encodeURIComponent(id) + "/toggle",
      { method: "POST", body: JSON.stringify({ enabled: !!enabled }) });
  } catch (e) { toast(e.message, true); }
  loadAutomation();
}

async function autoRunNow(id) {
  const tsk = (S.autoTasks || []).find((x) => x.id === id);
  if (tsk && tsk.last_status === "error") {
    toast(t("上次拉起失败，请先检查工作目录 / 流程配置后再试"), true);
    return;
  }
  try {
    await api("/api/automation/" + encodeURIComponent(id) + "/run", { method: "POST", body: "{}" });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已开始执行，可在任务树查看新运行"));
  loadAutomation();
}

async function autoEdit(id) {
  const tsk = (S.autoTasks || []).find((x) => x.id === id);
  if (tsk) autoForm(tsk);
}

async function autoRemove(id) {
  const tsk = (S.autoTasks || []).find((x) => x.id === id);
  if (!await uiConfirm(t("删除定时任务「") + (tsk ? tsk.name : id) + t("」？已产生的运行记录不受影响。"),
      { ok: t("删除"), danger: true })) return;
  try {
    await api("/api/automation/" + encodeURIComponent(id) + "/delete", { method: "POST", body: "{}" });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已删除"));
  loadAutomation();
}

/* 模板卡 → 预填创建表单（prompt/name + suggested_kind/time/interval/flow） */
function autoTemplate(tplId) {
  const tp = (S.autoTpl || []).find((x) => x.id === tplId);
  if (tp) autoForm(null, tp);
}

/* ---------------------------------------------------------- 禅道 Bug 自动修复 */
/* /api/zentao → {config(脱敏，含 product_profiles), claims, last_scan, next_scan, last_error}。
 * 产品档案卡：结构增删走「先采集 DOM 回 S.ztProfiles → 改 → 重渲染」，保住已输入值。 */

async function loadZentao() {
  let v = null;
  try { v = await api("/api/zentao"); } catch (e) { v = null; }
  S.zentao = v;
  const cfg = (v && v.config) || {};
  const set = (id, val) => { const el = $(id); if (el) el.value = val == null ? "" : val; };
  set("zt-base-url", cfg.base_url);
  set("zt-account", cfg.account);
  const pw = $("zt-password");
  if (pw) { pw.value = ""; pw.placeholder = cfg.has_password ? t("已保存（不改就留空）") : ""; }
  const tg = (id, on) => { const el = $(id); if (el) el.checked = !!on; };
  tg("zt-triageai", cfg.triage_ai);
  tg("zt-autoresolve", cfg.auto_resolve);
  tg("zt-automerge", cfg.auto_merge);
  tg("zt-poll", cfg.poll_enabled);
  tg("zt-holiday", cfg.skip_holidays);
  set("zt-interval", cfg.interval_minutes || 5);
  S.ztProfiles = JSON.parse(JSON.stringify(cfg.product_profiles || []));
  renderZentaoProfiles();
  renderZentaoStatus();
  renderZentaoClaims();
  if (cfg.base_url && cfg.has_password) ztFetchCatalog(true);   // 静默拉清单：产品/账号就位即变下拉
}

/* ---- 产品档案：渲染与采集 ---- */

const ZT_SIDES = ["backend", "frontend"];

/* 模块字段双形态（同产品字段口径）：拉到清单 → 下拉选（#id 名称）；
 * 没拉到（连接不可用/该产品无模块）→ 保留手填 ID。已配值不在清单里也给
 * 「手填」选项，否则 select 选中态落空、采集时该路由会被当成 0 丢掉。 */
function ztModuleField(p, r) {
  const mods = (S.ztMods || {})[p.product] || [];
  const cur = r.module ? String(r.module) : "";
  if (!mods.length)
    return '<input class="zt-mr-module zt-num" placeholder="' + t("模块 ID") + '" value="' + esc(cur) + '">';
  const opts = ['<option value=""' + (cur ? "" : " selected") + " disabled>" + t("— 选模块 —") + "</option>"];
  if (cur && !mods.some((m) => String(m.id) === cur))
    opts.push('<option value="' + esc(cur) + '" selected>#' + esc(cur) + t("（手填）") + "</option>");
  for (const m of mods)
    opts.push('<option value="' + esc(m.id) + '"' + (cur === String(m.id) ? " selected" : "") + ">#" +
      esc(m.id) + " " + esc(m.name || "") + "</option>");
  return '<select class="zt-mr-module">' + opts.join("") + "</select>";
}

/* 产品字段双形态：拉到清单 → 下拉选；没拉到（连接不可用/老版无接口）→ 保留手填 ID */
function ztProductField(p) {
  const cur = p.product || "";
  const list = S.ztProducts || [];
  if (!list.length)
    return '<input class="zt-p-product zt-num" type="number" min="1" value="' + esc(cur) +
      '" placeholder="ID" title="' + t("配好连接后点「拉取清单」变下拉选择") + '">';
  const opts = [];
  if (cur && !list.some((x) => String(x.id) === String(cur)))
    opts.push('<option value="' + esc(cur) + '" selected>#' + esc(cur) + t("（手填）") + "</option>");
  opts.push('<option value=""' + (cur ? "" : " selected") + " disabled>" + t("— 选产品 —") + "</option>");
  for (const x of list) {
    const label = "#" + x.id + " " + (x.name || "") +
      (x.status && x.status !== "normal" ? t("（已关闭）") : "");
    opts.push('<option value="' + esc(x.id) + '"' +
      (String(cur) === String(x.id) ? " selected" : "") + ">" + esc(label) + "</option>");
  }
  return '<select class="zt-p-product" onchange="ztProdChanged(this)">' + opts.join("") + "</select>";
}

/* 选了产品 → 静默拉该产品的模块清单进 S.ztMods（模块路由就地变下拉） */
function ztProdChanged(el) {
  const card = el.closest(".zt-prof");
  const i = Array.from(document.querySelectorAll("#zt-profiles .zt-prof")).indexOf(card);
  if (i >= 0) ztFetchMods(i, true);
}

/* 工作目录「选择…」：复用全局 pickFolder（原生对话框→网页目录弹框回落），回填同一行的输入框 */
function ztWdPick(btn) {
  const inp = btn.closest(".zt-wd-row").querySelector(".zt-p-wd");
  window.pickFolder(inp, true);
  // 选完目录顺手拉该仓库的分支清单，基线分支变下拉可选
  const card = btn.closest(".zt-prof");
  const side = inp.dataset.side;
  if (card && side) setTimeout(() => ztRevFill(card, side), 400);
}

/* 基线分支下拉（datalist）：从仓库工作目录拉本地分支列表。
 * 复用 /api/git/info（只读探测，仅限本机）；拉不到就保持手填，不报错打扰。 */
function ztRevFill(card, side, force) {
  if (!card) return;
  const wd = (card.querySelector(".zt-p-wd") || {}).value || "";
  const rev = card.querySelector(".zt-p-rev");
  const dl = card.querySelector('datalist[data-side="' + side + '"]');
  if (!rev || !dl) return;
  if (!wd.trim()) { dl.innerHTML = ""; return; }
  if (!force && dl.options.length) return;   // 已有清单不重拉
  api("/api/git/info?workdir=" + encodeURIComponent(wd.trim()))
    .then((r) => {
      if (!r || !r.repo) return;
      dl.innerHTML = (r.branches || []).map((b) =>
        '<option value="' + esc(b) + '">').join("");
    })
    .catch(() => {});
}

function ztRepoHtml(i, side) {
  const cn = side === "backend" ? t("后端") : t("前端");
  const p = (S.ztProfiles[i] || {});
  const repo = (p.repos || {})[side] || {};
  const hint = (p.repo_hints || {})[side] || "";
  return '<label>' + cn + t("仓库·工作目录") + '</label><span class="zt-wd-row">' +
    '<input class="zt-p-wd" data-side="' + side + '" value="' + esc(repo.workdir || "") + '" placeholder="' + t("空 = 用默认保存路径") + '">' +
    '<button class="ghost small" type="button" title="' + t("浏览本机目录选择") + '" onclick="ztWdPick(this)">' + t("选择…") + "</button></span>" +
    '<label>' + cn + t("仓库·基线分支") + '</label><span class="zt-wd-row">' +
    '<input class="zt-p-rev" data-side="' + side + '" list="zt-rev-' + i + '-' + side + '" value="' + esc(repo.git_rev || "") + '" placeholder="' + t("如 main；空 = 直接改工作目录") + '" onfocus="ztRevFill(this.closest(\'.zt-prof\'), \'' + side + '\')">' +
    '<button class="ghost small" type="button" title="' + t("刷新分支列表") + '" onclick="ztRevFill(this.closest(\'.zt-prof\'), \'' + side + '\', true)">▾</button>' +
    '<datalist id="zt-rev-' + i + '-' + side + '" data-side="' + side + '"></datalist></span>' +
    '<label>' + cn + t("仓库·验证命令") + '</label><input class="zt-p-verify" data-side="' + side + '" value="' + esc(repo.verify_command || "") + '" placeholder="' + t("如 npm test；空 = 靠评审把关") + '">' +
    '<label>' + cn + t("仓库·一句话描述") + '</label><input class="zt-p-hint" data-side="' + side + '" value="' + esc(hint) + '" placeholder="' + t("给 AI 排查看，如：Vue3 管理台前端") + '">';
}

function ztProfCardHtml(p, i) {
  const ours = p.our_sides || [];
  const routes = p.module_routes || [];
  const SIDE_OPTS = [["backend", t("后端")], ["frontend", t("前端")], ["both", t("双端")], ["not_ours", t("非我方")]];
  const rows = routes.map((r, j) =>
    '<div class="zt-mr-row" data-j="' + j + '">' +
    ztModuleField(p, r) +
    '<select class="zt-mr-side">' + SIDE_OPTS.map((o) =>
      '<option value="' + o[0] + '"' + (r.side === o[0] ? " selected" : "") + ">" + t(o[1]) + "</option>").join("") + "</select>" +
    '<input class="zt-mr-account" list="zt-users" placeholder="' + t("转给谁（禅道账号，可空）") + '" value="' + esc(r.account || "") + '">' +
    '<button class="ghost small zt-mr-del" type="button" onclick="ztMrDel(' + i + "," + j + ')">' + t("删") + "</button>" +
    "</div>").join("");
  const owners = p.owners || {};
  return '<div class="card zt-prof" data-i="' + i + '"><div class="head">' +
    '<span class="name">' + t("产品") + " " + ztProductField(p) + "</span>" +
    '<button class="danger small" onclick="ztProfDel(' + i + ')">' + t("删除产品") + "</button></div>" +
    '<div class="zt-grid">' +
    '<label data-i18n="只认领指派给">只认领指派给</label><input class="zt-p-assigned" list="zt-users" value="' + esc(p.assigned_to || "") + '" placeholder="' + t("禅道账号名，空 = 不按指派过滤") + '">' +
    '<label data-i18n="严重度上限">严重度上限</label><select class="zt-p-sev">' +
    [0, 1, 2, 3, 4].map((n) => '<option value="' + n + '"' + (Number(p.severity_cap || 0) === n ? " selected" : "") + ">" +
      (n === 0 ? t("不限") : n + (n === 1 ? t("（最严重）") : "")) + "</option>").join("") + "</select>" +
    "</div>" +
    '<div class="zt-ours"><span>' + t("我方端（自动修）：") + "</span>" +
    ZT_SIDES.map((s) =>
      '<label class="toggle"><input type="checkbox" class="zt-p-ours" data-side="' + s + '"' + (ours.indexOf(s) >= 0 ? " checked" : "") + "><span>" +
      (s === "backend" ? t("后端") : t("前端")) + "</span></label>").join("") +
    '<span class="hint">' + t("都不勾 = 该产品只排查转派，不自动修") + "</span></div>" +
    '<div class="zt-grid">' + ZT_SIDES.map((s) => ztRepoHtml(i, s)).join("") + "</div>" +
    '<div class="zt-grid">' +
    '<label data-i18n="后端负责人">后端负责人</label><input class="zt-p-owner" list="zt-users" data-side="backend" value="' + esc(owners.backend || "") + '" placeholder="' + t("禅道账号，转派/升级用") + '">' +
    '<label data-i18n="前端负责人">前端负责人</label><input class="zt-p-owner" list="zt-users" data-side="frontend" value="' + esc(owners.frontend || "") + '" placeholder="' + t("禅道账号，转派/升级用") + '">' +
    '<label data-i18n="非我方转派给">非我方转派给</label><input class="zt-p-owner" list="zt-users" data-side="not_ours" value="' + esc(owners.not_ours || "") + '" placeholder="' + t("空 = 指回报告人") + '">' +
    "</div>" +
    '<div class="zt-mrs"><div class="zt-mr-head">' + t("模块路由（模块 → 端/人，排查优先级最高）") +
    '<button class="ghost small" onclick="ztFetchMods(' + i + ', false, true)">' + t("拉取模块清单") + "</button>" +
    '<button class="ghost small" onclick="ztMrAdd(' + i + ')">' + t("＋ 加路由") + "</button></div>" +
    (rows || '<div class="hint">' + t("未配路由——模块不在路由里的 Bug 走 AI 排查") + "</div>") +
    "</div></div>";
}

function renderZentaoProfiles() {
  const box = $("zt-profiles");
  if (!box) return;
  box.innerHTML = (S.ztProfiles || []).map((p, i) => ztProfCardHtml(p, i)).join("") ||
    '<div class="empty">' + t("还没有产品档案——先测试连接，再从禅道选择产品，无需自己查 ID。") + "</div>";
}

/* DOM 卡片 → profiles 数组（结构变化前采集，保住已输入值） */
function ztHarvestProfiles() {
  return Array.from(document.querySelectorAll("#zt-profiles .zt-prof")).map((card) => {
    const gv = (sel) => { const el = card.querySelector(sel); return el ? (el.value || "").trim() : ""; };
    const routes = Array.from(card.querySelectorAll(".zt-mr-row")).map((row) => ({
      module: parseInt((row.querySelector(".zt-mr-module").value || ""), 10) || 0,
      side: row.querySelector(".zt-mr-side").value,
      account: (row.querySelector(".zt-mr-account").value || "").trim(),
    })).filter((r) => r.module > 0);
    return {
      product: parseInt(gv(".zt-p-product"), 10) || 0,
      assigned_to: gv(".zt-p-assigned"),
      severity_cap: parseInt(gv(".zt-p-sev"), 10) || 0,
      our_sides: Array.from(card.querySelectorAll(".zt-p-ours:checked")).map((el) => el.dataset.side),
      repos: {
        backend: { workdir: gv('.zt-p-wd[data-side="backend"]'), git_rev: gv('.zt-p-rev[data-side="backend"]'), verify_command: gv('.zt-p-verify[data-side="backend"]') },
        frontend: { workdir: gv('.zt-p-wd[data-side="frontend"]'), git_rev: gv('.zt-p-rev[data-side="frontend"]'), verify_command: gv('.zt-p-verify[data-side="frontend"]') },
      },
      repo_hints: {
        backend: gv('.zt-p-hint[data-side="backend"]'),
        frontend: gv('.zt-p-hint[data-side="frontend"]'),
      },
      owners: {
        backend: gv('.zt-p-owner[data-side="backend"]'),
        frontend: gv('.zt-p-owner[data-side="frontend"]'),
        not_ours: gv('.zt-p-owner[data-side="not_ours"]'),
      },
      module_routes: routes,
    };
  });
}

async function ztProfAdd() {
  S.ztProfiles = ztHarvestProfiles();
  // 新档案必须来自禅道产品清单。先拉清单，再自动选第一个尚未配置的产品，
  // 避免生成 product=0 的空卡，用户随后保存才看到“缺产品 ID”。
  if (!(S.ztProducts || []).length) {
    if (!($("zt-base-url") && $("zt-base-url").value.trim())) {
      toast(t("请先测试并保存禅道连接，再添加产品"), true);
      return;
    }
    await ztFetchCatalog(false);
    S.ztProfiles = ztHarvestProfiles();
  }
  const used = new Set(S.ztProfiles.map((p) => String(p.product || "")));
  const next = (S.ztProducts || []).find((p) => p.id && !used.has(String(p.id)));
  if (!next) {
    toast(t((S.ztProducts || []).length ? t("禅道产品均已添加") : t("未拉到可用产品，请先测试连接")), true);
    return;
  }
  S.ztProfiles.push({ product: Number(next.id), assigned_to: "", severity_cap: 0, our_sides: ["backend"],
    repos: { backend: {}, frontend: {} }, repo_hints: { backend: "", frontend: "" },
    owners: { backend: "", frontend: "", not_ours: "" }, module_routes: [] });
  renderZentaoProfiles();
  ztFetchMods(S.ztProfiles.length - 1, true);
}

function ztProfDel(i) {
  S.ztProfiles = ztHarvestProfiles();
  S.ztProfiles.splice(i, 1);
  renderZentaoProfiles();
}

function ztMrAdd(i) {
  S.ztProfiles = ztHarvestProfiles();
  (S.ztProfiles[i].module_routes = S.ztProfiles[i].module_routes || []).push({ module: "", side: "backend", account: "" });
  renderZentaoProfiles();
}

function ztMrDel(i, j) {
  S.ztProfiles = ztHarvestProfiles();
  S.ztProfiles[i].module_routes.splice(j, 1);
  renderZentaoProfiles();
}

/* 拉产品模块清单 → S.ztMods[产品ID]（重画后模块 ID 变下拉）。
 * S.ztModsAsked 每产品只自动拉一次（失败不重试，免得每次重画都打一趟）；
 * 「拉取模块清单」按钮 force=true 绕过去，手动可反复刷新。
 * silent=自动补拉（静默无busy）；重画前先采集，保住未保存输入。 */
async function ztFetchMods(i, silent, force) {
  const card = $("zt-profiles").querySelectorAll(".zt-prof")[i];
  const pidEl = card && card.querySelector(".zt-p-product");
  const pid = parseInt((pidEl && pidEl.value) || "", 10);
  if (!pid) {
    if (!silent) toast(t("先选产品再拉模块清单"), true);
    return;
  }
  S.ztModsAsked = S.ztModsAsked || {};
  if (S.ztModsAsked[pid] && !force) return;
  S.ztModsAsked[pid] = true;
  let r;
  try {
    r = await api("/api/zentao/modules", { method: "POST", body: JSON.stringify({ product: pid }),
      silent: !!silent, busy: !silent });
  } catch (e) { if (!silent) toast(e.message, true); return; }
  if (!r.ok) { if (!silent) toast(r.error || t("拉取失败"), true); return; }
  const mods = r.modules || [];
  if (!mods.length) { if (!silent) toast(t("该产品没有模块清单"), true); return; }
  S.ztMods = S.ztMods || {};
  S.ztMods[pid] = mods;
  S.ztProfiles = ztHarvestProfiles();
  renderZentaoProfiles();
  if (!silent) toast(t("模块清单已拉到 ") + mods.length + t(" 条，模块 ID 已变下拉选择"));
}

/* 拉产品/账号清单：产品 ID 变下拉，负责人/转派账号挂 datalist。silent=进页自动拉 */
async function ztFetchCatalog(silent) {
  // 后台拉清单：静默（不画顶部滑动线、不挂按钮转圈）+ 前端 45s 超时——
  // 禅道内网不可达时此前会挂住页面加载指示十几二十秒（用户实测反馈）
  const grab = (url) => api(url, { method: "POST", body: "{}",
    timeout: 45000, busy: false, silent: true })
    .catch((e) => ({ ok: false, error: e.message }));
  const [pr, ur] = await Promise.all([grab("/api/zentao/products"), grab("/api/zentao/users")]);
  if (pr && pr.ok) S.ztProducts = pr.products || [];
  if (ur && ur.ok) S.ztUsers = ur.users || [];
  const dl = $("zt-users");
  if (dl) dl.innerHTML = (S.ztUsers || []).map((u) =>
    '<option value="' + esc(u.account) + '">' + esc(u.realname || "") + "</option>").join("");
  const prodOk = pr && pr.ok && (pr.products || []).length > 0;
  if (prodOk) {           // 产品下拉就位（先采集已填值再重渲染）
    S.ztProfiles = ztHarvestProfiles();
    renderZentaoProfiles();
    // 各产品模块清单静默补拉（每产品一次）：有清单的档案，模块 ID 路由行就地变下拉
    (S.ztProfiles || []).forEach((p, i) => {
      if (parseInt(p.product, 10) > 0 && !((S.ztMods || {})[p.product])) ztFetchMods(i, true);
    });
  }
  if (silent) return;
  const got = [];
  if (prodOk) got.push((pr.products || []).length + t(" 个产品"));
  if (ur && ur.ok) got.push((ur.users || []).length + t(" 个账号"));
  if (got.length) toast(t("已拉到 ") + got.join(t("、")) + t("，产品/负责人已是下拉选择"));
  else toast((pr && pr.error) || (ur && ur.error) || t("拉取失败——先「测试连接」确认可用"), true);
}

/* ---------------------------------------------------------- 钩子（任务生命周期） */
/* 设置 → 钩子：task_start / message_submit / run_end 三事件挂本机命令。
 * stdin 收 JSON、stdout 回 {"inject"} 或纯文本即注入；失败超时静默跳过。 */
function loadHooksPanel() {
  api("/api/hooks").then((d) => {
    S.hooks = d.hooks || [];
    S.hookEvents = d.events || [];
    S.hookDiagnostics = d.diagnostics || {};
    renderHooks();
  }).catch((e) => toast(t("加载失败：") + (e.message || e), true));
}

function renderHooks() {
  const box = $("hooks-list"), empty = $("hooks-empty");
  if (!box) return;
  const list = S.hooks || [];
  if (empty) empty.classList.toggle("hidden", list.length > 0);
  const evLabel = { task_start: t("任务开始"), message_submit: t("消息送达"), run_end: t("运行结束") };
  box.innerHTML = list.map((h, i) => {
    const diagnostic = hookDiagnosticHtml(h, S.hookDiagnostics);
    return '<div class="card hook-card" data-i="' + i + '">' +
      '<div class="hook-row">' +
      '<input class="hook-name" value="' + esc(h.name || "") + '" placeholder="' + esc(t("钩子名称")) + '" data-hf="name">' +
      '<select class="hook-event" data-hf="event">' +
      ["task_start", "message_submit", "run_end"].map((ev) =>
        '<option value="' + ev + '"' + (h.event === ev ? " selected" : "") + ">" +
        esc(evLabel[ev]) + "</option>").join("") +
      "</select>" +
      "</div>" +
      '<input class="hook-cmd mono" value="' + esc(h.cmd || "") + '" placeholder="' +
      esc(t('命令：python D:\\proj\\hook.py（stdin 收 JSON，stdout 回 {"inject":"文本"}）')) + '" data-hf="cmd">' +
      '<div class="hook-row hook-foot">' +
      '<label class="switch" title="' + esc(t("启用")) + '"><input type="checkbox" data-hf="enabled"' +
      (h.enabled ? " checked" : "") + '><span></span><em>' + esc(t("启用")) + '</em></label>' +
      '<span class="hook-foot-lab">' + esc(t("超时（秒）")) + '</span>' +
      '<input class="hook-timeout" type="number" min="1" max="120" value="' + Number(h.timeout_s || 10) + '" data-hf="timeout_s">' +
      '<button type="button" class="ghost small" data-hook-test="' + i + '">' + t("测试") + "</button>" +
      '<button type="button" class="ghost small" onclick="removeHook(' + i + ')">' + t("删除") + "</button>" +
      '<span class="hint hook-test-out">' + diagnostic + '</span>' +
      "</div></div>";
  }).join("");
}

window.removeHook = function (i) {
  (S.hooks || []).splice(i, 1);
  renderHooks();
};

function hookDiagnosticHtml(hook, diagnostics) {
  const match = row => row.hook_id === hook.id && row.event === hook.event;
  const recent = ((diagnostics || {}).recent || []).find(match);
  const failure = ((diagnostics || {}).last_errors || []).find(match);
  const labels = { succeeded: t("成功"), failed: t("执行失败"), timeout: t("超时"),
    spawn_failed: t("启动失败"), invalid_command: t("命令无效") };
  return (recent ? esc(t("最近调用：") + t(labels[recent.status] || recent.status) +
    " · " + recent.duration_ms + " ms" + (recent.exit_code != null ? " · exit " + recent.exit_code : "")) : "") +
    (failure ? '<br><span class="warn">' + esc(t("最近错误：") + (failure.error || t(labels[failure.status] || failure.status))) + '</span>' : "");
}

function hookHarvest() {
  return Array.from(document.querySelectorAll("#hooks-list .hook-card")).map((card) => {
    const gv = (f) => card.querySelector('[data-hf="' + f + '"]');
    return { id: (S.hooks || [])[Number(card.dataset.i)]?.id || "",
      name: gv("name").value.trim(), event: gv("event").value,
      cmd: gv("cmd").value.trim(), enabled: gv("enabled").checked,
      timeout_s: Number(gv("timeout_s").value || 10) };
  });
}

function bindHooksPanel() {
  if ($("btn-hooks-add").dataset.bound) return;
  $("btn-hooks-add").dataset.bound = "1";
  $("btn-hooks-add").addEventListener("click", () => {
    S.hooks = S.hooks || [];
    S.hooks.push({ id: "hk-" + Date.now(), name: "", event: "task_start",
      cmd: "", enabled: true, timeout_s: 10 });
    renderHooks();
  });
  $("btn-hooks-save").addEventListener("click", async () => {
    try {
      const r = await api("/api/hooks/save", { method: "POST",
        body: JSON.stringify({ hooks: hookHarvest() }) });
      S.hooks = r.hooks || [];
      renderHooks();
      toast(t("钩子已保存"));
    } catch (e) { toast(t("保存失败：") + (e.message || e), true); }
  });
  $("hooks-list").addEventListener("click", async (e) => {
    const btn = e.target.closest("[data-hook-test]");
    if (!btn) return;
    const card = btn.closest(".hook-card");
    const gv = (f) => card.querySelector('[data-hf="' + f + '"]');
    const out = card.querySelector(".hook-test-out");
    btn.disabled = true;
    out.textContent = t("运行中…");
    try {
      const r = await api("/api/hooks/test", { method: "POST",
        body: JSON.stringify({ cmd: gv("cmd").value.trim(), event: gv("event").value,
          timeout_s: Number(gv("timeout_s").value || 10) }) });
      out.textContent = (r.ok ? "✓ " : "✗ ") + String(r.output || "").slice(0, 120);
    } catch (e2) { out.textContent = "✗ " + (e2.message || e2); }
    btn.disabled = false;
  });
}
bindHooksPanel();

/* ---- 状态行 / 修复记录 ---- */

function zentaoStateTag(st) {
  const MAP = {
    fixing: [t("修复中"), "zt-tag-fix"],
    retry: [t("待重试"), "zt-tag-warn"],
    resolved: [t("已解决"), "zt-tag-ok"],
    transferred: [t("已转派"), "zt-tag-fix"],
    escalated: [t("已升级转派"), "zt-tag-warn"],
    merge_failed: [t("合并失败"), "zt-tag-warn"],
    commented: [t("已评论留人工"), "zt-tag-warn"],
    resolve_failed: [t("回写失败"), "zt-tag-warn"],
    done_manual: [t("待人工确认"), "zt-tag-warn"],
    need_manual: [t("需人工"), "zt-tag-warn"],
    failed: [t("修复失败"), "zt-tag-err"],
    lost: [t("记录丢失"), "zt-tag-err"],
  };
  const m = MAP[st] || [st || "?", ""];
  return '<span class="tag ' + m[1] + '">' + t(m[0]) + "</span>";
}

function zentaoTriText(c) {
  const tri = c.triage || {};
  if (!tri.side) return "";
  const NAME = { backend: t("后端问题"), frontend: t("前端问题"), both: t("双端问题"), not_ours: t("非我方"), unknown: t("待人工") };
  const by = tri.by === "rule" ? t("模块路由") : tri.by === "ai" ? "AI" : "";
  return t("排查：") + t(NAME[tri.side] || tri.side) + (by ? "（" + by + "）" : "");
}

/* 扫描间隔（分钟）→ 人类可读：整小时显示「2 小时」，否则「5 分钟」 */
function ztIntervalText(mins) {
  const n = Math.max(1, parseInt(mins, 10) || 5);
  if (n % 60 === 0) return (n / 60) + t(" 小时一次");
  return n + t(" 分钟一次");
}

function renderZentaoStatus() {
  const box = $("zentao-status");
  if (!box) return;
  const v = S.zentao;
  if (!v) { box.innerHTML = t("加载失败：服务未连接"); return; }
  const cfg = v.config || {};
  const parts = [];
  parts.push(cfg.poll_enabled
    ? (t("定时扫描已开启，每 ") + ztIntervalText(cfg.interval_minutes)
       + (cfg.skip_holidays ? t("，法定休假日自动顺延") : "")
       + (v.next_scan ? t("，下次 ") + esc(v.next_scan) : ""))
    : t("定时扫描未开启（仍可手动「立即扫描」）"));
  if (v.last_scan) parts.push(t("上次扫描 ") + esc(v.last_scan));
  box.innerHTML = parts.map(esc).join(" · ") +
    (v.last_error ? '<span class="zt-err">' + t("最近错误：") + esc(v.last_error) + "</span>" : "");
}

/* bug 详情页地址：后端回传探测出的 web 根（含 /zentao 子路径）与路由形态
   bug_style。默认伪静态 bug-view-N.html（官方默认；2026-09-23 真机实证
   伪静态部署对 GET 式链接不路由），探到 GET 形态部署才回退查询串形态。 */
function zentaoBugUrl(c) {
  const z = S.zentao || {};
  const base = String(z.bug_base || "").replace(/\/+$/, "");
  if (!base || !c.bug_id) return "";
  if (z.bug_style === "get")
    return base + "/index.php?m=bug&f=view&bugID=" + encodeURIComponent(c.bug_id);
  return base + "/bug-view-" + encodeURIComponent(c.bug_id) + ".html";
}

let ztArchivedOpen = false;   // 已归档区默认收起（会话内记忆，不落 localStorage）

function zentaoToggleArchive() {
  ztArchivedOpen = !ztArchivedOpen;
  renderZentaoClaims();
}

/* 归档 / 取消归档：后端改 claim 字段后整页重拉（记录少，不划算做乐观更新） */
async function zentaoArchiveClaim(bugId, archived) {
  try {
    await api("/api/zentao/claims/archive", { method: "POST",
      body: JSON.stringify({ bug_id: bugId, archived: archived }) });
    await loadZentao();
  } catch (e) { toast((e && e.message) || String(e), true); }
}

/* 立即处理：不等下轮扫描，手工重触发失败/留人工的修复（后端按状态分流） */
async function zentaoRetryClaim(bugId) {
  try {
    const r = await api("/api/zentao/claims/retry", { method: "POST",
      body: JSON.stringify({ bug_id: bugId }) });
    toast((r && r.message) || t("已重新触发处理"));
    await loadZentao();
  } catch (e) { toast((e && e.message) || String(e), true); }
}

/* 这些状态的记录可以「立即处理」（fixing/resolved/transferred/done_manual 不行） */
const ZT_RETRYABLE = { retry: 1, failed: 1, escalated: 1, commented: 1,
  need_manual: 1, merge_failed: 1, resolve_failed: 1, lost: 1 };

function zentaoClaimCard(c, archived) {
  const tasks = (c.tasks || []).map((tk) =>
    "<span>" + t("【") + (tk.side === "frontend" ? t("前端") : t("后端")) + t("】") +
    '<a href="#" onclick="zentaoOpenRun(\'' + jsq(tk.run_id || "") + '\');return false;">' + esc(tk.task_id || "?") + "</a></span>").join("");
  const bugUrl = zentaoBugUrl(c);
  const name = "#" + esc(c.bug_id) + " " + esc(c.title || "");
  const headName = bugUrl
    ? '<a class="zt-bug-link" href="' + esc(bugUrl) + '" target="_blank" rel="noopener" title="' +
      esc(t("在禅道中打开 Bug 详情")) + '">' + name + "</a>"
    : name;
  const retryBtn = (!archived && ZT_RETRYABLE[c.state])
    ? '<button class="ghost small" title="' + esc(t("不等下轮扫描，立即重新触发修复")) +
      '" onclick="zentaoRetryClaim(\'' + jsq(c.bug_id) + '\')">' + t("立即处理") + "</button>"
    : "";
  const act = archived
    ? '<button class="ghost small" onclick="zentaoArchiveClaim(\'' + jsq(c.bug_id) + '\',false)">' + t("取消归档") + "</button>"
    : '<button class="ghost small" title="' + esc(t("移入已归档区，不再出现在进行中列表")) + '" onclick="zentaoArchiveClaim(\'' + jsq(c.bug_id) + '\',true)">' + t("归档") + "</button>";
  return '<div class="card' + (archived ? " zt-archived" : "") + '"><div class="head"><span class="name">' + headName + "</span>" +
    zentaoStateTag(c.state) + retryBtn + act + "</div>" +
    '<div class="auto-meta">' +
    (zentaoTriText(c) ? "<span>" + esc(zentaoTriText(c)) + "</span>" : "") +
    (tasks || "") +
    (c.claimed_at ? "<span>" + t("认领于 ") + esc(c.claimed_at) + "</span>" : "") +
    "</div>" +
    (archived && c.archive_reason ? '<div class="note">' + t("归档：") + esc(c.archive_reason) +
      (c.archived_at ? " · " + esc(c.archived_at) : "") + "</div>" : "") +
    (c.note ? '<div class="note">' + esc(c.note) + "</div>" : "") +
    "</div>";
}

function renderZentaoClaims() {
  const box = $("zentao-claims");
  if (!box) return;
  const claims = (S.zentao && S.zentao.claims) || [];
  const live = claims.filter((c) => !c.archived);
  const done = claims.filter((c) => c.archived);
  let html = live.map((c) => zentaoClaimCard(c, false)).join("");
  if (!claims.length)
    html = '<div class="empty">' + t("还没有认领过 Bug——配置好连接与产品档案后点「立即扫描」。") + "</div>";
  if (done.length) {
    html += '<button class="zt-arch-head' + (ztArchivedOpen ? " open" : "") +
      '" onclick="zentaoToggleArchive()">' +
      '<svg class="ico" aria-hidden="true"><use href="#i-chevron-r"></use></svg>' +
      t("已归档") + '<span class="tag">' + done.length + "</span></button>";
    if (ztArchivedOpen)
      html += '<div class="zt-arch-list">' + done.map((c) => zentaoClaimCard(c, true)).join("") + "</div>";
  }
  box.innerHTML = html;
}

function zentaoOpenRun(runId) {
  if (runId) { openRun(runId); return; }
  switchTab("tasks");
}

/* 表单 → 保存配置。password 只在用户输入了才提交（空 = 保持已存密码）。 */
function ztFormPayload() {
  const val = (id) => (($(id).value || "").trim());
  const payload = {
    base_url: val("zt-base-url"),
    account: val("zt-account"),
    product_profiles: ztHarvestProfiles(),
    triage_ai: $("zt-triageai").checked,
    auto_resolve: $("zt-autoresolve").checked,
    auto_merge: $("zt-automerge").checked,
    poll_enabled: $("zt-poll").checked,
    skip_holidays: $("zt-holiday").checked,
    interval_minutes: Math.max(5, parseInt($("zt-interval").value, 10) || 5),
  };
  const pw = ($("zt-password").value || "").trim();
  if (pw) payload.password = pw;
  return payload;
}

async function saveZentao() {
  const payload = ztFormPayload();
  if ((payload.product_profiles || []).some((p) => !p.product)) {
    toast(t("请选择禅道产品后再保存"), true);
    const empty = Array.from(document.querySelectorAll("#zt-profiles .zt-p-product"))
      .find((el) => !parseInt(el.value || "", 10));
    if (empty) empty.focus();
    return;
  }
  try {
    await api("/api/zentao/config", { method: "POST", body: JSON.stringify(payload) });
  } catch (e) { toast(t("保存失败：") + e.message, true); return; }
  toast(t("禅道配置已保存"));
  loadZentao();
}

async function testZentao() {
  const val = (id) => (($(id).value || "").trim());
  const body = { base_url: val("zt-base-url"), account: val("zt-account") };
  const pw = ($("zt-password").value || "").trim();
  if (pw) body.password = pw;
  let r;
  try {
    r = await api("/api/zentao/test", { method: "POST", body: JSON.stringify(body) });
  } catch (e) { toast(e.message, true); return; }
  toast(r.message || (r.ok ? t("连接成功") : t("连接失败")), !r.ok);
  if (r.ok && r.base_url) {          // 子路径部署被自动补全：回填输入框提醒保存
    const inp = $("zt-base-url");
    const cur = (inp.value || "").trim().replace(/\/+$/, "");
    if (inp && r.base_url !== cur) {
      inp.value = r.base_url;
      toast(t("地址已自动补全子路径，记得「保存配置」"));
    }
  }
  if (r.ok) {
    // 测试成功即保存当前连接；产品/账号清单后台拉（真机禅道慢，await 会把
    // 确认按钮按住几十秒——「保存为啥要这么久」根因），拉到后下拉自动就位。
    api("/api/zentao/config", { method: "POST", operation: false,
      body: JSON.stringify(ztFormPayload()) })
      .then(() => loadZentao())
      .catch(() => {});
    toast(t("连接成功，已保存；正在拉取产品清单…"));
    ztFetchCatalog(true).catch(() => {});
  }
}

async function scanZentao() {
  let r;
  try {
    r = await api("/api/zentao/scan", { method: "POST", body: "{}" });
  } catch (e) { toast(e.message, true); return; }
  if (r.error) toast(r.error, true);
  else toast(t("扫描完成，新认领 ") + (r.claimed || 0) + t(" 个 Bug"));
  loadZentao();
}

/* ---------------------------------------------------------- 插件市场 */
/* /api/market → {catalog, categories(闭集)}；搜索/分类/状态全在本地过滤。
 * 外部目录（/api/market/remote）只读缓存不联网；联网拉取仅在用户点「拉取更新」。 */
async function loadMarket() {
  loadPlugins();
  try { S.market = await api("/api/market"); }
  catch (e) { S.market = null; }
  if (mkActiveView() === "remote") {
    await mkrLoadPage(true);   // 外部视图：按当前过滤条件重拉第一页（装/卸后状态翻牌）
  } else {
    S.mkrAll = null;           // 本地视图进市场：外部数据进视图时再拉（mkSetView 触发）
    S.marketRemote = null;
  }
  renderMarket();
  renderMarketRemote();
}

/* ---------------------------------------------------------- 本地插件（manifest） */
async function loadPlugins() {
  try { S.plugins = await api("/api/plugins"); }
  catch (e) { S.plugins = null; }
  renderPlugins();
}

function pluginCardHtml(p) {
  const title = p.display_name || p.name || p.id || "";
  const state = p.state || (p.installed ? (p.enabled ? "enabled" : "disabled") : "available");
  let ops = "";
  if (state === "blocked" || state === "broken") {
    ops = '<span class="tag warn">' + esc(t(state === "blocked" ? "不适配" : t("损坏"))) + "</span>";
  } else if (p.installed) {
    ops = '<label class="switch" title="' + esc(p.enabled ? t("已启用") : t("已停用")) + '">' +
      '<input type="checkbox"' + (p.enabled ? " checked" : "") +
      ' onchange="pluginToggle(\'' + jsq(p.id) + '\', this.checked)"></label>' +
      '<button class="ghost small" onclick="pluginUpdate(\'' + jsq(p.id) + '\')">' + t("更新") + "</button>" +
      '<button class="ghost small" onclick="pluginRemove(\'' + jsq(p.id) + '\')">' + t("卸载") + "</button>";
  } else {
    ops = '<button class="primary small" onclick="pluginInstall(\'' + jsq(p.id) + '\')">' + t("安装") + "</button>";
  }
  const caps = (p.capabilities || []).map((x) => '<span class="tag">' + esc(x) + "</span>").join("");
  const features = [
    p.skill_count ? t("技能 ") + p.skill_count : "",
    p.has_mcp ? "MCP" : "",
    p.version ? "v" + p.version : "",
  ].filter(Boolean).join(" · ");
  return '<div class="card mk-card plugin-card"><div class="head">' +
    '<span class="name">' + esc(t(title)) + "</span>" +
    '<span class="tag">' + esc(t(p.category || "Productivity")) + "</span></div>" +
    '<div class="note">' + esc(t(p.short_description || p.description || p.error || "")) + "</div>" +
    (p.compatibility && !p.compatibility.compatible ? '<div class="note warn">' +
      esc(p.compatibility.reason || t("宿主版本不兼容")) + '</div>' : "") +
    '<div class="mk-meta"><span>' + esc(features) + '</span><span>' + esc(p.author || "") + "</span></div>" +
    (caps ? '<div class="mk-meta">' + caps + "</div>" : "") +
    '<div class="ops">' + ops + "</div></div>";
}

function renderPlugins() {
  const grid = $("plugin-grid");
  if (!grid) return;
  const data = S.plugins;
  if (!data) { grid.innerHTML = '<div class="empty">' + t("插件加载失败") + "</div>"; return; }
  const count = $("plugin-count");
  if (count) count.textContent = data.total || 0;
  grid.innerHTML = (data.plugins || []).map(pluginCardHtml).join("") ||
    '<div class="empty">' + t("还没有发现本地插件") + "</div>";
}

async function pluginInstall(id) {
  try {
    const r = await api("/api/plugins/" + encodeURIComponent(id) + "/install", { method: "POST", body: "{}" });
    toast(r && r.already ? t("该插件已安装过") : t("插件安装成功"));
  } catch (e) { toast(e.message || t("安装失败"), true); return; }
  await loadPlugins();
  loadMarket();
}

async function pluginToggle(id, enabled) {
  try {
    await api("/api/plugins/" + encodeURIComponent(id) + "/" + (enabled ? "enable" : "disable"), { method: "POST", body: "{}" });
    toast(enabled ? t("插件已启用") : t("插件已停用"));
  } catch (e) { toast(e.message || t("操作失败"), true); }
  loadPlugins();
}

async function pluginUpdate(id) {
  try {
    const result = await api("/api/plugins/" + encodeURIComponent(id) + "/update", { method: "POST", body: "{}" });
    toast(result.cleanup_error ? t("插件已更新，旧技能清理失败：") + result.cleanup_error : t("插件已更新，启停状态已保留"), !!result.cleanup_error);
  } catch (e) { toast(e.message || t("更新失败"), true); }
  await loadPlugins();
  loadMarket();
}

async function pluginRemove(id) {
  if (!await uiConfirm(t("卸载该插件？技能包和本地插件副本会被移除。"), { ok: t("卸载"), danger: true })) return;
  try {
    await api("/api/plugins/" + encodeURIComponent(id) + "/remove", { method: "POST", body: "{}" });
    toast(t("插件已卸载"));
  } catch (e) { toast(e.message || t("卸载失败"), true); return; }
  await loadPlugins();
  loadMarket();
}

function mkCount(text) {
  const el = $("mk-count");
  if (el) el.textContent = text || "";
}

function mkScopeText(scopes) {
  const list = scopes || [];
  if (!list.length || list.indexOf("*") >= 0) return t("全部流程");
  return list.map((s) => { const f = flowById(s); return f ? t(f.name) : s; }).join(" / ");
}

/* 体量：「约 1.7k 字」；千字以下原样数字 */
function mkCharsText(n) {
  n = Number(n) || 0;
  if (n >= 1000) return t("约 ") + (n / 1000).toFixed(1).replace(/\.0$/, "") + "k " + t("字");
  return t("约 ") + n + " " + t("字");
}

function mkCardHtml(p, section) {
  let ops;
  if (p.builtin) ops = '<button class="ghost small" disabled>' + t("已内置") + "</button>";
  else if (p.installed) ops = '<span class="tag ok">' + t("已安装") + "</span>" +
    '<button class="ghost small" onclick="mkRemove(\'' + jsq(p.id) + '\')">' + t("卸载") + "</button>";
  else ops = '<button class="primary small" onclick="mkInstall(\'' + jsq(p.id) + '\')">' + t("安装") + "</button>";
  // 已装插件卡片直接给启停开关（对齐 ZCode 插件管理形态：启停不用去经验库翻）。
  // 注意传 pack_id（user-哈希）而非市场 id——启停记账在 skills 用户包上
  const toggle = p.installed
    ? '<label class="switch" title="' + (p.enabled ? t("已启用") : t("已停用")) + '">' +
      '<input type="checkbox"' + (p.enabled ? " checked" : "") +
      ' onchange="mkTogglePack(\'' + jsq(p.pack_id || p.id) + '\', this.checked)"></label>'
    : "";
  const sec = section ? '<span class="tag mk-sec">' + esc(section) + "</span>" : "";
  return '<div class="card mk-card"><div class="head">' +
    '<span class="name">' + esc(t(p.name)) + "</span>" +
    '<span class="tag">' + esc(t(p.category || "")) + "</span>" + sec +
    "</div>" +
    '<div class="note">' + esc(t(p.desc || "")) + "</div>" +
    '<div class="mk-meta"><span title="' + esc(t("运行该类型任务时自动注入提示词，无需手动调用")) + '">' + t("适用：") + esc(mkScopeText(p.scopes)) + "</span><span>" + esc(mkCharsText(p.chars)) + "</span></div>" +
    '<div class="ops">' + ops + toggle + "</div></div>";
}

/* 已装插件启停：走经验库包启停（同一条链），停用后该插件不再注入任务提示词 */
async function mkTogglePack(id, enabled) {
  try {
    await api("/api/skills/pack-op", { method: "POST",
      body: JSON.stringify({ id, op: enabled ? "enable" : "disable" }) });
    toast(enabled ? t("已启用") : t("已停用（不再注入任务提示词）"));
    loadMarket();
  } catch (e) {
    toast(e.message || t("操作失败"), true);
    loadMarket();
  }
}

function renderMarket() {
  const grid = $("mk-grid");
  if (!grid) return;
  const data = S.market;
  if (!data) {
    grid.innerHTML = '<div class="empty">' + t("加载失败：服务未连接") + "</div>";
    const cnt0 = $("mk-count");
    if (cnt0) cnt0.textContent = "";
    return;
  }
  // 分类下拉：闭集（含 0 条类目），只在首次填充，之后保留用户选择
  const catSel = $("mk-cat");
  if (catSel && !catSel.options.length) {
    catSel.innerHTML = '<option value="">' + t("全部分类") + "</option>" +
      (data.categories || []).map((c) => '<option value="' + esc(c) + '">' + esc(t(c)) + "</option>").join("");
  }
  const q = (($("mk-search") || {}).value || "").trim().toLowerCase();
  const cat = catSel ? catSel.value : "";
  const st = S.mkState || "all";
  let items = data.catalog || [];
  if (cat) items = items.filter((p) => p.category === cat);
  if (st === "installed") items = items.filter((p) => p.installed);
  if (st === "not") items = items.filter((p) => !p.installed);
  if (q) items = items.filter((p) =>
    (p.name || "").toLowerCase().indexOf(q) >= 0 || (p.desc || "").toLowerCase().indexOf(q) >= 0);
  const cnt = $("mk-count");
  if (cnt && mkActiveView() === "local") cnt.textContent = t("共 ") + items.length + t(" 个");
  // 分区渲染（对齐 ZCode 插件管理形态）：内置 / 已安装 / 可安装三组。
  // #mk-grid 本身是 grid 容器，直接塞 h3 会把标题当格子排（样式乱）——
  // 分区模式给外层加 .mk-grouped 转块级，每组自带独立 .mk-grid。
  if (st === "all" && !cat && !q) {
    const builtin = items.filter((p) => p.builtin);
    const inst = items.filter((p) => !p.builtin && p.installed);
    const avail = items.filter((p) => !p.builtin && !p.installed);
    const sec = (title, list) => !list.length ? "" :
      '<h3 class="sec-title">' + esc(t(title)) + ' <span class="tag">' + list.length + "</span></h3>" +
      '<div class="mk-grid">' + list.map((p) => mkCardHtml(p)).join("") + "</div>";
    grid.classList.add("mk-grouped");
    grid.innerHTML = sec(t("内置"), builtin) + sec(t("已安装"), inst) + sec(t("可安装"), avail) ||
      '<div class="empty">' + t("没有符合条件插件") + "</div>";
    return;
  }
  grid.classList.remove("mk-grouped");
  grid.innerHTML = items.map((p) => mkCardHtml(p)).join("") || '<div class="empty">' + t("没有符合条件插件") + "</div>";
}

async function mkInstall(id) {
  try {
    const r = await api("/api/market/" + encodeURIComponent(id) + "/install", { method: "POST", body: "{}" });
    if (r && r.already) toast(t("该插件已安装过"));
    else {
      toast(t("安装成功，运行任务时自动注入提示词；可到「经验库」启停或查看"));
      (r && r.warnings || []).forEach((w) => toast(w, true));   // 供应链/内容警示逐条红牌
    }
  } catch (e) { toast(e.message, true); return; }
  loadMarket();
}

async function mkRemove(id) {
  if (!await uiConfirm(t("卸载该插件？它会从经验库中移除。"), { ok: t("卸载"), danger: true })) return;
  try {
    await api("/api/market/" + encodeURIComponent(id) + "/remove", { method: "POST", body: "{}" });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已卸载"));
  loadMarket();
}

/* ------------------------------------------------------ 市场：外部目录 */
/* 公开生态插件目录：只装纯技能类（文档型）；含脚本/钩子/MCP 的条目服务端
 * 预分类灰显。服务端对全量本地缓存做搜索/来源过滤后分页下发（每页 60），
 * 前端累积渲染 + 滚动哨兵自动续页；缓存全在本地，翻页零成本。 */
const MKR_PAGE = 60;

function mkActiveView() {
  const btn = document.querySelector("#mk-view .seg-btn.active");
  return btn ? (btn.dataset.v || "local") : "local";
}

function mkSetView(v) {
  document.querySelectorAll("#mk-view .seg-btn").forEach((b) =>
    b.classList.toggle("active", b.dataset.v === v));
  const local = $("mk-local"), remote = $("mk-remote");
  if (local) local.classList.toggle("hidden", v !== "local");
  if (remote) remote.classList.toggle("hidden", v !== "remote");
  renderMarket();
  if (v === "remote" && !S.mkrAll) mkrLoadPage(true);
  else renderMarketRemote();
}

function mkrFilterKey() {
  const q = (($("mkr-search") || {}).value || "").trim().toLowerCase();
  const srcSel = $("mkr-source");
  return q + "|" + (srcSel ? srcSel.value : "") + "|" + (S.mkrInst ? "inst" : "");
}

/* 搜索防抖：过滤在服务端对全量做，停 350ms 再发请求；只跟当前过滤键变化时重拉首页 */
function mkrDebounce() {
  clearTimeout(mkrDebounce._t);
  mkrDebounce._t = setTimeout(() => {
    if (mkrFilterKey() === S.mkrKey && S.mkrAll) return;   // 同条件不重复拉
    mkrLoadPage(true);
  }, 350);
}

/* 拉一页：reset=清空已累积列表（首进/搜索/换来源/刷新后）。 */
async function mkrLoadPage(reset) {
  // 翻页保持单飞；搜索/换来源/刷新属于重置请求，可以抢占旧请求。
  // 旧响应回来时由 requestKey 丢弃，不能覆盖用户刚选的新条件。
  if (S.mkrLoading && !reset) return;
  const requestKey = (S.mkrRequestKey || 0) + 1;
  S.mkrRequestKey = requestKey;
  if (reset) { S.mkrAll = []; S.mkrOffset = 0; }
  const q = (($("mkr-search") || {}).value || "").trim();
  const srcSel = $("mkr-source");
  let url = "/api/market/remote?offset=" + (S.mkrOffset || 0) + "&limit=" + MKR_PAGE;
  if (srcSel && srcSel.value) url += "&source=" + encodeURIComponent(srcSel.value);
  if (q) url += "&q=" + encodeURIComponent(q);
  if (S.mkrInst) url += "&installed=1";
  S.mkrLoading = true;
  let data = null;
  try { data = await api(url); } catch (e) { data = null; }
  if (requestKey !== S.mkrRequestKey) return;
  S.mkrLoading = false;
  if (!data) { S.marketRemote = null; S.mkrAll = null; renderMarketRemote(); return; }
  S.marketRemote = data;
  S.mkrAll = (S.mkrAll || []).concat(data.entries || []);
  S.mkrOffset = S.mkrAll.length;
  S.mkrKey = mkrFilterKey();
  renderMarketRemote();
}

function mkrCardHtml(p) {
  let ops;
  if (p.installed) ops = '<span class="tag ok">' + t("已安装") +
      (p.installed_version ? " v" + esc(p.installed_version) : "") + "</span>" +
    (p.update_available
      ? '<button class="ghost small" onclick="mkrUpdate(\'' + jsq(p.id) + '\', \'' + jsq(p.version || "") + '\')" title="' +
        esc(t("目录已有 v") + (p.version || "?") + t("；重装覆写（仅本包标记文件），内容变化会提示核对")) + '">' +
        t("更新到 v") + esc(p.version || "?") + "</button>"
      : "") +
    '<button class="ghost small" onclick="mkRemove(\'' + jsq(p.id) + '\')">' + t("卸载") + "</button>";
  else if (p.compat === "blocked") ops = '<button class="ghost small" disabled title="' +
    esc(p.block_reason || t("该插件无法从公开生态下载")) + '">' + t("不适配") + "</button>";
  else ops = '<button class="primary small" data-mk="' + esc(p.id) + '" onclick="mkrInstall(\'' + jsq(p.id) + '\')">' + t("安装") + "</button>";
  const meta = [p.author, p.version ? "v" + p.version : ""].filter(Boolean).join(" · ");
  // 信任卡（ClawTrust 思路）：热度（来源自报下载量，仅参考）+ 装前安检结论
  const trust = [
    p.downloads ? '<span class="tag" title="' + t("来源自报下载量，仅作热度参考") + '">▼ ' +
      esc(p.downloads) + "</span>" : "",
    p.scan_note ? (p.scan_note.indexOf("高风险") >= 0
      ? '<span class="tag" style="color:var(--err,#d33)" title="' + esc(p.scan_note) + '">' +
        t("⚠ 安检高风险") + "</span>"
      : '<span class="tag" title="' + esc(p.scan_note) + '">' + t("安检：") + esc(p.scan_note.split("：")[0]) + "</span>")
      : ""].filter(Boolean).join("");
  return '<div class="card mk-card' + (p.compat === "blocked" ? " blocked" : "") + '"><div class="head">' +
    '<span class="name">' + esc(t(p.title || p.name)) + "</span>" +
    '<span class="tag mk-src">' + esc(t(p.source_name || "")) + "</span>" +
    (p.category ? '<span class="tag">' + esc(p.category) + "</span>" : "") +
    "</div>" +
    '<div class="note">' + esc(t(p.desc || "")) + "</div>" +
    '<div class="mk-meta"><span>' + esc(meta) + "</span>" + trust + "</div>" +
    '<div class="ops">' + ops + "</div></div>";
}

function renderMarketRemote() {
  const grid = $("mkr-grid");
  if (!grid) return;
  if (mkActiveView() !== "remote") return;   // 本地视图时不动计数（renderMarket 负责）
  const data = S.marketRemote;
  if (!data) {
    grid.innerHTML = '<div class="empty">' + t("加载失败：服务未连接") + "</div>";
    mkCount("");
    return;
  }
  // 来源下拉：首次填充，之后保留用户选择（计数是目录全量，不是本页）；
  // 自定义源在条目名前加「自定义·」标注（B6）
  const srcSel = $("mkr-source");
  if (srcSel && !srcSel.options.length) {
    srcSel.innerHTML = '<option value="">' + t("全部来源") + "</option>" +
      (data.sources || []).map((s) =>
        '<option value="' + esc(s.id) + '">' + (s.custom ? t("自定义·") : "") +
        esc(t(s.name)) + t("（") + s.count + t("）") + "</option>").join("");
  }
  mkrSyncSourceButtons();
  const times = (data.sources || []).map((s) => s.fetched_at).filter(Boolean);
  const meta = $("mkr-meta");
  if (meta) meta.textContent = times.length ? t("目录更新于 ") + times.join(" / ") : "";
  // 「已安装 N」入口：计数是全量已装（未过滤），点击切换只看已安装
  const instBtn = $("mkr-installed");
  if (instBtn) {
    instBtn.textContent = t("已安装 ") + (Number(data.installed_total) || 0);
    instBtn.classList.toggle("active", !!S.mkrInst);
    instBtn.setAttribute("aria-pressed", S.mkrInst ? "true" : "false");
  }
  const items = S.mkrAll || [];
  mkCount(t("已加载 ") + items.length + t(" / 共 ") + data.total + t(" 个"));
  if (!items.length) {
    grid.innerHTML = '<div class="empty">' + (data.total === 0 && !S.mkrOffset && !(($("mkr-search")||{}).value||"").trim() && !(srcSel||{}).value
      ? (S.mkrInst
          ? t("还没有从外部目录安装过插件；退出过滤后逛逛目录，安装前会先给你看包内容。")
          : t("外部目录还是空的，点「拉取更新」从公开生态获取。"))
      : t("没有符合条件插件")) + "</div>";
    const more = $("mkr-more");
    if (more) more.classList.add("hidden");
    return;
  }
  grid.innerHTML = items.map(mkrCardHtml).join("");
  const more = $("mkr-more");
  if (more) {
    more.classList.toggle("hidden", !data.has_more);
    const txt = $("mkr-more-txt");
    if (txt) txt.textContent = t("还有 ") + (data.total - items.length) + t(" 条，继续滚动加载");
    const btn = $("mkr-more-btn");
    if (btn) btn.disabled = false;
  }
}

/* 滚动哨兵进入视野即续页（main 是滚动容器，哨兵贴在列表尾）。 */
function mkrBindSentinel() {
  const sentinel = $("mkr-sentinel");
  if (!sentinel || !("IntersectionObserver" in window)) return;
  new IntersectionObserver((es) => {
    if (!es.some((e) => e.isIntersecting)) return;
    if (mkActiveView() !== "remote") return;
    if (S.mkrLoading || !S.marketRemote || !S.marketRemote.has_more) return;
    mkrLoadPage(false);
  }, { root: document.querySelector("main"), rootMargin: "400px" }).observe(sentinel);
}

/* 已装插件更新（B6，dsh「安装结果显示实际版本」借鉴）：直接 force 重装
 * （服务端仍走下载+剥离式检查+内容突变对账），不像新装那样走预览弹框。 */
async function mkrUpdate(id, ver) {
  if (!await uiConfirm(t("重装该插件到目录当前版本？只覆写带本包标记的文件；内容有变化会停用待复核。"), { ok: t("更新") })) return;
  let r;
  try {
    r = await api("/api/market/remote/install", { method: "POST",
      body: JSON.stringify({ id, force: true }), timeout: 180000 });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已更新到 v") + (ver || (r && r.version) || "?"));
  (r && r.warnings || []).forEach((w) => toast(w, true));
  mkrLoadPage(true);
}

/* 自定义索引源管理（B6，dsh「自定义插件索引源」借鉴）：标准 marketplace.json
 * 的 https 直链；添加后与内置源同权参与「拉取更新」。 */
async function mkrAddSource() {
  const url = await uiPrompt(t("输入自定义源的 marketplace.json 地址（https）"), "");
  if (!url || !url.trim()) return;
  try {
    await api("/api/market/remote/sources", { method: "POST",
      body: JSON.stringify({ action: "add", url: url.trim() }) });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已添加自定义源；点「拉取更新」抓取目录"));
  const srcSel = $("mkr-source");
  if (srcSel) srcSel.innerHTML = "";   // 触发下拉重建
  mkrRefreshSourcesOnly();
}

async function mkrDelSource() {
  const srcSel = $("mkr-source");
  const sid = srcSel ? srcSel.value : "";
  if (!sid) return;
  if (!await uiConfirm(t("删除自定义源？已装插件不受影响。"), { ok: t("删除"), danger: true })) return;
  try {
    await api("/api/market/remote/sources", { method: "POST",
      body: JSON.stringify({ action: "remove", id: sid }) });
  } catch (e) { toast(e.message, true); return; }
  toast(t("已删除自定义源"));
  const sel = $("mkr-source");
  if (sel) { sel.innerHTML = ""; sel.value = ""; }
  mkrRefreshSourcesOnly();
}

/* 源管理后的轻量刷新：重拉目录页并按选中项切换「删此源」按钮可见性。 */
function mkrRefreshSourcesOnly() {
  mkrLoadPage(true);
  mkrSyncSourceButtons();
}

function mkrSyncSourceButtons() {
  const srcSel = $("mkr-source"), del = $("mkr-del-source");
  if (!srcSel || !del) return;
  const sid = srcSel.value || "";
  const known = ((S.marketRemote || {}).sources || []).find((s) => s.id === sid);
  del.classList.toggle("hidden", !(known && known.custom));
}

async function mkrRefresh() {
  const btn = $("mkr-refresh");
  if (!btn || btn.disabled) return;
  btn.disabled = true;
  const old = btn.textContent;
  btn.textContent = t("拉取中…");
  try {
    const r = await api("/api/market/remote/refresh", {
      method: "POST", timeout: 120000, body: "{}" });
    const bad = (r.refresh || []).filter((x) => !x.ok);
    if (bad.length) toast(t("部分来源拉取失败：") + bad.map((x) => x.error || x.id).join(t("；")), true);
    else toast(t("拉取成功"));
    // 刷新后来源计数变了：下拉重建并保留当前选择，再重拉第一页
    const srcSel = $("mkr-source");
    if (srcSel) {
      const keep = srcSel.value;
      srcSel.innerHTML = '<option value="">' + t("全部来源") + "</option>" +
        (r.sources || []).map((s) =>
          '<option value="' + esc(s.id) + '">' + esc(t(s.name)) + t("（") + s.count + t("）") + "</option>").join("");
      srcSel.value = keep;
    }
    mkrLoadPage(true);
  } catch (e) { toast(e.message, true); }
  btn.disabled = false;
  btn.textContent = old;
}

/* 两阶段安装（先看后装）：① 预览——服务端下载+剥离式检查但不落盘，弹框展示
 * 包内容（文件清单/体量/剥离项/完整性）；② 确认——带 token 安装那份已检内容，
 * 不重复下载。token 一次性，安装失败弹框保留可重试。 */
async function mkrInstall(id) {
  const btn = document.querySelector('#mkr-grid button[data-mk="' + id + '"]');
  if (btn) { btn.disabled = true; btn.textContent = t("检查中…"); }
  toast(t("正在下载插件包做安装前检查，包较大时需要约一分钟…"));
  let p;
  try {
    p = await api("/api/market/remote/preview", { method: "POST",
      body: JSON.stringify({ id }), timeout: 180000 });
  } catch (e) {
    toast(e.message, true);
    mkrLoadPage(true);   // 失败重拉复位按钮
    return;
  }
  mkrShowInstallPreview(p);
}

function _mkrIntegrityText(k) {
  const map = {
    verified: t("sha256 已校验"),
    unverified: t("无哈希（HTTPS 传输 + 纯技能白名单兜底）"),
    "git-ref": t("按 git ref 锁定"),
    "git-head": t("跟随仓库 HEAD"),
  };
  return map[k] || k || "";
}

function mkrShowInstallPreview(p) {
  p = p || {};
  const rows = (p.file_list || []).map((f) =>
    '<tr><td title="' + esc(f.path) + '">' + esc(f.path) + '</td><td class="mkpv-chars">' + esc(mkCharsText(f.chars)) + "</td></tr>").join("");
  const moreF = p.files_total > (p.file_list || []).length
    ? '<tr><td colspan="2" class="mkpv-more">' + t("…等共 ") + p.files_total + t(" 个文件") + "</td></tr>" : "";
  const stripped = p.stripped || [];
  const strippedHtml = stripped.length
    ? '<div class="mkpv-sec">' + t("将自动剥离（不写入、不执行）：") + "</div>" +
      '<ul class="mkpv-strip">' + stripped.map((s) => "<li>" + esc(s) + "</li>").join("") +
      (p.stripped_total > stripped.length
        ? '<li class="mkpv-more">' + t("…等 ") + p.stripped_total + t(" 个") + "</li>" : "") + "</ul>"
    : "";
  const skills = (p.skills || []).map((s) => '<span class="tag">' + esc(s) + "</span>").join("");
  // 内容安检（装前扫描）：高风险红字强提示 + 发现明细；注意级只留一行
  const riskFindings = (p.risk_findings || []).map((f) =>
    '<li>' + esc(t(f.category)) + ' · ' + esc(f.detail || "") + t("（行 ") + f.line + "）</li>").join("");
  const riskHtml = p.risk_label
    ? (p.risk_label.indexOf("高风险") >= 0
      ? '<div class="mkpv-sec" style="color:var(--err,#d33)"><b>' + esc(t(p.risk_label)) +
        "：</b>" + t("技能文本命中危险模式（可能诱导模型外传密钥/执行命令）。请逐条确认下方发现，不确定就别装。") +
        '<ul class="mkpv-strip">' + riskFindings + "</ul></div>"
      : '<div class="mkpv-sec">' + esc(t(p.risk_label)) + "：" + t("部分内容值得留意识别") +
        '<ul class="mkpv-strip">' + riskFindings + "</ul></div>")
    : "";
  // 供应链对账（AST10 #2）：内容突变 / 近似名仿冒特征
  const chainHtml =
    (p.changed ? '<div class="mkpv-sec" style="color:var(--err,#d33)">⚠ ' +
      t("内容较上次安装发生变化（指纹 ") + esc(p.digest || "") + t("），建议核对后再启用") + "</div>" : "") +
    ((p.near_names || []).map((n) =>
      '<div class="mkpv-sec">⚠ ' + t("与已装技能「") + esc(n[0]) + t("」名称过近（相似度 ") +
      Math.round(n[1] * 100) + t("%），注意甄别仿冒") + "</div>").join(""));
  openModal(t("安装前确认"),
    '<div class="mkpv">' +
    '<div class="mkpv-name">' + esc(p.title || p.id || "") + "</div>" +
    '<div class="mkpv-meta"><span>' + esc(t("来源：") + (p.source || "")) + "</span>" +
    (p.version ? "<span>v" + esc(p.version) + "</span>" : "") +
    "<span>" + esc(_mkrIntegrityText(p.integrity)) + "</span></div>" +
    (skills ? '<div class="mkpv-skills">' + t("包含技能：") + skills + "</div>" : "") +
    riskHtml + chainHtml +
    '<div class="mkpv-sum">' + t("共 ") + (p.files_total || 0) + t(" 个文件 · ") + esc(mkCharsText(p.total_chars || 0)) + "</div>" +
    (rows ? '<table class="mkpv-files"><thead><tr><th>' + t("文件") + "</th><th>" + t("体量") +
      "</th></tr></thead><tbody>" + rows + moreF + "</tbody></table>" : "") +
    strippedHtml +
    '<p class="hint">' + t("安装后运行任务时自动注入提示词；可到「经验库」启停或卸载。") + "</p>" +
    "</div>",
    '<button class="ghost" onclick="closeModal()">' + t("取消") + "</button>" +
    '<button class="' + (p.risk_label && p.risk_label.indexOf("高风险") >= 0 ? "danger" : "primary") +
    '" id="mkpv-ok" onclick="mkrInstallConfirm(\'' + jsq(p.token || "") + '\',\'' + jsq(p.id || "") + '\')">' +
    (p.risk_label && p.risk_label.indexOf("高风险") >= 0 ? t("我已确认风险，仍要安装") : t("确认安装")) + "</button>");
}

async function mkrInstallConfirm(token, id) {
  const ok = $("mkpv-ok");
  if (ok) { ok.disabled = true; ok.textContent = t("安装中…"); }
  try {
    const r = await api("/api/market/remote/install", { method: "POST",
      body: JSON.stringify({ id, token }), timeout: 180000 });
    closeModal();
    if (r && r.already) toast(t("该插件已安装过"));
    else {
      // 剥离式安装：脚本/钩子/MCP 文件被剔除但技能装上了，如实告知剔除了什么
      const stripped = (r && r.stripped) || [];
      toast(t("安装成功，运行任务时自动注入提示词；可到「经验库」启停或查看") + (stripped.length
        ? t("；已自动剥离脚本/钩子/MCP 文件：") + stripped.slice(0, 3).join("、")
          + (stripped.length > 3 ? t(" 等 ") + stripped.length + t(" 个文件") : "")
        : ""));
    }
  } catch (e) {
    toast(e.message, true);
    const ok2 = $("mkpv-ok");
    if (ok2) { ok2.disabled = false; ok2.textContent = t("确认安装"); }
    return;   // 弹框保留：可重试或取消（token 未消费）
  }
  mkrLoadPage(true);   // 已安装徽章要翻牌
}


/* ---------------------------------------------------------- 编排设置（编排者 + 并发设置） */
async function loadOrchestrator() {
  try {
    const r = await api("/api/orchestrator");
    S.orch = r.orchestrator || null;
  } catch (e) { S.orch = null; }
  renderOrchSide();
  renderOrch();
}

/* 侧栏左下角中间的「编排者供应商」：显示 CodeBee 自己的智能体当前用的厂商，
 * 点一下到设置里的「编排设置」更换（可选范围＝已接入的供应商）。 */
function renderOrchSide() {
  const btn = $("btn-prov-side"), txt = $("prov-side-text"), dot = $("prov-side-dot");
  if (!btn || !txt || !dot) return;
  const o = S.orch || {};
  const name = (o.provider_name || "").trim().replace(/^\[[^\]]+\]\s*/, "");  // 去掉 "[CC] " 之类前缀
  const model = (o.model || "").trim();
  if (!name) {
    txt.textContent = t("未选厂商");
    dot.className = "pdot";
    btn.title = t("尚未选择编排者供应商\n点击到「编排设置」，从已接入的厂商里选一个");
    return;
  }
  txt.textContent = name;
  dot.className = "pdot " + (o.ready ? "ok" : "warn");
  btn.title = t("编排者供应商：") + name + (model ? " · " + model : "") +
    (o.ready ? t("（生效中）") : t("（未生效：检查密钥 / 启停 / 模型）")) +
    t("\n点击到「编排设置」更换");
}

async function loadSettings() {
  try {
    S.settings = await api("/api/settings");
    const inp = $("set-workers");
    if (inp && S.settings) inp.value = S.settings.max_concurrent_jobs;
    const tel = $("set-telemetry");
    if (tel && S.settings) tel.checked = S.settings.telemetry_errors !== false;
    const pet = $("set-pet");
    if (pet && S.settings) pet.checked = !!S.settings.pet_enabled;
    const cs = $("set-claude-sync");
    if (cs && S.settings) cs.checked = S.settings.claude_config_sync !== false;
    const mcp = $("set-mcp-servers");
    if (mcp && S.settings) mcp.value = S.settings.mcp_servers || "";
    fillNotifyPush();
    loadVoiceTerms();
    fillBackupRemote();
    syncPetModeSeg();
    syncPetSkinSeg();
    const wd = $("set-workdir"), hint = $("set-workdir-hint");
    if (wd && S.settings) wd.value = S.settings.default_workdir_effective || "";
    if (hint && S.settings) {
      const custom = !!(S.settings.default_workdir || "").trim();
      hint.textContent = custom ? t("当前生效：") + S.settings.default_workdir_effective + t("（自定义）")
                                : t("当前生效：") + S.settings.default_workdir_effective + t("（内置默认，尚未自定义）");
    }
    // 新任务表单：默认就「选中」默认路径（参考工作区选择器的默认选中态）；
    // 手动清空输入仍表示跟随默认。f-workdir-hint 保留给「继续会话/克隆任务」的覆盖警告
    const wdInput = $("f-workdir");
    if (wdInput && S.settings && !wdInput.value.trim()) {
      wdInput.value = S.settings.default_workdir_effective || "";
      queueGitProbe();   // 目录在场即探测代码版本，点亮分支胶囊
    }
  } catch (e) { /* 忽略 */ }
  loadMcpCatalog();
  loadSettingsV2();   // 引擎调参卡独立拉取（挂了不影响基础设置）
  loadBackendProfiles();
  loadCommandAuth();
}

async function loadBackendProfiles() {
  const box = $("acp-profiles");
  if (!box) return;
  try {
    const data = await api("/api/backend-profiles");
    const rows = data.profiles || [];
    box.innerHTML = rows.length ? rows.map((row) =>
      '<div class="list-row"><span><b>' + esc(row.label || row.id) + '</b> · ' + esc(row.command || "") +
      (row.enabled === false ? ' · ' + esc(t("已停用")) : '') + '</span><button class="ghost small" type="button" onclick="deleteAcpProfile(\'' + jsq(row.id) + '\')">' + esc(t("删除")) + '</button></div>'
    ).join("") : '<span class="hint">' + esc(t("暂无 ACP 后端")) + '</span>';
  } catch (error) {
    box.innerHTML = '<span class="hint">' + esc(t("ACP 配置加载失败：")) + esc(error.message) + '</span>';
  }
}

window.saveAcpProfile = async function () {
  const msg = $("acp-msg");
  try {
    const argsText = ($("acp-args") || {}).value || "[]";
    const args = JSON.parse(argsText);
    if (!Array.isArray(args)) throw new Error(t("参数必须是 JSON 数组"));
    await api("/api/backend-profiles", { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()),
      body: JSON.stringify({ label: $("acp-label").value, command: $("acp-command").value,
        args, workspace_path: $("acp-workspace").value }) });
    if (msg) msg.textContent = t("ACP 后端已保存");
    ["acp-label", "acp-command", "acp-args", "acp-workspace"].forEach((id) => { const el = $(id); if (el) el.value = id === "acp-args" ? "[]" : ""; });
    await loadBackendProfiles();
    await refreshState();
  } catch (error) { if (msg) msg.textContent = t("ACP 保存失败：") + error.message; }
};

window.deleteAcpProfile = async function (id) {
  try {
    await api("/api/backend-profiles/" + encodeURIComponent(id) + "/delete", { method: "POST", headers: authHeaders(), body: "{}" });
    await loadBackendProfiles();
    await refreshState();
  } catch (error) { toast(t("删除 ACP 失败：") + error.message, true); }
};

async function loadCommandAuth() {
  const pendingBox = $("command-auth-pending");
  const mode = $("command-auth-mode");
  if (!pendingBox || !mode) return;
  try {
    const data = await api("/api/command-auth");
    mode.value = data.mode || "legacy";
    const rows = data.pending || [];
    pendingBox.innerHTML = rows.length ? rows.map((row) =>
      '<div class="list-row"><span><code>' + esc(row.command || "") + '</code> · ' + esc(row.source || "") + '</span><button class="ghost small" type="button" onclick="decideCommandAuth(\'' + jsq(row.id) + '\',true)">' + esc(t("批准一次")) + '</button><button class="ghost small" type="button" onclick="decideCommandAuth(\'' + jsq(row.id) + '\',false)">' + esc(t("拒绝")) + '</button></div>'
    ).join("") : '<span class="hint">' + esc(t("暂无待批准命令")) + '</span>';
  } catch (error) { pendingBox.innerHTML = '<span class="hint">' + esc(t("授权状态加载失败：")) + esc(error.message) + '</span>'; }
}

window.saveCommandAuthMode = async function () {
  try {
    await api("/api/command-auth", { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()), body: JSON.stringify({ mode: $("command-auth-mode").value }) });
    await loadCommandAuth();
  } catch (error) { const msg = $("command-auth-msg"); if (msg) msg.textContent = t("授权策略保存失败：") + error.message; }
};

window.decideCommandAuth = async function (id, approve) {
  try {
    await api("/api/command-auth/requests/" + encodeURIComponent(id), { method: "POST", headers: Object.assign({ "Content-Type": "application/json" }, authHeaders()), body: JSON.stringify({ approve, scope: "once" }) });
    await loadCommandAuth();
  } catch (error) { const msg = $("command-auth-msg"); if (msg) msg.textContent = t("命令授权操作失败：") + error.message; }
};

/* ---------------- settings_v2 引擎调参卡（schema 驱动） ----------------
 * /api/settings-v2 拉 describe（含字段元数据），按 namespace 渲染控件；
 * 保存走 /api/settings-v2/<ns> mutate（expected_revision CAS，409=别处已改，
 * 自动重拉最新值）。schema 变更零前端改动。 */
async function loadSettingsV2() {
  const box = $("set-v2-card");
  if (!box) return;
  let v2 = null;
  try { v2 = await api("/api/settings-v2"); } catch (e) { box.innerHTML = ""; return; }
  if (!v2 || typeof v2 !== "object" || !v2.namespaces || typeof v2.namespaces !== "object") {
    box.innerHTML = "";
    return;
  }
  S.settingsV2 = v2;
  const NS_LABEL = { orchestrator: t("编排引擎"), budget: t("预算"), cascade: t("级联路由"), startup: t("启动") };
  let html = "<label>" + esc(t("引擎调参（schema 化设置，立即生效）")) + "</label>";
  for (const ns of Object.keys(v2.namespaces || {})) {
    const d = v2.namespaces[ns] || {};
    html += '<div class="set-v2-ns" data-ns="' + esc(ns) + '" data-rev="' + (d.revision || 0) + '">' +
      '<div class="set-v2-ns-h">' + esc(NS_LABEL[ns] || ns) +
      '<span class="flex1"></span><span class="set-v2-rev">rev ' + (d.revision || 0) + "</span></div>";
    for (const f of (d.fields || [])) {
      const iid = "setv2-" + esc(ns) + "-" + f.path.replace(/\./g, "-");
      const val = f.path.split(".").reduce((o, k) => (o && o[k] !== undefined) ? o[k] : undefined, d.values || {});
      const cur = val === undefined ? "" : val;
      let inp;
      if (f.type === "bool") {
        inp = '<input id="' + iid + '" type="checkbox"' + (cur ? " checked" : "") + ">";
      } else if (f.type === "int" || f.type === "float") {
        const step = f.type === "float" ? "0.01" : "1";
        inp = '<input id="' + iid + '" type="number" step="' + step + '" value="' + esc(String(cur)) + '"' +
          (f.clamp ? ' min="' + f.clamp[0] + '" max="' + f.clamp[1] + '"' : "") + ' style="max-width:140px">';
      } else {
        inp = '<input id="' + iid + '" type="text" value="' + esc(String(cur)) + '">';
      }
      html += '<div class="set-v2-row">' + inp +
        '<span class="set-v2-lb" title="' + esc(t(f.description || f.path)) + '">' + esc(t(f.description || f.path)) + "</span></div>";
    }
    html += '<div class="input-row" style="margin-top:6px"><button class="ghost small" onclick="saveSettingsV2(\'' + jsq(ns) + '\')">' + t("保存") + "</button>" +
      '<span class="set-v2-msg msg"></span></div></div>';
  }
  box.innerHTML = html;
}

window.saveSettingsV2 = async function (ns) {
  const v2 = S.settingsV2 || {};
  const d = (v2.namespaces || {})[ns];
  const box = document.querySelector('.set-v2-ns[data-ns="' + ns + '"]');
  if (!d || !box) return;
  const ops = [];
  for (const f of (d.fields || [])) {
    const iid = "setv2-" + ns + "-" + f.path.replace(/\./g, "-");
    const el = document.getElementById(iid);
    if (!el) continue;
    if (f.type === "bool") ops.push({ op: "set", path: f.path, value: el.checked });
    else if (f.type === "int" || f.type === "float") ops.push({ op: "set", path: f.path, value: Number(el.value) });
    else ops.push({ op: "set", path: f.path, value: el.value });
  }
  const msg = box.querySelector(".set-v2-msg");
  try {
    const r = await api("/api/settings-v2/" + ns, {
      method: "POST", body: JSON.stringify({ ops, expected_revision: d.revision || 0 }) });
    if (msg) { msg.className = "set-v2-msg msg ok"; msg.textContent = t("已保存 rev ") + r.revision; }
    loadSettingsV2();
  } catch (e) {
    if (/期望 rev/.test(String(e.message))) {
      if (msg) { msg.className = "set-v2-msg msg err"; msg.textContent = t("配置已被别处修改，已刷新，请重试"); }
      loadSettingsV2();
    } else if (msg) { msg.className = "set-v2-msg msg err"; msg.textContent = e.message; }
  }
};

/* 保存默认保存路径；可选把旧默认路径下的现有任务目录迁移到新路径 */
async function saveDefaultWorkdir() {
  const msg = $("settings-msg");
  try {
    const r = await api("/api/settings/default-workdir", { method: "POST", body: JSON.stringify({
      path: ($("set-workdir").value || "").trim(),
      migrate: $("set-workdir-migrate") && $("set-workdir-migrate").checked,
    }) });
    S.settings = r.settings;
    const n = (r.moved || 0), sk = (r.skipped || 0);
    if (msg) {
      msg.className = "msg ok";
      msg.textContent = t("默认保存路径已更新：") + r.settings.default_workdir_effective +
        (n ? t("；已迁移 ") + n + t(" 个任务目录") : "") + (sk ? t("（跳过 ") + sk + t(" 个运行中/迁移失败）") : "");
    }
    loadSettings();
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
}

/* 编排者供应商下拉：三种协议都支持直连（含 google），不限于可注入 CLI 的 */
function orchProvs() {
  return (S.providers || []).filter((p) => p.api_key && p.enabled !== false);
}

/* 编排者模型下拉的选项：当前值 + 该供应商已启用模型（按优先级） */
function orchModelHtml(prov, curModel) {
  const names = (prov ? (prov.models || []).filter((m) => !m.hidden && m.enabled !== false)
    .sort((a, b) => (a.priority || 0) - (b.priority || 0)).map((m) => m.name) : []);
  const all = Array.from(new Set([curModel].concat(names).filter(Boolean)));
  return '<option value="">' + t("（用供应商默认模型）") + '</option>' +
    all.map((m) => '<option value="' + esc(m) + '"' + (m === curModel ? " selected" : "") + ">" + esc(m) + "</option>").join("");
}

function renderOrch() {
  const box = $("orch-config");
  if (!box || !S.orch) return;
  const provs = orchProvs();
  const sig = JSON.stringify([S.orch, provs.map((p) => p.id)]);
  if (sig === S.orchSig) return;
  S.orchSig = sig;
  const sel = provs.find((p) => p.id === S.orch.provider_id) || null;
  const opts = '<option value="">' + t("（不使用编排者）") + '</option>' + provs.map((p) =>
    '<option value="' + esc(p.id) + '"' + (S.orch.provider_id === p.id ? " selected" : "") + ">" +
    esc(p.name) + t("（") + esc(protoLabel(p)) + t("）") + "</option>").join("");
  const curModel = S.orch.model || (sel ? sel.model : "") || "";
  box.innerHTML =
    '<div class="grid-2">' +
    '<div class="field"><label>' + t("编排者供应商") + '</label><select id="orch-prov">' + opts + "</select></div>" +
    '<div class="field"><label>' + t("编排者模型") + '</label><select id="orch-model">' + orchModelHtml(sel, curModel) + "</select></div></div>" +
    '<div class="ops"><label class="toggle"><input type="checkbox" id="orch-enabled"' +
    (S.orch.enabled ? " checked" : "") + ">" + t(" 启用编排者（规划 / 难度判定 / 写作大纲）") + "</label>" +
    '<button class="ghost small" onclick="saveOrchestrator()">' + t("保存") + '</button>' +
    '<button class="ghost small" onclick="testOrchestrator()">' + t("测试连通") + '</button>' +
    '<span id="orch-test" class="msg"></span></div>' +
    (S.orch.enabled && !S.orch.ready ? '<p class="hint warn">' + t("当前配置不生效：请检查供应商密钥、启停状态与模型选择。") + '</p>' : "");
  // 换供应商只刷新模型下拉，不整块重绘：整块重绘会按 S.orch 重写 selected，
  // 把用户刚选中的供应商弹回旧值，保存下去的还是旧值
  $("orch-prov").addEventListener("change", () => {
    const p = orchProvs().find((x) => x.id === $("orch-prov").value) || null;
    $("orch-model").innerHTML = orchModelHtml(p, (p ? p.model : "") || "");
  });
}

async function saveOrchestrator() {
  try {
    const r = await api("/api/orchestrator", { method: "POST", body: JSON.stringify({
      provider_id: $("orch-prov").value,
      model: $("orch-model").value,
      enabled: $("orch-enabled").checked }) });
    S.orch = r.orchestrator;
    S.orchSig = null;
    renderOrchSide();   // 侧栏指示同步
    renderOrch();
    toast(t("编排者配置已保存"));
  } catch (e) { toast(t("保存失败：") + e.message, true); }
}

async function testOrchestrator() {
  const el = $("orch-test");
  if (!el) return;
  el.textContent = t("测试中…"); el.className = "msg";
  try {
    const r = await api("/api/orchestrator/test", { method: "POST" });
    el.className = "msg " + (r.ok ? "ok" : "err");
    el.textContent = r.ok ? ("✓ " + r.provider + " · " + r.model + t(" 回应正常")) : ("✗ " + (r.error || t("失败")));
  } catch (e) {
    el.className = "msg err"; el.textContent = "✗ " + e.message;
  }
}

async function saveSettings() {
  const msg = $("settings-msg");
  try {
    const r = await api("/api/settings", { method: "POST", body: JSON.stringify({
      max_concurrent_jobs: parseInt($("set-workers").value, 10),
      claude_config_sync: !$("set-claude-sync") || $("set-claude-sync").checked }) });
    S.settings = r.settings;
    if (msg) { msg.className = "msg ok"; msg.textContent = t("已保存：编排并发上限 ") + r.workers; }
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
}

/* 推送通知（设置页）：群 webhook + 个人推送通道（Bark/ntfy/Server酱/Telegram） */
const NOTIFY_INPUTS = ["set-notify-webhook", "set-notify-bark-server", "set-notify-bark-key",
  "set-notify-ntfy", "set-notify-serverchan", "set-notify-tg-token", "set-notify-tg-chat"];

function fillNotifyPush() {
  if (!S.settings) return;
  const v = (k) => S.settings[k] || "";
  const set = (id, key) => { const el = $(id); if (el) el.value = v(key); };
  set("set-notify-webhook", "notify_webhook");
  set("set-notify-bark-server", "notify_bark_server");
  set("set-notify-bark-key", "notify_bark_key");
  set("set-notify-ntfy", "notify_ntfy_topic");
  set("set-notify-serverchan", "notify_serverchan_key");
  set("set-notify-tg-token", "notify_telegram_token");
  set("set-notify-tg-chat", "notify_telegram_chat_id");
  paintBrowserNotify();
}

function notifyPushPatch() {
  const val = (id) => { const el = $(id); return el ? el.value.trim() : undefined; };
  const p = {};
  const pairs = [["set-notify-webhook", "notify_webhook"], ["set-notify-bark-server", "notify_bark_server"],
    ["set-notify-bark-key", "notify_bark_key"], ["set-notify-ntfy", "notify_ntfy_topic"],
    ["set-notify-serverchan", "notify_serverchan_key"], ["set-notify-tg-token", "notify_telegram_token"],
    ["set-notify-tg-chat", "notify_telegram_chat_id"]];
  pairs.forEach(([id, key]) => { const v = val(id); if (v !== undefined) p[key] = v; });
  return p;
}

async function saveNotifyPush() {
  const msg = $("notify-test-msg");
  try {
    const r = await api("/api/settings", { method: "POST", body: JSON.stringify(notifyPushPatch()) });
    S.settings = r.settings;
    fillNotifyPush();
    if (msg) { msg.className = "msg ok"; msg.textContent = t("推送设置已保存"); }
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
}

async function saveMcpServers() {
  const el = $("set-mcp-servers");
  if (!el) return;
  try {
    const r = await api("/api/settings", { method: "POST", body: JSON.stringify({ mcp_servers: el.value }) });
    S.settings = r.settings;
    await loadMcpCatalog();
    toast(t("MCP 配置已保存，下次对话生效"));
  } catch (e) { toast(t("保存失败：") + e.message, true); }
}

function mcpRuntimeStatus(status) {
  return ({
    ready: t("可启动"),
    missing_launcher: t("缺少启动器"),
    missing_package_manager: t("缺少包管理器"),
    missing_sandbox: t("缺少隔离后端"),
  })[status] || t("待检查");
}

async function loadMcpCatalog() {
  const box = $("mcp-catalog-runtime");
  if (!box) return;
  box.innerHTML = '<span class="hint">' + esc(t("正在检查 MCP 运行环境…")) + "</span>";
  try {
    const data = await api("/api/mcp/catalog", { timeout: 15000 });
    const configuredRows = Array.isArray(data.configured_runtime) ? data.configured_runtime : [];
    const configured = Object.fromEntries(configuredRows.map((row) => [row.name, row]));
    const rows = Array.isArray(data.catalog) ? data.catalog : [];
    box.innerHTML = '<div class="mcp-runtime-title">' + esc(t("MCP 目录运行时检查")) + "</div>" +
      (rows.length ? rows.map((row) => {
        const status = mcpRuntimeStatus(row.runtime_status);
        const state = row.configured ? t("已配置") : t("未配置");
        const cls = row.runtime_status === "ready" ? "ok" : "warn";
        const launcher = (row.launcher_available ? "✓ " : "✗ ") + (row.launcher || "—");
        const manager = (row.package_manager_available ? "✓ " : "✗ ") + (row.package_manager || "—");
        const sandbox = row.sandbox_available ? "✓ " + t("OS 隔离") : "✗ " + t("OS 隔离");
        const hint = row.install_hint
          ? '<div class="mcp-runtime-hint"><span>' + esc(t("首次运行/手动安装提示：")) +
            '</span><code>' + esc(row.install_hint) + "</code></div>" : "";
        const configuredRow = configured[row.default_name];
        const configuredNote = configuredRow && configuredRow.runtime_status !== "ready"
          ? '<span class="mcp-runtime-config-warn">' + esc(t("已配置但当前无法启动")) + "</span>" : "";
        return '<div class="mcp-runtime-row"><div class="mcp-runtime-main"><b>' + esc(row.name || row.id) +
          '</b><span class="tag">' + esc(state) + '</span><span class="tag ' + cls + '">' + esc(status) +
          '</span>' + configuredNote + '</div><div class="mcp-runtime-meta"><span>' + esc(t("启动器")) +
          ': <code>' + esc(launcher) + '</code></span><span>' + esc(t("包管理器")) + ': <code>' + esc(manager) +
          '</code></span><span>' + esc(sandbox) + '</span></div>' + hint + "</div>";
      }).join("") : '<span class="hint">' + esc(t("暂无 MCP 目录项")) + "</span>");
  } catch (error) {
    box.innerHTML = '<span class="hint">' + esc(t("MCP 目录检查失败：")) + esc(error.message || error) + "</span>";
  }
}

/* MCP 一键模板（2026 社区最常用五款，npx 免安装）：追加进现有清单，
 * name 冲突时覆盖同名条目；由用户自行点「保存 MCP 配置」落盘。 */
const MCP_TEMPLATES = {
  fetch: () => ({ name: "fetch", command: "npx", args: ["-y", "mcp-server-fetch"],
    note: t("网页抓取：把 URL 内容取回为 markdown（内置智能体即可联网读网页）") }),
  memory: () => ({ name: "memory", command: "npx", args: ["-y", "@modelcontextprotocol/server-memory"],
    note: t("知识图谱记忆：跨对话的持久记忆（实体/关系存本机 JSONL）") }),
  filesystem: () => ({ name: "fs", command: "npx",
    args: ["-y", "@modelcontextprotocol/server-fs", (S.settings && S.settings.default_workdir_effective) || "."],
    note: t("文件访问：授权目录内的读/写/搜索（默认授权 CodeBee 保存路径，可改）") }),
  playwright: () => ({ name: "playwright", command: "npx",
    args: ["-y", "@playwright/mcp@latest"],
    note: t("浏览器自动化：开页面/点击/填表/截图（2026 社区使用量第一的 MCP 服务器）") }),
  context7: () => ({ name: "context7", command: "npx",
    args: ["-y", "@upstash/context7-mcp"],
    note: t("文档查询：取常用库的最新版文档（防 API 过时幻觉）") }),
};

function mcpTemplate(kind) {
  const el = $("set-mcp-servers");
  if (!el) return;
  const mk = (MCP_TEMPLATES[kind] || (() => null))();
  if (!mk) return;
  let arr = [];
  try { arr = JSON.parse(el.value || "[]") || []; } catch (e) { arr = []; }
  if (!Array.isArray(arr)) arr = [];
  const i = arr.findIndex((x) => x && x.name === mk.name);
  const dupNote = i >= 0 ? t("（覆盖同名 ") + mk.name + "）" : "";
  if (i >= 0) arr[i] = { name: mk.name, command: mk.command, args: mk.args };
  else if (arr.length >= 16) { toast(t("最多 16 个 MCP 服务器，请先删减再套模板"), true); return; }
  else arr.push({ name: mk.name, command: mk.command, args: mk.args });
  el.value = JSON.stringify(arr, null, 2);
  toast(mk.note + dupNote + t("——记得点「保存 MCP 配置」"));
}

async function testNotifyPush() {
  const msg = $("notify-test-msg");
  if (msg) { msg.className = "msg"; msg.textContent = t("发送中…"); }
  try {
    // 先落盘当前输入再测，避免「改了没保存测的是旧配置」的困惑
    await api("/api/settings", { method: "POST", body: JSON.stringify(notifyPushPatch()) });
    const r = await api("/api/notify/test", { method: "POST" });
    const names = Object.keys(r.channels || {});
    const bad = names.filter((k) => !r.channels[k]);
    if (msg) {
      msg.className = "msg " + (r.ok ? "ok" : "err");
      msg.textContent = r.ok
        ? (bad.length ? t("部分通道失败：") + bad.join(", ") : t("✓ 测试消息已发出（") + names.join(", ") + "）")
        : (t("全部通道发送失败：") + names.join(", "));
    }
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
}

/* ---------------------------------------------------------- 模型评测（评测基准台）
 * 固定样题 × 候选模型实跑 + 编排者裁判打分 → 能力榜；修 bug 题真跑代码做客观验证。 */
let EB_TIMER = null;

async function loadEvalBench() {
  if (EB_TIMER) { clearInterval(EB_TIMER); EB_TIMER = null; }
  try { S.evalbench = await api("/api/evalbench"); } catch (e) { S.evalbench = null; }
  if (!S.models) { try { S.models = await api("/api/models"); } catch (e) { /* 页面其余部分自会提示 */ } }
  if (!S.settings) { try { S.settings = await api("/api/settings"); } catch (e) { /* 定时开关留默认 */ } }
  const ae = $("eb-auto-enabled"), ad = $("eb-auto-days");
  if (ae && S.settings) ae.checked = S.settings.bench_auto_enabled === true;
  if (ad && S.settings) ad.value = S.settings.bench_auto_days || 7;
  const fbe = $("eb-feedback-enabled");
  if (fbe && S.settings) fbe.checked = S.settings.bench_feedback_enabled !== false;
  try {
    const failed = await api("/api/evalbench/failed-runs");
    S.evalbenchFailures = failed.failures || [];
  } catch (e) { S.evalbenchFailures = []; }
  renderEvalBench();
  if (S.evalbench && S.evalbench.running) EB_TIMER = setInterval(pollEvalBench, 2500);
}

async function saveBenchFeedback() {
  const msg = $("eb-feedback-msg");
  try {
    const r = await api("/api/settings", { method: "POST", body: JSON.stringify({
      bench_feedback_enabled: !$("eb-feedback-enabled") || $("eb-feedback-enabled").checked }) });
    S.settings = r.settings;
    if (msg) { msg.textContent = t("已保存"); }
    pollEvalBench();
  } catch (e) {
    if (msg) { msg.textContent = e.message; }
  }
}

async function saveBenchAuto() {
  const msg = $("eb-auto-msg");
  try {
    const r = await api("/api/settings", { method: "POST", body: JSON.stringify({
      bench_auto_enabled: !$("eb-auto-enabled") || $("eb-auto-enabled").checked,
      bench_auto_days: parseInt($("eb-auto-days").value, 10) || 7 }) });
    S.settings = r.settings;
    if (msg) { msg.textContent = t("已保存"); }
  } catch (e) {
    if (msg) { msg.textContent = e.message; }
  }
}

function pollEvalBench() {
  api("/api/evalbench").then((r) => {
    S.evalbench = r; renderEvalBench();
    if (!r.running && EB_TIMER) { clearInterval(EB_TIMER); EB_TIMER = null; }
  }).catch(() => {});
}

function ebCandidates() {
  const rows = [];
  (S.models && S.models.providers || []).forEach((p) => {
    if (p.enabled === false) return;
    (p.models || []).forEach((m) => {
      if (m.enabled === false || m.hidden) return;
      rows.push({ provider_id: p.id, provider_name: p.name || p.id, model: m.name });
    });
  });
  return rows;
}

function renderEvalBench() {
  const eb = S.evalbench;
  if (!eb) return;
  const samplesBox = $("eb-samples"), candsBox = $("eb-cands"), board = $("eb-board");
  if (!samplesBox) return;                     // 子页不在 DOM（防御并行改版）
  renderEvalBenchFailures();
  if (!samplesBox.dataset.done) {
    samplesBox.innerHTML = eb.samples.map((s) =>
      '<div class="item"><div class="t"><span class="name">' + esc(t(s.name)) + "</span>" +
      (s.verify ? '<span class="tag ok">' + t("带客观验证") + "</span>" : "") +
      (s.redteam ? '<span class="tag" style="color:var(--err,#d33)">' + t("安全测试") + "</span>" : "") +
      (s.builtin ? "" : '<span class="tag">' + t("自定义") + "</span>" +
        '<button class="ghost small" onclick="sampleExport(\'' + jsq(s.id) + '\')">' + t("导出") + "</button>" +
        '<button class="danger small" onclick="sampleDelete(\'' + jsq(s.id) + '\')">' + t("删除") + "</button>") +
      "</div>" +
      '<div class="desc">' + esc(t(s.requirement)) + t("　维度：") +
      esc(s.dims.map((d) => t(d)).join(" / ")) + "</div></div>").join("");
    samplesBox.dataset.done = "1";
  }
  const prev = (eb.leaderboard || []).reduce((acc, r) => {
    acc[r.provider_id + "\n" + r.model] = true; return acc;
  }, {});
  candsBox.innerHTML = ebCandidates().map((c) => {
    const key = c.provider_id + "\n" + c.model;
    return '<label class="toggle" style="display:flex;align-items:center;gap:6px">' +
      '<input type="checkbox" class="eb-cand" data-pid="' + esc(c.provider_id) +
      '" data-model="' + esc(c.model) + '"' + (prev[key] ? " checked" : "") + "> " +
      '<span>' + esc(t(c.provider_name)) + " · " + esc(c.model) + "</span></label>";
  }).join("") || '<div class="hint">' + t("没有可用模型：先在「模型接入」配置启用了密钥的供应商。") + "</div>";
  const j = eb.judge || {};
  const jEl = $("eb-judge");
  if (jEl) jEl.textContent = j.ready
    ? t("裁判：") + (j.model || j.provider_id)
    : t("裁判未就绪：先在「编排设置」配置编排者供应商");
  const pr = eb.progress;
  $("eb-progress").textContent = eb.running && pr
    ? t("评测中 ") + (pr.done || 0) + "/" + (pr.total || 0) + (pr.current ? t("　·　") + pr.current : "") +
      (pr.cancel ? t("　·　停止中…当前样题完成后即停") : "")
    : "";
  board.innerHTML = (eb.leaderboard || []).map((r) => {
    const dims = Object.keys(r.scores || {}).length
      ? t("　") + Object.keys(r.scores).map((d) => t(d) + " " + r.scores[d]).join(t("　")) : "";
    const verify = r.verify_total
      ? t("　客观验证 ") + r.verify_pass + "/" + r.verify_total : "";
    const marks = (r.same_family ? '<span class="tag">' + t("同族评审") + "</span>" : "") +
      (r.failed_n ? '<span class="tag">' + t("失败 ") + r.failed_n + "</span>" : "") +
      (!r.scored_n ? '<span class="tag">' + t("未得分") + "</span>" : "") +
      (r.value_per_yuan != null
        ? '<span class="tag ok" title="' + t("综合分 ÷ 评测花费（¥，按标定单价折算）") + '">' +
          t("性价比 ") + r.value_per_yuan + t(" 分/¥") + "</span>"
        : (r.cost_yuan != null ? '<span class="tag">' + t("花费 ¥") + r.cost_yuan + "</span>" : ""));
    return '<div class="item"><div class="t"><span class="name">#' + r.rank + "　" +
      esc(r.model) + "</span>" +
      (r.overall != null ? '<span class="tag ok">' + t("综合 ") + r.overall + "</span>" : "") + marks +
      '<span class="tag">' + esc(t(r.provider_name)) + "</span></div>" +
      '<div class="desc">' + t("样题 ") + r.samples_n + verify + dims +
      (r.last_ts ? t("　·　") + r.last_ts : "") + "</div></div>";
  }).join("") || '<div class="hint">' + t("还没有评测结果：勾选候选模型后点「开始评测」。") + "</div>";
  renderEvalMatrix(eb);
  // 分数走势 sparkline（近 14 天全体已得分的按日均值；数据≥2 天才画）
  const trendBox = $("eb-trend");
  if (trendBox) {
    const series = (eb.trend || []).map((t) => t.overall);
    trendBox.innerHTML = (series.length > 1)
      ? '<span class="hint">' + t("分数走势（近 ") + series.length + t(" 天）") + "</span>" +
        kpiSparkSvg(series, series[series.length - 1] >= series[0] ? "up" : "down")
      : "";
  }
  const btn = $("eb-run-btn");
  if (btn) btn.disabled = !!eb.running;
  const stopBtn = $("eb-stop-btn");
  if (stopBtn) {
    const stopping = !!(eb.running && eb.progress && eb.progress.cancel);
    stopBtn.textContent = stopping ? t("强制停止") : t("停止");
    stopBtn.disabled = !eb.running;          // 空闲置灰：第二次点击=强制脱离的入口只在停止中开放
  }
  const fbBox = $("eb-feedback-status");
  if (fbBox) {
    const fb = eb.feedback || {};
    if (!fb.enabled) {
      fbBox.textContent = t("反哺已关闭：评测只出榜单，不影响选路。");
    } else {
      const sig = Object.values(fb.signals || {});
      const down = sig.filter((x) => x.below).length;
      const up = sig.length - down;
      fbBox.textContent = sig.length
        ? t("反哺生效：") + up + t(" 个模型加权 · ") + down + t(" 个降权（据 14 天内实测分）")
        : t("反哺生效中：暂无 14 天内实测分，跑一轮评测后开始影响排序。");
    }
  }
}

function renderEvalBenchFailures() {
  const box = $("eb-failed-runs");
  if (!box) return;
  const rows = S.evalbenchFailures || [];
  if (!rows.length) {
    box.innerHTML = '<div class="hint">' + t("暂无可导入的失败步骤") + "</div>";
    return;
  }
  box.innerHTML = rows.slice(0, 30).map((row) =>
    '<div class="item"><div class="t"><span class="name">' +
    esc(row.task_id || row.run_id) + " · #" + esc(row.step_n) + " · " +
    esc(row.role || row.agent || t("失败步骤")) + "</span>" +
    '<button class="ghost small" onclick="evalbenchFailureSample(\'' +
    jsq(row.run_id) + "'," + Number(row.step_n) + ')">' +
    t("整理为回归样题") + "</button></div><div class=\"desc\">" +
    esc(row.failure_excerpt || t("无失败摘要")) + "</div></div>").join("");
}

function evalbenchFailureSample(runId, stepN) {
  const row = (S.evalbenchFailures || []).find((item) =>
    item.run_id === runId && Number(item.step_n) === Number(stepN));
  if (!row) return;
  const body = '<p class="hint">' + t("以下是脱敏预览，不会写入样题。请自行填写可复现输入与期望标准；不要粘贴密钥或个人信息。") +
    '</p><pre class="hint" style="white-space:pre-wrap;max-height:180px;overflow:auto">' +
    esc(row.failure_excerpt || t("无失败摘要")) + '</pre><div class="form">' +
    '<div class="field"><label>' + t("样题名称") + '</label><input id="fb-name" maxlength="20" value="' +
    esc(t("失败回归") + " " + (row.task_id || row.run_id).slice(0, 12)) + '"></div>' +
    '<div class="field"><label>' + t("期望行为 / 验收标准") + '</label><input id="fb-req" maxlength="120"></div>' +
    '<div class="field"><label>' + t("复现输入（手工填写，不会从运行记录复制）") + '</label><textarea id="fb-prompt" rows="5" maxlength="2000"></textarea></div>' +
    '<div class="field"><label>' + t("评审维度（2-6 个，逗号分隔）") + '</label><input id="fb-dims" value="' +
    t("正确性，可复现性") + '"></div>' +
    '<label class="toggle"><input id="fb-confirm" type="checkbox"> <span>' +
    t("我已检查预览并确认只保存手工编写的复现输入和期望标准") + '</span></label></div>';
  openModal(t("从失败运行创建回归样题"), body,
    '<button class="ghost" onclick="closeModal()">' + t("取消") + '</button>' +
    '<button class="primary" onclick="evalbenchFailureSampleDo(\'' + jsq(runId) + "'," + Number(stepN) + ')">' +
    t("确认并保存样题") + '</button>');
}

async function evalbenchFailureSampleDo(runId, stepN) {
  if (!(($("fb-confirm") || {}).checked)) { toast(t("请先确认预览与样题内容"), true); return; }
  const dims = (($("fb-dims") || {}).value || "").split(/[,，、\\n]+/).map((s) => s.trim()).filter(Boolean);
  try {
    await api("/api/evalbench/sample-from-run", { method: "POST", body: JSON.stringify({
      run_id: runId, step_n: stepN, confirmed: true,
      sample: { name: ($("fb-name") || {}).value,
        requirement: ($("fb-req") || {}).value,
        prompt: ($("fb-prompt") || {}).value, dims }
    }) });
    closeModal();
    S.evalbench = await api("/api/evalbench");
    const samples = $("eb-samples");
    if (samples) samples.dataset.done = "";
    renderEvalBench();
    toast(t("回归样题已创建；失败输出未保存"));
  } catch (e) { toast(t("创建失败：") + e.message, true); }
}

/* 逐题对比：行=样题，列=候选模型（按榜单名次），格=最新一次得分 */
function renderEvalMatrix(eb) {
  const box = $("eb-matrix");
  if (!box) return;
  const mx = eb.matrix || { samples: [], cells: {} };
  const cols = (eb.leaderboard || [])
    .map((r) => r.provider_id + "|" + r.model);
  const sname = {};
  (eb.samples || []).forEach((s) => { sname[s.id] = s.name; });
  if (!mx.samples.length || !cols.length) { box.innerHTML = ""; return; }
  const cellHtml = (sid, mk) => {
    const c = (mx.cells[sid] || {})[mk];
    if (!c) return '<td style="color:var(--dim,#999);text-align:center">·</td>';
    if (!c.ok) return '<td style="text-align:center;color:var(--err,#d33)">✗</td>';
    if (!c.scored || c.overall == null)
      return '<td style="text-align:center;color:var(--dim,#999)">−</td>';
    const mark = c.verify_ok === false ? "⚠" : "";
    return '<td style="text-align:center">' + c.overall.toFixed(1) + mark + "</td>";
  };
  box.innerHTML = '<div style="overflow-x:auto"><table class="eb-mx" style="border-collapse:collapse;width:100%;font-size:12.5px">' +
    "<tr><th style=\"text-align:left;padding:4px 8px;color:var(--dim,#999)\">" + t("样题 \\ 模型") + "</th>" +
    cols.map((mk) => '<th style="padding:4px 8px;white-space:nowrap">' + esc(mk.split("|")[1]) + "</th>").join("") + "</tr>" +
    mx.samples.map((sid) =>
      "<tr><td style=\"padding:4px 8px;white-space:nowrap\">" + esc(t(sname[sid] || sid)) + "</td>" +
      cols.map((mk) => cellHtml(sid, mk)).join("") + "</tr>").join("") +
    "</table></div>" +
    '<p class="hint">' + t("⚠ = 该题客观验证未通过；✗ = 生成失败；− = 生成成功但未得分。") + "</p>";
}

async function evalbenchRun() {
  const picks = Array.from(document.querySelectorAll(".eb-cand:checked")).map((el) => ({
    provider_id: el.dataset.pid, model: el.dataset.model }));
  const msg = $("eb-msg");
  if (!picks.length) { if (msg) { msg.className = "msg err"; msg.textContent = t("请先勾选至少一个候选模型"); } return; }
  try {
    await api("/api/evalbench/run", { method: "POST", body: JSON.stringify({ candidates: picks }) });
    if (msg) { msg.className = "msg ok"; msg.textContent = ""; }
    if (!EB_TIMER) EB_TIMER = setInterval(pollEvalBench, 2500);
    pollEvalBench();
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
}

async function evalbenchCancel() {
  // 两段式：第一击优雅停（等当前样题做完——生成调用最坏要等几分钟）；
  // 服务端已打停止标记后再点=强制脱离（立即回到空闲，后台线程自行收尾）。
  const msg = $("eb-msg");
  const already = !!(S.evalbench && S.evalbench.progress && S.evalbench.progress.cancel);
  try {
    const r = await api("/api/evalbench/cancel",
                        { method: "POST", body: JSON.stringify({ force: already }) });
    if (r && r.ok && r.force) {
      if (msg) { msg.className = "msg ok"; msg.textContent = t("已强制脱离：界面回到空闲，后台当前调用跑完即自行退出"); }
    } else if (r && r.ok) {
      if (msg) { msg.className = "msg"; msg.textContent = t("已请求停止：当前样题完成后即停（生成调用最长可能等几分钟）；等不及再点一次「强制停止」"); }
    }
  } catch (e) {
    if (msg) { msg.className = "msg err"; msg.textContent = e.message; }
  }
  pollEvalBench();
}

